-- Maternal Health question bank: exactly 1150 hand-written NCLEX-style
-- single-best-answer questions, 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/Maternal Health/Infant-Bonding.html
--   Notes/Maternal Health/APGAR-Score.html
--   Notes/Maternal Health/Leopold-Maneuvers.html
--   Notes/Maternal Health/Medications-in-Pregnancy.html
--   Notes/Maternal Health/TORCH-Infections.html
--   Notes/Maternal Health/Hormonal-and-Menstrual-Disorders.html
--   Notes/Maternal Health/Menstrual-Cycle-Made-Easy.html
--   Notes/Maternal Health/Female-Reproductive-Cycle.html
--   Notes/Maternal Health/Womens-Health-NCLEX-Priorities.html
--   Notes/Maternal Health/Fertilization-and-Implantation.html
--   Notes/Maternal Health/Organ-Disorders.html
--   Notes/Maternal Health/Naegeles-Rule-Antepartum-Complications.html
--   Notes/Maternal Health/Ectopic-Pregnancy.html
--   Notes/Maternal Health/Pregnancy-Assessment-Signs.html
--   Notes/Maternal Health/Hyperemesis-Gravidarum.html
--   Notes/Maternal Health/Antepartum-Care.html
--   Notes/Maternal Health/GDM.html
--   Notes/Maternal Health/Gestational-Hypertension-Preeclampsia-Eclampsia.html
--   Notes/Maternal Health/Intrapartum-Care.html
--   Notes/Maternal Health/Placenta-Previa.html
--   Notes/Maternal Health/VEAL-CHOP-FHR-Patterns.html
--   Notes/Maternal Health/Placental-Abruption.html
--   Notes/Maternal Health/Postpartum.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (1150) exist after insert.
BEGIN;

CREATE TEMP TABLE _mat_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _mat_sources (source_key, source_path, category) VALUES
  ('bonding', 'Notes/Maternal Health/Infant-Bonding.html', 'Maternal Health NCLEX seed v1 - infant bonding'),
  ('apgar', 'Notes/Maternal Health/APGAR-Score.html', 'Maternal Health NCLEX seed v1 - apgar score'),
  ('leopold', 'Notes/Maternal Health/Leopold-Maneuvers.html', 'Maternal Health NCLEX seed v1 - leopold maneuvers'),
  ('meds', 'Notes/Maternal Health/Medications-in-Pregnancy.html', 'Maternal Health NCLEX seed v1 - medications in pregnancy'),
  ('torch', 'Notes/Maternal Health/TORCH-Infections.html', 'Maternal Health NCLEX seed v1 - torch infections'),
  ('hormonal', 'Notes/Maternal Health/Hormonal-and-Menstrual-Disorders.html', 'Maternal Health NCLEX seed v1 - hormonal and menstrual disorders'),
  ('menstrual', 'Notes/Maternal Health/Menstrual-Cycle-Made-Easy.html', 'Maternal Health NCLEX seed v1 - menstrual cycle made easy'),
  ('repro_cycle', 'Notes/Maternal Health/Female-Reproductive-Cycle.html', 'Maternal Health NCLEX seed v1 - female reproductive cycle'),
  ('priorities', 'Notes/Maternal Health/Womens-Health-NCLEX-Priorities.html', 'Maternal Health NCLEX seed v1 - womens health nclex priorities'),
  ('fertilization', 'Notes/Maternal Health/Fertilization-and-Implantation.html', 'Maternal Health NCLEX seed v1 - fertilization and implantation'),
  ('organ', 'Notes/Maternal Health/Organ-Disorders.html', 'Maternal Health NCLEX seed v1 - organ disorders'),
  ('naegele', 'Notes/Maternal Health/Naegeles-Rule-Antepartum-Complications.html', 'Maternal Health NCLEX seed v1 - naegeles rule antepartum complications'),
  ('ectopic', 'Notes/Maternal Health/Ectopic-Pregnancy.html', 'Maternal Health NCLEX seed v1 - ectopic pregnancy'),
  ('signs', 'Notes/Maternal Health/Pregnancy-Assessment-Signs.html', 'Maternal Health NCLEX seed v1 - pregnancy assessment signs'),
  ('hyperemesis', 'Notes/Maternal Health/Hyperemesis-Gravidarum.html', 'Maternal Health NCLEX seed v1 - hyperemesis gravidarum'),
  ('antepartum', 'Notes/Maternal Health/Antepartum-Care.html', 'Maternal Health NCLEX seed v1 - antepartum care'),
  ('gdm', 'Notes/Maternal Health/GDM.html', 'Maternal Health NCLEX seed v1 - gdm'),
  ('htn', 'Notes/Maternal Health/Gestational-Hypertension-Preeclampsia-Eclampsia.html', 'Maternal Health NCLEX seed v1 - gestational hypertension preeclampsia eclampsia'),
  ('intrapartum', 'Notes/Maternal Health/Intrapartum-Care.html', 'Maternal Health NCLEX seed v1 - intrapartum care'),
  ('previa', 'Notes/Maternal Health/Placenta-Previa.html', 'Maternal Health NCLEX seed v1 - placenta previa'),
  ('vealchop', 'Notes/Maternal Health/VEAL-CHOP-FHR-Patterns.html', 'Maternal Health NCLEX seed v1 - veal chop fhr patterns'),
  ('abruption', 'Notes/Maternal Health/Placental-Abruption.html', 'Maternal Health NCLEX seed v1 - placental abruption'),
  ('postpartum', 'Notes/Maternal Health/Postpartum.html', 'Maternal Health NCLEX seed v1 - postpartum');

CREATE TEMP TABLE _mat_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _mat_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'maternal health'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Maternal Health"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'maternal health'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _mat_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Maternal Health subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Maternal Health points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _mat_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Maternal seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _mat_seed_map) <> 23 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 23 note mappings, found %.',
      (SELECT count(*) FROM _mat_seed_map);
  END IF;

  INSERT INTO _mat_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _mat_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, false, v.display_order, 1, true
  FROM (VALUES
  ('bonding', 1, 'Ten minutes after birth, a mother holding her newborn skin-to-skin gently strokes the baby''s fingers and toes with her fingertips but has not yet cradled the baby. Her partner asks the nurse whether something is wrong. Which response by the nurse is best?', '[{"id": "a", "text": "She is avoiding touching the baby, so I will assess her further"}, {"id": "b", "text": "This hesitation can signal depression, so I will screen her today"}, {"id": "c", "text": "This is the usual first way mothers explore their new baby"}, {"id": "d", "text": "This pattern suggests an avoidant attachment is starting"}]'::jsonb, '["c"]', 'Fingertip exploration starting at the extremities is the normal first phase of maternal touch, progressing to palm touching and then enfolding. Avoiding touch altogether would be concerning, but fingertip touching is contact.'),
  ('bonding', 2, 'A nurse is observing a mother during the first hour after an uncomplicated birth. Which sequence of maternal touch behaviors should the nurse expect?', '[{"id": "a", "text": "Full embrace of the baby → palm on the trunk → fingertips on the hands"}, {"id": "b", "text": "Fingertips on the extremities → palm on the trunk → full embrace"}, {"id": "c", "text": "Palm on the trunk → fingertips on the extremities → full embrace"}, {"id": "d", "text": "Fingertips on the trunk → full embrace → palm on the extremities"}]'::jsonb, '["b"]', 'The normal progression is fingertip touching starting at the extremities, then full palm on the trunk and back within minutes, then enfolding within the first hour. The other sequences reverse or scramble these phases.'),
  ('bonding', 3, 'On postpartum day 1, a mother holds her newborn so that their faces are on the same horizontal plane and gazes into the baby''s eyes for long periods while talking softly. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Suggest holding the baby facing outward to limit stimulation"}, {"id": "b", "text": "Assess the mother further for signs of postpartum depression"}, {"id": "c", "text": "Report the behavior as a possible sign of anxious attachment"}, {"id": "d", "text": "Document this as a positive, normal attachment behavior"}]'::jsonb, '["d"]', 'The en face position, with eye contact on the same plane, is a normal and healthy attachment behavior. Holding the baby away from the face is actually one of the concerning behaviors.'),
  ('bonding', 4, 'On postpartum day 1, a mother holds her newborn away from her face, refers to the baby as ''it,'' and rarely looks at the baby during feedings. What is the nurse''s first action?', '[{"id": "a", "text": "Explore her feelings and assess the situation further"}, {"id": "b", "text": "Notify social services that the newborn is being neglected"}, {"id": "c", "text": "Move the newborn to the nursery for the remainder of the stay"}, {"id": "d", "text": "Document normal adjustment and recheck at the next shift"}]'::jsonb, '["a"]', 'Referring to the baby as ''it,'' positioning the baby away from the face, and avoiding looking are concerning behaviors that call for further assessment first, before intervening and without assuming neglect. Documenting them as normal would miss warning signs.'),
  ('bonding', 5, 'Several hours after birth, a mother tearfully tells the nurse she does not feel the instant rush of love she expected and asks whether she is a bad mother. She is holding, feeding, and talking to her baby. Which response by the nurse is best?', '[{"id": "a", "text": "That feeling suggests postpartum depression, so let''s screen now"}, {"id": "b", "text": "Love often grows over time as you keep caring for your baby"}, {"id": "c", "text": "The bonding window has passed, but we can still try skin-to-skin"}, {"id": "d", "text": "That is a concerning sign that I will need to report to the provider"}]'::jsonb, '["b"]', 'A mother who does not feel immediate bonding is not failing; attachment develops over time through consistent interaction, which this mother is providing. Her caregiving behaviors are positive, not a reportable concern.'),
  ('bonding', 6, 'Fifteen minutes after a vaginal birth, a stable, vigorous newborn is skin-to-skin with the mother and beginning to root. A nursery nurse arrives to weigh the baby and apply eye ointment. Which action by the nurse is best?', '[{"id": "a", "text": "Weigh the baby quickly and return the baby to the mother"}, {"id": "b", "text": "Apply eye ointment now but postpone the weight until later"}, {"id": "c", "text": "Delay weighing and eye ointment until after the first hour"}, {"id": "d", "text": "Bathe the baby first, then return the baby for skin-to-skin"}]'::jsonb, '["c"]', 'The first 60 minutes of uninterrupted skin-to-skin are the most critical bonding period, so non-urgent procedures such as weighing, bathing, and eye ointment are delayed when possible. Any of the other options interrupts the golden hour.'),
  ('bonding', 7, 'A mother holding her stable term newborn skin-to-skin immediately after birth asks why her baby is not being placed in a warmer to stay warm. Which response by the nurse best answers her concern?', '[{"id": "a", "text": "Skin contact releases oxytocin that helps your uterus contract"}, {"id": "b", "text": "Skin contact lowers the stress hormone levels in your baby"}, {"id": "c", "text": "Skin contact strengthens your baby''s immune system over time"}, {"id": "d", "text": "Your bare chest works like a natural incubator for your baby"}]'::jsonb, '["d"]', 'Thermoregulation is a skin-to-skin benefit because the parent''s chest acts as a natural incubator. The other options are true benefits of skin-to-skin but do not answer her question about warmth.'),
  ('bonding', 8, 'A mother who is worried about bleeding after birth asks how keeping her baby skin-to-skin could help her own recovery. Which response by the nurse is most accurate?', '[{"id": "a", "text": "It releases oxytocin, which helps your uterus contract"}, {"id": "b", "text": "It lowers your cortisol so that your heart rate stabilizes"}, {"id": "c", "text": "It reduces crying, so you will have more time to rest"}, {"id": "d", "text": "It builds your immunity through your baby''s microbiome"}]'::jsonb, '["a"]', 'For the mother, skin-to-skin stimulates oxytocin release, which promotes uterine contraction and milk let-down. Lowered cortisol, stabilized heart rate, and reduced crying are newborn benefits.'),
  ('bonding', 9, 'The mother of an infant born at 32 weeks who is in the NICU visits rarely, says she feels guilty and grieves the birth she expected, and is afraid to touch her fragile baby. Which intervention is most appropriate?', '[{"id": "a", "text": "Encourage visits, kangaroo care, and involvement in care"}, {"id": "b", "text": "Suggest she wait to hold the baby until discharge is near"}, {"id": "c", "text": "Refer to social services for possible infant neglect"}, {"id": "d", "text": "Limit her visits until the infant is medically stable"}]'::jsonb, '["a"]', 'For a preterm/NICU infant, the response to separation, fear, guilt, and grief is to encourage early visits, skin-to-skin/kangaroo care, and involvement in care. Delaying or limiting contact deepens the barrier, and her behavior reflects fear rather than neglect.'),
  ('bonding', 10, 'After a cesarean birth under regional anesthesia, a mother is drowsy and in pain, and her term newborn is stable. Her partner is at the bedside. Which plan best promotes bonding?', '[{"id": "a", "text": "Keep the baby in the nursery until the mother has recovered"}, {"id": "b", "text": "Delay all contact until the anesthesia has fully worn off"}, {"id": "c", "text": "Start skin-to-skin once safe and involve the partner"}, {"id": "d", "text": "Have nursery staff give all feedings so the mother can rest"}]'::jsonb, '["c"]', 'After a cesarean, recovery pain and anesthesia limit early contact, so the nurse facilitates skin-to-skin as soon as medically safe and involves the partner. Keeping the baby away delays bonding.'),
  ('bonding', 11, 'A 16-year-old first-time mother on postpartum day 1 asks the nurse to change her baby''s diaper because she is unsure how to do it, and she holds the baby stiffly. Which action by the nurse is best?', '[{"id": "a", "text": "Refer her to social services because she cannot parent safely"}, {"id": "b", "text": "Provide all newborn care for her until the day of discharge"}, {"id": "c", "text": "Report her lack of interest as a concerning bonding behavior"}, {"id": "d", "text": "Demonstrate diapering, assess needs, and have her practice"}]'::jsonb, '["d"]', 'Adolescent mothers need extra education and modeling of parenting behaviors, and the nurse should assess needs rather than assume incompetence. Her request reflects inexperience, not disinterest.'),
  ('bonding', 12, 'A postpartum client becomes quiet and flinches whenever her partner enters the room. The nurse notices bruises on her upper arms, and the partner answers all questions for her. Which action is the nurse''s priority?', '[{"id": "a", "text": "Involve the partner more in newborn care to promote bonding"}, {"id": "b", "text": "Screen the client privately while the partner is away"}, {"id": "c", "text": "Ask the couple together whether there is violence in the home"}, {"id": "d", "text": "Give the couple a handout listing community parenting resources"}]'::jsonb, '["b"]', 'Possible domestic violence calls for private screening, safety planning, and mandatory reporting as required. Involving partners is a bonding intervention, but asking in front of the partner or increasing his role could endanger her.'),
  ('bonding', 13, 'A mother with an opioid use disorder is caring for her newborn, who is showing signs of neonatal abstinence syndrome. She seems anxious and avoids eye contact with staff. Which nursing approach is most appropriate?', '[{"id": "a", "text": "Restrict her contact with the newborn until treatment begins"}, {"id": "b", "text": "Provide non-judgmental care and refer to recovery services"}, {"id": "c", "text": "Explain firmly how her drug use has harmed the newborn"}, {"id": "d", "text": "Postpone any referrals until the newborn is discharged"}]'::jsonb, '["b"]', 'For substance use disorder, the nursing response is non-judgmental care with referral to social services and recovery programs. Confrontation or restricting contact adds barriers rather than addressing them.'),
  ('bonding', 14, 'A mother whose newborn was born with a visible facial anomaly is crying, says she is in shock, and has not yet held her baby. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Reassure her that the baby will look normal after surgery"}, {"id": "b", "text": "Encourage her to focus on the positives and to stop crying"}, {"id": "c", "text": "Keep the baby in the nursery until she feels ready to bond"}, {"id": "d", "text": "Allow her to grieve and give honest information"}]'::jsonb, '["d"]', 'With infant illness or anomalies, parents experience shock and grief, so the nurse allows grieving, provides honest information, and connects them with support groups. False reassurance and discouraging grief are not supportive.'),
  ('bonding', 15, 'A single mother who recently moved away from her family tells the nurse she has no one to help her at home and feels isolated. She is caring well for her newborn and denies sadness. Which nursing action best addresses this barrier?', '[{"id": "a", "text": "Arrange a referral for antidepressant medication"}, {"id": "b", "text": "Notify social services about possible neglect"}, {"id": "c", "text": "Connect her with home visiting and peer support"}, {"id": "d", "text": "Make a mandatory report to the local authorities"}]'::jsonb, '["c"]', 'Lack of social support increases stress and PPD risk and is addressed with community resources, home visiting programs, and peer support. She shows no depressive symptoms or neglect, and mandatory reporting applies to abuse.'),
  ('bonding', 16, 'On postpartum day 3, a mother is tearful and says she feels a little sad, but she is eating, caring for her baby, and denies thoughts of harming herself or the baby. Which nursing action is most appropriate?', '[{"id": "a", "text": "Offer support, encourage rest, and reassure her"}, {"id": "b", "text": "Refer her for therapy and antidepressant medication"}, {"id": "c", "text": "Arrange immediate psychiatric hospitalization"}, {"id": "d", "text": "Report her to the provider for a depression workup"}]'::jsonb, '["a"]', 'Onset at 2–4 days with mild, functional symptoms and no thoughts of harm fits baby blues, treated with support, rest, and reassurance. Therapy and antidepressants are for PPD, and hospitalization is for psychosis.'),
  ('bonding', 17, 'At a 3-week postpartum visit, a mother says she has felt deeply sad every day since her baby was born and can no longer manage feedings or diaper changes. She denies hallucinations. Which action is the priority?', '[{"id": "a", "text": "Reassure her that these feelings usually resolve on their own"}, {"id": "b", "text": "Arrange immediate admission to a psychiatric hospital"}, {"id": "c", "text": "Refer her for therapy and possible antidepressants"}, {"id": "d", "text": "Encourage more rest and reassess her in 2 weeks"}]'::jsonb, '["c"]', 'Sadness lasting longer than 2 weeks that impairs functioning indicates postpartum depression, which requires referral for therapy and antidepressants. Baby blues resolve within 14 days, and hospitalization is reserved for psychosis.'),
  ('bonding', 18, 'On postpartum day 6, a mother tells the nurse that a voice has been telling her to hurt her baby. She appears confused. Which action is the nurse''s priority?', '[{"id": "a", "text": "Refer her to an outpatient therapist this week"}, {"id": "b", "text": "Arrange immediate psychiatric hospitalization"}, {"id": "c", "text": "Screen her with the Edinburgh Postnatal Depression Scale"}, {"id": "d", "text": "Provide support, rest, and reassurance"}]'::jsonb, '["b"]', 'Command auditory hallucinations to harm the baby signal postpartum psychosis, a rare emergency requiring immediate psychiatric hospitalization. Screening or outpatient referral delays needed emergency care.'),
  ('bonding', 19, 'The nurse is caring for four postpartum mothers. Which mother should the nurse assess first?', '[{"id": "a", "text": "Day 2: tearful at times but caring for her baby"}, {"id": "b", "text": "Day 1: calls the baby by name and notes family resemblance"}, {"id": "c", "text": "Day 1: touches the baby only with her fingertips at first"}, {"id": "d", "text": "Day 5: hears a voice telling her to harm the baby"}]'::jsonb, '["d"]', 'Command hallucinations to harm the baby indicate postpartum psychosis, an emergency. Mild tearfulness while functioning fits baby blues, and naming the baby and fingertip touching are normal bonding behaviors.'),
  ('bonding', 20, 'A mother who began having crying spells on postpartum day 3 is seen on day 18. She still cries daily and says she is finding it harder to care for her baby. Which action by the nurse is best?', '[{"id": "a", "text": "Screen her with the EPDS and refer for treatment"}, {"id": "b", "text": "Reassure her that baby blues often last about a month"}, {"id": "c", "text": "Arrange immediate psychiatric hospitalization"}, {"id": "d", "text": "Suggest rooming-in to strengthen the bond with her baby"}]'::jsonb, '["a"]', 'Baby blues resolve within 14 days; symptoms persisting beyond 2 weeks with declining function suggest PPD, which calls for screening and referral. Without hallucinations or delusions, emergency hospitalization is not indicated.'),
  ('bonding', 21, 'A mother with uncomplicated vaginal birth, a healthy newborn, and no mood symptoms is being prepared for discharge on postpartum day 2. Which action is most important for the early identification of postpartum depression?', '[{"id": "a", "text": "Ask her partner to call if she starts to seem sad"}, {"id": "b", "text": "Screen her with the EPDS before she is discharged"}, {"id": "c", "text": "Wait to screen her at the 6-week postpartum visit"}, {"id": "d", "text": "Observe how she holds the baby during one feeding"}]'::jsonb, '["b"]', 'Screening with the EPDS before discharge allows early identification, early treatment, and better outcomes. Waiting until 6 weeks or relying on informal observation delays identification.'),
  ('bonding', 22, 'On postpartum night 1, a rested, well mother who is breastfeeding a healthy newborn asks to send the baby to the nursery overnight so she can sleep. Which response by the nurse is best?', '[{"id": "a", "text": "Agree, because nursery care is preferred for bonding"}, {"id": "b", "text": "Report the request as a concerning bonding behavior"}, {"id": "c", "text": "Explain how rooming-in helps her learn the baby''s cues"}, {"id": "d", "text": "Refuse the request because overnight nursery care is not allowed"}]'::jsonb, '["c"]', 'Rooming-in is preferred over nursery care because it promotes learning the baby''s cues, interaction, and breastfeeding. A single request is not the constant, unexplained pattern that would be concerning.'),
  ('bonding', 23, 'The nurse is observing four mothers with their newborns on postpartum day 1. Which observation requires further assessment?', '[{"id": "a", "text": "A mother who points out that the baby has her partner''s chin"}, {"id": "b", "text": "A mother who sings softly to her baby during each feeding"}, {"id": "c", "text": "A mother who calls her baby by name while changing a diaper"}, {"id": "d", "text": "A rested mother who asks staff to take her baby at every cry"}]'::jsonb, '["d"]', 'Constantly requesting nurse care for the baby without a physiologic reason is a concerning behavior that calls for further assessment. Looking for family resemblance, singing, and using the baby''s name are positive behaviors.'),
  ('bonding', 24, 'On postpartum day 1, which statement by a mother indicates positive attachment to her newborn?', '[{"id": "a", "text": "She''s rooting and sucking her fist, so she must be hungry"}, {"id": "b", "text": "She''s beautiful, but I was really hoping for a boy this time"}, {"id": "c", "text": "She''s going to be a selfish baby, I can already tell"}, {"id": "d", "text": "Please hold it for a while; I''ll take it back later"}]'::jsonb, '["a"]', 'Appropriately interpreting the baby''s cues is a positive bonding behavior. Disappointment in the baby''s sex, assigning negative traits, and calling the baby ''it'' are concerning behaviors.'),
  ('bonding', 25, 'At a well-baby visit, a 12-month-old explores the room confidently, checks back with the mother, and is easily comforted by her after a minor fall. Which caregiver pattern does this behavior most likely reflect?', '[{"id": "a", "text": "Care that is responsive at some times and absent at other times"}, {"id": "b", "text": "Care that is consistently unresponsive or rejecting"}, {"id": "c", "text": "Care that is frightening or abusive to the infant"}, {"id": "d", "text": "Care that is consistently responsive, warm, and predictable"}]'::jsonb, '["d"]', 'An infant who explores confidently and is easily comforted shows secure attachment, which results from consistently responsive, warm, predictable care. Inconsistent care produces an anxious-ambivalent, hard-to-comfort infant.'),
  ('bonding', 26, 'A home-visit nurse notes that a mother sometimes responds warmly to her 10-month-old''s cries and at other times ignores them for long periods. The infant is clingy, anxious, and hard to soothe. Which attachment pattern do these findings suggest?', '[{"id": "a", "text": "Secure attachment"}, {"id": "b", "text": "Avoidant attachment"}, {"id": "c", "text": "Anxious-ambivalent attachment"}, {"id": "d", "text": "Disorganized attachment"}]'::jsonb, '["c"]', 'Inconsistently responsive care produces an anxious-ambivalent infant who is clingy, anxious, and difficult to comfort. Avoidant attachment results from consistently unresponsive or rejecting care.'),
  ('bonding', 27, 'A toddler whose mother consistently rejects the child''s bids for comfort appears independent, does not seek the mother when upset, and seems emotionally detached. Which attachment pattern is the nurse most likely observing?', '[{"id": "a", "text": "Anxious-ambivalent attachment"}, {"id": "b", "text": "Avoidant attachment"}, {"id": "c", "text": "Secure attachment"}, {"id": "d", "text": "Disorganized attachment"}]'::jsonb, '["b"]', 'Consistently unresponsive or rejecting care leads to avoidant attachment, in which the child avoids the caregiver and appears independent but emotionally detached. Anxious-ambivalent children are clingy rather than detached.'),
  ('bonding', 28, 'The nurse reviews family assessments for four infants. Which infant is at the highest risk for developmental problems?', '[{"id": "a", "text": "An infant with no coherent strategy whose caregiver is frightening"}, {"id": "b", "text": "A clingy infant whose caregiver responds only inconsistently"}, {"id": "c", "text": "A detached infant whose caregiver is consistently rejecting"}, {"id": "d", "text": "A confident infant whose caregiver is warm and predictable"}]'::jsonb, '["a"]', 'Frightening or abusive care produces disorganized attachment, with no coherent strategy and the highest risk for developmental problems. Anxious-ambivalent and avoidant patterns are concerning but not the highest risk.'),
  ('bonding', 29, 'After a vaginal birth, the mother is being sutured, and the father asks whether he can hold the stable newborn skin-to-skin or whether that only helps mothers. Which response by the nurse is best?', '[{"id": "a", "text": "Skin-to-skin benefits come only from the birthing parent"}, {"id": "b", "text": "Fathers usually bond later, once the baby is a few months old"}, {"id": "c", "text": "Yes; your bond with the baby matters just as much as hers"}, {"id": "d", "text": "Wait until she is finished so the baby can bond with her first"}]'::jsonb, '["c"]', 'Attachment is not only maternal; paternal bonding is equally important, so partners and fathers are included. Telling him to wait or that fathers bond later excludes him unnecessarily.'),
  ('bonding', 30, 'On postpartum day 2, a mother says her baby cries all the time for no reason and that she never knows what the baby wants. She has been feeding on a strict 4-hour schedule. Which intervention is most appropriate?', '[{"id": "a", "text": "Move the baby to the nursery so the mother can rest"}, {"id": "b", "text": "Teach her to recognize the baby''s hunger and fatigue cues"}, {"id": "c", "text": "Advise letting the baby cry so the baby is not spoiled"}, {"id": "d", "text": "Report her frustration as a concerning bonding behavior"}]'::jsonb, '["b"]', 'Parents who understand hunger and fatigue cues respond appropriately, which builds attachment. Her frustration reflects not knowing the cues; nursery care would reduce opportunities to learn them.'),
  ('bonding', 31, 'A first-time mother nervously completes her baby''s first diaper change correctly while the nurse watches, then asks whether she did it right. Which response by the nurse best supports bonding?', '[{"id": "a", "text": "Offer to do the next change so she does not feel stressed"}, {"id": "b", "text": "Point out the small steps she could do a bit more quickly"}, {"id": "c", "text": "Suggest that nursery staff handle diapering during her stay"}, {"id": "d", "text": "Tell her she is doing a great job caring for her baby"}]'::jsonb, '["d"]', 'Non-judgmental presence and praise reinforce caregiving behavior and build confidence. Taking over or focusing on speed undermines her competence.'),
  ('bonding', 32, 'On postpartum day 1, a mother is skin-to-skin and breastfeeding, but visitors and staff keep entering the room, and the baby repeatedly detaches from the breast. Which nursing action is best?', '[{"id": "a", "text": "Limit interruptions to protect the feeding and contact time"}, {"id": "b", "text": "Move the baby to the nursery for quieter feedings"}, {"id": "c", "text": "Shorten each feeding so the visits can continue"}, {"id": "d", "text": "Delay the next feeding until all the visitors leave"}]'::jsonb, '["a"]', 'Minimizing interruptions during feeding and skin-to-skin protects bonding time. Moving the baby away or shortening feedings reduces closeness.'),
  ('bonding', 33, 'A mother who had a long labor worries that she will not bond with her stable term newborn. Right after birth, which single intervention is most effective for promoting bonding?', '[{"id": "a", "text": "Rooming-in for the rest of the hospital stay"}, {"id": "b", "text": "Immediate skin-to-skin contact"}, {"id": "c", "text": "EPDS screening before discharge"}, {"id": "d", "text": "Demonstrating the baby''s first bath"}]'::jsonb, '["b"]', 'Skin-to-skin is the single most evidence-based intervention to promote bonding. Rooming-in, EPDS screening, and modeling care are helpful but not the most effective first measure.'),
  ('bonding', 34, 'The parents of an infant born at 30 weeks of gestation ask the NICU nurse how kangaroo care will help their baby. Which response by the nurse is most accurate?', '[{"id": "a", "text": "It mainly benefits the two of you rather than your baby"}, {"id": "b", "text": "It raises your baby''s cortisol to build a stress response"}, {"id": "c", "text": "It speeds up your baby''s heart rate to improve circulation"}, {"id": "d", "text": "It supports your baby''s weight gain and brain development"}]'::jsonb, '["d"]', 'Skin-to-skin improves weight gain and neurodevelopmental outcomes in preterm infants. It reduces cortisol and stabilizes heart rate, rather than raising them.'),
  ('bonding', 35, 'A stable 1-day-old newborn needs a routine heel stick. The mother, who is breastfeeding, asks whether she can do anything to keep her baby comfortable. Which response by the nurse is best?', '[{"id": "a", "text": "You can wait outside while we do it in the nursery"}, {"id": "b", "text": "We will place your baby in a warmer away from you"}, {"id": "c", "text": "You can hold your baby skin-to-skin during the test"}, {"id": "d", "text": "It is best if you look away and leave comfort to us"}]'::jsonb, '["c"]', 'Skin-to-skin contact reduces infant crying and pain perception. Separating the baby from the mother removes that comfort.'),
  ('bonding', 36, 'A nurse is caring for a stable mother and newborn during the first hour after an uncomplicated birth. Which action by the nurse requires correction?', '[{"id": "a", "text": "Removing the baby at 20 minutes to give the first bath"}, {"id": "b", "text": "Placing the diapered newborn on the mother''s bare chest"}, {"id": "c", "text": "Letting the newborn crawl toward and self-attach to the breast"}, {"id": "d", "text": "Deferring the newborn''s weight until after the first hour"}]'::jsonb, '["a"]', 'Non-urgent procedures such as bathing are delayed until after the first 60 minutes of uninterrupted skin-to-skin. Placing the diapered baby chest-to-chest, allowing self-attachment, and deferring the weight are all correct.'),
  ('bonding', 37, 'Thirty minutes after birth, a stable newborn who is skin-to-skin with the mother begins rooting and inching toward her breast. Which nursing action is best?', '[{"id": "a", "text": "Move the baby to the crib and feed after the assessments"}, {"id": "b", "text": "Allow the baby to self-attach without interrupting"}, {"id": "c", "text": "Weigh the baby first to get a baseline before feeding"}, {"id": "d", "text": "Bathe the baby so the skin is clean before feeding"}]'::jsonb, '["b"]', 'During the golden hour, the baby can self-attach to the breast, which promotes breastfeeding. Weighing and bathing are non-urgent procedures to delay.'),
  ('bonding', 38, 'Shortly after birth, a mother studies her baby''s face and says that the baby has her husband''s chin and her own mother''s eyes. How should the nurse interpret this behavior?', '[{"id": "a", "text": "As a positive bonding behavior"}, {"id": "b", "text": "As a sign of hidden disappointment"}, {"id": "c", "text": "As a concerning behavior to assess"}, {"id": "d", "text": "As an early sign of depression"}]'::jsonb, '["a"]', 'Pointing out the baby''s features and looking for family resemblance is a positive bonding behavior. Disappointment in the baby''s sex or appearance would be concerning, but this mother expresses none.'),
  ('bonding', 39, 'A mother who wanted a son learns her baby is a girl. Over the next several hours, she says she is disappointed, holds the baby only briefly, and interacts with the baby very little. What is the nurse''s first action?', '[{"id": "a", "text": "Notify social services about the risk of neglect"}, {"id": "b", "text": "Reassure her that this is normal and needs no follow-up"}, {"id": "c", "text": "Transfer the baby to the nursery to give her more time"}, {"id": "d", "text": "Explore her feelings and assess the interaction further"}]'::jsonb, '["d"]', 'Disappointment in the baby''s sex and minimal interaction are concerning behaviors that call for further assessment first, before intervening and without assuming neglect. Dismissing them as normal would miss a warning sign.'),
  ('bonding', 40, 'On postpartum day 4, a tearful mother whose symptoms started 2 days ago tells the nurse that she sometimes thinks about hurting herself. She denies hallucinations. Which action is the nurse''s priority?', '[{"id": "a", "text": "Reassure her that this fits the usual timing of baby blues"}, {"id": "b", "text": "Encourage rest and recheck her mood in about 14 days"}, {"id": "c", "text": "Refer her for treatment, since this goes beyond baby blues"}, {"id": "d", "text": "Document this as part of normal postpartum adjustment"}]'::jsonb, '["c"]', 'Although onset at 2–4 days resembles baby blues, baby blues involve no thoughts of harm; thoughts of harming self point to PPD, which requires referral. Reassurance based on timing alone misses the warning sign.'),
  ('bonding', 41, 'Five months after birth, a mother reports months of persistent sadness that interferes with caring for her baby. She says it cannot be postpartum depression because so much time has passed. Which response by the nurse is most accurate?', '[{"id": "a", "text": "You''re right; postpartum depression starts only in the first month"}, {"id": "b", "text": "Postpartum depression can begin up to a year after birth"}, {"id": "c", "text": "This is most likely the baby blues returning after a delay"}, {"id": "d", "text": "These symptoms point to postpartum psychosis rather than PPD"}]'::jsonb, '["b"]', 'PPD typically begins within 4 weeks but can occur up to 1 year after birth, and persistent impairing sadness warrants screening and referral. Baby blues resolve within 14 days, and psychosis involves hallucinations or delusions.'),
  ('bonding', 42, 'The nurse reviews the mood assessments of four postpartum mothers. Which mother should the nurse refer for further evaluation?', '[{"id": "a", "text": "Day 3: tearful with mild sadness, caring well for the baby"}, {"id": "b", "text": "Day 4: irritable and weepy, resting when the baby sleeps"}, {"id": "c", "text": "Day 10: crying spells that are clearly improving each day"}, {"id": "d", "text": "Week 3: sad for over 2 weeks and unable to manage baby care"}]'::jsonb, '["d"]', 'Sadness persisting beyond 2 weeks that impairs functioning indicates PPD, which requires referral. Mild, functional symptoms starting at 2–4 days and resolving within 14 days fit baby blues.'),
  ('bonding', 43, 'A nurse educator asks a new nurse to match barriers to bonding with appropriate responses. Which pairing by the new nurse is correct?', '[{"id": "a", "text": "Domestic violence: involve the partner more in newborn care"}, {"id": "b", "text": "Adolescent mother: perform all care for her to prevent errors"}, {"id": "c", "text": "Cesarean birth: skin-to-skin as soon as medically safe"}, {"id": "d", "text": "Lack of social support: mandatory report to authorities"}]'::jsonb, '["c"]', 'After a cesarean, the nurse facilitates skin-to-skin as soon as medically safe and involves the partner. Domestic violence calls for private screening and safety planning, adolescents need education and modeling, and lack of support calls for community resources.'),
  ('bonding', 44, 'During private screening, a postpartum client discloses that her partner hits her and that she is afraid to go home with the baby. Which action should the nurse take next?', '[{"id": "a", "text": "Develop a safety plan and report as required"}, {"id": "b", "text": "Confront the partner about the abuse at the bedside"}, {"id": "c", "text": "Arrange couples counseling with the partner present"}, {"id": "d", "text": "Keep the disclosure private and take no further action"}]'::jsonb, '["a"]', 'For domestic violence, private screening is followed by safety planning and mandatory reporting as required. Confronting the partner or involving him in counseling could increase danger, and taking no action ignores the barrier.'),
  ('bonding', 45, 'After teaching a mother about her newborn''s cues, the nurse observes several feedings. Which observation best indicates the teaching was effective?', '[{"id": "a", "text": "She feeds strictly every 4 hours regardless of the baby''s cues"}, {"id": "b", "text": "She feeds promptly when the baby roots and sucks on a fist"}, {"id": "c", "text": "She lets the baby cry for a while so the baby is not spoiled"}, {"id": "d", "text": "She asks the nurse to interpret each cry the baby makes"}]'::jsonb, '["b"]', 'Appropriately interpreting cues and responding promptly are positive bonding behaviors and show that cue teaching worked. Ignoring cues or crying, or relying on the nurse, shows that learning has not occurred.'),
  ('bonding', 46, 'A stable term newborn is born at 14:10 and immediately placed skin-to-skin with the mother. Until approximately what time should non-urgent procedures such as weighing and bathing be delayed when possible?', '[{"id": "a", "text": "14:25"}, {"id": "b", "text": "14:40"}, {"id": "c", "text": "15:10"}, {"id": "d", "text": "16:10"}]'::jsonb, '["c"]', 'The golden hour is the first 60 minutes of uninterrupted skin-to-skin, so non-urgent procedures wait until about 15:10. Stopping at 15 or 30 minutes cuts the golden hour short.'),
  ('bonding', 47, 'Ten minutes after birth, a mother who first touched her baby''s hands with her fingertips now rests her full palm on the baby''s back. Her partner asks whether she is moving too fast. Which response by the nurse is correct?', '[{"id": "a", "text": "This is expected; enfolding often follows within the hour"}, {"id": "b", "text": "She should remain at fingertip touch for the whole first hour"}, {"id": "c", "text": "Moving this quickly is a concerning sign that I need to assess"}, {"id": "d", "text": "Palm touching normally appears only after the first hour"}]'::jsonb, '["a"]', 'Palm touching on the trunk and back normally occurs within minutes of fingertip touching, followed by enfolding within the first hour. Her progression is on schedule, not too fast.'),
  ('bonding', 48, 'A nursing student presents a plan to promote bonding for a healthy breastfeeding mother and newborn. Which statement by the student requires correction?', '[{"id": "a", "text": "Rooming-in helps parents learn their baby''s cues"}, {"id": "b", "text": "Skin-to-skin is the most evidence-based bonding measure"}, {"id": "c", "text": "The en face position is a positive attachment behavior"}, {"id": "d", "text": "Nursery care at night is preferred for breastfeeding"}]'::jsonb, '["d"]', 'Rooming-in, not nursery care, is preferred for bonding and breastfeeding. The other statements about rooming-in, skin-to-skin, and the en face position are accurate.'),
  ('bonding', 49, 'Three weeks after birth, a mother has become withdrawn, says she has no motivation, and is struggling to care for her baby. She denies hallucinations or delusions. Which plan best addresses this barrier to bonding?', '[{"id": "a", "text": "Encourage rest and reassure her these feelings are expected"}, {"id": "b", "text": "EPDS screening, counseling or medication referral, and support"}, {"id": "c", "text": "Immediate psychiatric hospitalization for her own safety"}, {"id": "d", "text": "Modeling of parenting and links to teen parenting resources"}]'::jsonb, '["b"]', 'Withdrawal, decreased motivation, and inability to care for the baby beyond 2 weeks suggest PPD, addressed with the EPDS, referral for counseling or medication, and a support network. Hospitalization is for psychosis, and teen resources are for adolescent mothers.'),
  ('bonding', 50, 'A pregnant client at 30 weeks of gestation talks to her fetus, has already chosen a name, and rubs her abdomen whenever she feels movement. Her partner asks the nurse what this means. Which response is most accurate?', '[{"id": "a", "text": "Bonding does not begin until the baby is actually born"}, {"id": "b", "text": "This may signal anxiety that should be assessed further"}, {"id": "c", "text": "Bonding with the baby can begin even before birth"}, {"id": "d", "text": "This is the fingertip phase of maternal touch behavior"}]'::jsonb, '["c"]', 'Bonding is the parent-to-infant emotional connection that begins at birth or even prenatally. The fingertip phase describes first contact with the newborn after birth.'),
  ('apgar', 1, 'At 1 minute of life, a term newborn has a pink body with blue hands and feet, a heart rate of 98 bpm, sneezes when the suction catheter enters the nares, shows some flexion of the extremities, and has slow, irregular breathing with a weak cry. Which action should the nurse take first?', '[{"id": "a", "text": "Begin positive pressure ventilation and prepare for compressions"}, {"id": "b", "text": "Rub the back, give free-flow oxygen, and reassess at 5 minutes"}, {"id": "c", "text": "Place the newborn skin-to-skin and continue routine care"}, {"id": "d", "text": "Begin chest compressions because the heart rate is below 100"}]'::jsonb, '["b"]', 'Appearance 1 + pulse 1 + grimace 2 (sneeze) + activity 1 + respirations 1 = 6, a 4–6 score that calls for stimulation, free-flow oxygen, and reassessment at 5 minutes. PPV and compressions belong to the 0–3 range, and compressions are reserved for a heart rate below 60 despite PPV.'),
  ('apgar', 2, 'A newborn assessed at 1 minute is completely pink, has a heart rate of 102 bpm, coughs when suctioned, shows some flexion of the extremities, and has slow, irregular respirations with a weak cry. Which APGAR score and nursing response are correct?', '[{"id": "a", "text": "6; stimulate the newborn and give free-flow oxygen"}, {"id": "b", "text": "7; stimulate the newborn and reassess at 5 minutes"}, {"id": "c", "text": "8; dry, warm, and promote skin-to-skin contact"}, {"id": "d", "text": "9; provide routine care and continue monitoring"}]'::jsonb, '["c"]', 'Appearance 2 + pulse 2 (≥100) + grimace 2 (cough) + activity 1 + respirations 1 = 8, which is in the 7–10 range for routine care. Scoring 102 bpm as 1 point or treating some flexion as full tone produces the wrong totals in the distractors.'),
  ('apgar', 3, 'At 1 minute, a newborn is pale all over, has a heart rate of 90 bpm, only grimaces when the catheter is introduced, shows some flexion, and makes no respiratory effort. Which intervention is the nurse''s priority?', '[{"id": "a", "text": "Rub the back, flick the soles, and give free-flow oxygen"}, {"id": "b", "text": "Begin chest compressions coordinated with ventilation"}, {"id": "c", "text": "Administer epinephrine before starting any ventilation"}, {"id": "d", "text": "Begin positive pressure ventilation immediately"}]'::jsonb, '["d"]', 'Appearance 0 + pulse 1 + grimace 1 + activity 1 + respirations 0 = 3, which requires immediate resuscitation beginning with PPV. Stimulation with free-flow oxygen is the 4–6 response, and compressions/epinephrine apply only when the heart rate stays below 60.'),
  ('apgar', 4, 'A term newborn at 1 minute is pink centrally with blue hands and feet, has a heart rate of 138 bpm, cries when suctioned, shows active flexion, and has a strong, regular cry. Which action by the nurse requires correction?', '[{"id": "a", "text": "Removing the newborn from skin-to-skin to give free-flow oxygen"}, {"id": "b", "text": "Drying and warming the newborn while on the mother''s chest"}, {"id": "c", "text": "Positioning the newborn and keeping skin-to-skin contact"}, {"id": "d", "text": "Rescoring the newborn at 5 minutes after the birth"}]'::jsonb, '["a"]', 'The score is 1 + 2 + 2 + 2 + 2 = 9; acrocyanosis at 1 minute is normal and earns 1 point, so routine care with skin-to-skin is correct. Interrupting skin-to-skin for oxygen treats a normal finding as a problem.'),
  ('apgar', 5, 'A nurse documents a 1-minute APGAR of 5 for a newborn with a pink body and blue hands and feet, a heart rate of 100 bpm, who cries when a suction catheter is introduced, shows active flexion, and takes slow, irregular breaths with a weak cry. Which conclusion by the charge nurse is correct?', '[{"id": "a", "text": "It is correct at 5; stimulate and give free-flow oxygen"}, {"id": "b", "text": "It should be 7; a heart rate of 100 bpm earns only 1 point"}, {"id": "c", "text": "It should be 9; acrocyanosis earns full points at 1 minute"}, {"id": "d", "text": "It should be 8; routine care with skin-to-skin is indicated"}]'::jsonb, '["d"]', 'Appearance 1 + pulse 2 (100 is ≥100) + grimace 2 (cry) + activity 2 + respirations 1 = 8, so routine care applies. A heart rate of exactly 100 bpm is in the safe 2-point range, and acrocyanosis scores 1, not 2.'),
  ('apgar', 6, 'A newborn who scored 3 at 1 minute received positive pressure ventilation. At 5 minutes, the newborn is completely pink, has a heart rate of 110 bpm, shows no response to the suction catheter, has some flexion, and breathes slowly and irregularly. Which nursing action is most appropriate at this time?', '[{"id": "a", "text": "Stop APGAR scoring because the 5-minute score is final"}, {"id": "b", "text": "Continue APGAR scoring every 5 minutes up to 20 minutes"}, {"id": "c", "text": "Begin routine care because the score has improved from 3"}, {"id": "d", "text": "Begin chest compressions because the score is below 7"}]'::jsonb, '["b"]', 'The 5-minute score is 2 + 2 + 0 + 1 + 1 = 6; a 5-minute score below 7 requires reassessment every 5 minutes up to 20 minutes. Improvement from 3 does not make it a normal score, and compressions depend on a heart rate below 60, not on the total.'),
  ('apgar', 7, 'A newborn scored 4 at 1 minute and 8 at 5 minutes after stimulation and free-flow oxygen. The father asks whether the low first score means his son will have learning problems. Which response by the nurse is most accurate?', '[{"id": "a", "text": "The score guides care at birth; it doesn''t predict later outcome"}, {"id": "b", "text": "A score of 4 suggests a mild brain injury that will need follow-up"}, {"id": "c", "text": "Only the 1-minute score predicts development, and 4 is borderline"}, {"id": "d", "text": "The 5-minute score of 8 guarantees that he will develop normally"}]'::jsonb, '["a"]', 'APGAR is a snapshot that guides immediate resuscitation and does not predict long-term outcome. Neither the 1-minute nor the 5-minute score forecasts neurological development.'),
  ('apgar', 8, 'During a 1-minute APGAR on a term newborn whose trunk is pink but whose hands and feet are blue, a student nurse assigns 0 for appearance, stating that any blue means cyanosis. Which response by the precepting nurse is correct?', '[{"id": "a", "text": "Correct; any visible cyanosis earns 0 for appearance"}, {"id": "b", "text": "Appearance earns 2, since acrocyanosis is expected"}, {"id": "c", "text": "Appearance is not scored until the 5-minute check"}, {"id": "d", "text": "It earns 1; acrocyanosis is normal at 1 minute"}]'::jsonb, '["d"]', 'A pink body with blue extremities (acrocyanosis) is normal at 1 minute and scores 1, not 0. Being expected does not raise it to 2; only a completely pink newborn earns 2.'),
  ('apgar', 9, 'A term newborn at 1 minute is pink centrally with blue hands and feet, has a heart rate of 146 bpm, sneezes with suctioning, shows active flexion with movement, and has a strong cry with regular breathing. The mother asks why her baby did not get a perfect 10. Which response by the nurse is best?', '[{"id": "a", "text": "A 9 shows mild distress, so your baby will get extra oxygen"}, {"id": "b", "text": "Blue hands and feet are common, so most healthy babies score 7 to 9"}, {"id": "c", "text": "A 9 means we will recheck the score every 5 minutes for 20 minutes"}, {"id": "d", "text": "Your baby lost a point for heart rate, which should rise by 5 minutes"}]'::jsonb, '["b"]', 'The total is 1 + 2 + 2 + 2 + 2 = 9; a 10 is rare because acrocyanosis is common, so most healthy newborns score 7–9. A 9 is in the routine-care range, and 146 bpm earns full points.'),
  ('apgar', 10, 'At 1 minute, a newborn has a pink trunk with blue hands and feet, a heart rate of 124 bpm, only grimaces when the catheter is introduced, shows active flexion, and has slow, irregular breathing with a weak cry. What is the nurse''s most appropriate action?', '[{"id": "a", "text": "Dry, warm, position, and place the newborn skin-to-skin"}, {"id": "b", "text": "Rub the back, flick the soles, and give free-flow oxygen"}, {"id": "c", "text": "Begin positive pressure ventilation and call the team"}, {"id": "d", "text": "Reassess every 5 minutes until the 20-minute mark"}]'::jsonb, '["a"]', 'Appearance 1 + pulse 2 + grimace 1 + activity 2 + respirations 1 = 7, the lower edge of the normal 7–10 range, so routine care applies. Stimulation and free-flow oxygen are for scores of 4–6.'),
  ('apgar', 11, 'At 1 minute, a newborn is blue and pale all over, has a heart rate of 84 bpm, grimaces only when suctioned, shows some flexion, and has slow, irregular breathing with a weak cry. Which intervention should the nurse initiate first?', '[{"id": "a", "text": "Begin positive pressure ventilation without delay"}, {"id": "b", "text": "Start chest compressions as the heart rate is below 100"}, {"id": "c", "text": "Stimulate, reposition the airway, and give free-flow O2"}, {"id": "d", "text": "Dry and warm, then promote skin-to-skin with the mother"}]'::jsonb, '["c"]', 'Appearance 0 + pulse 1 + grimace 1 + activity 1 + respirations 1 = 4, the bottom of the 4–6 range, which calls for stimulation, airway repositioning, and free-flow oxygen. PPV is the response for a total of 0–3.'),
  ('apgar', 12, 'At 1 minute, a newborn is completely pink, has a heart rate of 108 bpm, cries when suctioned, shows some flexion, and has slow, irregular breathing with a weak cry. The nurse provides routine care. Which single different finding would instead have required stimulation and free-flow oxygen?', '[{"id": "a", "text": "A heart rate of 96 bpm instead of 108 bpm"}, {"id": "b", "text": "Active flexion with movement of the limbs"}, {"id": "c", "text": "A pink body with blue hands and feet"}, {"id": "d", "text": "No response to the suction catheter"}]'::jsonb, '["d"]', 'The current score is 2 + 2 + 2 + 1 + 1 = 8; losing both grimace points (no response) drops it to 6, which requires stimulation and free-flow oxygen. A heart rate of 96 bpm or acrocyanosis subtracts only 1 point, leaving a normal 7.'),
  ('apgar', 13, 'A newborn with a 1-minute APGAR of 2 is receiving positive pressure ventilation. After effective ventilation, the heart rate is 52 bpm. Which intervention is the priority now?', '[{"id": "a", "text": "Giving epinephrine as the next intervention"}, {"id": "b", "text": "Beginning chest compressions as the next step"}, {"id": "c", "text": "Switching to free-flow oxygen with back rubbing"}, {"id": "d", "text": "Stopping ventilation and rescoring at 5 minutes"}]'::jsonb, '["b"]', 'A heart rate below 60 despite PPV is the trigger for chest compressions. Epinephrine is added only if the rate stays below 60 after compressions.'),
  ('apgar', 14, 'A newborn scored 1 at 1 minute. Despite positive pressure ventilation followed by chest compressions, the heart rate remains 48 bpm. Which intervention is the nurse''s priority now?', '[{"id": "a", "text": "Epinephrine administration"}, {"id": "b", "text": "Stopping compressions and continuing ventilation only"}, {"id": "c", "text": "Stimulation by rubbing the back and flicking the soles"}, {"id": "d", "text": "Free-flow oxygen and rescoring at the 5-minute mark"}]'::jsonb, '["a"]', 'When the heart rate stays below 60 after compressions, epinephrine is the next step in the resuscitation sequence. Stimulation and free-flow oxygen are the response to a 4–6 score, not to severe depression.'),
  ('apgar', 15, 'A newborn with a 1-minute APGAR of 2 has been receiving positive pressure ventilation, and the heart rate is now 64 bpm. A student asks whether chest compressions should start. Which reply by the nurse is correct?', '[{"id": "a", "text": "Yes; compressions are needed because the rate is below 100 bpm"}, {"id": "b", "text": "Yes; epinephrine and compressions are needed below 100 bpm"}, {"id": "c", "text": "No; compressions are not yet indicated at a rate of 64 bpm"}, {"id": "d", "text": "No; compressions are reserved for newborns with no heart rate"}]'::jsonb, '["c"]', 'Compressions are added only when the heart rate is below 60 despite PPV, so 64 bpm does not meet the threshold. A rate below 100 lowers the pulse score but is not the compression trigger, and compressions are not limited to an absent rate.'),
  ('apgar', 16, 'A newborn scored 5 at 1 minute and received stimulation and free-flow oxygen. At 5 minutes, the newborn is completely pink, has a heart rate of 132 bpm, coughs with suctioning, shows some flexion, and has a strong cry with regular breathing. How should the nurse interpret this score?', '[{"id": "a", "text": "It shows a good response to intervention; routine care can follow"}, {"id": "b", "text": "It reflects birth transition, so rescoring continues until 20 minutes"}, {"id": "c", "text": "It predicts normal long-term neurological development for the newborn"}, {"id": "d", "text": "It requires neonatal resuscitation team involvement at 10 minutes"}]'::jsonb, '["a"]', 'The 5-minute score is 2 + 2 + 2 + 1 + 2 = 9 and reflects response to interventions; a score of 7 or more means routine care. Birth transition is what the 1-minute score reflects, and APGAR does not predict long-term outcome.'),
  ('apgar', 17, 'Four newborns are rescored at 5 minutes after birth. For which newborn should the nurse plan to repeat APGAR scoring at 10 minutes?', '[{"id": "a", "text": "Pink body, blue hands and feet; HR 96; grimace only; some flexion; weak, irregular cry"}, {"id": "b", "text": "Completely pink; HR 102; grimace only; some flexion; slow, irregular breathing"}, {"id": "c", "text": "Pink body, blue hands and feet; HR 118; cries when suctioned; some flexion; strong cry"}, {"id": "d", "text": "Completely pink; HR 140; sneezes when suctioned; some flexion; weak, irregular cry"}]'::jsonb, '["a"]', 'Newborn (a) totals 1 + 1 + 1 + 1 + 1 = 5, and a 5-minute score below 7 requires reassessment every 5 minutes. Newborn (b) scores 7 because 102 bpm earns 2 points, and (c) and (d) both score 8.'),
  ('apgar', 18, 'A nursing student is helping with 1-minute APGAR care for four newborns in the birthing unit. Which action by the student requires the nurse to intervene?', '[{"id": "a", "text": "Rubbing the back of a newborn who scored 5 at 1 minute"}, {"id": "b", "text": "Placing a newborn who scored 8 skin-to-skin with the mother"}, {"id": "c", "text": "Waiting until 5 minutes to ventilate a newborn who scored 2"}, {"id": "d", "text": "Flicking the soles of a newborn who scored 6 at 1 minute"}]'::jsonb, '["c"]', 'A score of 0–3 requires immediate resuscitation with PPV, so delaying ventilation until the 5-minute score is unsafe. Back rubbing and sole flicking are correct for 4–6, and skin-to-skin is routine care for 7–10.'),
  ('apgar', 19, 'At 1 minute, a newborn has a pink trunk with blue hands and feet, a heart rate of 99 bpm, grimaces only when suctioned, shows active flexion, and has slow, irregular breathing with a weak cry. Which score and action are correct?', '[{"id": "a", "text": "7; routine care with skin-to-skin contact"}, {"id": "b", "text": "6; stimulation and free-flow oxygen"}, {"id": "c", "text": "5; stimulation and free-flow oxygen"}, {"id": "d", "text": "6; positive pressure ventilation"}]'::jsonb, '["b"]', 'Appearance 1 + pulse 1 (99 is below 100) + grimace 1 + activity 2 + respirations 1 = 6, which calls for stimulation and free-flow oxygen. Rounding 99 bpm up to the safe range gives the incorrect total of 7.'),
  ('apgar', 20, 'A newborn at 1 minute is completely pink, has a heart rate of 100 bpm, grimaces only when suctioned, shows some flexion, and has slow, irregular breathing with a weak cry. Which plan is most appropriate?', '[{"id": "a", "text": "Stimulate, flick the soles, and give free-flow oxygen"}, {"id": "b", "text": "Begin PPV and call for the neonatal resuscitation team"}, {"id": "c", "text": "Routine care: dry, warm, position, and skin-to-skin"}, {"id": "d", "text": "Reposition the airway and rescore every 5 minutes"}]'::jsonb, '["c"]', 'Appearance 2 + pulse 2 (100 is ≥100) + grimace 1 + activity 1 + respirations 1 = 7, the normal range for routine care. Scoring 100 bpm as 1 point gives 6 and would wrongly lead to stimulation and oxygen.'),
  ('apgar', 21, 'A newborn''s APGAR was 5 at 1 minute and 8 at 5 minutes after stimulation and free-flow oxygen. Which statement by a student nurse indicates correct understanding of the scores?', '[{"id": "a", "text": "The 1-minute score showed how well our interventions worked"}, {"id": "b", "text": "The 5-minute score of 8 confirms a normal neurological outcome"}, {"id": "c", "text": "The 1-minute score of 5 meant PPV should have started at once"}, {"id": "d", "text": "The 1-minute score reflected her transition after birth"}]'::jsonb, '["d"]', 'The 1-minute score assesses transition from intrauterine to extrauterine life, while the 5-minute score reflects response to interventions. A score of 5 calls for stimulation and oxygen rather than PPV, and APGAR does not predict neurological outcome.'),
  ('apgar', 22, 'At 1 minute, a newborn has a pink body with blue hands and feet, a heart rate of 92 bpm, coughs when the suction catheter is introduced, shows active flexion, and has slow, irregular breathing with a weak cry. Which score and plan are correct?', '[{"id": "a", "text": "6; stimulate and give free-flow oxygen"}, {"id": "b", "text": "7; routine care and continued monitoring"}, {"id": "c", "text": "7; stimulate and reassess at 5 minutes"}, {"id": "d", "text": "8; routine care and continued monitoring"}]'::jsonb, '["b"]', 'Appearance 1 + pulse 1 + grimace 2 (cough) + activity 2 + respirations 1 = 7, which is normal and calls for routine care. Scoring a cough as a grimace only gives 6, and a total of 7 does not call for stimulation.'),
  ('apgar', 23, 'At 1 minute, a newborn is completely pink, has a heart rate of 150 bpm, cries vigorously when suctioned, and has regular breathing with a strong cry, but the arms and legs are limp and flaccid. Which interpretation by the nurse is most accurate?', '[{"id": "a", "text": "The total of 6 calls for stimulation and free-flow oxygen"}, {"id": "b", "text": "The total of 8 calls for stimulation and free-flow oxygen"}, {"id": "c", "text": "The total of 8 is normal, but the tone is a neurological concern"}, {"id": "d", "text": "The total of 10 is rare, and routine care can continue as usual"}]'::jsonb, '["c"]', 'The score is 2 + 2 + 2 + 0 + 2 = 8, which is in the normal range, yet flaccid tone is flagged as a neurological concern. A total of 8 does not call for stimulation, and limp extremities score 0, not 2.'),
  ('apgar', 24, 'Immediately after a difficult birth, a newborn at 1 minute is pale, limp, and not breathing, shows no reaction to the suction catheter, and has no detectable heart rate. Which intervention comes first in the resuscitation sequence?', '[{"id": "a", "text": "Chest compressions, because no heart rate is detected"}, {"id": "b", "text": "Epinephrine, because the heart rate is absent"}, {"id": "c", "text": "Positive pressure ventilation"}, {"id": "d", "text": "Back rubbing and free-flow oxygen, then rescoring"}]'::jsonb, '["c"]', 'A score of 0 requires immediate resuscitation, and the sequence begins with PPV; compressions follow only if the heart rate stays below 60 despite PPV, and epinephrine after compressions. Stimulation with free-flow oxygen is the 4–6 response.'),
  ('apgar', 25, 'Four newborns are assessed at 1 minute in the birthing unit. Which newborn can remain skin-to-skin with the mother for routine care?', '[{"id": "a", "text": "Pink body, blue hands and feet; HR 98; cries when suctioned; some flexion; weak, irregular cry"}, {"id": "b", "text": "Completely pink; HR 104; grimace only; some flexion; weak, irregular cry"}, {"id": "c", "text": "Pink body, blue hands and feet; HR 110; grimace only; limp; weak, irregular cry"}, {"id": "d", "text": "Pale all over; HR 120; grimace only; active flexion; weak, irregular cry"}]'::jsonb, '["b"]', 'Newborn (b) totals 2 + 2 + 1 + 1 + 1 = 7, the normal range for routine care. Newborn (a) scores 6 because 98 bpm earns 1 point, (c) scores 5, and (d) scores 6, all needing stimulation and oxygen.'),
  ('apgar', 26, 'The parents of a newborn whose APGAR was 6 at 1 minute and 9 at 5 minutes are taught about the scoring. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "The score is checked at 1 minute and again at 5 minutes"}, {"id": "b", "text": "Blue hands and feet right after birth can be normal for her"}, {"id": "c", "text": "Her low first score means she will likely have delays later"}, {"id": "d", "text": "Each of the five signs is given between 0 and 2 points"}]'::jsonb, '["c"]', 'APGAR is a snapshot used to guide immediate care, not a predictor of long-term neurological outcome, so this statement needs correction. Scoring at 1 and 5 minutes, normal acrocyanosis, and 0–2 points per sign are all accurate.'),
  ('apgar', 27, 'A newborn scored 2 at 1 minute and 5 at 5 minutes. At 10 minutes, the newborn has a pink body with blue hands and feet, a heart rate of 112 bpm, grimaces only when suctioned, shows some flexion, and has a weak, irregular cry. What is the nurse''s priority plan?', '[{"id": "a", "text": "Resume routine care because the score has improved from 5"}, {"id": "b", "text": "Stop scoring because 10 minutes is the final APGAR time"}, {"id": "c", "text": "Rescore at 15 minutes with neonatal resuscitation team input"}, {"id": "d", "text": "Begin chest compressions because the score remains below 7"}]'::jsonb, '["c"]', 'The 10-minute score is 1 + 2 + 1 + 1 + 1 = 6; when scores stay below 7 after 5 minutes, monitoring continues at 10, 15, and 20 minutes with neonatal resuscitation team involvement. Compressions depend on a heart rate below 60, not the total.'),
  ('apgar', 28, 'A newborn scored 5 at 1 minute and received stimulation and free-flow oxygen. Which set of 5-minute findings best indicates that the interventions were effective?', '[{"id": "a", "text": "Pink body, blue hands and feet; HR 94; grimace only; some flexion; weak, irregular cry"}, {"id": "b", "text": "Completely pink; HR 106; sneezes; some flexion; weak, irregular cry"}, {"id": "c", "text": "Pale all over; HR 120; grimace only; some flexion; weak, irregular cry"}, {"id": "d", "text": "Pink body, blue hands and feet; HR 98; coughs; limp; strong, regular cry"}]'::jsonb, '["b"]', 'Set (b) totals 2 + 2 + 2 + 1 + 1 = 8, a normal score showing response to interventions. Sets (a) and (c) total 5 and set (d) totals 6, all still below 7.'),
  ('apgar', 29, 'Four newborns are scored at 1 minute. Which newborn requires positive pressure ventilation rather than stimulation and free-flow oxygen?', '[{"id": "a", "text": "Pale all over; HR 70; grimace only; some flexion; weak, irregular cry"}, {"id": "b", "text": "Pink body, blue extremities; HR 80; no response; limp; weak, irregular cry"}, {"id": "c", "text": "Pale all over; HR 104; no response; some flexion; weak, irregular cry"}, {"id": "d", "text": "Pink body, blue extremities; HR 90; grimace only; limp; weak, irregular cry"}]'::jsonb, '["b"]', 'Newborn (b) totals 1 + 1 + 0 + 0 + 1 = 3, which requires immediate resuscitation with PPV. Newborns (a), (c), and (d) each total 4, the lower edge of the stimulation and oxygen range.'),
  ('apgar', 30, 'A nurse documents a 1-minute APGAR of 6 for a newborn who is completely pink, has a heart rate of 110 bpm, shows some flexion, and has slow, irregular breathing with a weak cry. Which response to the suction catheter must the newborn have shown?', '[{"id": "a", "text": "No response to the catheter"}, {"id": "b", "text": "A grimace only"}, {"id": "c", "text": "A cry when suctioned"}, {"id": "d", "text": "A sneeze when suctioned"}]'::jsonb, '["a"]', 'The other signs total 2 + 2 + 1 + 1 = 6, so reflex irritability must have scored 0, meaning no response. A grimace only would make the total 7, and a cry or sneeze would make it 8.'),
  ('apgar', 31, 'A newborn''s 1-minute APGAR is documented as 7. The newborn has a pink body with blue hands and feet, grimaces only when suctioned, shows active flexion, and has a strong cry with regular breathing. Which heart rate is consistent with this total?', '[{"id": "a", "text": "128 bpm"}, {"id": "b", "text": "100 bpm"}, {"id": "c", "text": "No detectable rate"}, {"id": "d", "text": "92 bpm"}]'::jsonb, '["d"]', 'The other signs total 1 + 1 + 2 + 2 = 6, so the pulse must have scored 1, which requires a rate below 100. Rates of 100 and 128 bpm earn 2 points (total 8), and an absent rate earns 0 (total 6).'),
  ('apgar', 32, 'A newborn at 1 minute has a pink body with blue hands and feet, a heart rate of 94 bpm, sneezes when suctioned, shows some flexion, and has slow, irregular breathing with a weak cry. Which action by the nurse requires correction?', '[{"id": "a", "text": "Rubbing the newborn''s back to provide stimulation"}, {"id": "b", "text": "Flicking the soles of the newborn''s feet"}, {"id": "c", "text": "Starting chest compressions for the rate of 94 bpm"}, {"id": "d", "text": "Giving free-flow oxygen and rescoring at 5 minutes"}]'::jsonb, '["c"]', 'The score is 1 + 1 + 2 + 1 + 1 = 6, which calls for stimulation and free-flow oxygen with reassessment. Compressions are indicated only for a heart rate below 60 despite PPV, not for a rate below 100.'),
  ('apgar', 33, 'At 1 minute, a newborn is pale all over, has a heart rate of 88 bpm, coughs when suctioned, shows some flexion, and has slow, irregular breathing with a weak cry. A student plans to wait for the 5-minute score before intervening because the first score only reflects transition. Which response by the nurse is best?', '[{"id": "a", "text": "Agreed; care is based on the 5-minute score, not the 1-minute one"}, {"id": "b", "text": "A score in this range calls for stimulation and oxygen right now"}, {"id": "c", "text": "This score calls for positive pressure ventilation without delay"}, {"id": "d", "text": "Agreed; pallor at 1 minute is expected and scores a 1 for color"}]'::jsonb, '["b"]', 'The score is 0 + 1 + 2 + 1 + 1 = 5; a low 1-minute score calls for stimulation, supplemental oxygen, and warming/drying now. PPV is reserved for 0–3, and only acrocyanosis, not generalized pallor, is expected and scores 1.'),
  ('apgar', 34, 'At 1 minute, a newborn is pale all over, has a heart rate of 110 bpm, does not respond to the suction catheter, is limp, and has no respiratory effort. Which plan is the priority?', '[{"id": "a", "text": "Positive pressure ventilation; compressions are not indicated"}, {"id": "b", "text": "Ventilation plus chest compressions because the score is 0–3"}, {"id": "c", "text": "Stimulation and free-flow oxygen because the heart rate is safe"}, {"id": "d", "text": "Epinephrine first, followed by positive pressure ventilation"}]'::jsonb, '["a"]', 'The score is 0 + 2 + 0 + 0 + 0 = 2, requiring immediate PPV; with a rate of 110, the below-60 trigger for compressions is not met. A safe heart rate does not override a total of 0–3.'),
  ('apgar', 35, 'At 1 minute, a newborn is completely pink, has a heart rate of 136 bpm, and has a strong cry with regular breathing and active flexion. When the suction catheter is introduced, the newborn only grimaces. What APGAR score should the nurse record?', '[{"id": "a", "text": "7"}, {"id": "b", "text": "8"}, {"id": "c", "text": "9"}, {"id": "d", "text": "10"}]'::jsonb, '["c"]', 'Appearance 2 + pulse 2 + grimace 1 (grimace only) + activity 2 + respirations 2 = 9. Only a cry, cough, or sneeze to the catheter earns 2 points for reflex irritability, so 10 is incorrect.'),
  ('apgar', 36, 'A newborn has a 1-minute APGAR of 2 and is in severe depression. If the heart rate stays below 60 bpm at each step, which sequence of interventions should the nurse anticipate?', '[{"id": "a", "text": "Chest compressions → positive pressure ventilation → epinephrine"}, {"id": "b", "text": "Positive pressure ventilation → epinephrine → chest compressions"}, {"id": "c", "text": "Stimulation → epinephrine → positive pressure ventilation"}, {"id": "d", "text": "Positive pressure ventilation → chest compressions → epinephrine"}]'::jsonb, '["d"]', 'Resuscitation begins with PPV, adds chest compressions if the heart rate is below 60 despite PPV, and adds epinephrine if it is still below 60 after compressions. Starting with compressions or giving epinephrine before compressions reverses the order.'),
  ('apgar', 37, 'A newborn scored 4 at 1 minute. At 5 minutes, the newborn has a pink body with blue hands and feet, a heart rate of 116 bpm, grimaces only when suctioned, shows active flexion, and has slow, irregular breathing with a weak cry. Which plan is most appropriate?', '[{"id": "a", "text": "Repeat scoring every 5 minutes until the 20-minute mark"}, {"id": "b", "text": "Involve the neonatal resuscitation team at 10 minutes"}, {"id": "c", "text": "Continue stimulation and free-flow oxygen until 10 minutes"}, {"id": "d", "text": "Provide routine care and continue monitoring"}]'::jsonb, '["d"]', 'The 5-minute score is 1 + 2 + 1 + 2 + 1 = 7, which is normal, so routine care follows. Repeated scoring to 20 minutes and team involvement apply only when the 5-minute score is below 7.'),
  ('apgar', 38, 'At 1 minute, a newborn is pale all over, has a heart rate of 104 bpm, sneezes when suctioned, shows some flexion, and has slow, irregular breathing with a weak cry. Which component scored 0, and what is the total?', '[{"id": "a", "text": "Appearance; total of 6"}, {"id": "b", "text": "Pulse; total of 6"}, {"id": "c", "text": "Appearance; total of 7"}, {"id": "d", "text": "Respirations; total of 5"}]'::jsonb, '["a"]', 'Pallor all over scores 0, and the total is 0 + 2 + 2 + 1 + 1 = 6. A rate of 104 bpm earns 2 points, and slow, irregular breathing earns 1, not 0.'),
  ('apgar', 39, 'At 1 minute, a newborn is completely pink, has a heart rate of 94 bpm, shows no response to the suction catheter, has some flexion, and has a weak, irregular cry. The mother asks why the nurse is rubbing the baby''s back and flicking the soles. Which response is best?', '[{"id": "a", "text": "We do this for every newborn as part of routine care at birth"}, {"id": "b", "text": "Her first score is in the middle range, so we stimulate and recheck"}, {"id": "c", "text": "We are testing her reflexes to find out whether she has a brain injury"}, {"id": "d", "text": "This is how we measure the grimace part of her score right now"}]'::jsonb, '["b"]', 'The score is 2 + 1 + 0 + 1 + 1 = 5; a 4–6 score calls for stimulation (rubbing the back, flicking the soles) and reassessment. Routine care for 7–10 is drying, warming, positioning, and skin-to-skin, and the grimace sign is tested with a suction catheter.'),
  ('apgar', 40, 'A newborn scored 8 at 1 minute. At 5 minutes, the newborn has a pink body with blue hands and feet, a heart rate of 104 bpm, grimaces only when suctioned, shows some flexion, and has a weak, irregular cry. What is the nurse''s priority plan?', '[{"id": "a", "text": "Rescore every 5 minutes up to 20 minutes"}, {"id": "b", "text": "Resume routine care since the 1-minute score was 8"}, {"id": "c", "text": "Stop rescoring because the 5-minute score is final"}, {"id": "d", "text": "Document the decline and rescore at the 1-hour check"}]'::jsonb, '["a"]', 'The 5-minute score is 1 + 2 + 1 + 1 + 1 = 6; any 5-minute score below 7 requires reassessment every 5 minutes up to 20 minutes. A normal 1-minute score does not cancel a low 5-minute score.'),
  ('apgar', 41, 'At 1 minute, a newborn is pale all over but has a heart rate of 132 bpm, cries when the suction catheter is introduced, shows active flexion with movement, and has a strong cry with regular breathing. What is the nurse''s best action?', '[{"id": "a", "text": "Begin positive pressure ventilation for the generalized pallor"}, {"id": "b", "text": "Provide routine care: dry, warm, position, and skin-to-skin"}, {"id": "c", "text": "Rub the back, flick the soles, and give free-flow oxygen"}, {"id": "d", "text": "Reassess every 5 minutes until the total score reaches 10"}]'::jsonb, '["b"]', 'Pallor scores 0, but the total is 0 + 2 + 2 + 2 + 2 = 8, which is normal and calls for routine care. One 0-point sign does not place the newborn in the 0–3 or 4–6 range.'),
  ('apgar', 42, 'The parents of a newborn who scored 5 at 1 minute and 8 at 5 minutes after stimulation and oxygen ask about the two scores. Which statement by a parent shows correct understanding?', '[{"id": "a", "text": "The 1-minute score shows how she responded to the oxygen"}, {"id": "b", "text": "The 5-minute score tells us how she will do in school later"}, {"id": "c", "text": "The 5-minute score shows how she responded to the help given"}, {"id": "d", "text": "A healthy baby normally gets a 10, so she is still a bit behind"}]'::jsonb, '["c"]', 'The 5-minute score reflects the response to interventions, while the 1-minute score reflects birth transition. APGAR does not predict long-term outcome, and most healthy newborns score 7–9, not 10.'),
  ('apgar', 43, 'A nurse reviews four documented 1-minute assessments for accuracy. Which set of findings is consistent with a total APGAR score of 5?', '[{"id": "a", "text": "Completely pink; HR 90; grimace only; limp; weak, irregular cry"}, {"id": "b", "text": "Pink body, blue hands and feet; HR 104; grimace only; some flexion; weak, irregular cry"}, {"id": "c", "text": "Pale all over; HR 96; coughs; some flexion; no respiratory effort"}, {"id": "d", "text": "Pink body, blue hands and feet; HR 112; sneezes; some flexion; weak, irregular cry"}]'::jsonb, '["a"]', 'Set (a) totals 2 + 1 + 1 + 0 + 1 = 5. Set (b) totals 6, set (c) totals 4, and set (d) totals 7.'),
  ('apgar', 44, 'At 1 minute, a newborn is pale all over, has a heart rate of 80 bpm, shows no response to the suction catheter, is limp, and has slow, irregular breathing with a weak cry. The nurse begins PPV. Which single different finding would have placed this newborn in the 4–6 range instead?', '[{"id": "a", "text": "A grimace only when suctioned"}, {"id": "b", "text": "A heart rate of 104 bpm"}, {"id": "c", "text": "Some flexion of the extremities"}, {"id": "d", "text": "A cough when suctioned"}]'::jsonb, '["d"]', 'The current total is 0 + 1 + 0 + 0 + 1 = 2; a cough earns 2 points for reflex irritability, raising the total to 4. A grimace only, a rate of 104 bpm, or some flexion each add just 1 point, leaving a total of 3.'),
  ('apgar', 45, 'A newborn at 1 minute is pale all over, has a heart rate of 76 bpm, only grimaces when suctioned, is limp, and has slow, irregular breaths with a weak cry. A new nurse flicks the soles, gives free-flow oxygen, and plans to rescore at 5 minutes. Which response by the charge nurse is correct?', '[{"id": "a", "text": "Good plan; a score of 4 calls for stimulation and oxygen"}, {"id": "b", "text": "Begin chest compressions now; the heart rate is below 100"}, {"id": "c", "text": "Good plan; add epinephrine if the 5-minute score is still low"}, {"id": "d", "text": "This score of 3 needs immediate positive pressure ventilation"}]'::jsonb, '["d"]', 'The total is 0 + 1 + 1 + 0 + 1 = 3, which requires immediate resuscitation with PPV rather than stimulation. Compressions require a heart rate below 60 despite PPV, and epinephrine follows compressions.'),
  ('apgar', 46, 'A newborn at 1 minute is completely pink, has a heart rate of 96 bpm, grimaces only when suctioned, shows active flexion, and has slow, irregular breathing with a weak cry. Which action by a new nurse requires correction?', '[{"id": "a", "text": "Drying the newborn and keeping the newborn warm"}, {"id": "b", "text": "Positioning the newborn on the mother''s chest"}, {"id": "c", "text": "Keeping the newborn skin-to-skin with the mother"}, {"id": "d", "text": "Removing the newborn to flick soles and give oxygen"}]'::jsonb, '["d"]', 'The total is 2 + 1 + 1 + 2 + 1 = 7, the normal range, so drying, warming, positioning, and skin-to-skin are correct. Stimulation and free-flow oxygen are reserved for scores of 4–6.'),
  ('apgar', 47, 'A delivery record shows that a newborn''s APGAR was 3 at 1 minute and, after positive pressure ventilation, 7 at 5 minutes. Which conclusion by the nurse is most accurate?', '[{"id": "a", "text": "The 1-minute score of 3 predicts later neurological delay"}, {"id": "b", "text": "The ventilation worked; rescoring past 5 minutes is not needed"}, {"id": "c", "text": "The 5-minute score reflects birth transition, not the ventilation"}, {"id": "d", "text": "Rescoring must continue every 5 minutes up to 20 minutes"}]'::jsonb, '["b"]', 'The 5-minute score reflects response to interventions, and repeated scoring every 5 minutes is required only when the 5-minute score is below 7. APGAR does not predict long-term outcome.'),
  ('apgar', 48, 'A nurse documents a 1-minute APGAR of 6 for a newborn with a pink body and blue hands and feet, a heart rate of 108 bpm, a grimace only when suctioned, and slow, irregular breathing with a weak cry. Which muscle tone and action are consistent with this record?', '[{"id": "a", "text": "Limp extremities; begin positive pressure ventilation"}, {"id": "b", "text": "Active flexion; provide routine care with skin-to-skin"}, {"id": "c", "text": "Some flexion; stimulate and give free-flow oxygen"}, {"id": "d", "text": "Some flexion; begin positive pressure ventilation"}]'::jsonb, '["c"]', 'The other signs total 1 + 2 + 1 + 1 = 5, so activity must be 1 (some flexion) to reach 6, which calls for stimulation and free-flow oxygen. Limp tone gives 5 and active flexion gives 7, and PPV is for 0–3.'),
  ('apgar', 49, 'During the 1-minute APGAR of a newborn who is pink with blue hands and feet and crying weakly, the nurse introduces a suction catheter into the nares. The mother asks why. Which response by the nurse is most accurate?', '[{"id": "a", "text": "It checks her reflex response, which is one part of her score"}, {"id": "b", "text": "It stimulates her breathing, which is the first step for a low score"}, {"id": "c", "text": "It lets us count her heart rate, which is one part of her score"}, {"id": "d", "text": "It checks her muscle tone, which is one part of her score"}]'::jsonb, '["a"]', 'The grimace sign measures reflex irritability as the response to a suction catheter stimulus. Stimulation for a low score is done by rubbing the back and flicking the soles, and tone is scored by flexion.'),
  ('apgar', 50, 'At 1 minute, a newborn has a pink body with blue hands and feet, a heart rate of 92 bpm, coughs when suctioned, shows some flexion, and has slow, irregular breathing with a weak cry. A new nurse reaches for the PPV mask because the breathing is irregular. Which response by the charge nurse is best?', '[{"id": "a", "text": "Yes; irregular breathing scores 0 and requires ventilation"}, {"id": "b", "text": "Yes; a heart rate below 100 bpm requires ventilation now"}, {"id": "c", "text": "No; this score of 8 needs routine care with skin-to-skin"}, {"id": "d", "text": "No; a score of 6 needs stimulation and free-flow oxygen"}]'::jsonb, '["d"]', 'The total is 1 + 1 + 2 + 1 + 1 = 6; slow, irregular breathing scores 1, not 0, so stimulation and free-flow oxygen come first. A rate below 100 lowers the pulse score but is not an indication for PPV by itself.'),
  ('leopold', 1, 'The nurse is preparing to perform Leopold maneuvers on a client at 38 weeks who has just arrived for her prenatal visit. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Place the client supine with her knees slightly flexed"}, {"id": "b", "text": "Ask the client to empty her bladder"}, {"id": "c", "text": "Palpate the upper abdomen to identify the fundal contents"}, {"id": "d", "text": "Warm the hands before touching the client''s abdomen"}]'::jsonb, '["b"]', 'Before Leopold maneuvers, the client is asked to empty her bladder first, then positioned supine with knees slightly flexed, and the nurse uses warm hands. Palpating the fundus is the first maneuver, which comes after preparation.'),
  ('leopold', 2, 'A client at 36 weeks has emptied her bladder and is ready for Leopold maneuvers to assess fetal lie and presentation. Which position is best for this assessment?', '[{"id": "a", "text": "Left side-lying with a pillow between her knees"}, {"id": "b", "text": "Semi-Fowler''s with her legs fully extended"}, {"id": "c", "text": "Sitting upright on the edge of the exam table"}, {"id": "d", "text": "Supine with her knees slightly flexed"}]'::jsonb, '["d"]', 'Leopold maneuvers are performed with the client supine and her knees slightly flexed, after she empties her bladder. Side-lying or upright positions do not match this preparation.'),
  ('leopold', 3, 'A nursing student is performing Leopold maneuvers on a client at 37 weeks who has just voided. Which action by the student requires the instructor to intervene?', '[{"id": "a", "text": "Rubbing the hands together to warm them first"}, {"id": "b", "text": "Beginning by palpating the upper abdomen"}, {"id": "c", "text": "Having the client lie supine with her legs straight"}, {"id": "d", "text": "Placing both hands on the sides of the abdomen second"}]'::jsonb, '["c"]', 'The client should be supine with her knees slightly flexed, not with legs straight. Warm hands, starting at the upper abdomen (fundal grip), and then the lateral grip are all correct.'),
  ('leopold', 4, 'The nurse is reviewing the prenatal appointments of four clients. Based on gestational age, which client is the most appropriate candidate for Leopold maneuvers today?', '[{"id": "a", "text": "A client at 37 weeks"}, {"id": "b", "text": "A client at 30 weeks"}, {"id": "c", "text": "A client at 20 weeks"}, {"id": "d", "text": "A client at 12 weeks"}]'::jsonb, '["a"]', 'Leopold maneuvers are performed in the third trimester at 36+ weeks to determine lie, presentation, position, and engagement. A client at 30 weeks has not reached 36 weeks.'),
  ('leopold', 5, 'During the first Leopold maneuver on a client at 38 weeks, the nurse palpates the upper abdomen and feels a soft, irregular mass in the fundus. Which conclusion is best supported by this finding?', '[{"id": "a", "text": "The fetus is in a breech presentation"}, {"id": "b", "text": "The fetal head is flexed in a normal attitude"}, {"id": "c", "text": "The fetus is in a cephalic presentation"}, {"id": "d", "text": "The presenting part is engaged at station 0"}]'::jsonb, '["c"]', 'A softer, more irregular part in the fundus is the buttocks, so the head is the part entering the pelvis: a cephalic presentation. Attitude is assessed with the pelvic grip, and engagement with Pawlik''s grip.'),
  ('leopold', 6, 'At 37 weeks, the nurse performing the fundal grip feels a round, firm part in the upper abdomen that moves independently of the rest of the fetus. How should the nurse interpret this finding?', '[{"id": "a", "text": "Cephalic presentation, because the fetal head is palpable"}, {"id": "b", "text": "Breech presentation, because the head is in the fundus"}, {"id": "c", "text": "Engagement, because the head moves independently"}, {"id": "d", "text": "Extended attitude, because the head is firm and round"}]'::jsonb, '["b"]', 'A round, firm part that moves independently is the head; finding it in the fundus means the buttocks are entering the pelvis first, a breech presentation. Cephalic presentation would place the head, not the buttocks, toward the pelvis.'),
  ('leopold', 7, 'The nurse has just completed the fundal grip on a client at 38 weeks and identified soft, irregular buttocks in the fundus. What should the nurse do NEXT?', '[{"id": "a", "text": "Grasp the lower abdomen just above the symphysis pubis"}, {"id": "b", "text": "Face the client''s feet and slide the hands downward"}, {"id": "c", "text": "Palpate the fundus again to confirm the presentation"}, {"id": "d", "text": "Place the hands on both sides of the client''s abdomen"}]'::jsonb, '["d"]', 'The second maneuver, the lateral grip, follows the fundal grip and places the hands on both sides of the abdomen. Grasping above the symphysis is the third maneuver, and facing the feet is the fourth.'),
  ('leopold', 8, 'During the second Leopold maneuver, the nurse feels a smooth, firm, continuous surface on the client''s right side and small, irregular, moving parts on her left side. Which interpretation is best?', '[{"id": "a", "text": "The fetal back is on the right; hands and feet are on the left"}, {"id": "b", "text": "The fetal back is on the left; hands and feet are on the right"}, {"id": "c", "text": "The fetal head is on the right; the buttocks are on the left"}, {"id": "d", "text": "The presenting part is engaged on the right side of the pelvis"}]'::jsonb, '["a"]', 'In the lateral grip, one hand feels the smooth, firm back while the other detects small parts (hands, feet). The smooth surface on the right is the back, and the small parts on the left are the extremities.'),
  ('leopold', 9, 'A nurse wants to determine which direction a fetus at 37 weeks is facing in order to describe its position, such as left occiput anterior. Which assessment would best provide this information?', '[{"id": "a", "text": "Pawlik''s grip above the symphysis pubis"}, {"id": "b", "text": "Lateral grip on both sides of the abdomen"}, {"id": "c", "text": "Pelvic grip while facing the client''s feet"}, {"id": "d", "text": "Vaginal exam to determine fetal station"}]'::jsonb, '["b"]', 'The lateral grip locates the back and small parts and determines fetal position (e.g., left occiput anterior). Pawlik''s grip determines engagement, and the pelvic grip determines descent and attitude.'),
  ('leopold', 10, 'After identifying the fetal back on the client''s left side, the nurse''s next goal is to determine whether the presenting part of a 38-week fetus is engaged. Where should the nurse place the hands NEXT?', '[{"id": "a", "text": "On the upper abdomen to palpate the fundus"}, {"id": "b", "text": "On both sides of the abdomen at the midsection"}, {"id": "c", "text": "Just above the pubic symphysis"}, {"id": "d", "text": "Over the fetal back to locate the small parts"}]'::jsonb, '["c"]', 'Pawlik''s grip, the third maneuver, grasps the lower abdomen just above the pubic symphysis to determine whether the presenting part is engaged. The upper abdomen and the sides are used in the first and second maneuvers.'),
  ('leopold', 11, 'After the third Leopold maneuver on a client at 39 weeks, a vaginal examination shows that the presenting part has reached the level of the ischial spines. How should the nurse document this finding?', '[{"id": "a", "text": "Station −3, not engaged"}, {"id": "b", "text": "Station +3, crowning"}, {"id": "c", "text": "Station +1, engaged and descending"}, {"id": "d", "text": "Station 0, engaged"}]'::jsonb, '["d"]', 'Engagement means the presenting part has reached the ischial spines, which is station 0. The other stations do not describe the presenting part at the level of the spines.'),
  ('leopold', 12, 'A nursing student is performing the fourth Leopold maneuver on a client at 38 weeks to assess fetal descent and attitude. Which action by the student requires correction?', '[{"id": "a", "text": "Standing at the client''s side while facing her head"}, {"id": "b", "text": "Sliding both hands downward toward the client''s pelvis"}, {"id": "c", "text": "Feeling for the cephalic prominence on each side"}, {"id": "d", "text": "Comparing the prominence to the side of the back"}]'::jsonb, '["a"]', 'For the pelvic grip, the nurse faces the mother''s feet and slides the hands downward to find the cephalic prominence. Facing the client''s head is incorrect for this maneuver.'),
  ('leopold', 13, 'On a client at 38 weeks, the lateral grip shows the fetal back on the client''s left. During the pelvic grip, the nurse feels the cephalic prominence on the client''s right side. How should the nurse interpret this finding?', '[{"id": "a", "text": "The head is extended, which is not the ideal attitude"}, {"id": "b", "text": "The head is flexed, which is the ideal attitude"}, {"id": "c", "text": "The fetus is in a transverse lie across the pelvis"}, {"id": "d", "text": "The presenting part is not yet engaged in the pelvis"}]'::jsonb, '["b"]', 'A cephalic prominence on the side opposite the back means the head is flexed, the ideal attitude. A prominence on the same side as the back indicates an extended head.'),
  ('leopold', 14, 'On the fourth Leopold maneuver for a client at 37 weeks, the nurse finds the cephalic prominence on the same side as the fetal back. Which interpretation of this finding is most accurate?', '[{"id": "a", "text": "The head is well flexed, the ideal attitude"}, {"id": "b", "text": "The fetus is in a breech presentation"}, {"id": "c", "text": "The head is extended, which is not ideal"}, {"id": "d", "text": "The presenting part has reached station 0"}]'::jsonb, '["c"]', 'A cephalic prominence on the same side as the back means the head is extended, which is not ideal. A prominence opposite the back indicates the ideal flexed attitude.'),
  ('leopold', 15, 'After Leopold maneuvers, the nurse tells a client at 38 weeks that her baby has a ''good attitude.'' The client asks what this means. Which response by the nurse is best?', '[{"id": "a", "text": "Your baby is lying parallel to your spine, head or bottom first."}, {"id": "b", "text": "Your baby''s head is the part that will enter your pelvis first."}, {"id": "c", "text": "Your baby''s head has reached the level of your ischial spines."}, {"id": "d", "text": "Your baby''s head is tucked, or flexed, which is the ideal way."}]'::jsonb, '["d"]', 'Attitude is the degree of flexion of the fetal head, and flexed is normal/ideal. Lying parallel describes lie, the part entering the pelvis first describes presentation, and reaching the ischial spines describes engagement.'),
  ('leopold', 16, 'A nurse is teaching a student to perform Leopold maneuvers on a client at 37 weeks. In which order should the student perform the maneuvers?', '[{"id": "a", "text": "Fundal grip, lateral grip, Pawlik''s grip, pelvic grip"}, {"id": "b", "text": "Lateral grip, fundal grip, pelvic grip, Pawlik''s grip"}, {"id": "c", "text": "Pawlik''s grip, fundal grip, lateral grip, pelvic grip"}, {"id": "d", "text": "Fundal grip, Pawlik''s grip, lateral grip, pelvic grip"}]'::jsonb, '["a"]', 'The sequence moves from the fundus (fundal grip), to the midsection (lateral grip), to the lower segment (Pawlik''s grip), to the bottom (pelvic grip). Placing Pawlik''s grip second skips the lateral grip''s assessment of the back.'),
  ('leopold', 17, 'A student uses the phrase ''Feel My Lovely Baby'' to remember the order of Leopold maneuvers before assessing a client at 37 weeks. Which student statement about the phrase requires correction?', '[{"id": "a", "text": "''Feel'' reminds me to palpate the fundus first."}, {"id": "b", "text": "''My'' reminds me to grasp just above the pubic symphysis."}, {"id": "c", "text": "''Lovely'' reminds me to assess the lower segment third."}, {"id": "d", "text": "''Baby'' reminds me to finish at the bottom with the pelvic grip."}]'::jsonb, '["b"]', 'In ''Feel My Lovely Baby,'' ''My'' stands for the midsection (lateral grip, 2nd); grasping just above the pubic symphysis is Pawlik''s grip, the lower segment (3rd). The other statements match the mnemonic.'),
  ('leopold', 18, 'On Leopold maneuvers for a client at 38 weeks, the nurse feels a soft, irregular part in the fundus and confirms a round, firm part just above the symphysis pubis. Which documentation is most accurate?', '[{"id": "a", "text": "Transverse lie, cephalic presentation"}, {"id": "b", "text": "Longitudinal lie, breech presentation"}, {"id": "c", "text": "Longitudinal lie, cephalic presentation"}, {"id": "d", "text": "Transverse lie, breech presentation"}]'::jsonb, '["c"]', 'Buttocks in the fundus and the head above the symphysis mean the fetus lies parallel to the mother (longitudinal) with the head entering the pelvis first (cephalic). A transverse lie is sideways.'),
  ('leopold', 19, 'During Leopold maneuvers at 37 weeks, the nurse finds neither the head nor the buttocks in the fundus or above the symphysis pubis. Instead, a round, firm part is felt on one side of the abdomen and a softer, irregular part on the other. Which fetal lie is most likely?', '[{"id": "a", "text": "Longitudinal lie with cephalic presentation"}, {"id": "b", "text": "Longitudinal lie with breech presentation"}, {"id": "c", "text": "Longitudinal lie with an extended head"}, {"id": "d", "text": "Transverse lie across the abdomen"}]'::jsonb, '["d"]', 'With the head on one side and the buttocks on the other, the fetus is lying sideways, a transverse lie. A longitudinal lie places the fetus parallel, with the head or buttocks at the fundus and pelvis.'),
  ('leopold', 20, 'During Pawlik''s grip, the nurse grasps the lower abdomen just above the symphysis pubis of a client at 38 weeks and feels a soft, irregular part. Which conclusion is best supported?', '[{"id": "a", "text": "The buttocks are presenting, a breech presentation"}, {"id": "b", "text": "The head is presenting, so this is a cephalic presentation"}, {"id": "c", "text": "The head is extended, an abnormal attitude"}, {"id": "d", "text": "The fetus is lying sideways, a transverse lie"}]'::jsonb, '["a"]', 'Pawlik''s grip confirms presentation (head or buttocks); a soft, irregular part just above the symphysis is the buttocks, so the presentation is breech. The head would feel round and firm.'),
  ('leopold', 21, 'On the fundal grip of a client at 37 weeks, the nurse feels a round, firm part that moves independently. Which finding during Pawlik''s grip would BEST confirm the presentation suggested by this finding?', '[{"id": "a", "text": "A round, firm part just above the symphysis pubis"}, {"id": "b", "text": "A soft, irregular part just above the symphysis pubis"}, {"id": "c", "text": "A smooth, firm surface along one side of the abdomen"}, {"id": "d", "text": "Small, irregular parts along one side of the abdomen"}]'::jsonb, '["b"]', 'The head in the fundus suggests breech, so Pawlik''s grip should confirm softer, irregular buttocks above the symphysis. A smooth, firm surface and small parts are lateral-grip findings of the back and extremities.'),
  ('leopold', 22, 'While palpating a client at 37 weeks, the nurse is trying to decide whether the part felt in the fundus is the fetal head. Which characteristic BEST indicates that it is the head?', '[{"id": "a", "text": "It feels softer and more irregular in shape"}, {"id": "b", "text": "It feels smooth, firm, and continuous along a side"}, {"id": "c", "text": "It feels round and firm and moves independently"}, {"id": "d", "text": "It feels like small, knobby parts that move often"}]'::jsonb, '["c"]', 'The head is round, firm, and moves independently. A softer, irregular part is the buttocks, a smooth, firm continuous surface is the back, and small parts are hands and feet.'),
  ('leopold', 23, 'A client at 38 weeks is having the second Leopold maneuver. Which palpation finding should the nurse recognize as the fetal back?', '[{"id": "a", "text": "Small, irregular parts that shift under the hand"}, {"id": "b", "text": "A soft, irregular mass high in the upper abdomen"}, {"id": "c", "text": "A round, firm part that moves independently"}, {"id": "d", "text": "A smooth, firm surface along one side"}]'::jsonb, '["d"]', 'In the lateral grip, one hand feels the smooth, firm back while the other detects small parts such as hands and feet. A round, firm, independently movable part is the head.'),
  ('leopold', 24, 'As the nurse places one hand on each side of a 37-week client''s abdomen and presses gently, the client asks what the nurse is checking for. Which response by the nurse is best?', '[{"id": "a", "text": "Which side your baby''s back is on, to tell the baby''s position."}, {"id": "b", "text": "Whether the baby''s head has settled down into your pelvis yet."}, {"id": "c", "text": "Whether the head or the bottom is at the top of your uterus."}, {"id": "d", "text": "How well your baby''s head is tucked down toward the baby''s chest."}]'::jsonb, '["a"]', 'The lateral grip finds the smooth back on one side and small parts on the other to determine fetal position. Engagement is assessed with Pawlik''s grip, fundal contents with the fundal grip, and head flexion with the pelvic grip.'),
  ('leopold', 25, 'After Leopold maneuvers, the nurse documents the fetal position of a 38-week fetus as LOA. The client asks what ''position'' means. Which explanation by the nurse is best?', '[{"id": "a", "text": "It describes which part of the baby will enter the pelvis first."}, {"id": "b", "text": "It describes which direction your baby is facing in the uterus."}, {"id": "c", "text": "It describes how much your baby''s head is bent toward its chest."}, {"id": "d", "text": "It describes whether your baby lies parallel or sideways to you."}]'::jsonb, '["b"]', 'Position is the direction the baby faces (e.g., LOA = Left Occiput Anterior). The part entering the pelvis first is presentation, head flexion is attitude, and parallel versus sideways is lie.'),
  ('leopold', 26, 'A client at 38 weeks asks if her baby has ''engaged'' yet. A vaginal exam shows the presenting part has not yet reached the ischial spines. Which response by the nurse is most accurate?', '[{"id": "a", "text": "Yes, your baby is engaged at station 0 now."}, {"id": "b", "text": "Yes, the head is flexed, so it is engaged."}, {"id": "c", "text": "Not yet; engagement is when it reaches station 0."}, {"id": "d", "text": "Not yet; engagement is when the head is crowning."}]'::jsonb, '["c"]', 'Engagement occurs when the presenting part reaches the ischial spines, which is station 0; this presenting part has not reached them. Flexion describes attitude, not engagement.'),
  ('leopold', 27, 'The nurse has determined fetal presentation, position, and engagement on a client at 37 weeks. To assess fetal descent and the attitude of the head, which maneuver should the nurse perform NEXT?', '[{"id": "a", "text": "Fundal grip"}, {"id": "b", "text": "Lateral grip"}, {"id": "c", "text": "Pawlik''s grip"}, {"id": "d", "text": "Pelvic grip"}]'::jsonb, '["d"]', 'The fourth maneuver, the pelvic grip, determines fetal descent and attitude. Pawlik''s grip determines engagement, which has already been assessed.'),
  ('leopold', 28, 'The nurse has just completed Pawlik''s grip on a client at 38 weeks and found the presenting part engaged. How should the nurse perform the NEXT maneuver?', '[{"id": "a", "text": "Face the client''s feet and slide the hands downward"}, {"id": "b", "text": "Grasp the lower abdomen just above the pubic symphysis"}, {"id": "c", "text": "Place both hands on the sides of the client''s abdomen"}, {"id": "d", "text": "Palpate the upper abdomen to identify the fundal part"}]'::jsonb, '["a"]', 'After Pawlik''s grip (3rd), the pelvic grip (4th) is performed by facing the mother''s feet and sliding the hands downward to find the cephalic prominence. Grasping above the symphysis is Pawlik''s grip itself.'),
  ('leopold', 29, 'A nurse asks an unlicensed assistive personnel (UAP) to prepare a client at 37 weeks for Leopold maneuvers. Which instruction by the nurse is best?', '[{"id": "a", "text": "Have her lie on her left side with her legs straight."}, {"id": "b", "text": "Have her void, then lie supine with knees slightly bent."}, {"id": "c", "text": "Have her sit upright with a full bladder for better views."}, {"id": "d", "text": "Have her lie supine with legs straight after she voids."}]'::jsonb, '["b"]', 'The client should empty her bladder first and lie supine with knees slightly flexed. Lying with legs straight or keeping a full bladder does not match the preparation.'),
  ('leopold', 30, 'The nurse completes Leopold maneuvers on four clients at 37 to 39 weeks. Which finding requires the nurse''s follow-up because it is not ideal?', '[{"id": "a", "text": "Soft, irregular buttocks palpated in the uterine fundus"}, {"id": "b", "text": "Cephalic prominence opposite the fetal back"}, {"id": "c", "text": "Cephalic prominence on the same side as the back"}, {"id": "d", "text": "Smooth, firm back palpated along the left side"}]'::jsonb, '["c"]', 'A cephalic prominence on the same side as the back means the head is extended, which is not ideal. A prominence opposite the back means the head is flexed (ideal), and buttocks in the fundus indicate a cephalic presentation.'),
  ('leopold', 31, 'A nursing student assessing a client at 38 weeks says, ''To find out whether the presenting part is engaged, I will face the client''s feet and slide my hands down toward the pelvis.'' Which response by the instructor is best?', '[{"id": "a", "text": "Correct; the pelvic grip is how engagement is determined."}, {"id": "b", "text": "Correct; facing the feet also confirms the fetal position."}, {"id": "c", "text": "Incorrect; engagement is found with the lateral grip."}, {"id": "d", "text": "Incorrect; engagement is found with Pawlik''s grip."}]'::jsonb, '["d"]', 'Pawlik''s grip, grasping the lower abdomen just above the pubic symphysis, determines engagement. The pelvic grip (facing the feet) determines descent and attitude, and the lateral grip determines position.'),
  ('leopold', 32, 'During the lateral grip on a client at 37 weeks, the nurse identifies a smooth, firm surface on the client''s left side. Where should the nurse expect to feel the fetal hands and feet?', '[{"id": "a", "text": "On the client''s right side"}, {"id": "b", "text": "In the upper fundus"}, {"id": "c", "text": "Just above the symphysis pubis"}, {"id": "d", "text": "Along the client''s left side"}]'::jsonb, '["a"]', 'In the lateral grip, one hand feels the smooth, firm back and the other hand detects the small parts (hands, feet), so the extremities lie on the side opposite the back.'),
  ('leopold', 33, 'On a client at 38 weeks, the lateral grip shows the fetal back along the client''s right side. If the fetal head is well flexed, where should the nurse expect to feel the cephalic prominence during the pelvic grip?', '[{"id": "a", "text": "On the client''s right side"}, {"id": "b", "text": "On the client''s left side"}, {"id": "c", "text": "Centered above the umbilicus"}, {"id": "d", "text": "High in the uterine fundus"}]'::jsonb, '["b"]', 'When the head is flexed (ideal), the cephalic prominence is on the side opposite the back; with the back on the right, it is felt on the left. A prominence on the same side as the back would mean an extended head.'),
  ('leopold', 34, 'On a client at 38 weeks, the lateral grip locates the fetal back on the client''s left side, and the pelvic grip locates the cephalic prominence on the client''s left side as well. Which conclusion is best?', '[{"id": "a", "text": "The head is flexed, which is the ideal attitude"}, {"id": "b", "text": "The fetus is lying in a transverse position"}, {"id": "c", "text": "The head is extended, which is not ideal"}, {"id": "d", "text": "The presenting part has not yet engaged"}]'::jsonb, '["c"]', 'A cephalic prominence on the same side as the back indicates an extended head, which is not ideal. A flexed head would place the prominence on the side opposite the back.'),
  ('leopold', 35, 'A client at 39 weeks says her provider mentioned checking whether the baby is engaged, and she asks the nurse to check. Which Leopold maneuver should the nurse use to best answer her question?', '[{"id": "a", "text": "Fundal grip of the upper abdomen"}, {"id": "b", "text": "Lateral grip of the abdominal sides"}, {"id": "c", "text": "Pelvic grip while facing the feet"}, {"id": "d", "text": "Pawlik''s grip above the symphysis"}]'::jsonb, '["d"]', 'Pawlik''s grip, just above the pubic symphysis, determines whether the presenting part is engaged. The pelvic grip assesses descent and attitude, and the fundal and lateral grips assess presentation and position.'),
  ('leopold', 36, 'After Leopold maneuvers, the nurse tells a client at 37 weeks that her baby is in a longitudinal lie. The client asks what this means. Which response by the nurse is best?', '[{"id": "a", "text": "Your baby is lying parallel to your body, lengthwise."}, {"id": "b", "text": "Your baby is lying sideways, across the width of your abdomen."}, {"id": "c", "text": "Your baby''s bottom will be the first part delivered."}, {"id": "d", "text": "Your baby''s head is tucked down toward the chest."}]'::jsonb, '["a"]', 'A longitudinal lie means the fetus is parallel to the mother, while a transverse lie is sideways. The part delivered first describes presentation, and head flexion describes attitude.'),
  ('leopold', 37, 'Leopold maneuvers on a client at 37 weeks reveal a round, firm part in the fundus and softer, irregular buttocks above the symphysis pubis. The client asks what this means for her baby. Which explanation by the nurse is best?', '[{"id": "a", "text": "Your baby''s head is down and will enter the pelvis first."}, {"id": "b", "text": "Your baby''s bottom is down and will enter the pelvis first."}, {"id": "c", "text": "Your baby is lying sideways across your uterus at this time."}, {"id": "d", "text": "Your baby''s head is tilted back instead of being tucked."}]'::jsonb, '["b"]', 'With the head in the fundus and the buttocks above the symphysis, the buttocks will enter the pelvis first, a breech presentation. A cephalic presentation would have the head entering first.'),
  ('leopold', 38, 'A nurse has just completed the lateral grip on a client at 37 weeks and located the fetal back on the right side. What should the nurse do NEXT?', '[{"id": "a", "text": "Repeat the fundal grip to recheck the upper abdomen"}, {"id": "b", "text": "Face the client''s feet and slide hands toward the pelvis"}, {"id": "c", "text": "Grasp the lower abdomen just above the pubic symphysis"}, {"id": "d", "text": "Have the client void before continuing the assessment"}]'::jsonb, '["c"]', 'After the lateral grip (2nd), Pawlik''s grip (3rd) grasps the lower abdomen just above the pubic symphysis to determine engagement. Facing the feet is the pelvic grip, which comes last, and the bladder is emptied before starting.'),
  ('leopold', 39, 'The nurse is beginning Leopold maneuvers on a client at 38 weeks who has emptied her bladder and is positioned correctly with knees slightly flexed. Where should the nurse place the hands FIRST?', '[{"id": "a", "text": "On both sides of the abdomen to locate the back"}, {"id": "b", "text": "Just above the pubic symphysis to assess engagement"}, {"id": "c", "text": "Facing the client''s feet to find the cephalic prominence"}, {"id": "d", "text": "On the upper abdomen to identify the fundal contents"}]'::jsonb, '["d"]', 'The first maneuver, the fundal grip, palpates the upper abdomen to identify what is in the fundus. Locating the back is the second maneuver, and assessing engagement is the third.'),
  ('leopold', 40, 'The nurse has positioned a client at 37 weeks supine with her knees slightly flexed and has warmed both hands. Before palpation begins, the client says she needs to urinate. What is the nurse''s best action?', '[{"id": "a", "text": "Have her void, then reposition her and begin"}, {"id": "b", "text": "Begin quickly with the fundal grip, then let her void"}, {"id": "c", "text": "Perform only the lateral and pelvic grips for now"}, {"id": "d", "text": "Elevate the head of the bed to relieve her urge"}]'::jsonb, '["a"]', 'The bladder should be emptied before Leopold maneuvers begin, so the client voids and is then repositioned supine with knees slightly flexed. Starting palpation with a full bladder skips this preparation.'),
  ('leopold', 41, 'A nursing student reviews the purpose of each Leopold maneuver before assessing a client at 37 weeks. Which student statement requires correction?', '[{"id": "a", "text": "The pelvic grip helps me assess descent and head flexion."}, {"id": "b", "text": "The lateral grip tells me whether the head is engaged."}, {"id": "c", "text": "Pawlik''s grip helps confirm whether the head or buttocks presents."}, {"id": "d", "text": "The fundal grip shows whether the fetus is cephalic or breech."}]'::jsonb, '["b"]', 'Engagement is determined with Pawlik''s grip; the lateral grip locates the back and small parts to determine position. The other statements are correct.'),
  ('leopold', 42, 'A client at 37 weeks whose previous baby was breech wants to know whether this baby is head-down. Which maneuver should the nurse begin with to gather this information?', '[{"id": "a", "text": "Lateral grip"}, {"id": "b", "text": "Pelvic grip"}, {"id": "c", "text": "Fundal grip"}, {"id": "d", "text": "Pawlik''s grip"}]'::jsonb, '["c"]', 'The fundal grip is performed first and determines presentation (cephalic vs breech) by identifying the part in the fundus. Pawlik''s grip later confirms presentation, but it is not the starting maneuver.'),
  ('leopold', 43, 'Leopold maneuvers on a client at 38 weeks reveal soft, irregular buttocks in the fundus, the fetal back on the left, the cephalic prominence on the right, and a presenting part at station 0. Which documentation is most accurate?', '[{"id": "a", "text": "Breech presentation, flexed attitude, engaged"}, {"id": "b", "text": "Cephalic presentation, extended attitude, engaged"}, {"id": "c", "text": "Cephalic presentation, flexed attitude, not engaged"}, {"id": "d", "text": "Cephalic presentation, flexed attitude, engaged"}]'::jsonb, '["d"]', 'Buttocks in the fundus mean a cephalic presentation, a prominence opposite the back means a flexed head, and station 0 means engaged. A prominence on the same side as the back would mean an extended head.'),
  ('leopold', 44, 'Leopold maneuvers on a client at 36 weeks reveal a round, firm, independently movable part in the fundus and a soft, irregular part above the symphysis pubis. Which documentation is most accurate?', '[{"id": "a", "text": "Longitudinal lie, breech presentation"}, {"id": "b", "text": "Transverse lie, breech presentation"}, {"id": "c", "text": "Longitudinal lie, cephalic presentation"}, {"id": "d", "text": "Transverse lie, cephalic presentation"}]'::jsonb, '["a"]', 'With the head in the fundus and buttocks above the symphysis, the fetus is parallel to the mother (longitudinal) with the buttocks entering the pelvis first (breech). A transverse lie would be sideways.'),
  ('leopold', 45, 'The fundal grip suggests that a client''s 37-week fetus is breech, and the nurse has completed the lateral grip. Which maneuver performed next will help confirm the presentation?', '[{"id": "a", "text": "Pelvic grip"}, {"id": "b", "text": "Pawlik''s grip"}, {"id": "c", "text": "Fundal grip"}, {"id": "d", "text": "Vaginal exam for station"}]'::jsonb, '["b"]', 'Pawlik''s grip, the third maneuver, determines engagement and confirms presentation (head or buttocks). The pelvic grip assesses descent and attitude, and repeating the fundal grip does not confirm what is entering the pelvis.'),
  ('leopold', 46, 'A nurse is documenting the results of each Leopold maneuver separately for a client at 37 weeks. Which finding should be recorded as the result of the second maneuver?', '[{"id": "a", "text": "Whether the presenting part has reached station 0"}, {"id": "b", "text": "Whether the fetal head is flexed or extended"}, {"id": "c", "text": "Which side of the abdomen the fetal back lies on"}, {"id": "d", "text": "Whether the presenting part is the head or buttocks"}]'::jsonb, '["c"]', 'The second (lateral) maneuver finds the smooth, firm back on one side and small parts on the other, determining position. Engagement is the third maneuver, attitude the fourth, and presentation the first.'),
  ('leopold', 47, 'After Leopold maneuvers and a vaginal exam, the nurse tells a client at 39 weeks that her baby is ''engaged.'' Which client statement indicates correct understanding?', '[{"id": "a", "text": "My baby''s head is tucked down against its chest now."}, {"id": "b", "text": "My baby is lying lengthwise in my uterus rather than sideways."}, {"id": "c", "text": "My baby''s head is crowning and birth is minutes away."}, {"id": "d", "text": "My baby''s presenting part is down at my ischial spines."}]'::jsonb, '["d"]', 'Engagement means the presenting part has reached the ischial spines (station 0). A tucked head describes a flexed attitude, and lying lengthwise describes a longitudinal lie.'),
  ('leopold', 48, 'A client at 37 weeks is lying on her left side when the nurse arrives to perform Leopold maneuvers. She has already emptied her bladder. What should the nurse do FIRST?', '[{"id": "a", "text": "Help her turn supine with her knees slightly flexed"}, {"id": "b", "text": "Begin the fundal grip while she stays on her left side"}, {"id": "c", "text": "Ask her to straighten her legs fully on her left side"}, {"id": "d", "text": "Raise the head of the bed to a high-Fowler''s position"}]'::jsonb, '["a"]', 'After the bladder is emptied, the client is positioned supine with knees slightly flexed before palpation begins. Starting the fundal grip in a side-lying position skips correct positioning.'),
  ('leopold', 49, 'During the first Leopold maneuver on a client at 38 weeks, the client asks why the nurse is feeling the top of her abdomen. Which response by the nurse is best?', '[{"id": "a", "text": "To find which side your baby''s back is on."}, {"id": "b", "text": "To tell whether the head or bottom is up there."}, {"id": "c", "text": "To check whether the baby has engaged in the pelvis."}, {"id": "d", "text": "To see how well the baby''s head is tucked down."}]'::jsonb, '["b"]', 'The fundal grip identifies what is in the fundus (head or buttocks) to determine presentation. The back is located with the lateral grip, engagement with Pawlik''s grip, and flexion with the pelvic grip.'),
  ('leopold', 50, 'The nurse is about to begin Leopold maneuvers on a client at 38 weeks who has voided and is positioned supine with knees slightly flexed. The nurse''s hands are cold from the hallway. Which action is best?', '[{"id": "a", "text": "Begin promptly so the client is not kept waiting"}, {"id": "b", "text": "Wear gloves so the cold hands are not noticed"}, {"id": "c", "text": "Warm the hands before touching the abdomen"}, {"id": "d", "text": "Palpate lightly to limit the client''s discomfort"}]'::jsonb, '["c"]', 'Preparation for Leopold maneuvers includes emptying the bladder, supine positioning with knees slightly flexed, and using warm hands. Starting with cold hands skips this step.'),
  ('meds', 1, 'A client whose first pregnancy was affected by spina bifida tells the nurse she hopes to conceive within the next 3 months. She currently takes an over-the-counter prenatal vitamin containing 800 mcg of folic acid daily. Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "Your dose is already at the top of the recommended range, so no change is needed."}, {"id": "b", "text": "Your provider will likely recommend 4 mg of folic acid daily before you conceive."}, {"id": "c", "text": "Keep your current dose for now, then increase it once a pregnancy test is positive."}, {"id": "d", "text": "Take your vitamin with a glass of milk at breakfast to improve folic acid absorption."}]'::jsonb, '["b"]', 'A prior neural tube defect raises the folic acid dose to 4 mg/day, and supplementation should start before conception. 800 mcg is the top of the standard range only for clients without that history, and waiting for a positive test misses the preconception start.'),
  ('meds', 2, 'During a preconception visit, a 28-year-old with no personal or family history of neural tube defects asks about folic acid. She plans to stop using contraception next month. Which statement by the client indicates correct understanding of the teaching?', '[{"id": "a", "text": "I''ll take 4 mg daily, starting as soon as my pregnancy test turns positive."}, {"id": "b", "text": "I''ll take 400 mcg daily, starting at my first prenatal appointment."}, {"id": "c", "text": "I''ll take 4 mg daily, starting now, because a higher dose protects the baby more."}, {"id": "d", "text": "I''ll take 400 mcg daily, starting now, before I begin trying to conceive."}]'::jsonb, '["d"]', 'Without a prior NTD, the dose is 400–800 mcg/day and it should begin before conception. The 4 mg/day dose is reserved for clients with a prior NTD history, and starting at the first prenatal visit is too late.'),
  ('meds', 3, 'A client at 24 weeks'' gestation has been diagnosed with anemia and is started on an oral iron supplement. She also uses a calcium carbonate antacid for heartburn. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I''ll take my iron tablet together with my antacid and a glass of milk."}, {"id": "b", "text": "I''ll take my iron tablet with a glass of orange juice to help it absorb."}, {"id": "c", "text": "I''ll wait at least 2 hours after my iron dose before I take my antacid."}, {"id": "d", "text": "I''ll keep my afternoon yogurt snack at least 2 hours away from my iron dose."}]'::jsonb, '["a"]', 'Dairy and antacids should be kept at least 2 hours away from iron, so taking them together needs correction. Taking iron with vitamin C (orange juice) boosts absorption and is correct.'),
  ('meds', 4, 'A client at 33 weeks'' gestation calls the prenatal clinic and reports she has been taking ibuprofen 400 mg three times daily for 4 days for a sprained ankle. When reporting this to the provider, the nurse identifies which fetal complication as the MOST significant concern?', '[{"id": "a", "text": "Fetal hemorrhage from impaired clotting"}, {"id": "b", "text": "A neural tube defect of the spinal cord"}, {"id": "c", "text": "Premature closure of the ductus arteriosus"}, {"id": "d", "text": "Tooth discoloration and slowed bone growth"}]'::jsonb, '["c"]', 'NSAIDs such as ibuprofen in the third trimester (avoid after 30 weeks) can close the ductus arteriosus prematurely. Fetal hemorrhage is linked to warfarin, neural tube defects to valproate and methotrexate, and tooth discoloration to tetracyclines.'),
  ('meds', 5, 'A nurse at a prenatal clinic is reviewing four voicemail messages from clients about over-the-counter medication use. Which client''s report requires the nurse''s immediate follow-up?', '[{"id": "a", "text": "A client at 16 weeks taking acetaminophen 500 mg every 6 hours for low back pain"}, {"id": "b", "text": "A client at 12 weeks taking doxylamine with vitamin B6 at bedtime for morning nausea"}, {"id": "c", "text": "A client at 28 weeks taking her iron tablet with orange juice every morning"}, {"id": "d", "text": "A client at 31 weeks taking ibuprofen twice daily for 3 days for headaches"}]'::jsonb, '["d"]', 'Ibuprofen should be avoided after 30 weeks because it can close the ductus arteriosus prematurely. Acetaminophen 2 g/day is below the 3 g/day limit, doxylamine-B6 is first-line for nausea, and iron with vitamin C is correct.'),
  ('meds', 6, 'A client at 22 weeks'' gestation with a toothache reports taking extra-strength acetaminophen 1,000 mg every 4 hours while awake, about 5 doses each day, for the past 3 days. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Reinforce that acetaminophen is the preferred analgesic, so the regimen may continue."}, {"id": "b", "text": "Advise her to switch to ibuprofen, which is the stronger choice before 30 weeks."}, {"id": "c", "text": "Notify the provider that her daily intake exceeds the recommended maximum."}, {"id": "d", "text": "Suggest she take each acetaminophen dose with food to limit stomach upset."}]'::jsonb, '["c"]', 'Five 1,000-mg doses equal 5 g/day, which exceeds the 3 g/day maximum, so the provider must be notified. Acetaminophen is the preferred analgesic, but not at this dose, and OTC changes such as ibuprofen require provider approval.'),
  ('meds', 7, 'A client at 29 weeks'' gestation with gestational diabetes has fasting glucose values that stay elevated despite diet changes, and the provider plans to start insulin. The client says, ''I''d rather take a pill, because the shots will go straight to my baby.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Pills are preferred in pregnancy because, unlike insulin, they stay in your bloodstream."}, {"id": "b", "text": "Insulin does not cross the placenta and is preferred over pills for gestational diabetes."}, {"id": "c", "text": "Insulin does reach the baby, but the amount is too small to lower the baby''s sugar."}, {"id": "d", "text": "Pills are avoided because metformin is Category X at every stage of pregnancy."}]'::jsonb, '["b"]', 'Insulin does not cross the placenta and is preferred over oral agents for GDM requiring medication. Metformin is Category B and is used by some providers, so calling it Category X is incorrect.'),
  ('meds', 8, 'A client with a seizure disorder that is well controlled on valproate (Depakote) calls the clinic after a positive home pregnancy test; her last menstrual period began 5 weeks ago. The nurse arranges an urgent provider visit because this drug is associated with which fetal effect?', '[{"id": "a", "text": "Spina bifida and later cognitive impairment"}, {"id": "b", "text": "Fetal renal damage with low amniotic fluid"}, {"id": "c", "text": "Fetal hemorrhage and drug embryopathy"}, {"id": "d", "text": "Tooth discoloration and inhibited bone growth"}]'::jsonb, '["a"]', 'Valproate (Category D) causes neural tube defects such as spina bifida and cognitive impairment. Renal damage with oligohydramnios belongs to ACE inhibitors, hemorrhage and embryopathy to warfarin, and tooth discoloration to tetracyclines.'),
  ('meds', 9, 'A 19-year-old taking isotretinoin (Accutane) for severe nodular acne tells the clinic nurse that her period is 2 weeks late and a home pregnancy test this morning was positive. What is the nurse''s PRIORITY action?', '[{"id": "a", "text": "Instruct her to take no further doses and notify the prescriber right away."}, {"id": "b", "text": "Reduce her dose to every other day until the prescriber can see her."}, {"id": "c", "text": "Start folic acid 4 mg daily to offset the drug''s effect on the embryo."}, {"id": "d", "text": "Schedule a routine first prenatal visit and continue the acne regimen."}]'::jsonb, '["a"]', 'Isotretinoin is Category X, a severe teratogen causing craniofacial, cardiac, and CNS defects, so exposure must stop and the prescriber be notified. Dose reduction or folic acid does not make a contraindicated drug acceptable.'),
  ('meds', 10, 'A client who takes warfarin (Coumadin) for a history of recurrent venous clots has a positive pregnancy test at 6 weeks'' gestation. Which change in her anticoagulation plan is MOST appropriate for the nurse to anticipate?', '[{"id": "a", "text": "Continue warfarin through the first trimester, then change agents."}, {"id": "b", "text": "Stop warfarin and change the anticoagulant therapy to heparin."}, {"id": "c", "text": "Stop all anticoagulant therapy until after the baby is delivered."}, {"id": "d", "text": "Replace warfarin with daily low-dose aspirin for the pregnancy."}]'::jsonb, '["b"]', 'Warfarin is Category X, causing fetal hemorrhage and warfarin embryopathy in the first trimester, so heparin is used instead during pregnancy. Continuing it through the first trimester exposes the embryo during the highest-risk period.'),
  ('meds', 11, 'At a preconception clinic, the nurse reviews the medication lists of four clients who each plan to conceive within the next few months. Which client requires the MOST urgent follow-up with the provider?', '[{"id": "a", "text": "A client taking low-dose aspirin as prescribed for a history of preeclampsia"}, {"id": "b", "text": "A client taking metformin as prescribed for type 2 diabetes mellitus"}, {"id": "c", "text": "A client taking weekly methotrexate for rheumatoid arthritis"}, {"id": "d", "text": "A client taking fluconazole as prescribed for a vaginal yeast infection"}]'::jsonb, '["c"]', 'Methotrexate is Category X: a folic acid antagonist that causes neural tube defects and embryo death. Low-dose aspirin and fluconazole are Category C and metformin is Category B, so they do not carry the same absolute contraindication.'),
  ('meds', 12, 'A nurse in a prenatal clinic is reviewing new prescriptions written for four clients who are in the second trimester. Which prescription should the nurse question before it is filled?', '[{"id": "a", "text": "Penicillin for a bacterial infection in a client at 20 weeks"}, {"id": "b", "text": "Metronidazole for bacterial vaginosis in a client at 24 weeks"}, {"id": "c", "text": "Ondansetron for hyperemesis unrelieved by conservative measures at 16 weeks"}, {"id": "d", "text": "Tetracycline for an acne flare in a client at 22 weeks"}]'::jsonb, '["d"]', 'Tetracyclines are Category D, causing tooth discoloration and inhibition of fetal bone growth. Penicillin is Category B, metronidazole is used after the first trimester, and ondansetron is used when conservative measures fail.'),
  ('meds', 13, 'A client with chronic hypertension who continued taking lisinopril after conception is now at 26 weeks'' gestation. A routine ultrasound shows a decreased amniotic fluid volume. The nurse recognizes this finding is MOST likely explained by which mechanism?', '[{"id": "a", "text": "Premature closure of the fetal ductus arteriosus"}, {"id": "b", "text": "Fetal renal damage caused by the ACE inhibitor"}, {"id": "c", "text": "Folic acid antagonism impairing neural tube closure"}, {"id": "d", "text": "Fetal hemorrhage from impaired clotting factors"}]'::jsonb, '["b"]', 'ACE inhibitors in the 2nd/3rd trimester cause fetal renal damage and oligohydramnios. Ductus arteriosus closure is an NSAID effect, folic acid antagonism is methotrexate, and fetal hemorrhage is warfarin.'),
  ('meds', 14, 'A client at 22 weeks'' gestation is seen during influenza season. She is due for her immunizations and asks for the ''easiest'' flu vaccine because she strongly dislikes needles. Which order should the nurse question?', '[{"id": "a", "text": "Inactivated influenza vaccine by intramuscular injection"}, {"id": "b", "text": "Tdap vaccine by intramuscular injection"}, {"id": "c", "text": "Live attenuated influenza vaccine by nasal spray"}, {"id": "d", "text": "Acetaminophen orally as needed for arm soreness"}]'::jsonb, '["c"]', 'Live vaccines, including the nasal flu vaccine, are contraindicated in pregnancy because of the risk of fetal infection. The inactivated flu shot and Tdap are safe and recommended, and acetaminophen is the preferred analgesic.'),
  ('meds', 15, 'A client at 31 weeks'' gestation tells the nurse she has been drinking an herbal blend containing black cohosh every day for a week. Today she reports abdominal tightening every 8 to 10 minutes and low back pressure. Which assessment is the nurse''s PRIORITY?', '[{"id": "a", "text": "Monitor the uterine contraction pattern for signs of preterm labor"}, {"id": "b", "text": "Assess the fetal heart for signs of premature ductus closure"}, {"id": "c", "text": "Review her supplement list for high-dose vitamin A products"}, {"id": "d", "text": "Check her blood pressure for drug-induced vasoconstriction"}]'::jsonb, '["a"]', 'Black cohosh and blue cohosh can stimulate labor, and her regular tightening at 31 weeks suggests preterm labor. Ductus closure is an NSAID concern and vasoconstriction is a methylergonovine effect.'),
  ('meds', 16, 'A client at 8 weeks'' gestation brings her supplements to the first prenatal visit: a prenatal vitamin with 600 mcg folic acid, an iron tablet she takes with juice, a doxylamine-B6 tablet at bedtime, and a retinol capsule containing a large dose of vitamin A ''for her skin.'' Which product requires the nurse''s immediate follow-up?', '[{"id": "a", "text": "The prenatal vitamin with 600 mcg of folic acid"}, {"id": "b", "text": "The iron tablet taken each morning with juice"}, {"id": "c", "text": "The doxylamine-B6 tablet taken at bedtime"}, {"id": "d", "text": "The retinol capsule taken for her skin"}]'::jsonb, '["d"]', 'High-dose vitamin A (retinol) is teratogenic in large amounts and should be avoided. Folic acid 600 mcg is within the 400–800 mcg range, iron with vitamin C is correct, and doxylamine-B6 is first-line for nausea.'),
  ('meds', 17, 'A client at 20 weeks'' gestation is prescribed metronidazole (Flagyl) for trichomoniasis. After the nurse reviews the medication with her, which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I won''t take any over-the-counter medicine without checking with my provider first."}, {"id": "b", "text": "Since I''m past my first trimester, one glass of wine after this course is fine."}, {"id": "c", "text": "I''ll avoid alcohol completely while I''m taking this medicine."}, {"id": "d", "text": "I''ll finish the medicine as prescribed and keep my next prenatal visit."}]'::jsonb, '["b"]', 'There is no safe amount of alcohol in pregnancy, regardless of trimester or finishing metronidazole. Avoiding alcohol during metronidazole treatment and checking before taking OTC drugs are correct.'),
  ('meds', 18, 'A client at 9 weeks'' gestation reports nausea and vomiting most mornings. Small, frequent meals for 2 weeks have given little relief, and the provider plans to begin drug therapy. Which statement by the nurse about the medication plan is accurate?', '[{"id": "a", "text": "Ondansetron is first-line here because it is the strongest antiemetic choice."}, {"id": "b", "text": "Ondansetron is preferred in the first trimester because it has no cardiac concerns."}, {"id": "c", "text": "Ondansetron should be tried first, then doxylamine-B6 if vomiting continues."}, {"id": "d", "text": "Doxylamine with vitamin B6 is the first-line medication for nausea in pregnancy."}]'::jsonb, '["d"]', 'Doxylamine + B6 (Bonjesta) is the first-line pharmacological treatment for nausea in pregnancy. Ondansetron is used when other measures fail and has some first-trimester cardiac concerns, so it is not first-line at 9 weeks.'),
  ('meds', 19, 'A client at 10 weeks'' gestation with persistent vomiting asks for ondansetron (Zofran) because ''it worked great for my sister.'' She has not yet tried any other antiemetic. Which response by the nurse is BEST?', '[{"id": "a", "text": "It''s usually saved for when other measures fail because of some early cardiac concerns."}, {"id": "b", "text": "It''s a Category X drug, so it can''t be prescribed at any time during pregnancy."}, {"id": "c", "text": "It''s the first-line drug for nausea, so your provider will likely start it today."}, {"id": "d", "text": "It''s equally safe in every trimester, so the choice depends on your preference."}]'::jsonb, '["a"]', 'Ondansetron is used when conservative measures fail and carries some first-trimester cardiac concerns, so it is used carefully. It is not Category X (it is listed as B with caution), and doxylamine-B6 is first-line.'),
  ('meds', 20, 'A client with severe preeclampsia has been receiving IV magnesium sulfate for 10 hours. The nurse finds her drowsy with absent patellar reflexes, a respiratory rate of 9/min, and 30 mL of urine in the past 2 hours. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Administer calcium gluconate IV"}, {"id": "b", "text": "Stop the magnesium sulfate infusion"}, {"id": "c", "text": "Notify the provider of the findings"}, {"id": "d", "text": "Reassess the reflexes in 15 minutes"}]'::jsonb, '["b"]', 'Absent reflexes, RR below 12, and urine below 25 mL/hr (here 15 mL/hr) indicate magnesium toxicity; the first step is to stop the infusion, then give calcium gluconate. Giving the antidote while magnesium keeps infusing reverses the order.'),
  ('meds', 21, 'A nurse is completing the hourly assessment of a client at 35 weeks'' gestation who is receiving magnesium sulfate for seizure prophylaxis after a diagnosis of preeclampsia. Which finding requires the nurse''s immediate follow-up?', '[{"id": "a", "text": "Respiratory rate of 12 breaths/min"}, {"id": "b", "text": "Patellar reflexes present at 2+ bilaterally"}, {"id": "c", "text": "Urine output of 20 mL in the past hour"}, {"id": "d", "text": "Urine output of 45 mL in the past hour"}]'::jsonb, '["c"]', 'Urine output must be at least 25 mL/hr during magnesium therapy, so 20 mL/hr needs follow-up. A respiratory rate of 12 meets the ≥12 requirement, and present reflexes are expected.'),
  ('meds', 22, 'A client at 31 weeks'' gestation in preterm labor receives an IM injection of betamethasone. Her partner asks, ''Why is she getting a shot when the problem is that the baby is coming early?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "It is given to the mother to help mature the baby''s lungs before birth."}, {"id": "b", "text": "It relaxes the uterus so that the contractions slow down and labor stops."}, {"id": "c", "text": "It protects the mother from seizures while she is in preterm labor."}, {"id": "d", "text": "It keeps the mother from forming antibodies against the baby''s blood."}]'::jsonb, '["a"]', 'Betamethasone is given IM to the mother to promote fetal lung maturity before preterm delivery. Relaxing the uterus describes tocolytics such as terbutaline, seizure prevention describes magnesium, and antibody prevention describes RhoGAM.'),
  ('meds', 23, 'A nurse on the antepartum unit reviews four clients. Based on gestational age and the expected timing of birth, for which client does the nurse anticipate an order for betamethasone?', '[{"id": "a", "text": "A client at 38 weeks scheduled for induction tomorrow morning"}, {"id": "b", "text": "A client at 32 weeks in preterm labor expected to deliver within 2 days"}, {"id": "c", "text": "A client 1 day postpartum after giving birth at 33 weeks'' gestation"}, {"id": "d", "text": "A client at 22 weeks admitted for observation of persistent vomiting"}]'::jsonb, '["b"]', 'Betamethasone is given to the mother 24–48 hours before an anticipated preterm delivery between 24 and 34 weeks. The 38-week and 22-week clients fall outside that range, and the postpartum client has already delivered.'),
  ('meds', 24, 'A client at 40 weeks is receiving an oxytocin infusion for labor induction. The monitor shows 7 contractions in the last 10 minutes, and the fetal heart rate tracing now shows signs of fetal distress. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Turn the client to the left lateral position"}, {"id": "b", "text": "Apply oxygen to the client by face mask"}, {"id": "c", "text": "Notify the provider about the tracing"}, {"id": "d", "text": "Stop the oxytocin infusion"}]'::jsonb, '["d"]', 'More than 5 contractions in 10 minutes is hyperstimulation; the sequence is stop the infusion, turn left lateral, give oxygen, then notify the provider. Repositioning or oxygen while oxytocin continues does not remove the cause.'),
  ('meds', 25, 'Oxytocin was stopped 10 minutes ago for a laboring client with uterine hyperstimulation, but she continues to have 6 contractions every 10 minutes. The provider orders a medication to relieve the hyperstimulation. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Terbutaline"}, {"id": "b", "text": "Methylergonovine (Methergine)"}, {"id": "c", "text": "Dinoprostone (Cervidil)"}, {"id": "d", "text": "Misoprostol (Cytotec)"}]'::jsonb, '["a"]', 'Terbutaline is used for tocolysis and to relieve uterine hyperstimulation. Dinoprostone and misoprostol can themselves cause hyperstimulation, and methylergonovine is used for postpartum hemorrhage.'),
  ('meds', 26, 'A nurse is caring for four postpartum clients with excessive bleeding related to uterine atony. Which medication order should the nurse question before administering it?', '[{"id": "a", "text": "Oxytocin infusion for a client with a boggy fundus and a BP of 118/74 mm Hg"}, {"id": "b", "text": "Methylergonovine IM for a client with atony persisting after oxytocin, BP 112/70 mm Hg"}, {"id": "c", "text": "Methylergonovine PO for a client treated for preeclampsia in labor, BP 138/88 mm Hg"}, {"id": "d", "text": "Oxytocin infusion for a client treated for preeclampsia in labor, BP 140/90 mm Hg"}]'::jsonb, '["c"]', 'Methylergonovine causes vasoconstriction and raises BP, so it is contraindicated in preeclampsia regardless of the current reading. Oxytocin is not restricted by preeclampsia, and methylergonovine is appropriate second-line therapy for the normotensive client.'),
  ('meds', 27, 'A client who gave birth vaginally 30 minutes ago has a boggy fundus and heavy bleeding that persists despite an oxytocin infusion. Her BP is 116/72 mm Hg, and she has no history of hypertension or preeclampsia. Which medication does the nurse anticipate the provider will order next?', '[{"id": "a", "text": "Terbutaline"}, {"id": "b", "text": "Dinoprostone (Cervidil)"}, {"id": "c", "text": "Methylergonovine (Methergine)"}, {"id": "d", "text": "Betamethasone"}]'::jsonb, '["c"]', 'Methylergonovine is second-line for postpartum hemorrhage after oxytocin fails, and her normal BP with no hypertension history means it is not contraindicated. Terbutaline relaxes the uterus, which would worsen atony.'),
  ('meds', 28, 'A client at 41 weeks'' gestation is admitted for induction of labor with an unfavorable cervix. Her history includes a cesarean birth 2 years ago. Which order should the nurse question?', '[{"id": "a", "text": "Misoprostol intravaginally for cervical ripening"}, {"id": "b", "text": "Penicillin for a positive group B streptococcus status"}, {"id": "c", "text": "Epidural anesthesia on request once IV access is confirmed"}, {"id": "d", "text": "Continuous monitoring of the fetal heart rate"}]'::jsonb, '["a"]', 'Misoprostol must not be used with a prior uterine scar from cesarean birth. Penicillin is first-line GBS prophylaxis, and an epidural with IV access and FHR monitoring are appropriate.'),
  ('meds', 29, 'A nurse placed a dinoprostone (Cervidil) vaginal insert for cervical ripening 40 minutes ago. Which action by the unlicensed assistive personnel (UAP) requires the nurse to intervene?', '[{"id": "a", "text": "Raising the side rails while the client rests in bed"}, {"id": "b", "text": "Reporting that the client says her abdomen feels tight"}, {"id": "c", "text": "Bringing the client ice chips as permitted by the nurse"}, {"id": "d", "text": "Helping the client walk to the bathroom to void"}]'::jsonb, '["d"]', 'After dinoprostone insertion the client must lie flat for 2 hours, so ambulating at 40 minutes requires correction. Reporting tightening is appropriate because hyperstimulation requires removal of the insert.'),
  ('meds', 30, 'Three hours after a dinoprostone (Cervidil) vaginal insert is placed for cervical ripening, the client is having 6 contractions in 10 minutes. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Notify the provider of the contraction pattern"}, {"id": "b", "text": "Begin the prescribed oxytocin infusion"}, {"id": "c", "text": "Remove the dinoprostone vaginal insert"}, {"id": "d", "text": "Prepare to administer methylergonovine"}]'::jsonb, '["c"]', 'More than 5 contractions in 10 minutes indicates hyperstimulation, and the dinoprostone insert is removed when this occurs. Notifying the provider follows removing the cause, and adding oxytocin would worsen the pattern.'),
  ('meds', 31, 'A client at 30 weeks'' gestation in preterm labor has received terbutaline for 24 hours, and her heart rate is now 112/min. Which new order should the nurse clarify with the provider?', '[{"id": "a", "text": "Administer betamethasone IM to the client"}, {"id": "b", "text": "Monitor maternal heart rate before each dose"}, {"id": "c", "text": "Monitor the fetal heart rate continuously"}, {"id": "d", "text": "Continue terbutaline every 4 hours for 7 more days"}]'::jsonb, '["d"]', 'Terbutaline is not for long-term tocolysis beyond 48–72 hours, so a 7-day course needs clarification. Monitoring maternal heart rate for tachycardia and the fetal heart rate are expected, and betamethasone fits preterm labor at 30 weeks.'),
  ('meds', 32, 'Twenty minutes after an epidural is placed for labor pain, the nurse reviews the client''s assessment. Her BP was 122/76 mm Hg before the procedure. Which finding requires the nurse''s immediate follow-up?', '[{"id": "a", "text": "Blood pressure of 86/50 mm Hg"}, {"id": "b", "text": "Contraction pain rated 2 on a 0-10 scale"}, {"id": "c", "text": "Bladder palpable just above the symphysis"}, {"id": "d", "text": "IV fluid infusing at the prescribed rate"}]'::jsonb, '["a"]', 'Hypotension is the key epidural risk, and a drop from 122/76 to 86/50 threatens perfusion, so it takes priority. Bladder assessment is also part of epidural care but is less urgent than hypotension, and low pain scores indicate effective relief.'),
  ('meds', 33, 'A nurse is reviewing admission orders for a term newborn born 20 minutes ago who is skin-to-skin with the mother. Which order should the nurse question?', '[{"id": "a", "text": "Erythromycin ointment to both eyes within 2 hours of birth"}, {"id": "b", "text": "Initiate breastfeeding within the first hour after birth"}, {"id": "c", "text": "Place a knit cap on the newborn''s head"}, {"id": "d", "text": "Phytonadione 5 mg IM within 1 hour of birth"}]'::jsonb, '["d"]', 'Newborn vitamin K (phytonadione) is 0.5–1 mg IM within 1 hour of birth, so 5 mg needs clarification. Erythromycin within 1–2 hours, breastfeeding within the first hour, and a knit cap are all appropriate.'),
  ('meds', 34, 'A term newborn is 50 minutes old and has been breastfeeding skin-to-skin since shortly after birth. Neither vitamin K nor erythromycin eye ointment has been given yet. Which action is the nurse''s PRIORITY at this time?', '[{"id": "a", "text": "Apply the erythromycin ointment to both eyes"}, {"id": "b", "text": "Administer the vitamin K injection IM"}, {"id": "c", "text": "Delay both medications until the feeding ends"}, {"id": "d", "text": "Move the newborn to a radiant warmer for both"}]'::jsonb, '["b"]', 'Vitamin K must be given within 1 hour of birth, leaving only 10 minutes, whereas erythromycin may be applied within 1–2 hours. A radiant warmer is reserved for at-risk newborns or procedures and is not needed here.'),
  ('meds', 35, 'The parents of a newborn born 30 minutes ago ask the nurse to skip the eye ointment because ''our baby''s eyes look perfectly healthy.'' Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "It prevents hemorrhagic disease of the newborn during the first weeks of life."}, {"id": "b", "text": "It supplies antibodies to the eyes until colostrum changes to mature milk."}, {"id": "c", "text": "It prevents a gonococcal eye infection and is required by law in most states."}, {"id": "d", "text": "It is needed only if the mother tested positive for an infection in pregnancy."}]'::jsonb, '["c"]', 'Erythromycin eye ointment prevents gonococcal ophthalmia and is required by law in most states, applied within 1–2 hours of birth. Preventing hemorrhagic disease is the purpose of vitamin K.'),
  ('meds', 36, 'A nurse on the maternity unit reviews RhoGAM orders for four Rh-negative clients. Which order should the nurse question?', '[{"id": "a", "text": "A client at 28 weeks'' gestation at a routine prenatal visit"}, {"id": "b", "text": "A client seen 1 day after a first-trimester miscarriage"}, {"id": "c", "text": "A client 48 hours after giving birth to an Rh-positive newborn"}, {"id": "d", "text": "A client 24 hours after giving birth to an Rh-negative newborn"}]'::jsonb, '["d"]', 'Postpartum RhoGAM is given within 72 hours only if the baby is Rh-positive, so an Rh-negative newborn makes the order unnecessary. RhoGAM at 28 weeks, after miscarriage, and within 72 hours of an Rh-positive birth are all indicated.'),
  ('meds', 37, 'An Rh-negative client at 16 weeks'' gestation has just had an amniocentesis. She tells the nurse, ''I know I need the RhoGAM shot, but not until 28 weeks.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "That''s right; the first dose is given at 28 weeks regardless of any procedures."}, {"id": "b", "text": "RhoGAM is also given after an amniocentesis, so you will receive a dose now."}, {"id": "c", "text": "RhoGAM is given only after delivery, once the baby''s blood type is known."}, {"id": "d", "text": "Your baby will receive RhoGAM after birth if the baby is found to be Rh-positive."}]'::jsonb, '["b"]', 'In addition to 28 weeks and after birth of an Rh-positive baby, RhoGAM is given to the Rh-negative mother after amniocentesis. It is given to the mother, not the baby.'),
  ('meds', 38, 'An Rh-negative client gave birth to an Rh-positive newborn 20 hours ago and is preparing for discharge tomorrow. Which statement by the client indicates a need for further teaching about RhoGAM?', '[{"id": "a", "text": "I need to receive the RhoGAM shot within 72 hours of my baby''s birth."}, {"id": "b", "text": "I had a RhoGAM shot at 28 weeks, but I still need another one now."}, {"id": "c", "text": "My baby will get the RhoGAM shot before we are discharged home."}, {"id": "d", "text": "I need RhoGAM because I am Rh-negative and my baby is Rh-positive."}]'::jsonb, '["c"]', 'RhoGAM is given to the Rh-negative mother, not the baby, within 72 hours after delivery. A 28-week dose does not replace the postpartum dose when the baby is Rh-positive.'),
  ('meds', 39, 'A term newborn is placed on the mother''s abdomen immediately after a vaginal birth. The newborn is crying vigorously, and the skin is covered with amniotic fluid. Which action BEST addresses the type of heat loss caused by the newborn''s wet skin?', '[{"id": "a", "text": "Placing a knit cap on the newborn''s head"}, {"id": "b", "text": "Drying the newborn''s skin thoroughly"}, {"id": "c", "text": "Covering the newborn with a warm blanket"}, {"id": "d", "text": "Transferring the newborn to a radiant warmer"}]'::jsonb, '["b"]', 'Drying removes amniotic fluid, which causes evaporative heat loss. A knit cap addresses loss from the head, warm blankets address conductive loss, and a radiant warmer is for at-risk or preterm newborns.'),
  ('meds', 40, 'A 3-hour-old term newborn was left unwrapped in a cool room during a long family visit and is now cool to the touch. The blood glucose is reported as low, and the nurse notes grunting with increased respiratory effort. Which explanation of these findings is MOST accurate?', '[{"id": "a", "text": "Low glucose reduced heat production, which then caused the newborn to become cold."}, {"id": "b", "text": "Respiratory distress developed first and lowered glucose, which then caused cooling."}, {"id": "c", "text": "Cold exposure raised oxygen use and glucose burning, leading to respiratory distress."}, {"id": "d", "text": "The newborn shivered to make heat, which used up glucose and tired the breathing muscles."}]'::jsonb, '["c"]', 'In the cold stress cascade, hypothermia increases oxygen consumption, glucose is burned for heat causing hypoglycemia, and respiratory distress follows. Newborns cannot shiver, and the other options reverse the sequence.'),
  ('meds', 41, 'A nurse is observing an unlicensed assistive personnel (UAP) caring for a 2-hour-old term newborn in the mother''s room during visiting hours. Which action by the UAP requires correction?', '[{"id": "a", "text": "Placing the newborn skin-to-skin on the mother''s chest"}, {"id": "b", "text": "Replacing a damp blanket with a dry, warm blanket"}, {"id": "c", "text": "Removing the knit cap so visitors can see the hair"}, {"id": "d", "text": "Covering both mother and newborn with a warm blanket"}]'::jsonb, '["c"]', 'The head is the largest surface area and a major source of heat loss, so the cap should stay on. Skin-to-skin contact is the most effective warming method, and dry, warm blankets preserve heat.'),
  ('meds', 42, 'A nurse observes a first-time mother breastfeeding her 1-day-old newborn. Which observation indicates the latch is NOT effective and requires the nurse''s intervention?', '[{"id": "a", "text": "The mother reports brief discomfort in the first few seconds of the latch."}, {"id": "b", "text": "The newborn''s lower lip is turned outward against the breast."}, {"id": "c", "text": "Swallowing sounds can be heard after several sucks."}, {"id": "d", "text": "The newborn''s lips are on the nipple alone, with the areola fully visible."}]'::jsonb, '["d"]', 'A good latch includes the nipple plus most of the areola in the mouth, so lips on the nipple alone needs correction. Brief initial discomfort, a flanged lower lip, and audible swallowing are expected.'),
  ('meds', 43, 'A mother calls the nursery line on day 5 after birth. Her exclusively breastfed newborn has had 4 wet diapers in the past 24 hours, passes yellow seedy stools, feeds about 9 times a day, and weighed slightly less than birth weight yesterday. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Yellow, seedy stools"}, {"id": "b", "text": "Feeding about 9 times a day"}, {"id": "c", "text": "4 wet diapers in 24 hours"}, {"id": "d", "text": "Weight below birth weight on day 5"}]'::jsonb, '["c"]', 'Fewer than 6 wet diapers by day 5 is a reason to call the provider. Yellow seedy stools and 8–12 feedings a day are expected, and birth weight is regained by 2 weeks, so being under it on day 5 is not yet a concern.'),
  ('meds', 44, 'On the second day after birth, a breastfeeding mother tells the nurse her newborn ''sleeps so well''; the baby has nursed 5 times in the past 24 hours, sleeping about 5 hours between feedings. Which teaching is MOST important for the nurse to provide?', '[{"id": "a", "text": "Offer the breast every 2 to 3 hours, watching for rooting or fist-sucking."}, {"id": "b", "text": "Wait until day 5 to count wet diapers before changing the feeding plan."}, {"id": "c", "text": "Let the newborn sleep, since long sleep stretches show adequate intake."}, {"id": "d", "text": "Keep to a strict 4-hour schedule to help the milk supply build steadily."}]'::jsonb, '["a"]', 'Newborns should feed every 2–3 hours, 8–12 times per day on demand, watching for hunger cues such as rooting and sucking fists; 5 feedings is too few. Waiting until day 5 delays correcting an inadequate pattern.'),
  ('meds', 45, 'A breastfeeding mother on postpartum day 2 says, ''My milk is thick and yellow, and there''s hardly any. I think I should switch to formula until the real milk comes in.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Thick yellow milk can point to an infection, so pump and discard it until it turns white."}, {"id": "b", "text": "Your mature milk should be in by now, so formula is a reasonable choice for the baby."}, {"id": "c", "text": "This early milk has few antibodies, so its main role is simply to start your supply."}, {"id": "d", "text": "This first milk is rich in antibodies and changes to mature milk by about day 10."}]'::jsonb, '["d"]', 'Colostrum is the thick, yellowish first milk of days 1–3, high in antibodies (IgA) and nutrients, and it transitions to mature milk by day 10. On day 2, mature milk is not yet expected.'),
  ('meds', 46, 'A term newborn is assessed 30 minutes after a birth during which the mother received opioid analgesia. When the bassinet is gently jarred, the newborn does not extend and then bring the arms together. Which action is the nurse''s PRIORITY?', '[{"id": "a", "text": "Document the response as an expected finding on the first day of life"}, {"id": "b", "text": "Further assess for neurologic injury or the effects of maternal drugs"}, {"id": "c", "text": "Plan to recheck the reflex at the 4-month well-baby visit"}, {"id": "d", "text": "Elicit the Babinski reflex to confirm the Moro finding"}]'::jsonb, '["b"]', 'An absent Moro reflex at birth requires assessment for neurological injury or drug effects. The Moro reflex should be present at birth and disappears around 4–6 months, so documenting it as expected or waiting is incorrect.'),
  ('meds', 47, 'During a well-child visit, the parent of a 9-month-old reports that when the infant''s sole is stroked from heel to toes, the toes fan outward. The parent read online that this is ''a bad sign.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "This is expected at this age and usually fades by about 12 months."}, {"id": "b", "text": "This suggests an upper motor neuron problem, so a referral is needed."}, {"id": "c", "text": "This reflex should have faded by 6 months, so it needs evaluation."}, {"id": "d", "text": "This is normal only if the infant also still shows a stepping reflex."}]'::jsonb, '["a"]', 'A positive Babinski is normal in infants and disappears around 12 months (up to 2 years). It indicates an upper motor neuron lesion only in adults, and the stepping reflex normally disappears by about 2 months.'),
  ('meds', 48, 'A term newborn is 45 minutes old, and the mother is ready to begin the first breastfeeding session in the birthing room. Which reflex assessment is the nurse''s PRIORITY before this first feed?', '[{"id": "a", "text": "Moro and palmar grasp reflexes"}, {"id": "b", "text": "Babinski and stepping reflexes"}, {"id": "c", "text": "Rooting and sucking reflexes"}, {"id": "d", "text": "Moro and stepping reflexes"}]'::jsonb, '["c"]', 'Rooting and sucking reflexes are essential for feeding and should be assessed before the first feed. The other reflexes reflect neurologic status but do not determine feeding readiness.'),
  ('meds', 49, 'A client in early pregnancy with risk factors for preeclampsia is prescribed low-dose aspirin by her provider. She says, ''I looked it up, and aspirin is a Category C drug, so isn''t it unsafe?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Category C means fetal risk is proven, so it''s used only in life-threatening situations."}, {"id": "b", "text": "Category C means risk can''t be ruled out, so it''s used when benefits outweigh the risk."}, {"id": "c", "text": "Category C means studies show no fetal risk, so there is nothing to be concerned about."}, {"id": "d", "text": "Category C means the drug is contraindicated, so you should stop taking it right away."}]'::jsonb, '["b"]', 'Category C means risk cannot be ruled out, so the drug is used if benefits outweigh risks; low-dose aspirin is used in some high-risk pregnancies to prevent preeclampsia. Proven risk describes Category D, no risk describes A, and contraindicated describes X.'),
  ('meds', 50, 'A client at 39 weeks'' gestation is admitted in active labor. Her prenatal record shows a positive group B streptococcus (GBS) culture, and she has no known drug allergies. Which medication does the nurse anticipate administering during labor?', '[{"id": "a", "text": "Metronidazole (Flagyl)"}, {"id": "b", "text": "Tetracycline"}, {"id": "c", "text": "Fluconazole"}, {"id": "d", "text": "Penicillin"}]'::jsonb, '["d"]', 'Penicillin is first-line for GBS prophylaxis in labor. Metronidazole is used for bacterial vaginosis and trichomoniasis, tetracycline is Category D, and fluconazole is Category C.'),
  ('torch', 1, 'A newborn delivered at 38 weeks has an enlarged head circumference. Imaging shows hydrocephalus with scattered intracranial calcifications, and the eye examination reveals chorioretinitis. Which congenital infection does the nurse MOST likely suspect?', '[{"id": "a", "text": "Cytomegalovirus"}, {"id": "b", "text": "Syphilis"}, {"id": "c", "text": "Rubella"}, {"id": "d", "text": "Toxoplasmosis"}]'::jsonb, '["d"]', 'Hydrocephalus, chorioretinitis, and intracranial calcifications are the fetal effects of toxoplasmosis. CMV also causes calcifications, but they are periventricular and accompany microcephaly and hearing loss rather than hydrocephalus.'),
  ('torch', 2, 'A 2-day-old newborn has a small head circumference, does not pass the newborn hearing screen, and has a seizure in the nursery. Cranial imaging shows calcifications located around the ventricles. Which congenital infection is MOST consistent with these findings?', '[{"id": "a", "text": "Toxoplasmosis"}, {"id": "b", "text": "Rubella"}, {"id": "c", "text": "Cytomegalovirus"}, {"id": "d", "text": "Herpes simplex virus"}]'::jsonb, '["c"]', 'Microcephaly, hearing loss, seizures, and periventricular calcifications describe congenital CMV. Toxoplasmosis produces calcifications with hydrocephalus and chorioretinitis, and rubella causes deafness and microcephaly with cataracts and heart defects.'),
  ('torch', 3, 'A newborn''s examination shows clouding of both lenses and a small head circumference. An echocardiogram confirms a patent ductus arteriosus, and the infant does not pass the hearing screen. The nurse recognizes this cluster as which condition?', '[{"id": "a", "text": "Congenital cytomegalovirus infection"}, {"id": "b", "text": "Congenital toxoplasmosis"}, {"id": "c", "text": "Congenital syphilis"}, {"id": "d", "text": "Congenital rubella syndrome"}]'::jsonb, '["d"]', 'Deafness, cataracts, PDA, and microcephaly make up congenital rubella syndrome. CMV shares microcephaly and hearing loss but not cataracts or PDA.'),
  ('torch', 4, 'A 3-week-old infant is brought to the clinic with a skin rash. The nurse notes a flattened nasal bridge, and x-rays show bone lesions. The mother had no prenatal care during the pregnancy. Which maternal infection does the nurse MOST likely suspect?', '[{"id": "a", "text": "Syphilis"}, {"id": "b", "text": "Herpes simplex virus"}, {"id": "c", "text": "Rubella"}, {"id": "d", "text": "Toxoplasmosis"}]'::jsonb, '["a"]', 'Rash, saddle nose, and bone lesions are features of congenital syphilis. Herpes causes vesicular lesions with seizures and lethargy, not saddle nose or bone lesions.'),
  ('torch', 5, 'A 9-day-old infant born vaginally is brought to the emergency department with clusters of fluid-filled vesicles on the scalp, marked lethargy, and a seizure at home. Which infection is MOST consistent with this presentation?', '[{"id": "a", "text": "Cytomegalovirus"}, {"id": "b", "text": "Rubella"}, {"id": "c", "text": "Syphilis"}, {"id": "d", "text": "Herpes simplex virus"}]'::jsonb, '["d"]', 'Vesicular lesions, lethargy, and seizures are signs of neonatal herpes, which can be fatal. CMV can cause seizures but presents with microcephaly, hearing loss, and periventricular calcifications rather than vesicles.'),
  ('torch', 6, 'At 30 weeks'' gestation, an ultrasound for a client who missed most of her prenatal visits shows hydrops fetalis. Which prenatal laboratory result would BEST explain this finding?', '[{"id": "a", "text": "Positive rubella IgG"}, {"id": "b", "text": "Positive CMV IgG"}, {"id": "c", "text": "Positive RPR"}, {"id": "d", "text": "Negative toxoplasma IgM"}]'::jsonb, '["c"]', 'Syphilis, screened by VDRL/RPR, crosses the placenta and causes stillbirth and hydrops fetalis. A positive IgG reflects past exposure or immunity, and a negative IgM does not indicate an active infection.'),
  ('torch', 7, 'A client at 10 weeks'' gestation who owns two cats has a TORCH panel drawn. Results show toxoplasma IgG positive and toxoplasma IgM negative. Which interpretation by the nurse is accurate?', '[{"id": "a", "text": "Recent active infection that requires treatment"}, {"id": "b", "text": "Confirmed fetal infection requiring amniocentesis"}, {"id": "c", "text": "No prior exposure, so she remains susceptible"}, {"id": "d", "text": "Past exposure, with immunity to the parasite"}]'::jsonb, '["d"]', 'IgG reflects past exposure or immunity, while IgM indicates a recent or active infection; with IgM negative, there is no evidence of current infection. Amniocentesis is reserved for suspected fetal involvement.'),
  ('torch', 8, 'A client at 20 weeks'' gestation has a positive CMV IgM result. A follow-up ultrasound shows a small fetal head, and the provider now suspects fetal infection. Which diagnostic test does the nurse prepare the client for to evaluate the fetus directly?', '[{"id": "a", "text": "Repeat maternal IgG titer"}, {"id": "b", "text": "TORCH panel of maternal blood"}, {"id": "c", "text": "Amniocentesis"}, {"id": "d", "text": "Rubella antibody titer"}]'::jsonb, '["c"]', 'Amniocentesis checks amniotic fluid and is used when fetal involvement is suspected. Maternal blood tests such as IgG titers or a TORCH panel reflect maternal infection or immunity, not fetal infection.'),
  ('torch', 9, 'At her first prenatal visit at 9 weeks'' gestation, a client''s rubella titer shows she is non-immune. She asks whether she can get the vaccine today ''to protect the baby.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "You can receive the MMR vaccine today, since early protection is best."}, {"id": "b", "text": "You can receive the MMR vaccine at 28 weeks, once the organs are formed."}, {"id": "c", "text": "You will be offered the MMR vaccine after delivery, not during pregnancy."}, {"id": "d", "text": "There is no rubella vaccine, so avoiding sick contacts is your only option."}]'::jsonb, '["c"]', 'Rubella vaccine is a live vaccine and is contraindicated throughout pregnancy, so a non-immune client is vaccinated postpartum. A rubella (MMR) vaccine does exist; CMV is the infection with no vaccine.'),
  ('torch', 10, 'A client receives the MMR vaccine at a preconception visit after her titer showed she is not immune to rubella. Which statement by the client indicates correct understanding of the follow-up teaching?', '[{"id": "a", "text": "I can start trying to get pregnant tonight."}, {"id": "b", "text": "I''ll wait at least 1 week before trying to conceive."}, {"id": "c", "text": "I''ll wait at least 2 weeks before trying to conceive."}, {"id": "d", "text": "I''ll wait at least 1 month before trying to conceive."}]'::jsonb, '["d"]', 'MMR should be received at least 1 month before pregnancy because it is a live vaccine. Waiting 1 or 2 weeks does not meet that interval.'),
  ('torch', 11, 'A nurse reviews the charts of four clients whose rubella titers show non-immunity. For which client should the nurse question an order for the MMR vaccine today?', '[{"id": "a", "text": "A client who gave birth vaginally yesterday"}, {"id": "b", "text": "A client at 14 weeks'' gestation with twins"}, {"id": "c", "text": "A client planning to conceive in 6 months"}, {"id": "d", "text": "A client using contraception who plans pregnancy next year"}]'::jsonb, '["b"]', 'The rubella vaccine is a live vaccine and is contraindicated during pregnancy. Postpartum clients and those vaccinated at least 1 month before conception are appropriate candidates.'),
  ('torch', 12, 'A client at 16 weeks'' gestation lives with two indoor cats and cooks most meals at home. After teaching about toxoplasmosis, which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "My partner will take over cleaning the cats'' litter box."}, {"id": "b", "text": "I''ll cook meat until it is no longer raw before I eat it."}, {"id": "c", "text": "I''ll keep cleaning the litter box but wash my hands afterward."}, {"id": "d", "text": "I''ll wash fruits and vegetables before eating them."}]'::jsonb, '["c"]', 'Pregnant clients should avoid litter boxes entirely, along with raw meat and unwashed produce; handwashing alone is not the teaching for toxoplasmosis. Handing the task to her partner is correct.'),
  ('torch', 13, 'A routine ultrasound at 22 weeks'' gestation shows fetal hydrocephalus with intracranial calcifications. Which question in the maternal history is MOST relevant to the infection the nurse suspects?', '[{"id": "a", "text": "Do you work with toddlers, such as in a daycare?"}, {"id": "b", "text": "Have you noticed any genital sores this pregnancy?"}, {"id": "c", "text": "Do you eat undercooked meat or handle cat litter?"}, {"id": "d", "text": "Did you receive an MMR vaccine during this pregnancy?"}]'::jsonb, '["c"]', 'Hydrocephalus with intracranial calcifications points to toxoplasmosis, transmitted by undercooked meat, contaminated soil, and cat litter. Daycare exposure relates to CMV, whose calcifications are periventricular and occur with microcephaly.'),
  ('torch', 14, 'A preschool teacher at 10 weeks'' gestation asks how to protect her baby from cytomegalovirus while she continues working with young children. Which instruction is MOST important for the nurse to give?', '[{"id": "a", "text": "Ask your provider about getting the CMV vaccine during this pregnancy."}, {"id": "b", "text": "Do hand hygiene after contact with the children''s saliva or urine."}, {"id": "c", "text": "Have a coworker handle the classroom pet''s litter and cage cleaning."}, {"id": "d", "text": "Plan for a cesarean birth so the virus is not passed to the baby."}]'::jsonb, '["b"]', 'CMV prevention focuses on avoiding contact with young children''s saliva and urine and on hand hygiene. There is no CMV vaccine, litter avoidance targets toxoplasmosis, and cesarean birth is the strategy for active HSV lesions.'),
  ('torch', 15, 'A daycare worker at 18 weeks'' gestation has just been taught about cytomegalovirus. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I''ll wash my hands after wiping the toddlers'' noses and mouths."}, {"id": "b", "text": "I won''t share cups or utensils with the children I care for."}, {"id": "c", "text": "CMV can pass to my baby across the placenta during pregnancy."}, {"id": "d", "text": "I''ll ask for the CMV vaccine at my next prenatal visit."}]'::jsonb, '["d"]', 'No vaccine is available for CMV, so planning to receive one shows misunderstanding. CMV spreads through saliva and urine and is transmitted transplacentally, so hand hygiene and avoiding shared utensils are appropriate.'),
  ('torch', 16, 'A newborn whose mother had a positive CMV IgM during pregnancy appears well at birth, with a normal head size and no seizures. Which assessment is MOST important for the nurse to ensure is completed before discharge?', '[{"id": "a", "text": "Newborn hearing screen"}, {"id": "b", "text": "Inspection for saddle nose"}, {"id": "c", "text": "Eye exam for chorioretinitis"}, {"id": "d", "text": "Skin check for vesicular lesions"}]'::jsonb, '["a"]', 'Hearing loss is a key effect of congenital CMV, and newborns of infected mothers are monitored for hearing loss. Saddle nose belongs to syphilis, chorioretinitis to toxoplasmosis, and vesicular lesions to herpes.'),
  ('torch', 17, 'A client at 39 weeks with a history of genital herpes arrives in early labor. On examination, the nurse sees active vesicular lesions on the labia. What is the nurse''s PRIORITY action?', '[{"id": "a", "text": "Notify the provider in anticipation of a cesarean birth"}, {"id": "b", "text": "Prepare for vaginal birth and start acyclovir after delivery"}, {"id": "c", "text": "Cover the lesions with a dressing and allow labor to continue"}, {"id": "d", "text": "Start acyclovir now and allow labor to progress vaginally"}]'::jsonb, '["a"]', 'Active genital lesions at the onset of labor call for cesarean birth to prevent neonatal transmission. Acyclovir is given from 36 weeks to reduce outbreaks; it does not make vaginal birth safe once lesions are present.'),
  ('torch', 18, 'A client at 38 weeks'' gestation with recurrent genital herpes has taken acyclovir since 36 weeks. She is admitted in labor, and a careful inspection of the perineum shows no active lesions. Which birth plan does the nurse anticipate?', '[{"id": "a", "text": "Cesarean birth because of her herpes history"}, {"id": "b", "text": "Vaginal birth, since no active lesions are present"}, {"id": "c", "text": "Delayed birth until a TORCH panel is resulted"}, {"id": "d", "text": "Amniocentesis to check for fetal herpes infection"}]'::jsonb, '["b"]', 'HSV is mainly transmitted during vaginal delivery when active lesions are present, and cesarean birth is indicated for active lesions. A history of herpes without lesions does not by itself require a cesarean.'),
  ('torch', 19, 'A client at 32 weeks'' gestation with recurrent genital herpes asks when she will start the antiviral medication her provider mentioned. Which response by the nurse is accurate?', '[{"id": "a", "text": "You''ll begin at 36 weeks, to lower the chance of an outbreak at delivery."}, {"id": "b", "text": "You''ll begin after delivery, since antivirals are avoided in pregnancy."}, {"id": "c", "text": "You''ll begin only if lesions appear after labor has already started."}, {"id": "d", "text": "You''ll begin today at 32 weeks, so the virus is gone before delivery."}]'::jsonb, '["a"]', 'Acyclovir is given from 36 weeks onward to reduce outbreaks before labor. Starting only after labor begins or after delivery misses the purpose of preventing lesions at birth.'),
  ('torch', 20, 'The labor and delivery nurse receives report on four newly admitted clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A client at 39 weeks, rubella non-immune, asking when she will get her vaccine"}, {"id": "b", "text": "A client at 38 weeks with a positive toxoplasma IgG asking about her cats"}, {"id": "c", "text": "A client at 39 weeks with a negative RPR asking whether she will be retested"}, {"id": "d", "text": "A client at 40 weeks with a herpes history who reports a new genital blister"}]'::jsonb, '["d"]', 'A possible active herpes lesion at the onset of labor determines whether a cesarean is needed to prevent neonatal herpes, which can be fatal. The other clients have teaching needs that are not time-critical.'),
  ('torch', 21, 'A client at high risk for sexually transmitted infections had a negative RPR at her first prenatal visit at 8 weeks. She is now at 27 weeks'' gestation. Which plan for syphilis screening does the nurse anticipate?', '[{"id": "a", "text": "No further testing, since the first result was negative"}, {"id": "b", "text": "Repeat testing at 28 weeks and again at delivery"}, {"id": "c", "text": "Repeat testing only if the newborn develops a rash"}, {"id": "d", "text": "Repeat testing at the 6-week postpartum visit"}]'::jsonb, '["b"]', 'VDRL/RPR screening is done at the first prenatal visit, at 28 weeks, and at delivery for high-risk clients. A single negative early result does not end screening, and waiting for newborn signs is too late.'),
  ('torch', 22, 'A client at 24 weeks'' gestation has a positive RPR, and syphilis is confirmed. She asks whether there is any medicine that is safe for her baby. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "Acyclovir starting at 36 weeks"}, {"id": "b", "text": "Treatment deferred until after delivery"}, {"id": "c", "text": "Penicillin G given during pregnancy"}, {"id": "d", "text": "Treatment of the newborn only after birth"}]'::jsonb, '["c"]', 'Syphilis is treated with penicillin G, which is safe in pregnancy. Deferring treatment allows ongoing fetal exposure because the organism crosses the placenta, and acyclovir is used for herpes.'),
  ('torch', 23, 'A client at 20 weeks'' gestation has just received penicillin G for syphilis. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "My partner has to be treated for this infection too."}, {"id": "b", "text": "I''ll come back for repeat blood tests after this treatment."}, {"id": "c", "text": "Since I''ve been treated, my partner doesn''t need to be seen."}, {"id": "d", "text": "The penicillin I received is considered safe for my baby."}]'::jsonb, '["c"]', 'The partner must also be treated, and the client is re-tested after treatment. Penicillin is safe in pregnancy.'),
  ('torch', 24, 'A client at 34 weeks'' gestation is newly diagnosed with syphilis. She says, ''The baby is almost fully formed, so the infection can''t reach it now.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "That''s correct; the risk to the baby is limited to the first trimester."}, {"id": "b", "text": "Syphilis can cross the placenta at any stage of the pregnancy."}, {"id": "c", "text": "The baby is exposed only during a vaginal birth with active sores."}, {"id": "d", "text": "A cesarean birth is the main way to protect the baby from it."}]'::jsonb, '["b"]', 'Syphilis crosses the placenta at any stage, so third-trimester infection still threatens the fetus. Transmission during vaginal birth with active lesions, and cesarean birth to prevent it, apply to HSV.'),
  ('torch', 25, 'A client at 8 weeks'' gestation is at her first prenatal visit and has no symptoms of infection. Which pair of infection-related laboratory tests does the nurse expect as standard first-visit screening?', '[{"id": "a", "text": "Rubella titer and VDRL/RPR"}, {"id": "b", "text": "CMV IgM and toxoplasma IgM"}, {"id": "c", "text": "Amniocentesis and ultrasound"}, {"id": "d", "text": "Herpes culture and rubella IgM"}]'::jsonb, '["a"]', 'A rubella titer and VDRL/RPR are both standard first-visit labs. Amniocentesis is reserved for suspected fetal involvement, and IgM testing is used when recent infection is suspected.'),
  ('torch', 26, 'A client at 18 weeks'' gestation has a positive toxoplasma IgM result. Today''s fetal ultrasound shows normal anatomy and growth. Which ongoing plan does the nurse anticipate for monitoring the fetus?', '[{"id": "a", "text": "Serial ultrasounds to track growth and detect structural defects"}, {"id": "b", "text": "One ultrasound at term to confirm fetal size before delivery"}, {"id": "c", "text": "Weekly maternal IgG titers in place of further fetal imaging"}, {"id": "d", "text": "Immediate amniocentesis despite the normal ultrasound today"}]'::jsonb, '["a"]', 'Fetal development is monitored with serial ultrasounds for growth and structural defects, with amniocentesis if fetal infection is suspected. A single normal scan does not end monitoring, and maternal IgG reflects past exposure, not fetal status.'),
  ('torch', 27, 'A 2-day-old newborn whose mother was treated for syphilis late in the pregnancy develops a new rash, and the nurse notes yellowing of the skin. What is the nurse''s PRIORITY action?', '[{"id": "a", "text": "Document the findings and reassess at the next feeding"}, {"id": "b", "text": "Report the findings to the pediatrician immediately"}, {"id": "c", "text": "Encourage frequent feeding and recheck the skin tomorrow"}, {"id": "d", "text": "Teach the parents to watch for these signs after discharge"}]'::jsonb, '["b"]', 'Infants of infected mothers are monitored for rash, jaundice, cataracts, and hearing loss, and these signs are reported to the pediatrician immediately. Documenting, rechecking later, or teaching for home delays action.'),
  ('torch', 28, 'A client had a positive rubella IgM at 9 weeks'' gestation and gave birth at term today. Which assessment of the newborn is the nurse''s PRIORITY to complete and communicate?', '[{"id": "a", "text": "Inspect the eyes for cataracts and assess hearing"}, {"id": "b", "text": "Inspect the skin for clusters of vesicular lesions"}, {"id": "c", "text": "Assess the nose for a saddle shape and bones for lesions"}, {"id": "d", "text": "Measure the head for hydrocephalus and check for chorioretinitis"}]'::jsonb, '["a"]', 'First-trimester rubella can cause congenital rubella syndrome with deafness, cataracts, heart defects, and microcephaly. Vesicles point to herpes, saddle nose to syphilis, and hydrocephalus with chorioretinitis to toxoplasmosis.'),
  ('torch', 29, 'A client at 10 weeks'' gestation reports a rash illness 2 weeks ago. Her rubella IgM is positive. Which interpretation of this result is MOST accurate?', '[{"id": "a", "text": "Past exposure with immunity, so the fetus is not at risk"}, {"id": "b", "text": "A recent or active infection that can affect the fetus"}, {"id": "c", "text": "Lasting protection produced by a childhood vaccine"}, {"id": "d", "text": "A false result, since rubella cannot cross the placenta"}]'::jsonb, '["b"]', 'IgM indicates a recent or active infection, and rubella is a TORCH infection that crosses the placenta and causes congenital defects. Past exposure or immunity is indicated by IgG, not IgM.'),
  ('torch', 30, 'A nurse is reviewing postpartum laboratory results for four clients before discharge. Which client should receive the MMR vaccine before going home?', '[{"id": "a", "text": "Rubella IgG positive, rubella IgM negative"}, {"id": "b", "text": "CMV IgG negative, CMV IgM negative"}, {"id": "c", "text": "Rubella IgG negative, rubella IgM negative"}, {"id": "d", "text": "Toxoplasma IgG negative, toxoplasma IgM negative"}]'::jsonb, '["c"]', 'A negative rubella IgG means no past exposure or immunity, so this client is non-immune and should be vaccinated postpartum. Positive IgG indicates immunity, and MMR does not protect against CMV or toxoplasmosis.'),
  ('torch', 31, 'A client who gave birth yesterday had a positive rubella IgG at her first prenatal visit. She asks whether she needs the MMR vaccine before discharge like her roommate. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, every client receives the MMR vaccine after delivery."}, {"id": "b", "text": "Yes, the vaccine should be given within 72 hours of the birth."}, {"id": "c", "text": "No, the vaccine can only be given before a pregnancy begins."}, {"id": "d", "text": "No, your positive IgG result shows you are already immune."}]'::jsonb, '["d"]', 'IgG indicates past exposure or immunity, so postpartum rubella vaccination is for non-immune clients only. The vaccine can be given postpartum to non-immune clients, so saying it is only given before pregnancy is incorrect.'),
  ('torch', 32, 'A client at 14 weeks'' gestation tells the nurse that her 2-year-old attends daycare and that she has a cat at home. She asks which of her daily tasks could expose her baby to cytomegalovirus. Which task should the nurse identify?', '[{"id": "a", "text": "Changing her toddler''s diapers and sharing his spoon"}, {"id": "b", "text": "Scooping the cat''s litter box twice a week"}, {"id": "c", "text": "Working in her vegetable garden without washing up"}, {"id": "d", "text": "Eating fruit from the market without washing it"}]'::jsonb, '["a"]', 'CMV spreads through saliva and urine, so diaper changes and shared utensils with a young child are the CMV exposure. Cat litter, garden soil, and unwashed produce are toxoplasmosis risks.'),
  ('torch', 33, 'A client planning a pregnancy next year asks which vaccines she should get beforehand to protect a future baby from TORCH infections. Which response by the nurse is accurate?', '[{"id": "a", "text": "Get the MMR at least 1 month before conceiving; no CMV vaccine exists."}, {"id": "b", "text": "Get the MMR and the CMV vaccines together at least 1 month before trying."}, {"id": "c", "text": "Get the MMR in early pregnancy, when the baby needs protection most."}, {"id": "d", "text": "Get the MMR at 28 weeks along with the repeat syphilis screening."}]'::jsonb, '["a"]', 'MMR should be received at least 1 month before pregnancy, and there is no vaccine for CMV. Live vaccines are contraindicated during pregnancy, so receiving MMR in early pregnancy or at 28 weeks is wrong.'),
  ('torch', 34, 'A client with a history of high-risk sexual behavior had negative RPR results at her first prenatal visit and at 28 weeks. She is now admitted in active labor at 39 weeks. Which syphilis-related action does the nurse anticipate?', '[{"id": "a", "text": "No testing, since two earlier results were negative"}, {"id": "b", "text": "Repeat RPR testing at the time of delivery"}, {"id": "c", "text": "RPR testing of the newborn only if a rash appears"}, {"id": "d", "text": "Penicillin G given during labor as a precaution"}]'::jsonb, '["b"]', 'High-risk clients are screened at the first visit, at 28 weeks, and again at delivery. Prior negative results do not replace the delivery screen, and penicillin treats confirmed syphilis.'),
  ('torch', 35, 'A client in active labor with known recurrent genital herpes asks to deliver vaginally even though the nurse has just found an active lesion. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "The virus crosses the placenta anyway, so the delivery route makes no difference."}, {"id": "b", "text": "Newborn herpes can be fatal, and a cesarean avoids contact with active lesions."}, {"id": "c", "text": "Giving acyclovir to the baby after birth will fully protect it from infection."}, {"id": "d", "text": "Small lesions do not shed the virus, so a vaginal birth would be just as safe."}]'::jsonb, '["b"]', 'Neonatal herpes can be fatal, and HSV is mainly transmitted during vaginal delivery with active lesions, so a cesarean is indicated. The infection that crosses the placenta at any stage is syphilis, not herpes.'),
  ('torch', 36, 'A client at 28 weeks'' gestation is treated with penicillin G for syphilis. Her partner has not been seen by a provider and says he has ''no symptoms.'' What is the nurse''s PRIORITY teaching for this client?', '[{"id": "a", "text": "Your single dose cured the infection, so retesting is not needed."}, {"id": "b", "text": "Your partner needs treatment only if symptoms develop later."}, {"id": "c", "text": "Your newborn will be treated at birth, so no follow-up is needed."}, {"id": "d", "text": "Your partner must be treated too, and you will be retested."}]'::jsonb, '["d"]', 'Syphilis teaching requires that the partner also be treated and that the client be re-tested after treatment. Waiting for partner symptoms or skipping repeat serology leaves the infection unchecked.'),
  ('torch', 37, 'A client gave birth 2 days ago and was found to have a positive toxoplasma IgM late in pregnancy. Which assessment of the newborn is the nurse''s PRIORITY?', '[{"id": "a", "text": "Eye exam for chorioretinitis and head size for hydrocephalus"}, {"id": "b", "text": "Echocardiogram for patent ductus arteriosus and cataracts"}, {"id": "c", "text": "Skin inspection for clusters of fluid-filled vesicles"}, {"id": "d", "text": "Inspection for saddle nose and notched teeth"}]'::jsonb, '["a"]', 'Congenital toxoplasmosis causes hydrocephalus, chorioretinitis, and intracranial calcifications. PDA and cataracts suggest rubella, vesicles suggest herpes, and saddle nose suggests syphilis.'),
  ('torch', 38, 'A client at 12 weeks'' gestation who adopted a kitten last month has a TORCH panel showing toxoplasma IgG negative and IgM negative. Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Reassure her that she is immune and can continue her routines"}, {"id": "b", "text": "Prepare her for amniocentesis to check the fetus for infection"}, {"id": "c", "text": "Teach her to avoid the litter box, raw meat, and unwashed produce"}, {"id": "d", "text": "Arrange treatment for an active infection with the toxoplasma parasite"}]'::jsonb, '["c"]', 'A negative IgG shows no past exposure or immunity and a negative IgM shows no current infection, so she remains susceptible and needs prevention teaching. Amniocentesis is for suspected fetal involvement, which is not present.'),
  ('torch', 39, 'A newborn in the NICU has microcephaly, a failed hearing screen, and periventricular calcifications. The mother says, ''I never had a cat or ate rare meat, so how did this happen?'' Which history question is MOST relevant for the nurse to ask?', '[{"id": "a", "text": "Did you have any genital sores at the time of delivery?"}, {"id": "b", "text": "Did you have frequent contact with young children''s saliva or urine?"}, {"id": "c", "text": "Did you receive an MMR vaccine during the pregnancy?"}, {"id": "d", "text": "Did you garden in soil without gloves during the pregnancy?"}]'::jsonb, '["b"]', 'These findings indicate congenital CMV, which spreads through saliva and urine, as in daycares. Garden soil relates to toxoplasmosis, and genital lesions at delivery relate to herpes.'),
  ('torch', 40, 'A nurse in a prenatal clinic is returning four phone calls. Which client should the nurse call back FIRST?', '[{"id": "a", "text": "A client at 36 weeks with recurrent herpes asking whether to start her acyclovir"}, {"id": "b", "text": "A client at 20 weeks asking whether her cat must be rehomed"}, {"id": "c", "text": "A client at 30 weeks asking about handwashing at her daycare job"}, {"id": "d", "text": "A client at 12 weeks, rubella non-immune, planning to get an MMR shot this week"}]'::jsonb, '["d"]', 'The rubella vaccine is a live vaccine contraindicated during pregnancy, so this client''s plan could cause harm and must be stopped first. The other calls are appropriate teaching questions without immediate risk.'),
  ('torch', 41, 'A nurse in the newborn nursery receives report on four infants. Which infant should the nurse assess FIRST?', '[{"id": "a", "text": "A newborn whose mother has a positive toxoplasma IgG and negative IgM"}, {"id": "b", "text": "A 7-day-old readmitted with scalp vesicles and increasing lethargy"}, {"id": "c", "text": "A newborn whose mother has a positive rubella IgG, awaiting a hearing screen"}, {"id": "d", "text": "A newborn whose mother had a negative RPR result at delivery"}]'::jsonb, '["b"]', 'Vesicular lesions with lethargy suggest neonatal herpes, which can be fatal. A positive IgG with negative IgM indicates past maternal exposure, and a negative RPR is reassuring.'),
  ('torch', 42, 'A client at 22 weeks'' gestation has completed penicillin G treatment for syphilis and asks, ''Am I finished now?'' Which follow-up does the nurse anticipate?', '[{"id": "a", "text": "No further care, since the treatment is complete"}, {"id": "b", "text": "Repeat serology to confirm the treatment worked"}, {"id": "c", "text": "Amniocentesis to confirm the fetus is free of infection"}, {"id": "d", "text": "A TORCH panel to screen for rubella immunity only"}]'::jsonb, '["b"]', 'After syphilis treatment, serology is repeated and the partner is treated. Amniocentesis is reserved for suspected fetal involvement.'),
  ('torch', 43, 'A client at 20 weeks'' gestation with recurrent genital herpes asks when her baby is at greatest risk of catching the virus. Which response by the nurse is accurate?', '[{"id": "a", "text": "Across the placenta at any stage, the same as with syphilis"}, {"id": "b", "text": "During a vaginal birth when active lesions are present"}, {"id": "c", "text": "Through contact with soil, raw meat, or cat litter"}, {"id": "d", "text": "Through the placenta, mainly in the third trimester"}]'::jsonb, '["b"]', 'HSV is mainly transmitted during vaginal delivery when active lesions are present. Crossing the placenta at any stage describes syphilis, and soil, raw meat, and cat litter describe toxoplasmosis.'),
  ('torch', 44, 'A client at 12 weeks'' gestation asks why her provider ordered a TORCH panel when she ''feels completely fine.'' Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "It is a blood test that screens for a group of infections that can cross the placenta."}, {"id": "b", "text": "It is a test of amniotic fluid that confirms whether the fetus has an infection."}, {"id": "c", "text": "It is an imaging study that looks for structural problems in the developing baby."}, {"id": "d", "text": "It is a blood test that confirms whether you are immune to rubella alone."}]'::jsonb, '["a"]', 'A TORCH panel is a combined blood test screening for all TORCH infections, which can cross the placenta and cause congenital defects. Amniotic fluid testing is amniocentesis and structural imaging is ultrasound.'),
  ('torch', 45, 'A client at 16 weeks'' gestation has a positive toxoplasma IgM. The provider first wants a noninvasive test to look for fetal structural abnormalities. Which test does the nurse prepare the client for?', '[{"id": "a", "text": "Amniocentesis"}, {"id": "b", "text": "Ultrasound"}, {"id": "c", "text": "Maternal TORCH panel"}, {"id": "d", "text": "Maternal IgG titer"}]'::jsonb, '["b"]', 'Ultrasound assesses fetal development and detects structural abnormalities. Amniocentesis checks amniotic fluid when fetal involvement is suspected, and maternal blood tests do not show fetal structure.'),
  ('torch', 46, 'A nurse is admitting a laboring client at 39 weeks whose prenatal record documents recurrent genital herpes. Which assessment is the nurse''s PRIORITY on admission?', '[{"id": "a", "text": "Inspect the perineum and vulva for active lesions"}, {"id": "b", "text": "Draw a rubella titer to check for immunity"}, {"id": "c", "text": "Ask whether she handles a cat''s litter box"}, {"id": "d", "text": "Obtain blood for a combined TORCH panel"}]'::jsonb, '["a"]', 'The presence of active genital lesions at the onset of labor determines whether a cesarean is needed to prevent neonatal transmission. Rubella titers and TORCH panels are screening tests, not labor priorities.'),
  ('torch', 47, 'A client at 26 weeks'' gestation has a positive RPR result at her prenatal visit. Her rubella titer is non-immune, and she says her toddler attends daycare. Which finding requires the nurse''s immediate follow-up with the provider?', '[{"id": "a", "text": "The non-immune rubella titer"}, {"id": "b", "text": "The toddler''s daycare attendance"}, {"id": "c", "text": "The 26-week gestational age"}, {"id": "d", "text": "The positive RPR result"}]'::jsonb, '["d"]', 'A positive RPR indicates syphilis, which crosses the placenta at any stage and needs prompt penicillin treatment. A non-immune rubella titer is managed with postpartum vaccination, and daycare exposure calls for hand-hygiene teaching.'),
  ('torch', 48, 'A nurse is teaching two pregnant clients: one newly diagnosed with syphilis and one with recurrent genital herpes. Which statement by the nurse correctly contrasts how these infections reach the baby?', '[{"id": "a", "text": "Both infections reach the baby only during a vaginal birth, so a cesarean protects against both."}, {"id": "b", "text": "Herpes crosses the placenta at any stage; syphilis spreads mainly during a vaginal birth with lesions."}, {"id": "c", "text": "Syphilis crosses the placenta at any stage; herpes spreads mainly during a vaginal birth with lesions."}, {"id": "d", "text": "Both infections are prevented by a vaccine given at least 1 month before the pregnancy begins."}]'::jsonb, '["c"]', 'Syphilis crosses the placenta at any stage, whereas HSV is mainly transmitted during vaginal delivery when active lesions are present. Option b reverses the two, and the 1-month pre-pregnancy vaccine applies to rubella.'),
  ('torch', 49, 'A client at 11 weeks'' gestation who works at a pet shelter and eats rare steak frequently is found to have a positive toxoplasma IgM. She asks what is causing the infection. Which response by the nurse is accurate?', '[{"id": "a", "text": "A spirochete bacterium spread mainly through sexual contact"}, {"id": "b", "text": "A virus spread through saliva and urine of young children"}, {"id": "c", "text": "A parasite spread through undercooked meat, soil, and cat litter"}, {"id": "d", "text": "A virus spread mainly during vaginal birth with active lesions"}]'::jsonb, '["c"]', 'Toxoplasmosis is caused by the parasite Toxoplasma gondii and spreads through undercooked meat, contaminated soil, and cat litter. A spirochete describes syphilis, saliva and urine describe CMV, and birth with active lesions describes herpes.'),
  ('torch', 50, 'A client at 10 weeks'' gestation has a negative RPR at her first prenatal visit. She tells the nurse she recently began a relationship with a new sexual partner and asks how to protect her baby from syphilis. Which teaching is MOST appropriate?', '[{"id": "a", "text": "Avoid cleaning cat litter and eating raw meat"}, {"id": "b", "text": "Plan to receive the MMR vaccine after delivery"}, {"id": "c", "text": "Wash hands after contact with children''s saliva"}, {"id": "d", "text": "Use safe sex practices throughout the pregnancy"}]'::jsonb, '["d"]', 'Syphilis is transmitted by sexual contact, so prevention teaching centers on safe sex practices. Avoiding litter and raw meat prevents toxoplasmosis, and hand hygiene after contact with children''s saliva prevents CMV.'),
  ('hormonal', 1, 'A 16-year-old client reports cramping lower abdominal pain that begins the day before her menstrual flow each month and lasts about 2 days. Her pelvic examination is normal, and the pain has not changed since her periods began. Which intervention should the nurse anticipate FIRST?', '[{"id": "a", "text": "Pelvic ultrasound followed by laparoscopy to locate a cause"}, {"id": "b", "text": "An NSAID to reduce prostaglandin production and cramping"}, {"id": "c", "text": "A GnRH agonist to induce a temporary medical menopause"}, {"id": "d", "text": "An SSRI taken during the luteal phase to relieve symptoms"}]'::jsonb, '["b"]', 'Pain starting 1–2 days before flow and lasting 2–3 days with no underlying cause is primary dysmenorrhea, which is driven by excess prostaglandins; NSAIDs are first-line. Ultrasound and laparoscopy are used when secondary dysmenorrhea is suspected.'),
  ('hormonal', 2, 'A 34-year-old client reports that her menstrual cramps have become steadily more severe over the past 3 years, although her periods were only mildly uncomfortable as a teenager. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Reassure her that cramps commonly peak during the third decade"}, {"id": "b", "text": "Teach her to begin an SSRI during the 2 weeks before each period"}, {"id": "c", "text": "Teach her to apply heat and exercise as her only treatment"}, {"id": "d", "text": "Prepare her for evaluation by pelvic ultrasound or laparoscopy"}]'::jsonb, '["d"]', 'Pain that worsens over time suggests secondary dysmenorrhea caused by conditions such as endometriosis, fibroids, or PID, so the underlying cause should be evaluated with pelvic ultrasound or laparoscopy. Heat and exercise alone address primary dysmenorrhea.'),
  ('hormonal', 3, 'A nurse teaches a 17-year-old client with primary dysmenorrhea about the cause of her monthly cramps. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "My cramps mean I likely have a disease such as fibroids or PID."}, {"id": "b", "text": "Extra prostaglandins make my uterus contract and lose blood flow."}, {"id": "c", "text": "Taking an NSAID helps because it lowers my prostaglandin levels."}, {"id": "d", "text": "Applying heat and getting exercise can help ease the cramping."}]'::jsonb, '["a"]', 'Primary dysmenorrhea has no underlying cause; excess prostaglandins cause uterine contractions and ischemia. Fibroids and PID are causes of secondary dysmenorrhea.'),
  ('hormonal', 4, 'A school nurse reviews health records for four adolescent clients who have never had a menstrual period. Which client meets the criteria for primary amenorrhea and requires referral for evaluation?', '[{"id": "a", "text": "A 14-year-old with breast development and pubic hair"}, {"id": "b", "text": "A 12-year-old with no breast development or pubic hair"}, {"id": "c", "text": "A 13-year-old with no breast development or pubic hair"}, {"id": "d", "text": "A 14-year-old with early breast development this year"}]'::jsonb, '["c"]', 'Primary amenorrhea is no period by age 15 with normal secondary sex traits or by age 13 without them, so the 13-year-old with no secondary sex characteristics qualifies. The 14-year-olds with secondary sex traits have not yet reached age 15.'),
  ('hormonal', 5, 'A 24-year-old client who previously had regular monthly periods reports that she has not had a period for 4 months. She has also been under stress at work and has lost some weight. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Obtain a pregnancy test before any other evaluation"}, {"id": "b", "text": "Draw TSH and prolactin levels to check for an endocrine cause"}, {"id": "c", "text": "Teach her stress-reduction strategies for hypothalamic causes"}, {"id": "d", "text": "Begin calcium and vitamin D for low-estrogen bone protection"}]'::jsonb, '["a"]', 'No period for 3 months or more in a woman who previously menstruated is secondary amenorrhea, and a pregnancy test is always checked first. TSH, prolactin, and other labs follow only after pregnancy is excluded.'),
  ('hormonal', 6, 'A 28-year-old client with no period for 5 months, after previously regular cycles, has a negative hCG test. Which group of laboratory tests should the nurse anticipate NEXT to identify the cause?', '[{"id": "a", "text": "CBC, coagulation panel, and pelvic ultrasound"}, {"id": "b", "text": "Fasting glucose, insulin, and a lipid panel"}, {"id": "c", "text": "TSH, prolactin, FSH/LH, and estradiol"}, {"id": "d", "text": "Repeat hCG, CBC, and a coagulation panel"}]'::jsonb, '["c"]', 'For amenorrhea, hCG is checked first, followed by TSH, prolactin, FSH/LH, and estradiol to look for thyroid, pituitary, ovarian, or hypothalamic causes. CBC, coagulation panel, and pelvic ultrasound are the workup for heavy bleeding.'),
  ('hormonal', 7, 'A 22-year-old competitive distance runner has had no period for 6 months and has lost weight during training. Her pregnancy test is negative, and her estrogen level is low. Which teaching is the PRIORITY for this client?', '[{"id": "a", "text": "Take an SSRI during the 2 weeks before her expected period"}, {"id": "b", "text": "Increase calcium and vitamin D intake to protect her bones"}, {"id": "c", "text": "Take tranexamic acid to restore her normal menstrual cycle"}, {"id": "d", "text": "Begin spironolactone to correct the cause of her amenorrhea"}]'::jsonb, '["b"]', 'Hypothalamic dysfunction from weight loss and overexercise causes amenorrhea, and low estrogen raises osteoporosis risk, so calcium and vitamin D are taught. Tranexamic acid treats heavy bleeding, not absent periods.'),
  ('hormonal', 8, 'A client who delivered 4 months ago is exclusively breastfeeding and has not had a menstrual period since giving birth. She asks why her cycle has not returned. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Oxytocin released during let-down suppresses ovulation"}, {"id": "b", "text": "Prolactin suppresses GnRH, which inhibits ovulation"}, {"id": "c", "text": "hCG remains elevated for months and maintains the lining"}, {"id": "d", "text": "Progesterone remains high from the corpus luteum of pregnancy"}]'::jsonb, '["b"]', 'Prolactin stimulates milk production and suppresses GnRH, which inhibits ovulation while breastfeeding. Oxytocin causes the milk let-down reflex and uterine contractions but is not the hormone that suppresses ovulation.'),
  ('hormonal', 9, 'A 38-year-old client calls the clinic on day 2 of her period. She has soaked through one pad every hour for the past 5 hours and reports feeling dizzy and short of breath when she stands. Which group of diagnostic tests should the nurse anticipate?', '[{"id": "a", "text": "TSH, prolactin, FSH/LH, and estradiol"}, {"id": "b", "text": "CBC, coagulation panel, and pelvic ultrasound"}, {"id": "c", "text": "LH:FSH ratio, testosterone, and fasting insulin"}, {"id": "d", "text": "FSH, LH, estrogen, and anti-Müllerian hormone"}]'::jsonb, '["b"]', 'Soaking at least 1 pad per hour for several hours is abnormal heavy bleeding (menorrhagia), and dizziness and shortness of breath suggest anemia; the workup includes CBC, coagulation panel, and pelvic ultrasound. TSH, prolactin, FSH/LH, and estradiol are the amenorrhea workup.'),
  ('hormonal', 10, 'A nurse reviews telephone messages from four clients who are currently menstruating. Which client''s report should the nurse identify as abnormal and requiring follow-up?', '[{"id": "a", "text": "Soaking one pad each hour for the past 4 hours"}, {"id": "b", "text": "Changing a pad every 3 to 4 hours on the heaviest day"}, {"id": "c", "text": "Cramping that began the day before her flow started"}, {"id": "d", "text": "Bloating and breast tenderness in the week before flow"}]'::jsonb, '["a"]', 'Soaking 1 or more pads per hour for several hours is abnormal and indicates menorrhagia. Cramping beginning just before flow fits primary dysmenorrhea, and premenstrual bloating and breast tenderness fit PMS.'),
  ('hormonal', 11, 'A 30-year-old client had a copper IUD inserted 6 months ago. She now reports that her periods last 8 days and are much heavier than before, and she feels increasingly tired. Which conclusion by the nurse is MOST accurate?', '[{"id": "a", "text": "Her findings suggest PMDD, which commonly follows IUD insertion"}, {"id": "b", "text": "Her findings suggest metrorrhagia, bleeding at unpredictable times"}, {"id": "c", "text": "Her findings suggest oligomenorrhea, which is common with an IUD"}, {"id": "d", "text": "Her findings suggest menorrhagia, a recognized copper IUD effect"}]'::jsonb, '["d"]', 'Periods longer than 7 days or with excessive loss are menorrhagia, and the copper IUD is a listed cause; fatigue suggests developing anemia. Metrorrhagia is irregular bleeding between periods, not prolonged heavy flow.'),
  ('hormonal', 12, 'A 41-year-old client with fibroids has had periods lasting 9 days with heavy flow for the past 6 months. Which additional finding should the nurse recognize as MOST indicative of a complication of her bleeding?', '[{"id": "a", "text": "Bloating and breast tenderness before each period"}, {"id": "b", "text": "Fatigue, pallor, and brittle nails lately"}, {"id": "c", "text": "Acne and coarse hair growth on the chin and lip"}, {"id": "d", "text": "Pain with intercourse and painful bowel movements"}]'::jsonb, '["b"]', 'Fatigue, pallor, and brittle nails are signs of anemia, a complication of heavy, prolonged bleeding. Acne and hirsutism suggest PCOS, and dyspareunia with dyschezia suggests endometriosis.'),
  ('hormonal', 13, 'A 36-year-old client with menorrhagia and a low hemoglobin is being discharged with a prescription for tranexamic acid. Which teaching by the nurse is MOST appropriate for this client?', '[{"id": "a", "text": "Tranexamic acid is a progestin, so she should expect her periods to stop"}, {"id": "b", "text": "Tranexamic acid is an SSRI, so she should take it in the luteal phase"}, {"id": "c", "text": "Tranexamic acid is an antifibrinolytic; also eat iron-rich foods daily"}, {"id": "d", "text": "Tranexamic acid is a GnRH agonist, so hot flashes are an expected effect"}]'::jsonb, '["c"]', 'Tranexamic acid is an antifibrinolytic used for menorrhagia, and clients are taught an iron-rich diet plus supplements because of anemia risk. GnRH agonists, not tranexamic acid, cause hot flashes from medical menopause.'),
  ('hormonal', 14, 'A nurse teaches a 19-year-old client with primary dysmenorrhea about non-drug measures to use alongside her prescribed NSAID. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I can place a heating pad on my lower abdomen when cramps start."}, {"id": "b", "text": "Regular exercise may help reduce my cramping each month."}, {"id": "c", "text": "Starting my NSAID as cramps begin helps lower prostaglandins."}, {"id": "d", "text": "I should rest in bed and skip exercise until cramps pass."}]'::jsonb, '["d"]', 'Heat therapy and exercise are recommended treatments for dysmenorrhea along with NSAIDs and hormonal contraceptives, so avoiding exercise reflects a misunderstanding. NSAIDs work by lowering prostaglandins.'),
  ('hormonal', 15, 'A 45-year-old client reports regular monthly periods of normal amount, but over the past 2 months she has also had episodes of spotting and light bleeding at unpredictable times between her periods. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Prepare for evaluation to identify a cause such as polyps or cancer"}, {"id": "b", "text": "Teach that heavy flow over 7 days requires a pad count each day"}, {"id": "c", "text": "Explain that cycles longer than 35 days are expected at her age"}, {"id": "d", "text": "Teach that luteal-phase spotting is treated with an SSRI first-line"}]'::jsonb, '["a"]', 'Irregular bleeding between periods is metrorrhagia, and management begins by identifying the cause, such as polyps, infection, or cancer. Flow longer than 7 days describes menorrhagia, and cycles longer than 35 days describe oligomenorrhea.'),
  ('hormonal', 16, 'A 23-year-old client reports that her periods come every 45 to 60 days. She also has acne, coarse hair growth on her chin, and a body mass index in the obese range. Which condition should the nurse suspect is MOST likely causing her menstrual pattern?', '[{"id": "a", "text": "Endometriosis causing scarring and adhesions in the pelvis"}, {"id": "b", "text": "Primary dysmenorrhea from excess uterine prostaglandins"}, {"id": "c", "text": "Polycystic ovary syndrome with irregular ovulation"}, {"id": "d", "text": "Perimenopause with fluctuating ovarian hormone levels"}]'::jsonb, '["c"]', 'Cycles longer than 35 days are oligomenorrhea, which is common in PCOS, and hirsutism, acne, and obesity are PCOS symptoms. Endometriosis presents with dysmenorrhea, dyspareunia, and infertility rather than hirsutism.'),
  ('hormonal', 17, 'A nurse in a gynecology clinic reviews the menstrual diaries of four clients. Which client''s cycle pattern meets the criterion for oligomenorrhea?', '[{"id": "a", "text": "A client whose periods begin every 33 days"}, {"id": "b", "text": "A client whose periods begin every 35 days"}, {"id": "c", "text": "A client whose periods begin every 40 days"}, {"id": "d", "text": "A client whose periods begin every 21 days"}]'::jsonb, '["c"]', 'Oligomenorrhea is infrequent periods with more than 35 days between cycles, so only the 40-day pattern meets the criterion. A 35-day interval is at, not beyond, the cut-off.'),
  ('hormonal', 18, 'A 29-year-old client reports that for the 10 days before each period she feels hopeless and anxious, has angry outbursts, and has missed work several times. Her mood improves within days after her flow starts. Which treatment should the nurse anticipate as first-line?', '[{"id": "a", "text": "Calcium supplements and regular aerobic exercise"}, {"id": "b", "text": "An NSAID taken at the first sign of symptoms"}, {"id": "c", "text": "A GnRH agonist to suppress ovarian hormones"}, {"id": "d", "text": "An SSRI taken daily or during the luteal phase"}]'::jsonb, '["d"]', 'Severe mood symptoms with significant impairment that improve within days of menstruation starting suggest PMDD, for which SSRIs are first-line and may be given continuously or only during the luteal phase. Calcium, exercise, and NSAIDs are treatments for milder PMS.'),
  ('hormonal', 19, 'A nurse is screening four clients who report premenstrual symptoms during the week before their periods. Which client statement requires the MOST immediate follow-up?', '[{"id": "a", "text": "I feel so hopeless that I have thought about ending my life."}, {"id": "b", "text": "I get bloated and my breasts are sore every month before my period."}, {"id": "c", "text": "I am irritable and snap at my partner for a few days each month."}, {"id": "d", "text": "I get headaches and feel tired for several days before I bleed."}]'::jsonb, '["a"]', 'Hopelessness with suicidal ideation is a PMDD mood symptom and requires immediate follow-up. Bloating, breast tenderness, fatigue, headache, and mild irritability are typical PMS symptoms with only mild disruption.'),
  ('hormonal', 20, 'A 26-year-old client reports bloating, breast tenderness, and mild irritability during the week before each period. She continues to work and socialize normally. Which teaching should the nurse include for this client?', '[{"id": "a", "text": "Begin a daily SSRI, since this is the first-line treatment for her pattern"}, {"id": "b", "text": "Prepare for laparoscopy, since these signs suggest an ovarian cause"}, {"id": "c", "text": "Exercise regularly, adjust her diet, and consider calcium and NSAIDs"}, {"id": "d", "text": "Begin metformin, since these signs suggest underlying insulin resistance"}]'::jsonb, '["c"]', 'Mild physical and mood symptoms in the luteal phase with only mild disruption fit PMS, which is treated with exercise, diet, calcium, NSAIDs, and OCPs. SSRIs are first-line for PMDD, which causes significant impairment.'),
  ('hormonal', 21, 'A 31-year-old client with PMDD is starting an SSRI and asks whether she will have to take it every day for the rest of her life. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "It must be taken every day, since stopping it in any phase causes relapse"}, {"id": "b", "text": "It is taken during menstrual bleeding, when her symptoms are at their worst"}, {"id": "c", "text": "It is taken in the first week after her period, before her symptoms start"}, {"id": "d", "text": "It may be taken daily or limited to the luteal phase before her period"}]'::jsonb, '["d"]', 'SSRIs for PMDD can be given continuously or only during the luteal phase, when symptoms occur. PMDD symptoms occur in the luteal phase and improve once menstruation starts, so dosing during bleeding or right after it is mistimed.'),
  ('hormonal', 22, 'A nurse reviews symptom diaries from four clients who believe they have PMS. Which client''s pattern is MOST consistent with PMS?', '[{"id": "a", "text": "Breast tenderness and bloating from day 18 until her flow begins"}, {"id": "b", "text": "Fatigue and irritability from day 2 until day 9 of her cycle"}, {"id": "c", "text": "Headache and low mood that start 3 days after her flow ends"}, {"id": "d", "text": "Bloating and mood swings that persist throughout the entire cycle"}]'::jsonb, '["a"]', 'PMS symptoms occur in the luteal phase, 1–2 weeks before the period, so symptoms from day 18 until flow fit the pattern. Symptoms that begin during or after menses or persist throughout the cycle do not match luteal-phase timing.'),
  ('hormonal', 23, 'A 32-year-old client reports severe menstrual cramps, pain during intercourse, and 2 years of unsuccessful attempts to become pregnant. Her pregnancy test is negative. Which condition should the nurse suspect?', '[{"id": "a", "text": "Polycystic ovary syndrome"}, {"id": "b", "text": "Premenstrual dysphoric disorder"}, {"id": "c", "text": "Endometriosis"}, {"id": "d", "text": "Primary dysmenorrhea"}]'::jsonb, '["c"]', 'Dysmenorrhea, dyspareunia, and infertility form the classic triad of endometriosis. Primary dysmenorrhea has no underlying cause and does not explain dyspareunia or infertility.'),
  ('hormonal', 24, 'A 30-year-old client with dysmenorrhea, dyspareunia, and pelvic pain throughout her cycle had a normal pelvic ultrasound. She asks whether this rules out endometriosis. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, a normal ultrasound excludes endometriosis as the cause"}, {"id": "b", "text": "Yes, so an elevated FSH level is needed to explain her pain"}, {"id": "c", "text": "No, an LH:FSH ratio above 2:1 is needed to confirm the diagnosis"}, {"id": "d", "text": "No, laparoscopy is the gold standard for the diagnosis"}]'::jsonb, '["d"]', 'Laparoscopy is the gold standard for diagnosing endometriosis; ultrasound may show endometriomas but does not exclude the disease. An elevated LH:FSH ratio is classic for PCOS, not endometriosis.'),
  ('hormonal', 25, 'A 33-year-old client with worsening dysmenorrhea and dyspareunia has a transvaginal ultrasound report describing dark, blood-filled cysts on both ovaries. She asks what these cysts mean. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "They are multiple small follicular cysts, typical of PCOS"}, {"id": "b", "text": "They are endometriomas, a finding seen with endometriosis"}, {"id": "c", "text": "They are signs of uterine infection, typical of endometritis"}, {"id": "d", "text": "They are a dominant follicle and corpus luteum of a normal cycle"}]'::jsonb, '["b"]', 'Dark, blood-filled ovarian cysts are endometriomas, called chocolate cysts, which ultrasound may show in endometriosis. PCOS produces multiple small follicular cysts in a string-of-pearls pattern.'),
  ('hormonal', 26, 'A nurse on a women''s health unit reviews four clients whose charts list either endometriosis or endometritis. Which client''s presentation is MOST consistent with endometritis?', '[{"id": "a", "text": "A client 4 days after birth with a uterine infection"}, {"id": "b", "text": "A client with painful periods and pain during intercourse"}, {"id": "c", "text": "A client with infertility and painful bowel movements"}, {"id": "d", "text": "A client with pelvic pain and ovarian chocolate cysts"}]'::jsonb, '["a"]', 'Endometritis is a uterine infection, often postpartum, whereas endometriosis is endometrial tissue growing outside the uterus. Dysmenorrhea, dyspareunia, infertility, dyschezia, and chocolate cysts all point to endometriosis.'),
  ('hormonal', 27, 'A 35-year-old client with endometriosis is starting leuprolide (Lupron), a GnRH agonist. Which teaching about expected effects is MOST important for the nurse to include?', '[{"id": "a", "text": "It raises prolactin, so milky breast discharge is expected"}, {"id": "b", "text": "It raises androgens, so acne and facial hair are expected"}, {"id": "c", "text": "It thickens the endometrium, so heavier periods are expected"}, {"id": "d", "text": "It causes a temporary menopause, so hot flashes are expected"}]'::jsonb, '["d"]', 'GnRH agonists such as Lupron induce a temporary medical menopause, which may cause hot flashes and osteoporosis. Androgen effects such as acne and hirsutism are features of PCOS, not of GnRH agonist therapy.'),
  ('hormonal', 28, 'A 27-year-old client reports pelvic pain that is worst during her periods. During the health history, she mentions other symptoms. Which additional finding should the nurse recognize as MOST consistent with endometriosis?', '[{"id": "a", "text": "Coarse hair growth on her chin and dark velvety neck skin"}, {"id": "b", "text": "Pain with bowel movements and rectal bleeding near menses"}, {"id": "c", "text": "Hot flashes, night sweats, and vaginal dryness for months"}, {"id": "d", "text": "Bloating and breast tenderness that resolve as flow begins"}]'::jsonb, '["b"]', 'Endometriosis may cause pelvic pain throughout the cycle, dyschezia (painful defecation), rectal bleeding, and fatigue. Hirsutism and acanthosis nigricans suggest PCOS, and hot flashes with vaginal dryness suggest menopause.'),
  ('hormonal', 29, 'A 47-year-old client with severe endometriosis has had no relief from NSAIDs, combined OCPs, progestins, or laparoscopic excision. She does not desire future pregnancy and asks which treatment offers a definitive cure. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Danazol, continued long term to suppress the disease"}, {"id": "b", "text": "Repeated laparoscopic ablation of the visible lesions"}, {"id": "c", "text": "Hysterectomy with removal of the ovaries"}, {"id": "d", "text": "A GnRH agonist continued with add-back therapy"}]'::jsonb, '["c"]', 'Hysterectomy with oophorectomy is the definitive cure for endometriosis. Danazol, GnRH agonists, and laparoscopic excision or ablation are medical or conservative surgical treatments.'),
  ('hormonal', 30, 'A 25-year-old client reports periods every 2 to 3 months, acne, and excess hair on her face and abdomen. The nurse notes obesity and dark, velvety skin on the back of her neck. Which condition should the nurse suspect?', '[{"id": "a", "text": "Polycystic ovary syndrome"}, {"id": "b", "text": "Endometriosis"}, {"id": "c", "text": "Hypothalamic amenorrhea"}, {"id": "d", "text": "Premenstrual syndrome"}]'::jsonb, '["a"]', 'Oligomenorrhea, hirsutism, acne, obesity, and acanthosis nigricans are classic symptoms of PCOS. Hypothalamic amenorrhea is linked to stress, weight loss, and overexercise rather than hirsutism and obesity.'),
  ('hormonal', 31, 'A 24-year-old client has irregular ovulation documented over 6 months, and her ultrasound shows polycystic ovaries. Her testosterone level is normal, and she has no acne or excess hair. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "PCOS cannot be diagnosed because hyperandrogenism is absent"}, {"id": "b", "text": "PCOS cannot be diagnosed without an LH:FSH ratio above 3:1"}, {"id": "c", "text": "PCOS requires all three criteria, so laparoscopy is needed next"}, {"id": "d", "text": "PCOS criteria are met, because 2 of the 3 criteria are present"}]'::jsonb, '["d"]', 'The Rotterdam criteria require 2 of 3 findings: irregular ovulation or anovulation, hyperandrogenism, and polycystic ovaries on ultrasound. This client has two, so hyperandrogenism is not required.'),
  ('hormonal', 32, 'A nurse reviews laboratory results for four clients being evaluated for irregular menses. Which client''s results are MOST consistent with polycystic ovary syndrome?', '[{"id": "a", "text": "LH 6 mIU/mL and FSH 18 mIU/mL"}, {"id": "b", "text": "LH 18 mIU/mL and FSH 6 mIU/mL"}, {"id": "c", "text": "LH 8 mIU/mL and FSH 6 mIU/mL"}, {"id": "d", "text": "LH 10 mIU/mL and FSH 10 mIU/mL"}]'::jsonb, '["b"]', 'An LH:FSH ratio above 2:1 is classic for PCOS; LH 18 with FSH 6 is a 3:1 ratio. LH 8 with FSH 6 is only about 1.3:1, and LH 6 with FSH 18 reverses the ratio.'),
  ('hormonal', 33, 'A 26-year-old client with PCOS has an elevated fasting insulin level and has never been diagnosed with diabetes. She is prescribed metformin and says, ''I don''t have diabetes, so why do I need this?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Metformin raises your estrogen so your endometrium is protected"}, {"id": "b", "text": "Metformin lowers your androgens, which is its main role in PCOS"}, {"id": "c", "text": "Metformin is first-line in PCOS with insulin resistance"}, {"id": "d", "text": "Metformin prevents ovulation so the ovarian cysts can shrink"}]'::jsonb, '["c"]', 'Metformin is not just for diabetics; it is first-line for PCOS with insulin resistance. Spironolactone is the listed treatment for hirsutism, and clomiphene is used for fertility.'),
  ('hormonal', 34, 'A 30-year-old client with PCOS has had only four periods in the past year. She asks why her provider is concerned about her risk for endometrial cancer. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Without ovulation, no progesterone opposes estrogen on the lining"}, {"id": "b", "text": "High LH levels directly convert the cells of the lining into cancer cells"}, {"id": "c", "text": "Excess progesterone from frequent ovulation overstimulates the lining"}, {"id": "d", "text": "The ovarian cysts spread abnormal tissue to the lining of the uterus"}]'::jsonb, '["a"]', 'In PCOS, anovulation means no progesterone is produced, so unopposed estrogen builds up the endometrium and raises endometrial cancer risk. PCOS involves irregular ovulation, not frequent ovulation with excess progesterone.'),
  ('hormonal', 35, 'A 28-year-old client with PCOS weighs 220 lb (100 kg) and feels discouraged because her target weight seems out of reach. Which teaching by the nurse is MOST accurate?', '[{"id": "a", "text": "Symptoms improve only after she reaches a normal body weight"}, {"id": "b", "text": "A loss of about 44 lb (20 kg) is needed before any benefit occurs"}, {"id": "c", "text": "Weight loss mainly helps acne and does not affect her cycles"}, {"id": "d", "text": "Losing about 11 lb (5 kg) may already improve her symptoms"}]'::jsonb, '["d"]', 'Even a 5% weight loss improves PCOS symptoms; 5% of 220 lb is 11 lb (5 kg). Requiring a 20% loss or normal weight before any benefit is incorrect.'),
  ('hormonal', 36, 'A nurse is planning follow-up care for a 34-year-old client with long-standing PCOS and insulin resistance. Which complication should the nurse prioritize in screening during follow-up visits?', '[{"id": "a", "text": "Osteoporosis from long-term estrogen deficiency"}, {"id": "b", "text": "Type 2 diabetes and metabolic syndrome"}, {"id": "c", "text": "Anemia from heavy and frequent menstrual flow"}, {"id": "d", "text": "Endometriosis spreading to the ovaries"}]'::jsonb, '["b"]', 'Complications of PCOS include type 2 diabetes, metabolic syndrome, endometrial cancer, cardiovascular disease, and infertility. Low-estrogen osteoporosis risk is associated with amenorrhea from low estrogen and menopause, while PCOS involves unopposed estrogen.'),
  ('hormonal', 37, 'A 29-year-old client with PCOS has not conceived after a year of trying and asks which medication her provider is MOST likely to prescribe to help her become pregnant. Which response by the nurse is accurate?', '[{"id": "a", "text": "Spironolactone, which is used for this purpose in PCOS"}, {"id": "b", "text": "A combined OCP, which is used for this purpose in PCOS"}, {"id": "c", "text": "Clomiphene, which is used for this purpose in PCOS"}, {"id": "d", "text": "Leuprolide, which is used for this purpose in PCOS"}]'::jsonb, '["c"]', 'In PCOS, clomiphene is used for fertility, while spironolactone treats hirsutism and OCPs regulate the cycle. OCPs would not help a client trying to conceive.'),
  ('hormonal', 38, 'A 31-year-old client recently diagnosed with endometriosis asks why her misplaced tissue causes so much pain and scarring each month. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The tissue lacks hormone receptors, so it grows steadily all month"}, {"id": "b", "text": "The tissue responds to the cycle and bleeds with no way to exit"}, {"id": "c", "text": "The tissue is infected, so the body forms scar tissue around it"}, {"id": "d", "text": "The tissue forms fluid-filled follicles that rupture at ovulation"}]'::jsonb, '["b"]', 'Endometrial tissue outside the uterus responds to the hormonal cycle and bleeds with no exit, causing inflammation, scarring, and adhesions. Infection of the uterus describes endometritis, not endometriosis.'),
  ('hormonal', 39, 'A 50-year-old client reports hot flashes and night sweats and states that her last menstrual period was 10 months ago. She asks whether she has reached menopause. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Not yet; menopause requires 12 months in a row with no period"}, {"id": "b", "text": "Yes; menopause is confirmed once hot flashes occur with missed periods"}, {"id": "c", "text": "Yes; menopause is confirmed after 6 months in a row without a period"}, {"id": "d", "text": "Not yet; menopause cannot be confirmed until she reaches age 55"}]'::jsonb, '["a"]', 'Menopause is 12 consecutive months without a period and is diagnosed retrospectively, so at 10 months she has not yet met the definition. The average age of menopause is 51, so age 55 is not a requirement.'),
  ('hormonal', 40, 'A 53-year-old client has had no menstrual period for 14 months and reports hot flashes and vaginal dryness. Which set of laboratory findings should the nurse expect?', '[{"id": "a", "text": "Low FSH, low LH, high estrogen, and high AMH"}, {"id": "b", "text": "High FSH, low LH, high estrogen, and low AMH"}, {"id": "c", "text": "Low FSH, high LH, low estrogen, and high AMH"}, {"id": "d", "text": "High FSH, high LH, low estrogen, and low AMH"}]'::jsonb, '["d"]', 'Menopause labs show increased FSH and LH with decreased estrogen and AMH. Low FSH would not fit, because FSH rises as the pituitary tries to stimulate non-responsive ovaries.'),
  ('hormonal', 41, 'A nurse reviews hormone replacement therapy (HRT) prescriptions for four postmenopausal clients with no contraindications to HRT. Which prescription should the nurse question?', '[{"id": "a", "text": "Estrogen alone for a client who had a hysterectomy 5 years ago"}, {"id": "b", "text": "Estrogen alone for a client whose uterus is intact"}, {"id": "c", "text": "Estrogen plus progesterone for a client whose uterus is intact"}, {"id": "d", "text": "Vaginal estrogen cream for a client with vaginal dryness"}]'::jsonb, '["b"]', 'If the uterus is intact, progesterone must be added to estrogen HRT to prevent endometrial cancer, so estrogen alone for this client should be questioned. After hysterectomy, estrogen-only HRT is safe.'),
  ('hormonal', 42, 'A 52-year-old menopausal client with frequent, disruptive hot flashes has a history of deep vein thrombosis 3 years ago. She asks what can be done for her hot flashes. Which treatment should the nurse anticipate?', '[{"id": "a", "text": "Combined estrogen and progesterone HRT"}, {"id": "b", "text": "Estrogen-only HRT at the lowest dose"}, {"id": "c", "text": "An SSRI to reduce the hot flashes"}, {"id": "d", "text": "A GnRH agonist to stop the hot flashes"}]'::jsonb, '["c"]', 'A history of DVT/PE is an HRT contraindication, and SSRIs are used for hot flashes when HRT is contraindicated. GnRH agonists induce medical menopause and cause hot flashes rather than treat them.'),
  ('hormonal', 43, 'A nurse is reviewing the histories of four menopausal clients who are requesting hormone replacement therapy for hot flashes. For which client should the nurse question the plan for HRT?', '[{"id": "a", "text": "A 54-year-old with new, unexplained vaginal bleeding"}, {"id": "b", "text": "A 51-year-old with night sweats and sleep disruption"}, {"id": "c", "text": "A 49-year-old who had a hysterectomy for fibroids"}, {"id": "d", "text": "A 56-year-old with vaginal dryness and low libido"}]'::jsonb, '["a"]', 'Unexplained vaginal bleeding is a contraindication to HRT, along with breast or uterine cancer history, DVT/PE, liver disease, and stroke. Night sweats, vaginal dryness, and a prior hysterectomy are not contraindications.'),
  ('hormonal', 44, 'A nurse teaches a 55-year-old postmenopausal client about preventing osteoporosis. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will take vitamin D along with my calcium supplement."}, {"id": "b", "text": "I will aim for about 1200 mg of calcium each day."}, {"id": "c", "text": "I will walk briskly for exercise on most days of the week."}, {"id": "d", "text": "I will swim instead of doing weight-bearing exercise."}]'::jsonb, '["d"]', 'Osteoporosis prevention after menopause includes weight-bearing exercise, calcium 1200 mg/day, and vitamin D, so replacing weight-bearing activity shows a misunderstanding. Brisk walking is a weight-bearing exercise.'),
  ('hormonal', 45, 'A 46-year-old client reports that over the past year her cycles have varied from 21 to 50 days and that she has begun having hot flashes. Her last period was 6 weeks ago, and her pregnancy test is negative. Which conclusion by the nurse is MOST accurate?', '[{"id": "a", "text": "She has reached menopause because her cycles have become irregular"}, {"id": "b", "text": "Her findings are consistent with perimenopause, before menopause"}, {"id": "c", "text": "Her findings suggest PMDD because her symptoms are hormone related"}, {"id": "d", "text": "She has primary amenorrhea because her periods have stopped"}]'::jsonb, '["b"]', 'Perimenopause is the 2–10 year transition before menopause, with irregular cycles, fluctuating hormones, and beginning vasomotor symptoms. Menopause requires 12 consecutive months without a period.'),
  ('hormonal', 46, 'A 57-year-old postmenopausal client reports vaginal dryness and painful intercourse but has no hot flashes. She has no HRT contraindications. Which treatment should the nurse anticipate for her symptoms?', '[{"id": "a", "text": "Vaginal estrogen cream to treat vaginal atrophy"}, {"id": "b", "text": "An SSRI to treat vaginal atrophy and dryness"}, {"id": "c", "text": "Spironolactone to treat vaginal atrophy and dryness"}, {"id": "d", "text": "Tranexamic acid to treat vaginal atrophy and dryness"}]'::jsonb, '["a"]', 'Vaginal atrophy with dryness and dyspareunia is a menopausal symptom treated with vaginal estrogen cream. SSRIs are used for hot flashes when HRT is contraindicated, not for vaginal atrophy.'),
  ('hormonal', 47, 'A client who is 2 weeks postpartum is breastfeeding and asks which hormones are responsible for making her milk and for releasing it when her infant begins to nurse. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Prolactin stimulates milk production, and oxytocin causes let-down"}, {"id": "b", "text": "Oxytocin stimulates milk production, and prolactin causes let-down"}, {"id": "c", "text": "Estrogen stimulates milk production, and progesterone causes let-down"}, {"id": "d", "text": "hCG stimulates milk production, and LH causes the let-down reflex"}]'::jsonb, '["a"]', 'Prolactin from the anterior pituitary stimulates breast milk production, and oxytocin from the posterior pituitary causes the milk let-down reflex. Reversing the two roles is the most common error.'),
  ('hormonal', 48, 'A 52-year-old client who has had no period for 13 months asks why her FSH level is high when her ovaries are making less hormone. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Her ovaries are producing extra FSH to make up for lost estrogen"}, {"id": "b", "text": "High FSH shows that she is still ovulating every month"}, {"id": "c", "text": "High FSH shows that her pituitary has stopped responding to GnRH"}, {"id": "d", "text": "Her pituitary is stimulating ovaries that no longer respond"}]'::jsonb, '["d"]', 'FSH rises in menopause because the hypothalamus and pituitary keep trying to stimulate non-responsive ovaries. FSH comes from the anterior pituitary, not the ovaries.'),
  ('hormonal', 49, 'A nurse in a gynecology clinic reviews four clients who report painful periods. Which client''s history is MOST suggestive of secondary rather than primary dysmenorrhea?', '[{"id": "a", "text": "A 17-year-old whose cramps start the day before flow and last 2 days"}, {"id": "b", "text": "A 36-year-old whose cramps have grown steadily worse over 4 years"}, {"id": "c", "text": "A 19-year-old whose cramps ease with an NSAID and a heating pad"}, {"id": "d", "text": "A 15-year-old whose cramps began within a year of her first period"}]'::jsonb, '["b"]', 'Secondary dysmenorrhea is caused by conditions such as endometriosis, fibroids, or PID, and its pain worsens over time. Cramps starting 1–2 days before flow and lasting 2–3 days that respond to NSAIDs and heat fit primary dysmenorrhea.'),
  ('hormonal', 50, 'A nurse receives four telephone messages from clients in a women''s health practice. Which client should the nurse call back FIRST?', '[{"id": "a", "text": "A 51-year-old with night sweats that disrupt her sleep"}, {"id": "b", "text": "A 24-year-old with acne and periods every 40 days"}, {"id": "c", "text": "A 37-year-old soaking a pad hourly who is now dizzy"}, {"id": "d", "text": "A 28-year-old with bloating and breast tenderness"}]'::jsonb, '["c"]', 'Soaking a pad every hour is abnormal heavy bleeding, and dizziness is a sign of anemia, making this client the priority. Night sweats, PCOS-type findings, and PMS symptoms are not urgent.'),
  ('menstrual', 1, 'A client with regular 28-day cycles is tracking her body changes. On cycle day 9 she reports that her bleeding stopped 4 days ago and that her cervical mucus is becoming thinner and clearer each day. Which hormonal process BEST explains what she describes?', '[{"id": "a", "text": "Rising estrogen from the maturing follicle is rebuilding the lining"}, {"id": "b", "text": "Rising progesterone from the corpus luteum is thickening the endometrium"}, {"id": "c", "text": "The LH surge is releasing the egg from the dominant Graafian follicle"}, {"id": "d", "text": "Falling FSH is signaling the corpus luteum to begin degenerating"}]'::jsonb, '["a"]', 'Days 6–13 are the proliferative (follicular) phase, when the maturing follicle produces rising estrogen that rebuilds the endometrium and thins the mucus. Progesterone from the corpus luteum dominates only after ovulation (days 15–28).'),
  ('menstrual', 2, 'A client with regular 28-day cycles charts her basal body temperature (BBT). Readings were 97.3–97.6°F during the first 2 weeks, dipped slightly on day 13, and rose 0.5°F on day 15. It is now day 33, she has had no bleeding, and her BBT remains elevated. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Estrogen is peaking, so an LH surge and ovulation should follow shortly"}, {"id": "b", "text": "The corpus luteum has degenerated, so bleeding should start within a day"}, {"id": "c", "text": "Progesterone is remaining high, a pattern consistent with pregnancy"}, {"id": "d", "text": "Her temperature is at the expected non-fertile follicular baseline"}]'::jsonb, '["c"]', 'The post-ovulation BBT rise is a progesterone effect and stays elevated if pregnant, so a sustained rise with no period fits pregnancy. If the corpus luteum had degenerated, progesterone would fall and menstruation would begin.'),
  ('menstrual', 3, 'A client with 28-day cycles who is trying to conceive has charted her basal body temperature for 2 months. She asks which chart change tells her that ovulation is about to happen rather than already over. Which response by the nurse is BEST?', '[{"id": "a", "text": "A rise of 0.4–0.6°F above your usual baseline"}, {"id": "b", "text": "A slight dip below your usual baseline reading"}, {"id": "c", "text": "A steady reading between 97.2°F and 97.7°F"}, {"id": "d", "text": "A reading that stays elevated for about 2 weeks"}]'::jsonb, '["b"]', 'BBT shows a slight dip just before ovulation and then rises 0.4–0.6°F after ovulation. The rise therefore confirms ovulation has already occurred and cannot be used to predict it.'),
  ('menstrual', 4, 'On cycle day 7, a client using fertility awareness reports that her cervix feels low, firm, and closed and that her cervical mucus is thick, sticky, and opaque. She asks what these findings mean for conception. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "These are fertile signs; this mucus helps sperm travel to the egg"}, {"id": "b", "text": "Your LH surge just occurred, and the egg is viable for about a day"}, {"id": "c", "text": "These signs mean ovulation is imminent and will occur within hours"}, {"id": "d", "text": "These are non-fertile signs; this type of mucus blocks sperm"}]'::jsonb, '["d"]', 'A low, firm, closed cervix with dry, thick, sticky, opaque mucus is the non-fertile pattern, and this mucus blocks sperm. Wet, slippery, clear, stretchy mucus with a soft, high, open cervix is the fertile pattern.'),
  ('menstrual', 5, 'A couple using fertility awareness wants to avoid pregnancy. On cycle day 13 of a 28-day cycle, the client reports her cervix feels high, soft, and open and her mucus is wet, clear, and stretches between her fingers. Which advice by the nurse is BEST?', '[{"id": "a", "text": "Avoid unprotected intercourse now, because these are peak fertility signs"}, {"id": "b", "text": "Unprotected intercourse is safe now, because the cervix is in a non-fertile state"}, {"id": "c", "text": "Unprotected intercourse is safe now, because these signs mean the egg is gone"}, {"id": "d", "text": "Avoid unprotected intercourse once the mucus turns thick, sticky, and opaque"}]'::jsonb, '["a"]', 'Egg-white, stretchy mucus with a soft, high, open, wet cervix indicates peak fertility because ovulation is imminent or just occurred. Thick, sticky, opaque mucus is the non-fertile pattern, so abstaining at that point would be mistimed.'),
  ('menstrual', 6, 'A client with regular 28-day cycles who wants to conceive says that this month she and her partner can be together on either cycle day 11 or cycle day 18. She asks which day gives the better chance of pregnancy. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Day 18, because the egg stays viable until the corpus luteum forms"}, {"id": "b", "text": "Day 18, because progesterone peaks then and supports implantation"}, {"id": "c", "text": "Day 11, because sperm can survive 3–5 days until ovulation occurs"}, {"id": "d", "text": "Neither day, because conception requires intercourse on day 14 itself"}]'::jsonb, '["c"]', 'Ovulation occurs on day 14, and sperm remain viable about 3–5 days, so sperm from day 11 can still meet the egg. The egg is viable only about 12–24 hours, so by day 18 it is no longer available for fertilization.'),
  ('menstrual', 7, 'A nurse teaches a client and her partner about using the timing of ovulation to plan a pregnancy in a regular 28-day cycle. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Clear, stretchy mucus means ovulation is near or has just happened."}, {"id": "b", "text": "Once released, my egg can be fertilized for several days afterward."}, {"id": "c", "text": "Sperm from intercourse 2 days before ovulation may still fertilize."}, {"id": "d", "text": "A sustained temperature rise of about half a degree follows ovulation."}]'::jsonb, '["b"]', 'The egg is viable only about 12–24 hours after release, so believing it can be fertilized for several days shows a misunderstanding. Sperm, not the egg, survive about 3–5 days, which is why intercourse before ovulation can result in pregnancy.'),
  ('menstrual', 8, 'A client with regular 28-day cycles has had a sustained basal body temperature elevation since cycle day 15. On the morning of day 27, her temperature falls back to her usual baseline of 97.4°F. Which event should the nurse anticipate NEXT?', '[{"id": "a", "text": "An LH surge followed by release of an egg within the next day"}, {"id": "b", "text": "Formation of a corpus luteum followed by rising progesterone"}, {"id": "c", "text": "Thin, clear, stretchy cervical mucus appearing within a day"}, {"id": "d", "text": "Onset of menstrual bleeding as progesterone levels decline"}]'::jsonb, '["d"]', 'The BBT elevation is a progesterone effect, so a return to baseline reflects falling progesterone as the corpus luteum degenerates, which triggers menstruation. An LH surge and corpus luteum formation occur mid-cycle, not at the end of the secretory phase.'),
  ('menstrual', 9, 'A client with regular 28-day cycles has a positive home pregnancy test on what would have been cycle day 32. She asks why she has not had a period this month. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "hCG keeps the corpus luteum active, so progesterone stays high"}, {"id": "b", "text": "Estrogen stays at its peak, which stops the lining from shedding"}, {"id": "c", "text": "The LH surge continues, so the follicle keeps releasing hormones"}, {"id": "d", "text": "FSH rises steadily, which keeps the endometrium firmly intact"}]'::jsonb, '["a"]', 'In early pregnancy hCG maintains the corpus luteum, which keeps progesterone high and prevents the period. Without that rescue, the corpus luteum degenerates and the progesterone drop triggers menstruation.'),
  ('menstrual', 10, 'A client undergoing a fertility workup has hormone levels drawn at a single visit. Results show progesterone at its highest level of the cycle, estrogen at a moderate level, and both FSH and LH low. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Proliferative phase; estrogen is rebuilding the recently shed lining"}, {"id": "b", "text": "Ovulation; the LH surge is releasing the egg from the follicle"}, {"id": "c", "text": "Secretory phase; the endometrium is preparing for implantation"}, {"id": "d", "text": "Menstrual phase; falling hormone levels are triggering shedding"}]'::jsonb, '["c"]', 'Low FSH and LH, moderate estrogen, and peak progesterone match the secretory (luteal) phase, when the corpus luteum''s progesterone thickens the endometrium for implantation. The proliferative phase has peaking estrogen with low progesterone.'),
  ('menstrual', 11, 'A client with regular 28-day cycles has blood drawn on cycle day 3 while she is actively bleeding. She asks what her hormone results are likely to show at this point. Which hormone pattern should the nurse expect?', '[{"id": "a", "text": "Estrogen at its peak with LH beginning to surge"}, {"id": "b", "text": "FSH rising while estrogen and progesterone are low"}, {"id": "c", "text": "Progesterone at its peak with FSH remaining low"}, {"id": "d", "text": "Estrogen moderate while progesterone is still rising"}]'::jsonb, '["b"]', 'During the menstrual phase (days 1–5), FSH is rising while estrogen and progesterone are low. Peak progesterone belongs to the secretory phase, and the estrogen peak with LH surge occurs around days 12–14.'),
  ('menstrual', 12, 'A client who is not pregnant reports that her basal body temperature dropped back to baseline this morning and her period is expected in 2 days. Which hormone pattern does the nurse expect in this late part of her cycle?', '[{"id": "a", "text": "FSH low, LH surging, and estrogen at its peak"}, {"id": "b", "text": "FSH falling, estrogen rising, and progesterone low"}, {"id": "c", "text": "FSH low, estrogen moderate, and progesterone peaking"}, {"id": "d", "text": "FSH rising; estrogen, progesterone falling"}]'::jsonb, '["d"]', 'In the late secretory/premenstrual phase FSH begins rising again while estrogen and progesterone fall, which triggers the period. Peak progesterone with moderate estrogen describes the earlier secretory phase, before the BBT falls.'),
  ('menstrual', 13, 'A client beginning a fertility evaluation asks the nurse to explain how her body gets from the start of the cycle to releasing an egg. Which sequence of events should the nurse describe as correct?', '[{"id": "a", "text": "GnRH → FSH and LH → follicle matures → estrogen rises → LH surge"}, {"id": "b", "text": "GnRH → LH surge → follicle matures → estrogen rises → FSH released"}, {"id": "c", "text": "FSH and LH → GnRH → estrogen rises → follicle matures → LH surge"}, {"id": "d", "text": "GnRH → FSH and LH → estrogen rises → LH surge → follicle matures"}]'::jsonb, '["a"]', 'The hypothalamus releases GnRH, which releases FSH and LH; the follicle matures and produces estrogen, and rising estrogen leads to the LH surge that causes ovulation. A follicle must mature before the estrogen rise and LH surge, not after.'),
  ('menstrual', 14, 'A transvaginal ultrasound on a client being evaluated for infertility shows a corpus luteum on the right ovary. Which uterine phase and endometrial change should the nurse expect to correspond with this finding?', '[{"id": "a", "text": "Proliferative phase; the lining rebuilds under estrogen"}, {"id": "b", "text": "Menstrual phase; the stratum functionalis is shedding"}, {"id": "c", "text": "Secretory phase; the lining thickens under progesterone"}, {"id": "d", "text": "Proliferative phase; the lining thickens under progesterone"}]'::jsonb, '["c"]', 'The corpus luteum forms after ovulation and secretes progesterone, which thickens and prepares the endometrium during the secretory (luteal) phase. Estrogen-driven rebuilding is the proliferative phase, before a corpus luteum exists.'),
  ('menstrual', 15, 'A client tracking her cycle asks whether her ovaries and her uterine lining follow two separate hormonal schedules, one finishing before the other starts. Which response by the nurse is BEST?', '[{"id": "a", "text": "The ovarian cycle finishes first, and the uterine cycle then begins"}, {"id": "b", "text": "Both cycles occur at the same time and are driven by the same hormones"}, {"id": "c", "text": "The uterine cycle is driven by FSH, and the ovarian cycle by progesterone"}, {"id": "d", "text": "Each cycle has its own hormones, so the two can run out of step"}]'::jsonb, '["b"]', 'The uterine and ovarian cycles happen simultaneously and are driven by the same hormones; for example, estrogen drives both follicular growth and endometrial proliferation. They do not occur in sequence or under separate hormones.'),
  ('menstrual', 16, 'A client with regular 28-day cycles in a fertility program has labs on cycle day 12 showing estrogen at the highest level of her cycle so far, while her LH remains low and progesterone is low. Which event should the nurse anticipate NEXT?', '[{"id": "a", "text": "Formation of the corpus luteum with a progesterone peak"}, {"id": "b", "text": "Menstrual shedding caused by the falling estrogen level"}, {"id": "c", "text": "A rise in FSH that begins stimulating a new set of follicles"}, {"id": "d", "text": "An LH surge that releases the egg from the follicle"}]'::jsonb, '["d"]', 'Estrogen peaks on days 12–13, and the estrogen peak triggers the LH surge that releases the egg on day 14. The corpus luteum and its progesterone peak follow ovulation, so they come later.'),
  ('menstrual', 17, 'A client with regular 28-day cycles who wants to conceive reports a positive home LH test on the morning of cycle day 13. Which teaching by the nurse is MOST accurate?', '[{"id": "a", "text": "The egg is likely to be released soon, so fertility is at its peak"}, {"id": "b", "text": "The egg was likely released last week, so this cycle''s chance has passed"}, {"id": "c", "text": "Progesterone is now at its peak, so the lining is ready for implantation"}, {"id": "d", "text": "The corpus luteum has already degenerated, so a period will start soon"}]'::jsonb, '["a"]', 'The LH surge triggers release of the egg on about day 14, so a positive LH test on day 13 signals imminent ovulation and peak fertility. Progesterone peaks later, in the secretory phase after the corpus luteum forms.'),
  ('menstrual', 18, 'A client with regular 28-day cycles is on cycle day 2 of her menstrual bleeding. She asks the nurse what tissue is actually leaving her body with the blood. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The muscular layer of the uterus is breaking down and shedding"}, {"id": "b", "text": "The corpus luteum is passing out along with the uterine lining"}, {"id": "c", "text": "The stratum functionalis of the endometrium is being shed"}, {"id": "d", "text": "The unfertilized dominant follicle is passing with the blood"}]'::jsonb, '["c"]', 'During the menstrual phase (days 1–5) the endometrium sheds its stratum functionalis. The corpus luteum is an ovarian structure that degenerates; it is not shed with the lining.'),
  ('menstrual', 19, 'A client in a fertility program has a low progesterone level 7 days after an ovulation confirmed by ultrasound. The nurse recognizes that this finding MOST directly threatens which process needed for pregnancy?', '[{"id": "a", "text": "Maturation of the dominant Graafian follicle"}, {"id": "b", "text": "Maintenance of the endometrium for implantation"}, {"id": "c", "text": "Triggering of the mid-cycle LH surge for ovulation"}, {"id": "d", "text": "Thinning of cervical mucus for sperm passage"}]'::jsonb, '["b"]', 'Progesterone from the corpus luteum is the hormone that maintains the endometrium for pregnancy, so low luteal progesterone threatens implantation. Follicle maturation, the LH surge, and mucus thinning are pre-ovulatory estrogen- and FSH-driven events.'),
  ('menstrual', 20, 'A client with regular 28-day cycles has labs drawn on cycle day 3 and again on cycle day 11. The day 11 result shows estrogen rising steeply and FSH lower than it was on day 3. She asks whether the falling FSH is a problem. Which response by the nurse is BEST?', '[{"id": "a", "text": "The FSH drop suggests the follicle stopped growing and needs evaluation"}, {"id": "b", "text": "The pattern shows the corpus luteum is degenerating ahead of schedule"}, {"id": "c", "text": "Estrogen this high this early in the cycle suggests she is pregnant"}, {"id": "d", "text": "This is expected; FSH falls as the dominant follicle matures"}]'::jsonb, '["d"]', 'In the proliferative phase FSH falls as the follicle matures while estrogen rises toward its day 12–13 peak, so this pattern is expected. Corpus luteum degeneration occurs at the end of the secretory phase, not on day 11.'),
  ('menstrual', 21, 'A client is 30 weeks pregnant. Four years ago she delivered twins at 35 weeks, and both children are living and well. Two years ago she had a miscarriage at 8 weeks. Which GTPAL notation should the nurse document?', '[{"id": "a", "text": "G3 T0 P2 A1 L2"}, {"id": "b", "text": "G3 T0 P1 A1 L2"}, {"id": "c", "text": "G2 T0 P1 A1 L2"}, {"id": "d", "text": "G4 T0 P2 A1 L2"}]'::jsonb, '["b"]', 'Gravida counts the current pregnancy, the twin pregnancy, and the miscarriage (G3); twins born at 35 weeks count as one preterm birth (P1); the 8-week loss is A1; and each living twin is counted (L2). Counting the twins as two preterm births is the common error.'),
  ('menstrual', 22, 'A client at 12 weeks of gestation reports an ectopic pregnancy at 7 weeks 3 years ago, a daughter born at 38 weeks who is living, and a son born at 34 weeks who died at 2 days of age. Which GTPAL notation is MOST accurate?', '[{"id": "a", "text": "G3 T1 P1 A1 L1"}, {"id": "b", "text": "G4 T1 P1 A0 L2"}, {"id": "c", "text": "G4 T2 P0 A1 L1"}, {"id": "d", "text": "G4 T1 P1 A1 L1"}]'::jsonb, '["d"]', 'Gravida includes the current pregnancy and the ectopic (G4); the 38-week birth is term (T1); the 34-week birth is preterm (P1) even though the son died; the ectopic is a loss before 20 weeks (A1); and only one child is living (L1).'),
  ('menstrual', 23, 'A client gave birth to a healthy infant at 37 weeks of gestation today. Her first child was born at 36 weeks, and she had an elective abortion at 9 weeks between the two births. Both children are living. Which GTPAL notation should the nurse record?', '[{"id": "a", "text": "G3 T2 P0 A1 L2"}, {"id": "b", "text": "G2 T1 P1 A1 L2"}, {"id": "c", "text": "G3 T1 P1 A1 L2"}, {"id": "d", "text": "G3 T1 P1 A0 L2"}]'::jsonb, '["c"]', 'Today''s 37-week birth is term (T1) because term is 37 weeks or more, while the 36-week birth is preterm (P1). The elective abortion counts as both a pregnancy (G3) and a loss before 20 weeks (A1).'),
  ('menstrual', 24, 'A client at 16 weeks of gestation reports that her first pregnancy ended with a stillborn infant delivered at 22 weeks and that her second pregnancy produced a daughter born at 40 weeks who is living. Which GTPAL notation is MOST accurate?', '[{"id": "a", "text": "G3 T1 P1 A0 L1"}, {"id": "b", "text": "G3 T1 P0 A1 L1"}, {"id": "c", "text": "G2 T1 P1 A0 L1"}, {"id": "d", "text": "G3 T1 P0 A1 L2"}]'::jsonb, '["a"]', 'A delivery at 22 weeks falls in the 20–36 week range, so it is a preterm birth (P1), not an abortion, which is a loss before 20 weeks. The current pregnancy is included in G3, and only the daughter is living (L1).'),
  ('menstrual', 25, 'A client at 10 weeks of gestation reviews her chart and sees T1 and L2 in her GTPAL. Her only previous pregnancy produced twins born at 39 weeks, and both are living. She asks whether the numbers are a mistake. Which response by the nurse is BEST?', '[{"id": "a", "text": "Twins count as two term births, so T should be corrected to T2"}, {"id": "b", "text": "L includes the current pregnancy, which is why it reads as L2"}, {"id": "c", "text": "Twins count as one birth for T, but each living twin counts in L"}, {"id": "d", "text": "T counts each delivery after 20 weeks, and L counts each pregnancy"}]'::jsonb, '["c"]', 'A twin delivery counts as one birth for T or P, but each living child is counted individually for L, so T1 L2 is correct. The current pregnancy is counted in gravida, not in living children.'),
  ('menstrual', 26, 'A client at 8 weeks of gestation reports an elective termination at 11 weeks, a spontaneous loss at 18 weeks, and a son born at 41 weeks who is living. Which GTPAL notation should the nurse document?', '[{"id": "a", "text": "G4 T1 P0 A1 L1"}, {"id": "b", "text": "G4 T1 P0 A2 L1"}, {"id": "c", "text": "G3 T1 P0 A2 L1"}, {"id": "d", "text": "G4 T1 P1 A1 L1"}]'::jsonb, '["b"]', 'Both the elective termination and the spontaneous loss occurred before 20 weeks, so each counts under A (A2). With the current pregnancy the client is G4, and the 41-week birth is term (T1).'),
  ('menstrual', 27, 'A client is 24 weeks pregnant. Three years ago she delivered triplets at 32 weeks; one triplet died in the neonatal period and two are living. She has had no other pregnancies. Which GTPAL notation is MOST accurate?', '[{"id": "a", "text": "G2 T0 P3 A0 L2"}, {"id": "b", "text": "G4 T0 P1 A0 L3"}, {"id": "c", "text": "G2 T0 P1 A1 L2"}, {"id": "d", "text": "G2 T0 P1 A0 L2"}]'::jsonb, '["d"]', 'The triplet delivery is one pregnancy and one preterm birth (P1), and only the two surviving children count toward L2. With the current pregnancy the client is G2; there were no losses before 20 weeks (A0).'),
  ('menstrual', 28, 'A nurse reviews GTPAL entries a nursing student documented for four clients on a prenatal unit. Which entry requires correction?', '[{"id": "a", "text": "Prior birth at 36 weeks, child living, now 20 weeks: G2 T1 P0 A0 L1"}, {"id": "b", "text": "Twins born at 38 weeks, both living, not pregnant now: G1 T1 P0 A0 L2"}, {"id": "c", "text": "Miscarriage at 12 weeks, now 15 weeks pregnant: G2 T0 P0 A1 L0"}, {"id": "d", "text": "First pregnancy, currently 9 weeks, no prior losses: G1 T0 P0 A0 L0"}]'::jsonb, '["a"]', 'A birth at 36 weeks is preterm (20–36 weeks), so that client should be G2 T0 P1 A0 L1. The twin entry correctly counts one term birth and two living children.'),
  ('menstrual', 29, 'A client who has stopped having regular cycles is found to have markedly reduced release of GnRH from the hypothalamus. Which downstream effect should the nurse anticipate FIRST in the hormonal sequence?', '[{"id": "a", "text": "Increased progesterone output from the corpus luteum"}, {"id": "b", "text": "An early LH surge followed by premature ovulation"}, {"id": "c", "text": "Reduced release of FSH and LH to stimulate the follicle"}, {"id": "d", "text": "Increased estrogen that rapidly rebuilds the endometrium"}]'::jsonb, '["c"]', 'GnRH from the hypothalamus is the first step and causes release of FSH and LH, so reduced GnRH first lowers FSH and LH. Without them the follicle cannot mature, so the estrogen rise, LH surge, and corpus luteum progesterone downstream would also fail.'),
  ('menstrual', 30, 'A nurse teaches a client with regular 28-day cycles about the order of hormonal events in her cycle. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Estrogen from my maturing follicle rebuilds my lining after my period."}, {"id": "b", "text": "My LH surge happens after the corpus luteum has already formed."}, {"id": "c", "text": "Progesterone from the corpus luteum prepares my lining for a pregnancy."}, {"id": "d", "text": "A drop in progesterone when the corpus luteum fails starts my period."}]'::jsonb, '["b"]', 'The LH surge on day 14 causes ovulation, and the corpus luteum forms afterward from that event, so the client has the order reversed. The other statements correctly link estrogen to rebuilding, progesterone to preparation, and the progesterone drop to menstruation.'),
  ('menstrual', 31, 'A client with regular 28-day cycles has a pelvic ultrasound on cycle day 10 that shows one enlarging dominant follicle while several smaller follicles are regressing. She asks what is causing this and what the follicle will do. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "FSH is maturing it, and it will secrete rising estrogen"}, {"id": "b", "text": "LH is maturing it, and the follicle will secrete progesterone now"}, {"id": "c", "text": "Progesterone is maturing it, and the follicle will release hCG"}, {"id": "d", "text": "GnRH is acting on it directly, and the follicle will release FSH"}]'::jsonb, '["a"]', 'During the proliferative (follicular) phase, FSH stimulates follicles to mature into one dominant Graafian follicle, which produces rising estrogen. Progesterone comes from the corpus luteum after ovulation, not from the maturing follicle.'),
  ('menstrual', 32, 'A client with regular 28-day cycles who has just started charting her basal body temperature reads 97.5°F on cycle day 7. She is worried the reading is too low and asks whether something is wrong with her cycle. Which response by the nurse is BEST?', '[{"id": "a", "text": "A reading this low suggests ovulation has already passed this cycle"}, {"id": "b", "text": "A reading this low suggests your progesterone level is elevated today"}, {"id": "c", "text": "A reading this low suggests estrogen failed to rise early in this cycle"}, {"id": "d", "text": "This reading falls within the expected baseline before ovulation"}]'::jsonb, '["d"]', 'The normal non-fertile baseline BBT is about 97.2–97.7°F, so 97.5°F on day 7 is expected. A progesterone effect would raise the BBT 0.4–0.6°F, which occurs after ovulation.'),
  ('menstrual', 33, 'A client with regular 28-day cycles is on cycle day 17. She asks whether her uterine lining is still in the rebuilding stage that follows her period. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "The lining is still rebuilding under estrogen from the growing follicle"}, {"id": "b", "text": "The lining is now thickening under progesterone to prepare for implantation"}, {"id": "c", "text": "The lining is shedding because estrogen and progesterone are both low"}, {"id": "d", "text": "The lining is rebuilding because FSH reaches its highest level at this point"}]'::jsonb, '["b"]', 'Day 17 is in the secretory (luteal) phase, days 15–28, when progesterone from the corpus luteum thickens and prepares the endometrium for implantation. Estrogen-driven rebuilding occurs during the proliferative phase, days 6–13.'),
  ('menstrual', 34, 'A client with regular 28-day cycles noted wet, clear, stretchy cervical mucus on cycle day 13. On cycle day 16 she reports that her mucus is thick, sticky, and opaque again. Which conclusion by the nurse is MOST accurate?', '[{"id": "a", "text": "She is approaching ovulation and should expect her LH surge soon"}, {"id": "b", "text": "She is in the menstrual phase, as estrogen and progesterone are low"}, {"id": "c", "text": "Ovulation has passed; she is in the secretory (luteal) phase"}, {"id": "d", "text": "Her corpus luteum has degenerated, and FSH has begun to rise again"}]'::jsonb, '["c"]', 'Fertile egg-white mucus around day 13 followed by a return to non-fertile thick mucus on day 16 places her after ovulation, in the secretory (luteal) phase of days 15–28. Corpus luteum degeneration and a rising FSH occur late in that phase, just before menstruation.'),
  ('menstrual', 35, 'A client in a fertility program with regular 28-day cycles has labs drawn on a single morning. LH is markedly elevated compared with the previous day, estrogen is slightly lower than its peak the day before, and progesterone remains low. Which event should the nurse recognize is occurring?', '[{"id": "a", "text": "Ovulation, triggered by the surge in LH"}, {"id": "b", "text": "Menstruation, triggered by falling estrogen"}, {"id": "c", "text": "Corpus luteum degeneration in the late cycle"}, {"id": "d", "text": "Early follicle recruitment under rising FSH"}]'::jsonb, '["a"]', 'On day 14 LH surges to trigger ovulation while estrogen shows a slight drop after its day 12–13 peak and progesterone is still low. Menstruation requires a fall in progesterone, which has not yet risen in this cycle.'),
  ('menstrual', 36, 'A client with regular 28-day cycles uses fertility awareness to avoid pregnancy. She states she plans to avoid unprotected intercourse on cycle day 14 because that is the day she ovulates. Which teaching by the nurse is the PRIORITY?', '[{"id": "a", "text": "Avoiding day 14 is sufficient because the egg survives under a day"}, {"id": "b", "text": "She should begin avoiding intercourse the day her temperature rises"}, {"id": "c", "text": "She should avoid intercourse during her days of menstrual bleeding"}, {"id": "d", "text": "Sperm live 3–5 days, so earlier intercourse can cause pregnancy"}]'::jsonb, '["d"]', 'Sperm remain viable about 3–5 days, so intercourse in the days before ovulation can still result in fertilization. Although the egg survives only 12–24 hours, avoiding just the day of ovulation ignores sperm survival.'),
  ('menstrual', 37, 'A client with regular 28-day cycles has a pelvic ultrasound on cycle day 8. It shows a maturing follicle on the left ovary and an endometrium that is thin but beginning to thicken. Which pairing of ovarian and uterine phases should the nurse identify?', '[{"id": "a", "text": "Luteal ovarian phase with secretory uterine phase"}, {"id": "b", "text": "Follicular ovarian phase with proliferative uterine phase"}, {"id": "c", "text": "Follicular ovarian phase with secretory uterine phase"}, {"id": "d", "text": "Luteal ovarian phase with proliferative uterine phase"}]'::jsonb, '["b"]', 'A maturing follicle places the ovary in the follicular phase, and an endometrium rebuilding under the follicle''s estrogen is the proliferative uterine phase. The secretory phase pairs with the luteal phase after a corpus luteum forms.'),
  ('menstrual', 38, 'A client who is trying to conceive asks the nurse which hormone rises first in each new cycle and how the other hormones follow. Which order of events should the nurse describe as MOST accurate?', '[{"id": "a", "text": "Estrogen rises first, then FSH, then progesterone, then the LH surge"}, {"id": "b", "text": "LH surges first, then FSH, then estrogen rises, then progesterone"}, {"id": "c", "text": "Progesterone rises first, then estrogen, then FSH, then the LH surge"}, {"id": "d", "text": "FSH rises first, then estrogen, then LH surge, then progesterone"}]'::jsonb, '["d"]', 'FSH peaks early to stimulate the follicle, the follicle then raises estrogen, the estrogen peak triggers the LH surge, and progesterone rises from the corpus luteum after ovulation. Estrogen cannot rise first because it depends on FSH-stimulated follicle growth.'),
  ('menstrual', 39, 'A client with regular 28-day cycles in a fertility evaluation has a serum progesterone drawn on cycle day 10 that is low. She is worried that her body is not making enough progesterone. Which interpretation by the nurse is MOST appropriate?', '[{"id": "a", "text": "It signals failed ovulation and needs immediate follow-up"}, {"id": "b", "text": "It shows the corpus luteum is degenerating ahead of schedule"}, {"id": "c", "text": "It is expected because progesterone rises after ovulation"}, {"id": "d", "text": "It shows the endometrium is being prepared for implantation"}]'::jsonb, '["c"]', 'Progesterone rises only after ovulation, when the corpus luteum forms, so a low level on day 10 of the proliferative phase is expected. Day 10 is before ovulation, so it cannot yet show whether ovulation failed.'),
  ('menstrual', 40, 'A client with regular 28-day cycles has labs drawn on cycle day 22 that show low FSH and low LH. She has read that these hormones control her ovaries and is worried her pituitary is failing. Which response by the nurse is BEST?', '[{"id": "a", "text": "Low FSH and LH are expected now, while progesterone is at its peak"}, {"id": "b", "text": "Low FSH and LH suggest the follicle never matured during this cycle"}, {"id": "c", "text": "Low FSH and LH show that menstruation has already begun this cycle"}, {"id": "d", "text": "Low FSH and LH show that the LH surge will occur within the next day"}]'::jsonb, '["a"]', 'In the secretory phase (days 15–28) FSH and LH are both low while progesterone peaks, so these results are expected. FSH begins rising again only in the late secretory/premenstrual phase, and the LH surge occurs on day 14.'),
  ('menstrual', 41, 'A client with irregular cycles has labs showing that her estrogen failed to rise during the first half of her cycle. Which pair of consequences should the nurse anticipate from this finding?', '[{"id": "a", "text": "Early corpus luteum formation and a thick secretory lining"}, {"id": "b", "text": "Poor follicle growth and a poorly rebuilt endometrium"}, {"id": "c", "text": "A premature LH surge followed by early release of the egg"}, {"id": "d", "text": "A high progesterone level and a sustained temperature rise"}]'::jsonb, '["b"]', 'Estrogen drives both follicular growth and endometrial proliferation, so failure of estrogen to rise affects both the follicle and the lining. The LH surge is triggered by the estrogen peak, so it would not occur prematurely.'),
  ('menstrual', 42, 'A client who has been trying to conceive for several months shows the nurse her basal body temperature chart for an entire cycle. Every reading stayed between 97.3°F and 97.6°F, with no sustained rise at any point. Which conclusion is MOST supported by this chart?', '[{"id": "a", "text": "She ovulated, and her corpus luteum is producing progesterone"}, {"id": "b", "text": "She is pregnant, because her temperature has remained steady"}, {"id": "c", "text": "No progesterone rise occurred, so she may not have ovulated"}, {"id": "d", "text": "Her estrogen peaked late, which caused progesterone to peak early"}]'::jsonb, '["c"]', 'After ovulation, progesterone''s thermogenic effect raises the BBT 0.4–0.6°F, so a chart that stays at baseline shows no progesterone rise and suggests ovulation may not have occurred. A pregnancy pattern is a temperature that rises and stays elevated, not one that never rises.'),
  ('menstrual', 43, 'A client with regular 28-day cycles who wants to conceive tells the nurse she plans to wait until her basal body temperature rises before having intercourse, so she can be sure she has ovulated. Which response by the nurse is BEST?', '[{"id": "a", "text": "That works well, because the rise shows the egg is about to be released"}, {"id": "b", "text": "That works well, because the rise means the lining is ready for the embryo"}, {"id": "c", "text": "Not ideal; the rise means the corpus luteum has already degenerated"}, {"id": "d", "text": "Not ideal; the rise follows ovulation and the egg lives about a day"}]'::jsonb, '["d"]', 'The BBT rises after ovulation, and the egg is viable only about 12–24 hours, so waiting for the rise may miss the fertile time. Corpus luteum degeneration lowers progesterone and the temperature rather than raising it.'),
  ('menstrual', 44, 'A client with regular 28-day cycles is on cycle day 2 of her period. She asks whether anything is already happening in her body to prepare for the next ovulation while she is still bleeding. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "FSH is rising to stimulate new follicles to mature"}, {"id": "b", "text": "LH is surging to mature the next follicle in the ovary"}, {"id": "c", "text": "Estrogen is peaking to prepare for the next egg release"}, {"id": "d", "text": "Progesterone is rising to begin rebuilding the lining"}]'::jsonb, '["a"]', 'During the menstrual phase FSH is rising, and FSH stimulates follicles to mature for the next ovulation. The estrogen peak and LH surge come later, near days 12–14.'),
  ('menstrual', 45, 'A client with regular 28-day cycles had a positive home LH test on cycle day 13. On cycle day 15 she still notices clear, slippery, stretchy cervical mucus and asks whether this means her test was wrong. Which response by the nurse is BEST?', '[{"id": "a", "text": "This mucus means ovulation has not happened, so the test should be repeated"}, {"id": "b", "text": "This mucus means progesterone has peaked, so the lining is now fully ready"}, {"id": "c", "text": "This mucus can be present when ovulation is imminent or has just occurred"}, {"id": "d", "text": "This mucus means the corpus luteum has degenerated earlier than expected"}]'::jsonb, '["c"]', 'Egg-white mucus indicates peak fertility and may be seen when ovulation is imminent or has just occurred, so it is consistent with a day 14 ovulation after the LH surge. Progesterone after ovulation produces thick mucus, not this fertile pattern.'),
  ('menstrual', 46, 'A nurse in a fertility clinic reviews self-reported findings from four clients with regular 28-day cycles who are trying to conceive. Which client should the nurse identify as being at peak fertility today?', '[{"id": "a", "text": "Day 4: bleeding, cervix low and firm, mucus scant"}, {"id": "b", "text": "Day 13: cervix high, soft; mucus clear, stretchy"}, {"id": "c", "text": "Day 22: mucus thick and opaque, temperature elevated"}, {"id": "d", "text": "Day 27: temperature falling, mucus sticky and opaque"}]'::jsonb, '["b"]', 'A soft, high, open, wet cervix with clear, stretchy mucus on day 13 indicates peak fertility just before the day 14 ovulation. Thick, opaque mucus with an elevated temperature on day 22 reflects the post-ovulation progesterone phase.'),
  ('menstrual', 47, 'A client whose period is 2 weeks late has a positive pregnancy test, and her provider is monitoring an hCG level that is much lower than expected. The client asks what could happen if her hCG remains too low. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Estrogen could surge again, causing a second LH surge and ovulation"}, {"id": "b", "text": "FSH could fall, causing the uterine lining to thicken even further"}, {"id": "c", "text": "Her temperature could rise further as estrogen replaces progesterone"}, {"id": "d", "text": "Progesterone could fall as the corpus luteum fails, causing bleeding"}]'::jsonb, '["d"]', 'In pregnancy hCG maintains the corpus luteum, which keeps progesterone high and prevents a period. Without adequate hCG the corpus luteum degenerates and the progesterone drop leads to shedding of the lining.'),
  ('menstrual', 48, 'A nurse teaches a client with regular 28-day cycles about the start of her menstrual period. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "My bleeding begins when estrogen and progesterone levels drop."}, {"id": "b", "text": "FSH begins rising again while I am still having my period."}, {"id": "c", "text": "My bleeding is triggered by a sharp surge of estrogen and LH."}, {"id": "d", "text": "The layer that sheds is the stratum functionalis of my lining."}]'::jsonb, '["c"]', 'Menstrual bleeding is triggered by falling estrogen and progesterone from the previous cycle, not by a hormone surge. A surge of estrogen and LH occurs mid-cycle and leads to ovulation.'),
  ('menstrual', 49, 'A client at 30 weeks of gestation is pregnant with twins. She has never been pregnant before and has no living children. Which GTPAL notation should the nurse document for this client today?', '[{"id": "a", "text": "G1 T0 P0 A0 L0"}, {"id": "b", "text": "G2 T0 P0 A0 L0"}, {"id": "c", "text": "G1 T0 P0 A0 L2"}, {"id": "d", "text": "G1 T0 P1 A0 L0"}]'::jsonb, '["a"]', 'The current pregnancy is always included in gravida, and a twin pregnancy is one pregnancy (G1). No births have occurred yet, so T, P, and L are 0; the twins will count as two living children only after birth.'),
  ('menstrual', 50, 'A client in a fertility program has labs on cycle day 21 showing a high progesterone level along with a moderate estrogen level. She asks whether estrogen should have disappeared after she ovulated. Which response by the nurse is BEST?', '[{"id": "a", "text": "Moderate estrogen means another follicle is maturing for release"}, {"id": "b", "text": "Moderate estrogen means the LH surge has not yet happened"}, {"id": "c", "text": "Moderate estrogen means the lining is shedding ahead of schedule"}, {"id": "d", "text": "Moderate estrogen alongside peak progesterone is expected now"}]'::jsonb, '["d"]', 'In the secretory phase (days 15–28) estrogen is at a moderate level while progesterone peaks, so this pattern is expected. Estrogen peaks on days 12–13 before the LH surge, not in the secretory phase.'),
  ('repro_cycle', 1, 'A client who has had consistent 32-day menstrual cycles for the past year is trying to conceive. She asks on which cycle day she most likely ovulates so she can plan intercourse. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "About day 14, because ovulation occurs on day 14 in every cycle"}, {"id": "b", "text": "About day 16, which is the midpoint of a 32-day menstrual cycle"}, {"id": "c", "text": "About day 18, counting back 14 days from her next period"}, {"id": "d", "text": "About day 21, because longer cycles push ovulation a week later"}]'::jsonb, '["c"]', 'The luteal phase is about 14 days regardless of cycle length, so ovulation occurs 14 days before the next period: 32 − 14 = day 18. Day 14 applies only to a 28-day cycle, and day 21 fits a 35-day cycle.'),
  ('repro_cycle', 2, 'A nurse teaches a client in early pregnancy about how her corpus luteum supports the pregnancy until other sources take over. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "The follicle that released my egg turned into the corpus luteum."}, {"id": "b", "text": "Without a fertilized egg, my corpus luteum would have broken down."}, {"id": "c", "text": "The hCG from my embryo is keeping my corpus luteum from dying."}, {"id": "d", "text": "My corpus luteum stops making progesterone once hCG is present."}]'::jsonb, '["d"]', 'hCG from the embryo rescues the corpus luteum so that progesterone production continues; it does not stop progesterone. The ruptured follicle becomes the corpus luteum, which degenerates if fertilization does not occur.'),
  ('repro_cycle', 3, 'A client reports that over the last year her cycles have ranged from 28 days to 35 days. She asks which part of her cycle is responsible for the difference in length from month to month. Which response by the nurse is BEST?', '[{"id": "a", "text": "The luteal phase, since the corpus luteum lasts longer in some months"}, {"id": "b", "text": "The follicular phase, which is longer in her longer cycles"}, {"id": "c", "text": "The menstrual phase, since heavier bleeding takes longer to complete"}, {"id": "d", "text": "The secretory phase, since progesterone rises longer in some months"}]'::jsonb, '["b"]', 'The luteal phase stays about 14 days because of the corpus luteum''s fixed lifespan; it is the follicular phase that varies, being longer in longer cycles. That is why ovulation timing varies while the luteal phase is predictable.'),
  ('repro_cycle', 4, 'A client being evaluated for infertility is found to have scarring that blocks the widest, outer portion of both fallopian tubes, while her ovaries and uterus are normal. Which reproductive event is MOST directly prevented by this finding?', '[{"id": "a", "text": "Ovulation, because the LH surge acts on that portion of the tube"}, {"id": "b", "text": "Menstruation, because the lining sheds through that portion of the tube"}, {"id": "c", "text": "Follicle maturation, because FSH reaches the ovary through the tube"}, {"id": "d", "text": "Fertilization, because egg and sperm normally meet in that portion"}]'::jsonb, '["d"]', 'Fertilization normally occurs in the ampulla, the widest, outer portion of the fallopian tube, so blockage there prevents egg and sperm from meeting. Ovulation and follicle maturation are ovarian events driven by LH and FSH.'),
  ('repro_cycle', 5, 'A client with regular cycles who is trying to conceive uses an ovulation predictor kit. Her kit turns positive at 7:00 a.m. on Monday. She asks when she should expect to release an egg. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Within the next 2–4 hours, so intercourse should occur this morning"}, {"id": "b", "text": "About 24–36 hours after the surge, so Tuesday into Tuesday evening"}, {"id": "c", "text": "About 3–5 days after the surge, so near the end of the week"}, {"id": "d", "text": "About 24–36 hours before the test, so the egg was released Saturday"}]'::jsonb, '["b"]', 'Ovulation predictor kits detect the LH surge, which occurs about 24–36 hours before ovulation, so release of the egg is expected about 24–36 hours after the positive result. The surge precedes ovulation; it does not follow it.'),
  ('repro_cycle', 6, 'A client in a fertility program has serial labs showing that her estrogen has climbed above its threshold level on cycle day 12 of a 28-day cycle. Which pituitary response should the nurse anticipate NEXT?', '[{"id": "a", "text": "Positive feedback that triggers a massive surge of LH"}, {"id": "b", "text": "Negative feedback that suppresses the release of FSH and LH"}, {"id": "c", "text": "Positive feedback that triggers a large rise in FSH for new follicles"}, {"id": "d", "text": "Negative feedback that causes the corpus luteum to degenerate"}]'::jsonb, '["a"]', 'Estrogen normally exerts negative feedback, but when it rises above a threshold just before ovulation it switches to positive feedback and triggers the LH surge. Negative feedback is the effect of lower estrogen levels earlier in the cycle.'),
  ('repro_cycle', 7, 'A client with regular 28-day cycles has labs on cycle day 20 showing FSH and LH far below their mid-cycle levels. She asks what is holding these hormones down after ovulation. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The LH surge used up pituitary stores until the next cycle begins"}, {"id": "b", "text": "hCG released by the ovary blocks FSH and LH after every ovulation"}, {"id": "c", "text": "Progesterone and estrogen from the corpus luteum suppress both"}, {"id": "d", "text": "GnRH release stops permanently once the egg has left the follicle"}]'::jsonb, '["c"]', 'During the luteal phase the corpus luteum sustains the cycle with progesterone and estrogen, whose negative feedback suppresses further FSH and LH secretion. hCG comes from an embryo after implantation, not from the ovary.'),
  ('repro_cycle', 8, 'A client with regular 28-day cycles had unprotected intercourse on cycle day 14. On cycle day 16 she takes a home pregnancy test that is negative and asks whether this means she is not pregnant. Which response by the nurse is BEST?', '[{"id": "a", "text": "The test detects LH, which has already dropped after ovulation"}, {"id": "b", "text": "The test detects estrogen, which falls once the egg is released"}, {"id": "c", "text": "The test detects progesterone, which has not peaked by day 16"}, {"id": "d", "text": "The test detects hCG, made only after the embryo implants"}]'::jsonb, '["d"]', 'Pregnancy tests detect hCG, which is produced by the embryo after implantation, so a test 2 days after ovulation is too early to be meaningful. LH, estrogen, and progesterone are not what a pregnancy test detects.'),
  ('repro_cycle', 9, 'A client with regular 28-day cycles who is not pregnant has serial progesterone levels drawn. The level was high on cycle day 21 and begins falling sharply on cycle day 25. Which ovarian change should the nurse recognize is occurring?', '[{"id": "a", "text": "The ruptured follicle is beginning to form a corpus luteum"}, {"id": "b", "text": "The corpus luteum is degenerating into the corpus albicans"}, {"id": "c", "text": "A new Graafian follicle is releasing its egg into the tube"}, {"id": "d", "text": "The corpus luteum is being rescued and enlarged by hCG"}]'::jsonb, '["b"]', 'Without fertilization the corpus luteum degenerates around days 25–26 into the corpus albicans, causing a sharp fall in progesterone. If hCG had rescued it, progesterone would stay high rather than fall.'),
  ('repro_cycle', 10, 'A client on cycle day 3 asks how her uterine lining can grow back every month if it sheds completely during her period. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The muscle layer of the uterus produces a new lining after each period"}, {"id": "b", "text": "Part of the functional layer is kept each month and simply thickens"}, {"id": "c", "text": "The deep basal layer stays intact and regrows the lining under estrogen"}, {"id": "d", "text": "Progesterone from the follicle rebuilds the lining from the muscle layer"}]'::jsonb, '["c"]', 'Only the superficial stratum functionalis sheds; the deep stratum basalis remains intact and regenerates a new functionalis under estrogen. The myometrium is muscle and is not the source of the new lining.'),
  ('repro_cycle', 11, 'A client with regular 28-day cycles who uses fertility awareness had clear, slippery, stretchy mucus on cycle day 13. On cycle day 19 she reports that her mucus is now thick and sticky. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Progesterone after ovulation has made the mucus a barrier to sperm"}, {"id": "b", "text": "Estrogen is rising again, so a second ovulation is about to occur"}, {"id": "c", "text": "FSH is stimulating new follicles, which thickens the cervical mucus"}, {"id": "d", "text": "The LH surge is underway, and the mucus will thin again within hours"}]'::jsonb, '["a"]', 'After ovulation, progesterone makes cervical mucus thick, sticky, and impenetrable, a natural barrier to sperm. Rising estrogen produces the opposite effect, making mucus thin, clear, and stretchy.'),
  ('repro_cycle', 12, 'A nurse teaches a client how to use the Billings (cervical mucus) method of natural family planning to avoid pregnancy. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will check my discharge every day and note how it looks and feels."}, {"id": "b", "text": "Clear, slippery, stretchy discharge tells me I am near ovulation."}, {"id": "c", "text": "I should avoid unprotected sex when my discharge is clear and stretchy."}, {"id": "d", "text": "Dry, sticky discharge tells me I am in my most fertile days now."}]'::jsonb, '["d"]', 'With the Billings method, dry or sticky discharge indicates the infertile time, while clear, slippery, stretchy discharge marks the fertile window around ovulation. The client has reversed the meaning of dry, sticky mucus.'),
  ('repro_cycle', 13, 'A client with regular cycles who wants to avoid pregnancy asks the nurse whether tracking her cervical mucus and basal body temperature would protect her as well as a hormonal contraceptive. Which response by the nurse is BEST?', '[{"id": "a", "text": "Mucus and temperature tracking match hormonal methods if charted daily"}, {"id": "b", "text": "Mucus and temperature tracking are less reliable than hormonal methods"}, {"id": "c", "text": "Mucus and temperature tracking beat hormonal methods for regular cycles"}, {"id": "d", "text": "Mucus and temperature tracking are reliable if she avoids day 14 alone"}]'::jsonb, '["b"]', 'The cervical mucus and basal body temperature methods are natural family planning options but are less reliable than hormonal contraception. Avoiding only day 14 ignores that sperm survive up to 5 days.'),
  ('repro_cycle', 14, 'A client being evaluated for infertility is found to have granulosa cells in her developing follicles that do not respond to FSH. Which hormone should the nurse expect to be MOST reduced during her follicular phase?', '[{"id": "a", "text": "Progesterone, normally secreted by the granulosa cells before ovulation"}, {"id": "b", "text": "LH, normally secreted by the granulosa cells to trigger ovulation"}, {"id": "c", "text": "Estrogen, normally produced by the granulosa cells under FSH"}, {"id": "d", "text": "hCG, normally produced by the granulosa cells to support the follicle"}]'::jsonb, '["c"]', 'During the follicular phase FSH stimulates the granulosa cells to produce estrogen, so unresponsive granulosa cells would lower estrogen. Progesterone comes mainly from the corpus luteum after ovulation, and LH comes from the anterior pituitary.'),
  ('repro_cycle', 15, 'A client with regular 28-day cycles had menstrual bleeding through cycle day 6. A pelvic ultrasound on cycle day 10 shows that her endometrium is steadily thickening. Which hormone is the primary driver of the change seen on the ultrasound?', '[{"id": "a", "text": "Estrogen, which rebuilds the uterine lining after menstruation"}, {"id": "b", "text": "Progesterone, which rebuilds the uterine lining after menstruation"}, {"id": "c", "text": "LH, which rebuilds the uterine lining before its mid-cycle surge"}, {"id": "d", "text": "hCG, which rebuilds the uterine lining to prepare for implantation"}]'::jsonb, '["a"]', 'Days 7–14 are the proliferative phase, when estrogen rebuilds the uterine lining. Progesterone drives the later secretory phase, after the corpus luteum forms.'),
  ('repro_cycle', 16, 'A client in a fertility evaluation has an endometrial biopsy on cycle day 22 of a 28-day cycle. The report describes a thick, vascular, glandular endometrium. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Ovulation has not yet occurred, and estrogen is still rebuilding the lining"}, {"id": "b", "text": "The lining is in the menstrual phase and will begin shedding today"}, {"id": "c", "text": "hCG from an implanted embryo is directly thickening the lining"}, {"id": "d", "text": "Ovulation has occurred, and progesterone is preparing the lining"}]'::jsonb, '["d"]', 'Progesterone from the corpus luteum makes the endometrium thick, vascular, and glandular during the secretory phase, which follows ovulation. Estrogen alone rebuilds the lining in the proliferative phase but does not create this secretory pattern.'),
  ('repro_cycle', 17, 'A client with regular 28-day cycles is on cycle day 4 and is having her menstrual period. She asks what her ovaries are doing while her uterine lining is shedding. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Your ovaries are in the luteal phase while the corpus luteum finishes"}, {"id": "b", "text": "Your ovaries are resting until bleeding stops and the lining rebuilds"}, {"id": "c", "text": "Your ovaries are in the follicular phase as new follicles grow"}, {"id": "d", "text": "Your ovaries are in the ovulatory phase while the LH surge continues"}]'::jsonb, '["c"]', 'The ovarian follicular phase (days 1–13) runs at the same time as the uterine menstrual phase (days 1–6) and proliferative phase (days 7–14). The luteal phase pairs with the secretory phase on days 15–28.'),
  ('repro_cycle', 18, 'A client with regular 28-day cycles has a pelvic ultrasound on cycle day 7 that shows several follicles beginning to grow on one ovary. She is worried that this means she will release several eggs. Which response by the nurse is BEST?', '[{"id": "a", "text": "Several growing follicles mean LH has surged early this cycle"}, {"id": "b", "text": "FSH starts several follicles, and normally one becomes dominant"}, {"id": "c", "text": "Several growing follicles mean a corpus luteum failed last cycle"}, {"id": "d", "text": "Each follicle seen now is expected to release an egg at ovulation"}]'::jsonb, '["b"]', 'FSH stimulates several follicles to begin maturing each cycle, and one dominant Graafian follicle continues to maturity. LH triggers ovulation; it does not initiate follicle growth.'),
  ('repro_cycle', 19, 'A client being evaluated for absent cycles is found to have an anterior pituitary that does not respond to GnRH, even though her hypothalamus releases GnRH normally. Which consequence should the nurse anticipate?', '[{"id": "a", "text": "Follicles fail to mature because FSH and LH are not released"}, {"id": "b", "text": "Follicles mature early because GnRH acts on the ovary directly"}, {"id": "c", "text": "Ovulation continues because the hypothalamus releases LH itself"}, {"id": "d", "text": "The corpus luteum persists because progesterone keeps rising"}]'::jsonb, '["a"]', 'GnRH signals the anterior pituitary to release FSH and LH, which then act on the ovaries; without that response, follicles are not stimulated to mature. GnRH does not act directly on the ovary.'),
  ('repro_cycle', 20, 'A nurse reviews the cycle physiology a nursing student taught a client who is starting fertility treatment. Which statement by the student requires correction?', '[{"id": "a", "text": "GnRH from your hypothalamus signals your pituitary to release FSH and LH."}, {"id": "b", "text": "FSH from your pituitary stimulates several follicles to begin maturing."}, {"id": "c", "text": "The LH surge triggers release of the egg from the dominant follicle."}, {"id": "d", "text": "LH from your pituitary is the hormone that starts your follicles growing."}]'::jsonb, '["d"]', 'FSH, not LH, initiates follicle growth; LH triggers ovulation but does not initiate follicle growth. The other statements correctly describe GnRH, FSH, and the LH surge.'),
  ('repro_cycle', 21, 'A client with regular 28-day cycles has a pelvic ultrasound on cycle day 18 that shows a corpus luteum at the site where her dominant follicle ruptured. She asks what this structure is doing. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "It is secreting FSH and LH to prepare the next follicle"}, {"id": "b", "text": "It is secreting hCG to keep the uterine lining in place"}, {"id": "c", "text": "It is secreting mainly progesterone, plus some estrogen"}, {"id": "d", "text": "It is secreting estrogen alone until menstruation starts"}]'::jsonb, '["c"]', 'After ovulation the ruptured follicle becomes the corpus luteum, which secretes progesterone (dominant) and estrogen during the luteal phase. hCG comes from the embryo, and FSH and LH come from the anterior pituitary.'),
  ('repro_cycle', 22, 'A client with regular 28-day cycles who wants to avoid pregnancy had unprotected intercourse on cycle day 10. She says she is not worried because she will not ovulate until day 14. Which response by the nurse is the PRIORITY?', '[{"id": "a", "text": "Sperm survive up to 5 days, so a day 14 egg could be fertilized"}, {"id": "b", "text": "The egg lives 12–24 hours, so day 10 intercourse cannot reach it"}, {"id": "c", "text": "Day 10 is in the luteal phase, when thick mucus blocks the sperm"}, {"id": "d", "text": "Fertilization occurs in the uterus, which is not ready until day 15"}]'::jsonb, '["a"]', 'Sperm can survive up to 5 days, so intercourse up to 5 days before ovulation can result in fertilization. Egg viability of 12–24 hours limits fertility after ovulation, not before it.'),
  ('repro_cycle', 23, 'A client with regular 28-day cycles who is trying to conceive confirmed ovulation on cycle day 14. She and her partner were apart until cycle day 17, and she asks how likely pregnancy is from intercourse that day. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Likely, because sperm can survive up to 5 days to meet the egg"}, {"id": "b", "text": "Unlikely, because the egg is viable only 12–24 hours"}, {"id": "c", "text": "Likely, because the corpus luteum keeps the egg viable for 2 weeks"}, {"id": "d", "text": "Unlikely, because the egg is fertilized in the uterus on day 15"}]'::jsonb, '["b"]', 'The egg is viable for only 12–24 hours after ovulation, so by day 17 it can no longer be fertilized. Sperm survival matters for intercourse before ovulation, not 3 days after it.'),
  ('repro_cycle', 24, 'A client with regular 28-day cycles who has been trying to conceive asks the nurse which days of her cycle she and her partner should focus on for intercourse. Which response by the nurse is BEST?', '[{"id": "a", "text": "Days 14–20, starting on the day of ovulation and continuing after"}, {"id": "b", "text": "Days 4–9, while the follicles are first starting to mature"}, {"id": "c", "text": "Days 16–22, once the corpus luteum has formed and is active"}, {"id": "d", "text": "Days 9–16, which center around ovulation on about day 14"}]'::jsonb, '["d"]', 'The most fertile window in a 28-day cycle is about days 9–16, centered on ovulation at day 14, because sperm survive up to 5 days and the egg 12–24 hours. Days after the corpus luteum forms are past the egg''s viability.'),
  ('repro_cycle', 25, 'A client with regular 28-day cycles notices on cycle day 12 that her cervical mucus has become thin and clear and stretches between her fingers. She asks which hormone causes this and why it matters. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Progesterone; it makes the mucus a barrier that protects the lining"}, {"id": "b", "text": "LH; it softens the mucus so the egg can leave through the cervix"}, {"id": "c", "text": "Estrogen; it makes the mucus friendly to sperm before ovulation"}, {"id": "d", "text": "hCG; it thins the mucus to prepare the uterus for implantation"}]'::jsonb, '["c"]', 'Rising estrogen in the proliferative phase makes cervical mucus thin, clear, and stretchy, which makes it sperm-friendly. Progesterone after ovulation does the opposite, making mucus thick and impenetrable.'),
  ('repro_cycle', 26, 'A nurse teaches a client who has just had a positive pregnancy test about the hormone the test detected. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "The hCG in my test was made by my ovary''s corpus luteum."}, {"id": "b", "text": "The hCG appears after the embryo implants in my uterus."}, {"id": "c", "text": "The hCG keeps my corpus luteum producing progesterone."}, {"id": "d", "text": "The hCG is the hormone that home pregnancy tests detect."}]'::jsonb, '["a"]', 'hCG is produced by the developing embryo''s trophoblast cells after implantation; the corpus luteum is the structure hCG rescues, not its source. The other statements correctly describe hCG''s timing, role, and detection.'),
  ('repro_cycle', 27, 'A client with regular 28-day cycles is on cycle day 20. Her ultrasound shows a corpus luteum, and her progesterone level is elevated. Which pairing of ovarian and uterine phases should the nurse identify?', '[{"id": "a", "text": "Follicular ovarian phase with proliferative uterine phase"}, {"id": "b", "text": "Luteal ovarian phase with secretory uterine phase"}, {"id": "c", "text": "Follicular ovarian phase with secretory uterine phase"}, {"id": "d", "text": "Luteal ovarian phase with proliferative uterine phase"}]'::jsonb, '["b"]', 'The ovarian luteal phase (days 15–28) corresponds to the uterine secretory phase (days 15–28), when corpus luteum progesterone dominates. Follicular pairs with menstrual and proliferative, days 1–14.'),
  ('repro_cycle', 28, 'A client with regular 28-day cycles has labs on cycle day 5 showing estrogen just beginning to rise from a low level. She asks how this early estrogen affects her pituitary. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "It triggers positive feedback that produces an immediate LH surge"}, {"id": "b", "text": "It triggers positive feedback that keeps FSH rising throughout"}, {"id": "c", "text": "It has no effect on the pituitary until after ovulation has occurred"}, {"id": "d", "text": "It exerts negative feedback, which suppresses FSH and LH release"}]'::jsonb, '["d"]', 'Estrogen normally exerts negative feedback on the pituitary, suppressing FSH and LH; it switches to positive feedback only when it rises above a threshold just before ovulation. A low, early level therefore does not trigger the LH surge.'),
  ('repro_cycle', 29, 'A nurse in a fertility clinic reviews four clients, each with consistent cycle lengths, who are tracking ovulation. Which client should the nurse identify as MOST likely to be ovulating today?', '[{"id": "a", "text": "A client with 26-day cycles who is on cycle day 14"}, {"id": "b", "text": "A client with 35-day cycles who is on cycle day 14"}, {"id": "c", "text": "A client with 30-day cycles who is on cycle day 16"}, {"id": "d", "text": "A client with 32-day cycles who is on cycle day 16"}]'::jsonb, '["c"]', 'Ovulation occurs about 14 days before the next period, so a 30-day cycle ovulates on day 16 (30 − 14). The 26-day client ovulated on day 12, the 35-day client will ovulate on day 21, and the 32-day client on day 18.'),
  ('repro_cycle', 30, 'A nurse teaches a client with regular 28-day cycles why her period starts at the end of a cycle in which she did not conceive. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "A surge of progesterone near the end of my cycle starts my bleeding."}, {"id": "b", "text": "My corpus luteum breaks down when there is no fertilized egg."}, {"id": "c", "text": "Falling estrogen and progesterone let the lining break down and shed."}, {"id": "d", "text": "Without hormone support, the surface layer of my lining is shed."}]'::jsonb, '["a"]', 'Menstruation results from a drop, not a surge, in progesterone and estrogen when the corpus luteum degenerates. Without these hormones the stratum functionalis breaks down and sheds.'),
  ('repro_cycle', 31, 'A client starting fertility treatment asks the nurse to explain the order of events in her ovary from early in the cycle through the time after the egg is released. Which sequence should the nurse describe?', '[{"id": "a", "text": "Corpus luteum forms → FSH stimulates follicles → estrogen positive feedback → ovulation"}, {"id": "b", "text": "FSH stimulates follicles → estrogen positive feedback → ovulation → corpus luteum forms"}, {"id": "c", "text": "Estrogen positive feedback → FSH stimulates follicles → corpus luteum forms → ovulation"}, {"id": "d", "text": "FSH stimulates follicles → ovulation → estrogen positive feedback → corpus luteum forms"}]'::jsonb, '["b"]', 'FSH stimulates follicles to grow, rising estrogen produces positive feedback and the LH surge, ovulation follows, and the ruptured follicle becomes the corpus luteum. Positive feedback must precede ovulation because it triggers the LH surge.'),
  ('repro_cycle', 32, 'A client in a fertility evaluation with regular 28-day cycles wants evidence that she actually ovulated this cycle rather than evidence that ovulation is coming. Which finding provides the BEST evidence that ovulation has already occurred?', '[{"id": "a", "text": "Clear, stretchy cervical mucus with a rising estrogen level"}, {"id": "b", "text": "A positive ovulation predictor kit result early this morning"}, {"id": "c", "text": "An estrogen level above threshold with positive feedback"}, {"id": "d", "text": "Thick, sticky mucus with a rising progesterone level"}]'::jsonb, '["d"]', 'Progesterone from the corpus luteum rises only after ovulation and makes cervical mucus thick and sticky, so this pairing shows ovulation has occurred. A positive LH kit, peak estrogen, and stretchy mucus all indicate ovulation is approaching.'),
  ('repro_cycle', 33, 'A client with regular 28-day cycles confirmed ovulation on cycle day 14 and is not pregnant this cycle. She asks when her corpus luteum will stop working and her period will begin. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "It degenerates around day 15, and bleeding follows by day 17"}, {"id": "b", "text": "It degenerates around day 20, and bleeding begins by day 21"}, {"id": "c", "text": "It degenerates around days 25–26, and bleeding then follows"}, {"id": "d", "text": "It persists until hCG falls, and bleeding begins near day 35"}]'::jsonb, '["c"]', 'When fertilization does not occur, the corpus luteum degenerates around days 25–26, and the fall in progesterone and estrogen produces bleeding on day 1 of the new cycle. hCG plays a role only if fertilization occurs.'),
  ('repro_cycle', 34, 'A client in a fertility evaluation asks the nurse how the two cell types surrounding her developing follicle work together to make estrogen during the first half of her cycle. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Theca cells make androgens that granulosa cells convert to estrogen"}, {"id": "b", "text": "Granulosa cells make androgens that theca cells convert to estrogen"}, {"id": "c", "text": "Theca cells make progesterone that granulosa cells convert to estrogen"}, {"id": "d", "text": "Granulosa cells make LH that theca cells convert to estrogen"}]'::jsonb, '["a"]', 'Theca cells produce androgens, which the granulosa cells convert to estrogen under FSH stimulation. Progesterone becomes dominant only after ovulation from the corpus luteum, and LH comes from the anterior pituitary.'),
  ('repro_cycle', 35, 'A nurse teaches a client with regular 28-day cycles about which part of the uterus is lost during menstruation. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "The surface layer of my uterine lining is what sheds each month."}, {"id": "b", "text": "The muscle layer of my uterus is shed along with the lining."}, {"id": "c", "text": "The deep layer of my lining stays in place to regrow the surface."}, {"id": "d", "text": "Estrogen helps my lining grow back after my bleeding stops."}]'::jsonb, '["b"]', 'The myometrium is muscle and is not shed; only the superficial stratum functionalis sheds, while the stratum basalis remains to regenerate it under estrogen.'),
  ('repro_cycle', 36, 'A client with regular 28-day cycles who does not want to become pregnant is using fertility awareness. She asks which part of her cycle requires the most caution with unprotected intercourse. Which response by the nurse is BEST?', '[{"id": "a", "text": "Days 1–6, while menstrual bleeding is occurring"}, {"id": "b", "text": "Days 15–22, while the corpus luteum is most active"}, {"id": "c", "text": "Days 22–28, while estrogen and progesterone decline"}, {"id": "d", "text": "Days 9–16, the window that surrounds ovulation"}]'::jsonb, '["d"]', 'The most fertile window in a 28-day cycle is about days 9–16, around ovulation on day 14, which matters for both contraception counseling and fertility planning. The later luteal days follow the egg''s 12–24 hour viability.'),
  ('repro_cycle', 37, 'A client with regular 28-day cycles has labs on cycle day 14 showing a very high LH level. Repeat labs on cycle day 16 show that both FSH and LH have fallen sharply. She asks whether this drop is a problem. Which response by the nurse is BEST?', '[{"id": "a", "text": "The drop suggests the egg was never released and needs follow-up"}, {"id": "b", "text": "The drop suggests the pituitary has stopped responding to GnRH"}, {"id": "c", "text": "The drop is expected after the LH surge has triggered ovulation"}, {"id": "d", "text": "The drop is expected because hCG from the ovary suppresses both"}]'::jsonb, '["c"]', 'After the LH surge triggers ovulation, both FSH and LH fall dramatically, and the corpus luteum then maintains the cycle with progesterone and estrogen. hCG comes from an embryo after implantation, not from the ovary.'),
  ('repro_cycle', 38, 'A client who conceived this cycle is having serial labs drawn 2 weeks after ovulation to confirm that her corpus luteum is being sustained. Which lab pattern BEST indicates that the corpus luteum has been rescued?', '[{"id": "a", "text": "Rising hCG with a sustained progesterone level"}, {"id": "b", "text": "A new LH surge with a falling progesterone level"}, {"id": "c", "text": "Rising FSH with a falling estrogen level"}, {"id": "d", "text": "Falling hCG with a falling progesterone level"}]'::jsonb, '["a"]', 'hCG from the embryo rescues the corpus luteum from degenerating, so progesterone production continues. Falling progesterone and rising FSH indicate the corpus luteum is degenerating and a new cycle is starting.'),
  ('repro_cycle', 39, 'A client with regular 28-day cycles reports that her menstrual bleeding has lasted through cycle day 6 and is now ending. She asks whether bleeding that long means her lining is not rebuilding normally. Which response by the nurse is BEST?', '[{"id": "a", "text": "Bleeding through day 6 means progesterone failed to rise this cycle"}, {"id": "b", "text": "Bleeding through day 6 falls within the expected menstrual phase"}, {"id": "c", "text": "Bleeding through day 6 means estrogen should already have peaked"}, {"id": "d", "text": "Bleeding through day 6 means her ovulation will be delayed a week"}]'::jsonb, '["b"]', 'The menstrual phase spans days 1–6, followed by the estrogen-driven proliferative phase on days 7–14. Estrogen peaks just before ovulation, not by day 6.'),
  ('repro_cycle', 40, 'A client with regular 28-day cycles has labs on cycle day 21 showing estrogen present along with high progesterone. She asks where estrogen is coming from, since the follicle that made it ruptured a week ago. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "New granulosa cells are maturing a second follicle this cycle"}, {"id": "b", "text": "The anterior pituitary is releasing estrogen along with LH"}, {"id": "c", "text": "The embryo''s trophoblast cells are releasing it before implantation"}, {"id": "d", "text": "The corpus luteum formed from that follicle is now its main source"}]'::jsonb, '["d"]', 'After ovulation the corpus luteum, formed from the ruptured follicle, becomes the main source of both progesterone and estrogen. The anterior pituitary releases FSH and LH, not estrogen.'),
  ('repro_cycle', 41, 'A client with regular 28-day cycles in a fertility evaluation has an ultrasound on cycle day 18 showing that no corpus luteum formed after her dominant follicle developed. Which finding should the nurse expect for the remainder of this cycle?', '[{"id": "a", "text": "Low progesterone and a lining unready for implantation"}, {"id": "b", "text": "High progesterone and a thick, glandular secretory lining"}, {"id": "c", "text": "High hCG that maintains the lining until the next cycle"}, {"id": "d", "text": "Low FSH and LH that rebuild the lining in the next week"}]'::jsonb, '["a"]', 'The corpus luteum is the progesterone factory that maintains the endometrium for implantation, so without it progesterone stays low and the secretory lining does not develop. hCG comes from an embryo after implantation, not from a failed cycle.'),
  ('repro_cycle', 42, 'A client beginning a fertility workup asks the nurse to describe how the hormonal signals that control her cycle travel through her body, starting from the top of the system. Which pathway should the nurse describe?', '[{"id": "a", "text": "Anterior pituitary releases GnRH → hypothalamus releases FSH and LH → ovaries respond"}, {"id": "b", "text": "Ovaries release GnRH → anterior pituitary releases FSH and LH → hypothalamus responds"}, {"id": "c", "text": "Hypothalamus releases GnRH → anterior pituitary releases FSH and LH → ovaries respond"}, {"id": "d", "text": "Hypothalamus releases FSH and LH → anterior pituitary releases GnRH → ovaries respond"}]'::jsonb, '["c"]', 'GnRH is released from the hypothalamus in pulses and signals the anterior pituitary to release FSH and LH, which then act on the ovaries. GnRH sits at the top of the hypothalamic-pituitary-ovarian axis.'),
  ('repro_cycle', 43, 'A client with cycles that vary between 30 and 36 days confirmed ovulation on cycle day 19 this month with an ovulation predictor kit and an ultrasound. She is not trying to conceive and asks when to expect her next period. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Around day 28, because a period comes 28 days after the last one"}, {"id": "b", "text": "Around day 33, since the luteal phase lasts about 14 days"}, {"id": "c", "text": "Around day 38, because the luteal phase lengthens in longer cycles"}, {"id": "d", "text": "Around day 24, because the corpus luteum survives about 5 days"}]'::jsonb, '["b"]', 'The luteal phase is nearly constant at about 14 days, so the period should begin about 14 days after ovulation: 19 + 14 = day 33. It is the follicular phase, not the luteal phase, that lengthens in longer cycles.'),
  ('repro_cycle', 44, 'A client with regular cycles who is trying to conceive buys an ovulation predictor kit and asks the nurse what the kit measures and why a positive result is useful. Which response by the nurse is BEST?', '[{"id": "a", "text": "It measures FSH; a rise shows that follicles are starting to mature"}, {"id": "b", "text": "It measures estrogen; a peak shows that the corpus luteum has formed"}, {"id": "c", "text": "It measures progesterone; a rise shows that ovulation is about to occur"}, {"id": "d", "text": "It measures LH; a surge shows that release of the egg is approaching"}]'::jsonb, '["d"]', 'Ovulation predictor kits detect the LH surge, which triggers release of the mature egg and occurs before ovulation. Progesterone rises after ovulation from the corpus luteum, so it cannot predict ovulation.'),
  ('repro_cycle', 45, 'A client with regular 28-day cycles in a fertility evaluation has labs on cycle day 23 showing progesterone at its highest level of the cycle. Which endometrial finding should the nurse expect at this time?', '[{"id": "a", "text": "A thick, glandular lining that is ready for implantation"}, {"id": "b", "text": "A thin lining that is just beginning to rebuild under estrogen"}, {"id": "c", "text": "A shedding functional layer with active menstrual bleeding"}, {"id": "d", "text": "A lining that thickens as estrogen reaches its pre-ovulation peak"}]'::jsonb, '["a"]', 'During the secretory phase (days 15–28) progesterone makes the endometrium thick, glandular, and ready for implantation. Rebuilding under estrogen is the proliferative phase, before ovulation.'),
  ('repro_cycle', 46, 'A client who is 5 weeks past the start of her last period has a positive pregnancy test, and serial labs are being drawn to monitor the early pregnancy. Which result should the nurse report to the provider?', '[{"id": "a", "text": "An hCG level that is rising on serial draws"}, {"id": "b", "text": "A progesterone level that is falling on serial draws"}, {"id": "c", "text": "FSH and LH levels that remain suppressed on serial draws"}, {"id": "d", "text": "An estrogen level that remains above baseline on serial draws"}]'::jsonb, '["b"]', 'In early pregnancy hCG rescues the corpus luteum so that progesterone continues to be produced to maintain the endometrium, so falling progesterone suggests that support is failing. Rising hCG is the expected pattern.'),
  ('repro_cycle', 47, 'A client in a fertility evaluation has serial labs showing that her estrogen rose during the follicular phase but never climbed above its threshold level this cycle. Which event should the nurse anticipate will fail to occur?', '[{"id": "a", "text": "Initial recruitment of follicles by FSH early in the cycle"}, {"id": "b", "text": "Shedding of the stratum functionalis at the start of the cycle"}, {"id": "c", "text": "The LH surge that is needed to trigger release of the egg"}, {"id": "d", "text": "Negative feedback of estrogen on the pituitary early in the cycle"}]'::jsonb, '["c"]', 'Only when estrogen rises above a threshold does it switch to positive feedback and trigger the LH surge that causes ovulation. Negative feedback on FSH and LH is the normal effect of lower estrogen levels, so it would still occur.'),
  ('repro_cycle', 48, 'A client with regular 28-day cycles has a pelvic ultrasound on cycle day 10 showing a single enlarging follicle and an endometrium that is thickening after her recent period. Which pairing of ovarian and uterine phases should the nurse identify?', '[{"id": "a", "text": "Follicular ovarian phase with proliferative uterine phase"}, {"id": "b", "text": "Luteal ovarian phase with secretory uterine phase"}, {"id": "c", "text": "Follicular ovarian phase with secretory uterine phase"}, {"id": "d", "text": "Luteal ovarian phase with menstrual uterine phase"}]'::jsonb, '["a"]', 'Day 10 falls in the ovarian follicular phase (days 1–13) and the uterine proliferative phase (days 7–14), when estrogen from the growing follicle rebuilds the lining. The secretory phase pairs with the luteal phase after ovulation.'),
  ('repro_cycle', 49, 'A client with regular 28-day cycles who is trying to conceive ovulated on cycle day 14 and asks where and when the egg could be fertilized. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "In the uterus, at any point until her next period begins"}, {"id": "b", "text": "In the uterus, within about 3–5 days after ovulation"}, {"id": "c", "text": "In the ovary, within a few hours of the LH surge"}, {"id": "d", "text": "In the ampulla, within about 12–24 hours of ovulation"}]'::jsonb, '["d"]', 'Fertilization normally occurs in the ampulla of the fallopian tube, and the egg is viable for only 12–24 hours after ovulation. The 3–5 day figure applies to sperm survival, not to the egg.'),
  ('repro_cycle', 50, 'A nurse teaches a client with regular 28-day cycles which hormone controls each phase of her uterine lining. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Estrogen is the main driver of my proliferative phase."}, {"id": "b", "text": "Progesterone is the main driver of my secretory phase."}, {"id": "c", "text": "Progesterone rebuilds my lining right after my period ends."}, {"id": "d", "text": "Falling estrogen and progesterone bring on my menstrual phase."}]'::jsonb, '["c"]', 'Estrogen rebuilds the lining in the proliferative phase after menstruation; progesterone drives the later secretory phase. The client has assigned estrogen''s rebuilding role to progesterone.'),
  ('priorities', 1, 'A nurse in a women''s health clinic is reviewing four clients'' breast findings. Which client should the nurse prioritize for referral for mammogram and biopsy?', '[{"id": "a", "text": "A 23-year-old with a smooth, firm, mobile, non-tender lump"}, {"id": "b", "text": "A 34-year-old with lumpy, tender breasts that worsen before her period"}, {"id": "c", "text": "A 52-year-old with a hard, fixed, non-tender lump and skin dimpling"}, {"id": "d", "text": "A 29-year-old with a tender lump that changes size with her cycle"}]'::jsonb, '["c"]', 'A hard, fixed, non-tender lump with skin dimpling suggests malignancy and requires referral for mammogram or biopsy. A smooth, mobile, non-tender lump fits a fibroadenoma, and tender lumps that fluctuate with the cycle are more likely benign.'),
  ('priorities', 2, 'A 21-year-old client found a breast lump during her self-exam. The provider documents a 2-cm smooth, firm lump that moves easily under the fingers and is not tender. The client is frightened. Which response by the nurse is best?', '[{"id": "a", "text": "''This sounds like the most common benign breast lump in young women.''"}, {"id": "b", "text": "''Lumps that are not tender are the type most likely to be cancerous.''"}, {"id": "c", "text": "''This is a fibrocystic change, so cutting back on caffeine should help.''"}, {"id": "d", "text": "''A lump at your age needs a biopsy today to rule out a breast cancer.''"}]'::jsonb, '["a"]', 'A smooth, mobile, firm, non-tender lump in a young woman fits a fibroadenoma, the most common benign breast tumor in young women. A non-tender lump is concerning when it is hard and fixed, not when it is smooth and mobile.'),
  ('priorities', 3, 'A 36-year-old client reports that both breasts become lumpy and sore during the week before each period and improve once menses begins. Her exam shows no fixed masses or skin changes. Which instruction by the nurse is most appropriate first?', '[{"id": "a", "text": "Schedule a mammogram and a biopsy of the most tender area later this week"}, {"id": "b", "text": "Wear a supportive bra, reduce caffeine, and use NSAIDs for discomfort"}, {"id": "c", "text": "Stop monthly self-exams, since lumpy breasts make results unreliable"}, {"id": "d", "text": "Report any tenderness immediately, since tender lumps suggest cancer"}]'::jsonb, '["b"]', 'Lumpy, tender breasts that worsen before the period are fibrocystic changes, which are benign and treated with NSAIDs, a supportive bra, and reduced caffeine. Tender lumps that fluctuate with the cycle are more likely benign.'),
  ('priorities', 4, 'A client has a regular 28-day cycle, and her most recent period started on the 3rd of the month. She asks when she should perform this month''s breast self-exam. Which date should the nurse recommend as best?', '[{"id": "a", "text": "The 3rd, on the first day her period began this month"}, {"id": "b", "text": "The 11th, about a week after her period starts"}, {"id": "c", "text": "The 24th, about a week before her next period"}, {"id": "d", "text": "The 30th, on the day her next period is due"}]'::jsonb, '["b"]', 'BSE is done monthly, 7–10 days after the period starts, when breasts are least tender; the 3rd plus 8 days is the 11th. The days just before the next period are when breasts are most likely to be tender and lumpy.'),
  ('priorities', 5, 'A nurse has taught a 30-year-old client about breast self-examination. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''I''ll check my breasts both while lying down and also in the shower.''"}, {"id": "b", "text": "''I''ll report any dimpling or nipple discharge that I notice.''"}, {"id": "c", "text": "''I''ll do the exam a week after my period starts each month.''"}, {"id": "d", "text": "''I''ll do the exam right before my period, when they''re fullest.''"}]'::jsonb, '["d"]', 'BSE should be done about 1 week after the period starts, when breasts are least tender. Before the period, fibrocystic changes make breasts lumpy and tender.'),
  ('priorities', 6, 'A 48-year-old client reports that the skin over one breast has developed an orange-peel texture, and she has a new bloody discharge from that nipple. Which action by the nurse is the priority?', '[{"id": "a", "text": "Teach her to reduce caffeine and wear a supportive bra"}, {"id": "b", "text": "Advise her to recheck the area 7–10 days after her period"}, {"id": "c", "text": "Arrange prompt evaluation with mammogram and biopsy"}, {"id": "d", "text": "Reassure her that cyclic breast changes are often benign"}]'::jsonb, '["c"]', 'Peau d''orange skin and bloody nipple discharge are breast cancer warning signs that require referral for mammogram or biopsy. Reducing caffeine and reassurance apply to benign fibrocystic changes.'),
  ('priorities', 7, 'A 19-year-old client who has been sexually active for two years requests a Pap smear at her first gynecologic visit. Which response by the nurse is best?', '[{"id": "a", "text": "''You should have had one when you became sexually active, so we''ll do it today.''"}, {"id": "b", "text": "''A Pap smear is not recommended until age 21, even if you are sexually active.''"}, {"id": "c", "text": "''We''ll do a Pap with an HPV co-test today, then repeat it every five years.''"}, {"id": "d", "text": "''We''ll do a Pap today, and then every three years until you turn 30.''"}]'::jsonb, '["b"]', 'No Pap smear is done before age 21, regardless of sexual activity. Pap every 3 years begins at 21, and co-testing begins at 30.'),
  ('priorities', 8, 'A 26-year-old client had her first Pap smear one year ago, and the result was normal (NILM). She asks when she should have her next one. Which response by the nurse is best?', '[{"id": "a", "text": "In about 1 year, since screening is yearly at her age"}, {"id": "b", "text": "In about 2 years, since cytology is every 3 years"}, {"id": "c", "text": "In about 4 years, since co-testing is every 5 years"}, {"id": "d", "text": "Not until age 30, when HPV co-testing can begin"}]'::jsonb, '["b"]', 'Ages 21–29 have a Pap smear every 3 years with cytology alone, so her next Pap is due 2 years from now. Co-testing every 5 years applies to ages 30–65.'),
  ('priorities', 9, 'A 38-year-old client had a Pap smear with HPV co-testing today, and both results are negative. She asks when she needs to be screened again. Which response by the nurse is best?', '[{"id": "a", "text": "In 1 year"}, {"id": "b", "text": "In 3 years"}, {"id": "c", "text": "In 5 years"}, {"id": "d", "text": "At age 65"}]'::jsonb, '["c"]', 'For ages 30–65, a Pap with HPV co-test is repeated every 5 years, or Pap alone every 3 years. Because she was co-tested, the 5-year interval applies.'),
  ('priorities', 10, 'A nurse is reviewing cervical screening needs for four clients. Which client still requires continued Pap smear screening?', '[{"id": "a", "text": "A 67-year-old with adequate prior negative results who is not high risk"}, {"id": "b", "text": "A 50-year-old with a hysterectomy for fibroids and no cervical disease history"}, {"id": "c", "text": "A 45-year-old with a total hysterectomy after precancerous cervical lesions"}, {"id": "d", "text": "A 19-year-old who has been sexually active for the past three years"}]'::jsonb, '["c"]', 'Screening stops after hysterectomy only if there is no cervix and no history of cervical cancer or precancerous lesions, so her history requires continued screening. Screening stops after 65 with adequate negatives, and does not start before 21.'),
  ('priorities', 11, 'A 66-year-old client asks whether she still needs Pap smears. Her records show adequate prior negative results, and she has no high-risk factors and an intact cervix. Which response by the nurse is best?', '[{"id": "a", "text": "She may stop cervical screening based on her age and results"}, {"id": "b", "text": "She should continue Pap smears every 3 years for her lifetime"}, {"id": "c", "text": "She should switch to yearly Pap smears now that she is over 65"}, {"id": "d", "text": "She should have a colposcopy before screening can be stopped"}]'::jsonb, '["a"]', 'After age 65, screening stops if there are adequate prior negative results and the client is not high risk. Colposcopy is used for abnormal results, not to end screening.'),
  ('priorities', 12, 'A 27-year-old client''s Pap smear shows atypical squamous cells of undetermined significance (ASC-US), and reflex HPV testing is positive. Which next step should the nurse anticipate as the priority?', '[{"id": "a", "text": "Routine Pap screening in 3 years"}, {"id": "b", "text": "Colposcopy to examine the cervix"}, {"id": "c", "text": "Repeat HPV testing in 5 years"}, {"id": "d", "text": "Staging workup for cervical cancer"}]'::jsonb, '["b"]', 'For ASC-US, an HPV test is done; if HPV is positive, colposcopy follows. Routine screening is appropriate only if HPV is negative, and staging is for confirmed cervical cancer.'),
  ('priorities', 13, 'A 32-year-old client''s Pap smear shows ASC-US, and her reflex HPV test is negative. She is anxious and asks whether she needs a procedure. Which response by the nurse is best?', '[{"id": "a", "text": "She will need a colposcopy with biopsy to evaluate the cells"}, {"id": "b", "text": "She can return to routine screening per the usual guidelines"}, {"id": "c", "text": "She will need a staging workup to determine the extent of disease"}, {"id": "d", "text": "She will need a repeat Pap smear and HPV test in six months"}]'::jsonb, '["b"]', 'With ASC-US, a negative HPV test means routine screening per guidelines; colposcopy is needed only if HPV is positive. Staging is reserved for confirmed cervical cancer.'),
  ('priorities', 14, 'A 28-year-old client''s Pap smear result is reported as a low-grade squamous intraepithelial lesion (LSIL). Which next step should the nurse anticipate?', '[{"id": "a", "text": "Reflex HPV testing to decide whether follow-up is needed"}, {"id": "b", "text": "Routine Pap screening again in another three years"}, {"id": "c", "text": "Colposcopy with biopsy of the cervix"}, {"id": "d", "text": "A staging workup with surgery, chemo, or radiation"}]'::jsonb, '["c"]', 'LSIL and HSIL results are followed by colposcopy with biopsy. HPV testing to triage is the approach for ASC-US, and staging is for confirmed cervical cancer.'),
  ('priorities', 15, 'A 24-year-old client completed the HPV vaccine series at age 12. She tells the nurse she plans to skip her Pap smears because she is ''protected now.'' Which response by the nurse is best?', '[{"id": "a", "text": "''Since you were vaccinated early, Pap smears can begin at 30.''"}, {"id": "b", "text": "''You only need Pap smears if you have had more than one sexual partner.''"}, {"id": "c", "text": "''Your vaccine replaces Pap smears as long as you were 9 to 26.''"}, {"id": "d", "text": "''The vaccine does not replace Pap smears, so screening continues.''"}]'::jsonb, '["d"]', 'The HPV vaccine does not replace Pap smear screening, so she should continue Pap smears every 3 years at her age. Vaccination does not change when screening starts.'),
  ('priorities', 16, 'The parent of an 11-year-old asks why the provider is recommending the HPV vaccine now, since the child is not sexually active. Which response by the nurse is best?', '[{"id": "a", "text": "The vaccine is recommended at 9–26 and works best before sexual activity begins"}, {"id": "b", "text": "The vaccine is given only after a first Pap smear, so it should wait until age 21"}, {"id": "c", "text": "The vaccine treats existing genital warts, so it is best given early in life"}, {"id": "d", "text": "The vaccine replaces later Pap smears, so it is best given before age 12"}]'::jsonb, '["a"]', 'The HPV vaccine is recommended for ages 9–26, ideally before sexual activity begins. It does not replace Pap screening, and HPV warts are managed with topical treatment or cryotherapy, not the vaccine.'),
  ('priorities', 17, 'A 41-year-old client who never received the HPV vaccine asks whether it is too late for her to get it. Which response by the nurse is best?', '[{"id": "a", "text": "It is too late, since the vaccine is only approved through age 26"}, {"id": "b", "text": "It may be given up to age 45 after discussion with her provider"}, {"id": "c", "text": "It is too late, since it works only before any sexual activity"}, {"id": "d", "text": "It must be given right away, since it will cure any current HPV"}]'::jsonb, '["b"]', 'The HPV vaccine can be given up to age 45 with shared clinical decision-making, although ages 9–26 are recommended. HPV has no cure; the vaccine prevents infection.'),
  ('priorities', 18, 'A 30-year-old client''s cervical screening shows infection with HPV type 16. She has no visible genital lesions. Which concern should the nurse identify as most important when teaching her?', '[{"id": "a", "text": "This strain causes painless chancres that need penicillin"}, {"id": "b", "text": "This strain mainly causes genital warts that need cryotherapy"}, {"id": "c", "text": "This strain is linked to cervical cancer, so follow-up matters"}, {"id": "d", "text": "This strain is cured by a single dose of ceftriaxone IM"}]'::jsonb, '["c"]', 'HPV strains 16 and 18 cause cervical cancer, whereas strains 6 and 11 cause warts. HPV has no cure, and penicillin and ceftriaxone treat syphilis and gonorrhea.'),
  ('priorities', 19, 'A nurse is identifying which clients at a college health clinic should be offered routine annual chlamydia screening. None of the clients have symptoms. Which client meets the criteria?', '[{"id": "a", "text": "A 26-year-old who is sexually active with one partner"}, {"id": "b", "text": "A 24-year-old who is sexually active with one partner"}, {"id": "c", "text": "A 23-year-old who has never been sexually active"}, {"id": "d", "text": "A 29-year-old who recently started a new sexual relationship"}]'::jsonb, '["b"]', 'All sexually active women under 25 should be screened annually for chlamydia, which is often asymptomatic. The 26- and 29-year-olds are over the age cutoff, and the 23-year-old is not sexually active.'),
  ('priorities', 20, 'A 20-year-old client asks why she is being screened for chlamydia when she has no symptoms at all. Which response by the nurse is best?', '[{"id": "a", "text": "Chlamydia always causes pelvic pain, so screening confirms a cure"}, {"id": "b", "text": "Chlamydia is often silent and can lead to PID and infertility"}, {"id": "c", "text": "Chlamydia causes cervical cancer, so it is screened with Paps"}, {"id": "d", "text": "Chlamydia causes painless chancres that are easy to overlook"}]'::jsonb, '["b"]', 'Chlamydia is often asymptomatic and is a major cause of PID and infertility, which is why sexually active women under 25 are screened annually. Painless chancres are a sign of primary syphilis.'),
  ('priorities', 21, 'A client at 28 weeks'' gestation is diagnosed with gonorrhea after reporting purulent vaginal discharge and dysuria. In addition to administering the prescribed treatment, which action by the nurse is the priority?', '[{"id": "a", "text": "Arrange for partner treatment and report the case to public health"}, {"id": "b", "text": "Teach her that this infection will cause genital warts in her newborn"}, {"id": "c", "text": "Prepare her for a cesarean birth because of the risk of transmission"}, {"id": "d", "text": "Teach her to take metronidazole for 7 days along with her partner"}]'::jsonb, '["a"]', 'Gonorrhea is reported to public health and the partner is treated; it causes PID, infertility, and neonatal ophthalmia. Cesarean birth is indicated for an active herpes outbreak at delivery, and metronidazole is the treatment for trichomonas.'),
  ('priorities', 22, 'A client presents with purulent vaginal discharge and dysuria, and testing confirms gonorrhea. Which medication order should the nurse anticipate?', '[{"id": "a", "text": "Penicillin G as the drug of choice"}, {"id": "b", "text": "Ceftriaxone IM as a single dose"}, {"id": "c", "text": "Metronidazole for both partners"}, {"id": "d", "text": "Acyclovir to suppress outbreaks"}]'::jsonb, '["b"]', 'Gonorrhea is treated with a single dose of ceftriaxone IM. Penicillin G treats syphilis, metronidazole treats trichomonas, and acyclovir suppresses herpes outbreaks.'),
  ('priorities', 23, 'A client reports a single sore on her labia that she noticed a week ago. On exam it is a firm ulcer that she says has never hurt. Which medication should the nurse anticipate the provider will order?', '[{"id": "a", "text": "Acyclovir"}, {"id": "b", "text": "Ceftriaxone"}, {"id": "c", "text": "Metronidazole"}, {"id": "d", "text": "Penicillin G"}]'::jsonb, '["d"]', 'A painless chancre is primary syphilis, and penicillin G is the drug of choice. Painful vesicles or ulcers suggest herpes, which is treated with acyclovir.'),
  ('priorities', 24, 'A client who had an untreated painless genital sore two months ago now has a diffuse rash that includes her palms and the soles of her feet. Which stage of infection does the nurse recognize?', '[{"id": "a", "text": "Primary syphilis"}, {"id": "b", "text": "Secondary syphilis"}, {"id": "c", "text": "Tertiary syphilis"}, {"id": "d", "text": "Recurrent herpes"}]'::jsonb, '["b"]', 'Secondary syphilis presents with a diffuse rash on the palms and soles, following the painless chancre of primary syphilis. Tertiary syphilis causes cardiovascular and neurologic damage.'),
  ('priorities', 25, 'A client at her first prenatal visit at 9 weeks'' gestation asks why she is being tested for syphilis when she has no sores or rash. Which response by the nurse is best?', '[{"id": "a", "text": "Syphilis can cross the placenta and cause congenital syphilis in the baby"}, {"id": "b", "text": "Syphilis is tested only in clients who report a painless sore or a rash"}, {"id": "c", "text": "Syphilis causes cervical cancer, so it is tested along with the Pap smear"}, {"id": "d", "text": "Syphilis can be cured only with a cesarean birth to prevent its transmission"}]'::jsonb, '["a"]', 'Syphilis can cross the placenta and cause congenital syphilis, so it is tested at the first prenatal visit. Cesarean birth is the measure for an active herpes outbreak at delivery.'),
  ('priorities', 26, 'A client at 39 weeks'' gestation with a history of genital herpes is admitted in early labor. On assessment the nurse finds painful vesicles on her labia that appeared yesterday. Which action by the nurse is the priority?', '[{"id": "a", "text": "Give penicillin G before delivery to protect the newborn"}, {"id": "b", "text": "Continue routine labor care, since herpes is lifelong anyway"}, {"id": "c", "text": "Notify the provider and prepare for a likely cesarean birth"}, {"id": "d", "text": "Give acyclovir now, since it will clear the virus before birth"}]'::jsonb, '["c"]', 'An active herpes outbreak at delivery calls for a cesarean birth to prevent neonatal herpes. Acyclovir suppresses outbreaks but does not cure, and penicillin G treats syphilis.'),
  ('priorities', 27, 'A client with recurrent genital herpes has been prescribed acyclovir. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''Acyclovir will help to keep my outbreaks under control.''"}, {"id": "b", "text": "''I may still shed the virus even when I have no sores.''"}, {"id": "c", "text": "''I should tell my provider if I have an outbreak near delivery.''"}, {"id": "d", "text": "''Once I finish the acyclovir, the herpes will be cured.''"}]'::jsonb, '["d"]', 'Acyclovir suppresses outbreaks but does not cure herpes, and viral shedding is lifelong. An outbreak at delivery requires cesarean birth, so reporting it is correct.'),
  ('priorities', 28, 'A client with a history of genital herpes calls to report tingling and burning in her genital area since this morning, but she sees no sores yet. Which interpretation by the nurse is best?', '[{"id": "a", "text": "These symptoms suggest a prodrome before a new outbreak"}, {"id": "b", "text": "These symptoms suggest primary syphilis is developing"}, {"id": "c", "text": "These symptoms suggest a trichomonas infection is starting"}, {"id": "d", "text": "These symptoms suggest the herpes infection has been cured"}]'::jsonb, '["a"]', 'Herpes has a prodrome of tingling or burning before painful vesicles appear, and it recurs. Primary syphilis presents with a painless chancre, and trichomonas presents with frothy discharge.'),
  ('priorities', 29, 'A client reports a frothy, yellow-green, foul-smelling vaginal discharge with itching. The speculum exam shows a strawberry-appearing cervix. Which instruction is most important for the nurse to include in teaching?', '[{"id": "a", "text": "Her partner must also be treated with metronidazole"}, {"id": "b", "text": "She will need a single dose of ceftriaxone IM today"}, {"id": "c", "text": "She will need acyclovir to suppress future outbreaks"}, {"id": "d", "text": "She should be vaccinated against HPV types 6 and 11"}]'::jsonb, '["a"]', 'Frothy yellow-green foul-smelling discharge with a strawberry cervix indicates trichomonas, which is treated with metronidazole in both partners. Ceftriaxone treats gonorrhea, and acyclovir treats herpes.'),
  ('priorities', 30, 'A 23-year-old client has lower abdominal pain, a temperature of 38.6°C (101.5°F), and mucopurulent cervical discharge. During the pelvic exam she jumps when the provider moves her cervix. Which condition is the nurse''s priority concern?', '[{"id": "a", "text": "Primary syphilis"}, {"id": "b", "text": "Pelvic inflammatory disease"}, {"id": "c", "text": "Trichomonas infection"}, {"id": "d", "text": "Fibrocystic changes"}]'::jsonb, '["b"]', 'Pelvic pain, fever, mucopurulent cervical discharge, and cervical motion tenderness (the chandelier sign) are the classic presentation of PID. Trichomonas presents with frothy discharge and a strawberry cervix, not cervical motion tenderness.'),
  ('priorities', 31, 'A nurse is reviewing four clients newly diagnosed with pelvic inflammatory disease. Which client should the nurse anticipate will need hospital admission rather than outpatient treatment?', '[{"id": "a", "text": "A 22-year-old with mild pelvic pain and a low-grade fever"}, {"id": "b", "text": "A 25-year-old whose partner has not yet been treated"}, {"id": "c", "text": "A 30-year-old who uses barrier contraception inconsistently"}, {"id": "d", "text": "A 27-year-old who is 10 weeks pregnant with pelvic pain"}]'::jsonb, '["d"]', 'Clients with PID are hospitalized if the disease is severe, they are pregnant, or a tubo-ovarian abscess is suspected. Mild disease, untreated partners, and inconsistent barrier use are not listed criteria for admission.'),
  ('priorities', 32, 'A nurse is screening four clients who request combined oral contraceptives. Which client''s history should the nurse report to the provider as a contraindication?', '[{"id": "a", "text": "A 24-year-old nonsmoker who has regular monthly cycles"}, {"id": "b", "text": "A 31-year-old with a past benign fibroadenoma"}, {"id": "c", "text": "A 38-year-old who smokes a pack of cigarettes daily"}, {"id": "d", "text": "A 33-year-old with tender breasts before her period"}]'::jsonb, '["c"]', 'Combined OCPs are contraindicated in smokers over 35 because of high DVT and stroke risk. A fibroadenoma is not cancerous, and premenstrual breast tenderness reflects benign fibrocystic changes.'),
  ('priorities', 33, 'A 29-year-old nonsmoker requests combined oral contraceptives. Her history includes migraine headaches that begin with an aura. Which action by the nurse is best?', '[{"id": "a", "text": "Teach her to take the pill at the same time each day"}, {"id": "b", "text": "Report the history to the provider before the pill is prescribed"}, {"id": "c", "text": "Reassure her that combined pills are safe because she does not smoke"}, {"id": "d", "text": "Advise her to take the pill only on days when she has no headache"}]'::jsonb, '["b"]', 'Migraines with aura are a contraindication to combined OCPs, so this history must be reported before prescribing. Being a nonsmoker does not remove this contraindication.'),
  ('priorities', 34, 'A client who is 4 weeks postpartum and exclusively breastfeeding requests an oral contraceptive. Which option should the nurse anticipate the provider will recommend?', '[{"id": "a", "text": "A combined estrogen-progestin pill"}, {"id": "b", "text": "Plan B taken after each intercourse"}, {"id": "c", "text": "A progestin-only ''mini-pill''"}, {"id": "d", "text": "The natural family planning method"}]'::jsonb, '["c"]', 'The progestin-only mini-pill is safe for breastfeeding mothers and those who cannot use estrogen. Plan B is not for regular use, and natural family planning is the least reliable method and requires regular cycles.'),
  ('priorities', 35, 'A breastfeeding client started the progestin-only ''mini-pill'' last month. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''I set an alarm so I take it at the same time each day.''"}, {"id": "b", "text": "''This pill is a safe choice while I am breastfeeding.''"}, {"id": "c", "text": "''This pill does not contain any estrogen in it.''"}, {"id": "d", "text": "''I take it in the morning or at night, whenever I remember.''"}]'::jsonb, '["d"]', 'The mini-pill must be taken at the exact same time daily, so taking it whenever she remembers requires correction. It is safe for breastfeeding and for those who cannot use estrogen.'),
  ('priorities', 36, 'A client who has taken combined oral contraceptives for two years calls reporting pain and swelling in her right calf that began yesterday. Which action by the nurse is the priority?', '[{"id": "a", "text": "Reassure her that leg discomfort is common in the first 3 months"}, {"id": "b", "text": "Advise her to stop the pill and be evaluated for a blood clot now"}, {"id": "c", "text": "Tell her to take the pill at the same time each day to avoid this"}, {"id": "d", "text": "Recommend switching to Plan B as her regular form of contraception"}]'::jsonb, '["b"]', 'Severe calf pain and swelling is the S in ACHES, suggesting DVT, and ACHES signs mean stopping the pill immediately and reporting. Side effects expected in the first 3 months are nausea, breast tenderness, and spotting, not calf pain.'),
  ('priorities', 37, 'A nurse receives four phone messages from clients taking combined oral contraceptives. Which client should the nurse call back first?', '[{"id": "a", "text": "A client in her second month with mild nausea after each pill"}, {"id": "b", "text": "A client in her first month with light spotting between periods"}, {"id": "c", "text": "A client in her third month with tender breasts most mornings"}, {"id": "d", "text": "A client with a sudden severe headache and new blurred vision"}]'::jsonb, '["d"]', 'A severe new-onset headache and blurred vision are ACHES signs that can indicate stroke and must be reported immediately. Nausea, breast tenderness, and spotting are expected side effects in the first 3 months.'),
  ('priorities', 38, 'A client had unprotected intercourse 4 days (96 hours) ago and does not want to become pregnant. She asks which emergency contraception option would be most effective at this point. Which response by the nurse is best?', '[{"id": "a", "text": "A copper IUD inserted now, since it works if placed within 5 days"}, {"id": "b", "text": "Plan B, since it is the most effective emergency method overall"}, {"id": "c", "text": "No option remains, since emergency methods work only within 72 hours"}, {"id": "d", "text": "A combined pill started today, taken daily at the same time each day"}]'::jsonb, '["a"]', 'The copper IUD is the most effective emergency contraception overall and works if inserted within 5 days. Plan B is most effective within 72 hours, though it can be used up to 120 hours.'),
  ('priorities', 39, 'A nurse has taught a client who is requesting levonorgestrel (Plan B) after a condom broke last night. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''It works best if I take it within 72 hours of the sex.''"}, {"id": "b", "text": "''I might have some nausea or irregular bleeding afterward.''"}, {"id": "c", "text": "''If I''m already pregnant, this pill will end the pregnancy.''"}, {"id": "d", "text": "''This is not meant to be my regular form of birth control.''"}]'::jsonb, '["c"]', 'Plan B prevents ovulation or fertilization and does not terminate an existing pregnancy. Nausea and irregular bleeding are expected effects, and it is not for regular use.'),
  ('priorities', 40, 'A 34-year-old client with very heavy menstrual periods wants a long-acting IUD and asks which type is the better fit for her. Which response by the nurse is best?', '[{"id": "a", "text": "The copper IUD, because it is non-hormonal and lasts 10–12 years"}, {"id": "b", "text": "The copper IUD, because it usually makes menstrual periods lighter"}, {"id": "c", "text": "The hormonal IUD, because it lasts longer than any copper device"}, {"id": "d", "text": "The hormonal IUD, because it often lightens periods or stops them"}]'::jsonb, '["d"]', 'Hormonal IUDs cause the lightest periods or amenorrhea, while the copper IUD causes heavier periods. The copper IUD actually lasts longer (10–12 years) than hormonal IUDs (3–8 years).'),
  ('priorities', 41, 'A client uses a diaphragm with spermicide. She inserted it at 9:00 p.m., and intercourse occurred at 10:00 p.m. She asks the earliest time she may remove it. Which time should the nurse give?', '[{"id": "a", "text": "11:00 p.m."}, {"id": "b", "text": "1:00 a.m."}, {"id": "c", "text": "4:00 a.m."}, {"id": "d", "text": "6:00 a.m."}]'::jsonb, '["c"]', 'The diaphragm must be left in at least 6 hours after intercourse, so the earliest removal is 10:00 p.m. plus 6 hours, or 4:00 a.m. Counting from the 9:00 p.m. insertion would wrongly give 3:00 a.m., and 6:00 a.m. is acceptable but not the earliest.'),
  ('priorities', 42, 'A client who gave birth 8 weeks ago plans to resume using the diaphragm she used before her pregnancy. Which action by the nurse is best?', '[{"id": "a", "text": "Arrange for her to be refitted for a diaphragm before she uses it"}, {"id": "b", "text": "Teach her to use the diaphragm alone, without adding spermicide"}, {"id": "c", "text": "Teach her to insert it at least 8 hours before having intercourse"}, {"id": "d", "text": "Teach her to remove it within 2 hours after intercourse occurs"}]'::jsonb, '["a"]', 'A diaphragm must be refitted after pregnancy. It is always used with spermicide, inserted less than 6 hours before intercourse, and left in at least 6 hours after.'),
  ('priorities', 43, 'A client whose menstrual cycles vary from 24 to 45 days says she prefers natural family planning and wants to avoid sex only during days 10–17. Which response by the nurse is best?', '[{"id": "a", "text": "This method is the most reliable choice for a client with her history"}, {"id": "b", "text": "This method works well if she avoids intercourse on days 1 through 7"}, {"id": "c", "text": "This method is effective for her as long as her partner uses spermicide"}, {"id": "d", "text": "This method is least reliable and requires regular cycles to work well"}]'::jsonb, '["d"]', 'Natural family planning is the least reliable method and requires regular cycles, so it is a poor fit for her irregular cycles. Avoiding days 10–17 assumes a regular cycle.'),
  ('priorities', 44, 'A client who plans to try to conceive in about 6 months asks whether Depo-Provera injections would be a good method until then. Which response by the nurse is best?', '[{"id": "a", "text": "It is a good fit, since fertility returns as soon as she stops"}, {"id": "b", "text": "It is a good fit, since one shot lasts about 6 months"}, {"id": "c", "text": "Fertility may take up to a year to return after stopping it"}, {"id": "d", "text": "It should be avoided, since it causes heavier periods"}]'::jsonb, '["c"]', 'After stopping Depo-Provera, fertility may take up to 1 year to return, which conflicts with her plan. Injections are given every 3 months, and the method causes irregular bleeding or amenorrhea rather than heavier periods.'),
  ('priorities', 45, 'A client who uses latex condoms for STI and pregnancy prevention tells the nurse she uses baby oil as a lubricant to reduce friction. Which response by the nurse is best?', '[{"id": "a", "text": "Condoms prevent pregnancy only, so a second method is needed for STIs"}, {"id": "b", "text": "Any lubricant is acceptable as long as the condom is applied correctly each time"}, {"id": "c", "text": "Baby oil is acceptable if she also adds a spermicide to the condom"}, {"id": "d", "text": "Oil-based products can break latex, so a water-based lubricant is needed"}]'::jsonb, '["d"]', 'Only water-based lubricants should be used, because oil-based products can break condom latex. Condoms prevent both STIs and pregnancy.'),
  ('priorities', 46, 'A client is on postoperative day 1 after an abdominal hysterectomy. Her vital signs are stable, and her perineal pad shows scant drainage. Which nursing action is the priority to prevent a serious complication?', '[{"id": "a", "text": "Assist her with early ambulation and apply compression stockings"}, {"id": "b", "text": "Teach her to avoid any heavy lifting for 6 weeks after surgery"}, {"id": "c", "text": "Teach her about the hot flashes that she can expect after surgery"}, {"id": "d", "text": "Teach her Kegel exercises to strengthen her pelvic floor muscles"}]'::jsonb, '["a"]', 'After hysterectomy, DVT/PE risk is addressed with early ambulation and compression stockings. Lifting restrictions are discharge teaching, and hot flashes occur only if the ovaries were removed.'),
  ('priorities', 47, 'A client is being discharged 3 days after a hysterectomy in which both ovaries were also removed. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''I may have hot flashes and mood changes since my ovaries are gone.''"}, {"id": "b", "text": "''I will keep track of how many pads I use and report heavy bleeding.''"}, {"id": "c", "text": "''I can lift my 30-pound toddler again once my incision stops hurting.''"}, {"id": "d", "text": "''I will keep walking at home to lower my risk of getting a blood clot.''"}]'::jsonb, '["c"]', 'Clients should avoid heavy lifting for 6 weeks after hysterectomy, regardless of incision pain. Surgical menopause symptoms, pad counts, and ambulation to reduce DVT risk are correct.'),
  ('priorities', 48, 'A nurse is supervising an unlicensed assistive personnel (UAP) caring for a client on the first day after a left mastectomy. Which action by the UAP requires correction?', '[{"id": "a", "text": "Placing the client''s left arm on pillows so that it stays elevated"}, {"id": "b", "text": "Wrapping the blood pressure cuff on the client''s left upper arm for vitals"}, {"id": "c", "text": "Reporting new redness and warmth at the incision site to the nurse right away"}, {"id": "d", "text": "Reminding the client to do the gentle arm exercises the nurse taught her"}]'::jsonb, '["b"]', 'No BP, IV, or lab draws are done on the affected arm because of lymphedema risk. Elevating the arm, reporting signs of infection, and gentle ROM exercises are appropriate.'),
  ('priorities', 49, 'A client at 30 weeks'' gestation asks whether any vaccines are recommended for her at this point in her pregnancy. Which response by the nurse is best?', '[{"id": "a", "text": "Vaccines should wait until after delivery to protect the baby"}, {"id": "b", "text": "The flu shot is unsafe during pregnancy, so it should be skipped"}, {"id": "c", "text": "Tdap should have been given in the first trimester to be effective"}, {"id": "d", "text": "Tdap is given in the third trimester to protect baby from pertussis"}]'::jsonb, '["d"]', 'Tdap is given in the third trimester to protect the baby from pertussis, and the flu shot is safe in pregnancy. At 30 weeks she is in the third trimester.'),
  ('priorities', 50, 'A client who started combined oral contraceptives 6 weeks ago calls reporting light spotting between periods, mild nausea, and breast tenderness. She has no leg, chest, or vision symptoms. Which response by the nurse is best?', '[{"id": "a", "text": "These are common in the first 3 months, so continue the pill"}, {"id": "b", "text": "These are ACHES warning signs, so stop the pill immediately"}, {"id": "c", "text": "These suggest a blood clot, so go to the emergency department"}, {"id": "d", "text": "These mean the pill failed, so take Plan B as a backup tonight"}]'::jsonb, '["a"]', 'Nausea, breast tenderness, and spotting are common combined OCP side effects in the first 3 months. ACHES signs are severe abdominal pain, chest pain, severe headache, eye changes, and severe leg pain, none of which she has.'),
  ('fertilization', 1, 'A client who is trying to avoid pregnancy reports a single episode of unprotected intercourse 4 days before an ovulation predictor confirmed that she ovulated. She says, ''The egg was not even released yet, so I can''t be pregnant.'' Which response by the nurse is best?', '[{"id": "a", "text": "Pregnancy is unlikely, because the egg stays viable for only 12–24 hours after it is released"}, {"id": "b", "text": "Pregnancy is possible, because sperm can survive up to 5 days in the female reproductive tract"}, {"id": "c", "text": "Pregnancy is unlikely, because sperm survive only about 24 hours after they are deposited"}, {"id": "d", "text": "Pregnancy is possible, because the egg remains viable for about 5 days after it has been released"}]'::jsonb, '["b"]', 'Sperm can survive up to 5 days in the female reproductive tract, so intercourse several days before ovulation can still lead to fertilization. The 12–24 hour figure is true of the egg, but it limits fertility after ovulation, not before.'),
  ('fertilization', 2, 'A couple trying to conceive confirmed by LH testing that the client ovulated early Monday morning. Their only intercourse that cycle occurred Wednesday evening, about 60 hours later. The client asks about her chance of conceiving this cycle. Which explanation by the nurse is best?', '[{"id": "a", "text": "Conception is unlikely, because the egg remains viable for only about 12–24 hours after ovulation"}, {"id": "b", "text": "Conception is likely, because sperm can survive for up to 5 days within the reproductive tract"}, {"id": "c", "text": "Conception is likely, because the fertile window extends for several days after ovulation occurs"}, {"id": "d", "text": "Conception is unlikely, because the zona pellucida locks shut within the first hour after ovulation"}]'::jsonb, '["a"]', 'The egg is viable for only 12–24 hours after ovulation, so intercourse about 60 hours later is too late. Sperm survival matters only when sperm are already present before ovulation; the fertile window extends days before ovulation but only 1 day after.'),
  ('fertilization', 3, 'A client with a 28-day cycle reliably ovulates on cycle day 14. She wants to time intercourse to avoid pregnancy and asks which day carries the lowest chance of conception. Considering egg and sperm survival, which day should the nurse identify?', '[{"id": "a", "text": "Cycle day 10"}, {"id": "b", "text": "Cycle day 12"}, {"id": "c", "text": "Cycle day 14"}, {"id": "d", "text": "Cycle day 17"}]'::jsonb, '["d"]', 'Sperm survive up to 5 days, so intercourse on days 10 and 12 can still lead to fertilization on day 14, while the egg survives only 12–24 hours, so by day 17 it is no longer viable. The fertile window extends several days before ovulation but only 1 day after.'),
  ('fertilization', 4, 'A client whose fallopian tube ends were scarred by a past pelvic infection now has a positive pregnancy test. The provider orders close follow-up to confirm where the pregnancy has implanted. The client asks why her history matters. Which explanation by the nurse is best?', '[{"id": "a", "text": "Damaged fimbriae may not move the egg normally, so it may implant within the tube"}, {"id": "b", "text": "Damaged fimbriae may keep the zona pellucida from locking after the first sperm enters"}, {"id": "c", "text": "Damaged fimbriae may stop the corpus luteum from producing progesterone after ovulation"}, {"id": "d", "text": "Damaged fimbriae may block sperm from passing through the cervix into the uterine cavity"}]'::jsonb, '["a"]', 'Fimbriae sweep the egg into the tube; if they are damaged, as from PID, the egg may implant in the tube, causing an ectopic pregnancy. Fimbriae have no role in the zona pellucida block or in corpus luteum function.'),
  ('fertilization', 5, 'During an infertility workup, imaging shows that the widest outer segment of both of a client''s fallopian tubes is obstructed, while her uterus, cervix, and ovaries appear normal. The client asks why this finding matters most for conception. Which response by the nurse is best?', '[{"id": "a", "text": "This segment is where the blastocyst normally implants and grows"}, {"id": "b", "text": "This segment is where the egg is stored until the LH surge occurs"}, {"id": "c", "text": "This segment is where egg and sperm normally meet for fertilization"}, {"id": "d", "text": "This segment is where the trophoblast begins secreting the hCG hormone"}]'::jsonb, '["c"]', 'Fertilization occurs in the ampulla, the widest outer segment of the fallopian tube. Implantation occurs in the uterine lining, and the ovaries store and release eggs.'),
  ('fertilization', 6, 'A client had a single episode of unprotected intercourse 5 days ago, which she believes occurred on her day of ovulation. A home pregnancy test this morning is negative, and she asks whether she can be sure she is not pregnant. Which response by the nurse is best?', '[{"id": "a", "text": "The result is reliable, because hCG enters the urine within 24 hours after fertilization"}, {"id": "b", "text": "The result may be falsely negative, because hCG is usually detectable 10–14 days after fertilization"}, {"id": "c", "text": "The result may be falsely negative, because hCG appears only once the placenta takes over at 8–12 weeks"}, {"id": "d", "text": "The result is reliable, because implantation is completed by day 3 and hCG would already be present"}]'::jsonb, '["b"]', 'Sensitive home tests detect hCG about 10–14 days after fertilization, so testing at 5 days may give a false negative. hCG starts at implantation (days 6–10), not at the luteal-placental shift.'),
  ('fertilization', 7, 'A client with regular 28-day cycles conceived on cycle day 14. She plans to buy a sensitive home pregnancy test and asks when it would first be likely to turn positive. Which timeframe should the nurse give?', '[{"id": "a", "text": "Around cycle day 15–16, shortly after fertilization"}, {"id": "b", "text": "Around cycle day 17–19, when the morula forms"}, {"id": "c", "text": "Around cycle day 24–28, near the missed period"}, {"id": "d", "text": "Around cycle day 36–40, at the luteal-placental shift"}]'::jsonb, '["c"]', 'Home tests detect hCG about 10–14 days after fertilization (day 14 + 10–14 = cycle days 24–28), around the time of the first missed period. Earlier testing, such as at the morula stage, may yield a false negative.'),
  ('fertilization', 8, 'A client''s ovulation and fertilization both occurred on cycle day 14 of a 28-day cycle. The nurse is explaining when the embryo first begins producing the hormone that pregnancy tests detect. On which cycle day could this production begin at the earliest?', '[{"id": "a", "text": "Cycle day 15, as soon as the zygote forms"}, {"id": "b", "text": "Cycle day 17, when the morula is formed"}, {"id": "c", "text": "Cycle day 20, when implantation begins"}, {"id": "d", "text": "Cycle day 28, when the period is missed"}]'::jsonb, '["c"]', 'The trophoblast begins producing hCG at implantation, about 6–10 days after fertilization, so the earliest is day 14 + 6 = cycle day 20. The missed period is when a home test usually detects it, not when production starts.'),
  ('fertilization', 9, 'A client''s serum hCG is faintly detectable about 9 days after fertilization. She asks which part of the early pregnancy is producing this hormone. Which response by the nurse is best?', '[{"id": "a", "text": "The corpus luteum that remained on the ovary after the follicle ruptured"}, {"id": "b", "text": "The inner cell mass of the blastocyst that will become the baby"}, {"id": "c", "text": "The anterior pituitary gland, responding to the rise in estrogen"}, {"id": "d", "text": "The outer cell layer of the blastocyst that will form the placenta"}]'::jsonb, '["d"]', 'The trophoblast, the outer layer that becomes the placenta, releases hCG once it embeds in the uterine lining. The corpus luteum responds to hCG by making progesterone; it does not produce hCG.'),
  ('fertilization', 10, 'A client in early pregnancy has an hCG level far below expected for her dates. Ultrasound suggests poorly developed outer cell tissue around the embryo, while the inner cell mass appears to be present. Which developing structure should the nurse recognize as primarily affected?', '[{"id": "a", "text": "The future placenta"}, {"id": "b", "text": "The corpus luteum"}, {"id": "c", "text": "The zona pellucida"}, {"id": "d", "text": "The embryonic organs"}]'::jsonb, '["a"]', 'The trophoblast (outer layer) becomes the placenta and is the source of hCG, so poorly developed outer tissue with low hCG points to the future placenta. The inner cell mass, not the trophoblast, forms the embryo''s organs.'),
  ('fertilization', 11, 'A client who is 3 weeks past fertilization asks why her menstrual period has not started, since ''the lining sheds every month.'' Which explanation by the nurse is best?', '[{"id": "a", "text": "The placenta is already producing enough progesterone to keep the lining from shedding"}, {"id": "b", "text": "hCG signals the corpus luteum to keep producing progesterone, which maintains the lining"}, {"id": "c", "text": "hCG causes repeated LH surges that keep the Graafian follicle making estrogen"}, {"id": "d", "text": "Estrogen from the granulosa cells keeps the uterine lining in its proliferative, rebuilding phase"}]'::jsonb, '["b"]', 'hCG from the trophoblast tells the corpus luteum to keep producing progesterone, which maintains the thick, blood-rich lining. The placenta does not take over hormone production until 8–12 weeks.'),
  ('fertilization', 12, 'A client who is not pregnant asks why her period reliably starts about two weeks after she ovulates. Which explanation by the nurse is best?', '[{"id": "a", "text": "The LH surge on day 14 directly causes the endometrium to break down two weeks later"}, {"id": "b", "text": "Estrogen from the Graafian follicle peaks, and this peak causes the lining to shed"}, {"id": "c", "text": "Without hCG, the corpus luteum degenerates in about 14 days and progesterone drops"}, {"id": "d", "text": "FSH stimulates new primordial follicles, which then signal the lining to detach"}]'::jsonb, '["c"]', 'Without fertilization, the corpus luteum degenerates in about 14 days, progesterone drops, and menstruation occurs. The estrogen peak triggers the LH surge and ovulation, not menstruation.'),
  ('fertilization', 13, 'A client at 10 weeks'' gestation has had serial hCG levels that rose rapidly. She is worried after reading that her hCG will soon begin to fall. Which response by the nurse is best?', '[{"id": "a", "text": "A falling hCG at this stage means the corpus luteum is failing and needs evaluation"}, {"id": "b", "text": "hCG normally peaks around 10–12 weeks and then falls as the placenta takes over"}, {"id": "c", "text": "hCG should keep rising until delivery, so any decline would need to be reported"}, {"id": "d", "text": "hCG normally peaks at implantation, so it should already have been falling for weeks"}]'::jsonb, '["b"]', 'hCG levels peak at about 10–12 weeks and then fall as the placenta takes over hormone production. A decline at this point reflects the luteal-placental shift, not corpus luteum failure.'),
  ('fertilization', 14, 'A client at 7 weeks'' gestation is found to need urgent surgery on the ovary that contains her corpus luteum. When the team plans her care, which concern about the pregnancy should the nurse identify as the priority?', '[{"id": "a", "text": "Loss of the main source of progesterone that maintains the uterine lining"}, {"id": "b", "text": "Loss of the main source of the hCG hormone that pregnancy tests detect in urine"}, {"id": "c", "text": "Loss of the main source of FSH that is maturing the next follicle"}, {"id": "d", "text": "Loss of the main source of estrogen produced by the mature placenta"}]'::jsonb, '["a"]', 'Before 8–12 weeks, the corpus luteum, maintained by hCG, is the primary progesterone source that keeps the lining thick. hCG comes from the trophoblast, and the placenta has not yet taken over at 7 weeks.'),
  ('fertilization', 15, 'A client at 16 weeks'' gestation has an ovarian cyst involving the old corpus luteum and asks whether its removal would stop her body from making pregnancy hormones. Which response by the nurse is best?', '[{"id": "a", "text": "The corpus luteum is still the main progesterone source until the third trimester"}, {"id": "b", "text": "The placenta has taken over estrogen and progesterone production by this point"}, {"id": "c", "text": "The trophoblast hormone hCG directly maintains the lining without progesterone"}, {"id": "d", "text": "The anterior pituitary produces the progesterone needed after the first trimester"}]'::jsonb, '["b"]', 'After the luteal-placental shift at 8–12 weeks, the mature placenta takes over estrogen and progesterone production, so at 16 weeks the corpus luteum is no longer the primary source. hCG works by maintaining the corpus luteum''s progesterone output, not by replacing progesterone.'),
  ('fertilization', 16, 'A client at 6 weeks'' gestation has a low progesterone level, and the provider suspects the corpus luteum is not being adequately supported. The client asks which hormone normally prevents the corpus luteum from degenerating. Which response by the nurse is best?', '[{"id": "a", "text": "FSH from the anterior pituitary, which keeps stimulating the ovary"}, {"id": "b", "text": "Estrogen from the granulosa cells inside the ruptured follicle"}, {"id": "c", "text": "hCG from the trophoblast, which acts like LH on the corpus luteum"}, {"id": "d", "text": "Progesterone from the placenta, which has already fully matured"}]'::jsonb, '["c"]', 'hCG from the trophoblast acts like LH on the corpus luteum, preventing its degeneration and keeping progesterone high. At 6 weeks the placenta has not yet taken over hormone production.'),
  ('fertilization', 17, 'A nurse is explaining to a newly pregnant client how the pregnancy maintains the uterine lining after the blastocyst embeds. Which sequence of events is correct?', '[{"id": "a", "text": "Corpus luteum releases hCG → trophoblast produces progesterone → lining thickens"}, {"id": "b", "text": "Embryoblast releases hCG → follicle produces more estrogen → lining enters the proliferative phase"}, {"id": "c", "text": "Placenta releases hCG → corpus luteum degenerates → progesterone maintains the lining"}, {"id": "d", "text": "Trophoblast releases hCG → corpus luteum keeps making progesterone → lining is maintained"}]'::jsonb, '["d"]', 'At implantation the trophoblast releases hCG, which tells the corpus luteum to keep producing progesterone and maintain the thick, blood-rich lining. The corpus luteum responds to hCG rather than producing it.'),
  ('fertilization', 18, 'A client''s IVF report states that her egg was fertilized 12 hours ago and has not yet undergone its first cell division. She asks how the nurse would describe the fertilized egg at this point. Which response by the nurse is best?', '[{"id": "a", "text": "It is an embryo, because fertilization has already taken place in the tube"}, {"id": "b", "text": "It is a morula, a solid ball of cells that is ready to divide"}, {"id": "c", "text": "It is a blastocyst, with an inner cell mass and an outer layer"}, {"id": "d", "text": "It is a zygote, a single diploid cell formed from egg and sperm"}]'::jsonb, '["d"]', 'The zygote is the single diploid cell formed when one sperm fuses with one egg, before its first division. The term embryo is typically used after the blastocyst implants, and the morula and blastocyst come days later.'),
  ('fertilization', 19, 'A client''s IVF embryo report describes a well-formed inner cell mass. The client asks what this group of cells will go on to produce. Which explanation by the nurse is best?', '[{"id": "a", "text": "It invades the endometrium and begins producing hCG"}, {"id": "b", "text": "It forms the three germ layers that make the body''s organs"}, {"id": "c", "text": "It forms the placenta and chorion around the pregnancy"}, {"id": "d", "text": "It forms the shell that blocks additional sperm from entering"}]'::jsonb, '["b"]', 'The inner cell mass differentiates into the three germ layers that form all the body''s organs. Invading the endometrium, producing hCG, and forming the placenta and chorion are functions of the trophoblast.'),
  ('fertilization', 20, 'After a teaching session on early development, a pregnant client describes the blastocyst. Which statement by the client indicates correct understanding?', '[{"id": "a", "text": "''The inner cells become my baby, and the outer cells become the placenta.''"}, {"id": "b", "text": "''The outer cells become my baby, and the inner cells become the placenta.''"}, {"id": "c", "text": "''The inner cells make the hCG, and the outer cells become the baby''s organs.''"}, {"id": "d", "text": "''The inner cells become the placenta, and the outer cells form the zona pellucida.''"}]'::jsonb, '["a"]', 'The embryoblast (inner cell mass) becomes the baby and the trophoblast (outer layer) becomes the placenta. Saying the outer cells become the baby reverses the two layers, and hCG comes from the outer layer, not the inner cells.'),
  ('fertilization', 21, 'A client undergoing IVF is told her embryo will be transferred on day 3 after fertilization. She asks what the embryo will look like at that point. Which description by the nurse is best?', '[{"id": "a", "text": "A hollow structure with an inner cell mass and outer layer"}, {"id": "b", "text": "A single diploid cell that has not yet begun to divide"}, {"id": "c", "text": "A solid ball of about 16 cells that is still dividing"}, {"id": "d", "text": "A structure already embedded within the uterine lining"}]'::jsonb, '["c"]', 'By days 3–4 the embryo is a morula, a solid ball of about 16 cells. The hollow blastocyst with inner cell mass and trophoblast does not form until days 5–6.'),
  ('fertilization', 22, 'A client''s IVF report states that her embryo on day 5 is a hollow structure containing an inner cell mass and an outer cell layer. She asks whether this means development is behind schedule. Which response by the nurse is best?', '[{"id": "a", "text": "No; a hollow blastocyst is the expected stage on days 5–6"}, {"id": "b", "text": "Yes; by day 5 it should have embedded in the uterine lining"}, {"id": "c", "text": "Yes; on day 5 it should still be a solid ball of 16 cells"}, {"id": "d", "text": "No; but it should have stayed a single cell until day 6"}]'::jsonb, '["a"]', 'The blastocyst, a hollow structure with an embryoblast and trophoblast, is expected on days 5–6. The solid morula occurs on days 3–4, and implantation occurs on days 6–10.'),
  ('fertilization', 23, 'A client is told that her embryo was a solid ball of about 16 cells on day 4. She asks what must happen next before a pregnancy can be established. Which sequence should the nurse describe?', '[{"id": "a", "text": "It implants as a solid ball, then hollows out into a blastocyst inside the lining"}, {"id": "b", "text": "It hollows into a blastocyst, hatches from the zona pellucida, then implants"}, {"id": "c", "text": "It hatches from the zona pellucida, returns to a zygote, then divides again"}, {"id": "d", "text": "It implants immediately, then the zona pellucida locks to block more sperm"}]'::jsonb, '["b"]', 'The morula becomes a hollow blastocyst by days 5–6, hatches from the zona pellucida, and then implants during days 6–10. Implantation occurs at the blastocyst stage, not as a solid morula.'),
  ('fertilization', 24, 'A client''s IVF day-6 blastocyst is described as having difficulty escaping the zona pellucida. The client asks why this would interfere with the pregnancy. Which explanation by the nurse is best?', '[{"id": "a", "text": "The trophoblast cells need direct contact with the endometrium to implant"}, {"id": "b", "text": "The embryoblast must leave the shell before it can become the placenta"}, {"id": "c", "text": "The zona pellucida must stay intact until implantation to block sperm"}, {"id": "d", "text": "Hatching is what triggers the LH surge that maintains the thick uterine lining"}]'::jsonb, '["a"]', 'By days 5–6 the blastocyst hatches by digesting the zona pellucida so trophoblast cells can contact the endometrium and implant. The embryoblast becomes the baby, not the placenta.'),
  ('fertilization', 25, 'A client tracking her cycle had intercourse on the day she ovulated, and fertilization occurred that day. She asks when the developing embryo will begin embedding in her uterine lining. Which timeframe should the nurse give?', '[{"id": "a", "text": "About 1–2 days after fertilization"}, {"id": "b", "text": "About 3–4 days after fertilization"}, {"id": "c", "text": "About 6–10 days after fertilization"}, {"id": "d", "text": "About 12–16 days after fertilization"}]'::jsonb, '["c"]', 'Implantation occurs on days 6–10 after fertilization, once the blastocyst has formed and hatched. Days 3–4 is the morula stage, which comes before implantation.'),
  ('fertilization', 26, 'A nursing student is describing to a client the events that follow her LH surge in a cycle in which she conceives. Which sequence, if stated by the student, is correct?', '[{"id": "a", "text": "Follicle ruptures → fimbriae sweep egg into tube → fertilization in ampulla → morula → blastocyst → implantation"}, {"id": "b", "text": "Fimbriae sweep egg into tube → follicle ruptures → fertilization in the uterus → blastocyst → morula → implantation"}, {"id": "c", "text": "Follicle ruptures → fertilization in ampulla → implantation → morula → blastocyst → corpus luteum forms"}, {"id": "d", "text": "Follicle ruptures → egg enters uterus → fertilization in endometrium → zygote → morula → blastocyst forms"}]'::jsonb, '["a"]', 'The LH surge ruptures the Graafian follicle, the fimbriae sweep the egg into the tube, fertilization occurs in the ampulla, and the zygote becomes a morula and then a blastocyst that implants. Implantation follows the blastocyst stage, and fertilization occurs in the tube, not the uterus.'),
  ('fertilization', 27, 'A client with normal ovaries and open fallopian tubes is found to have an obstruction of the opening between her vagina and uterus. She asks why this could prevent pregnancy when her eggs are released normally. Which response by the nurse is best?', '[{"id": "a", "text": "The fertilized egg normally implants and grows in that opening"}, {"id": "b", "text": "Sperm must pass from vagina to cervix to uterus to reach the tube"}, {"id": "c", "text": "The egg must travel out through that opening to meet the sperm"}, {"id": "d", "text": "That opening produces the progesterone that maintains the uterine lining"}]'::jsonb, '["b"]', 'The cervix is the opening between vagina and uterus, and sperm must travel vagina → cervix → uterus → fallopian tube to reach the egg. The fertilized egg implants in the uterus, not the cervix.'),
  ('fertilization', 28, 'After teaching about reproductive anatomy, a nurse asks a client who is planning pregnancy to describe the role of each structure. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''The fimbriae sweep the released egg into my fallopian tube.''"}, {"id": "b", "text": "''My ovaries store and release eggs and make estrogen and progesterone.''"}, {"id": "c", "text": "''My cervix is where the fertilized egg will implant and grow.''"}, {"id": "d", "text": "''My uterine lining thickens for pregnancy and sheds with my period.''"}]'::jsonb, '["c"]', 'The uterus is where the fertilized egg implants and grows; the cervix is the opening between the vagina and uterus. The other statements correctly describe the fimbriae, ovaries, and endometrium.'),
  ('fertilization', 29, 'A client asks whether her baby will grow in the same place where the egg and sperm first meet. Which response by the nurse is best?', '[{"id": "a", "text": "Yes; fertilization and implantation both take place in the ampulla"}, {"id": "b", "text": "No; fertilization occurs in the uterus, and the embryo then moves out into the tube to grow"}, {"id": "c", "text": "No; fertilization occurs in the ampulla, and implantation occurs in the uterine lining"}, {"id": "d", "text": "Yes; fertilization and implantation both take place in the endometrium"}]'::jsonb, '["c"]', 'Fertilization normally occurs in the ampulla of the fallopian tube, and the blastocyst later embeds in the uterine lining. Implantation in the tube is abnormal, and fertilization does not occur in the uterus.'),
  ('fertilization', 30, 'An embryology report for a client undergoing IVF notes that an egg was penetrated by two sperm and the embryo is not suitable for transfer. The client asks why this happened and why it matters. Which explanation by the nurse is best?', '[{"id": "a", "text": "The fimbriae failed to sweep the egg away, which can lead to tubal implantation"}, {"id": "b", "text": "The corpus luteum failed to lock the egg, which can cause low progesterone levels"}, {"id": "c", "text": "The zona pellucida block failed, which can cause abnormal chromosome numbers"}, {"id": "d", "text": "The trophoblast failed to form, which can prevent the placenta from developing"}]'::jsonb, '["c"]', 'The zona pellucida normally locks after the first sperm enters (polyspermy block), which is essential to prevent abnormal chromosome numbers. Fimbriae, corpus luteum, and trophoblast do not prevent entry of extra sperm.'),
  ('fertilization', 31, 'A client asks how, with millions of sperm present, the egg ends up fertilized by just one. Which client statement after teaching indicates correct understanding?', '[{"id": "a", "text": "''After one sperm gets in, the zona pellucida locks the others out.''"}, {"id": "b", "text": "''After one sperm gets in, the fimbriae sweep the other sperm away.''"}, {"id": "c", "text": "''After one sperm gets in, the corpus luteum blocks the other sperm.''"}, {"id": "d", "text": "''After one sperm gets in, the trophoblast seals the egg from others.''"}]'::jsonb, '["a"]', 'The zona pellucida allows only one sperm to enter and then locks, the polyspermy block. Fimbriae sweep the egg into the tube, and the trophoblast forms later as part of the blastocyst.'),
  ('fertilization', 32, 'A client whose partner has a low sperm count asks why so many sperm are needed when only one fertilizes the egg. Which response by the nurse is best?', '[{"id": "a", "text": "About half of the sperm reach the tube, and several must enter the egg together"}, {"id": "b", "text": "Of 200–500 million deposited, only about 200 reach the tube, and one fertilizes"}, {"id": "c", "text": "Each sperm fertilizes part of the egg, so many are needed to complete fertilization"}, {"id": "d", "text": "Most sperm are needed to dissolve the zona pellucida before implantation can occur"}]'::jsonb, '["b"]', 'Of 200–500 million sperm deposited, only about 200 reach the fallopian tube, and only one fertilizes the egg. Multiple sperm entering the egg is prevented by the zona pellucida block.'),
  ('fertilization', 33, 'During genetic counseling, a pregnant client asks how her baby receives half of its chromosomes from each parent. Which explanation by the nurse is best?', '[{"id": "a", "text": "Egg and sperm are each diploid, and the zygote keeps half of each set"}, {"id": "b", "text": "Egg and sperm are each haploid, and their fusion forms a diploid zygote"}, {"id": "c", "text": "The egg is diploid and the sperm is haploid, together forming a triploid zygote"}, {"id": "d", "text": "The sperm is diploid and the egg is haploid, forming a diploid morula"}]'::jsonb, '["b"]', 'The zygote is a single diploid cell formed when one haploid sperm fuses with one haploid egg, giving the full complement of 23 pairs. Neither gamete is diploid.'),
  ('fertilization', 34, 'A client has a hypothalamic disorder that prevents release of GnRH. Her ovaries are structurally normal, but follicles are not maturing. Which explanation by the nurse is best?', '[{"id": "a", "text": "Without GnRH, the posterior pituitary does not release FSH or LH"}, {"id": "b", "text": "Without GnRH, the ovaries cannot produce hCG to start the follicles"}, {"id": "c", "text": "Without GnRH, the anterior pituitary does not release FSH and LH"}, {"id": "d", "text": "Without GnRH, the corpus luteum secretes too much progesterone"}]'::jsonb, '["c"]', 'Follicle development is stimulated by GnRH from the hypothalamus, which triggers FSH and LH release from the anterior pituitary. hCG comes from the trophoblast, not the ovary.'),
  ('fertilization', 35, 'A client undergoing natural-cycle monitoring has an early follicular ultrasound showing several small follicles growing in one ovary. She asks whether she will release several eggs this cycle. Which response by the nurse is best?', '[{"id": "a", "text": "Yes; each growing follicle will rupture and release its egg at the LH surge"}, {"id": "b", "text": "Yes; each growing follicle will become a corpus luteum after the LH surge"}, {"id": "c", "text": "No; only one follicle starts to grow each cycle, so the others are cysts"}, {"id": "d", "text": "No; 10–20 follicles begin each cycle, but usually one becomes dominant"}]'::jsonb, '["d"]', 'Each cycle 10–20 primordial follicles begin maturing under FSH, but one becomes the dominant Graafian follicle and the others undergo atresia. It is not true that only one follicle starts to grow.'),
  ('fertilization', 36, 'A client''s follicular-phase labs show a normal LH level, but her FSH is very low and her estrogen level is low. Which explanation of the low estrogen by the nurse is best?', '[{"id": "a", "text": "FSH normally stimulates theca cells to make estrogen directly from cholesterol"}, {"id": "b", "text": "FSH normally stimulates the anterior pituitary to release extra estrogen"}, {"id": "c", "text": "FSH normally stimulates the corpus luteum to secrete estrogen before ovulation"}, {"id": "d", "text": "FSH normally stimulates granulosa cells to convert androgens into estrogen"}]'::jsonb, '["d"]', 'In the two-cell model, FSH stimulates granulosa cells to convert theca-cell androgens into estrogen via aromatase. Theca cells make androgens under LH, and the corpus luteum forms only after ovulation.'),
  ('fertilization', 37, 'A client''s follicular-phase labs show a normal FSH level, but her LH is very low and her estrogen remains low despite growing follicles. Which explanation by the nurse is best?', '[{"id": "a", "text": "Granulosa cells lack the androgens from theca cells that LH normally stimulates"}, {"id": "b", "text": "Granulosa cells require LH, rather than FSH, to produce estrogen through aromatase"}, {"id": "c", "text": "Theca cells require FSH to convert androgens into estrogen in the follicle"}, {"id": "d", "text": "The corpus luteum requires LH to make the estrogen needed in this phase"}]'::jsonb, '["a"]', 'LH stimulates theca cells to produce androgens, which granulosa cells convert to estrogen under FSH; both cell types are needed. Granulosa aromatase is FSH-driven, not LH-driven.'),
  ('fertilization', 38, 'A client receiving fertility teaching is asked to explain how estrogen is made in the developing follicle. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''FSH is the hormone that gets my follicles started each cycle.''"}, {"id": "b", "text": "''The theca cells are the estrogen factory, and granulosa cells just help.''"}, {"id": "c", "text": "''The dominant follicle''s estrogen peak is what triggers my LH surge.''"}, {"id": "d", "text": "''Both the theca cells and the granulosa cells are needed to produce my estrogen.''"}]'::jsonb, '["b"]', 'Granulosa cells are the estrogen factory inside the follicle, while theca cells support them by supplying androgens. The client has reversed the roles of the two cell types.'),
  ('fertilization', 39, 'A client using daily hormone monitoring to plan conception reports that her estrogen level from a single large dominant follicle peaked yesterday. Which event should the nurse explain is most likely to occur next?', '[{"id": "a", "text": "A drop in estrogen that causes the lining to shed"}, {"id": "b", "text": "Formation of the corpus luteum before ovulation"}, {"id": "c", "text": "A rise in FSH that starts primordial follicle growth"}, {"id": "d", "text": "An LH surge that causes the follicle to rupture"}]'::jsonb, '["d"]', 'In the Graafian follicle, estrogen peaks and triggers the LH surge, which causes ovulation. The corpus luteum forms from the ruptured follicle after ovulation, not before.'),
  ('fertilization', 40, 'A client''s ultrasound shows a fully mature dominant follicle and her estrogen has risen normally, but serial testing shows that no LH surge occurs this cycle. Which outcome should the nurse anticipate?', '[{"id": "a", "text": "The primordial follicles will not begin to develop"}, {"id": "b", "text": "The granulosa cells will stop producing estrogen"}, {"id": "c", "text": "The mature follicle will not rupture to release an egg"}, {"id": "d", "text": "The endometrium will not rebuild during this cycle"}]'::jsonb, '["c"]', 'The LH surge triggers ovulation (LH = Let''s Hatch), so without it the Graafian follicle does not rupture and release the egg. Follicle growth and estrogen production have already occurred under FSH.'),
  ('fertilization', 41, 'On cycle day 9, a client''s ultrasound shows follicles continuing to enlarge and her serum estrogen is rising from day to day. Which interpretation by the nurse is best?', '[{"id": "a", "text": "The corpus luteum has formed early and is secreting estrogen"}, {"id": "b", "text": "The trophoblast has begun producing hormones after implantation"}, {"id": "c", "text": "Granulosa and theca cells of growing follicles are making more estrogen"}, {"id": "d", "text": "The LH surge has already occurred and the egg has been released"}]'::jsonb, '["c"]', 'As secondary follicles continue to grow, granulosa and theca cells produce increasing estrogen. The corpus luteum forms only after ovulation, and the LH surge follows the estrogen peak.'),
  ('fertilization', 42, 'Two days after ovulation, a client''s ultrasound shows a new structure at the site where her follicle ruptured. She asks what this structure is doing. Which response by the nurse is best?', '[{"id": "a", "text": "Secreting mainly hCG, along with some progesterone"}, {"id": "b", "text": "Secreting mainly progesterone, along with some estrogen"}, {"id": "c", "text": "Secreting mainly FSH, along with some LH"}, {"id": "d", "text": "Secreting mainly estrogen, along with some androgen"}]'::jsonb, '["b"]', 'The corpus luteum forms from the ruptured follicle after ovulation and secretes progesterone plus some estrogen. hCG comes from the trophoblast, and FSH and LH come from the anterior pituitary.'),
  ('fertilization', 43, 'A client asks what happens to the estrogen-producing cells that surrounded her egg once the follicle ruptures at ovulation. Which response by the nurse is best?', '[{"id": "a", "text": "They are luteinized and become part of the corpus luteum, which makes progesterone"}, {"id": "b", "text": "They undergo atresia along with the other follicles that did not become dominant"}, {"id": "c", "text": "They travel with the egg into the tube and later become the trophoblast layer"}, {"id": "d", "text": "They form the zona pellucida that locks after the first sperm enters the egg"}]'::jsonb, '["a"]', 'After ovulation, granulosa cells are luteinized and become part of the corpus luteum that produces progesterone. Atresia is the fate of the non-dominant follicles, and the trophoblast comes from the blastocyst.'),
  ('fertilization', 44, 'An endometrial sample taken from a client about one week after ovulation shows a thick, secretory lining. The client asks which hormone is mainly responsible for this phase. Which response by the nurse is best?', '[{"id": "a", "text": "Estrogen from the growing follicles"}, {"id": "b", "text": "FSH from the anterior pituitary"}, {"id": "c", "text": "Progesterone from the corpus luteum"}, {"id": "d", "text": "LH from the anterior pituitary"}]'::jsonb, '["c"]', 'Progesterone, secreted by the corpus luteum after ovulation, drives the secretory phase. Estrogen drives the earlier proliferative phase when the endometrium rebuilds.'),
  ('fertilization', 45, 'A client is 3 days past the end of her menstrual period, before ovulation. Ultrasound shows her endometrial lining is rebuilding and thickening. Which hormone should the nurse identify as mainly driving this change?', '[{"id": "a", "text": "Estrogen"}, {"id": "b", "text": "Progesterone"}, {"id": "c", "text": "hCG"}, {"id": "d", "text": "LH"}]'::jsonb, '["a"]', 'Estrogen rebuilds the endometrium during the proliferative phase before ovulation. Progesterone drives the secretory phase after ovulation, and hCG is not present without a pregnancy.'),
  ('fertilization', 46, 'A client trying to conceive has a luteal-phase ultrasound showing a very thin uterine lining. She asks why this could make it harder for a pregnancy to begin. Which response by the nurse is best?', '[{"id": "a", "text": "The lining is where the sperm and egg normally meet for fertilization"}, {"id": "b", "text": "The lining releases the egg into the tube for the fimbriae to collect"}, {"id": "c", "text": "The lining produces the hCG that is needed to rescue the corpus luteum"}, {"id": "d", "text": "The lining must thicken so the blastocyst can embed and be supported"}]'::jsonb, '["d"]', 'The endometrium thickens for pregnancy, and the blastocyst embeds into this lining, which progesterone keeps thick and blood-rich. Fertilization occurs in the ampulla, and hCG comes from the trophoblast.'),
  ('fertilization', 47, 'A client had surgery that removed the finger-like open end of her right fallopian tube, while her right ovary was left intact. She asks how this could affect eggs released from the right ovary. Which response by the nurse is best?', '[{"id": "a", "text": "The egg cannot be released because the follicle will not rupture"}, {"id": "b", "text": "The egg will not be swept into the tube, since it is not directly attached"}, {"id": "c", "text": "The egg will be fertilized normally but will not be able to implant"}, {"id": "d", "text": "The egg will not be protected because the zona pellucida cannot form"}]'::jsonb, '["b"]', 'The egg is not directly connected to the tube; the fimbriae must sweep it from the ovarian surface into the tube. Follicle rupture depends on the LH surge, not on the fimbriae.'),
  ('fertilization', 48, 'A client has an intact uterus and fallopian tubes, but both of her ovaries have stopped functioning. She asks which reproductive functions she has lost. Which response by the nurse is best?', '[{"id": "a", "text": "Providing the site where a fertilized egg implants and grows"}, {"id": "b", "text": "Sweeping the released egg from the ovary into the fallopian tube"}, {"id": "c", "text": "Releasing eggs and producing estrogen and progesterone"}, {"id": "d", "text": "Providing the site where sperm and egg normally meet"}]'::jsonb, '["c"]', 'The ovaries store and release eggs and produce estrogen and progesterone. Implantation occurs in the uterus, the fimbriae sweep the egg, and fertilization occurs in the tube.'),
  ('fertilization', 49, 'A nurse has taught a client who wants to conceive how her timing of intercourse relates to ovulation. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''Sperm from intercourse a few days before I ovulate can still fertilize the egg.''"}, {"id": "b", "text": "''My fertile window includes the several days leading up to ovulation.''"}, {"id": "c", "text": "''The egg is viable for only about 12 to 24 hours once it is released.''"}, {"id": "d", "text": "''We can wait until 3 days after I ovulate, since the egg lasts that long.''"}]'::jsonb, '["d"]', 'The egg remains viable only about 12–24 hours after ovulation, so waiting 3 days afterward misses the window. The fertile window extends several days before ovulation but only 1 day after.'),
  ('fertilization', 50, 'A client who conceived about 7 days ago plans to take a home pregnancy test tomorrow. Which statement by the client indicates the best understanding of test timing?', '[{"id": "a", "text": "''A negative result tomorrow would prove I am not pregnant this cycle.''"}, {"id": "b", "text": "''I should wait 8–12 weeks, until the placenta starts making the hormone.''"}, {"id": "c", "text": "''The test will turn positive as soon as the egg is fertilized in the tube.''"}, {"id": "d", "text": "''I should wait until around my missed period, about 1–2 weeks after conception.''"}]'::jsonb, '["d"]', 'hCG is detected by pregnancy test about 1–2 weeks after fertilization, around the missed period, and earlier testing may give a false negative. hCG starts at implantation, not at fertilization or the luteal-placental shift.'),
  ('organ', 1, 'A nurse in a gynecology clinic receives four client calls. Which client should the nurse speak with first?', '[{"id": "a", "text": "A client with endometriosis who reports pelvic pain that began the day before her period"}, {"id": "b", "text": "A client with a known ovarian cyst who reports sudden severe pelvic pain and repeated vomiting"}, {"id": "c", "text": "A client with fibroids who is anxious after reading online that her uterine growths may be cancerous"}, {"id": "d", "text": "A client taking a GnRH agonist for endometriosis who reports several hot flashes each day"}]'::jsonb, '["b"]', 'Severe pain with nausea and vomiting in a client with an ovarian cyst suggests torsion, which is an emergency. Cyclic premenstrual pain with endometriosis and hot flashes on a GnRH agonist are expected, and fibroid teaching is not urgent.'),
  ('organ', 2, 'A client with a known simple ovarian cyst calls to report pelvic pain that came on suddenly and is sharp, along with light vaginal spotting. She denies nausea or vomiting. Which complication should the nurse suspect?', '[{"id": "a", "text": "Ovarian torsion"}, {"id": "b", "text": "Pelvic inflammatory disease"}, {"id": "c", "text": "Cyst rupture"}, {"id": "d", "text": "Endometriosis flare"}]'::jsonb, '["c"]', 'Sudden sharp pain with light bleeding is the presentation of cyst rupture. Torsion presents with severe pain plus nausea and vomiting, which this client denies.'),
  ('organ', 3, 'Two clients with ovarian cysts call within minutes of each other. Client 1 has sudden sharp pelvic pain and light spotting. Client 2 has severe pelvic pain with nausea and vomiting. Which statement best describes the nurse''s priority?', '[{"id": "a", "text": "Client 1 first, because bleeding indicates the cyst has twisted"}, {"id": "b", "text": "Client 1 first, because her sudden sharp pain is the signal of ovarian torsion"}, {"id": "c", "text": "Client 2 first, because vomiting suggests an ascending infection"}, {"id": "d", "text": "Client 2 first, because her findings suggest torsion, an emergency"}]'::jsonb, '["d"]', 'Severe pain with nausea and vomiting suggests torsion, which is labeled an emergency. Sudden sharp pain with light bleeding matches rupture, and vomiting here does not indicate infection.'),
  ('organ', 4, 'A client with a large ovarian cyst is being observed at home. She calls the nurse to describe her symptoms. Which finding requires immediate follow-up?', '[{"id": "a", "text": "Abdominal bloating that has persisted for several weeks"}, {"id": "b", "text": "A constant feeling of pelvic pressure when she stands"}, {"id": "c", "text": "Severe pelvic pain that began suddenly, with vomiting"}, {"id": "d", "text": "A dull pelvic ache that is relieved by taking NSAIDs"}]'::jsonb, '["c"]', 'Severe pain with nausea and vomiting suggests torsion, an emergency. Bloating, pressure, and pelvic pain are expected with a large cyst and can be managed with NSAIDs.'),
  ('organ', 5, 'A client with an ovarian cyst arrives with severe pelvic pain that began an hour ago, along with nausea and two episodes of vomiting. Which action should the nurse anticipate as the priority?', '[{"id": "a", "text": "Observation with a repeat ultrasound in several weeks"}, {"id": "b", "text": "Preparation for emergency surgery on the affected ovary"}, {"id": "c", "text": "Oral contraceptives to suppress further cyst formation"}, {"id": "d", "text": "NSAIDs for pain followed by discharge home with teaching"}]'::jsonb, '["b"]', 'Severe pain with nausea and vomiting suggests torsion, which requires emergency surgery. Observation is reserved for small, simple cysts, and OCPs and NSAIDs do not address torsion.'),
  ('organ', 6, 'A client with a known ovarian cyst reports sudden, sharp pelvic pain and light vaginal bleeding. The nurse is determining whether her presentation is consistent with rupture or torsion. Which additional finding would most indicate torsion?', '[{"id": "a", "text": "Light spotting that continues for several hours"}, {"id": "b", "text": "Bloating and pelvic pressure for several weeks"}, {"id": "c", "text": "Severe pain that is accompanied by vomiting"}, {"id": "d", "text": "A small, simple cyst seen on a prior ultrasound"}]'::jsonb, '["c"]', 'Torsion presents with severe pain and nausea or vomiting, while rupture presents with sudden sharp pain and light bleeding. Bloating and pressure reflect a large cyst rather than torsion.'),
  ('organ', 7, 'A 27-year-old client reports several weeks of pelvic pressure and bloating, and the provider suspects an ovarian cyst. Which diagnostic plan should the nurse anticipate?', '[{"id": "a", "text": "Laparoscopy to make the definitive diagnosis of the cyst"}, {"id": "b", "text": "Ultrasound, along with an hCG test to rule out pregnancy"}, {"id": "c", "text": "MRI for planning surgery before any other imaging is done"}, {"id": "d", "text": "Cervical cultures for chlamydia and gonorrhea before imaging"}]'::jsonb, '["b"]', 'Ovarian cysts are diagnosed with ultrasound, with hCG to rule out pregnancy. Laparoscopy is the definitive test for endometriosis, and MRI is used for fibroid surgical planning.'),
  ('organ', 8, 'A client of childbearing age with a suspected ovarian cyst is being worked up for pelvic pain. Ultrasound has been ordered. Which additional laboratory result is most important for the nurse to ensure is obtained?', '[{"id": "a", "text": "A serum hCG level"}, {"id": "b", "text": "A cervical culture"}, {"id": "c", "text": "A bone density scan"}, {"id": "d", "text": "An estrogen level"}]'::jsonb, '["a"]', 'The workup for an ovarian cyst includes ultrasound plus hCG to rule out pregnancy. Cervical cultures relate to STI-related PID, and bone density relates to GnRH agonist therapy.'),
  ('organ', 9, 'A client with no symptoms has a small, simple ovarian cyst found incidentally on ultrasound. Her hCG is negative. Which plan of care should the nurse anticipate?', '[{"id": "a", "text": "Emergency surgery to remove the ovary"}, {"id": "b", "text": "Scheduled cystectomy within the week"}, {"id": "c", "text": "Observation of the cyst over time"}, {"id": "d", "text": "A GnRH agonist to shrink the cyst"}]'::jsonb, '["c"]', 'Small, simple cysts are managed with observation. Emergency surgery is for torsion or rupture, and GnRH agonists are used to shrink fibroids before surgery.'),
  ('organ', 10, 'A client whose small, simple ovarian cyst is being observed asks the nurse questions about her condition. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''Many cysts like mine cause no symptoms at all.''"}, {"id": "b", "text": "''My cyst most likely formed when ovulation was incomplete.''"}, {"id": "c", "text": "''A small, simple cyst like this is often just watched.''"}, {"id": "d", "text": "''My cyst needs surgery right away so it won''t twist.''"}]'::jsonb, '["d"]', 'Small, simple cysts are treated with observation; emergency surgery is reserved for torsion or rupture. Cysts are often asymptomatic and usually result from failed or incomplete ovulation.'),
  ('organ', 11, 'A client is told that her ultrasound shows a corpus luteum cyst. She is worried because she has never heard of this and asks whether it is unusual and how it formed. Which response by the nurse is best?', '[{"id": "a", "text": "It is a rare cyst that forms when endometrial tissue grows on the surface of the ovary"}, {"id": "b", "text": "It is a common functional cyst that forms from failed or incomplete ovulation"}, {"id": "c", "text": "It is a rare cyst that forms when an untreated STI ascends to the ovary"}, {"id": "d", "text": "It is a common functional cyst that forms when the ovary twists on itself"}]'::jsonb, '["b"]', 'Functional cysts, follicular or corpus luteum, are the most common type and usually result from failed or incomplete ovulation. Endometrial tissue outside the uterus is endometriosis, and torsion is a complication, not a cause.'),
  ('organ', 12, 'A client with recurrent painful functional ovarian cysts has no signs of torsion or rupture, and her hCG is negative. Which group of treatments should the nurse expect the provider to consider?', '[{"id": "a", "text": "Ceftriaxone and doxycycline, plus pelvic rest"}, {"id": "b", "text": "NSAIDs for pain and oral contraceptives"}, {"id": "c", "text": "A GnRH agonist and uterine artery embolization"}, {"id": "d", "text": "Emergency surgery and a pregnancy test"}]'::jsonb, '["b"]', 'Treatment of ovarian cysts includes observation, NSAIDs, OCPs, and cystectomy, with emergency surgery reserved for torsion or rupture. Ceftriaxone and doxycycline treat PID, and UAE is a fibroid treatment.'),
  ('organ', 13, 'A 22-year-old client reports fever, chills, and lower abdominal pain for two days. On exam she has purulent cervical discharge and cries out when the provider moves her cervix. She was told months ago she had an STI but never filled the prescription. Which condition should the nurse suspect?', '[{"id": "a", "text": "Endometriosis"}, {"id": "b", "text": "Ruptured ovarian cyst with bleeding"}, {"id": "c", "text": "Submucosal fibroid"}, {"id": "d", "text": "Pelvic inflammatory disease"}]'::jsonb, '["d"]', 'Fever, chills, lower abdominal pain, purulent cervical discharge, and cervical motion tenderness after an untreated STI indicate PID. Rupture causes sudden sharp pain with light bleeding, without fever or purulent discharge.'),
  ('organ', 14, 'A client presents with lower abdominal pain and a low-grade fever. The provider is considering several causes of her pelvic pain. Which exam finding, if present, would most strongly support pelvic inflammatory disease?', '[{"id": "a", "text": "Pain that worsens just before and during each period"}, {"id": "b", "text": "Tenderness when the cervix is moved during the exam"}, {"id": "c", "text": "Bloating and pressure from an enlarged ovary"}, {"id": "d", "text": "Heavy menstrual bleeding with fatigue"}]'::jsonb, '["b"]', 'Cervical motion tenderness is the key clinical sign of PID. Cyclic pain before and during periods suggests endometriosis, and bloating and pressure suggest a large ovarian cyst.'),
  ('organ', 15, 'A client with fever and lower abdominal pain is being evaluated in the emergency department. The nurse is reviewing the provider''s pelvic exam documentation. Which documented finding should the nurse recognize as the key clinical sign of the suspected infection?', '[{"id": "a", "text": "Cervical motion tenderness"}, {"id": "b", "text": "Light vaginal bleeding"}, {"id": "c", "text": "Painful intercourse"}, {"id": "d", "text": "Nausea and vomiting"}]'::jsonb, '["a"]', 'Cervical motion tenderness is the key clinical sign of PID. Dyspareunia and nausea and vomiting can occur in severe PID, but they are not the key sign, and light bleeding fits cyst rupture.'),
  ('organ', 16, 'A client who reports painful intercourse is being evaluated. Both endometriosis and pelvic inflammatory disease are being considered. Which additional finding would most support pelvic inflammatory disease rather than endometriosis?', '[{"id": "a", "text": "Difficulty becoming pregnant over the past year"}, {"id": "b", "text": "Pelvic pain that recurs before and during periods"}, {"id": "c", "text": "Fever with purulent discharge from the cervix"}, {"id": "d", "text": "Bowel and bladder symptoms during each period"}]'::jsonb, '["c"]', 'Fever and purulent cervical discharge are features of PID. Cyclic pain and bowel or bladder symptoms point to endometriosis, and infertility is associated with both conditions, so it does not distinguish them.'),
  ('organ', 17, 'A client reports painful intercourse, and the provider is weighing endometriosis against pelvic inflammatory disease. Which additional finding would most support endometriosis rather than pelvic inflammatory disease?', '[{"id": "a", "text": "Fever and chills that have continued over the past several days"}, {"id": "b", "text": "Purulent discharge seen at the cervical opening"}, {"id": "c", "text": "Tenderness when the cervix is moved on exam"}, {"id": "d", "text": "Pelvic pain that recurs before and during periods"}]'::jsonb, '["d"]', 'Cyclic pelvic pain before and during periods is characteristic of endometriosis. Fever, chills, purulent discharge, and cervical motion tenderness are findings of PID.'),
  ('organ', 18, 'A 20-year-old client was diagnosed with chlamydia but has not started treatment, saying she feels fine. Which explanation by the nurse best conveys why prompt treatment is important?', '[{"id": "a", "text": "Untreated chlamydia can cause endometrial tissue to grow outside the uterus"}, {"id": "b", "text": "Untreated chlamydia can ascend to infect the uterus, tubes, and ovaries"}, {"id": "c", "text": "Untreated chlamydia can cause fluid-filled cysts to form on the ovaries"}, {"id": "d", "text": "Untreated chlamydia can cause noncancerous growths in the uterine wall"}]'::jsonb, '["b"]', 'PID is an ascending infection from untreated STIs such as chlamydia that spreads to the uterus, tubes, and ovaries. Endometrial tissue outside the uterus describes endometriosis, and ovarian cysts usually result from failed ovulation.'),
  ('organ', 19, 'A nurse is explaining to a client with newly diagnosed pelvic inflammatory disease how her untreated gonorrhea led to this illness. Which description of the path of infection is accurate?', '[{"id": "a", "text": "Ovaries → fallopian tubes → uterus, descending from the pelvis"}, {"id": "b", "text": "Uterus → ovaries → fallopian tubes, spreading through the blood"}, {"id": "c", "text": "Fallopian tubes → uterus → ovaries, beginning in the tubes"}, {"id": "d", "text": "Untreated STI → uterus → fallopian tubes → ovaries, ascending"}]'::jsonb, '["d"]', 'PID is an ascending infection from untreated STIs that travels to the uterus, tubes, and ovaries. The other sequences describe descending or out-of-order spread.'),
  ('organ', 20, 'A nurse is assessing three clients being treated for pelvic inflammatory disease. Which client''s findings indicate the most severe disease and need priority attention?', '[{"id": "a", "text": "A client with purulent cervical discharge and mild lower abdominal pain"}, {"id": "b", "text": "A client with cervical motion tenderness noted on the pelvic exam"}, {"id": "c", "text": "A client with lower abdominal pain, fever, and nausea and vomiting"}, {"id": "d", "text": "A client with chills and lower abdominal pain that began yesterday"}]'::jsonb, '["c"]', 'Nausea and vomiting occur with PID in severe cases. Purulent discharge, cervical motion tenderness, chills, and lower abdominal pain are typical presenting findings rather than markers of severity.'),
  ('organ', 21, 'A client who was treated for pelvic inflammatory disease two years ago now has a positive pregnancy test. When planning her early prenatal care, which complication should the nurse be most alert for?', '[{"id": "a", "text": "Ectopic pregnancy"}, {"id": "b", "text": "Ovarian torsion"}, {"id": "c", "text": "Uterine fibroids"}, {"id": "d", "text": "Endometriosis"}]'::jsonb, '["a"]', 'Complications of PID include infertility, ectopic pregnancy, and tubo-ovarian abscess, so a pregnancy after PID warrants close attention for ectopic implantation. Torsion is a complication of ovarian cysts.'),
  ('organ', 22, 'A 24-year-old client is recovering from pelvic inflammatory disease and says she hopes to have children in a few years. Which long-term complication of her condition is most important for the nurse to discuss?', '[{"id": "a", "text": "Decreased bone density"}, {"id": "b", "text": "Infertility"}, {"id": "c", "text": "Anemia"}, {"id": "d", "text": "Ovarian torsion"}]'::jsonb, '["b"]', 'Infertility is a listed complication of PID and is directly relevant to her plans for children. Decreased bone density is an effect of GnRH agonists, and anemia is monitored with fibroids.'),
  ('organ', 23, 'A client with pelvic inflammatory disease is being discharged with an outpatient regimen. Which medication regimen should the nurse expect on her discharge orders?', '[{"id": "a", "text": "NSAIDs combined with an oral contraceptive"}, {"id": "b", "text": "A GnRH agonist with calcium supplements"}, {"id": "c", "text": "Ceftriaxone plus doxycycline ± metronidazole"}, {"id": "d", "text": "Metronidazole alone, given to both partners"}]'::jsonb, '["c"]', 'PID is treated with ceftriaxone plus doxycycline, with or without metronidazole, along with partner treatment and pelvic rest. NSAIDs and OCPs are used for cysts, fibroids, and endometriosis.'),
  ('organ', 24, 'A nurse reviews discharge teaching with a client being treated for pelvic inflammatory disease. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''I will take the doxycycline along with the ceftriaxone I received.''"}, {"id": "b", "text": "''I should avoid intercourse while I am being treated for this infection.''"}, {"id": "c", "text": "''My partner does not need treatment because I am the one with symptoms.''"}, {"id": "d", "text": "''This infection can affect my ability to get pregnant in the future.''"}]'::jsonb, '["c"]', 'Treatment of PID includes treating partners, so the partner must be treated even without symptoms. Pelvic rest, ceftriaxone with doxycycline, and awareness of infertility risk are all correct.'),
  ('organ', 25, 'A client is completing treatment for pelvic inflammatory disease caused by gonorrhea. Before discharge, which instruction is most important to prevent her from being reinfected?', '[{"id": "a", "text": "Take NSAIDs regularly for pelvic pain"}, {"id": "b", "text": "Make sure her partner is also treated"}, {"id": "c", "text": "Begin oral contraceptives this month"}, {"id": "d", "text": "Schedule a laparoscopy in six months"}]'::jsonb, '["b"]', 'PID results from ascending STIs, and its treatment includes treating partners, which prevents reinfection. NSAIDs relieve pain but do not prevent reinfection, and laparoscopy is the definitive test for endometriosis.'),
  ('organ', 26, 'A 29-year-old client reports pelvic pain that begins a few days before each period and continues through menses, painful intercourse, and 18 months of trying to conceive without success. She has no fever and no abnormal discharge. Which condition should the nurse suspect?', '[{"id": "a", "text": "Endometriosis"}, {"id": "b", "text": "Pelvic inflammatory disease"}, {"id": "c", "text": "Functional ovarian cyst"}, {"id": "d", "text": "Ovarian torsion"}]'::jsonb, '["a"]', 'Cyclic pelvic pain before and during periods, dyspareunia, and infertility are features of endometriosis. PID also causes dyspareunia and infertility, but it presents with fever and purulent discharge, which are absent.'),
  ('organ', 27, 'A client with cyclic pelvic pain, painful intercourse, and infertility had a normal pelvic ultrasound. She asks why the provider now recommends a surgical procedure to find out what is wrong. Which response by the nurse is best?', '[{"id": "a", "text": "Laparoscopy is the definitive way to diagnose the suspected condition"}, {"id": "b", "text": "Laparoscopy is needed to rule out pregnancy before any of the treatment is started"}, {"id": "c", "text": "Laparoscopy is the only way to obtain cervical cultures for infection"}, {"id": "d", "text": "Laparoscopy is used to plan surgery after an MRI shows the fibroids"}]'::jsonb, '["a"]', 'Her findings suggest endometriosis, which is definitively diagnosed by laparoscopy. hCG rules out pregnancy, and MRI is used for surgical planning of fibroids.'),
  ('organ', 28, 'Two clients are scheduled for diagnostic workups. Client 1 has suspected uterine fibroids with heavy periods. Client 2 has suspected endometriosis with cyclic pelvic pain. Which pairing of diagnostic tests should the nurse anticipate?', '[{"id": "a", "text": "Client 1: laparoscopy; Client 2: transvaginal ultrasound"}, {"id": "b", "text": "Client 1: hCG and MRI; Client 2: cervical cultures"}, {"id": "c", "text": "Client 1: transvaginal ultrasound; Client 2: laparoscopy"}, {"id": "d", "text": "Client 1: laparoscopy; Client 2: MRI for surgical planning"}]'::jsonb, '["c"]', 'Fibroids are diagnosed with transvaginal ultrasound, with MRI reserved for surgical planning, while endometriosis is definitively diagnosed by laparoscopy. Option pairings that reverse these tests are incorrect.'),
  ('organ', 29, 'A client with endometriosis reports that each month, just before and during her period, she has painful bowel movements and urinary discomfort; her urinalysis is negative. Which explanation by the nurse is best?', '[{"id": "a", "text": "Endometrial tissue can grow on the bowel and bladder, causing cyclic symptoms"}, {"id": "b", "text": "An ascending infection from the cervix is now spreading to the bowel and the bladder"}, {"id": "c", "text": "A large ovarian cyst is pressing on the bowel and bladder during each cycle"}, {"id": "d", "text": "Submucosal fibroids are bleeding into the bowel and bladder during each cycle"}]'::jsonb, '["a"]', 'In endometriosis, endometrial tissue grows outside the uterus, including on the bowel and bladder, causing bowel and bladder symptoms that follow the cycle. An ascending infection describes PID.'),
  ('organ', 30, 'A client newly diagnosed with endometriosis asks why her provider is recommending hormone-suppressing treatments such as oral contraceptives or a GnRH agonist. Which explanation by the nurse best links her condition to these treatments?', '[{"id": "a", "text": "The tissue grows in response to an infection that the hormones then help to clear"}, {"id": "b", "text": "The tissue forms from incomplete ovulation that hormones then correct"}, {"id": "c", "text": "The tissue is a cancerous growth that hormones can help to shrink"}, {"id": "d", "text": "The tissue is estrogen-dependent, so lowering hormone stimulation helps"}]'::jsonb, '["d"]', 'Endometriosis is estrogen-dependent, which is why OCPs and GnRH agonists are used in treatment. Incomplete ovulation causes functional cysts, and infection describes PID.'),
  ('organ', 31, 'A client started a GnRH agonist for endometriosis three weeks ago. She calls to report several episodes of sudden warmth and flushing each day and asks whether she should be worried. Which response by the nurse is best?', '[{"id": "a", "text": "Hot flashes suggest that the endometrial implants are spreading"}, {"id": "b", "text": "Hot flashes suggest the dose is too low to control the disease"}, {"id": "c", "text": "Hot flashes are an expected effect of this type of medication"}, {"id": "d", "text": "Hot flashes suggest an ovarian cyst has formed and is enlarging"}]'::jsonb, '["c"]', 'Hot flashes are an expected effect of GnRH agonists. They do not indicate disease spread, underdosing, or a new cyst.'),
  ('organ', 32, 'A client with severe endometriosis will be receiving a GnRH agonist for an extended period. When planning long-term monitoring, which adverse effect is most important for the nurse to include?', '[{"id": "a", "text": "Decreased bone density"}, {"id": "b", "text": "Heavy menstrual bleeding"}, {"id": "c", "text": "Cervical motion tenderness"}, {"id": "d", "text": "Ovarian cyst rupture"}]'::jsonb, '["a"]', 'GnRH agonists cause hot flashes and decreased bone density, so bone density warrants long-term monitoring. Cervical motion tenderness is a sign of PID.'),
  ('organ', 33, 'A nurse is teaching a client who is starting a GnRH agonist for endometriosis. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''My bones can lose density while I am on this medication.''"}, {"id": "b", "text": "''I might have some hot flashes while I am taking this new medication.''"}, {"id": "c", "text": "''This medication treats a condition that depends on estrogen.''"}, {"id": "d", "text": "''This medication has no effect at all on how strong my bones are.''"}]'::jsonb, '["d"]', 'GnRH agonists decrease bone density, so the belief that bone strength is unaffected requires correction. Hot flashes and the estrogen-dependent nature of endometriosis are correctly stated.'),
  ('organ', 34, 'Several clients with endometriosis are discussing treatment options with the nurse. For which client would hysterectomy most likely be considered an appropriate option?', '[{"id": "a", "text": "A 42-year-old with severe disease who has completed childbearing"}, {"id": "b", "text": "A 25-year-old with mild cyclic pain who hopes to conceive within the year"}, {"id": "c", "text": "A 30-year-old whose pain is controlled with NSAIDs and OCPs"}, {"id": "d", "text": "A 27-year-old newly diagnosed who has not yet tried medications"}]'::jsonb, '["a"]', 'Hysterectomy is reserved for endometriosis that is severe or when the client is done with childbearing. Clients with mild or medication-controlled disease, or who wish to conceive, are managed with NSAIDs, OCPs, GnRH agonists, or laparoscopic surgery.'),
  ('organ', 35, 'A client with newly diagnosed endometriosis and moderate cyclic pain asks which treatments are typically used for her condition. Which set of treatments should the nurse describe?', '[{"id": "a", "text": "NSAIDs, oral contraceptives, and GnRH agonists"}, {"id": "b", "text": "Ceftriaxone, doxycycline, and pelvic rest"}, {"id": "c", "text": "Observation, NSAIDs, and a cystectomy"}, {"id": "d", "text": "UAE, myomectomy, and an hCG test"}]'::jsonb, '["a"]', 'Endometriosis is treated with NSAIDs, OCPs, GnRH agonists, laparoscopic surgery, and hysterectomy if severe. Ceftriaxone and doxycycline treat PID, and observation with cystectomy applies to ovarian cysts.'),
  ('organ', 36, 'A nurse has taught a client about her new diagnosis of endometriosis. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''Tissue like my uterine lining is growing outside my uterus.''"}, {"id": "b", "text": "''My pain is caused by an infection spreading up from my cervix.''"}, {"id": "c", "text": "''My painful intercourse can be one of the symptoms of this condition.''"}, {"id": "d", "text": "''This condition may make it harder for me to become pregnant.''"}]'::jsonb, '["b"]', 'Endometriosis is endometrial tissue growing outside the uterus; an infection ascending from the cervix describes PID. Dyspareunia and infertility are features of endometriosis.'),
  ('organ', 37, 'A 31-year-old client with endometriosis tells the nurse she and her partner plan to start trying for a baby next year. Which complication of her condition is most important for the nurse to address in her teaching?', '[{"id": "a", "text": "Ovarian torsion"}, {"id": "b", "text": "Tubo-ovarian abscess"}, {"id": "c", "text": "Severe anemia"}, {"id": "d", "text": "Infertility"}]'::jsonb, '["d"]', 'Infertility is a feature of endometriosis and is directly relevant to her plans. Tubo-ovarian abscess is a complication of PID, and torsion is a complication of ovarian cysts.'),
  ('organ', 38, 'A 38-year-old client with uterine fibroids reports menstrual bleeding so heavy that she changes pads hourly on her heaviest days. Imaging shows a single fibroid. Which explanation of the fibroid''s likely location is most accurate?', '[{"id": "a", "text": "An intramural fibroid, since this type causes the most bleeding"}, {"id": "b", "text": "A subserosal fibroid, since this type causes the most bleeding"}, {"id": "c", "text": "Any location, since fibroid type does not change the bleeding"}, {"id": "d", "text": "A submucosal fibroid, since this type causes the most bleeding"}]'::jsonb, '["d"]', 'Of the three fibroid types, submucosal fibroids cause the most bleeding. Intramural and subserosal fibroids are the other types and are not described as causing the most bleeding.'),
  ('organ', 39, 'A nurse is planning follow-up for two clients with uterine fibroids of similar size. Client 1 has a submucosal fibroid; client 2 has a subserosal fibroid. Which plan reflects the correct priority for monitoring?', '[{"id": "a", "text": "Closer monitoring of client 1 for anemia, because her type causes the most bleeding"}, {"id": "b", "text": "Closer monitoring of client 2 for anemia, because her type causes the most bleeding"}, {"id": "c", "text": "Closer monitoring of client 1 for torsion, because her type is attached to the ovary"}, {"id": "d", "text": "Equal monitoring of both for anemia, because fibroid type does not affect bleeding"}]'::jsonb, '["a"]', 'Submucosal fibroids cause the most bleeding, and monitoring for anemia is a nursing priority with fibroids. Torsion is a complication of ovarian cysts, not fibroids.'),
  ('organ', 40, 'A client with uterine fibroids reports that her periods have become much heavier over the past six months and that she feels increasingly tired. Which nursing assessment is the priority?', '[{"id": "a", "text": "Ask whether her pain begins before her periods"}, {"id": "b", "text": "Check whether moving the cervix causes pain"}, {"id": "c", "text": "Ask about bowel and bladder symptoms with menses"}, {"id": "d", "text": "Assess for anemia related to her blood loss"}]'::jsonb, '["d"]', 'Monitoring for anemia is a nursing priority for clients with fibroids, especially with heavy bleeding. Cyclic pain and bowel or bladder symptoms relate to endometriosis, and cervical motion tenderness relates to PID.'),
  ('organ', 41, 'A client is told that transvaginal ultrasound shows several uterine fibroids. She becomes tearful and says, ''So I have cancer, and it is going to spread.'' Which response by the nurse is best?', '[{"id": "a", "text": "''These growths depend on estrogen, so they are treated like a cancer.''"}, {"id": "b", "text": "''These growths can become cancer, so removing them right away is best.''"}, {"id": "c", "text": "''These growths are not cancerous, though we will watch for heavy bleeding.''"}, {"id": "d", "text": "''These growths are often cancerous, so the MRI will be used to check for spread.''"}]'::jsonb, '["c"]', 'Clients with fibroids should be educated on the non-cancerous nature of the growths and monitored for anemia from bleeding. MRI is used for surgical planning, not to look for spread.'),
  ('organ', 42, 'A client with large uterine fibroids is scheduled for a myomectomy in three months and has been prescribed a GnRH agonist in the meantime. She asks why she needs medication if she is having surgery. Which response by the nurse is best?', '[{"id": "a", "text": "The medication confirms the diagnosis before the surgery"}, {"id": "b", "text": "The medication shrinks the fibroids before the surgery"}, {"id": "c", "text": "The medication treats an infection before the surgery"}, {"id": "d", "text": "The medication prevents a twisted ovary before surgery"}]'::jsonb, '["b"]', 'GnRH agonists are used to shrink fibroids before surgery. Fibroids are diagnosed by transvaginal ultrasound, and infection and torsion are not the purpose of this therapy.'),
  ('organ', 43, 'A client whose uterine fibroids were diagnosed by transvaginal ultrasound is now scheduled for an MRI. She asks why another test is needed when she already knows the diagnosis. Which response by the nurse is best?', '[{"id": "a", "text": "The MRI is the definitive test needed to confirm that fibroids are present"}, {"id": "b", "text": "The MRI is needed to rule out pregnancy before any treatment is started"}, {"id": "c", "text": "The MRI checks whether the fibroids have spread to the bowel and bladder"}, {"id": "d", "text": "The MRI gives the surgeon detailed information to plan the procedure"}]'::jsonb, '["d"]', 'Fibroids are diagnosed by transvaginal ultrasound, and MRI is used for surgical planning. Laparoscopy, not MRI, is the definitive test for endometriosis, and hCG rules out pregnancy.'),
  ('organ', 44, 'A 40-year-old client with heavy menstrual bleeding and suspected uterine fibroids is seen in the gynecology clinic. Which diagnostic test should the nurse anticipate being ordered first to diagnose the fibroids?', '[{"id": "a", "text": "Laparoscopy"}, {"id": "b", "text": "MRI of the pelvis"}, {"id": "c", "text": "Transvaginal ultrasound"}, {"id": "d", "text": "Cervical cultures"}]'::jsonb, '["c"]', 'Fibroids are diagnosed with transvaginal ultrasound, while MRI is reserved for surgical planning. Laparoscopy is the definitive test for endometriosis.'),
  ('organ', 45, 'A nurse has completed teaching with a client who has submucosal uterine fibroids. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "''My fibroids are a cancer that will spread unless they are removed.''"}, {"id": "b", "text": "''My GnRH medication may shrink the fibroids before my surgery.''"}, {"id": "c", "text": "''My heavy bleeding from this type of fibroid can lead to anemia.''"}, {"id": "d", "text": "''My type of fibroid is the type that tends to cause the most bleeding.''"}]'::jsonb, '["a"]', 'Fibroids are non-cancerous, so the belief that they will spread requires correction. Shrinking with GnRH before surgery, anemia risk, and submucosal bleeding are all correct.'),
  ('organ', 46, 'A client with symptomatic uterine fibroids asks which treatments might be offered. Which set of options should the nurse describe?', '[{"id": "a", "text": "Ceftriaxone, doxycycline, and pelvic rest"}, {"id": "b", "text": "Observation, NSAIDs, and a cystectomy"}, {"id": "c", "text": "Laparoscopy to diagnose, then hCG testing"}, {"id": "d", "text": "OCPs, GnRH agonists, UAE, and myomectomy"}]'::jsonb, '["d"]', 'Fibroid treatment includes OCPs, GnRH agonists, UAE, myomectomy, and hysterectomy. Ceftriaxone and doxycycline treat PID, and observation with cystectomy applies to ovarian cysts.'),
  ('organ', 47, 'A nurse in a women''s health clinic is reviewing four clients'' reports. Which client requires prompt referral for possible emergency surgery?', '[{"id": "a", "text": "A client with fibroids whose periods have been heavier for months"}, {"id": "b", "text": "A client with endometriosis who has pain each month before menses"}, {"id": "c", "text": "A client with an ovarian cyst who has sudden sharp pain and spotting"}, {"id": "d", "text": "A client with a small, simple ovarian cyst who has no symptoms at all"}]'::jsonb, '["c"]', 'Sudden sharp pain with light bleeding suggests cyst rupture, which may require emergency surgery. Heavy periods with fibroids call for anemia monitoring, and a small, simple asymptomatic cyst is observed.'),
  ('organ', 48, 'A 35-year-old client has newly diagnosed uterine fibroids with heavy periods and is frightened about the diagnosis. Which plan of care best reflects the nursing priorities for this client?', '[{"id": "a", "text": "Arrange a laparoscopy and ensure her partner is treated"}, {"id": "b", "text": "Monitor for anemia and teach that the growths are not cancer"}, {"id": "c", "text": "Prepare for emergency surgery and obtain an hCG level"}, {"id": "d", "text": "Monitor her bone density and teach about the hot flashes she should expect"}]'::jsonb, '["b"]', 'For fibroids, the nursing priorities are monitoring for anemia and educating on the non-cancerous nature of the growths. Partner treatment applies to PID, and emergency surgery applies to cyst torsion or rupture.'),
  ('organ', 49, 'A client is surprised to learn that a routine ultrasound found an ovarian cyst, since she has had no pain or other symptoms. She asks if this is unusual. Which response by the nurse is best?', '[{"id": "a", "text": "Many ovarian cysts cause no symptoms and are found incidentally"}, {"id": "b", "text": "Ovarian cysts typically cause severe pain, so hers may be rupturing"}, {"id": "c", "text": "Ovarian cysts typically cause fever, so an infection should be ruled out"}, {"id": "d", "text": "Ovarian cysts typically cause heavy periods, so anemia should be checked"}]'::jsonb, '["a"]', 'Ovarian cysts are often asymptomatic, with large cysts causing pain, bloating, and pressure. Fever suggests PID, and heavy bleeding is associated with fibroids.'),
  ('organ', 50, 'A client being treated with antibiotics for pelvic inflammatory disease asks when she can resume sexual activity. Which instruction is most important for the nurse to emphasize?', '[{"id": "a", "text": "Intercourse may continue as long as she takes NSAIDs for pain"}, {"id": "b", "text": "Intercourse may continue once her own fever has fully resolved"}, {"id": "c", "text": "Intercourse may continue as long as her partner is not having any symptoms"}, {"id": "d", "text": "Intercourse should be avoided, with pelvic rest during treatment"}]'::jsonb, '["d"]', 'Treatment of PID includes pelvic rest and treatment of partners. Resolution of her fever or an asymptomatic partner does not replace these measures.'),
  ('naegele', 1, 'At her first prenatal visit, a client with regular 28-day cycles reports that her last menstrual period began on October 27, 2025. Using Naegele''s rule, which estimated date of delivery should the nurse record?', '[{"id": "a", "text": "July 20, 2026"}, {"id": "b", "text": "August 3, 2026"}, {"id": "c", "text": "August 3, 2025"}, {"id": "d", "text": "February 3, 2026"}]'::jsonb, '["b"]', 'For an LMP in April-December: subtract 3 months (July 27), add 7 days (August 3, since July has 31 days), and add 1 year (2026). August 3, 2025 omits the year, and February 3, 2026 results from adding rather than subtracting 3 months.'),
  ('naegele', 2, 'A client with regular 28-day cycles states that the first day of her last menstrual period was September 26, 2025. Applying Naegele''s rule and checking month lengths carefully, which EDD is correct?', '[{"id": "a", "text": "July 2, 2026"}, {"id": "b", "text": "June 19, 2026"}, {"id": "c", "text": "July 3, 2025"}, {"id": "d", "text": "July 3, 2026"}]'::jsonb, '["d"]', 'September 26 minus 3 months is June 26; adding 7 days crosses the end of June, which has 30 days, giving July 3; adding 1 year gives 2026. July 2 results from treating June as a 31-day month.'),
  ('naegele', 3, 'A client with regular 28-day cycles reports that her last menstrual period started on August 27, 2025. Using Naegele''s rule, which estimated date of delivery should the nurse document?', '[{"id": "a", "text": "June 3, 2026"}, {"id": "b", "text": "June 4, 2026"}, {"id": "c", "text": "May 20, 2026"}, {"id": "d", "text": "June 3, 2025"}]'::jsonb, '["a"]', 'August 27 minus 3 months is May 27; adding 7 days gives June 3 because May has 31 days; adding 1 year gives 2026. June 4 treats May as a 30-day month, and May 20 subtracts the 7 days.'),
  ('naegele', 4, 'A client with regular 28-day cycles reports that her last menstrual period began on January 12, 2026. Using the form of Naegele''s rule that applies to this LMP, which EDD should the nurse calculate?', '[{"id": "a", "text": "October 19, 2027"}, {"id": "b", "text": "October 5, 2026"}, {"id": "c", "text": "October 19, 2026"}, {"id": "d", "text": "October 19, 2025"}]'::jsonb, '["c"]', 'For an LMP in January-March, add 7 days (January 19) and then add 9 months (October 19, 2026) with no added year. October 19, 2027 wrongly adds a year, and October 5 subtracts the 7 days.'),
  ('naegele', 5, 'A client with regular 28-day cycles reports that her last menstrual period began on March 27, 2026. Using the form of Naegele''s rule that applies to this LMP, which EDD should the nurse calculate?', '[{"id": "a", "text": "January 3, 2026"}, {"id": "b", "text": "January 3, 2027"}, {"id": "c", "text": "January 4, 2027"}, {"id": "d", "text": "December 20, 2026"}]'::jsonb, '["b"]', 'Adding 7 days to March 27 gives April 3 (March has 31 days); adding 9 months to April 3 lands on January 3 of the following year, 2027. January 3, 2026 misses the year change, and January 4 treats March as a 30-day month.'),
  ('naegele', 6, 'A client with regular 28-day cycles reports that her last menstrual period began on January 28, 2026. Using the appropriate form of Naegele''s rule, which estimated date of delivery is correct?', '[{"id": "a", "text": "November 5, 2026"}, {"id": "b", "text": "November 4, 2027"}, {"id": "c", "text": "October 21, 2026"}, {"id": "d", "text": "November 4, 2026"}]'::jsonb, '["d"]', 'Adding 7 days to January 28 gives February 4 because January has 31 days; adding 9 months gives November 4, 2026. November 5 treats January as a 30-day month, and November 4, 2027 adds a year the January-March formula does not use.'),
  ('naegele', 7, 'For a client whose last menstrual period began on March 5, 2026, a nurse documents an estimated date of delivery of December 12, 2027. Which error BEST explains the nurse''s result?', '[{"id": "a", "text": "Adding a year, which the January–March formula omits"}, {"id": "b", "text": "Subtracting 7 days instead of adding the 7 days"}, {"id": "c", "text": "Subtracting 3 months instead of adding the 9 months"}, {"id": "d", "text": "Miscounting the number of days in March"}]'::jsonb, '["a"]', 'For a March LMP, add 7 days (March 12) and add 9 months (December 12, 2026); this formula has no step that adds a year. The month and day in the nurse''s answer are correct, so only the year is wrong.'),
  ('naegele', 8, 'A nursing student calculates the EDD for a client whose last menstrual period began on October 30, 2025, and records August 7, 2026. Which error BEST explains the student''s result?', '[{"id": "a", "text": "Forgetting to add the 1 year to the final result"}, {"id": "b", "text": "Adding 3 months instead of subtracting them"}, {"id": "c", "text": "Counting July as a month with 30 days, not 31"}, {"id": "d", "text": "Adding the 7 days before subtracting 3 months"}]'::jsonb, '["c"]', 'October 30 minus 3 months is July 30; adding 7 days across a 31-day July gives August 6, then add 1 year (August 6, 2026). Reaching August 7 means July was counted as 30 days; the year in the student''s answer is correct.'),
  ('naegele', 9, 'A client with regular 28-day cycles states that her last menstrual period began on December 10, 2025. Using Naegele''s rule, which estimated date of delivery should the nurse record?', '[{"id": "a", "text": "September 17, 2026"}, {"id": "b", "text": "September 17, 2025"}, {"id": "c", "text": "March 17, 2026"}, {"id": "d", "text": "September 3, 2026"}]'::jsonb, '["a"]', 'December 10 minus 3 months is September 10, plus 7 days is September 17, plus 1 year gives 2026. September 17, 2025 omits the year, and March 17, 2026 results from adding 3 months instead of subtracting.'),
  ('naegele', 10, 'The nurse audits EDDs that were calculated with Naegele''s rule for four clients with regular 28-day cycles. Which client''s documented EDD requires correction?', '[{"id": "a", "text": "LMP May 14, 2026; EDD February 21, 2027"}, {"id": "b", "text": "LMP July 15, 2026; EDD April 22, 2026"}, {"id": "c", "text": "LMP November 12, 2025; EDD August 19, 2026"}, {"id": "d", "text": "LMP February 10, 2026; EDD November 17, 2026"}]'::jsonb, '["b"]', 'July 15, 2026 minus 3 months is April 15, plus 7 days is April 22, plus 1 year gives April 22, 2027; the documented date omits the year. The other three EDDs are calculated correctly.'),
  ('naegele', 11, 'A client whose menstrual cycles are irregular, ranging from 35 to 45 days, asks how accurate the due date calculated from her LMP is likely to be. Which response by the nurse is BEST?', '[{"id": "a", "text": "The rule gives an exact date regardless of cycle length."}, {"id": "b", "text": "The rule cannot be used because her LMP is already known."}, {"id": "c", "text": "The rule is accurate as long as she knows the LMP date exactly."}, {"id": "d", "text": "The rule assumes a 28-day cycle, so the date is less certain."}]'::jsonb, '["d"]', 'Naegele''s rule requires a known LMP and assumes a 28-day cycle, so it is less reliable when cycles are irregular. Knowing the LMP alone does not make the estimate accurate.'),
  ('naegele', 12, 'After her EDD is calculated as August 3, a primigravida with regular 28-day cycles says, ''Great, I''ll book my mother''s flight to arrive that morning for the birth.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, the rule predicts the exact day labor will begin."}, {"id": "b", "text": "Yes, that works because your cycles are every 28 days."}, {"id": "c", "text": "That date is an estimate, not the exact day of birth."}, {"id": "d", "text": "That date runs early, so plan for 2 weeks afterward."}]'::jsonb, '["c"]', 'Naegele''s rule provides only an estimate of the due date, not the exact date of birth, even when the 28-day cycle assumption is met.'),
  ('naegele', 13, 'A client with an uncomplicated pregnancy has an EDD of March 20, 2027. At today''s visit on January 9, 2027, she asks how often she will be seen from now on. Which response by the nurse is BEST?', '[{"id": "a", "text": "Every 4 weeks until she reaches 32 weeks of gestation"}, {"id": "b", "text": "Every 2 weeks until she reaches 36 weeks"}, {"id": "c", "text": "Every week from now until her delivery"}, {"id": "d", "text": "Every 3 weeks until she reaches 34 weeks"}]'::jsonb, '["b"]', 'The EDD represents 40 weeks; January 9 is 70 days (10 weeks) before March 20, so she is at 30 weeks. Third-trimester visits are every 2 weeks from 28 to 36 weeks, then weekly.'),
  ('naegele', 14, 'An Rh-positive client with an EDD of August 3, 2026 is seen on July 6, 2026 for a routine visit. Which antepartum test is MOST appropriately due at this visit?', '[{"id": "a", "text": "Glucose tolerance test for diabetes"}, {"id": "b", "text": "First ultrasound for fetal growth"}, {"id": "c", "text": "Group B strep screening culture"}, {"id": "d", "text": "RhoGAM to prevent sensitization"}]'::jsonb, '["c"]', 'July 6 is 4 weeks before the 40-week EDD, so she is at 36 weeks, within the 35-37 week window for GBS screening. The GTT is done at 24-28 weeks, the first ultrasound at 8-12 weeks, and RhoGAM applies to Rh-negative mothers.'),
  ('naegele', 15, 'A client with regular 28-day cycles whose last menstrual period began on January 12, 2026 is seen on July 27, 2026. Which fundal height measurement should the nurse expect at this visit?', '[{"id": "a", "text": "About 28 cm"}, {"id": "b", "text": "About 24 cm"}, {"id": "c", "text": "About 32 cm"}, {"id": "d", "text": "About 20 cm"}]'::jsonb, '["a"]', 'From January 12 to July 27 is 196 days, or 28 weeks of gestation. Between 20 and 36 weeks, fundal height in centimeters approximately equals weeks of gestation, so about 28 cm is expected.'),
  ('naegele', 16, 'A client with regular 28-day cycles whose last menstrual period began on March 5, 2026 is seen on August 27, 2026 for a routine visit. Which antepartum test is MOST appropriate to anticipate now?', '[{"id": "a", "text": "Group B strep vaginal culture"}, {"id": "b", "text": "First-trimester ultrasound"}, {"id": "c", "text": "Non-stress test as a routine screen"}, {"id": "d", "text": "Glucose tolerance test"}]'::jsonb, '["d"]', 'March 5 to August 27 is 175 days, or 25 weeks, which falls in the 24-28 week window for the glucose tolerance test. GBS screening is at 35-37 weeks, and an NST is done after 28 weeks if concerns arise.'),
  ('naegele', 17, 'A client at 34 weeks reports occasional irregular tightening of her abdomen and mild swelling of her feet by evening. She has no headache, visual changes, or bleeding. Which response by the nurse is BEST?', '[{"id": "a", "text": "These are expected third-trimester changes; review danger signs"}, {"id": "b", "text": "Swelling at this stage indicates preeclampsia; come in right now"}, {"id": "c", "text": "Tightening at 34 weeks indicates preterm labor; go to the hospital"}, {"id": "d", "text": "Both findings suggest fetal distress; begin counting movements"}]'::jsonb, '["a"]', 'Braxton Hicks contractions and swelling are expected in the third trimester. Danger signs include sudden severe swelling of the hands and face, severe headache with blurred vision, and severe abdominal pain.'),
  ('naegele', 18, 'The nurse is triaging messages from four pregnant clients. Which client should the nurse contact FIRST?', '[{"id": "a", "text": "10 weeks: morning sickness and daytime fatigue all week"}, {"id": "b", "text": "18 weeks: less nausea and a growing belly"}, {"id": "c", "text": "30 weeks: sudden severe swelling of face and hands"}, {"id": "d", "text": "36 weeks: mild Braxton Hicks contractions at night"}]'::jsonb, '["c"]', 'Sudden severe swelling of the hands and face is a danger sign of preeclampsia that requires immediate help. Morning sickness and fatigue, less nausea with a growing belly, and Braxton Hicks contractions are expected for their trimesters.'),
  ('naegele', 19, 'The nurse auscultates fetal heart rates during four clients'' prenatal visits. Which fetal heart rate should the nurse report to the provider?', '[{"id": "a", "text": "112 bpm at 24 weeks"}, {"id": "b", "text": "106 bpm at 30 weeks"}, {"id": "c", "text": "158 bpm at 20 weeks"}, {"id": "d", "text": "146 bpm at 36 weeks"}]'::jsonb, '["b"]', 'Normal fetal heart rate is 110-160 bpm, so 106 bpm is below normal and should be reported. Rates of 112, 146, and 158 bpm fall within the normal range.'),
  ('naegele', 20, 'A client at 32 weeks reports that her baby has been moving much less since yesterday. The nurse obtains a fetal heart rate of 164 bpm. Which action by the nurse is BEST?', '[{"id": "a", "text": "Reassure her that this heart rate is within normal limits"}, {"id": "b", "text": "Teach her to count kicks and recheck at the next visit"}, {"id": "c", "text": "Schedule a glucose tolerance test for later this week"}, {"id": "d", "text": "Report the findings and anticipate a non-stress test"}]'::jsonb, '["d"]', 'Decreased fetal movement can signal fetal distress, and an FHR of 164 bpm is above the 110-160 bpm normal range. An NST is used after 28 weeks when concerns arise.'),
  ('naegele', 21, 'The nurse reviews blood pressures recorded at four clients'' prenatal visits. Which client requires follow-up for possible preeclampsia?', '[{"id": "a", "text": "146/92 mm Hg at 30 weeks"}, {"id": "b", "text": "136/86 mm Hg at 28 weeks"}, {"id": "c", "text": "128/78 mm Hg at 34 weeks"}, {"id": "d", "text": "138/88 mm Hg at 24 weeks"}]'::jsonb, '["a"]', 'Blood pressure is monitored for preeclampsia at 140/90 or higher; 146/92 exceeds this threshold. The other readings are below 140/90.'),
  ('naegele', 22, 'At 22 weeks, a client''s urine dipstick shows glucose with no protein, and her blood pressure is 118/74. Which risk does this finding MOST suggest, and which test should the nurse anticipate?', '[{"id": "a", "text": "Preeclampsia; closer blood pressure monitoring"}, {"id": "b", "text": "Ectopic pregnancy; serial hCG levels"}, {"id": "c", "text": "Gestational diabetes; GTT at 24-28 weeks"}, {"id": "d", "text": "Hyperemesis; monitoring for ketonuria"}]'::jsonb, '["c"]', 'Glucosuria indicates gestational diabetes risk, and the glucose tolerance test is done at 24-28 weeks. Proteinuria, not glucosuria, signals preeclampsia risk.'),
  ('naegele', 23, 'A client at 33 weeks has a blood pressure of 152/98 mm Hg and protein on urine dipstick, and she reports a severe headache with blurred vision. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Recheck the urine dipstick at her next visit"}, {"id": "b", "text": "Notify the provider immediately of these findings"}, {"id": "c", "text": "Schedule a glucose tolerance test for later this week"}, {"id": "d", "text": "Advise rest and extra fluids at home tonight"}]'::jsonb, '["b"]', 'Severe headache, blurred vision, and high blood pressure are danger signs of preeclampsia, and proteinuria adds to that risk; help must be sought immediately.'),
  ('naegele', 24, 'The nurse reviews total weight gain for four clients at 39 weeks. Which client''s weight gain falls outside the recommended range for her pre-pregnancy BMI?', '[{"id": "a", "text": "Normal BMI; gained 30 lb"}, {"id": "b", "text": "Overweight; gained 22 lb"}, {"id": "c", "text": "Obese; gained 17 lb"}, {"id": "d", "text": "Obese; gained 24 lb"}]'::jsonb, '["d"]', 'Recommended total gain is 11-20 lb for obese clients, so 24 lb exceeds the range. A 30 lb gain with normal BMI (25-35 lb), 22 lb when overweight (15-25 lb), and 17 lb when obese are within range.'),
  ('naegele', 25, 'A client with a normal pre-pregnancy BMI has gained 21 lb by 39 weeks and proudly says she ''stayed under 25 pounds.'' Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Her gain fits the overweight range, so it is ideal for her"}, {"id": "b", "text": "Her gain is above the recommended range for a normal BMI"}, {"id": "c", "text": "Her gain is below the 25-35 lb range for a normal BMI"}, {"id": "d", "text": "Her gain is acceptable because any gain under 25 lb is safe"}]'::jsonb, '["c"]', 'The recommended total gain for a normal BMI is 25-35 lb, so 21 lb is below range. The 15-25 lb range applies to overweight clients, not to her.'),
  ('naegele', 26, 'A client with regular 28-day cycles whose last menstrual period began on January 12, 2026 calls on February 23, 2026, worried that she has not yet had an ultrasound to confirm her pregnancy. Which response by the nurse is BEST?', '[{"id": "a", "text": "At 6 weeks she is before the usual 8 to 12 week window"}, {"id": "b", "text": "It is overdue; it is normally done by 4 weeks after the LMP"}, {"id": "c", "text": "It is not due yet; the first scan is usually at 24-28 weeks"}, {"id": "d", "text": "It is overdue; it should be done once hCG turns positive"}]'::jsonb, '["a"]', 'January 12 to February 23 is 42 days, or 6 weeks. The first ultrasound to confirm pregnancy, fetal growth, and anatomy is done at 8-12 weeks, so it is not yet due; 24-28 weeks is the GTT window.'),
  ('naegele', 27, 'A client at 20 weeks whose mother has type 2 diabetes asks the nurse to order her gestational diabetes screening today so it is done early. Which response by the nurse is BEST?', '[{"id": "a", "text": "This screening is done for everyone at the first visit."}, {"id": "b", "text": "This screening is usually done at 24 to 28 weeks."}, {"id": "c", "text": "This screening is done once glucose shows in the urine."}, {"id": "d", "text": "This screening is done at 35-37 weeks with the GBS swab."}]'::jsonb, '["b"]', 'The glucose tolerance test screens for gestational diabetes at 24-28 weeks. GBS screening, not glucose testing, is done at 35-37 weeks.'),
  ('naegele', 28, 'An Rh-negative client who received RhoGAM at 28 weeks gave birth 30 hours ago. Her newborn''s blood type is Rh-positive. Which action by the nurse is BEST?', '[{"id": "a", "text": "No dose is needed since she received it at 28 weeks"}, {"id": "b", "text": "Hold the dose because more than 24 hours have passed"}, {"id": "c", "text": "Give RhoGAM now, within 72 hours of the delivery"}, {"id": "d", "text": "Give RhoGAM at her 6-week postpartum checkup"}]'::jsonb, '["c"]', 'Rh-negative mothers receive RhoGAM at 28 weeks and again within 72 hours postpartum if the baby is Rh-positive. At 30 hours she is still within the 72-hour window.'),
  ('naegele', 29, 'The nurse reviews four prenatal clients'' charts. For which client is a non-stress test MOST appropriate to anticipate today?', '[{"id": "a", "text": "A client at 20 weeks at a routine visit with no concerns"}, {"id": "b", "text": "A client at 26 weeks whose fundal height matches her dates"}, {"id": "c", "text": "A client at 12 weeks reporting morning sickness and fatigue"}, {"id": "d", "text": "A client at 30 weeks reporting decreased fetal movement"}]'::jsonb, '["d"]', 'The non-stress test assesses FHR response to fetal movement and is done after 28 weeks if concerns arise; decreased fetal movement is a danger sign of possible fetal distress.'),
  ('naegele', 30, 'A client at 32 weeks calls reporting bright red vaginal bleeding that began an hour ago. She has no history of problems in this pregnancy. Which interpretation and action is BEST?', '[{"id": "a", "text": "Possible abruption or previa; seek care immediately"}, {"id": "b", "text": "Expected late-pregnancy change; rest and hydrate"}, {"id": "c", "text": "Possible preterm labor; time contractions for an hour"}, {"id": "d", "text": "Possible miscarriage; monitor pad count at home"}]'::jsonb, '["a"]', 'Bright red vaginal bleeding in pregnancy is a danger sign of placental abruption or previa, and the client must seek help immediately. Waiting at home delays care.'),
  ('naegele', 31, 'The nurse returns phone calls from four pregnant clients. Which client should the nurse instruct to seek care FIRST?', '[{"id": "a", "text": "10 weeks: nausea in the mornings and fatigue"}, {"id": "b", "text": "29 weeks: severe abdominal pain for an hour"}, {"id": "c", "text": "16 weeks: less nausea and a growing belly"}, {"id": "d", "text": "33 weeks: occasional painless Braxton Hicks"}]'::jsonb, '["b"]', 'Severe abdominal pain is a danger sign of possible miscarriage or preterm labor and requires immediate help. The other clients describe findings expected for their trimester.'),
  ('naegele', 32, 'A client at 35 weeks calls and says the baby has been moving much less than usual since yesterday evening. She has no bleeding or pain. Which response by the nurse is BEST?', '[{"id": "a", "text": "This may signal fetal distress; come in to be evaluated now."}, {"id": "b", "text": "Movement normally slows late in pregnancy; keep monitoring."}, {"id": "c", "text": "This is expected before labor; keep your routine weekly visit."}, {"id": "d", "text": "This may signal preeclampsia; check your blood pressure later."}]'::jsonb, '["a"]', 'Decreased fetal movement is a danger sign of possible fetal distress, and help should be sought immediately. Preeclampsia warning signs are severe headache, blurred vision, high BP, and sudden swelling of the hands and face.'),
  ('naegele', 33, 'A client whose last menstrual period was 7 weeks ago reports sharp right-sided lower abdominal pain and vaginal spotting. Her urine hCG is positive, and her vital signs are stable. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Perform a vaginal exam to assess the cervix and adnexa"}, {"id": "b", "text": "Reassure her that spotting is common in early pregnancy"}, {"id": "c", "text": "Notify the provider and avoid performing a vaginal exam"}, {"id": "d", "text": "Schedule her routine first ultrasound for next month instead"}]'::jsonb, '["c"]', 'Unilateral lower abdominal pain, vaginal bleeding, and a missed period form the classic triad of ectopic pregnancy. A vaginal exam may cause rupture, so the nurse notifies the provider immediately and monitors for shock.'),
  ('naegele', 34, 'A client being evaluated for a suspected tubal pregnancy suddenly reports right shoulder pain and dizziness. Her BP is 84/50 mm Hg, and her heart rate is 126/min. Which action is the PRIORITY?', '[{"id": "a", "text": "Prepare to administer methotrexate by intramuscular route"}, {"id": "b", "text": "Reposition her shoulder and give an oral analgesic"}, {"id": "c", "text": "Draw a repeat serum hCG level in 48 hours"}, {"id": "d", "text": "Prepare for emergency surgery and monitor for shock"}]'::jsonb, '["d"]', 'Shoulder tip pain, dizziness, hypotension, and tachycardia indicate rupture with internal bleeding. Rupture requires emergency laparoscopic surgery or salpingectomy with monitoring for hemorrhagic shock; methotrexate is for early, unruptured cases in stable patients.'),
  ('naegele', 35, 'Four clients at about 6 weeks'' gestation have serum hCG levels drawn 48 hours apart. Which client''s results are MOST consistent with an ectopic pregnancy?', '[{"id": "a", "text": "1,400 rising to 1,750 mIU/mL"}, {"id": "b", "text": "1,400 rising to 2,900 mIU/mL"}, {"id": "c", "text": "2,000 rising to 4,100 mIU/mL"}, {"id": "d", "text": "900 rising to 1,850 mIU/mL"}]'::jsonb, '["a"]', 'In ectopic pregnancy, hCG rises slowly and does not double every 48 hours. A rise from 1,400 to 1,750 is well short of doubling, while the other three values more than double.'),
  ('naegele', 36, 'A client with a positive hCG and unilateral lower abdominal pain has a transvaginal ultrasound that shows no embryo within the uterus. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "It confirms a normal early intrauterine pregnancy is present"}, {"id": "b", "text": "It supports the suspicion of an ectopic pregnancy"}, {"id": "c", "text": "It rules out pregnancy because no embryo is seen"}, {"id": "d", "text": "It indicates hyperemesis gravidarum is the cause"}]'::jsonb, '["b"]', 'Diagnostic findings of ectopic pregnancy include a positive hCG that rises slowly and a transvaginal ultrasound showing no embryo in the uterus. The positive hCG means pregnancy is not ruled out.'),
  ('naegele', 37, 'Four clients have a confirmed tubal pregnancy. Which client is the BEST candidate for treatment with methotrexate rather than surgery?', '[{"id": "a", "text": "Early, unruptured, with stable vital signs"}, {"id": "b", "text": "Shoulder pain, BP 86/52, and HR of 124/min"}, {"id": "c", "text": "Rupture of the fallopian tube on ultrasound"}, {"id": "d", "text": "Dizziness and a fainting episode at home"}]'::jsonb, '["a"]', 'Methotrexate is used early, before rupture, in a stable patient. Shoulder pain, hypotension, tachycardia, fainting, or confirmed rupture call for surgery.'),
  ('naegele', 38, 'A client is discharged after methotrexate treatment for an unruptured ectopic pregnancy. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will avoid drinking alcohol while I am being treated."}, {"id": "b", "text": "I will keep taking my prenatal vitamin with folic acid."}, {"id": "c", "text": "I won''t take ibuprofen for any of the cramping that I have."}, {"id": "d", "text": "We will wait at least 3 months before trying again."}]'::jsonb, '["b"]', 'During methotrexate therapy, folic acid, alcohol, and NSAIDs are avoided, and the client waits 3 or more months before conceiving. Continuing a folic acid-containing prenatal vitamin is incorrect.'),
  ('naegele', 39, 'The nurse follows up by phone with a client 1 week after methotrexate treatment for an ectopic pregnancy. Which statement by the client is MOST concerning?', '[{"id": "a", "text": "I have not had any alcohol since my injection last week."}, {"id": "b", "text": "I stopped the vitamins that contain folic acid."}, {"id": "c", "text": "We plan to start trying to conceive next month."}, {"id": "d", "text": "I have avoided ibuprofen and other NSAIDs."}]'::jsonb, '["c"]', 'After methotrexate, the client should wait 3 or more months before conceiving, so trying next month needs correction. Avoiding alcohol, folic acid, and NSAIDs is correct.'),
  ('naegele', 40, 'An Rh-negative client is being treated for an ectopic pregnancy. In addition to treatment of the ectopic pregnancy itself, which medication should the nurse anticipate?', '[{"id": "a", "text": "Thiamine (vitamin B1)"}, {"id": "b", "text": "Ondansetron for nausea"}, {"id": "c", "text": "Folic acid supplement"}, {"id": "d", "text": "RhoGAM"}]'::jsonb, '["d"]', 'RhoGAM is given when the mother with an ectopic pregnancy is Rh-negative, to prevent isoimmunization. Folic acid is avoided with methotrexate, and thiamine is used in prolonged vomiting.'),
  ('naegele', 41, 'A nursing student is caring for a client with suspected ectopic pregnancy who reports unilateral pelvic pain. Which action by the student requires the nurse to intervene FIRST?', '[{"id": "a", "text": "Setting up equipment for a bimanual pelvic exam"}, {"id": "b", "text": "Monitoring blood pressure and heart rate frequently"}, {"id": "c", "text": "Asking whether she has any pain in her shoulder"}, {"id": "d", "text": "Checking whether she feels dizzy when standing up"}]'::jsonb, '["a"]', 'A vaginal exam must not be performed when ectopic pregnancy is suspected because it may cause rupture. Monitoring vital signs and asking about shoulder pain or dizziness are appropriate checks for rupture and shock.'),
  ('naegele', 42, 'Four clients at 10 weeks report persistent vomiting. Based on weight loss from pre-pregnancy weight, which client meets the weight-loss criterion for hyperemesis gravidarum?', '[{"id": "a", "text": "Pre-pregnancy 150 lb; now 144 lb"}, {"id": "b", "text": "Pre-pregnancy 140 lb; now 132 lb"}, {"id": "c", "text": "Pre-pregnancy 120 lb; now 115 lb"}, {"id": "d", "text": "Pre-pregnancy 160 lb; now 153 lb"}]'::jsonb, '["b"]', 'Hyperemesis gravidarum involves weight loss of more than 5% of pre-pregnancy weight. An 8 lb loss from 140 lb is about 5.7%, while the other losses are about 4.0%, 4.2%, and 4.4%.'),
  ('naegele', 43, 'A client at 9 weeks is admitted with hyperemesis gravidarum. Which assessment finding requires the nurse''s immediate follow-up with the provider?', '[{"id": "a", "text": "Ketones present on the urine dipstick"}, {"id": "b", "text": "Nausea triggered by the smell of cooking"}, {"id": "c", "text": "Urine output of 22 mL/hr for 4 hours"}, {"id": "d", "text": "Weight down 1 lb since yesterday''s weight"}]'::jsonb, '["c"]', 'Urine output under 30 mL/hr means the kidneys are struggling, with possible acute kidney injury, and needs immediate follow-up. Ketonuria reflects the body burning fat because of no food intake rather than kidney compromise.'),
  ('naegele', 44, 'A client hospitalized after 3 weeks of persistent vomiting in pregnancy becomes newly confused and lethargic. Which medication should the nurse anticipate as the PRIORITY?', '[{"id": "a", "text": "Ondansetron"}, {"id": "b", "text": "Vitamin B6 with doxylamine"}, {"id": "c", "text": "Methotrexate"}, {"id": "d", "text": "Thiamine (vitamin B1)"}]'::jsonb, '["d"]', 'Confusion or lethargy in hyperemesis may signal electrolyte imbalance or Wernicke''s encephalopathy, and thiamine prevents Wernicke''s encephalopathy in prolonged vomiting. Ondansetron and B6 with doxylamine control nausea and vomiting.'),
  ('naegele', 45, 'A client at 8 weeks with hyperemesis gravidarum cannot keep fluids down. Her heart rate is 118/min, BP 92/58 mm Hg, and she is dizzy when she stands. Which intervention should the nurse implement FIRST?', '[{"id": "a", "text": "Start IV fluids (NS or LR) with electrolytes"}, {"id": "b", "text": "Offer small sips of clear liquids by mouth every hour"}, {"id": "c", "text": "Give oral vitamin B6 with doxylamine"}, {"id": "d", "text": "Encourage a bland diet in small portions"}]'::jsonb, '["a"]', 'Inability to keep fluids down, tachycardia, hypotension, and orthostatic changes indicate hypovolemia requiring IV rehydration with NS or LR plus electrolytes. Oral intake is not tolerated, and the diet is advanced only after an NPO period.'),
  ('naegele', 46, 'A client with hyperemesis gravidarum has been NPO and on IV fluids for 24 hours, and her vomiting has stopped. Which diet order should the nurse anticipate NEXT?', '[{"id": "a", "text": "Regular diet as tolerated"}, {"id": "b", "text": "Clear fluids"}, {"id": "c", "text": "Bland diet"}, {"id": "d", "text": "High-protein meals"}]'::jsonb, '["b"]', 'In hyperemesis, the client is kept NPO initially and the diet is advanced slowly: clear fluids first, then a bland diet.'),
  ('naegele', 47, 'A client recovering from hyperemesis gravidarum asks which oral medication regimen is considered first-line for nausea and vomiting in pregnancy. Which regimen should the nurse identify?', '[{"id": "a", "text": "Thiamine taken by itself"}, {"id": "b", "text": "Ondansetron taken alone"}, {"id": "c", "text": "Vitamin B6 plus doxylamine"}, {"id": "d", "text": "Oral rehydration with saline"}]'::jsonb, '["c"]', 'Vitamin B6 plus doxylamine is the first-line combination for pregnancy nausea and vomiting. Ondansetron is an antiemetic used to control vomiting, and thiamine prevents Wernicke''s encephalopathy.'),
  ('naegele', 48, 'A client is receiving treatment for hyperemesis gravidarum on the antepartum unit. Which nursing measure BEST monitors her fluid status and weight loss?', '[{"id": "a", "text": "Weekly weights at her clinic visits"}, {"id": "b", "text": "Asking about nausea every shift"}, {"id": "c", "text": "Checking the FHR once each day"}, {"id": "d", "text": "Daily weights and strict I&O"}]'::jsonb, '["d"]', 'Daily weights and strict intake and output monitor fluid status and weight loss in hyperemesis gravidarum.'),
  ('naegele', 49, 'A client at 11 weeks with hyperemesis gravidarum asks why the nurse is monitoring her baby''s well-being when it is her own vomiting that is the problem. Which response is BEST?', '[{"id": "a", "text": "Dehydration can reduce placental blood flow and slow growth."}, {"id": "b", "text": "Vomiting triggers contractions that then cause fetal distress."}, {"id": "c", "text": "Ketones in your urine are a sign the baby is overgrowing."}, {"id": "d", "text": "Fetal checks are routine for everyone after 10 weeks."}]'::jsonb, '["a"]', 'Dehydration can impair placental perfusion, and hyperemesis carries fetal risks of low birth weight, IUGR, and preterm birth. Ketonuria reflects maternal fat burning, not fetal overgrowth.'),
  ('naegele', 50, 'A client with 2 weeks of persistent vomiting in pregnancy has large ketones on her urine dipstick. She asks what this result means. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Her kidneys are injured and are releasing the ketones"}, {"id": "b", "text": "Her body is burning fat because of no food intake"}, {"id": "c", "text": "She is at risk for gestational diabetes"}, {"id": "d", "text": "She is at risk for preeclampsia later on"}]'::jsonb, '["b"]', 'Ketonuria in hyperemesis means the body is burning fat because of lack of food intake, leading to ketosis. Glucosuria signals gestational diabetes risk and proteinuria preeclampsia risk.'),
  ('ectopic', 1, 'A client whose last menstrual period was 7 weeks ago has a positive pregnancy test, dull right-sided pelvic cramping, and dark spotting on her pad. BP is 118/74 and heart rate is 82. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Possible unruptured ectopic; anticipate serial β-hCG and transvaginal ultrasound"}, {"id": "b", "text": "Ruptured ectopic; prepare for emergency laparotomy before any testing is done"}, {"id": "c", "text": "Normal early pregnancy; one-sided cramping with spotting is an expected finding"}, {"id": "d", "text": "Ruptured ectopic; the one-sided pelvic cramping confirms a positive Kehr''s sign"}]'::jsonb, '["a"]', 'Amenorrhea, unilateral pelvic pain, and abnormal spotting form the classic triad of an early, unruptured ectopic, and her vital signs are stable. Shoulder pain, not pelvic cramping, is Kehr''s sign, and shock signs indicate rupture.'),
  ('ectopic', 2, 'A client at 7 weeks with a suspected tubal pregnancy suddenly reports severe, sharp left lower abdominal pain and left shoulder pain. BP is 86/52, heart rate is 128, and her skin is cool and clammy. The provider has been called. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Review methotrexate precautions with the client and her partner"}, {"id": "b", "text": "Check her Rh status so RhoGAM can be given before any surgery"}, {"id": "c", "text": "Offer grief support and a referral for counseling about the loss"}, {"id": "d", "text": "Establish large-bore IV access and prepare her for emergency surgery"}]'::jsonb, '["d"]', 'Sudden severe pain, shoulder pain, hypotension, and tachycardia indicate a ruptured ectopic in shock, so large-bore IV access and surgical preparation come next. Rh status, grief support, and teaching matter but are not the immediate priority, and methotrexate is not used for rupture.'),
  ('ectopic', 3, 'A client at 6 weeks under evaluation for possible ectopic pregnancy, who is not receiving any medication, reports new left shoulder pain along with pelvic pain that has suddenly worsened. She denies any injury. Which explanation for the shoulder pain is MOST accurate?', '[{"id": "a", "text": "Distension of an unruptured tube, an expected early finding"}, {"id": "b", "text": "Blood in the abdomen irritating the diaphragm, suggesting rupture"}, {"id": "c", "text": "Separation pain as the ectopic tissue is reabsorbed by the body"}, {"id": "d", "text": "Muscle strain from lying still on the stretcher for a long time"}]'::jsonb, '["b"]', 'Shoulder pain (Kehr''s sign) is referred pain from diaphragm irritation by pooling blood and signals rupture. Tubal distension causes one-sided pelvic pain in the unruptured stage, and separation pain follows methotrexate therapy, which she is not receiving.'),
  ('ectopic', 4, 'A client with 8 weeks of amenorrhea and severe lower abdominal pain has a bluish discoloration around her umbilicus. BP is 92/56 and heart rate is 118. What does the periumbilical finding MOST likely indicate?', '[{"id": "a", "text": "Intra-abdominal hemorrhage from a ruptured ectopic pregnancy"}, {"id": "b", "text": "Bruising left from a needle inserted during a culdocentesis"}, {"id": "c", "text": "Peritoneal irritation that makes the abdomen rigid and board-like"}, {"id": "d", "text": "Referred pain from blood irritating the underside of the diaphragm"}]'::jsonb, '["a"]', 'Periumbilical bruising (Cullen''s sign) indicates intra-abdominal hemorrhage, a late sign of a ruptured ectopic. Culdocentesis uses a needle through the posterior fornix, not the umbilicus, and diaphragmatic irritation causes shoulder pain.'),
  ('ectopic', 5, 'A client at 6 weeks admitted for observation of a suspected unruptured ectopic pregnancy is reassessed by the nurse. Which finding requires IMMEDIATE notification of the provider?', '[{"id": "a", "text": "Dark spotting on her perineal pad"}, {"id": "b", "text": "Dull, crampy right-sided pelvic pain"}, {"id": "c", "text": "A rigid, board-like abdomen on palpation"}, {"id": "d", "text": "A positive urine pregnancy test result"}]'::jsonb, '["c"]', 'A rigid, board-like abdomen reflects peritoneal irritation from internal bleeding and signals rupture. Spotting, one-sided crampy pain, and a positive test are part of the expected picture of an unruptured ectopic.'),
  ('ectopic', 6, 'A client at 6 weeks awaiting ultrasound for a suspected ectopic pregnancy gets up to the bathroom and nearly faints. Her BP has dropped from 120/76 to 92/58, and her heart rate has risen from 84 to 118. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give oral fluids and help her walk again once she feels steadier"}, {"id": "b", "text": "Return her to bed, reassess vital signs, and notify the provider"}, {"id": "c", "text": "Document dizziness as an expected early pregnancy symptom"}, {"id": "d", "text": "Offer ibuprofen for her pain and recheck her blood pressure later"}]'::jsonb, '["b"]', 'Near-syncope with falling BP and rising heart rate suggests hemorrhage and possible rupture, so she must be kept safe, reassessed, and reported immediately. NSAIDs mask symptoms, and dizziness with shock signs is not an expected finding.'),
  ('ectopic', 7, 'A client at 6 weeks with light spotting has a serum β-hCG of 1,200 mIU/mL on Monday and 1,450 mIU/mL on Wednesday. Ultrasound results are pending. How should the nurse interpret this trend?', '[{"id": "a", "text": "The rise is appropriate for a normal intrauterine pregnancy"}, {"id": "b", "text": "The rise is less than expected, raising concern for ectopic"}, {"id": "c", "text": "The rise confirms that an ectopic pregnancy has already ruptured"}, {"id": "d", "text": "The rise is faster than expected for a single pregnancy"}]'::jsonb, '["b"]', 'A rise from 1,200 to 1,450 in 48 hours is about 21%, well under the 66% expected in a normal early pregnancy, so it is suspicious for ectopic or failed pregnancy. Rupture is identified clinically by shock signs, not by the β-hCG trend.'),
  ('ectopic', 8, 'A client with pelvic pain has a serum β-hCG of 2,300 mIU/mL. Transvaginal ultrasound shows no intrauterine gestational sac and a right adnexal mass. BP is 122/78 and heart rate is 80. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "It is too early to see a sac; repeat the ultrasound in about 4 weeks"}, {"id": "b", "text": "This is a ruptured ectopic that requires emergency laparotomy now"}, {"id": "c", "text": "This is ectopic pregnancy until proven otherwise; notify the provider"}, {"id": "d", "text": "This is a normal pregnancy, because the β-hCG level is positive"}]'::jsonb, '["c"]', 'A β-hCG above 1,500–2,000 mIU/mL with no intrauterine sac, plus an adnexal mass, is ectopic until proven otherwise. Her stable vital signs do not indicate rupture with shock.'),
  ('ectopic', 9, 'A nurse reviews serial serum β-hCG results drawn 48 hours apart for four clients at 5–6 weeks. Which client''s results are MOST consistent with a normal intrauterine pregnancy?', '[{"id": "a", "text": "1,000 mIU/mL, then 1,150 mIU/mL"}, {"id": "b", "text": "1,600 mIU/mL, then 1,650 mIU/mL"}, {"id": "c", "text": "900 mIU/mL, then 1,050 mIU/mL"}, {"id": "d", "text": "1,100 mIU/mL, then 2,300 mIU/mL"}]'::jsonb, '["d"]', 'In a normal early IUP, β-hCG roughly doubles every 48 hours; 1,100 to 2,300 more than doubles. The other results rise only 3–17% or plateau, which is suspicious for ectopic or failed pregnancy.'),
  ('ectopic', 10, 'A nurse reviews four clients with a confirmed tubal pregnancy and no contraindications to drug therapy. For which client should the nurse anticipate a prescription for methotrexate?', '[{"id": "a", "text": "Unruptured, 2.8-cm mass, low β-hCG, BP 118/72, no fetal cardiac activity"}, {"id": "b", "text": "Unruptured, 4.5-cm mass, high β-hCG, BP 120/76, no fetal cardiac activity"}, {"id": "c", "text": "Shoulder pain, 2.5-cm mass, low β-hCG, BP 86/50, heart rate of 126"}, {"id": "d", "text": "Unruptured, 2.6-cm mass, low β-hCG, BP 116/70, fetal cardiac activity"}]'::jsonb, '["a"]', 'Methotrexate is used for a hemodynamically stable, unruptured ectopic with a mass under 3.5 cm, low β-hCG, and no fetal cardiac activity. A large mass, fetal cardiac activity, or signs of rupture and shock exclude it.'),
  ('ectopic', 11, 'A hemodynamically stable client has an unruptured tubal pregnancy with a low β-hCG and no fetal cardiac activity. Ultrasound measures the mass at 3.8 cm. She asks why she cannot "just have the shot." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Your β-hCG level is too low for methotrexate to be effective.\""}, {"id": "b", "text": "\"Methotrexate is reserved for ectopics that have already ruptured.\""}, {"id": "c", "text": "\"Stable vital signs mean the shot would not be strong enough.\""}, {"id": "d", "text": "\"The mass is larger than the size limit for using methotrexate.\""}]'::jsonb, '["d"]', 'Methotrexate requires a small mass under 3.5 cm; at 3.8 cm she exceeds that limit. Low β-hCG and hemodynamic stability are criteria for methotrexate, and ruptured ectopics require surgery.'),
  ('ectopic', 12, 'A stable client with a 2.4-cm unruptured tubal pregnancy and low β-hCG is being evaluated for methotrexate. Which finding in her history should the nurse report to the provider BEFORE the drug is given?', '[{"id": "a", "text": "Chronic kidney disease diagnosed 3 years ago"}, {"id": "b", "text": "A previous ectopic pregnancy in the other tube"}, {"id": "c", "text": "Smoking about five cigarettes each day"}, {"id": "d", "text": "Light vaginal spotting for the past 2 days"}]'::jsonb, '["a"]', 'Liver or kidney disease and immunocompromise are contraindications to methotrexate. A prior ectopic and smoking are risk factors for ectopic pregnancy, and spotting is part of the early triad; none excludes methotrexate.'),
  ('ectopic', 13, 'On day 2 after methotrexate for an unruptured ectopic, a client with stable vital signs calls about mild cramping and asks what she can take at home. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Take ibuprofen, because it relieves this kind of cramping best.\""}, {"id": "b", "text": "\"Take your prenatal vitamin with folic acid to ease the cramping.\""}, {"id": "c", "text": "\"Take acetaminophen, because NSAIDs interfere with methotrexate.\""}, {"id": "d", "text": "\"Take nothing at all, because any cramping means the tube ruptured.\""}]'::jsonb, '["c"]', 'NSAIDs interfere with methotrexate and mask symptoms, so acetaminophen is used if needed. Folic acid counteracts methotrexate, and some pain is expected during treatment, so mild cramping alone does not mean rupture.'),
  ('ectopic', 14, 'A client who received methotrexate today for an unruptured ectopic says, "I''ll keep taking my prenatal vitamin with folic acid, since I want to get pregnant again someday." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Good plan; folic acid helps the methotrexate work more quickly.\""}, {"id": "b", "text": "\"Hold the folic acid during treatment, because it counteracts methotrexate.\""}, {"id": "c", "text": "\"Double the folic acid dose to protect your liver during treatment.\""}, {"id": "d", "text": "\"Keep taking it, but avoid ibuprofen while you are on methotrexate.\""}]'::jsonb, '["b"]', 'Methotrexate is a folic acid antagonist, and folic acid directly counteracts the drug, so it is avoided during treatment. Avoiding ibuprofen is correct, but continuing folic acid is not.'),
  ('ectopic', 15, 'A nurse completes discharge teaching for a client treated with methotrexate for an unruptured ectopic. Her β-hCG was 1,400 mIU/mL before treatment. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll avoid drinking alcohol while I''m being treated.\""}, {"id": "b", "text": "\"I''ll stay out of the sun and cover up when I''m outdoors.\""}, {"id": "c", "text": "\"I''ll come back to have my β-hCG level checked as scheduled.\""}, {"id": "d", "text": "\"We can resume intercourse as soon as my cramping is gone.\""}]'::jsonb, '["d"]', 'Intercourse is avoided until the ectopic has resolved and β-hCG is undetectable, not just until pain stops. Avoiding alcohol and sun and returning for β-hCG monitoring are correct.'),
  ('ectopic', 16, 'Six weeks after methotrexate for an ectopic pregnancy, a client''s β-hCG is undetectable. She tells the nurse, "We''re going to start trying for a baby next month." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"That timing is fine, since your β-hCG is now undetectable.\""}, {"id": "b", "text": "\"Waiting is not needed, because the drug was a single dose.\""}, {"id": "c", "text": "\"You should wait at least 3 months after the methotrexate.\""}, {"id": "d", "text": "\"You should wait until 1 year after the methotrexate dose.\""}]'::jsonb, '["c"]', 'Clients should wait at least 3 months after methotrexate because this folic acid antagonist can cause birth defects. An undetectable β-hCG confirms resolution but does not shorten the wait.'),
  ('ectopic', 17, 'On day 4 after methotrexate, a client calls reporting mild lower abdominal cramping that is relieved by acetaminophen. She denies shoulder pain or dizziness, and her home BP reading is 118/74. Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"This may be expected separation pain; call right away if it worsens.\""}, {"id": "b", "text": "\"This means the tube has ruptured; call emergency services right now.\""}, {"id": "c", "text": "\"This means methotrexate failed, so surgery will be scheduled today.\""}, {"id": "d", "text": "\"This pain should be treated with ibuprofen alternating with acetaminophen.\""}]'::jsonb, '["a"]', 'Some separation pain is expected 3–7 days after methotrexate as the ectopic dissolves, but severe or worsening pain can signal rupture and must be evaluated. NSAIDs are avoided because they interfere with methotrexate and mask symptoms.'),
  ('ectopic', 18, 'On day 5 after methotrexate, a client calls saying her pain has become sudden and severe on one side, and she felt lightheaded when she stood up. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "\"Take acetaminophen and call back if the pain continues tomorrow.\""}, {"id": "b", "text": "\"This is expected separation pain, so rest and drink extra fluids.\""}, {"id": "c", "text": "\"Get emergency evaluation now, because these may be signs of rupture.\""}, {"id": "d", "text": "\"Take ibuprofen, which works better than acetaminophen for this pain.\""}]'::jsonb, '["c"]', 'Severe or worsening pain after methotrexate can signal rupture and requires in-person emergency evaluation, especially with lightheadedness. Expected separation pain is milder and should not be managed at home once it becomes severe.'),
  ('ectopic', 19, 'A client treated with methotrexate for an unruptured ectopic has follow-up serum β-hCG levels. Which set of results BEST indicates that treatment is effective?', '[{"id": "a", "text": "2,100 → 2,150 → 2,140 mIU/mL"}, {"id": "b", "text": "2,100 → 2,600 → 3,200 mIU/mL"}, {"id": "c", "text": "2,100 → 1,600 → 900 mIU/mL"}, {"id": "d", "text": "2,100 → 2,050 → 2,300 mIU/mL"}]'::jsonb, '["c"]', 'β-hCG is monitored after methotrexate to confirm falling levels as the ectopic is reabsorbed. Plateauing or rising levels indicate that trophoblastic tissue persists.'),
  ('ectopic', 20, 'A client who is Rh-negative had a laparoscopic salpingostomy for an unruptured ectopic this morning. Her vital signs are stable and her pain is controlled. Which intervention is the nurse''s PRIORITY before discharge?', '[{"id": "a", "text": "Administering Rho(D) immune globulin (RhoGAM)"}, {"id": "b", "text": "Teaching her to avoid sun exposure for 3 months"}, {"id": "c", "text": "Starting methotrexate to prevent a recurrence"}, {"id": "d", "text": "Giving folic acid to replace her lost stores"}]'::jsonb, '["a"]', 'An Rh-negative client with an ectopic pregnancy receives RhoGAM to prevent sensitization. Sun avoidance and folic acid restrictions relate to methotrexate therapy, which she did not receive.'),
  ('ectopic', 21, 'A client with a ruptured ectopic is being prepared for emergency surgery. The nurse reviews her chart and finds that one laboratory result is missing. Which result must the nurse obtain to determine whether an additional medication is needed after the pregnancy loss?', '[{"id": "a", "text": "Serum β-hCG level"}, {"id": "b", "text": "Rh blood type"}, {"id": "c", "text": "Liver enzymes"}, {"id": "d", "text": "Urine culture"}]'::jsonb, '["b"]', 'Checking Rh status is a nursing priority, because an Rh-negative client needs RhoGAM to prevent sensitization after an ectopic pregnancy. Liver enzymes relate to methotrexate eligibility, which does not apply to a ruptured ectopic.'),
  ('ectopic', 22, 'Two days after a laparoscopic salpingostomy for a tubal pregnancy, a client asks why she must return for β-hCG blood tests when "the pregnancy was already removed." Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Some ectopic tissue can remain in the tube, so levels must keep falling.\""}, {"id": "b", "text": "\"The test checks whether your remaining tube has now been blocked by scarring.\""}, {"id": "c", "text": "\"The test decides whether you will need RhoGAM before your next period.\""}, {"id": "d", "text": "\"The test shows when it is safe to start taking ibuprofen for your pain.\""}]'::jsonb, '["a"]', 'Salpingostomy preserves the tube but carries a risk of persistent trophoblastic tissue, so β-hCG is followed. RhoGAM depends on Rh status, not on β-hCG.'),
  ('ectopic', 23, 'A client with a ruptured tubal pregnancy has BP 78/46, heart rate 136, cold clammy skin, and new confusion. She is being rushed to the operating room. Which procedure should the nurse anticipate?', '[{"id": "a", "text": "Laparoscopic salpingostomy to preserve the affected tube"}, {"id": "b", "text": "Methotrexate injection with surgery scheduled if it fails"}, {"id": "c", "text": "Emergency laparotomy to control bleeding and remove the tube"}, {"id": "d", "text": "Culdocentesis to confirm bleeding before deciding on surgery"}]'::jsonb, '["c"]', 'A ruptured ectopic with hemorrhagic shock requires emergency laparotomy, which gives the fastest surgical access to control hemorrhage, with removal of the tube. Salpingostomy is for stable clients, and methotrexate is only for unruptured ectopics.'),
  ('ectopic', 24, 'A stable client has her second ectopic pregnancy in the same fallopian tube, which ultrasound shows is severely damaged. She asks why the surgeon plans to remove the tube instead of saving it. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Removing the tube is preferred for a recurrent ectopic in a badly damaged tube.\""}, {"id": "b", "text": "\"Removing the tube is required, since saving it works only after rupture occurs.\""}, {"id": "c", "text": "\"Removing the tube is done for every ectopic, regardless of the client''s wishes.\""}, {"id": "d", "text": "\"Removing the tube is needed because her vital signs are too stable for drug therapy.\""}]'::jsonb, '["a"]', 'Salpingectomy is chosen for ruptured ectopics, large masses, recurrent ectopics, and severely damaged tubes. Tube-sparing salpingostomy is for stable clients who want to preserve fertility, and stability is a criterion for, not against, drug therapy.'),
  ('ectopic', 25, 'A client is recovering from a unilateral salpingectomy for a ruptured ectopic. Her other tube and both ovaries appeared normal during surgery. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I could still get pregnant using my remaining tube.\""}, {"id": "b", "text": "\"I still have some risk of another ectopic pregnancy.\""}, {"id": "c", "text": "\"I will never be able to get pregnant again now.\""}, {"id": "d", "text": "\"My ovary on that side can still release eggs.\""}]'::jsonb, '["c"]', 'After unilateral salpingectomy, the remaining tube and ovary can still support natural conception, so believing pregnancy is impossible is incorrect. Future ectopic risk still exists.'),
  ('ectopic', 26, 'A nurse in a gynecology clinic reviews the histories of four clients who each have a positive pregnancy test at 5 weeks. Which client has the HIGHEST risk for ectopic pregnancy?', '[{"id": "a", "text": "A client who smokes about half a pack of cigarettes each day"}, {"id": "b", "text": "A client who was treated for PID five years ago"}, {"id": "c", "text": "A client who had an ectopic pregnancy treated last year"}, {"id": "d", "text": "A client who has had two uncomplicated vaginal births"}]'::jsonb, '["c"]', 'A previous ectopic pregnancy scars the tube and is the number one risk factor. PID and smoking also increase risk but are not the strongest single factor.'),
  ('ectopic', 27, 'A client with an IUD in place has a positive home pregnancy test and mild left-sided pelvic pain. Her vital signs are within normal limits. Which nursing action is MOST appropriate?', '[{"id": "a", "text": "Reassure her that the IUD makes a tubal pregnancy impossible"}, {"id": "b", "text": "Arrange urgent evaluation with β-hCG and transvaginal ultrasound"}, {"id": "c", "text": "Schedule a routine prenatal visit in the next 4 to 6 weeks"}, {"id": "d", "text": "Teach her methotrexate precautions before any testing is done"}]'::jsonb, '["b"]', 'An IUD prevents uterine implantation but does not protect against tubal implantation, so a pregnancy with an IUD raises ectopic risk and needs urgent β-hCG and TVUS. Methotrexate is considered only after an ectopic is confirmed.'),
  ('ectopic', 28, 'A client recovering from an ectopic pregnancy treated with methotrexate smokes a pack of cigarettes a day and asks what she can change to lower her risk of another ectopic. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Stopping smoking may help, because smoking impairs the tube''s cilia movement.\""}, {"id": "b", "text": "\"Stopping smoking will not help, because only tubal surgery affects ectopic risk.\""}, {"id": "c", "text": "\"Using an IUD will prevent any future ectopic pregnancy from occurring.\""}, {"id": "d", "text": "\"Having surgery on your tubes will lower your risk of another ectopic.\""}]'::jsonb, '["a"]', 'Smoking impairs tubal motility (cilia movement) and is a modifiable risk factor. An IUD does not always prevent ectopic implantation, and previous pelvic or tubal surgery increases risk through adhesions.'),
  ('ectopic', 29, 'A client at 6 weeks with a history of pelvic inflammatory disease from chlamydia has spotting and right-sided pelvic pain. She asks how an infection years ago could affect this pregnancy. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"PID causes scarring and adhesions in the tubes that slow the egg''s transport.\""}, {"id": "b", "text": "\"PID weakens the lining of your uterus, so the pregnancy is unable to implant there.\""}, {"id": "c", "text": "\"PID raises β-hCG levels, which makes the egg implant outside the uterus.\""}, {"id": "d", "text": "\"PID bacteria stay in the tube and attack the pregnancy as it implants.\""}]'::jsonb, '["a"]', 'PID causes scarring and adhesions in the fallopian tubes that block normal transport, allowing implantation in the tube. The mechanism is tubal transport, not the uterine lining or β-hCG.'),
  ('ectopic', 30, 'A client who conceived through in vitro fertilization with embryo transfer reports dark spotting and dull left-sided pelvic pain at 6 weeks. She says, "The embryo was placed right in my uterus, so it can''t be ectopic." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"You''re right; embryo transfer prevents implantation in the tube.\""}, {"id": "b", "text": "\"Embryo transfer can still result in implantation in the tube.\""}, {"id": "c", "text": "\"These symptoms are normal with embryo transfer and need no tests.\""}, {"id": "d", "text": "\"An ectopic is possible, but only if you also have an IUD in place.\""}]'::jsonb, '["b"]', 'Assisted reproductive technology is a risk factor because embryo transfer can result in tubal implantation. Her spotting and one-sided pain fit the early ectopic triad and need evaluation.'),
  ('ectopic', 31, 'A client who had a tubal ligation 4 years ago has a positive pregnancy test, 7 weeks of amenorrhea, and sharp right-sided pelvic pain. Her vital signs are stable. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Tubal ligation makes pregnancy impossible, so the test is likely a false positive"}, {"id": "b", "text": "A failed tubal ligation raises ectopic risk, so she needs urgent evaluation"}, {"id": "c", "text": "A failed tubal ligation usually leads to a normal intrauterine pregnancy"}, {"id": "d", "text": "Her stable vital signs rule out ectopic pregnancy despite the tubal history"}]'::jsonb, '["b"]', 'Tubal ligation failure damages tube anatomy and increases the risk of ectopic implantation. Stable vital signs indicate no rupture yet; they do not rule out an unruptured ectopic.'),
  ('ectopic', 32, 'Transvaginal ultrasound in a stable client at 5 weeks shows an ectopic pregnancy in the narrow isthmus of the fallopian tube. Compared with an ampullary pregnancy, what should the nurse anticipate?', '[{"id": "a", "text": "A lower risk of rupture, because the isthmus is the widest part of the tube"}, {"id": "b", "text": "Rupture early in pregnancy, because the isthmus is a smaller part of the tube"}, {"id": "c", "text": "Rupture delayed until 6–10 weeks, the same timing as in the ampulla"}, {"id": "d", "text": "Implantation that usually resolves without any treatment or follow-up"}]'::jsonb, '["b"]', 'The isthmus has a very high rupture risk and ruptures early because it is the smaller, narrower part of the tube. Ampullary pregnancies typically rupture at 6–10 weeks.'),
  ('ectopic', 33, 'A nurse is reviewing ultrasound reports for four stable clients with confirmed ectopic pregnancies. Which implantation site places the client at HIGHEST risk for massive hemorrhage?', '[{"id": "a", "text": "Ampulla of the fallopian tube"}, {"id": "b", "text": "Fimbria of the fallopian tube"}, {"id": "c", "text": "Ovary"}, {"id": "d", "text": "Cervix"}]'::jsonb, '["d"]', 'Abdominal, cervical, and interstitial ectopics carry the highest risk and can lead to massive hemorrhage. Fimbrial and ovarian sites carry moderate risk, and ampullary pregnancies carry high risk.'),
  ('ectopic', 34, 'A client with a positive pregnancy test and lower abdominal pain undergoes culdocentesis in a facility without immediate ultrasound. Nonclotting blood is aspirated through the posterior fornix. What does this finding indicate?', '[{"id": "a", "text": "Internal bleeding into the cul-de-sac"}, {"id": "b", "text": "A normal intrauterine pregnancy in progress"}, {"id": "c", "text": "An unruptured tube with no bleeding"}, {"id": "d", "text": "Expected bleeding from the needle"}]'::jsonb, '["a"]', 'Blood in the cul-de-sac obtained through the posterior fornix indicates internal bleeding. Culdocentesis is less used today, with TVUS being the gold standard.'),
  ('ectopic', 35, 'A client with a suspected ectopic pregnancy had a hematocrit of 38% at 0800. At 1200 it is 31%, her heart rate has risen from 88 to 116, and she reports increasing pelvic pain. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Hemodilution from IV fluids; continue to monitor"}, {"id": "b", "text": "Expected change in a stable, unruptured ectopic"}, {"id": "c", "text": "Laboratory error that should be repeated at 1600"}, {"id": "d", "text": "Probable rupture with ongoing internal bleeding"}]'::jsonb, '["d"]', 'A falling hematocrit occurs with rupture, and the rising heart rate and worsening pain support internal bleeding. Delaying for a repeat test ignores the clinical signs of shock.'),
  ('ectopic', 36, 'A client at 6 weeks with spotting and unilateral pelvic pain has a positive serum β-hCG and stable vital signs. Which test should the nurse anticipate to BEST confirm the location of the pregnancy?', '[{"id": "a", "text": "Culdocentesis"}, {"id": "b", "text": "Complete blood count"}, {"id": "c", "text": "Transvaginal ultrasound"}, {"id": "d", "text": "Repeat urine pregnancy test"}]'::jsonb, '["c"]', 'Transvaginal ultrasound is the gold standard for diagnosing ectopic pregnancy because it shows whether an intrauterine sac or adnexal mass is present. A pregnancy test confirms pregnancy but not location.'),
  ('ectopic', 37, 'A client with a confirmed unruptured ectopic is awaiting surgery. Her vital signs at 1400 were BP 118/74 and heart rate 84. Which set of vital signs at 1500 requires the nurse''s IMMEDIATE action?', '[{"id": "a", "text": "BP 116/72, heart rate 88"}, {"id": "b", "text": "BP 120/78, heart rate 80"}, {"id": "c", "text": "BP 112/70, heart rate 92"}, {"id": "d", "text": "BP 92/58, heart rate 122"}]'::jsonb, '["d"]', 'Falling BP with rising heart rate signals shock from hemorrhage and possible rupture. The other readings show only minor variation from baseline.'),
  ('ectopic', 38, 'The day after surgery for a ruptured ectopic, a client''s vital signs are stable, and she is crying quietly. She says, "I didn''t even know I was pregnant, and now the baby is gone." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"At least it happened early, before you were attached to the pregnancy.\""}, {"id": "b", "text": "\"You can try again in a month or two, so try to focus on the future.\""}, {"id": "c", "text": "\"This is a real loss. Would you like information about counseling support?\""}, {"id": "d", "text": "\"Ectopic pregnancies could never have grown into a baby, so this isn''t a loss.\""}]'::jsonb, '["c"]', 'Nursing priorities include grief support for the loss of pregnancy and referral to counseling. Minimizing the loss or redirecting her to the future dismisses her grief.'),
  ('ectopic', 39, 'A nurse in the emergency department receives report on four clients in early pregnancy. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Rh-negative client with a treated ectopic, awaiting RhoGAM"}, {"id": "b", "text": "Client on methotrexate day 1, asking about sun precautions"}, {"id": "c", "text": "Client at 7 weeks with new shoulder pain and dizziness"}, {"id": "d", "text": "Client after salpingectomy, asking when she may conceive"}]'::jsonb, '["c"]', 'New shoulder pain with dizziness in early pregnancy suggests a ruptured ectopic with hemorrhage, a surgical emergency. The other clients need care or teaching but are not unstable.'),
  ('ectopic', 40, 'A client at 7 weeks suddenly develops sharp, one-sided pelvic pain and shoulder pain while in the clinic. Which sequence of nursing actions is MOST appropriate?', '[{"id": "a", "text": "Assess vital signs → notify the provider → insert a large-bore IV → prepare for surgery"}, {"id": "b", "text": "Notify the provider → order a transvaginal ultrasound → assess vital signs → insert an IV"}, {"id": "c", "text": "Give acetaminophen → assess vital signs → notify the provider → prepare for surgery"}, {"id": "d", "text": "Insert a large-bore IV → prepare for surgery → assess vital signs → notify the provider"}]'::jsonb, '["a"]', 'For sudden one-sided pain with shoulder pain in early pregnancy, the nurse assesses vital signs immediately, calls the provider for a suspected ruptured ectopic, and prepares for the OR with large-bore IV access. Treating pain or delaying vital signs postpones recognizing shock.'),
  ('ectopic', 41, 'A client at 7 weeks with a known tubal pregnancy is being monitored. Which new finding MOST clearly indicates that the ectopic pregnancy has ruptured?', '[{"id": "a", "text": "A missed period and a positive pregnancy test"}, {"id": "b", "text": "Dull, crampy pain on one side of the pelvis"}, {"id": "c", "text": "Light spotting that is darker than her usual menses"}, {"id": "d", "text": "Sudden, sharp pelvic pain with pain in her shoulder"}]'::jsonb, '["d"]', 'Sudden, severe, sharp pain with shoulder pain (Kehr''s sign) indicates rupture. Amenorrhea, dull one-sided pain, and abnormal spotting form the triad of an early, unruptured ectopic.'),
  ('ectopic', 42, 'A client with 7 weeks of amenorrhea and a positive pregnancy test calls the clinic saying, "I think my period finally started, but it''s only light brownish spotting, and my right side has been aching." Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "This is likely a normal menstrual period after a false-positive test"}, {"id": "b", "text": "This is abnormal bleeding that may signal an unruptured ectopic"}, {"id": "c", "text": "This is expected implantation bleeding in a normal pregnancy"}, {"id": "d", "text": "This is a ruptured ectopic, because bleeding is now present"}]'::jsonb, '["b"]', 'Bleeding with an ectopic is abnormal spotting or light bleeding, not normal period flow, and with one-sided pain and amenorrhea it completes the early triad. Bleeding alone does not indicate rupture; shock signs and shoulder pain do.'),
  ('ectopic', 43, 'A stable client with an unruptured 2.2-cm tubal pregnancy is receiving methotrexate. She asks, "How can a shot get rid of the pregnancy without surgery?" Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It blocks folic acid, stopping the pregnancy cells from dividing so the tissue is reabsorbed.\""}, {"id": "b", "text": "\"It causes strong uterine contractions that push all of the pregnancy tissue out through the cervix.\""}, {"id": "c", "text": "\"It seals the damaged tube so it cannot rupture, and the pregnancy keeps growing there.\""}, {"id": "d", "text": "\"It raises β-hCG levels quickly, which makes the pregnancy detach from the tube wall.\""}]'::jsonb, '["a"]', 'Methotrexate is a folic acid antagonist that stops trophoblast cell division so the ectopic is reabsorbed. Successful treatment is shown by falling, not rising, β-hCG levels.'),
  ('ectopic', 44, 'A client receiving methotrexate for an unruptured ectopic tells the nurse about plans for the next 2 weeks. Which plan should the nurse advise her to change?', '[{"id": "a", "text": "Taking acetaminophen if she has mild cramping"}, {"id": "b", "text": "Spending afternoons sunbathing at the beach"}, {"id": "c", "text": "Returning to the clinic for β-hCG blood tests"}, {"id": "d", "text": "Avoiding wine and other alcoholic drinks"}]'::jsonb, '["b"]', 'Sun exposure is avoided during methotrexate treatment because of photosensitivity. Acetaminophen for pain, β-hCG monitoring, and avoiding alcohol are all appropriate.'),
  ('ectopic', 45, 'A nurse reviews data for four clients at 6 weeks who have pelvic pain. Which client''s findings are MOST suspicious for an ectopic pregnancy?', '[{"id": "a", "text": "β-hCG 2,400 mIU/mL with an intrauterine sac seen on ultrasound"}, {"id": "b", "text": "β-hCG 2,200 mIU/mL with no intrauterine sac seen on ultrasound"}, {"id": "c", "text": "β-hCG that rose from 1,000 to 2,100 mIU/mL in 48 hours"}, {"id": "d", "text": "β-hCG 2,600 mIU/mL with an intrauterine sac and no adnexal mass"}]'::jsonb, '["b"]', 'A β-hCG above 1,500–2,000 mIU/mL with no intrauterine sac on TVUS is highly suspicious for ectopic pregnancy. A visible intrauterine sac or a β-hCG that roughly doubles in 48 hours fits a normal pregnancy.'),
  ('ectopic', 46, 'A client with a tubal pregnancy has BP 84/50, heart rate 130, and severe abdominal pain. She asks, "Can''t I just have the methotrexate shot instead of surgery?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, the shot works well if it is given before your blood pressure drops further.\""}, {"id": "b", "text": "\"Yes, but only if your β-hCG level comes back low on today''s blood test.\""}, {"id": "c", "text": "\"No, the shot is used only for very large ectopics that cannot be removed.\""}, {"id": "d", "text": "\"No, the shot is for stable, unruptured cases; your signs show you need surgery.\""}]'::jsonb, '["d"]', 'Methotrexate is limited to hemodynamically stable, unruptured ectopics; ruptured or unstable clients go straight to surgery. Her hypotension and tachycardia indicate shock, and a low β-hCG would not change that.'),
  ('ectopic', 47, 'A client with a suspected unruptured ectopic has a normal hematocrit and stable vital signs. She says, "My blood count is normal, so I can''t be bleeding inside or rupture." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"A normal count early on doesn''t rule out rupture, so report sudden or shoulder pain.\""}, {"id": "b", "text": "\"That''s right; a normal blood count shows that a rupture cannot happen this time around.\""}, {"id": "c", "text": "\"A normal count means the ectopic will be reabsorbed on its own without treatment.\""}, {"id": "d", "text": "\"A normal count means the pregnancy is in the uterus, so no other testing is needed.\""}]'::jsonb, '["a"]', 'The hematocrit may be normal early and falls with rupture, so a normal value does not rule out later rupture. Sudden pain and shoulder pain must be reported immediately as signs of rupture.'),
  ('ectopic', 48, 'A client at 8 weeks with a known ampullary tubal pregnancy, who is awaiting treatment, calls the clinic. Which reported symptom should the nurse treat as the MOST urgent?', '[{"id": "a", "text": "Mild, dull cramping on the side of the ectopic"}, {"id": "b", "text": "Brownish spotting that is lighter than a period"}, {"id": "c", "text": "Fainting after standing up from the toilet"}, {"id": "d", "text": "A second positive home pregnancy test today"}]'::jsonb, '["c"]', 'Ampullary ectopics rupture at 6–10 weeks, and syncope signals hemorrhage with hypotension. Dull one-sided cramping and light spotting are part of the unruptured triad.'),
  ('ectopic', 49, 'A client with long-standing endometriosis has a positive pregnancy test at 5 weeks. She has no pain or bleeding, and she asks why her provider ordered an early transvaginal ultrasound. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Endometriosis raises β-hCG levels, which can be confirmed only by ultrasound.\""}, {"id": "b", "text": "\"Endometriosis makes miscarriage certain, so the scan plans your treatment.\""}, {"id": "c", "text": "\"Endometriosis means the pregnancy has already ruptured without causing pain.\""}, {"id": "d", "text": "\"Endometriosis can cause adhesions that alter the tubes and raise ectopic risk.\""}]'::jsonb, '["d"]', 'Endometriosis is an ectopic risk factor because adhesions alter tubal anatomy, so early TVUS checks for an intrauterine sac. She has no pain, bleeding, or shock signs suggesting rupture.'),
  ('ectopic', 50, 'A client started methotrexate yesterday for an unruptured 2.0-cm tubal pregnancy. Her β-hCG was 1,100 mIU/mL. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll take acetaminophen instead of ibuprofen if I have cramps.\""}, {"id": "b", "text": "\"I''ll keep my follow-up appointments for β-hCG blood tests.\""}, {"id": "c", "text": "\"I''ll call right away if my pain becomes severe or one-sided.\""}, {"id": "d", "text": "\"I''ll have a glass of wine with dinner to help me unwind.\""}]'::jsonb, '["d"]', 'Alcohol is avoided during methotrexate treatment because it increases the risk of hepatotoxicity. Using acetaminophen instead of NSAIDs, keeping β-hCG follow-up, and reporting severe pain are correct.'),
  ('signs', 1, 'A client 7 weeks after her last menstrual period reports amenorrhea, breast tenderness, and fatigue. On speculum examination, the nurse notes a bluish-purple cervix and vagina. Which finding is the MOST reliable indicator of pregnancy at this visit?', '[{"id": "a", "text": "Absence of menses for the past 7 weeks"}, {"id": "b", "text": "Tender, tingling breasts with darker areolae"}, {"id": "c", "text": "Bluish-purple color of the cervix and vagina"}, {"id": "d", "text": "Fatigue that began during the past several weeks"}]'::jsonb, '["c"]', 'The bluish-purple cervix and vagina (Chadwick''s sign) is a probable sign detected by the examiner. Amenorrhea, breast changes, and fatigue are presumptive signs reported by the woman and are the least certain.'),
  ('signs', 2, 'During a prenatal intake at 12 weeks, the nurse reviews four findings for a client who wants to know whether her pregnancy is confirmed. Which finding is the MOST conclusive evidence of pregnancy?', '[{"id": "a", "text": "Serum beta-hCG reported as positive by the lab"}, {"id": "b", "text": "Fetal heart tones of 148/min heard by Doppler"}, {"id": "c", "text": "Uterus palpable just above the symphysis pubis"}, {"id": "d", "text": "Cervix that feels soft like lips rather than a nose"}]'::jsonb, '["b"]', 'A fetal heartbeat heard by the provider is a positive (definitive) sign and Doppler can detect it at 10-12 weeks. A positive hCG, uterine enlargement, and cervical softening are probable signs that can have other causes.'),
  ('signs', 3, 'A multigravida at 17 weeks tells the nurse, ''I felt the baby flutter last night, so now we know for sure I''m pregnant.'' No other assessments have been done yet today. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, feeling the baby move is a definitive sign of pregnancy."}, {"id": "b", "text": "Feeling movement is a probable sign because it is so distinct."}, {"id": "c", "text": "Movement you feel is reliable only after 20 weeks of pregnancy."}, {"id": "d", "text": "What you feel is a presumptive sign; the provider confirms it."}]'::jsonb, '["d"]', 'Quickening is perceived only by the mother, so it is a presumptive (subjective) sign. Confirmation requires direct fetal evidence obtained by the provider, such as a heartbeat, ultrasound visualization, or provider-felt movement.'),
  ('signs', 4, 'A nursing student charts pregnancy-sign classifications for several clients seen in a prenatal clinic. Which entry should the supervising nurse correct before the client records are finalized?', '[{"id": "a", "text": "Goodell''s sign noted on cervical exam: presumptive sign"}, {"id": "b", "text": "Hegar''s sign present on bimanual exam: probable sign"}, {"id": "c", "text": "Linea nigra noted from navel to pubis: presumptive sign"}, {"id": "d", "text": "Gestational sac seen on transvaginal ultrasound: positive sign"}]'::jsonb, '["a"]', 'Goodell''s sign (softening of the cervix) is detected by the examiner and is a probable sign, not presumptive. Hegar''s sign is probable, linea nigra is presumptive, and ultrasound visualization is positive, so those entries are correct.'),
  ('signs', 5, 'A client with a history of uterine fibroids has a positive serum beta-hCG and an enlarged uterus on exam. No ultrasound or fetal heart tones have been obtained. She asks why the provider says pregnancy is not yet confirmed. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "Both findings are presumptive because they rely on your own report."}, {"id": "b", "text": "A blood test becomes a positive sign once the first trimester ends."}, {"id": "c", "text": "Both are probable signs that can have causes besides pregnancy."}, {"id": "d", "text": "An enlarged uterus is confirmatory when fundal height matches dates."}]'::jsonb, '["c"]', 'A positive hCG and uterine enlargement are probable signs: detected by the provider but not definitive, because tumors can produce hCG and fibroids can enlarge the uterus. Presumptive signs are those reported by the woman.'),
  ('signs', 6, 'A client is 8 weeks pregnant by dates, and the nurse assists the provider with a pelvic examination. Which examiner finding would be premature at this gestational age and should NOT yet be expected?', '[{"id": "a", "text": "Bluish-purple discoloration of the cervix and vulva"}, {"id": "b", "text": "Rebound of the fetus after the cervix is tapped upward"}, {"id": "c", "text": "Cervix that feels soft like lips rather than a nose tip"}, {"id": "d", "text": "Softening of the isthmus just above the cervix"}]'::jsonb, '["b"]', 'Ballottement, in which the fetus floats up and drops back after the cervix is tapped, occurs at 16-20 weeks. Chadwick''s and Goodell''s signs occur around 6-8 weeks and Hegar''s sign at 6-12 weeks, so they may be present at 8 weeks.'),
  ('signs', 7, 'At a 14-week prenatal visit, the nurse cannot hear fetal heart tones using a fetoscope, and the client becomes anxious that something is wrong with the pregnancy. Which action by the nurse is BEST?', '[{"id": "a", "text": "Attempt to auscultate fetal heart tones with a Doppler device"}, {"id": "b", "text": "Explain that no device can detect a heartbeat until 20 weeks"}, {"id": "c", "text": "Reposition the fetoscope lower, since tones are audible by 12 weeks"}, {"id": "d", "text": "Schedule a repeat fetoscope check in 1 week to confirm viability"}]'::jsonb, '["a"]', 'Doppler ultrasound can detect the fetal heartbeat as early as 10-12 weeks, whereas a fetoscope usually detects it around 18-20 weeks. Repeating the fetoscope check at 15 weeks would still be too early.'),
  ('signs', 8, 'A primigravida at 15 weeks'' gestation is worried because her sister, who has three children, said she felt her last baby move at 16 weeks. The client has felt nothing yet. Which response by the nurse is BEST?', '[{"id": "a", "text": "Your sister''s timing applies to you, so movement is overdue."}, {"id": "b", "text": "Lack of movement at 15 weeks means an ultrasound is needed today."}, {"id": "c", "text": "First-time mothers usually notice movement by about 12 weeks."}, {"id": "d", "text": "First-time mothers often notice it around 18–20 weeks."}]'::jsonb, '["d"]', 'A primigravida typically feels quickening at about 18-20 weeks, whereas a multigravida like her sister may feel it around 16 weeks. Absence of quickening at 15 weeks in a first pregnancy is expected.'),
  ('signs', 9, 'At 24 weeks, a client reports feeling the baby kick, and during the abdominal examination the provider also palpates distinct fetal movement. How should the nurse classify these two findings?', '[{"id": "a", "text": "Both are positive signs because the same fetal movement is perceived"}, {"id": "b", "text": "Client''s report is presumptive; the provider''s palpation is positive"}, {"id": "c", "text": "Client''s report is probable; the provider''s palpation is positive"}, {"id": "d", "text": "Both are probable signs because neither is seen on ultrasound"}]'::jsonb, '["b"]', 'Movement felt by the mother (quickening) is subjective and presumptive, while fetal movement objectively palpated by the provider is a positive sign. The same movement is classified differently depending on who detects it.'),
  ('signs', 10, 'A client whose last menstrual period was 5 weeks ago has a transvaginal ultrasound that shows a gestational sac within the uterus. Her urine hCG is also positive. Which statement BEST describes her pregnancy status?', '[{"id": "a", "text": "Pregnancy is probable until fetal heart tones are heard"}, {"id": "b", "text": "Pregnancy is presumptive until quickening is reported"}, {"id": "c", "text": "Pregnancy is confirmed by the ultrasound visualization"}, {"id": "d", "text": "Pregnancy is confirmed by the positive urine hCG result"}]'::jsonb, '["c"]', 'Ultrasound visualization of a gestational sac is direct fetal evidence and a positive sign. A positive hCG is only a probable sign because false positives can occur.'),
  ('signs', 11, 'A client at 7 weeks'' gestation says, ''My nausea comes in the evening, not in the morning, so I doubt it is from the pregnancy.'' She is keeping fluids down. Which response by the nurse is BEST?', '[{"id": "a", "text": "Pregnancy nausea can occur at any time of day as hCG rises."}, {"id": "b", "text": "Evening nausea suggests another cause and needs evaluation."}, {"id": "c", "text": "Pregnancy nausea usually begins after the first trimester."}, {"id": "d", "text": "Nausea becomes a probable sign once it occurs later in the day."}]'::jsonb, '["a"]', 'Nausea of pregnancy is caused by rising beta-hCG and can occur at any time of day despite the name morning sickness. It begins around 4-6 weeks, so it is expected at 7 weeks.'),
  ('signs', 12, 'A client at 37 weeks reports that urinary frequency, which bothered her early in pregnancy and then eased, has returned this week. She has no other complaints. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Frequency late in pregnancy is caused by rising beta-hCG levels"}, {"id": "b", "text": "Frequency returns in the third trimester when the baby drops"}, {"id": "c", "text": "Frequency is caused by rising progesterone in late pregnancy"}, {"id": "d", "text": "Frequency in the third trimester is a probable sign of labor"}]'::jsonb, '["b"]', 'Urinary frequency results from pressure of the uterus on the bladder in the first trimester and returns in the third trimester when the baby drops. Rising hCG is linked to nausea and rising progesterone to fatigue.'),
  ('signs', 13, 'A client who stopped oral contraceptives 2 months ago has darkened patches on her cheeks and forehead and reports amenorrhea. She asks whether the facial changes prove she is pregnant. Which response by the nurse is BEST?', '[{"id": "a", "text": "It is a positive sign because pregnancy hormones cause it."}, {"id": "b", "text": "It is presumptive and can also occur with oral contraceptive use."}, {"id": "c", "text": "It is a probable sign because it is visible to the examiner on exam."}, {"id": "d", "text": "It confirms pregnancy when amenorrhea is also present."}]'::jsonb, '["b"]', 'Chloasma (mask of pregnancy) is a presumptive sign from hormonal pigmentation changes and can also occur with oral contraceptive use. Being visible does not make it probable, and presumptive signs cannot confirm pregnancy even in combination.'),
  ('signs', 14, 'A client at 18 weeks has these findings: (1) breast tingling she reports, (2) softening of the lower uterine segment on bimanual exam, (3) fetal heart tones of 152/min by Doppler. In which order should the nurse rank them from LEAST to MOST certain evidence of pregnancy?', '[{"id": "a", "text": "1, 2, 3"}, {"id": "b", "text": "2, 1, 3"}, {"id": "c", "text": "1, 3, 2"}, {"id": "d", "text": "3, 2, 1"}]'::jsonb, '["a"]', 'Breast tingling is presumptive (least certain), Hegar''s sign is probable (examiner-detected but could have another cause), and a fetal heartbeat heard by the provider is positive (definitive).'),
  ('signs', 15, 'A client has amenorrhea, a markedly positive serum beta-hCG, and an enlarged uterus, but no fetus is seen on ultrasound. The provider suspects gestational trophoblastic disease. Which statement BEST explains why her hCG result was never considered confirmation of pregnancy?', '[{"id": "a", "text": "hCG is a presumptive sign because the woman reports the result"}, {"id": "b", "text": "hCG becomes a positive sign once the uterus is enlarged"}, {"id": "c", "text": "Certain tumors produce hCG, so the test is a probable sign"}, {"id": "d", "text": "hCG confirms pregnancy once fundal height matches the dates"}]'::jsonb, '["c"]', 'A positive hCG test is classified as probable because false positives occur with tumors such as gestational trophoblastic disease and choriocarcinoma. Uterine enlargement is also probable, so combining them still does not confirm pregnancy.'),
  ('signs', 16, 'The nurse reviews the charts of four clients scheduled in the prenatal clinic today. Which client''s documented findings provide definitive confirmation of her pregnancy?', '[{"id": "a", "text": "A client at 6 weeks with a positive serum hCG and a bluish cervix"}, {"id": "b", "text": "A client at 18 weeks reporting quickening and a dark linea nigra"}, {"id": "c", "text": "A client at 17 weeks with fetal rebound on vaginal examination"}, {"id": "d", "text": "A client at 20 weeks whose fetal heart is heard by fetoscope"}]'::jsonb, '["d"]', 'A fetal heartbeat heard by the provider, detectable by fetoscope around 18-20 weeks, is a positive sign. Positive hCG, Chadwick''s sign, and ballottement are probable; quickening and linea nigra are presumptive.'),
  ('signs', 17, 'A client presents 6 weeks after the first day of her last menstrual period for her first prenatal examination. Which examiner-detected finding is MOST likely to be present this early in pregnancy?', '[{"id": "a", "text": "Uterus palpable above the symphysis pubis"}, {"id": "b", "text": "Bluish-purple discoloration of the cervix"}, {"id": "c", "text": "Fetus rebounding when the cervix is tapped"}, {"id": "d", "text": "Fetal heart tones heard with a fetoscope"}]'::jsonb, '["b"]', 'Chadwick''s sign is one of the earliest probable signs, occurring at 6-8 weeks. The uterus becomes palpable above the symphysis by about 12 weeks, ballottement occurs at 16-20 weeks, and a fetoscope detects heart tones around 18-20 weeks.'),
  ('signs', 18, 'A client whose last menstrual period began 5 weeks ago has a positive home test and wants her pregnancy confirmed at today''s visit. Which assessment is MOST likely to provide definitive confirmation this early?', '[{"id": "a", "text": "Transvaginal ultrasound for a gestational sac"}, {"id": "b", "text": "Doppler auscultation of the fetal heart tones"}, {"id": "c", "text": "Bimanual exam for softening of the isthmus"}, {"id": "d", "text": "Serum beta-hCG level drawn and reported today"}]'::jsonb, '["a"]', 'Transvaginal ultrasound can visualize the gestational sac as early as 4.5-5 weeks, which is a positive sign. Doppler detects heart tones at 10-12 weeks, and Hegar''s sign and serum hCG are only probable signs.'),
  ('signs', 19, 'During a bimanual examination of a client at 9 weeks, the provider notes that the lower uterine segment just above the cervix is markedly soft and compressible. How should the nurse document this finding?', '[{"id": "a", "text": "Goodell''s sign, a probable sign of pregnancy"}, {"id": "b", "text": "Hegar''s sign, a positive sign of pregnancy"}, {"id": "c", "text": "Hegar''s sign, a probable sign of pregnancy"}, {"id": "d", "text": "Goodell''s sign, a presumptive sign of pregnancy"}]'::jsonb, '["c"]', 'Softening of the lower uterine segment (isthmus) on bimanual exam is Hegar''s sign, a probable sign occurring at 6-12 weeks. Goodell''s sign is softening of the cervix itself.'),
  ('signs', 20, 'On pelvic examination at 7 weeks, the examiner notes that the client''s cervix, which normally feels firm like the tip of the nose, now feels soft like the lips. The client asks whether this means her pregnancy is certain. Which response is BEST?', '[{"id": "a", "text": "Yes, cervical softening is a positive sign of a pregnancy."}, {"id": "b", "text": "No, cervical softening is a presumptive sign you report."}, {"id": "c", "text": "Yes, softening plus a missed period confirms pregnancy."}, {"id": "d", "text": "No, it is a probable sign that could have another cause."}]'::jsonb, '["d"]', 'Goodell''s sign is an examiner-detected probable sign; it is not definitive because another cause is possible. Adding a presumptive sign such as a missed period does not convert it into confirmation.'),
  ('signs', 21, 'A client at 12 weeks by dates has a uterus palpable just above the symphysis pubis. She has a known history of uterine fibroids. Which conclusion by the nurse about this finding is MOST accurate?', '[{"id": "a", "text": "Uterine enlargement at 12 weeks is a positive sign of pregnancy."}, {"id": "b", "text": "The finding is probable; fibroids can also enlarge the uterus."}, {"id": "c", "text": "The finding is presumptive because only the client can perceive it."}, {"id": "d", "text": "The finding is premature; the uterus is not palpable until 20 weeks."}]'::jsonb, '["b"]', 'A uterus palpable above the symphysis pubis by about 12 weeks is a probable sign; it is examiner-detected but can also occur with fibroids, so it is not definitive.'),
  ('signs', 22, 'A client with a positive home pregnancy test about 2 weeks after conception is taught about pregnancy signs. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "My positive test means the pregnancy is definitely confirmed."}, {"id": "b", "text": "My missed period and my tiredness can have other causes too."}, {"id": "c", "text": "Hearing the baby''s heartbeat would confirm the pregnancy."}, {"id": "d", "text": "Some tumors can make a pregnancy test read positive."}]'::jsonb, '["a"]', 'A pregnancy test is a probable sign, not a positive sign, because tumors also produce hCG. The other statements are accurate: presumptive signs have other causes and a provider-heard heartbeat is definitive.'),
  ('signs', 23, 'At 6 weeks, a client reports breast fullness and tingling, and the nurse observes enlarged Montgomery''s tubercles and darkened areolae. How should the nurse classify these breast changes?', '[{"id": "a", "text": "Probable, because the nurse can observe the changes"}, {"id": "b", "text": "Positive, because fetal hormones directly cause them"}, {"id": "c", "text": "Presumptive, because other conditions can cause them"}, {"id": "d", "text": "Probable, because they rarely begin before 12 weeks of pregnancy"}]'::jsonb, '["c"]', 'Breast changes, including enlarged Montgomery''s tubercles and darkened areolae, are presumptive signs that begin very early. Presumptive signs are the least certain because other conditions can cause them, even when the nurse can see them.'),
  ('signs', 24, 'A client at 22 weeks asks the nurse about a dark line running from her navel to her pubic bone and new stretch marks on her abdomen. She worries these mean something is wrong. Which explanation is MOST accurate?', '[{"id": "a", "text": "They are probable signs because the examiner can see them."}, {"id": "b", "text": "They are positive signs caused by the growing fetus."}, {"id": "c", "text": "They suggest a hormonal disorder that needs evaluation."}, {"id": "d", "text": "They are presumptive signs from hormonal pigment changes."}]'::jsonb, '["d"]', 'Linea nigra and striae are presumptive signs that result from hormonal pigmentation changes of pregnancy. Visibility to the examiner does not make them probable.'),
  ('signs', 25, 'A client at 9 weeks'' gestation says she is exhausted, naps daily, and is struggling at work. She asks whether something is wrong with her pregnancy. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "Extreme fatigue this early is a probable sign of anemia."}, {"id": "b", "text": "Rising progesterone and metabolic demands commonly cause this."}, {"id": "c", "text": "Fatigue this early comes from pressure of the uterus on organs."}, {"id": "d", "text": "Rising beta-hCG is the main cause of first-trimester fatigue."}]'::jsonb, '["b"]', 'Extreme tiredness in the first trimester is a presumptive sign caused by rising progesterone and metabolic demands. Rising beta-hCG is linked to nausea, and uterine pressure causes urinary frequency.'),
  ('signs', 26, 'A college athlete in the middle of final exams has had no menstrual period for 6 weeks and feels tired. She tells the nurse she is certain she is pregnant. Which response by the nurse is BEST?', '[{"id": "a", "text": "A missed period suggests pregnancy, but stress can also cause it."}, {"id": "b", "text": "A missed period together with fatigue is a probable sign of pregnancy."}, {"id": "c", "text": "A missed period lasting 6 weeks is a positive sign of pregnancy."}, {"id": "d", "text": "A missed period is unrelated to pregnancy when stress is present."}]'::jsonb, '["a"]', 'Amenorrhea is a presumptive sign: often the first sign noticed, but it can also be caused by stress, illness, or hormonal disorders. Presumptive signs cannot confirm pregnancy, alone or together.'),
  ('signs', 27, 'During an 18-week vaginal exam, the examiner taps the cervix upward and feels the fetus float away and drop back. A nursing student says this confirms pregnancy because the fetus itself was felt. Which response by the nurse is BEST?', '[{"id": "a", "text": "Correct; feeling the fetus rebound is a positive sign."}, {"id": "b", "text": "Correct; fetal rebound becomes definitive after 16 weeks."}, {"id": "c", "text": "This is ballottement, a probable rather than positive sign."}, {"id": "d", "text": "This is quickening, a presumptive sign that the client reports."}]'::jsonb, '["c"]', 'Ballottement, the fetal rebound after the cervix is tapped upward, is a probable sign assessed at 16-20 weeks. Positive signs are a provider-heard heartbeat, ultrasound visualization, or provider-palpated fetal movement on abdominal exam.'),
  ('signs', 28, 'A primigravida at 20 weeks has these findings recorded: she reports fluttering movements, the fundus is at the expected level, the provider palpates fetal movement on abdominal exam, and her urine hCG is positive. Which finding is the positive sign?', '[{"id": "a", "text": "Fluttering movements reported by the client"}, {"id": "b", "text": "Fundus palpated at the expected level"}, {"id": "c", "text": "Urine hCG test that remains positive"}, {"id": "d", "text": "Fetal movement palpated by the provider"}]'::jsonb, '["d"]', 'Fetal movement objectively palpated by the provider on abdominal exam is a positive sign. Quickening is presumptive, while uterine enlargement and a positive hCG are probable signs.'),
  ('signs', 29, 'A multigravida at 16 weeks is surprised that she already feels ''bubbling'' movements, since in her first pregnancy she felt nothing until 19 weeks. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "Feeling movement at 16 weeks suggests her dates are wrong."}, {"id": "b", "text": "Women who were pregnant before often recognize it earlier."}, {"id": "c", "text": "Movement this early is ballottement rather than quickening."}, {"id": "d", "text": "Earlier movement means this fetus is larger than her first."}]'::jsonb, '["b"]', 'A multigravida may feel quickening earlier, around 16 weeks, because she recognizes the sensation; a primigravida usually feels it at 18-20 weeks. Ballottement is an examiner finding, not something the mother feels.'),
  ('signs', 30, 'A client at 13 weeks says her nausea, which began at about 5 weeks, has nearly stopped. She fears that something has gone wrong with the pregnancy. Which response by the nurse is BEST?', '[{"id": "a", "text": "Loss of nausea at 13 weeks means an ultrasound is needed today."}, {"id": "b", "text": "Nausea usually continues until the third trimester begins."}, {"id": "c", "text": "Nausea often resolves by the end of the first trimester."}, {"id": "d", "text": "Nausea ending early shows hCG levels are falling abnormally."}]'::jsonb, '["c"]', 'Nausea and vomiting of pregnancy begins around 4-6 weeks and often resolves by the end of the first trimester, so its fading at 13 weeks is expected.'),
  ('signs', 31, 'At 12 weeks, the nurse hears fetal heart tones at 148/min by Doppler. The client''s partner asks why this finding matters more than her positive pregnancy test. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "Only a live fetus has a heartbeat, so no other cause is possible."}, {"id": "b", "text": "A heartbeat can be heard earlier than a pregnancy test turns positive."}, {"id": "c", "text": "A rate in the normal range is the feature that proves pregnancy."}, {"id": "d", "text": "A heartbeat confirms pregnancy only after quickening is reported."}]'::jsonb, '["a"]', 'A fetal heartbeat heard by the provider is positive because only a live fetus has a heartbeat, while a pregnancy test can be falsely positive. hCG is detectable about 1-2 weeks after conception, well before Doppler tones at 10-12 weeks.'),
  ('signs', 32, 'A client at 8 weeks asks when she can expect different pregnancy findings to be detected over the coming months. Which statement by the nurse is MOST accurate?', '[{"id": "a", "text": "Ballottement can usually be checked by about 8 to 10 weeks of pregnancy."}, {"id": "b", "text": "The heartbeat can be heard by fetoscope at 10 to 12 weeks."}, {"id": "c", "text": "You will probably feel the baby move by about 12 to 14 weeks."}, {"id": "d", "text": "A Doppler may detect the heartbeat as early as 10 to 12 weeks."}]'::jsonb, '["d"]', 'Doppler can detect the fetal heartbeat as early as 10-12 weeks. Ballottement occurs at 16-20 weeks, the fetoscope detects heart tones around 18-20 weeks, and quickening is felt at about 16-20 weeks.'),
  ('signs', 33, 'A client at 7 weeks reports urinary frequency, and on exam the examiner finds that her cervix feels soft like the lips. The client asks why the nurse says one finding ''counts more'' than the other. Which explanation is BEST?', '[{"id": "a", "text": "Frequency counts more because it occurs earlier in the pregnancy."}, {"id": "b", "text": "The soft cervix is examiner-found; frequency is self-reported."}, {"id": "c", "text": "The soft cervix is a positive sign of fetal circulation."}, {"id": "d", "text": "Frequency is probable because uterine pressure causes it."}]'::jsonb, '["b"]', 'Goodell''s sign is detected by the examiner and is probable, while urinary frequency is reported by the woman and is presumptive (least certain). Neither is a positive sign.'),
  ('signs', 34, 'A client 6 weeks after her last menstrual period reports urinary frequency and believes it proves she is pregnant. She also mentions burning when she voids. Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "Frequency is a probable sign, so pregnancy is likely."}, {"id": "b", "text": "Frequency confirms the pregnancy once the period is late."}, {"id": "c", "text": "Frequency is presumptive and can also come from a UTI."}, {"id": "d", "text": "Frequency this early is unrelated to the pregnancy."}]'::jsonb, '["c"]', 'Urinary frequency is a subjective presumptive sign that can be caused by conditions other than pregnancy, such as a UTI. In pregnancy it occurs in the first trimester from uterine pressure, so it is not unrelated at 6 weeks.'),
  ('signs', 35, 'Four clients at a prenatal clinic make statements about their pregnancy signs. Which client''s statement indicates the nurse''s teaching has NOT been understood and needs reinforcement first?', '[{"id": "a", "text": "At 9 weeks: ''Being this tired proves I''m pregnant for sure.''"}, {"id": "b", "text": "At 14 weeks: ''My stretch marks come from hormone changes.''"}, {"id": "c", "text": "At 18 weeks: ''The fluttering I feel is called quickening.''"}, {"id": "d", "text": "At 6 weeks: ''My sore breasts started very early on.''"}]'::jsonb, '["a"]', 'Fatigue is a presumptive sign and cannot confirm pregnancy. The other statements are accurate: striae come from hormonal pigmentation changes, quickening is the fluttering felt by the mother, and breast changes begin very early.'),
  ('signs', 36, 'A client in early pregnancy asks which findings her provider can use to diagnose pregnancy with certainty, because she has read conflicting information online. Which list should the nurse BEST include?', '[{"id": "a", "text": "Positive blood test, softened cervix, and bluish cervix"}, {"id": "b", "text": "Missed period, morning sickness, and breast tenderness"}, {"id": "c", "text": "Enlarged uterus, fetal rebound, and positive urine test"}, {"id": "d", "text": "Heartbeat heard, fetus seen on ultrasound, movement felt by provider"}]'::jsonb, '["d"]', 'Only direct fetal evidence (heartbeat heard by the provider, ultrasound visualization, provider-felt movement) is definitive. Lab tests and cervical or uterine changes are probable signs, and symptoms the woman reports are presumptive.'),
  ('signs', 37, 'A client at 16 weeks has four findings documented in her chart. Three of them belong to the same category of pregnancy signs. Which finding belongs to a DIFFERENT category than the others?', '[{"id": "a", "text": "Chloasma across the cheeks and forehead"}, {"id": "b", "text": "Linea nigra from the navel to the pubis"}, {"id": "c", "text": "Uterus palpable above the symphysis pubis"}, {"id": "d", "text": "Reported fluttering movements in the abdomen"}]'::jsonb, '["c"]', 'Uterine enlargement is a probable sign detected by the examiner. Chloasma, linea nigra, and quickening are all presumptive signs.'),
  ('signs', 38, 'A client at 19 weeks has fetal heart tones of 144/min heard by the nurse with a fetoscope during a routine visit. Which interpretation of this finding by the nurse is MOST accurate?', '[{"id": "a", "text": "Positive sign; the rate is within the expected range"}, {"id": "b", "text": "Probable sign; fetoscope tones need ultrasound proof"}, {"id": "c", "text": "Positive sign; the rate is above the expected range"}, {"id": "d", "text": "Presumptive sign; the client can also hear the tones"}]'::jsonb, '["a"]', 'A fetal heartbeat heard by the provider is a positive sign, and the fetoscope detects it around 18-20 weeks. The normal fetal heart rate is 110-160 bpm, so 144/min is within range.'),
  ('signs', 39, 'A client at 18 weeks reports feeling ''fluttering'' in her abdomen several times a day. The nurse places a hand on the abdomen during the visit and feels nothing. Which interpretation by the nurse is BEST?', '[{"id": "a", "text": "The client''s report is probable and should be rechecked by ultrasound."}, {"id": "b", "text": "The flutters are likely imagined because the examiner could not feel them."}, {"id": "c", "text": "The flutters become a positive sign once the client reports them daily."}, {"id": "d", "text": "The client''s report is presumptive and cannot be confirmed by exam."}]'::jsonb, '["d"]', 'Quickening is a presumptive sign perceived only by the mother, and presumptive signs cannot be confirmed by exam. It is not dismissed as imagined, and repeated reporting does not make it a positive sign.'),
  ('signs', 40, 'Over several visits, a client''s chart accumulates the following groups of findings. Which group, by itself, is sufficient for the provider to confirm the pregnancy?', '[{"id": "a", "text": "Positive hCG, Hegar''s sign, and Goodell''s sign"}, {"id": "b", "text": "Amenorrhea, quickening, and urinary frequency"}, {"id": "c", "text": "Ballottement, Chadwick''s sign, and an enlarged uterus"}, {"id": "d", "text": "Fetal heartbeat by Doppler at a 12-week visit"}]'::jsonb, '["d"]', 'A fetal heartbeat heard by the provider is a positive sign and confirms pregnancy on its own. Groups of probable or presumptive signs, however many, still could have another cause.'),
  ('signs', 41, 'The nurse reviews four prenatal charts. Which documented finding is inconsistent with the client''s gestational age and requires follow-up with the client?', '[{"id": "a", "text": "8 weeks: bluish-purple discoloration of the cervix"}, {"id": "b", "text": "11 weeks: fetal heart tones heard by Doppler"}, {"id": "c", "text": "10 weeks: client reports feeling fetal movement"}, {"id": "d", "text": "5 weeks: gestational sac seen on transvaginal ultrasound"}]'::jsonb, '["c"]', 'Quickening is felt at about 16-20 weeks, so a report at 10 weeks does not fit the gestational age. Chadwick''s sign occurs at 6-8 weeks, Doppler tones at 10-12 weeks, and a transvaginal gestational sac at 4.5-5 weeks.'),
  ('signs', 42, 'A sexually active client whose last menstrual period began 4 weeks ago asks which pregnancy sign she would most likely notice first. Which sign should the nurse identify as typically FIRST?', '[{"id": "a", "text": "Absence of her expected menstrual period"}, {"id": "b", "text": "Urinary frequency from uterine pressure"}, {"id": "c", "text": "Darkened patches on the face and cheeks"}, {"id": "d", "text": "Stretch marks on the abdomen and breasts"}]'::jsonb, '["a"]', 'Amenorrhea, at about week 4, is often the first sign a woman notices. Urinary frequency, chloasma, and striae are also presumptive signs but are not typically the first noticed.'),
  ('signs', 43, 'An ultrasound at 11 weeks shows an embryo in the uterus. The client''s partner says, ''We still need to hear the heartbeat before we can be sure she is pregnant.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "You are right; a heartbeat is the single definitive sign."}, {"id": "b", "text": "Seeing the embryo on ultrasound already confirms pregnancy."}, {"id": "c", "text": "You are right; ultrasound is probable until tones are heard."}, {"id": "d", "text": "The heartbeat cannot be detected until about 18 to 20 weeks."}]'::jsonb, '["b"]', 'Ultrasound visualization of the gestational sac, embryo, or fetus is a positive sign by itself. Doppler can detect the heartbeat at 10-12 weeks; 18-20 weeks applies to the fetoscope.'),
  ('signs', 44, 'At 20 weeks, the examiner feels the fetus rebound after tapping the cervix upward on vaginal exam, and later palpates a fetal kick on abdominal exam. Which classification of these two findings is correct?', '[{"id": "a", "text": "Both are positive because the examiner felt the fetus"}, {"id": "b", "text": "Rebound is positive; the palpated kick is probable"}, {"id": "c", "text": "Rebound is probable; the palpated kick is positive"}, {"id": "d", "text": "Both are probable because neither is seen on ultrasound"}]'::jsonb, '["c"]', 'Ballottement is a probable sign, while fetal movement palpated by the examiner on abdominal exam is a positive sign. Feeling the fetus during ballottement does not make it definitive.'),
  ('signs', 45, 'During history-taking, four clients describe findings from their recent visits. Which client is describing a probable sign of pregnancy?', '[{"id": "a", "text": "My provider said my uterus can now be felt above my pubic bone."}, {"id": "b", "text": "I have felt little flutters low in my belly this past week."}, {"id": "c", "text": "I have a dark line running down from my belly button."}, {"id": "d", "text": "My breasts tingle and the areolas have gotten darker."}]'::jsonb, '["a"]', 'A uterus palpable above the symphysis pubis is a probable sign detected by the examiner. Quickening, linea nigra, and breast changes are presumptive signs.'),
  ('signs', 46, 'At a 9-week visit, the nurse attempts Doppler auscultation but cannot locate fetal heart tones. A transvaginal ultrasound last week showed an embryo. Which interpretation by the nurse is BEST?', '[{"id": "a", "text": "The earlier ultrasound was likely wrong and should be repeated."}, {"id": "b", "text": "A fetoscope should be used now because it detects tones earlier."}, {"id": "c", "text": "Absent tones change the pregnancy from confirmed to probable."}, {"id": "d", "text": "Doppler tones may not be detectable until about 10 to 12 weeks."}]'::jsonb, '["d"]', 'Doppler detects the fetal heartbeat as early as 10-12 weeks, so absent tones at 9 weeks are not unexpected. The fetoscope detects tones later (18-20 weeks), and the prior ultrasound visualization was already a positive sign.'),
  ('signs', 47, 'A provider performs a bimanual examination on a client at 10 weeks'' gestation. Which examiner-detected finding is the nurse MOST likely to see documented at this visit?', '[{"id": "a", "text": "Fetus rebounding after the cervix is tapped"}, {"id": "b", "text": "Softening of the isthmus above the cervix"}, {"id": "c", "text": "Fetal heart tones heard through a fetoscope"}, {"id": "d", "text": "Fluttering movements felt by the client"}]'::jsonb, '["b"]', 'Hegar''s sign, softening of the isthmus detected on bimanual exam, occurs at 6-12 weeks. Ballottement occurs at 16-20 weeks, fetoscope tones around 18-20 weeks, and quickening is felt by the mother (not the examiner) at about 16-20 weeks.'),
  ('signs', 48, 'At 8 weeks, a client has a bluish-purple vulva noted on exam and darkened patches on her face that she noticed herself. Which statement BEST contrasts these two findings?', '[{"id": "a", "text": "Both are presumptive signs caused by hormonal pigmentation"}, {"id": "b", "text": "Both are probable signs caused by vascular congestion"}, {"id": "c", "text": "Vulvar color is probable; facial darkening is presumptive"}, {"id": "d", "text": "Vulvar color is presumptive; facial darkening is probable"}]'::jsonb, '["c"]', 'Chadwick''s sign is a probable sign from increased vascular congestion, while chloasma is a presumptive sign from hormonal pigmentation changes.'),
  ('signs', 49, 'A client at 8 weeks complains of both daily nausea and profound exhaustion. She asks whether one hormone is responsible for both symptoms. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Both symptoms come from rising beta-hCG levels"}, {"id": "b", "text": "Both symptoms come from rising progesterone levels"}, {"id": "c", "text": "Nausea is from progesterone; fatigue is from beta-hCG"}, {"id": "d", "text": "Nausea is from beta-hCG; fatigue is from progesterone"}]'::jsonb, '["d"]', 'Nausea and vomiting of pregnancy is caused by rising beta-hCG, while first-trimester fatigue is due to rising progesterone and metabolic demands.'),
  ('signs', 50, 'A client who conceived about 3 weeks ago reports breast tingling and fullness. She asks whether it is too early for these changes to be related to a pregnancy. Which response by the nurse is BEST?', '[{"id": "a", "text": "Breast changes often begin very early in pregnancy."}, {"id": "b", "text": "Breast changes usually begin in the second trimester."}, {"id": "c", "text": "Breast tingling this early is a probable sign."}, {"id": "d", "text": "Breast changes begin after quickening is felt."}]'::jsonb, '["a"]', 'Breast tenderness, tingling, and fullness are presumptive signs that begin very early in pregnancy. As presumptive signs reported by the woman, they are not probable signs.'),
  ('hyperemesis', 1, 'A primigravida at 9 weeks reports nausea every morning and vomiting 2–3 times before noon, but she eats lunch and dinner without vomiting. Her weight is unchanged from before pregnancy, and her urine is negative for ketones. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "These findings fit normal morning sickness, managed with diet and lifestyle changes"}, {"id": "b", "text": "These findings fit hyperemesis gravidarum, which requires IV fluids and admission"}, {"id": "c", "text": "These findings suggest Wernicke''s encephalopathy from early thiamine deficiency"}, {"id": "d", "text": "These findings suggest a molar pregnancy, because vomiting began in the first trimester"}]'::jsonb, '["a"]', 'Normal morning sickness occurs in the first trimester, the client keeps some food down, has no significant weight loss, and has no ketonuria. HG is distinguished by ketonuria, dehydration, electrolyte imbalance, and weight loss of 5% or more.'),
  ('hyperemesis', 2, 'A client at 10 weeks has vomited multiple times daily for 6 days and cannot keep fluids down. Her pre-pregnancy weight was 62 kg; today she weighs 58.5 kg. Urine ketones are 2+. Which conclusion by the nurse is MOST accurate?', '[{"id": "a", "text": "Normal morning sickness, because vomiting before 12–14 weeks is expected"}, {"id": "b", "text": "Hyperemesis gravidarum, because she has ketonuria and has lost over 5% of her weight"}, {"id": "c", "text": "Normal morning sickness, because her weight loss has not yet reached 10 percent of her weight"}, {"id": "d", "text": "Hyperemesis gravidarum, because her nausea is occurring during the first trimester"}]'::jsonb, '["b"]', 'A 3.5-kg loss from 62 kg is about 5.6%, meeting the ≥5% criterion, and ketonuria plus inability to keep fluids down point to HG. First-trimester nausea alone also occurs with normal morning sickness, so it does not distinguish HG.'),
  ('hyperemesis', 3, 'A client at 8 weeks reports daily nausea and vomiting but tolerates small meals and fluids most of the day. Pre-pregnancy weight was 60 kg; she now weighs 57.4 kg. Urine is negative for ketones, and electrolytes are normal. Which statement by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Your weight loss meets the hyperemesis criterion, so you will need IV fluids today.\""}, {"id": "b", "text": "\"Your weight loss is under 5%, and these findings fit morning sickness managed by diet.\""}, {"id": "c", "text": "\"Your negative ketones show that you are dehydrated, so you need hospital admission today.\""}, {"id": "d", "text": "\"Your normal electrolytes mean thiamine must be given before you eat any oral food.\""}]'::jsonb, '["b"]', 'A 2.6-kg loss from 60 kg is about 4.3%, below the ≥5% HG criterion, and she has no ketonuria or electrolyte disturbance while keeping food down. These findings fit normal morning sickness, which is managed with diet and lifestyle changes.'),
  ('hyperemesis', 4, 'A client at 11 weeks is admitted after 10 days of vomiting. She has dry mucous membranes, poor skin turgor, urine specific gravity of 1.032, 3+ urine ketones, and a low potassium level. Which nursing priority should the nurse address FIRST?', '[{"id": "a", "text": "Advancing her diet to crackers and small bland meals"}, {"id": "b", "text": "Restoring fluid and electrolyte balance with IV therapy"}, {"id": "c", "text": "Arranging a fetal growth scan to check fetal nutrition"}, {"id": "d", "text": "Providing a quiet, dim, odor-free room with few visitors"}]'::jsonb, '["b"]', 'Fluid and electrolyte balance is the first nursing priority in HG, and her findings show dehydration and hypokalemia. Nutrition, fetal monitoring, and environmental measures follow in priority.'),
  ('hyperemesis', 5, 'A malnourished client with HG who has vomited for 4 weeks and lost 9% of her body weight has new prescriptions for IV thiamine and an IV dextrose-containing solution. Which administration plan is correct?', '[{"id": "a", "text": "Start the dextrose solution first, then give the thiamine once she can eat again"}, {"id": "b", "text": "Give the IV thiamine first, then start the dextrose-containing solution"}, {"id": "c", "text": "Start the dextrose solution, adding thiamine if confusion develops"}, {"id": "d", "text": "Mix the thiamine into the dextrose bag and infuse both together"}]'::jsonb, '["b"]', 'In malnourished pregnant clients with prolonged vomiting, IV thiamine is given before IV glucose to prevent Wernicke''s encephalopathy. Waiting for confusion means waiting for the complication the sequence is meant to prevent.'),
  ('hyperemesis', 6, 'A client hospitalized for 3 weeks with prolonged HG and poor intake becomes newly confused, walks with an unsteady gait, and has jerky eye movements. Her sodium and potassium were normal this morning. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Notify the provider immediately of suspected Wernicke''s encephalopathy"}, {"id": "b", "text": "Give a dextrose bolus first, then report the findings at the next rounds"}, {"id": "c", "text": "Recheck the potassium level, because hypokalemia explains these findings"}, {"id": "d", "text": "Reassure her that confusion is expected with HG and reassess in 4 hours"}]'::jsonb, '["a"]', 'Confusion, nystagmus, and ataxia after prolonged HG suggest thiamine deficiency causing Wernicke''s encephalopathy, an emergency. Giving dextrose before thiamine is the error that precipitates it, and normal electrolytes make hypokalemia unlikely.'),
  ('hyperemesis', 7, 'A client with HG who has vomited 6–8 times a day for a week reports generalized muscle weakness, and the nurse notes an irregular apical pulse. Which laboratory result should the nurse check FIRST?', '[{"id": "a", "text": "Serum potassium"}, {"id": "b", "text": "Serum hematocrit"}, {"id": "c", "text": "Urine ketones"}, {"id": "d", "text": "Liver enzymes"}]'::jsonb, '["a"]', 'Hypokalemia from vomiting causes muscle weakness and cardiac dysrhythmias, matching her findings. Hematocrit and ketones reflect dehydration and nutrition, and elevated liver enzymes occur in severe prolonged cases but do not explain these signs.'),
  ('hyperemesis', 8, 'A client admitted with HG is receiving IV fluids, and her intake and output are being recorded. The nurse is choosing how to judge whether her fluid status is improving. Which assessment provides the BEST objective measure?', '[{"id": "a", "text": "Daily weight on the same scale"}, {"id": "b", "text": "Skin turgor over the inner forearm"}, {"id": "c", "text": "Moistness of the oral mucosa"}, {"id": "d", "text": "Her own rating of her thirst"}]'::jsonb, '["a"]', 'Daily weight is the best objective measure of fluid balance in HG. Skin turgor and mucous membranes are useful dehydration signs but are less objective, and thirst is a subjective report.'),
  ('hyperemesis', 9, 'A client at 9 weeks who has vomited most meals for 5 days has a urine dipstick showing 3+ ketones. She asks what the result means. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Your body is breaking down fat for energy because you aren''t getting enough food.\""}, {"id": "b", "text": "\"Your kidneys are holding on to extra fluid, which means you are overhydrated right now.\""}, {"id": "c", "text": "\"Ketones are a normal pregnancy finding that shows the baby is growing well.\""}, {"id": "d", "text": "\"Ketones mean you have a urinary infection that needs antibiotic treatment.\""}]'::jsonb, '["a"]', 'Ketonuria in HG reflects the body catabolizing fat and indicates inadequate nutrition. It accompanies dehydration, not overhydration, and it is absent in normal morning sickness.'),
  ('hyperemesis', 10, 'A client at 9 weeks with severe, persistent vomiting and 2+ ketones has a serum β-hCG level much higher than expected for her gestational age. Which follow-up should the nurse anticipate as MOST important?', '[{"id": "a", "text": "Ultrasound to evaluate for molar pregnancy or multiple gestation"}, {"id": "b", "text": "Thyroid testing, since a high β-hCG causes lasting hypothyroidism"}, {"id": "c", "text": "Urine culture, since a UTI explains the elevated β-hCG level"}, {"id": "d", "text": "Liver studies, since a high β-hCG reflects acute liver damage"}]'::jsonb, '["a"]', 'HG is associated with high β-hCG, seen with twins and molar pregnancy, so molar pregnancy must be ruled out. β-hCG''s TSH-like action causes transient hyperthyroidism, not hypothyroidism.'),
  ('hyperemesis', 11, 'A nurse is reviewing the histories of four clients, each at 7 weeks'' gestation. Which client is at HIGHEST risk for developing hyperemesis gravidarum?', '[{"id": "a", "text": "A G3P2 with a singleton pregnancy whose prior pregnancies had no nausea"}, {"id": "b", "text": "A G2P1 with twins who had hyperemesis gravidarum in her last pregnancy"}, {"id": "c", "text": "A G2P1 whose first pregnancy had mild nausea that resolved by 12 weeks"}, {"id": "d", "text": "A G4P3 with a singleton pregnancy and no history of motion sickness"}]'::jsonb, '["b"]', 'Multiple gestation raises β-hCG, and a history of HG in a prior pregnancy is a strong predictor of recurrence. Mild nausea resolving by 12 weeks describes normal morning sickness, not HG.'),
  ('hyperemesis', 12, 'A client at 7 weeks with nausea is being assessed for her risk of progressing to hyperemesis gravidarum. Which finding from her history should the nurse identify as a risk factor?', '[{"id": "a", "text": "Two previous pregnancies without significant nausea"}, {"id": "b", "text": "A singleton pregnancy confirmed on early ultrasound"}, {"id": "c", "text": "A lifelong history of motion sickness in cars and boats"}, {"id": "d", "text": "A male fetus identified on early prenatal screening"}]'::jsonb, '["c"]', 'Personal or family history of motion sickness (vestibular sensitivity) is a listed HG risk factor. Multiple gestation, a female fetus, and first pregnancy are risk factors, so a singleton, a male fetus, and prior uncomplicated pregnancies are not.'),
  ('hyperemesis', 13, 'A client admitted with HG has vomited repeatedly for 8 days and has 3+ urine ketones. Which acid–base imbalance should the nurse expect her arterial blood gas to show?', '[{"id": "a", "text": "Metabolic acidosis from ketone production"}, {"id": "b", "text": "Metabolic alkalosis from loss of stomach acid"}, {"id": "c", "text": "Respiratory acidosis from shallow breathing"}, {"id": "d", "text": "Respiratory alkalosis from anxiety and pain"}]'::jsonb, '["b"]', 'Vomiting removes HCl, producing metabolic alkalosis in HG. Ketonuria reflects fat catabolism from inadequate nutrition but the expected acid–base finding is alkalosis.'),
  ('hyperemesis', 14, 'A client admitted with HG after 9 days of vomiting has a hematocrit above the normal range. She asks whether she has "too much blood." Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Your body is making extra red cells to carry more oxygen to the baby.\""}, {"id": "b", "text": "\"Fluid loss has concentrated your blood, so the hematocrit reads high.\""}, {"id": "c", "text": "\"Bleeding in your esophagus from vomiting has raised your hematocrit.\""}, {"id": "d", "text": "\"Your high β-hCG levels are directly stimulating red blood cell production.\""}]'::jsonb, '["b"]', 'An elevated hematocrit in HG reflects hemoconcentration from dehydration. GI bleeding from a Mallory-Weiss tear would not raise the hematocrit.'),
  ('hyperemesis', 15, 'A client with HG has received IV fluids and antiemetics for 36 hours. On admission her urine specific gravity was 1.032 with 3+ ketones. Which set of findings BEST indicates that treatment is effective?', '[{"id": "a", "text": "Specific gravity 1.030, 1+ ketones, and weight unchanged"}, {"id": "b", "text": "Specific gravity 1.028, negative ketones, weight down 0.5 kg"}, {"id": "c", "text": "Specific gravity 1.015, negative ketones, weight up 0.8 kg"}, {"id": "d", "text": "Specific gravity 1.018, 2+ ketones, and weight down 0.3 kg"}]'::jsonb, '["c"]', 'A specific gravity below 1.025, no ketones, and a rising daily weight show improved hydration and nutrition. A specific gravity of 1.028–1.030 still indicates concentrated urine, and persistent ketones show ongoing inadequate nutrition.'),
  ('hyperemesis', 16, 'A client at 10 weeks has vomited 8–12 times a day for 2 weeks and is admitted for HG. Which electrolyte pattern should the nurse expect on her admission laboratory results?', '[{"id": "a", "text": "High sodium, high potassium, and high chloride"}, {"id": "b", "text": "Low sodium, high potassium, and high chloride"}, {"id": "c", "text": "High sodium, low potassium, and normal chloride"}, {"id": "d", "text": "Low sodium, low potassium, and low chloride"}]'::jsonb, '["d"]', 'Electrolytes are lost through vomiting, causing hyponatremia, hypokalemia, and hypochloremia. Patterns with high or normal values do not reflect vomiting losses.'),
  ('hyperemesis', 17, 'A client at 14 weeks has had HG for 6 weeks despite outpatient treatment. Which new finding should the nurse recognize as a sign that her HG has become severe and prolonged?', '[{"id": "a", "text": "Nausea that worsens when strong cooking odors are present"}, {"id": "b", "text": "Mildly yellow sclerae with elevated liver function tests"}, {"id": "c", "text": "Fatigue and a desire to rest more during the daytime"}, {"id": "d", "text": "Vomiting that is worse in the morning than the evening"}]'::jsonb, '["b"]', 'Elevated LFTs and mild jaundice occur in severe or prolonged HG. Odor sensitivity and morning-predominant vomiting are common nausea triggers and patterns that do not indicate severity.'),
  ('hyperemesis', 18, 'A client at 9 weeks has tried small frequent meals, dry crackers before rising, and ginger for 2 weeks without relief. She keeps fluids down, her weight is stable, and she has no ketonuria. Which medication should the nurse anticipate FIRST?', '[{"id": "a", "text": "Pyridoxine (vitamin B6), with or without doxylamine"}, {"id": "b", "text": "IV ondansetron given with lactated Ringer''s solution"}, {"id": "c", "text": "Methylprednisolone given to control her symptoms"}, {"id": "d", "text": "Total parenteral nutrition to rest the GI tract"}]'::jsonb, '["a"]', 'In the step-up approach, vitamin B6 with or without doxylamine is the first-line pharmacologic therapy after dietary measures. Methylprednisolone is reserved for refractory HG and TPN is a last resort.'),
  ('hyperemesis', 19, 'A client at 8 weeks whose nausea is controlled most of the day is taught dietary measures to manage it. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll eat a few dry crackers before I get out of bed.\""}, {"id": "b", "text": "\"I''ll eat small meals often instead of three large ones.\""}, {"id": "c", "text": "\"I''ll choose hot meals, because warm food smells more appealing.\""}, {"id": "d", "text": "\"I''ll try ginger, because it''s safe to use in pregnancy.\""}]'::jsonb, '["c"]', 'Cold foods are recommended because they have less odor, which reduces nausea triggers. Dry crackers before rising, small frequent meals, and ginger are all recommended dietary measures.'),
  ('hyperemesis', 20, 'A client receiving IV promethazine for HG reports feeling very drowsy 30 minutes after the dose. She is oriented, her gait was steady earlier, and her vital signs are stable. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Drowsiness is an expected effect of promethazine"}, {"id": "b", "text": "Drowsiness indicates extrapyramidal symptoms from the drug"}, {"id": "c", "text": "Drowsiness shows the dose did not control her nausea"}, {"id": "d", "text": "Drowsiness shows the drug is promoting gastric emptying"}]'::jsonb, '["a"]', 'Promethazine is effective but causes sedation. Extrapyramidal symptoms and promotion of gastric emptying are associated with metoclopramide, not promethazine.'),
  ('hyperemesis', 21, 'A client with HG reports that food seems to "sit in her stomach for hours," and the provider prescribes metoclopramide. Which adverse effect is MOST important for the nurse to monitor for?', '[{"id": "a", "text": "Marked sedation"}, {"id": "b", "text": "Fetal cleft palate"}, {"id": "c", "text": "Extrapyramidal symptoms"}, {"id": "d", "text": "Wernicke''s encephalopathy"}]'::jsonb, '["c"]', 'Metoclopramide, a dopamine antagonist, promotes gastric emptying and requires monitoring for EPS. Marked sedation is the expected effect of promethazine.'),
  ('hyperemesis', 22, 'A client admitted with HG has dry mucous membranes, urine specific gravity of 1.030, and a low potassium level. She has vomited every oral medication given today. Which prescription should the nurse anticipate?', '[{"id": "a", "text": "Dextrose 5% in water as the first IV fluid, without thiamine"}, {"id": "b", "text": "Oral potassium tablets taken with small sips of water"}, {"id": "c", "text": "Total parenteral nutrition started on the first hospital day"}, {"id": "d", "text": "Normal saline with potassium added for rehydration"}]'::jsonb, '["d"]', 'Rehydration uses normal saline or lactated Ringer''s, with potassium added for hypokalemia. She cannot keep oral medications down, dextrose should not precede thiamine in a malnourished client, and TPN is a last resort.'),
  ('hyperemesis', 23, 'A client with HG continues to lose weight after a week of IV fluids, IV thiamine, and scheduled antiemetics, and she still cannot tolerate oral intake. Which nutritional intervention should the nurse anticipate NEXT?', '[{"id": "a", "text": "Total parenteral nutrition before any tube feeding is tried"}, {"id": "b", "text": "Discharge on a regular diet of three large meals a day"}, {"id": "c", "text": "Holding all nutrition until her vomiting stops entirely"}, {"id": "d", "text": "Nasogastric tube feedings before parenteral nutrition"}]'::jsonb, '["d"]', 'TPN or NG feeding is the last resort for refractory HG, and nasogastric feedings may be tried before TPN. Large meals worsen nausea, and withholding nutrition worsens weight loss.'),
  ('hyperemesis', 24, 'A nurse in an obstetric clinic reviews four clients with nausea and vomiting of pregnancy. Which client should the nurse expect to require hospital admission?', '[{"id": "a", "text": "At 8 weeks, vomits in the mornings but keeps lunch and dinner down"}, {"id": "b", "text": "At 11 weeks, nausea controlled on B6 and doxylamine, ketones negative"}, {"id": "c", "text": "At 10 weeks, vomits oral antiemetics and has significant weight loss"}, {"id": "d", "text": "At 9 weeks, mild nausea with odors, eats small meals every 2–3 hours"}]'::jsonb, '["c"]', 'Hospitalization is indicated for severe dehydration, inability to tolerate oral antiemetics, significant weight loss, or electrolyte imbalance. The other clients keep food or fluids down and are controlled with diet or first-line medication.'),
  ('hyperemesis', 25, 'A nurse is planning care for a client admitted with HG who has ketonuria, dehydration, and ongoing vomiting at 10 weeks. Which order of nursing priorities is correct?', '[{"id": "a", "text": "Antiemetics → fluid/electrolytes → fetal monitoring → nutrition"}, {"id": "b", "text": "Nutrition → fluid/electrolytes → antiemetics → psychological support"}, {"id": "c", "text": "Fluid/electrolytes → nutrition → antiemetics → fetal monitoring"}, {"id": "d", "text": "Fetal monitoring → antiemetics → nutrition → fluid/electrolytes"}]'::jsonb, '["c"]', 'The nursing care priorities for HG are fluid/electrolyte balance first, then nutrition, antiemetics, and fetal monitoring, followed by psychological support and environment. Starting with antiemetics or nutrition skips the first priority.'),
  ('hyperemesis', 26, 'A client with HG is resting in a private room after an episode of vomiting. Which action by the unlicensed assistive personnel (UAP) requires the nurse to intervene?', '[{"id": "a", "text": "Dimming the room lights during the afternoon"}, {"id": "b", "text": "Asking several visitors to wait in the lounge"}, {"id": "c", "text": "Recording each emesis on the intake and output record"}, {"id": "d", "text": "Leaving an uncovered hot meal tray at the bedside"}]'::jsonb, '["d"]', 'The environment for HG should be quiet and odor-free, with small meals kept covered to reduce nausea triggers. Dim lighting, limiting visitors, and recording output are appropriate.'),
  ('hyperemesis', 27, 'A client at 12 weeks admitted with HG cries and says, "I can''t keep anything down. I''m starving my baby, and it''s my fault." Fetal heart tones were heard on admission. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Your baby is likely being harmed, so it''s important to make yourself eat more.\""}, {"id": "b", "text": "\"This is caused by stress, so once you relax, the vomiting will stop on its own.\""}, {"id": "c", "text": "\"Try not to worry; HG ends for everyone by 12 weeks, so it will stop very soon.\""}, {"id": "d", "text": "\"HG doesn''t mean your baby is harmed; outcomes are usually good with treatment.\""}]'::jsonb, '["d"]', 'The nurse should reassure the client that HG does not mean the baby is harmed and outcomes are usually good. Stress can worsen severity but is not the sole cause, and the 12–14-week resolution applies to normal morning sickness.'),
  ('hyperemesis', 28, 'A client with HG who has had forceful retching and vomiting for 3 days now has streaks of bright red blood in her emesis. Her vital signs are stable. Which complication should the nurse suspect and report?', '[{"id": "a", "text": "Wernicke''s encephalopathy"}, {"id": "b", "text": "Gestational thyrotoxicosis"}, {"id": "c", "text": "Mallory-Weiss esophageal tear"}, {"id": "d", "text": "Metabolic alkalosis"}]'::jsonb, '["c"]', 'Forceful vomiting can cause Mallory-Weiss esophageal tears, leading to GI bleeding. Metabolic alkalosis results from HCl loss but does not cause bloody emesis.'),
  ('hyperemesis', 29, 'A client at 24 weeks has had severe HG since 8 weeks with continued weight loss despite treatment. Which fetal assessment should the nurse anticipate as MOST important?', '[{"id": "a", "text": "Serial growth scans to detect fetal growth restriction"}, {"id": "b", "text": "Fetal thyroid testing to detect gestational thyrotoxicosis"}, {"id": "c", "text": "Fetal heart checks started only after a delivery date is set"}, {"id": "d", "text": "Ultrasound to confirm molar pregnancy as the cause at 24 weeks"}]'::jsonb, '["a"]', 'Severe prolonged HG can cause fetal growth restriction from inadequate maternal nutrition, so FHR and growth scans are monitored. Gestational thyrotoxicosis is a transient maternal condition.'),
  ('hyperemesis', 30, 'A client who had severe HG requiring three hospital admissions gives birth at 38 weeks. At her 2-week postpartum visit, she is eating well and has regained weight. Which assessment is MOST important for the nurse to include?', '[{"id": "a", "text": "Checking her urine for ketones"}, {"id": "b", "text": "Screening for postpartum depression"}, {"id": "c", "text": "Assessing for nystagmus and ataxia"}, {"id": "d", "text": "Measuring her serum β-hCG level"}]'::jsonb, '["b"]', 'HG increases the risk of postpartum depression, and the severity of HG affects mental health. She is now eating and gaining weight, so ketones and Wernicke''s signs are less relevant.'),
  ('hyperemesis', 31, 'A client at 10 weeks with HG has thyroid studies showing transient hyperthyroidism. She asks whether she now has a permanent thyroid disease. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Vomiting has damaged your thyroid, so you will need lifelong hormone replacement.\""}, {"id": "b", "text": "\"β-hCG has mild TSH-like action, which can temporarily stimulate your thyroid.\""}, {"id": "c", "text": "\"Low β-hCG levels slow the thyroid in pregnancy, causing temporary hypothyroidism.\""}, {"id": "d", "text": "\"Thiamine deficiency from vomiting causes the thyroid to overproduce hormone.\""}]'::jsonb, '["b"]', 'β-hCG has mild TSH-like action, so transient hyperthyroidism (gestational thyrotoxicosis) can occur. HG is associated with high, not low, β-hCG, and thiamine deficiency causes Wernicke''s encephalopathy.'),
  ('hyperemesis', 32, 'A client at 9 weeks with HG asks why her vomiting is much worse now than it was at 5 weeks. Her urine ketones are 2+. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"β-hCG is falling now, and falling levels trigger the vomiting center.\""}, {"id": "b", "text": "\"Progesterone speeds stomach emptying, which increases vomiting now.\""}, {"id": "c", "text": "\"β-hCG stimulates the vomiting center and peaks around 8 to 10 weeks.\""}, {"id": "d", "text": "\"Estrogen levels drop sharply at 9 weeks, which triggers more nausea.\""}]'::jsonb, '["c"]', 'Rising β-hCG stimulates the vomiting center and peaks at 8–10 weeks, paralleling the HG peak. Progesterone slows, rather than speeds, gastric emptying.'),
  ('hyperemesis', 33, 'A client with HG reports that after even small meals she feels full for hours and food seems to "just sit there." She asks why. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Progesterone tightens the GI muscles, which pushes food out too quickly.\""}, {"id": "b", "text": "\"β-hCG blocks the outlet of your stomach, so food cannot leave it.\""}, {"id": "c", "text": "\"Thiamine deficiency has paralyzed your stomach muscles completely.\""}, {"id": "d", "text": "\"Progesterone relaxes the GI muscles, which slows stomach emptying.\""}]'::jsonb, '["d"]', 'Progesterone relaxes GI smooth muscle, causing delayed gastric emptying. β-hCG acts on the vomiting center, not the stomach outlet.'),
  ('hyperemesis', 34, 'A client at 11 weeks presents with vomiting, burning on urination, and urinary frequency for 3 days. The provider is considering HG. Which test should the nurse anticipate to help rule out another cause?', '[{"id": "a", "text": "Serum thiamine to confirm Wernicke''s encephalopathy"}, {"id": "b", "text": "Serum β-hCG to establish the diagnosis of HG"}, {"id": "c", "text": "Thyroid scan to confirm gestational thyrotoxicosis"}, {"id": "d", "text": "Urinalysis to evaluate for a urinary tract infection"}]'::jsonb, '["d"]', 'HG is a clinical diagnosis, and labs confirm severity and rule out other causes such as UTI, appendicitis, and cholecystitis. Her urinary symptoms make UTI the cause to rule out.'),
  ('hyperemesis', 35, 'A nurse assesses a client admitted with HG who has vomited 8–10 times daily for a week and has 3+ urine ketones. Which set of findings should the nurse expect?', '[{"id": "a", "text": "Moist mucous membranes, brisk skin turgor, and dilute urine"}, {"id": "b", "text": "Dependent edema, crackles, and urine specific gravity of 1.005"}, {"id": "c", "text": "Moist mucous membranes, poor skin turgor, and dilute urine"}, {"id": "d", "text": "Dry mucous membranes, poor skin turgor, and concentrated urine"}]'::jsonb, '["d"]', 'Dehydration in HG presents with dry mucous membranes, poor skin turgor, and concentrated urine. Edema, crackles, and dilute urine suggest fluid excess, not loss.'),
  ('hyperemesis', 36, 'A client admitted with HG has had no vomiting for 24 hours on IV fluids and antiemetics, and her ketones are now negative. The provider orders her diet advanced. Which plan is MOST appropriate?', '[{"id": "a", "text": "Start with clear liquids and advance slowly toward small, bland meals"}, {"id": "b", "text": "Start a regular diet of three large meals to help her regain the lost weight quickly"}, {"id": "c", "text": "Start with spicy, flavorful foods to stimulate her poor appetite"}, {"id": "d", "text": "Keep her NPO until she has gone 72 hours without any nausea"}]'::jsonb, '["a"]', 'Nutrition in HG is advanced slowly, starting with clear liquids and moving toward small bland meals, to prevent further weight loss while limiting vomiting triggers. Large or highly flavored meals act as triggers.'),
  ('hyperemesis', 37, 'A client hospitalized with HG for 5 days says she feels alone and afraid. Her electrolytes have normalized, and she is now tolerating crackers. Which nursing action is MOST appropriate at this time?', '[{"id": "a", "text": "Restrict every visitor, including family, to limit triggers"}, {"id": "b", "text": "Increase antiemetic doses to sedate her through the anxiety"}, {"id": "c", "text": "Acknowledge her distress, give information, and involve family"}, {"id": "d", "text": "Explain that stress is the main cause of her hyperemesis"}]'::jsonb, '["c"]', 'Psychological support includes acknowledging distress, providing information, and involving family, because HG can cause anxiety, isolation, and fear. Visitors are limited, not eliminated, and stress worsens severity rather than being the sole cause.'),
  ('hyperemesis', 38, 'A client at 9 weeks whose dietary measures failed is prescribed pyridoxine with doxylamine. She says, "Doxylamine is a sleep aid. Won''t it hurt my baby?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Doxylamine is unsafe early on, so take vitamin B6 alone until 14 weeks.\""}, {"id": "b", "text": "\"Doxylamine is safe in pregnancy and is often given together with vitamin B6.\""}, {"id": "c", "text": "\"Doxylamine is a corticosteroid that is reserved for refractory cases.\""}, {"id": "d", "text": "\"Doxylamine works by replacing the thiamine lost through your vomiting.\""}]'::jsonb, '["b"]', 'Doxylamine is an antihistamine that is safe in pregnancy and is often given with vitamin B6 as first-line therapy. Methylprednisolone is the corticosteroid reserved for refractory HG.'),
  ('hyperemesis', 39, 'A client with HG has a potassium level reported as very low after a week of persistent vomiting. She reports feeling weak and "fluttery." Which assessment is the nurse''s PRIORITY?', '[{"id": "a", "text": "Urine ketones"}, {"id": "b", "text": "Cardiac rhythm"}, {"id": "c", "text": "Skin turgor"}, {"id": "d", "text": "Daily weight"}]'::jsonb, '["b"]', 'Hypokalemia can cause cardiac dysrhythmias and muscle weakness, so cardiac rhythm is the priority. Ketones, turgor, and weight assess nutrition and hydration but not the immediate danger.'),
  ('hyperemesis', 40, 'A client with HG whose eye movements and gait are normal has a markedly low serum sodium level and becomes restless and newly confused. Which complication is the nurse MOST concerned about?', '[{"id": "a", "text": "Mallory-Weiss bleeding"}, {"id": "b", "text": "Cardiac dysrhythmias"}, {"id": "c", "text": "Esophageal rupture"}, {"id": "d", "text": "Seizure activity"}]'::jsonb, '["d"]', 'Hyponatremia causes neurological symptoms and seizures if severe. Cardiac dysrhythmias are associated with hypokalemia, and esophageal injuries cause bleeding, not confusion.'),
  ('hyperemesis', 41, 'A malnourished client with HG who has vomited for 5 weeks has prescriptions for IV thiamine and dextrose-containing IV fluids. The thiamine has not yet arrived from pharmacy. Which action by a new nurse requires correction?', '[{"id": "a", "text": "Hanging the dextrose infusion while waiting for the thiamine"}, {"id": "b", "text": "Calling the pharmacy to ask when the thiamine dose will be arriving"}, {"id": "c", "text": "Checking the client''s urine for ketones before the infusion"}, {"id": "d", "text": "Weighing the client on the same scale each morning"}]'::jsonb, '["a"]', 'IV thiamine must be given before IV dextrose in clients with prolonged vomiting and malnutrition to prevent Wernicke''s encephalopathy. Checking ketones and daily weights are appropriate HG nursing actions.'),
  ('hyperemesis', 42, 'A nurse on an antepartum unit receives report on four clients with HG. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A client who reports nausea whenever the lunch trays arrive"}, {"id": "b", "text": "A client whose urine ketones decreased from 3+ to 1+ today"}, {"id": "c", "text": "A client who is tearful about missing work for a week"}, {"id": "d", "text": "A client who is newly confused and unsteady when walking"}]'::jsonb, '["d"]', 'New confusion and ataxia in HG suggest Wernicke''s encephalopathy from thiamine deficiency, an emergency. Decreasing ketones indicate improvement, and the other concerns are not life-threatening.'),
  ('hyperemesis', 43, 'A client at 30 weeks who had severe, prolonged HG through the first and second trimesters calls reporting regular abdominal tightening for an hour. Which HG-related complication should the nurse consider and evaluate?', '[{"id": "a", "text": "Molar pregnancy, which develops late in HG"}, {"id": "b", "text": "Gestational thyrotoxicosis causing contractions"}, {"id": "c", "text": "Preterm birth associated with severe, prolonged HG"}, {"id": "d", "text": "Morning sickness that returns at 30 weeks"}]'::jsonb, '["c"]', 'Preterm birth is associated with severe, prolonged HG, so regular tightening at 30 weeks requires evaluation. Gestational thyrotoxicosis is a transient effect of β-hCG, not a cause of contractions.'),
  ('hyperemesis', 44, 'A client carrying twins at 8 weeks has severe vomiting and 2+ ketones. She asks why her sister, who carried one baby, had only mild nausea. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"A twin pregnancy lowers β-hCG levels, and the low levels cause more nausea.\""}, {"id": "b", "text": "\"A twin pregnancy raises β-hCG, which stimulates the vomiting center.\""}, {"id": "c", "text": "\"A twin pregnancy causes thiamine deficiency that triggers vomiting.\""}, {"id": "d", "text": "\"A twin pregnancy causes hyperthyroidism, the main cause of HG.\""}]'::jsonb, '["b"]', 'HG is associated with high β-hCG, which occurs more often with multiple gestation, and increased β-hCG increases stimulation of the vomiting centers. Thiamine deficiency is a consequence of prolonged HG, not its cause.'),
  ('hyperemesis', 45, 'A client at 17 weeks still vomits several times a day and has lost weight since her last visit. She says a friend told her that "morning sickness lasts the whole pregnancy." Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Morning sickness commonly lasts until birth, so this pattern is expected"}, {"id": "b", "text": "Morning sickness peaks at 16–18 weeks, so she should improve soon"}, {"id": "c", "text": "Weight loss is expected with morning sickness and needs no follow-up"}, {"id": "d", "text": "Morning sickness usually ends by 12–14 weeks, so this needs evaluation"}]'::jsonb, '["d"]', 'Normal morning sickness usually resolves by 12–14 weeks and involves no significant weight loss. Persistent vomiting at 17 weeks with weight loss goes beyond normal morning sickness.'),
  ('hyperemesis', 46, 'A nurse reviews urine specific gravity results for four clients at 9–11 weeks who report nausea and vomiting. Which result indicates concentrated urine consistent with dehydration?', '[{"id": "a", "text": "1.010"}, {"id": "b", "text": "1.018"}, {"id": "c", "text": "1.022"}, {"id": "d", "text": "1.029"}]'::jsonb, '["d"]', 'A urine specific gravity above 1.025 indicates concentrated urine from dehydration; 1.029 exceeds this value. The other results are below 1.025.'),
  ('hyperemesis', 47, 'A client at 9 weeks weighed 70 kg before pregnancy and now weighs 66.4 kg. She has 2+ urine ketones and has not kept fluids down for 2 days. Which finding MOST strongly supports HG rather than normal morning sickness?', '[{"id": "a", "text": "Her nausea first began at about 6 weeks of gestation"}, {"id": "b", "text": "Her vomiting is usually worse in the mornings"}, {"id": "c", "text": "Her nausea is triggered by strong food odors"}, {"id": "d", "text": "Her weight loss of 3.6 kg since pregnancy began"}]'::jsonb, '["d"]', 'A 3.6-kg loss from 70 kg is about 5.1%, meeting the ≥5% weight-loss criterion for HG. First-trimester onset, morning vomiting, and odor triggers occur with normal morning sickness too.'),
  ('hyperemesis', 48, 'A client at 16 weeks with HG has had no response to vitamin B6 with doxylamine, promethazine, metoclopramide, and ondansetron, and she remains on IV fluids. Which medication should the nurse anticipate may be added?', '[{"id": "a", "text": "Pyridoxine alone, as a first-line vitamin"}, {"id": "b", "text": "Methylprednisolone, a corticosteroid"}, {"id": "c", "text": "Doxylamine alone, as a first-line antihistamine"}, {"id": "d", "text": "Thiamine in place of all of her antiemetics"}]'::jsonb, '["b"]', 'Methylprednisolone is a corticosteroid reserved for refractory HG. Pyridoxine and doxylamine are first-line agents that have already failed, and thiamine prevents Wernicke''s rather than replacing antiemetics.'),
  ('hyperemesis', 49, 'A client admitted with HG is receiving IV fluids. Her daily weights are 55.4 kg on day 1, 54.9 kg on day 2, and 54.2 kg on day 3, and her urine ketones remain 3+. Which evaluation by the nurse is MOST accurate?', '[{"id": "a", "text": "Fluid balance is improving, so the current plan should continue"}, {"id": "b", "text": "Hydration and nutrition are not improving, so the trend should be reported"}, {"id": "c", "text": "Weight loss is expected while on IV fluids, so ketones are the better measure"}, {"id": "d", "text": "Ketones are normal in HG, so the weight trend is the only concern"}]'::jsonb, '["b"]', 'Daily weight is the best objective measure of fluid balance, and persistent ketones indicate inadequate nutrition; both show the client is not improving. A falling weight does not indicate improving fluid balance.'),
  ('hyperemesis', 50, 'A client at 7 weeks with nausea keeps most food down, her weight is stable, and her urine is negative for ketones. She asks for a prescription antiemetic right away. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Ondansetron is the first treatment, and it''s given before any diet changes.\""}, {"id": "b", "text": "\"IV fluids are the first step, even when you can keep fluids down by mouth.\""}, {"id": "c", "text": "\"Diet changes such as small frequent meals and dry crackers come first.\""}, {"id": "d", "text": "\"Methylprednisolone is usually started first because it works the fastest.\""}]'::jsonb, '["c"]', 'In the step-up approach, dietary modifications such as small frequent meals and dry crackers before rising come first. Vitamin B6 with doxylamine follows as first-line pharmacologic therapy, and methylprednisolone is reserved for refractory HG.'),
  ('antepartum', 1, 'A client at 31 weeks'' gestation with an uncomplicated pregnancy finishes her routine prenatal visit and asks when she should return to the clinic. Which response by the nurse is BEST?', '[{"id": "a", "text": "In 4 weeks, since visits stay monthly until 32 weeks"}, {"id": "b", "text": "In 2 weeks, since visits are every 2 weeks from 28 to 36"}, {"id": "c", "text": "In 1 week, since visits become weekly once past 30 weeks"}, {"id": "d", "text": "In 3 weeks, since visit spacing tapers after 28 weeks"}]'::jsonb, '["b"]', 'Prenatal visits are every 4 weeks through 28 weeks, every 2 weeks from 28 to 36 weeks, and weekly from 36 weeks to delivery. At 31 weeks the client returns in 2 weeks.'),
  ('antepartum', 2, 'The nurse audits return appointments that a new clerk scheduled for four clients with uncomplicated pregnancies. Which client''s appointment requires correction?', '[{"id": "a", "text": "Client at 14 weeks: return visit in 4 weeks'' time"}, {"id": "b", "text": "Client at 30 weeks: return visit in 2 weeks"}, {"id": "c", "text": "Client at 37 weeks: return visit in 2 weeks"}, {"id": "d", "text": "Client at 20 weeks: return visit in 4 weeks"}]'::jsonb, '["c"]', 'From 36 weeks to delivery, visits are weekly, so a client at 37 weeks should return in 1 week. Visits every 4 weeks before 28 weeks and every 2 weeks from 28 to 36 weeks are correct.'),
  ('antepartum', 3, 'The nurse measures fundal height for four clients during routine prenatal visits. Which client''s measurement requires follow-up with the provider FIRST?', '[{"id": "a", "text": "26 weeks; fundal height of 30 cm"}, {"id": "b", "text": "22 weeks; fundal height of 23.5 cm"}, {"id": "c", "text": "30 weeks; fundal height of 29 cm"}, {"id": "d", "text": "32 weeks; fundal height of 33 cm"}]'::jsonb, '["a"]', 'By McDonald''s rule, fundal height in cm approximates gestational weeks within 2 cm from 18 to 32 weeks. A 30 cm fundus at 26 weeks is 4 cm larger than expected; the other measurements are within 2 cm.'),
  ('antepartum', 4, 'A client at 30 weeks by well-established dates has a fundal height of 26 cm; her earlier measurements matched her dates. Which conditions is the provider MOST likely to evaluate?', '[{"id": "a", "text": "Macrosomia or polyhydramnios from excess growth"}, {"id": "b", "text": "Multiple gestation or macrosomia of the fetus"}, {"id": "c", "text": "None; the value is within the normal range"}, {"id": "d", "text": "Fetal growth restriction or oligohydramnios"}]'::jsonb, '["d"]', 'A fundal height 4 cm below gestational weeks is smaller than expected, which suggests FGR, oligohydramnios, or wrong dates. Macrosomia, multiple gestation, and polyhydramnios cause a larger-than-expected fundus.'),
  ('antepartum', 5, 'A client who is 16 weeks pregnant by her last menstrual period has her fundus palpated at the level of the umbilicus. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Expected; the fundus reaches the umbilicus by 16 weeks"}, {"id": "b", "text": "Smaller than expected; growth restriction is a concern"}, {"id": "c", "text": "Larger than expected; the umbilicus marks about 20 weeks"}, {"id": "d", "text": "Expected; the fundus is near the xiphoid at 16 weeks"}]'::jsonb, '["c"]', 'At 16 weeks the fundus is halfway between the symphysis and umbilicus; it reaches the umbilicus at 20 weeks. A fundus at the umbilicus at 16 weeks is larger than expected.'),
  ('antepartum', 6, 'At 38 weeks a client''s fundal height was 38 cm. At her 40-week visit it measures 36 cm, and she reports that breathing has become easier. Which interpretation by the nurse is BEST?', '[{"id": "a", "text": "Fetal growth restriction is likely and should be reported"}, {"id": "b", "text": "The fundus has dropped as the baby engages (lightening)"}, {"id": "c", "text": "Oligohydramnios is likely because the height decreased"}, {"id": "d", "text": "A measuring error is likely; remeasure from the umbilicus"}]'::jsonb, '["b"]', 'Near 40 weeks the fundus drops slightly as the baby engages (lightening) and returns toward the 36 cm level, and lightening relieves dyspnea. Fundal height is measured from the symphysis pubis, not the umbilicus.'),
  ('antepartum', 7, 'A nursing student is measuring fundal height on a client at 24 weeks'' gestation during a supervised prenatal visit. Which action by the student requires the nurse to intervene?', '[{"id": "a", "text": "Measuring from the umbilicus to the top of the fundus"}, {"id": "b", "text": "Placing the zero end of the tape at the symphysis pubis"}, {"id": "c", "text": "Recording the measurement in centimeters"}, {"id": "d", "text": "Comparing the result with weeks of gestation"}]'::jsonb, '["a"]', 'Fundal height is measured with a tape from the symphysis pubis to the top of the fundus in centimeters and compared with gestational weeks. Starting at the umbilicus would underestimate the measurement.'),
  ('antepartum', 8, 'A client''s first-visit prenatal labs have returned. Which result is MOST important for the nurse to report to the provider for follow-up?', '[{"id": "a", "text": "Hemoglobin of 11.2 g/dL"}, {"id": "b", "text": "Rubella titer showing immunity"}, {"id": "c", "text": "Negative indirect Coombs antibody screen"}, {"id": "d", "text": "Hemoglobin of 10.6 g/dL"}]'::jsonb, '["d"]', 'Normal hemoglobin in pregnancy is 11 g/dL or higher; 10.6 g/dL indicates anemia, and iron supplementation is used if anemic. A hemoglobin of 11.2 g/dL reflects normal dilution, and rubella immunity and a negative antibody screen are reassuring.'),
  ('antepartum', 9, 'A client at 20 weeks is worried because her hemoglobin is 11.3 g/dL, lower than her pre-pregnancy value of 13.2 g/dL. She has no other abnormal findings. Which response by the nurse is BEST?', '[{"id": "a", "text": "A lower value from dilution is normal; this level is acceptable."}, {"id": "b", "text": "This value indicates anemia, so iron therapy should start now."}, {"id": "c", "text": "This value suggests infection, so a WBC count is needed next."}, {"id": "d", "text": "A drop of this size during pregnancy must be reported today."}]'::jsonb, '["a"]', 'Hemoglobin of 11 g/dL or higher is normal in pregnancy because dilution is expected, so 11.3 g/dL is acceptable. Iron supplementation is indicated if the client is anemic, which she is not.'),
  ('antepartum', 10, 'A client at 10 weeks has a rubella titer showing she is non-immune. After teaching, which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will receive the vaccine after my baby is born."}, {"id": "b", "text": "The vaccine is live, so it is not given while I''m pregnant."}, {"id": "c", "text": "I can get the rubella vaccine at my next prenatal visit."}, {"id": "d", "text": "I should be vaccinated postpartum before I go home."}]'::jsonb, '["c"]', 'Rubella vaccine is a live vaccine that is not given in pregnancy; non-immune clients are vaccinated postpartum, before discharge. Planning to receive it at a prenatal visit shows a need for teaching.'),
  ('antepartum', 11, 'A client at 20 weeks whose varicella titer shows she is non-immune asks to receive the chickenpox vaccine today so she will be protected for the rest of the pregnancy. Which response by the nurse is BEST?', '[{"id": "a", "text": "The vaccine can be given now because it protects the fetus."}, {"id": "b", "text": "The vaccine is given after delivery, not during pregnancy."}, {"id": "c", "text": "The vaccine is safe once the first trimester has ended."}, {"id": "d", "text": "The vaccine is given along with RhoGAM at the 28-week visit."}]'::jsonb, '["b"]', 'Clients who are non-immune to varicella are vaccinated postpartum only. Completing the first trimester does not make the vaccine appropriate during pregnancy.'),
  ('antepartum', 12, 'A client''s prenatal hepatitis B surface antigen was positive. Her newborn is delivered at 0300 and is stable. Which intervention is the PRIORITY for the nurse to ensure is completed by 1500?', '[{"id": "a", "text": "HepB vaccine plus hepatitis B immune globulin"}, {"id": "b", "text": "HepB vaccine, with HBIG deferred until 1 month"}, {"id": "c", "text": "Hepatitis B immune globulin, with vaccine deferred"}, {"id": "d", "text": "Erythromycin ointment in place of hepatitis products"}]'::jsonb, '["a"]', 'When the mother is hepatitis B surface antigen positive, the newborn receives both HepB vaccine and HBIG within 12 hours of birth. Giving only one product or deferring either does not meet this requirement.'),
  ('antepartum', 13, 'The nurse reviews results for four prenatal clients who all report feeling well. Which result requires the nurse to notify the provider for treatment FIRST?', '[{"id": "a", "text": "Hemoglobin of 11.4 g/dL at the 28-week recheck"}, {"id": "b", "text": "1-hour glucose challenge of 124 mg/dL at 26 weeks"}, {"id": "c", "text": "Nuchal translucency of 2.1 mm at 12 weeks"}, {"id": "d", "text": "Positive urine culture, no symptoms, at 14 weeks"}]'::jsonb, '["d"]', 'Asymptomatic bacteriuria is always treated in pregnancy because of the risk of pyelonephritis and preterm labor. The hemoglobin, glucose challenge, and nuchal translucency values are all within normal limits.'),
  ('antepartum', 14, 'A client''s first-visit antibody screen (indirect Coombs) is positive. She asks what this result means for her baby. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The baby has inherited Rh-negative blood and will need RhoGAM"}, {"id": "b", "text": "Maternal antibodies are present that could cause hemolytic disease"}, {"id": "c", "text": "She is immune to rubella, so the baby will be protected at birth"}, {"id": "d", "text": "She is anemic and needs iron supplementation in pregnancy"}]'::jsonb, '["b"]', 'A positive antibody screen means maternal antibodies are present, which creates a risk of hemolytic disease of the newborn. Rubella immunity is shown by the rubella titer and anemia by the CBC.'),
  ('antepartum', 15, 'An Rh-negative client at 16 weeks with a negative antibody screen undergoes amniocentesis this morning. Which plan regarding RhoGAM is BEST?', '[{"id": "a", "text": "Wait and give the routine dose at 28 weeks"}, {"id": "b", "text": "Give RhoGAM after birth if the newborn is Rh-positive"}, {"id": "c", "text": "Give RhoGAM within 72 hours of the procedure"}, {"id": "d", "text": "Hold all doses until the pregnancy has ended"}]'::jsonb, '["c"]', 'RhoGAM is given at 28 weeks and within 72 hours after any sensitizing event, including amniocentesis, bleeding, and delivery. Waiting for the 28-week dose leaves the sensitizing event uncovered.'),
  ('antepartum', 16, 'An Rh-negative client at 28 weeks has a negative repeat antibody screen and has had no bleeding during this pregnancy. Which action should the nurse anticipate at this visit?', '[{"id": "a", "text": "Administer RhoGAM as routine antepartum prophylaxis"}, {"id": "b", "text": "Withhold RhoGAM because there has been no bleeding"}, {"id": "c", "text": "Delay RhoGAM until 72 hours before the expected birth"}, {"id": "d", "text": "Give RhoGAM later only if the antibody screen turns positive"}]'::jsonb, '["a"]', 'Rh-negative clients receive RhoGAM at 28 weeks to prevent sensitization from fetal cells entering the maternal circulation, even without bleeding. A positive antibody screen means antibodies are already present.'),
  ('antepartum', 17, 'A client''s first-visit RPR is reactive for syphilis. She asks why treatment cannot simply wait until after the baby is born. Which response by the nurse is BEST?', '[{"id": "a", "text": "Syphilis affects the newborn only during a vaginal birth."}, {"id": "b", "text": "Treatment is deferred because penicillin is unsafe now."}, {"id": "c", "text": "Syphilis is treated postpartum, like the rubella vaccine."}, {"id": "d", "text": "Syphilis crosses the placenta, so penicillin is given now."}]'::jsonb, '["d"]', 'Syphilis is treated with penicillin during pregnancy because it crosses the placenta to the fetus. Postpartum timing applies to live vaccines such as rubella, not to syphilis treatment.'),
  ('antepartum', 18, 'A client at 10 weeks tests positive for chlamydia at her first prenatal visit. Which rationale is MOST important for the nurse to emphasize when teaching about treatment now?', '[{"id": "a", "text": "Treatment prevents rubella infection in the newborn"}, {"id": "b", "text": "Treatment prevents neonatal eye infection at birth"}, {"id": "c", "text": "Treatment lowers the risk of preeclampsia later"}, {"id": "d", "text": "Treatment removes the need for eye ointment at birth"}]'::jsonb, '["b"]', 'Chlamydia and gonorrhea are treated in pregnancy to prevent neonatal eye infection, and erythromycin eye ointment is still given at birth. Preeclampsia risk is linked to hypothyroidism, not chlamydia.'),
  ('antepartum', 19, 'A client''s first-visit TSH result indicates hypothyroidism. The nurse explains why this result needs follow-up during the pregnancy. Which risk is MOST directly linked to this finding?', '[{"id": "a", "text": "Gestational diabetes and macrosomia"}, {"id": "b", "text": "Neural tube defects in the fetus"}, {"id": "c", "text": "Preeclampsia and fetal loss"}, {"id": "d", "text": "Hemolytic disease of the newborn"}]'::jsonb, '["c"]', 'Hypothyroidism increases the risk of preeclampsia and fetal loss. Neural tube defects are screened by AFP, and hemolytic disease of the newborn is linked to a positive antibody screen.'),
  ('antepartum', 20, 'A client at 8 weeks wants cell-free DNA screening for trisomies drawn at today''s visit so she can know as early as possible. Which response by the nurse is BEST?', '[{"id": "a", "text": "This screen is drawn at 15 to 20 weeks with the AFP."}, {"id": "b", "text": "This screen is done at 18 to 20 weeks with the anatomy scan."}, {"id": "c", "text": "This screen can be drawn today to give the earliest result."}, {"id": "d", "text": "This screen is typically drawn starting at 10 to 13 weeks."}]'::jsonb, '["d"]', 'Cell-free DNA (NIPT) screening is timed at 10-13 weeks and screens for trisomy 21, 18, and 13. The quad screen with AFP is at 15-20 weeks and the anatomy ultrasound at 18-20 weeks.'),
  ('antepartum', 21, 'A client at 12 weeks has a nuchal translucency ultrasound that measures 3.4 mm. Which interpretation of this result should the nurse anticipate is MOST accurate?', '[{"id": "a", "text": "Increased Down syndrome risk; further evaluation needed"}, {"id": "b", "text": "Normal result; no further screening is recommended"}, {"id": "c", "text": "Increased neural tube defect risk from elevated AFP"}, {"id": "d", "text": "Invalid result, because this test is done only at 18-20 weeks"}]'::jsonb, '["a"]', 'A nuchal translucency of 3 mm or more at 11-14 weeks indicates increased Down syndrome risk. Neural tube defects are associated with elevated AFP on the quad screen, not with nuchal translucency.'),
  ('antepartum', 22, 'A client at 17 weeks has a quad screen showing elevated AFP, with hCG, estriol, and inhibin A in the expected range. Which condition is this result MOST associated with?', '[{"id": "a", "text": "Down syndrome"}, {"id": "b", "text": "Neural tube defect"}, {"id": "c", "text": "Gestational diabetes"}, {"id": "d", "text": "Rh sensitization"}]'::jsonb, '["b"]', 'On the quad screen, elevated AFP is associated with neural tube defects. Down syndrome is associated with low AFP, high hCG, and low estriol.'),
  ('antepartum', 23, 'A client at 16 weeks has a quad screen showing low AFP, high hCG, and low estriol. Which interpretation and plan by the nurse is MOST appropriate?', '[{"id": "a", "text": "Neural tube defect risk; explain the AFP abnormality"}, {"id": "b", "text": "Normal pattern; no further testing is needed"}, {"id": "c", "text": "Down syndrome risk; anticipate further evaluation"}, {"id": "d", "text": "Gestational diabetes risk; schedule a 3-hour GTT"}]'::jsonb, '["c"]', 'Low AFP with high hCG and low estriol is the quad screen pattern for Down syndrome risk. A neural tube defect is suggested by elevated, not low, AFP.'),
  ('antepartum', 24, 'A client at 23 weeks who missed several earlier prenatal visits asks the nurse to draw the quad screen today. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "It is drawn at 24-28 weeks along with the glucose test."}, {"id": "b", "text": "It can be drawn today because it is done after 20 weeks."}, {"id": "c", "text": "It is drawn at 10-13 weeks, so the window has passed."}, {"id": "d", "text": "Its window is 15-20 weeks, so she is past the timing."}]'::jsonb, '["d"]', 'The quad screen (AFP, hCG, estriol, inhibin A) is timed for 15-20 weeks, so at 23 weeks she is past the window. The 10-13 week window applies to cell-free DNA screening.'),
  ('antepartum', 25, 'At 19 weeks, a client asks which test will show where her placenta is located and will examine the baby''s organs for anomalies. Which test should the nurse identify as BEST suited?', '[{"id": "a", "text": "Anatomy ultrasound at 18-20 weeks"}, {"id": "b", "text": "Nuchal translucency ultrasound scan"}, {"id": "c", "text": "Quad screen with AFP and estriol"}, {"id": "d", "text": "Cell-free DNA screening (NIPT)"}]'::jsonb, '["a"]', 'The anatomy ultrasound at 18-20 weeks evaluates fetal organs, anomalies, placental location, and fetal sex. Nuchal translucency assesses Down syndrome risk at 11-14 weeks.'),
  ('antepartum', 26, 'A client at 26 weeks has a 1-hour glucose challenge test result of 146 mg/dL. She asks whether this means she has diabetes. Which action should the nurse anticipate NEXT?', '[{"id": "a", "text": "Confirm gestational diabetes and begin teaching on insulin"}, {"id": "b", "text": "Schedule a 3-hour glucose tolerance test for follow-up"}, {"id": "c", "text": "Repeat the 1-hour challenge test again at 36 weeks"}, {"id": "d", "text": "Document a normal screen; no follow-up is required"}]'::jsonb, '["b"]', 'The 1-hour glucose challenge at 24-28 weeks is a screen; 140 mg/dL or higher is abnormal and is followed by a 3-hour GTT. The screen alone does not diagnose gestational diabetes.'),
  ('antepartum', 27, 'The nurse reviews screening results for four prenatal clients. Which client''s result should the nurse flag FIRST as needing further diagnostic testing?', '[{"id": "a", "text": "1-hour glucose challenge of 128 mg/dL at 25 weeks"}, {"id": "b", "text": "Hemoglobin of 11.1 g/dL at the 28-week recheck"}, {"id": "c", "text": "1-hour glucose challenge of 141 mg/dL at 27 weeks"}, {"id": "d", "text": "Nuchal translucency of 2.4 mm at 12 weeks"}]'::jsonb, '["c"]', 'A 1-hour glucose challenge of 140 mg/dL or higher is abnormal and requires a 3-hour GTT, so 141 mg/dL needs follow-up. Hemoglobin of at least 11 g/dL and nuchal translucency under 3 mm are within normal limits.'),
  ('antepartum', 28, 'A client at 36 weeks has a positive group B strep vaginal/rectal culture. After teaching, which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will receive IV antibiotics once I am in labor."}, {"id": "b", "text": "Penicillin will be given through my IV line during labor."}, {"id": "c", "text": "The swab was collected from my vagina and rectum."}, {"id": "d", "text": "I will take antibiotics now to clear it before labor."}]'::jsonb, '["d"]', 'GBS-positive clients receive IV penicillin in labor, not antepartum treatment, because colonization returns. The culture is a vaginal/rectal swab.'),
  ('antepartum', 29, 'A client at 32 weeks with an uncomplicated pregnancy asks whether her group B strep swab can be collected today, since she is already at the clinic. Which response by the nurse is BEST?', '[{"id": "a", "text": "The swab is collected at 35 to 37 weeks of pregnancy."}, {"id": "b", "text": "The swab is collected at 28 weeks along with the RhoGAM."}, {"id": "c", "text": "The swab is collected at 24 to 28 weeks with the GCT."}, {"id": "d", "text": "The swab is collected at the first prenatal visit."}]'::jsonb, '["a"]', 'GBS vaginal/rectal culture is performed at 35-37 weeks. The 24-28 week window is for the glucose challenge test, and 28 weeks is when RhoGAM is given to Rh-negative clients.'),
  ('antepartum', 30, 'A client at 32 weeks calls and reports counting 7 fetal movements in the 2 hours after dinner, the same time she counts every day. Yesterday she counted 12. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Count again tomorrow after breakfast and call if still low"}, {"id": "b", "text": "Contact the provider now for further fetal evaluation"}, {"id": "c", "text": "Lie down and count for another 2 hours before calling"}, {"id": "d", "text": "This is reassuring because she felt over 5 movements"}]'::jsonb, '["b"]', 'With the Cardiff count-to-ten method, the goal is 10 movements in 2 hours, and fewer than 10 in 2 hours must be reported to the provider. Delaying the report postpones needed evaluation.'),
  ('antepartum', 31, 'A client at 28 weeks is being taught to perform daily fetal kick counts at home. Which statement by the client indicates correct understanding of the technique?', '[{"id": "a", "text": "I''ll count whenever I happen to remember during the day."}, {"id": "b", "text": "I''ll count first thing in the morning before I eat."}, {"id": "c", "text": "I''ll count at the same time each day after a meal."}, {"id": "d", "text": "I''ll count for 30 minutes and expect at least 10 kicks."}]'::jsonb, '["c"]', 'Kick counts begin at 28 weeks and are done at the same time each day after a meal, when the baby is most active. The goal is 10 movements in 2 hours, not in 30 minutes.'),
  ('antepartum', 32, 'A client at 34 weeks has a non-stress test. After 40 minutes, the tracing shows one acceleration of 15 bpm lasting 18 seconds and no other accelerations. Which action should the nurse anticipate?', '[{"id": "a", "text": "Document a reactive test and schedule routine follow-up"}, {"id": "b", "text": "Continue the same test for another 40 minutes first"}, {"id": "c", "text": "Discharge the client since one acceleration is reassuring"}, {"id": "d", "text": "Prepare for further evaluation such as a BPP or CST"}]'::jsonb, '["d"]', 'A reactive NST requires at least 2 qualifying accelerations in 20 minutes; failing to meet criteria in 40 minutes is nonreactive and requires further evaluation such as BPP, CST, or delivery if indicated.'),
  ('antepartum', 33, 'During a 20-minute non-stress test at 36 weeks, the nurse notes three accelerations: 20 bpm for 20 seconds, 16 bpm for 15 seconds, and 12 bpm for 25 seconds. Which interpretation is BEST?', '[{"id": "a", "text": "Reactive; two accelerations meet the criteria"}, {"id": "b", "text": "Nonreactive; one acceleration is too small to count"}, {"id": "c", "text": "Nonreactive; each acceleration must qualify"}, {"id": "d", "text": "Equivocal; repeat the test in 24 hours"}]'::jsonb, '["a"]', 'A reactive NST has at least 2 accelerations of at least 15 bpm lasting at least 15 seconds in 20 minutes. Two of the three accelerations qualify, so the test is reactive and reassuring.'),
  ('antepartum', 34, 'A client at 34 weeks has a biophysical profile: one breathing episode of 40 seconds, largest fluid pocket 1.5 cm, two discrete body movements in 30 minutes, one extension with return to flexion, and a reactive NST. Which plan should the nurse anticipate?', '[{"id": "a", "text": "Immediate delivery for an abnormal score of 4"}, {"id": "b", "text": "Repeat the BPP in 24 hours for a score of 6"}, {"id": "c", "text": "Routine monitoring for a normal score of 8"}, {"id": "d", "text": "Delivery now for an equivocal score of 6"}]'::jsonb, '["b"]', 'Breathing, tone, and NST score 2 each; fluid under 2 cm and fewer than 3 movements score 0, totaling 6 (equivocal). Before 36 weeks, an equivocal BPP is repeated in 24 hours.'),
  ('antepartum', 35, 'A client at 37 weeks has a BPP with no fetal breathing in 30 minutes, a largest fluid pocket of 3 cm, four body movements, extension with return to flexion, and a nonreactive NST. Which interpretation is BEST?', '[{"id": "a", "text": "Score of 8; continue routine monitoring"}, {"id": "b", "text": "Score of 4; immediate intervention"}, {"id": "c", "text": "Score of 6; delivery may be considered"}, {"id": "d", "text": "Score of 10; fully reassuring result"}]'::jsonb, '["c"]', 'Fluid, movement, and tone score 2 each, while breathing and the NST score 0, totaling 6 (equivocal). At 36 weeks or more, delivery may be considered.'),
  ('antepartum', 36, 'A client at 33 weeks has a BPP with no breathing episodes, a largest fluid pocket of 1 cm, three discrete body movements, extension with return to flexion, and a nonreactive NST. Which action is the PRIORITY?', '[{"id": "a", "text": "Repeat the BPP in 24 hours"}, {"id": "b", "text": "Continue weekly NST monitoring"}, {"id": "c", "text": "Begin daily fetal kick counts at home tonight"}, {"id": "d", "text": "Notify the provider for immediate action"}]'::jsonb, '["d"]', 'Movement and tone score 2 each and the other three parameters score 0, for a total of 4. A BPP of 4 or less is abnormal and requires immediate intervention; repeating in 24 hours applies to a score of 6.'),
  ('antepartum', 37, 'The nurse is returning phone calls from four pregnant clients. Which client should the nurse call FIRST?', '[{"id": "a", "text": "34 weeks: sudden swelling of her face and hands since morning"}, {"id": "b", "text": "32 weeks: ankle swelling at the day''s end that improves with rest"}, {"id": "c", "text": "26 weeks: heartburn after large meals, relieved by antacids"}, {"id": "d", "text": "30 weeks: irregular painless tightening that eases with rest"}]'::jsonb, '["a"]', 'Sudden swelling of the face and hands is a danger sign of preeclampsia that must be reported immediately. Ankle edema, heartburn, and Braxton Hicks contractions are common discomforts of pregnancy.'),
  ('antepartum', 38, 'A client at 24 weeks calls reporting a temperature of 100.6°F (38.1°C) and body aches since last night. She asks whether she can wait until her visit in 4 weeks. Which response by the nurse is BEST?', '[{"id": "a", "text": "Rest and recheck in 24 hours, since it is under the limit"}, {"id": "b", "text": "This temperature should be reported to the provider now"}, {"id": "c", "text": "Take a warm bath and wait until the visit in 4 weeks"}, {"id": "d", "text": "Increase fluids; fever is reportable once it tops 101°F"}]'::jsonb, '["b"]', 'A fever above 100.4°F (38°C) is a danger sign that should be reported to the provider immediately; 100.6°F exceeds that threshold.'),
  ('antepartum', 39, 'A client at 33 weeks reports a slow trickle of clear fluid from her vagina since last night, with no contractions. She assumes it is urine leakage from the pressure of pregnancy. Which action by the nurse is BEST?', '[{"id": "a", "text": "Teach Kegel exercises to reduce the urine leakage now"}, {"id": "b", "text": "Advise limiting fluids during the evening hours"}, {"id": "c", "text": "Instruct her to come in for evaluation right away"}, {"id": "d", "text": "Reassure her that leakage is normal at this stage"}]'::jsonb, '["c"]', 'A gush or trickle of fluid from the vagina may indicate PROM and is a danger sign to report immediately. Kegel exercises and limiting evening fluids address urinary frequency, not possible ruptured membranes.'),
  ('antepartum', 40, 'A client at 22 weeks reports a small amount of bright red spotting on toilet tissue this morning, without pain or cramping. Which response by the nurse is BEST?', '[{"id": "a", "text": "Spotting is common; mention it at the next visit."}, {"id": "b", "text": "Rest today and call back only if bleeding becomes heavy."}, {"id": "c", "text": "Wear a pad and count pads for 24 hours before calling."}, {"id": "d", "text": "Bleeding at this stage needs to be reported right away."}]'::jsonb, '["d"]', 'Vaginal bleeding of any amount after the first trimester is a danger sign that must be reported to the provider immediately. Waiting to see whether bleeding increases delays evaluation.'),
  ('antepartum', 41, 'A client at 30 weeks calls reporting that she urinates frequently and that urination has started to burn over the past day. Which response by the nurse is BEST?', '[{"id": "a", "text": "Burning with urination should be reported for evaluation."}, {"id": "b", "text": "Frequency is expected now, so increase Kegel exercises."}, {"id": "c", "text": "Limit fluids at night to reduce frequency and burning."}, {"id": "d", "text": "Burning is from uterine pressure and will pass after birth."}]'::jsonb, '["a"]', 'Urinary frequency is a common third-trimester discomfort, but burning with urination suggests a UTI and is a danger sign to report. Kegel exercises and nighttime fluid limits do not address infection.'),
  ('antepartum', 42, 'A client at 30 weeks wakes at night with painful calf cramps. The nurse reviews how she has been managing them. Which action by the client requires correction FIRST?', '[{"id": "a", "text": "Stretching the calf muscle when a cramp starts"}, {"id": "b", "text": "Pointing her toes downward to ease the cramp"}, {"id": "c", "text": "Including calcium and magnesium in her diet"}, {"id": "d", "text": "Gently stretching her calves before bedtime"}]'::jsonb, '["b"]', 'Leg cramps are managed by stretching the calf muscle, getting adequate calcium and magnesium, and avoiding pointing the toes. Pointing the toes is the action to correct.'),
  ('antepartum', 43, 'A client at 26 weeks reports heartburn after dinner most evenings and is taught self-care measures. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I''ll eat smaller meals more often throughout the day."}, {"id": "b", "text": "I can use calcium carbonate antacids if needed."}, {"id": "c", "text": "I''ll lie down for a nap right after I eat dinner."}, {"id": "d", "text": "I''ll raise the head of my bed when I sleep."}]'::jsonb, '["c"]', 'Heartburn is managed with small meals, avoiding lying down after eating, calcium carbonate antacids, and elevating the head of the bed. Lying down right after a meal worsens it.'),
  ('antepartum', 44, 'A client at 32 weeks with varicose veins in both legs works long shifts as a receptionist. Which of her current behaviors should the nurse address FIRST?', '[{"id": "a", "text": "Wearing support stockings during her workday"}, {"id": "b", "text": "Elevating her legs during her lunch break"}, {"id": "c", "text": "Walking around the office every hour"}, {"id": "d", "text": "Sitting at her desk with her legs crossed"}]'::jsonb, '["d"]', 'Varicosities are managed with support stockings, leg elevation, regular ambulation, and avoiding crossing the legs. Sitting with crossed legs is the behavior to change.'),
  ('antepartum', 45, 'A client at 24 weeks reports low back pain at the end of her workday and asks how to relieve it. Which recommendation by the nurse is BEST?', '[{"id": "a", "text": "Do pelvic tilt exercises and wear supportive shoes"}, {"id": "b", "text": "Wear high-heeled shoes to improve her posture"}, {"id": "c", "text": "Avoid all exercise and activity until the baby is born"}, {"id": "d", "text": "Lie flat on her back for an hour after work"}]'::jsonb, '["a"]', 'Backache is managed with good posture, supportive shoes, a maternity belt, and pelvic tilt exercises, and high heels are avoided.'),
  ('antepartum', 46, 'A client at 35 weeks reports insomnia and feeling lightheaded when she lies flat on her back at night. Which sleep position should the nurse recommend as BEST?', '[{"id": "a", "text": "Supine with a pillow under her knees"}, {"id": "b", "text": "Left side-lying with a pillow between her knees"}, {"id": "c", "text": "Right side-lying with both of her legs fully extended"}, {"id": "d", "text": "Semi-prone with pillows placed under her hips"}]'::jsonb, '["b"]', 'Left side-lying with a pillow between the knees helps insomnia, and the left lateral position best supports uteroplacental perfusion by avoiding aortocaval compression.'),
  ('antepartum', 47, 'A client at 31 weeks reports irregular, painless tightening of her abdomen that eases when she rests and drinks water. She has no fluid leakage, bleeding, or decreased fetal movement. Which response by the nurse is BEST?', '[{"id": "a", "text": "Go to labor and delivery now for a preterm labor evaluation"}, {"id": "b", "text": "Lie flat on your back until the tightening has stopped"}, {"id": "c", "text": "These are likely Braxton Hicks; hydrate, rest, reposition"}, {"id": "d", "text": "Count kicks for 30 minutes and call if fewer than 10"}]'::jsonb, '["c"]', 'Irregular, painless tightening relieved by rest and hydration fits Braxton Hicks contractions, which are managed with reassurance, hydration, rest, and position change while distinguishing them from true labor.'),
  ('antepartum', 48, 'A client at 10 weeks with bothersome urinary frequency describes her plan for managing it. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "I''ll do Kegel exercises several times a day."}, {"id": "b", "text": "I''ll empty my bladder right before I go to bed."}, {"id": "c", "text": "I''ll drink less during the evening hours."}, {"id": "d", "text": "I''ll cut back on my fluids throughout the day."}]'::jsonb, '["d"]', 'Urinary frequency is managed with Kegel exercises, voiding before sleep, and limiting fluids at night while staying hydrated overall. Cutting fluids all day is incorrect.'),
  ('antepartum', 49, 'A woman who plans to try to conceive in about 6 months asks the nurse when she should begin taking a folic acid supplement. Which response by the nurse is BEST?', '[{"id": "a", "text": "Start 400 to 800 mcg daily now, before conception."}, {"id": "b", "text": "Start once a home pregnancy test turns positive for you."}, {"id": "c", "text": "Start in the second trimester along with iron."}, {"id": "d", "text": "Start after the anatomy ultrasound at 18-20 weeks."}]'::jsonb, '["a"]', 'Folic acid 400-800 mcg/day is started before conception to prevent neural tube defects. Waiting until pregnancy is confirmed or later misses the intended timing.'),
  ('antepartum', 50, 'At her first prenatal visit at 8 weeks, a client says she cleans her cats'' litter box daily and drinks wine on weekends. Which teaching is the PRIORITY at this visit?', '[{"id": "a", "text": "Keep doing litter care with gloves; limit wine to weekends"}, {"id": "b", "text": "Avoid alcohol, and have someone else handle the cat litter"}, {"id": "c", "text": "Avoid the litter box, but small amounts of wine are acceptable"}, {"id": "d", "text": "Stop the wine, but cat litter poses no pregnancy concern"}]'::jsonb, '["b"]', 'First-trimester counseling includes avoiding alcohol, smoking, and cat litter. Each of the other options leaves one of these exposures in place.'),
  ('gdm', 1, 'A G2P1 client at 26 weeks'' gestation who has no complaints completes a 1-hour 50-g glucose challenge test. Her result is 143 mg/dL, and she asks whether this means she has diabetes. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"This result confirms gestational diabetes, so you will start a diabetic meal plan and glucose checks today.\""}, {"id": "b", "text": "\"This screening result is above the cut-off, so the next step is a 3-hour test using 100 g of glucose.\""}, {"id": "c", "text": "\"This result falls within the expected screening range, so no further glucose testing is needed now.\""}, {"id": "d", "text": "\"This result should be rechecked with the same 1-hour screen at your 6-week postpartum visit.\""}]'::jsonb, '["b"]', 'On the 1-hour 50-g screen, a value above 140 mg/dL means the client proceeds to the 3-hour 100-g GTT. The screen itself does not diagnose GDM, so starting a GDM treatment plan now is premature.'),
  ('gdm', 2, 'A client at 27 weeks completes a 3-hour 100-g glucose tolerance test after an abnormal screen. Results: fasting 92 mg/dL, 1 hour 184 mg/dL, 2 hours 151 mg/dL, 3 hours 133 mg/dL. How should the nurse interpret these results?', '[{"id": "a", "text": "Gestational diabetes is confirmed, because the 1-hour value alone exceeds its diagnostic threshold"}, {"id": "b", "text": "Gestational diabetes is confirmed, because the fasting value is above the pregnancy fasting target"}, {"id": "c", "text": "Gestational diabetes is not diagnosed; one elevated value indicates impaired glucose tolerance"}, {"id": "d", "text": "The results are inconclusive, so the 50-g glucose challenge test must be repeated first"}]'::jsonb, '["c"]', 'Only the 1-hour value (184, limit 180) is abnormal; fasting 92 (<95), 2-hour 151 (<155), and 3-hour 133 (<140) are normal. GDM needs 2 or more abnormal values, so a single elevated value is impaired glucose tolerance.'),
  ('gdm', 3, 'A client''s 3-hour 100-g GTT results are: fasting 97 mg/dL, 1 hour 176 mg/dL, 2 hours 158 mg/dL, and 3 hours 138 mg/dL. Which interpretation and initial plan should the nurse anticipate FIRST?', '[{"id": "a", "text": "GDM is not diagnosed; the 1-hour value is below 180 mg/dL, so routine care continues"}, {"id": "b", "text": "GDM is diagnosed; begin insulin now, since insulin is the preferred therapy in pregnancy"}, {"id": "c", "text": "GDM is not diagnosed; one value is high, so impaired glucose tolerance is documented"}, {"id": "d", "text": "GDM is diagnosed; begin medical nutrition therapy and exercise with glucose checks"}]'::jsonb, '["d"]', 'Fasting 97 (limit 95) and 2-hour 158 (limit 155) are both abnormal, so 2 values confirm GDM. Diet and exercise are the first-line treatment; insulin is preferred only when medication becomes necessary.'),
  ('gdm', 4, 'A client with GDM brings her glucose log to a prenatal visit. Readings: fasting 93 mg/dL, 1 hour after breakfast 138 mg/dL, 2 hours after lunch 124 mg/dL, and 1 hour after dinner 136 mg/dL. Which reading should the nurse report to the provider?', '[{"id": "a", "text": "Fasting, 93 mg/dL"}, {"id": "b", "text": "1 hour after breakfast, 138 mg/dL"}, {"id": "c", "text": "1 hour after dinner, 136 mg/dL"}, {"id": "d", "text": "2 hours after lunch, 124 mg/dL"}]'::jsonb, '["d"]', 'The 2-hour post-meal target is <120 mg/dL, so 124 mg/dL is above goal. The 1-hour readings of 136 and 138 are under the 1-hour target of <140, and 93 meets the fasting target of <95.'),
  ('gdm', 5, 'On review of a GDM client''s glucose diary, the nurse notes: fasting 96 mg/dL, 1 hour after breakfast 134 mg/dL, 2 hours after lunch 117 mg/dL, and 2 hours after dinner 115 mg/dL. Which value requires follow-up because it is outside the client''s target?', '[{"id": "a", "text": "1 hour after breakfast, 134 mg/dL"}, {"id": "b", "text": "Fasting, 96 mg/dL"}, {"id": "c", "text": "2 hours after lunch, 117 mg/dL"}, {"id": "d", "text": "2 hours after dinner, 115 mg/dL"}]'::jsonb, '["b"]', 'The fasting target in GDM is <95 mg/dL, so 96 is above goal. The 1-hour reading of 134 is under <140, and the 2-hour readings of 115 and 117 are under <120.'),
  ('gdm', 6, 'A clinic nurse reviews phone messages from four clients with GDM who are managed with diet and exercise. Which client''s reading should the nurse follow up on FIRST with the provider?', '[{"id": "a", "text": "Client reporting a fasting reading of 94 mg/dL this morning"}, {"id": "b", "text": "Client reporting a 2-hour post-lunch reading of 118 mg/dL"}, {"id": "c", "text": "Client reporting a 1-hour post-dinner reading of 143 mg/dL"}, {"id": "d", "text": "Client reporting a 1-hour post-breakfast reading of 137 mg/dL"}]'::jsonb, '["c"]', 'The 1-hour post-meal target is <140 mg/dL, so 143 is above goal and should be reported. The other readings are each just under their own targets (fasting <95, 1-hour <140, 2-hour <120).'),
  ('gdm', 7, 'A client diagnosed with GDM at 28 weeks has followed her meal plan and walked daily for 2 weeks. Her fasting readings remain 100–104 mg/dL, and most 1-hour post-meal readings are 146–152 mg/dL. Which treatment should the nurse anticipate NEXT?', '[{"id": "a", "text": "Continuing diet alone until birth, then retesting glucose at 6–12 weeks postpartum"}, {"id": "b", "text": "Adding glyburide, because oral agents are preferred over injections in pregnancy"}, {"id": "c", "text": "Adding insulin, the preferred medication for glucose control in pregnancy"}, {"id": "d", "text": "Removing carbohydrates from meals and snacks until fasting values reach target"}]'::jsonb, '["c"]', 'When glucose stays above target after 1–2 weeks of diet and exercise, medication is added, and insulin is preferred. Oral agents are only sometimes used, and carbohydrates are distributed rather than eliminated.'),
  ('gdm', 8, 'A client at 25 weeks has just learned that her 3-hour GTT showed a fasting value of 98 mg/dL and a 2-hour value of 160 mg/dL, with the other two values normal. She says, "Just give me the insulin so I don''t hurt my baby." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Insulin will start today, because two abnormal values require medication right away.\""}, {"id": "b", "text": "\"Glyburide pills will be started first, and insulin is added if the pills do not work.\""}, {"id": "c", "text": "\"You do not have diabetes yet, because a second screening test is needed to confirm it.\""}, {"id": "d", "text": "\"Diet changes and exercise are the first treatment; medicine is added if they aren''t enough.\""}]'::jsonb, '["d"]', 'Two abnormal GTT values confirm GDM, and the first treatment is diet plus exercise, with insulin added if needed. Starting insulin immediately skips the first-line step, and oral agents are not the preferred medication.'),
  ('gdm', 9, 'A client with GDM whose glucose stayed above target despite 2 weeks of diet therapy is starting insulin. She asks why she cannot take a pill like her aunt who has type 2 diabetes. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"Insulin is used because it does not cross the placenta to my baby.\""}, {"id": "b", "text": "\"Glyburide would be better because none of it reaches my baby.\""}, {"id": "c", "text": "\"Pills such as glyburide or metformin are sometimes used in pregnancy.\""}, {"id": "d", "text": "\"Insulin has the longest safety record of the GDM medications.\""}]'::jsonb, '["b"]', 'Glyburide crosses the placenta in small amounts, so the client''s belief is incorrect. Insulin is preferred because it does not cross the placenta, is highly effective, and has the longest safety record.'),
  ('gdm', 10, 'A nurse reviews a meal plan with a client at 29 weeks newly diagnosed with GDM. Her readings this week were fasting 89–93 mg/dL and 2-hour post-meal 110–118 mg/dL. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will spread my carbohydrates over three small meals and two or three snacks.\""}, {"id": "b", "text": "\"I will keep my carbohydrate portions consistent at each meal and snack.\""}, {"id": "c", "text": "\"I will skip my bedtime snack so my morning fasting reading stays low.\""}, {"id": "d", "text": "\"I will include some protein with my bedtime snack to prevent low sugar overnight.\""}]'::jsonb, '["c"]', 'A bedtime snack, often with protein, is part of GDM nutrition therapy to prevent overnight hypoglycemia, so skipping it is incorrect. Distributing consistent carbohydrate portions across meals and snacks is the correct approach.'),
  ('gdm', 11, 'A client with GDM at 29 weeks has 1-hour post-meal readings of 145–150 mg/dL after large pasta lunches, with all other readings at target. Which instruction given by a student nurse requires correction by the nurse?', '[{"id": "a", "text": "\"Remove all carbohydrates from your diet until your baby is born.\""}, {"id": "b", "text": "\"Divide your carbohydrates across smaller meals and between-meal snacks.\""}, {"id": "c", "text": "\"Keep recording your readings before and after your meals each day.\""}, {"id": "d", "text": "\"Ask about meeting with a registered dietitian to review your meal plan.\""}]'::jsonb, '["a"]', 'GDM nutrition therapy distributes carbohydrates rather than eliminating them, to prevent post-meal spikes. Smaller, spread-out carbohydrate portions, glucose logging, and dietitian referral are all appropriate.'),
  ('gdm', 12, 'A 4,250-g newborn of a mother with GDM is pink, crying, and rooting at 50 minutes of life and shows no other abnormal findings. The heel-stick glucose is 36 mg/dL. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Start an IV dextrose infusion and recheck the glucose level in 4 hours"}, {"id": "b", "text": "Recheck the heel-stick glucose at 4 hours of life before any feeding"}, {"id": "c", "text": "Complete the bath and measurements before offering the first feeding"}, {"id": "d", "text": "Feed the newborn now and recheck the glucose in 30 to 60 minutes"}]'::jsonb, '["d"]', 'In an asymptomatic newborn, a glucose below 40–45 mg/dL is first treated with early feeding and rechecked 30–60 minutes later. IV dextrose is reserved for an infant who cannot feed or whose glucose remains critically low (<25 mg/dL).'),
  ('gdm', 13, 'A newborn of a mother with insulin-treated GDM makes no attempt to suck at the breast or from a bottle at 1 hour of life. The heel-stick glucose is 22 mg/dL. Which intervention should the nurse anticipate as the PRIORITY?', '[{"id": "a", "text": "Encourage another breastfeeding attempt and recheck the level in 1 hour"}, {"id": "b", "text": "Prepare for IV dextrose administration as prescribed by the provider"}, {"id": "c", "text": "Delay treatment until a second heel stick confirms the result in 2 hours"}, {"id": "d", "text": "Document the value as expected for a newborn of a mother with GDM"}]'::jsonb, '["b"]', 'IV dextrose is used when the newborn cannot feed or glucose is critically low (<25 mg/dL); this infant meets both conditions. Early feeding is the first step only for an infant who is able to feed.'),
  ('gdm', 14, 'A client with insulin-treated GDM gives birth to a 4,400-g newborn. The 1- and 5-minute APGAR scores are 8 and 9, and the newborn is now 20 minutes old and stable under the radiant warmer. Which assessment is the nurse''s PRIORITY within the next 40 minutes?', '[{"id": "a", "text": "Repeat APGAR scoring at 10 minutes to confirm the newborn''s stability"}, {"id": "b", "text": "Check the mother''s fasting glucose to confirm her GDM has resolved"}, {"id": "c", "text": "Obtain a heel-stick blood glucose level on the newborn"}, {"id": "d", "text": "Assess for arm weakness suggesting a brachial plexus birth injury"}]'::jsonb, '["c"]', 'Neonatal hypoglycemia is the most immediate threat to an infant of a mother with GDM, so glucose must be checked within 30–60 minutes of birth. APGAR scores are already done, and nothing suggests shoulder dystocia or a brachial plexus injury.'),
  ('gdm', 15, 'A mother with GDM asks why her newborn''s blood glucose was 39 mg/dL at 45 minutes of life, saying, "My sugar was the problem, not the baby''s." Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Your baby inherited diabetes from you, so the baby''s pancreas is not making enough insulin.\""}, {"id": "b", "text": "\"Your insulin crossed the placenta before delivery and is still lowering your baby''s sugar.\""}, {"id": "c", "text": "\"Your baby made extra insulin before birth, and it kept working after your sugar supply stopped.\""}, {"id": "d", "text": "\"Your baby used up stored sugar during labor and birth, which is unrelated to your diabetes.\""}]'::jsonb, '["c"]', 'Chronic exposure to high maternal glucose makes the fetal pancreas overproduce insulin; at birth the glucose supply stops but fetal insulin stays high. Maternal insulin does not cross the placenta, so the claim that maternal insulin is still acting is wrong.'),
  ('gdm', 16, 'A client with GDM at 39 weeks is admitted in active labor. Ultrasound earlier this week estimated fetal weight at 4,600 g. For which delivery complication should the nurse be MOST prepared?', '[{"id": "a", "text": "Cord compression from too little amniotic fluid around the fetus"}, {"id": "b", "text": "The fetal shoulders becoming stuck after the head delivers"}, {"id": "c", "text": "Delivery of a small-for-gestational-age, growth-restricted newborn"}, {"id": "d", "text": "Neonatal hyperglycemia requiring insulin shortly after birth"}]'::jsonb, '["b"]', 'An estimated weight of 4,600 g is macrosomic (>4,000–4,500 g), which places the fetus at risk for shoulder dystocia. GDM is associated with excess, not reduced, amniotic fluid and with neonatal hypoglycemia, not hyperglycemia.'),
  ('gdm', 17, 'A client with GDM at 38 weeks asks why her provider has mentioned a possible cesarean birth. Ultrasound estimates fetal weight at 4,650 g, and her glucose readings have been near target. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"A cesarean is required for every client with GDM, whatever the baby''s size.\""}, {"id": "b", "text": "\"A cesarean birth prevents your baby''s blood sugar from dropping after birth.\""}, {"id": "c", "text": "\"A cesarean is planned because GDM makes the placenta stop working early.\""}, {"id": "d", "text": "\"A very large baby raises the risk of a difficult birth, so a cesarean may be needed.\""}]'::jsonb, '["d"]', 'GDM raises the risk of C-section because of a large baby; macrosomic babies risk shoulder dystocia and birth trauma. Neonatal hypoglycemia results from fetal hyperinsulinemia and is not prevented by the mode of birth.'),
  ('gdm', 18, 'At 32 weeks, a client with GDM whose post-meal readings have often been above target reports abdominal discomfort, and ultrasound shows excess amniotic fluid. She asks what caused the extra fluid. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"High glucose reaching the baby makes the baby pass more urine into the fluid.\""}, {"id": "b", "text": "\"Your own high glucose makes you urinate more, and that fluid collects around the baby.\""}, {"id": "c", "text": "\"Insulin crossing the placenta makes the baby''s kidneys hold on to extra fluid.\""}, {"id": "d", "text": "\"Low glucose in the baby slows the baby''s growth, so less fluid is removed.\""}]'::jsonb, '["a"]', 'Fetal hyperglycemia acts as an osmotic diuretic, causing fetal polyuria and polyhydramnios. It is the fetus''s urine output, not the mother''s, that increases, and insulin does not cross the placenta.'),
  ('gdm', 19, 'A client with GDM at 31 weeks has polyhydramnios on ultrasound and is being monitored as an outpatient. Which finding reported by the client during a phone call requires the nurse''s IMMEDIATE follow-up?', '[{"id": "a", "text": "Abdominal fullness and discomfort that are worse after large meals"}, {"id": "b", "text": "A fasting glucose reading of 93 mg/dL obtained this morning"}, {"id": "c", "text": "Regular tightening of her abdomen every 6 minutes for the past hour"}, {"id": "d", "text": "A 2-hour post-breakfast glucose reading of 117 mg/dL today"}]'::jsonb, '["c"]', 'Polyhydramnios can cause preterm labor, and regular contractions at 31 weeks must be evaluated now. Maternal discomfort is an expected effect of excess fluid, and both glucose readings are within target.'),
  ('gdm', 20, 'A nurse on a mother-baby unit receives report on four clients at the start of the shift. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A mother with GDM, 2 days postpartum, whose fasting glucose this morning was 88 mg/dL"}, {"id": "b", "text": "A mother with GDM, 1 day postpartum, asking when her follow-up glucose test should be done"}, {"id": "c", "text": "A 4,350-g newborn of a mother with GDM, 35 minutes old, whose glucose has not been checked"}, {"id": "d", "text": "A mother with GDM, 1 day postpartum, who reports vaginal itching and a thick white discharge"}]'::jsonb, '["c"]', 'Hypoglycemia is the most immediate threat to a newborn of a mother with GDM, and glucose must be checked within 30–60 minutes of birth. The other concerns are real but not immediately dangerous.'),
  ('gdm', 21, 'A client who required insulin for GDM has normal glucose readings on postpartum day 2 and is being discharged. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll have a 75-g glucose tolerance test between 6 and 12 weeks after the birth.\""}, {"id": "b", "text": "\"If that test is normal, I should still be screened again every 1 to 3 years.\""}, {"id": "c", "text": "\"Because my sugars are normal now, I won''t need diabetes testing in the future.\""}, {"id": "d", "text": "\"Having had GDM raises my risk of developing type 2 diabetes later in life.\""}]'::jsonb, '["c"]', 'Even when postpartum results are normal, screening continues every 1–3 years because of the long-term risk of type 2 diabetes. The 75-g OGTT at 6–12 weeks and the increased type 2 diabetes risk are correct statements.'),
  ('gdm', 22, 'On postpartum day 1, a client who needed insulin for GDM at 36 weeks has a fasting glucose of 84 mg/dL without any insulin. She asks why her diabetes "disappeared overnight." Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Your pancreas has been permanently repaired, so your future risk is gone too.\""}, {"id": "b", "text": "\"The insulin you took in pregnancy is still lowering your glucose levels now.\""}, {"id": "c", "text": "\"Your baby was producing the extra sugar, so the problem left with the birth.\""}, {"id": "d", "text": "\"Delivering the placenta removed the hormones that blocked your insulin.\""}]'::jsonb, '["d"]', 'GDM is caused by placental hormones that create insulin resistance; once the placenta is delivered, insulin sensitivity returns to baseline. The underlying pancreatic vulnerability persists, so long-term risk does not disappear.'),
  ('gdm', 23, 'A client with GDM at 34 weeks is upset because her insulin dose has been increased twice in 3 weeks even though she has followed the same meal plan and her log is complete. She asks, "What am I doing wrong?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Rising doses suggest you are eating more carbohydrate than your log is showing.\""}, {"id": "b", "text": "\"Your pancreas is being damaged by the pregnancy and is making less insulin each week.\""}, {"id": "c", "text": "\"As the placenta grows it makes more insulin-blocking hormones, so needs often rise.\""}, {"id": "d", "text": "\"Your baby is now making insulin that cancels out the insulin you are injecting.\""}]'::jsonb, '["c"]', 'The growing placenta makes progressively more hPL, progesterone, and cortisol, so insulin resistance and insulin needs can rise in the third trimester without dietary change. Nothing in the data suggests dietary nonadherence.'),
  ('gdm', 24, 'Before discharge, a client whose GDM was controlled by diet alone asks whether she needs to worry about diabetes after this pregnancy. Her postpartum fasting glucose is 82 mg/dL. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Your future risk is mainly preeclampsia in later pregnancies rather than diabetes.\""}, {"id": "b", "text": "\"Because diet alone controlled it, your future risk is the same as women without GDM.\""}, {"id": "c", "text": "\"Your normal glucose today shows your pancreas fully recovered, so no follow-up is needed.\""}, {"id": "d", "text": "\"Your risk of type 2 diabetes later is higher, so screening and lifestyle changes matter.\""}]'::jsonb, '["d"]', 'Women with GDM have a significantly elevated risk of type 2 diabetes later in life, so follow-up and lifestyle modification after delivery are critical. A normal postpartum value does not remove this long-term risk.'),
  ('gdm', 25, 'At a routine visit at 20 weeks, a client''s urine dipstick is positive for glucose. She has not yet had her glucose challenge test, and she reports no symptoms. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Begin teaching insulin self-injection, because glycosuria confirms GDM today"}, {"id": "b", "text": "Document it as expected and wait for the 24–28-week screen without reporting it"}, {"id": "c", "text": "Report the finding, because glucose in the urine is a warning sign for GDM"}, {"id": "d", "text": "Schedule a 75-g OGTT for 6 weeks postpartum, because glycosuria predicts diabetes"}]'::jsonb, '["c"]', 'Urine glucose is a warning sign for GDM and should be reported rather than dismissed. Glycosuria does not diagnose GDM; diagnosis requires the GTT, so starting insulin is premature.'),
  ('gdm', 26, 'A client with no risk factors for diabetes is at her 18-week prenatal visit and asks when she will be tested for gestational diabetes. Her upcoming visits are at 22, 26, 30, and 34 weeks. At which visit should the nurse expect the 1-hour glucose challenge test to be done?', '[{"id": "a", "text": "The 22-week visit"}, {"id": "b", "text": "The 26-week visit"}, {"id": "c", "text": "The 30-week visit"}, {"id": "d", "text": "The 34-week visit"}]'::jsonb, '["b"]', 'Routine GDM screening for average-risk women is done at 24–28 weeks, so the 26-week visit falls in the window. The 22-week visit is too early and the 30- and 34-week visits are past the routine window.'),
  ('gdm', 27, 'At her first prenatal visit at 10 weeks, a client''s provider documents that she is at high risk for GDM. The client says she was told glucose screening "always happens at 24 to 28 weeks." Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"High-risk clients may be screened now, at the first prenatal visit.\""}, {"id": "b", "text": "\"Screening waits until 24 to 28 weeks for every client, whatever the risk.\""}, {"id": "c", "text": "\"High-risk clients skip screening and go straight to insulin therapy.\""}, {"id": "d", "text": "\"High-risk clients are screened only after the birth, at 6 to 12 weeks.\""}]'::jsonb, '["a"]', 'Average-risk women are screened at 24–28 weeks, but high-risk women may be screened at the first prenatal visit. Diagnosis still requires testing, and the 6–12-week test is the postpartum recheck.'),
  ('gdm', 28, 'A client at her 9-week visit who has no risk factors asks why she must wait until later in pregnancy for diabetes screening when her friend "was tested right away." Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Insulin resistance is highest in the first trimester, so later results are more reliable.\""}, {"id": "b", "text": "\"Your baby''s pancreas does not begin making insulin until the third trimester.\""}, {"id": "c", "text": "\"Placental hormones that cause insulin resistance are peaking by 24 to 28 weeks.\""}, {"id": "d", "text": "\"Screening is timed for when the baby is large enough to measure macrosomia.\""}]'::jsonb, '["c"]', 'Screening at 24–28 weeks corresponds to when hPL, progesterone, and cortisol from the placenta are peaking and causing insulin resistance. High-risk women may be screened at the first visit, which may explain the friend''s early test.'),
  ('gdm', 29, 'A client whose 1-hour glucose challenge result was 152 mg/dL is scheduled for her follow-up diagnostic test tomorrow morning. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"My blood will be drawn once before I drink the glucose solution.\""}, {"id": "b", "text": "\"I will be given a 100-gram glucose drink during the test.\""}, {"id": "c", "text": "\"My blood will be tested at 1, 2, and 3 hours after the drink.\""}, {"id": "d", "text": "\"I will eat my usual breakfast before I arrive for the test.\""}]'::jsonb, '["d"]', 'The 3-hour 100-g GTT begins with a fasting sample, so eating breakfast first is incorrect. The other statements describe the test correctly: fasting draw, 100 g of glucose, then samples at 1, 2, and 3 hours.'),
  ('gdm', 30, 'A nurse is planning care for a client at 24 weeks who has not yet been screened for GDM. Assuming each step produces results that require the next step, which sequence reflects the correct order of evaluation and management?', '[{"id": "a", "text": "50-g 1-hour screen → 100-g 3-hour GTT → diet and exercise → insulin"}, {"id": "b", "text": "100-g 3-hour GTT → 50-g 1-hour screen → insulin → diet and exercise"}, {"id": "c", "text": "50-g 1-hour screen → diet and exercise → 100-g 3-hour GTT → start insulin"}, {"id": "d", "text": "50-g 1-hour screen → 100-g 3-hour GTT → insulin → diet and exercise"}]'::jsonb, '["a"]', 'The 50-g challenge screens, and a value above 140 mg/dL leads to the diagnostic 100-g GTT. After diagnosis, diet and exercise come first, and insulin is added if needed.'),
  ('gdm', 31, 'A client with GDM at 30 weeks calls the clinic reporting burning on urination and a thick, itchy vaginal discharge for 2 days. Her glucose log shows several 1-hour post-meal readings of 148–155 mg/dL. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Her readings are within target, so her infection risk is unrelated to her GDM"}, {"id": "b", "text": "Her symptoms are expected pregnancy changes that need no follow-up at this time"}, {"id": "c", "text": "Her symptoms suggest polyhydramnios pressing on the bladder and vaginal tissues"}, {"id": "d", "text": "Her symptoms fit infections that occur more often with GDM and need evaluation"}]'::jsonb, '["d"]', 'Women with GDM have higher rates of UTIs and yeast infections, and her symptoms suggest both. Her 1-hour readings exceed the <140 mg/dL target, so calling them within target misreads the data.'),
  ('gdm', 32, 'A client was diagnosed with GDM after her 3-hour GTT showed a fasting value of 99 mg/dL and a 3-hour value of 146 mg/dL. She is learning to monitor her glucose at home. Which statement indicates correct understanding?', '[{"id": "a", "text": "\"I''ll check my sugar once a day, before I eat breakfast.\""}, {"id": "b", "text": "\"I''ll check my sugar fasting and again after my meals.\""}, {"id": "c", "text": "\"I''ll check my sugar whenever I feel shaky or dizzy.\""}, {"id": "d", "text": "\"I''ll have my sugar checked weekly at clinic visits.\""}]'::jsonb, '["b"]', 'Clients with GDM check blood sugar often, before and after meals, so fasting and post-meal checks are correct. A single daily fasting check misses post-meal spikes that have their own targets.'),
  ('gdm', 33, 'A 4,300-g newborn of a mother with GDM is 25 minutes old, and the heel-stick glucose has not yet been obtained. Which statement by the unlicensed assistive personnel (UAP) to the mother requires the nurse to intervene?', '[{"id": "a", "text": "\"I''m bringing the glucose meter so the nurse can check your baby''s sugar.\""}, {"id": "b", "text": "\"Your baby''s sugar will be checked after the bath, at about 2 hours old.\""}, {"id": "c", "text": "\"The nurse will help you start the first feeding within this first hour.\""}, {"id": "d", "text": "\"Your baby''s sugar may be checked again after the first feeding is done.\""}]'::jsonb, '["b"]', 'Glucose must be checked within 30–60 minutes of birth in an infant of a mother with GDM, so waiting until 2 hours is unsafe. Early feeding within the first hour and a recheck after feeding are appropriate.'),
  ('gdm', 34, 'A newborn of a mother with GDM had a heel-stick glucose of 38 mg/dL at 40 minutes of life and then breastfed well for 15 minutes. The glucose rechecked 45 minutes after the feeding is 58 mg/dL. How should the nurse evaluate this result?', '[{"id": "a", "text": "The feeding was effective; the glucose is no longer in the hypoglycemic range"}, {"id": "b", "text": "The value is still low, so IV dextrose should be started before the next feeding"}, {"id": "c", "text": "The value is unreliable; glucose should not be rechecked until 4 hours of life"}, {"id": "d", "text": "The value indicates neonatal hyperglycemia from the mother''s high glucose"}]'::jsonb, '["a"]', 'Glucose is rechecked 30–60 minutes after feeding to confirm response; 58 mg/dL is above the <40–45 mg/dL hypoglycemia range, so feeding worked. IV dextrose is for infants who cannot feed or remain below 25 mg/dL.'),
  ('gdm', 35, 'A client with GDM at 33 weeks started insulin last week after her fasting values stayed at 99–103 mg/dL. Ultrasound now shows the fetus measuring large, and she asks, "Is my insulin shot making the baby big?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"No; extra glucose crosses to the baby, whose own insulin then boosts growth and fat.\""}, {"id": "b", "text": "\"Yes; the injected insulin crosses the placenta and acts as a growth hormone in the baby.\""}, {"id": "c", "text": "\"No; large size comes from too little amniotic fluid limiting the baby''s movement.\""}, {"id": "d", "text": "\"Yes; the insulin raises your glucose, which then crosses into the baby''s circulation.\""}]'::jsonb, '["a"]', 'Maternal glucose crosses the placenta and stimulates the fetal pancreas to make excess insulin, which acts as a growth hormone in utero and causes macrosomia. Injected insulin does not cross the placenta.'),
  ('gdm', 36, 'A client with GDM says her mother, who has type 2 diabetes, was told a fasting glucose of 110 mg/dL was acceptable. The client''s fasting reading today is 101 mg/dL, and she asks why her own goal is stricter. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Your fasting reading of 101 mg/dL is already within your goal, so it is not stricter.\""}, {"id": "b", "text": "\"Pregnancy goals are stricter mainly to keep your own glucose from dropping low at night.\""}, {"id": "c", "text": "\"Your goal is stricter because GDM turns into type 2 diabetes right after the birth.\""}, {"id": "d", "text": "\"Even mildly high glucose crosses the placenta and makes your baby produce extra insulin.\""}]'::jsonb, '["d"]', 'GDM targets are tighter than non-pregnancy targets because even mild hyperglycemia crosses the placenta, driving fetal hyperinsulinemia and macrosomia. A fasting value of 101 is above the <95 mg/dL target.'),
  ('gdm', 37, 'A client at 27 weeks who has no symptoms completes a 1-hour 50-g glucose challenge test, and the result is 126 mg/dL. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Schedule the 3-hour 100-g glucose tolerance test for this week"}, {"id": "b", "text": "Explain that the screen is not elevated and continue routine care"}, {"id": "c", "text": "Begin teaching glucose self-monitoring before and after each meal"}, {"id": "d", "text": "Explain that GDM is diagnosed and refer the client to a registered dietitian"}]'::jsonb, '["b"]', 'The 1-hour screen cut-off is ≥140 mg/dL (some use ≥130); 126 is below either threshold, so no diagnostic GTT is needed. Self-monitoring and GDM teaching apply only after a diagnosis.'),
  ('gdm', 38, 'A client''s 3-hour 100-g GTT values are: fasting 94 mg/dL, 1 hour 178 mg/dL, 2 hours 156 mg/dL, and 3 hours 141 mg/dL. She is relieved because her "first two numbers were normal." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Two of your values are above their limits, so GDM is diagnosed.\""}, {"id": "b", "text": "\"One value is high, so this shows impaired glucose tolerance, not GDM.\""}, {"id": "c", "text": "\"Your fasting and 1-hour values are normal, so this rules out GDM.\""}, {"id": "d", "text": "\"The test must be repeated because your fasting value is near the limit.\""}]'::jsonb, '["a"]', 'The 2-hour value (156, limit 155) and 3-hour value (141, limit 140) are both abnormal, and 2 or more abnormal values diagnose GDM. Normal fasting and 1-hour values do not rule it out.'),
  ('gdm', 39, 'A client at 30 weeks was diagnosed with GDM last month and is managed with diet. In addition to glucose monitoring, which maternal complication of this pregnancy is MOST important for the nurse to monitor for at each visit?', '[{"id": "a", "text": "Maternal hypoglycemia caused by placental hormones"}, {"id": "b", "text": "Oligohydramnios from reduced fetal urine output"}, {"id": "c", "text": "Preeclampsia during this pregnancy"}, {"id": "d", "text": "Fetal growth restriction from a low glucose supply"}]'::jsonb, '["c"]', 'GDM significantly raises the risk of preeclampsia during the current pregnancy. GDM causes excess amniotic fluid and fetal overgrowth, and placental hormones raise rather than lower maternal glucose.'),
  ('gdm', 40, 'A client at 26 weeks whose sister had GDM asks, "Does every pregnant woman become resistant to insulin, or just women who get diabetes?" Her own 1-hour screen was 118 mg/dL. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Insulin resistance in pregnancy happens because the baby''s pancreas takes your insulin.\""}, {"id": "b", "text": "\"Insulin resistance happens only in women who develop GDM and signals a damaged pancreas.\""}, {"id": "c", "text": "\"Insulin resistance occurs only in the first trimester and resolves by about 24 weeks.\""}, {"id": "d", "text": "\"All pregnant women develop some insulin resistance; GDM occurs when the pancreas can''t keep up.\""}]'::jsonb, '["d"]', 'Placental hormones create physiological insulin resistance in pregnancy to ensure glucose for the fetus; GDM results in women with insufficient pancreatic reserve. Resistance increases as pregnancy progresses rather than resolving.'),
  ('gdm', 41, 'A client with GDM is at her 6-week postpartum visit. Her glucose readings have been normal since delivery, and she asks which test she will have today to check her diabetes status. Which test should the nurse expect to be performed?', '[{"id": "a", "text": "A 1-hour 50-g glucose challenge test"}, {"id": "b", "text": "A 3-hour 100-g glucose tolerance test"}, {"id": "c", "text": "A 75-g oral glucose tolerance test"}, {"id": "d", "text": "A urine dipstick check for glucose"}]'::jsonb, '["c"]', 'A 75-g OGTT at 6–12 weeks postpartum assesses whether glucose metabolism has normalized. The 50-g screen and 100-g GTT are the pregnancy screening and diagnostic tests, and urine glucose is only a warning sign.'),
  ('gdm', 42, 'After 1 week of diet and exercise, a client with GDM at 29 weeks has these ranges: fasting 88–94 mg/dL, 1-hour post-meal 128–138 mg/dL, and 2-hour post-meal 108–118 mg/dL. Which evaluation by the nurse is MOST accurate?', '[{"id": "a", "text": "Treatment is effective, so glucose monitoring can stop until the birth"}, {"id": "b", "text": "Treatment is failing; values this close to the limits mean insulin should be started"}, {"id": "c", "text": "Treatment is failing; the 1-hour values exceed the 1-hour target for GDM"}, {"id": "d", "text": "Treatment is effective; all values meet target, so the current plan continues"}]'::jsonb, '["d"]', 'All values are under their targets (fasting <95, 1-hour <140, 2-hour <120), so diet and exercise are working. Medication is added only when values remain above target; being close to a limit is not failure.'),
  ('gdm', 43, 'A client at 4 hours postpartum had a 4,550-g newborn whose delivery was complicated by shoulder dystocia. She had GDM managed with insulin. Which assessment is the nurse''s PRIORITY for this client?', '[{"id": "a", "text": "Checking the amount of vaginal bleeding and the perineum"}, {"id": "b", "text": "Scheduling her 75-g glucose test for 6–12 weeks postpartum"}, {"id": "c", "text": "Asking whether she has had any vaginal itching or discharge"}, {"id": "d", "text": "Reviewing her prenatal log of fasting and post-meal readings"}]'::jsonb, '["a"]', 'Shoulder dystocia can cause maternal hemorrhage and perineal tears, so bleeding and perineal assessment take priority. Postpartum glucose testing and infection screening are important but not immediately life-threatening.'),
  ('gdm', 44, 'A nurse is reviewing the birth weights of four newborns, each born to a mother with GDM. Which newborn''s weight meets the definition of macrosomia and calls for close monitoring for birth injury?', '[{"id": "a", "text": "A newborn weighing 3,650 g"}, {"id": "b", "text": "A newborn weighing 3,880 g"}, {"id": "c", "text": "A newborn weighing 3,970 g"}, {"id": "d", "text": "A newborn weighing 4,520 g"}]'::jsonb, '["d"]', 'Macrosomia is a birth weight above 4,000–4,500 g, and 4,520 g exceeds even the upper limit. The other weights are below 4,000 g.'),
  ('gdm', 45, 'A client with GDM at 35 weeks has polyhydramnios. A bedside ultrasound shows that the fetus is not in a head-down position. Which polyhydramnios-related problem should the nurse recognize and report?', '[{"id": "a", "text": "Malpresentation of the fetus"}, {"id": "b", "text": "Neonatal hypoglycemia"}, {"id": "c", "text": "Shoulder dystocia at the time of birth"}, {"id": "d", "text": "Maternal type 2 diabetes"}]'::jsonb, '["a"]', 'Polyhydramnios can cause maternal discomfort, preterm labor, and malpresentation, and the finding suggests the fetus may not be head-down. Hypoglycemia and type 2 diabetes are GDM risks but do not explain this finding.'),
  ('gdm', 46, 'A nurse is caring for four newborns of mothers with GDM in the first 2 hours of life. Which newborn requires the nurse''s attention FIRST?', '[{"id": "a", "text": "Glucose 52 mg/dL at 1 hour, breastfeeding every 2–3 hours"}, {"id": "b", "text": "Glucose 47 mg/dL at 50 minutes, latched and feeding now"}, {"id": "c", "text": "Glucose 38 mg/dL at 40 minutes, rooting and ready to feed"}, {"id": "d", "text": "Glucose 21 mg/dL at 1 hour, unable to suck at breast or bottle"}]'::jsonb, '["d"]', 'A glucose below 25 mg/dL in an infant who cannot feed needs IV dextrose. The 38 mg/dL newborn can be fed first, and 47 and 52 mg/dL are above the <40–45 mg/dL hypoglycemia range.'),
  ('gdm', 47, 'A client with GDM checks her glucose 2 hours after dinner and gets 132 mg/dL. She tells the nurse, "That''s fine because it''s under 140." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"You''re right; 132 is within your target for after-meal readings.\""}, {"id": "b", "text": "\"That target applies at 1 hour; at 2 hours your goal is under 120.\""}, {"id": "c", "text": "\"That target applies to fasting; after meals your goal is under 180.\""}, {"id": "d", "text": "\"You''re right, but recheck it at 3 hours to make sure it is under 95.\""}]'::jsonb, '["b"]', 'The <140 mg/dL target applies 1 hour after a meal; the 2-hour post-meal target is <120 mg/dL, so 132 is above goal. Applying the 1-hour number to a 2-hour reading is the error.'),
  ('gdm', 48, 'A newborn of a mother with GDM has a heel-stick glucose of 37 mg/dL at 45 minutes of life and is alert and rooting. Which sequence of nursing actions is correct?', '[{"id": "a", "text": "Feed the newborn → recheck glucose in 30–60 minutes → notify if still low or unable to feed"}, {"id": "b", "text": "Start IV dextrose → feed the newborn → recheck glucose at 4 hours of life"}, {"id": "c", "text": "Recheck glucose in 2 hours → feed the newborn → start IV dextrose if the value is still low"}, {"id": "d", "text": "Bathe and weigh → feed the newborn → recheck glucose at the next feeding time"}]'::jsonb, '["a"]', 'An asymptomatic newborn with low glucose is fed first, with glucose rechecked 30–60 minutes later; IV dextrose is used if the infant cannot feed or glucose stays critically low. Starting with IV dextrose skips the first-line step.'),
  ('gdm', 49, 'A client with GDM at 31 weeks has needed insulin for 3 weeks. She asks whether she can switch to metformin because she dislikes injections. Her readings are now at target. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Since your readings are at target, you can stop insulin and return to diet alone.\""}, {"id": "b", "text": "\"Metformin is preferred in pregnancy, so the switch can be made at your next visit.\""}, {"id": "c", "text": "\"Oral medicines are sometimes used, but insulin remains the preferred choice in pregnancy.\""}, {"id": "d", "text": "\"Oral medicines cannot be used in pregnancy because they all cross to the baby.\""}]'::jsonb, '["c"]', 'Glyburide and metformin are sometimes used, but insulin is the gold standard in pregnancy. Readings at target show the current treatment is working, not that it can be stopped.'),
  ('gdm', 50, 'At a 26-week visit, the nurse reviews data for a client with GDM managed by diet. Which finding is a warning sign that her glucose control may be inadequate and should be reported?', '[{"id": "a", "text": "Fasting glucose of 91 mg/dL on this morning''s meter reading"}, {"id": "b", "text": "Urine dipstick that is positive for glucose at today''s visit"}, {"id": "c", "text": "2-hour post-lunch glucose of 116 mg/dL recorded yesterday"}, {"id": "d", "text": "1-hour post-dinner glucose of 133 mg/dL recorded late last night"}]'::jsonb, '["b"]', 'Urine glucose is a warning sign in GDM. The glucose readings are within target: fasting under 95, 2-hour under 120, and 1-hour under 140 mg/dL.'),
  ('htn', 1, 'A client at 30 weeks has BP readings of 146/94 and 148/96. Her 24-hour urine contains 340 mg of protein. She denies headache or visual changes, and her urine output is 50 mL/hr. Which condition do these findings MOST indicate?', '[{"id": "a", "text": "Gestational hypertension"}, {"id": "b", "text": "Preeclampsia"}, {"id": "c", "text": "Severe preeclampsia"}, {"id": "d", "text": "Eclampsia"}]'::jsonb, '["b"]', 'BP of at least 140/90 with proteinuria of at least 300 mg/24 hr indicates preeclampsia. Severe preeclampsia requires BP of at least 160/110 with severe symptoms, and gestational hypertension has no proteinuria.'),
  ('htn', 2, 'A client at 34 weeks has a BP of 152/98 on two occasions. Her urine dipstick is negative for protein, and she has no headache, visual changes, or epigastric pain. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Preeclampsia"}, {"id": "b", "text": "Severe preeclampsia"}, {"id": "c", "text": "HELLP syndrome"}, {"id": "d", "text": "Gestational hypertension"}]'::jsonb, '["d"]', 'BP of at least 140/90 with no proteinuria and no organ damage is gestational hypertension. Preeclampsia requires proteinuria and organ involvement.'),
  ('htn', 3, 'A client at 35 weeks has a BP of 164/112, proteinuria, a severe headache, and a urine output of 25 mL/hr over the last 2 hours. She has had no seizures. Which classification BEST fits these findings?', '[{"id": "a", "text": "Severe preeclampsia"}, {"id": "b", "text": "Preeclampsia"}, {"id": "c", "text": "Gestational hypertension"}, {"id": "d", "text": "Eclampsia"}]'::jsonb, '["a"]', 'BP of at least 160/110 with proteinuria and severe symptoms such as severe headache and oliguria (<30 mL/hr) indicates severe preeclampsia. Eclampsia requires seizures, which she has not had.'),
  ('htn', 4, 'A client at 33 weeks has a BP of 158/108 and 3+ protein on dipstick. She has no headache, no visual changes, and a urine output of 45 mL/hr. Which classification should the nurse document?', '[{"id": "a", "text": "Severe preeclampsia"}, {"id": "b", "text": "Gestational hypertension"}, {"id": "c", "text": "Preeclampsia"}, {"id": "d", "text": "Eclampsia"}]'::jsonb, '["c"]', 'BP of at least 140/90 with 3+ protein indicates preeclampsia; 158/108 has not reached the 160/110 threshold, and there are no severe symptoms. Proteinuria rules out gestational hypertension.'),
  ('htn', 5, 'A client at 36 weeks with severe preeclampsia suddenly begins a generalized tonic-clonic seizure in bed. The MgSO₄ infusion was ordered but has not yet been started. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Start the magnesium sulfate infusion right away"}, {"id": "b", "text": "Prepare the client for an emergency delivery"}, {"id": "c", "text": "Leave the room to notify the provider of the event"}, {"id": "d", "text": "Ensure airway safety and turn her onto her side"}]'::jsonb, '["d"]', 'During an eclamptic seizure, the first actions are ensuring airway safety and turning the client to her side. MgSO₄ and preparation for delivery follow once the airway is protected.'),
  ('htn', 6, 'A client receiving MgSO₄ for severe preeclampsia has a respiratory rate of 10/min, absent deep tendon reflexes, and a urine output of 20 mL/hr. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Increase the MgSO₄ rate so that a seizure is prevented"}, {"id": "b", "text": "Reassess her reflexes again in one hour"}, {"id": "c", "text": "Prepare calcium gluconate for administration"}, {"id": "d", "text": "Turn her to the left side for placental flow"}]'::jsonb, '["c"]', 'A respiratory rate below 12/min, decreased reflexes, and low urine output are MgSO₄ toxicity signs, and calcium gluconate is the antidote. Increasing the magnesium would worsen toxicity.'),
  ('htn', 7, 'The nurse is reviewing hourly assessments for a client receiving MgSO₄ for preeclampsia. Which finding requires the nurse''s immediate follow-up?', '[{"id": "a", "text": "Respiratory rate of 14/min"}, {"id": "b", "text": "Respiratory rate of 11/min"}, {"id": "c", "text": "Urine output of 45 mL/hr"}, {"id": "d", "text": "Alert and fully oriented"}]'::jsonb, '["b"]', 'A respiratory rate below 12/min is a sign of MgSO₄ toxicity that can progress to respiratory arrest. A rate of 14/min and output of 45 mL/hr are above the toxicity thresholds.'),
  ('htn', 8, 'A client at 32 weeks with preeclampsia (BP 150/98, 3+ proteinuria) is not yet receiving magnesium. Which hourly finding MOST indicates her condition is progressing to severe preeclampsia?', '[{"id": "a", "text": "Urine output of 34 mL/hr"}, {"id": "b", "text": "Urine output of 26 mL/hr"}, {"id": "c", "text": "Facial and hand edema"}, {"id": "d", "text": "BP of 152/100 on recheck"}]'::jsonb, '["b"]', 'Oliguria below 30 mL/hr suggests severe preeclampsia. An output of 34 mL/hr is above that threshold, edema reflects fluid retention, and 152/100 remains below 160/110.'),
  ('htn', 9, 'A client at 36 weeks with preeclampsia reports new, steady pain in the epigastric area that radiates toward the right upper quadrant. Which interpretation of this symptom is MOST accurate?', '[{"id": "a", "text": "Fluid retention"}, {"id": "b", "text": "Brain/CNS involvement"}, {"id": "c", "text": "Liver swelling"}, {"id": "d", "text": "Magnesium toxicity"}]'::jsonb, '["c"]', 'RUQ or epigastric pain in preeclampsia reflects liver swelling. Fluid retention presents as facial and hand edema, and CNS involvement as severe headache or visual changes.'),
  ('htn', 10, 'A client at 35 weeks with severe preeclampsia reports RUQ pain, nausea, and malaise. Labs show hemolysis, elevated liver enzymes, and a low platelet count. Which complication should the nurse suspect?', '[{"id": "a", "text": "Eclampsia"}, {"id": "b", "text": "HELLP syndrome"}, {"id": "c", "text": "Magnesium toxicity"}, {"id": "d", "text": "Gestational hypertension"}]'::jsonb, '["b"]', 'Hemolysis, elevated liver enzymes, and low platelets with RUQ pain, nausea, and malaise define HELLP, a complication of severe preeclampsia. Eclampsia is defined by seizures.'),
  ('htn', 11, 'A client with severe preeclampsia has just been diagnosed with HELLP syndrome. Her partner asks why the team seems so worried. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"It mainly causes swelling of the face and hands to worsen.\""}, {"id": "b", "text": "\"It is life-threatening and can cause liver rupture or a stroke.\""}, {"id": "c", "text": "\"It is a side effect of the magnesium that goes away when stopped.\""}, {"id": "d", "text": "\"It is mild and usually resolves without any treatment.\""}]'::jsonb, '["b"]', 'HELLP is life-threatening and can cause liver rupture or stroke. Facial and hand edema reflects fluid retention, not HELLP.'),
  ('htn', 12, 'A client at 34 weeks with severe preeclampsia develops RUQ pain and malaise. Which laboratory pattern would MOST support the complication the nurse suspects?', '[{"id": "a", "text": "High platelets and elevated liver enzymes"}, {"id": "b", "text": "Low platelets and elevated liver enzymes"}, {"id": "c", "text": "Low platelets and normal liver enzymes"}, {"id": "d", "text": "Normal platelets with no hemolysis"}]'::jsonb, '["b"]', 'HELLP consists of hemolysis, elevated liver enzymes, and low platelets, and presents with RUQ pain and malaise. Normal liver enzymes or normal platelets do not fit the pattern.'),
  ('htn', 13, 'A client at 33 weeks with preeclampsia is on bed rest. She asks which way she should lie and why. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Flat on your back with your legs raised, to reduce swelling.\""}, {"id": "b", "text": "\"On your right side, to ease pressure on your swollen liver.\""}, {"id": "c", "text": "\"On your left side, to improve blood flow to the placenta.\""}, {"id": "d", "text": "\"Sitting upright in bed, to bring your blood pressure down.\""}]'::jsonb, '["c"]', 'The left lateral position improves blood flow to the placenta. The other positions are not the recommended position for a client with preeclampsia.'),
  ('htn', 14, 'A charge nurse observes a newly hired nurse caring for a client receiving an MgSO₄ infusion for severe preeclampsia. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Checks reflexes and the respiratory rate every hour"}, {"id": "b", "text": "Measures and records intake and output hourly"}, {"id": "c", "text": "Leaves calcium gluconate in pharmacy until needed"}, {"id": "d", "text": "Keeps continuous fetal monitoring in place"}]'::jsonb, '["c"]', 'Calcium gluconate, the MgSO₄ antidote, must be kept at the bedside. Hourly DTRs, respiratory rate, I&O, and fetal monitoring are the correct monitoring routine.'),
  ('htn', 15, 'A client at 34 weeks with severe preeclampsia is starting an MgSO₄ infusion. She asks, ''Is this medicine to bring my blood pressure down?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"No, it is given to prevent seizures.\""}, {"id": "b", "text": "\"Yes, it is the main blood pressure drug.\""}, {"id": "c", "text": "\"No, it cures the condition so birth can wait.\""}, {"id": "d", "text": "\"Yes, and it also reduces your facial swelling.\""}]'::jsonb, '["a"]', 'MgSO₄ prevents and treats seizures in preeclampsia and eclampsia. The only cure is delivery of the baby and placenta.'),
  ('htn', 16, 'A client at 36 weeks with preeclampsia whose BP has improved on treatment asks, ''Now that my pressure is better, will the preeclampsia go away so I can stay pregnant until 40 weeks?'' Which response is MOST accurate?', '[{"id": "a", "text": "\"Yes, once your pressure is normal it is resolved.\""}, {"id": "b", "text": "\"It will resolve after a few more days of magnesium.\""}, {"id": "c", "text": "\"Delivery of the baby and placenta is what cures it.\""}, {"id": "d", "text": "\"Left side-lying until 40 weeks will make it resolve.\""}]'::jsonb, '["c"]', 'The only cure for preeclampsia and eclampsia is delivery of the baby and placenta. MgSO₄ prevents seizures and the left lateral position improves placental flow, but neither cures the disease.'),
  ('htn', 17, 'The nurse receives report on four clients with hypertensive disorders of pregnancy. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "Gestational HTN, BP 144/92, no complaints"}, {"id": "b", "text": "Preeclampsia with new facial and hand edema"}, {"id": "c", "text": "On MgSO₄ with a respiratory rate of 10/min"}, {"id": "d", "text": "On MgSO₄, alert, respirations 16/min"}]'::jsonb, '["c"]', 'A respiratory rate below 12/min on MgSO₄ indicates toxicity that can lead to respiratory arrest. Facial and hand edema reflects fluid retention and is less urgent.'),
  ('htn', 18, 'A nurse is planning care for a client at 32 weeks with severe preeclampsia who has just started an MgSO₄ infusion. Which monitoring plan is MOST appropriate?', '[{"id": "a", "text": "DTRs and RR every 4 hours, with I&O recorded each shift"}, {"id": "b", "text": "Hourly BP only, with DTRs once per shift"}, {"id": "c", "text": "Fetal monitoring hourly, RR every 4 hours"}, {"id": "d", "text": "Hourly DTRs, RR, I&O, and fetal monitoring"}]'::jsonb, '["d"]', 'During MgSO₄ therapy, DTRs, respiratory rate, I&O, and fetal status are monitored hourly. Less frequent checks could miss early toxicity.'),
  ('htn', 19, 'A client with severe preeclampsia has a strict intake and output order. A nursing student asks why this is a priority. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"It helps prevent fluid overload and detect oliguria.\""}, {"id": "b", "text": "\"It shows whether her seizures are being prevented.\""}, {"id": "c", "text": "\"It is the best way to measure her protein loss.\""}, {"id": "d", "text": "\"It shows whether blood flow to the placenta is improving.\""}]'::jsonb, '["a"]', 'Strict I&O prevents fluid overload and watches for oliguria. Seizure prevention is the purpose of MgSO₄, and placental flow is supported by the left lateral position.'),
  ('htn', 20, 'A client at 37 weeks with preeclampsia reports a severe headache that started an hour ago and is not relieved by rest. BP is 162/112. Which body system involvement does her headache MOST indicate?', '[{"id": "a", "text": "Liver swelling"}, {"id": "b", "text": "Fluid retention"}, {"id": "c", "text": "Brain/CNS involvement"}, {"id": "d", "text": "Kidney involvement"}]'::jsonb, '["c"]', 'A severe headache in preeclampsia indicates brain/CNS involvement. Liver swelling causes RUQ or epigastric pain, and fluid retention causes facial and hand edema.'),
  ('htn', 21, 'A client at 31 weeks with preeclampsia notes that her rings are tight and her face looks puffy. She has no headache, visual changes, or epigastric pain. Which interpretation is MOST accurate?', '[{"id": "a", "text": "Fluid retention"}, {"id": "b", "text": "Liver swelling"}, {"id": "c", "text": "CNS involvement"}, {"id": "d", "text": "Eclampsia onset"}]'::jsonb, '["a"]', 'Facial and hand edema reflects fluid retention. Liver swelling causes RUQ or epigastric pain, and CNS involvement causes headache or visual changes.'),
  ('htn', 22, 'A client has been receiving MgSO₄ for 6 hours. She is drowsy and difficult to rouse, her urine output is 22 mL/hr, and her respiratory rate is 13/min. Which interpretation should guide the nurse''s next action?', '[{"id": "a", "text": "Signs of magnesium toxicity are present"}, {"id": "b", "text": "This is expected sedation from MgSO₄"}, {"id": "c", "text": "This reflects normal fatigue on bed rest"}, {"id": "d", "text": "Toxicity is ruled out by an RR above 12"}]'::jsonb, '["a"]', 'Lethargy and decreased urine output are MgSO₄ toxicity signs even when the respiratory rate is still above 12/min. Assuming toxicity is ruled out by the RR alone would miss these signs.'),
  ('htn', 23, 'A client with severe preeclampsia has received MgSO₄ for 12 hours. Which finding BEST indicates that the medication is achieving its intended purpose?', '[{"id": "a", "text": "BP decreased from 162/110 to 150/100 overnight"}, {"id": "b", "text": "No seizure activity since it started"}, {"id": "c", "text": "Facial and hand edema have resolved"}, {"id": "d", "text": "Urine protein dropped from 3+ to 2+"}]'::jsonb, '["b"]', 'MgSO₄ is given to prevent or treat seizures, so the absence of seizures shows it is working. Blood pressure, edema, and proteinuria changes do not reflect its purpose.'),
  ('htn', 24, 'A client at 32 weeks has a BP of 148/96 on two readings and no symptoms. Which additional finding would BEST help the nurse distinguish gestational hypertension from preeclampsia?', '[{"id": "a", "text": "Whether her BP is at least 140/90 on recheck"}, {"id": "b", "text": "Whether her urine contains protein"}, {"id": "c", "text": "Whether she has had any seizures"}, {"id": "d", "text": "Whether her BP is under 160/110"}]'::jsonb, '["b"]', 'Gestational hypertension and preeclampsia share BP of at least 140/90 without seizures; proteinuria and organ damage distinguish preeclampsia. The BP thresholds listed apply to both.'),
  ('htn', 25, 'A client at 34 weeks with preeclampsia had a BP of 150/100 this morning. She now has a BP of 166/112 and reports blurred vision and flashing lights. No MgSO₄ has been given yet. Which order should the nurse implement FIRST?', '[{"id": "a", "text": "Place a urine dipstick to check for protein"}, {"id": "b", "text": "Administer MgSO₄ to prevent seizures"}, {"id": "c", "text": "Measure the 24-hour urine output"}, {"id": "d", "text": "Give oral fluids for hydration"}]'::jsonb, '["b"]', 'BP of at least 160/110 with visual changes (CNS involvement) indicates severe preeclampsia, and MgSO₄ is given to prevent seizures. Urine tests do not address the immediate seizure risk.'),
  ('htn', 26, 'A client with eclampsia begins seizing. The nurse calls for help, and a UAP arrives first. Which action by the UAP requires the nurse to intervene?', '[{"id": "a", "text": "Placing her flat on her back"}, {"id": "b", "text": "Turning her onto her side"}, {"id": "c", "text": "Keeping her airway clear"}, {"id": "d", "text": "Calling for the nurse loudly"}]'::jsonb, '["a"]', 'During an eclamptic seizure, the client is turned to her side and the airway kept safe. Placing her supine does not follow the seizure response.'),
  ('htn', 27, 'A client at 35 weeks with severe preeclampsia had an eclamptic seizure that has just ended. She is on her side with a patent airway. MgSO₄ had been ordered but was not yet started. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Administer the MgSO₄ as ordered"}, {"id": "b", "text": "Prepare calcium gluconate to give"}, {"id": "c", "text": "Encourage her to drink oral fluids"}, {"id": "d", "text": "Recheck her urine for protein now"}]'::jsonb, '["a"]', 'After airway safety and side-lying, the next step is to administer MgSO₄ if not already given, then prepare for emergency delivery. Calcium gluconate is the antidote for MgSO₄ toxicity, not seizure treatment.'),
  ('htn', 28, 'A client at 35 weeks with severe preeclampsia says, ''I think I''m coming down with the flu. I''m nauseated, achy, and tired, and it hurts under my right ribs.'' Which action should the nurse take FIRST?', '[{"id": "a", "text": "Encourage rest and oral fluids for a viral illness"}, {"id": "b", "text": "Give an antacid for the pain under her ribs"}, {"id": "c", "text": "Recheck her symptoms at the next assessment"}, {"id": "d", "text": "Report possible HELLP syndrome to the provider"}]'::jsonb, '["d"]', 'RUQ pain, nausea, and malaise in severe preeclampsia are signs of HELLP, a life-threatening complication. Treating them as flu or indigestion delays care.'),
  ('htn', 29, 'A client at 33 weeks with preeclampsia on bed rest tells the nurse she would prefer to lie flat on her back to watch television. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Lying on your left side helps blood reach your baby.\""}, {"id": "b", "text": "\"Lying on your back is best for lowering your BP.\""}, {"id": "c", "text": "\"Any position is fine as long as you stay in bed.\""}, {"id": "d", "text": "\"Lying on your right side will help reduce your swelling.\""}]'::jsonb, '["a"]', 'The left lateral position improves blood flow to the placenta and is a nursing priority in preeclampsia. Other positions do not provide this benefit.'),
  ('htn', 30, 'A client at 36 weeks has a BP of 172/114, 3+ protein, and a severe headache. She is alert and has had no seizures. Which classification is MOST accurate?', '[{"id": "a", "text": "Eclampsia"}, {"id": "b", "text": "Preeclampsia"}, {"id": "c", "text": "Gestational hypertension"}, {"id": "d", "text": "Severe preeclampsia"}]'::jsonb, '["d"]', 'BP of at least 160/110 with proteinuria and severe symptoms is severe preeclampsia; eclampsia is distinguished by seizures. A severe headache indicates CNS involvement, not eclampsia itself.'),
  ('htn', 31, 'A client at 30 weeks was diagnosed with gestational hypertension last week. At today''s visit her BP is 146/94 and her dipstick now shows 3+ protein. Which conclusion should the nurse draw?', '[{"id": "a", "text": "Gestational HTN is unchanged at this visit"}, {"id": "b", "text": "Her condition now suggests preeclampsia"}, {"id": "c", "text": "She now meets the criteria for eclampsia"}, {"id": "d", "text": "She now has severe preeclampsia criteria"}]'::jsonb, '["b"]', '3+ protein on dipstick with BP of at least 140/90 suggests preeclampsia. Severe preeclampsia requires BP of at least 160/110, and eclampsia requires seizures.'),
  ('htn', 32, 'A client at 37 weeks with severe preeclampsia has been stabilized on MgSO₄, with no seizures and stable vital signs. Which plan should the nurse anticipate?', '[{"id": "a", "text": "Prepare for delivery of the baby"}, {"id": "b", "text": "Continue MgSO₄ until it resolves"}, {"id": "c", "text": "Discharge once BP is under 140/90"}, {"id": "d", "text": "Maintain bed rest until 40 weeks"}]'::jsonb, '["a"]', 'The only cure for preeclampsia is delivery of the baby and placenta, so preparing for delivery is a nursing priority. MgSO₄ prevents seizures but does not cure the disease.'),
  ('htn', 33, 'A client on MgSO₄ for severe preeclampsia has a respiratory rate of 14/min and a urine output of 35 mL/hr, but her patellar reflexes are now absent. What is the nurse''s PRIORITY interpretation?', '[{"id": "a", "text": "Expected therapeutic magnesium effect"}, {"id": "b", "text": "Worsening preeclampsia"}, {"id": "c", "text": "Developing HELLP syndrome"}, {"id": "d", "text": "Possible magnesium toxicity"}]'::jsonb, '["d"]', 'Decreased deep tendon reflexes are an MgSO₄ toxicity sign even when respirations and urine output remain above toxic thresholds. HELLP presents with RUQ pain, nausea, malaise, and bleeding.'),
  ('htn', 34, 'A client at 34 weeks with preeclampsia is being monitored. Which new finding requires the nurse''s immediate follow-up?', '[{"id": "a", "text": "Puffy face and tight rings on her hands"}, {"id": "b", "text": "BP of 144/92 on her latest recheck"}, {"id": "c", "text": "Urine output of 40 mL/hr this hour"}, {"id": "d", "text": "Severe headache with blurred vision"}]'::jsonb, '["d"]', 'Severe headache and blurred vision indicate CNS involvement, a severe symptom. Facial and hand edema reflects fluid retention, and an output of 40 mL/hr is above the oliguria threshold.'),
  ('htn', 35, 'The nurse teaches a client at 32 weeks who has preeclampsia. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I should report a bad headache or blurry vision.\""}, {"id": "b", "text": "\"Lying on my left side helps blood reach my baby.\""}, {"id": "c", "text": "\"Delivery of my baby and placenta ends this illness.\""}, {"id": "d", "text": "\"Once my blood pressure is normal, I am cured.\""}]'::jsonb, '["d"]', 'The only cure for preeclampsia is delivery of the baby and placenta, so a normal BP does not mean she is cured. The other statements are accurate.'),
  ('htn', 36, 'A client at 36 weeks had an eclamptic seizure. Her airway is safe, she is on her side, and MgSO₄ is infusing. Which action should the nurse anticipate next?', '[{"id": "a", "text": "Waiting 24 hours to observe her response"}, {"id": "b", "text": "Discharge teaching on BP checks"}, {"id": "c", "text": "Ordering a repeat 24-hour urine"}, {"id": "d", "text": "Preparing for emergency delivery"}]'::jsonb, '["d"]', 'After airway safety, side-lying, and MgSO₄, the seizure response is to prepare for emergency delivery, since delivery is the only cure. Waiting or testing delays definitive care.'),
  ('htn', 37, 'A nursing student asks why the respiratory rate is checked every hour in a client receiving MgSO₄. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"A low rate signals CNS involvement from her preeclampsia.\""}, {"id": "b", "text": "\"The rate reflects fluid overload from her IV fluids.\""}, {"id": "c", "text": "\"Toxicity can progress to respiratory arrest.\""}, {"id": "d", "text": "\"The rate shows whether seizures are being prevented.\""}]'::jsonb, '["c"]', 'Watching for MgSO₄ toxicity signs, including a respiratory rate below 12/min, prevents respiratory arrest. CNS involvement presents as headache or visual changes.'),
  ('htn', 38, 'A client with severe preeclampsia has developed HELLP syndrome and has a low platelet count. Which nursing assessment is MOST important to add to her plan of care?', '[{"id": "a", "text": "Monitoring for hand and face edema"}, {"id": "b", "text": "Checking reflexes once each shift"}, {"id": "c", "text": "Monitoring for signs of bleeding"}, {"id": "d", "text": "Assessing for a soft uterus each hour"}]'::jsonb, '["c"]', 'Low platelets are part of HELLP, and bleeding is one of its signs, so the nurse monitors for bleeding. Edema reflects fluid retention rather than HELLP.'),
  ('htn', 39, 'A client at 34 weeks with severe preeclampsia has a BP of 168/114 and 3+ protein. Which new finding indicates her condition has progressed to eclampsia?', '[{"id": "a", "text": "A generalized seizure"}, {"id": "b", "text": "A BP of 170/116"}, {"id": "c", "text": "Urine output of 25 mL/hr"}, {"id": "d", "text": "A severe headache"}]'::jsonb, '["a"]', 'Eclampsia is distinguished by seizures. Higher BP, oliguria, and severe headache are features of severe preeclampsia.'),
  ('htn', 40, 'The nurse completes the hourly assessment of a client receiving MgSO₄ for severe preeclampsia. Which set of findings indicates it is SAFE to continue the infusion as ordered?', '[{"id": "a", "text": "RR 11/min, reflexes present, output 40 mL/hr"}, {"id": "b", "text": "RR 16/min, reflexes present, output 40 mL/hr"}, {"id": "c", "text": "RR 16/min, reflexes absent, output 40 mL/hr"}, {"id": "d", "text": "RR 16/min, reflexes present, output 20 mL/hr"}]'::jsonb, '["b"]', 'MgSO₄ toxicity signs include RR below 12/min, decreased reflexes, and decreased urine output. Only the first set has none of these signs.'),
  ('htn', 41, 'A client at 30 weeks has gestational hypertension with a BP of 142/92, no proteinuria, and no symptoms. Which ongoing nursing assessment is the PRIORITY for this client?', '[{"id": "a", "text": "Hourly reflex and respiratory checks"}, {"id": "b", "text": "Calcium gluconate kept at bedside"}, {"id": "c", "text": "Close BP monitoring for worsening"}, {"id": "d", "text": "Strict hourly I&O for MgSO₄ therapy"}]'::jsonb, '["c"]', 'Monitoring BP closely watches for worsening hypertension. Hourly reflexes, calcium gluconate, and MgSO₄-related I&O apply to clients receiving magnesium.'),
  ('htn', 42, 'A client at 33 weeks has a BP of 144/94 and a 24-hour urine protein of 320 mg. The provider asks the nurse to watch for organ involvement. Which group of assessments BEST targets the organs affected?', '[{"id": "a", "text": "Respiratory rate, reflexes, and flushing"}, {"id": "b", "text": "Hand edema, face edema, and weight"}, {"id": "c", "text": "Fetal monitoring, BP, and position"}, {"id": "d", "text": "Urine output, RUQ pain, and headache"}]'::jsonb, '["d"]', 'Preeclampsia damages the kidneys, liver, and brain, assessed through urine output, RUQ pain, and headache or visual changes. Respiratory rate, reflexes, and flushing are MgSO₄ toxicity checks.'),
  ('htn', 43, 'The nurse is caring for four pregnant clients with hypertension. Which client is at GREATEST risk of developing HELLP syndrome?', '[{"id": "a", "text": "BP 146/94, no protein, no symptoms"}, {"id": "b", "text": "BP 166/112, 3+ protein, severe headache"}, {"id": "c", "text": "BP 148/96, 3+ protein, no symptoms"}, {"id": "d", "text": "BP 142/90, facial edema, and no proteinuria"}]'::jsonb, '["b"]', 'HELLP is a complication of severe preeclampsia, indicated by BP of at least 160/110 with proteinuria and severe symptoms. The other clients have gestational hypertension or preeclampsia.'),
  ('htn', 44, 'A client on MgSO₄ has a respiratory rate of 18/min, brisk reflexes, and a urine output of 50 mL/hr. A float nurse prepares to give calcium gluconate ''to protect her breathing.'' What should the charge nurse do?', '[{"id": "a", "text": "Allow the dose as a safety measure"}, {"id": "b", "text": "Give half the dose to be cautious"}, {"id": "c", "text": "Allow the dose if her BP is over 160/110 now"}, {"id": "d", "text": "Stop the dose; no toxicity signs exist"}]'::jsonb, '["d"]', 'Calcium gluconate is the antidote for MgSO₄ toxicity and is kept at the bedside for toxicity signs such as RR below 12/min. This client shows no toxicity signs.'),
  ('htn', 45, 'Over the past 4 hours, a client with severe preeclampsia receiving MgSO₄ has had IV intake of 200 mL/hr and urine output of 25 mL/hr. Which concern should the nurse report?', '[{"id": "a", "text": "Expected output on MgSO₄"}, {"id": "b", "text": "Dehydration needing more fluid"}, {"id": "c", "text": "Fluid overload with oliguria"}, {"id": "d", "text": "Improving kidney function"}]'::jsonb, '["c"]', 'Strict I&O prevents fluid overload and detects oliguria, and output below 30 mL/hr is oliguria. Decreased urine output is also an MgSO₄ toxicity sign.'),
  ('htn', 46, 'The nurse receives report on four antepartum clients at 34 to 36 weeks. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "Severe preeclampsia with new RUQ pain and vomiting"}, {"id": "b", "text": "Preeclampsia with new facial edema and no complaints"}, {"id": "c", "text": "Gestational HTN, BP 146/92, resting comfortably"}, {"id": "d", "text": "On MgSO₄, RR 16/min, reflexes present, alert"}]'::jsonb, '["a"]', 'RUQ pain and vomiting in severe preeclampsia suggest HELLP, which is life-threatening. The other clients are stable or have expected findings.'),
  ('htn', 47, 'Before starting an MgSO₄ infusion for a client at 33 weeks with severe preeclampsia, the nurse records baseline data. Which baseline assessments are MOST important for later detecting toxicity?', '[{"id": "a", "text": "Reflexes, respiratory rate, and output"}, {"id": "b", "text": "Weight, edema, and urine protein level"}, {"id": "c", "text": "BP, headache, and visual changes"}, {"id": "d", "text": "Fetal movements, fundal height, and pain"}]'::jsonb, '["a"]', 'MgSO₄ toxicity signs include decreased RR, decreased DTRs, and decreased urine output, so these baselines are needed for comparison. Headache and visual changes reflect CNS involvement from preeclampsia.'),
  ('htn', 48, 'A client at 30 weeks has puffy hands and face. Her BP is 138/88 on two readings, and her urine is negative for protein. Which statement by the nurse is MOST accurate?', '[{"id": "a", "text": "\"You have gestational hypertension from these readings.\""}, {"id": "b", "text": "\"The swelling means you now have preeclampsia.\""}, {"id": "c", "text": "\"You meet the criteria for severe preeclampsia.\""}, {"id": "d", "text": "\"Your BP is below the 140/90 hypertension cut-off.\""}]'::jsonb, '["d"]', 'Gestational hypertension and preeclampsia require BP of at least 140/90, and 138/88 is below that threshold. Edema reflects fluid retention but does not establish preeclampsia.'),
  ('htn', 49, 'A client with severe preeclampsia begins an eclamptic seizure. MgSO₄ has not been started. Which sequence of nursing actions is MOST appropriate?', '[{"id": "a", "text": "MgSO₄, airway and side-lying, then delivery prep"}, {"id": "b", "text": "Airway and side-lying, MgSO₄, then delivery prep"}, {"id": "c", "text": "Delivery prep, MgSO₄, then airway and side-lying"}, {"id": "d", "text": "Side-lying, delivery prep, then MgSO₄ infusion"}]'::jsonb, '["b"]', 'The eclampsia seizure response is to ensure airway safety and turn to the side, administer MgSO₄ if not already given, and prepare for emergency delivery. Starting with MgSO₄ delays airway protection.'),
  ('htn', 50, 'The nurse reviews data for four clients at 32 weeks. Which client''s data are consistent with gestational hypertension?', '[{"id": "a", "text": "BP 150/96, no proteinuria, no organ damage"}, {"id": "b", "text": "BP 150/96, 3+ protein, RUQ pain present"}, {"id": "c", "text": "BP 162/112, proteinuria, and a severe headache"}, {"id": "d", "text": "BP 136/86, no proteinuria, facial edema"}]'::jsonb, '["a"]', 'Gestational hypertension is BP of at least 140/90 with no proteinuria and no organ damage. A BP of 136/86 is below the threshold, and proteinuria with symptoms indicates preeclampsia.'),
  ('intrapartum', 1, 'A primigravida at 39 weeks arrives saying her contractions started this morning. Her cervix is 3 cm dilated; contractions are mild, occur every 10 minutes, and last about 35 seconds, and she is chatting excitedly on the phone. Which phase of labor do these findings indicate?', '[{"id": "a", "text": "Latent phase of the first stage"}, {"id": "b", "text": "Active phase of the first stage"}, {"id": "c", "text": "Transition phase of the first stage"}, {"id": "d", "text": "Early part of the second stage"}]'::jsonb, '["a"]', 'The latent phase spans 0–5 cm with mild contractions 5–30 minutes apart lasting 30–45 seconds, and the mother is excited and talkative. Transition (8–10 cm) brings very strong contractions every 2–3 minutes with irritability.'),
  ('intrapartum', 2, 'A client at 9 cm has very strong contractions every 2 minutes lasting 80 seconds. She is shaking, snaps at her partner to stop touching her, and says she feels the need to push. Her partner is upset by her behavior. Which response by the nurse to the partner is best?', '[{"id": "a", "text": "Her behavior suggests the epidural is wearing off, so I''ll call anesthesia."}, {"id": "b", "text": "These are signs of early labor, so she still has many hours to go."}, {"id": "c", "text": "Irritability and shaking are expected in this most intense phase."}, {"id": "d", "text": "Her shaking may mean an infection, so I will check her temperature."}]'::jsonb, '["c"]', 'At 8–10 cm with very strong contractions every 2–3 minutes, the client is in transition, the most intense phase, when irritability, shaking, and an urge to push are expected. Early (latent) labor features mild contractions and an excited, talkative mother.'),
  ('intrapartum', 3, 'A client in labor has strong contractions every 2–3 minutes and suddenly reports an intense urge to push. Her last exam, 30 minutes ago, showed 8 cm dilation. Before the nurse coaches her to push, which finding is MOST important to confirm?', '[{"id": "a", "text": "The presenting part is at station 0"}, {"id": "b", "text": "The cervix is dilated to 10 cm"}, {"id": "c", "text": "Contractions last at least 60 seconds"}, {"id": "d", "text": "Effacement has reached at least 50%"}]'::jsonb, '["b"]', 'An urge to push occurs during transition (8–10 cm), but readiness to push is full dilation at 10 cm. Station 0 only means the presenting part is engaged.'),
  ('intrapartum', 4, 'Fifteen minutes after a vaginal birth, the nurse notes a sudden gush of blood from the vagina, the umbilical cord lengthening at the introitus, and the uterus becoming firm and globular. How should the nurse interpret these findings?', '[{"id": "a", "text": "Postpartum hemorrhage requiring immediate fundal massage"}, {"id": "b", "text": "Retained placenta that has exceeded the normal time limit"}, {"id": "c", "text": "Signs that the fourth stage of labor has already begun"}, {"id": "d", "text": "Expected signs that the placenta is separating normally"}]'::jsonb, '["d"]', 'A gush of blood, lengthening of the cord, and a globular, firm uterus are signs of placental separation in stage 3, which normally ends within 30 minutes. At 15 minutes the placenta is not retained, and stage 4 begins only after the placenta delivers.'),
  ('intrapartum', 5, 'A multipara gave birth vaginally at 13:00. At 13:40 the nurse notes that the placenta has still not delivered, although the client''s vital signs are stable. What is the nurse''s priority action?', '[{"id": "a", "text": "Notify the provider that placental delivery is delayed"}, {"id": "b", "text": "Document this as an expected third-stage duration"}, {"id": "c", "text": "Continue observing, since up to 60 minutes is normal"}, {"id": "d", "text": "Recognize that the fourth stage has now begun"}]'::jsonb, '["a"]', 'The placenta is usually expelled within 30 minutes of birth, so 40 minutes is longer than expected and should be reported. Stage 4 begins only after the placenta is delivered.'),
  ('intrapartum', 6, 'A client gave birth 30 minutes ago and delivered the placenta 10 minutes later. She is holding her newborn, and her partner asks to bring the family in to visit. Which nursing action is the priority at this time?', '[{"id": "a", "text": "Allow uninterrupted family time and reassess in 2 hours"}, {"id": "b", "text": "Teach the client how to bathe the newborn before discharge"}, {"id": "c", "text": "Check fundus, lochia, and vital signs every 15 minutes"}, {"id": "d", "text": "Check vital signs hourly while encouraging the client to rest"}]'::jsonb, '["c"]', 'The client is in stage 4, the first 1–2 hours after birth and the highest-risk period for postpartum hemorrhage, so vital signs, fundal firmness, and lochia are checked about every 15 minutes. Bonding matters but does not replace hemorrhage surveillance.'),
  ('intrapartum', 7, 'The nurse on a labor and birth unit is caring for four clients. Based on their current stage of labor, which client is at the greatest risk for hemorrhage at this time?', '[{"id": "a", "text": "A client at 4 cm who is talkative and walking the halls"}, {"id": "b", "text": "A client who gave birth 45 minutes ago and is nursing"}, {"id": "c", "text": "A client at 7 cm who just received epidural analgesia"}, {"id": "d", "text": "A client at 10 cm who is pushing with a normal FHR"}]'::jsonb, '["b"]', 'Forty-five minutes after birth falls within stage 4 (first 1–2 hours), which carries the highest risk for postpartum hemorrhage. The other clients are in stage 1 or 2, where the priorities are FHR, contractions, pain, and pushing.'),
  ('intrapartum', 8, 'A client receiving oxytocin for labor induction is having contractions every 1½ minutes, and the FHR is 150 bpm. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Decrease the oxytocin rate by half and recheck in 15 minutes"}, {"id": "b", "text": "Notify the provider and continue the current oxytocin rate"}, {"id": "c", "text": "Increase the IV fluid rate and reassess in 30 minutes"}, {"id": "d", "text": "Stop the oxytocin infusion immediately"}]'::jsonb, '["d"]', 'Contractions every 1½ minutes means more than 5 contractions in 10 minutes (uterine hyperstimulation), so oxytocin is stopped first, followed by repositioning, O₂, and notifying the provider. Reducing or continuing the infusion leaves the cause in place.'),
  ('intrapartum', 9, 'The nurse is monitoring four clients receiving oxytocin infusions for labor. Which client''s contraction pattern requires the nurse to stop the infusion?', '[{"id": "a", "text": "Six contractions in the past 10 minutes"}, {"id": "b", "text": "Four contractions in the past 10 minutes"}, {"id": "c", "text": "Contractions lasting 60 seconds each"}, {"id": "d", "text": "Five contractions in the past 10 minutes"}]'::jsonb, '["a"]', 'Uterine hyperstimulation is more than 5 contractions in 10 minutes, so six contractions requires stopping oxytocin. Five contractions does not exceed the threshold.'),
  ('intrapartum', 10, 'Seconds after an amniotomy at 6 cm, a client''s FHR falls from 140 to 80 bpm and stays there. On vaginal examination, the nurse palpates the umbilical cord in front of the fetal head. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Turn the client to her left side and apply oxygen by mask"}, {"id": "b", "text": "Call the provider and leave to prepare the operating room"}, {"id": "c", "text": "Position her knee-chest and push the fetal head upward"}, {"id": "d", "text": "Gently push the cord back into the vagina past the head"}]'::jsonb, '["c"]', 'The cord coming before the baby with sudden fetal bradycardia is cord prolapse; the nurse places the client in knee-chest position and pushes the baby''s head up, followed by emergency C-section. Left lateral positioning and O₂ are the response to late decelerations.'),
  ('intrapartum', 11, 'A client with a prolapsed umbilical cord is in knee-chest position while the nurse holds the presenting part off the cord with a gloved hand. An emergency cesarean birth has been called. Which action by the nurse requires correction?', '[{"id": "a", "text": "Keeping the hand in place during transfer to the operating room"}, {"id": "b", "text": "Removing the hand once the client is positioned on the OR table"}, {"id": "c", "text": "Maintaining upward pressure on the presenting part continuously"}, {"id": "d", "text": "Asking another staff member to call for the surgical team"}]'::jsonb, '["b"]', 'In cord prolapse, the presenting part is elevated to decompress the cord, and the nurse does not remove the hand until delivery. Removing it on the OR table, before birth, allows the cord to be compressed again.'),
  ('intrapartum', 12, 'During a vaginal birth, the fetal head delivers, but the shoulders do not emerge with the next contraction and maternal push. What should the nurse do FIRST?', '[{"id": "a", "text": "Apply firm, steady pressure to the uterine fundus"}, {"id": "b", "text": "Place the client in the knee-chest position"}, {"id": "c", "text": "Turn the client to her left side and give O₂"}, {"id": "d", "text": "Hyperflex the client''s legs onto her abdomen"}]'::jsonb, '["d"]', 'A shoulder stuck after the head is born is shoulder dystocia, managed first with McRoberts maneuver (legs hyper-flexed) and suprapubic pressure. Knee-chest positioning is the response to cord prolapse.'),
  ('intrapartum', 13, 'The nurse is caring for four clients in the second stage of labor. For which client would the nurse anticipate the provider using McRoberts maneuver and suprapubic pressure?', '[{"id": "a", "text": "The head has delivered, but the shoulders do not follow"}, {"id": "b", "text": "A loop of umbilical cord is felt in front of the presenting part"}, {"id": "c", "text": "FHR drops begin after each contraction during pushing"}, {"id": "d", "text": "Contractions occur 6 times in 10 minutes on oxytocin"}]'::jsonb, '["a"]', 'McRoberts maneuver and suprapubic pressure are the interventions for shoulder dystocia, when the baby''s shoulder is stuck after the head is born. A palpable cord calls for knee-chest positioning, and hyperstimulation calls for stopping oxytocin.'),
  ('intrapartum', 14, 'The nurse is caring for four laboring clients who are requesting epidural analgesia. Based on labor progress, for which client is epidural placement most appropriate now?', '[{"id": "a", "text": "A client at 2 cm with mild, irregular contractions"}, {"id": "b", "text": "A client at 10 cm who has started pushing"}, {"id": "c", "text": "A client at 6 cm with strong, regular contractions"}, {"id": "d", "text": "A client whose placenta delivered 10 minutes ago"}]'::jsonb, '["c"]', 'Epidurals are given in active labor (6–7 cm). A client at 2 cm is in the latent phase, and a client who is pushing or has delivered the placenta is past the point of epidural placement.'),
  ('intrapartum', 15, 'A client at 6 cm will receive an epidural in 20 minutes. Her blood pressure is 118/74 mm Hg and the FHR is 140 bpm. Which action should the nurse take FIRST to prepare her?', '[{"id": "a", "text": "Insert a straight urinary catheter to empty the bladder"}, {"id": "b", "text": "Infuse the prescribed IV fluid bolus before placement"}, {"id": "c", "text": "Give IV morphine so she is comfortable during insertion"}, {"id": "d", "text": "Place a wedge under her right hip and keep her NPO"}]'::jsonb, '["b"]', 'Epidurals can cause hypotension, so the client is preloaded with IV fluids before placement. Straight catheterization addresses urinary retention that may develop after the epidural, and the wedge/NPO measures apply to general anesthesia.'),
  ('intrapartum', 16, 'Ten minutes after epidural placement, the nurse assesses a client at 7 cm. Which finding requires the nurse''s priority follow-up?', '[{"id": "a", "text": "Pain rating decreased from 8/10 to 2/10"}, {"id": "b", "text": "Contractions continuing every 3 minutes"}, {"id": "c", "text": "FHR baseline 145 bpm with accelerations"}, {"id": "d", "text": "Blood pressure 84/50, down from 122/78"}]'::jsonb, '["d"]', 'Hypotension is the most common epidural complication, caused by sympathetic blockade and vasodilation, so a sharp drop in blood pressure needs priority follow-up. Pain relief, ongoing contractions, and an FHR of 145 bpm (within 110–160) are expected.'),
  ('intrapartum', 17, 'Three hours after epidural placement, a client at 8 cm has a firm, distended bulge above the symphysis pubis, cannot feel an urge to void, and has been unable to void on the bedpan. What is the nurse''s best action?', '[{"id": "a", "text": "Perform straight catheterization as prescribed"}, {"id": "b", "text": "Slow the IV fluids to decrease urine production"}, {"id": "c", "text": "Recheck the bladder in 4 hours since this is expected"}, {"id": "d", "text": "Increase the epidural rate to relieve her discomfort"}]'::jsonb, '["a"]', 'Epidurals block the nerves that signal bladder fullness, causing urinary retention; when the bladder is distended and the client cannot void, the nurse may need to straight catheterize. Delaying 4 hours leaves the retention untreated.'),
  ('intrapartum', 18, 'After receiving an epidural, a client asks why the nurse keeps checking above her pubic bone and asking whether she needs to urinate. Which response by the nurse is best?', '[{"id": "a", "text": "The epidural often causes your kidneys to make extra urine."}, {"id": "b", "text": "Pressing there helps the baby''s head move down into the pelvis."}, {"id": "c", "text": "The epidural can block the feeling that your bladder is full."}, {"id": "d", "text": "A full bladder is the most common sign that labor is stalling."}]'::jsonb, '["c"]', 'Epidurals block the sensory nerves that signal bladder fullness, causing urinary retention, so the nurse assesses for bladder distension. The checks are not meant to move the baby down or to detect stalled labor.'),
  ('intrapartum', 19, 'A multipara at 9 cm with strong contractions every 2 minutes asks for IV morphine. The provider expects birth within the hour. Which response by the nurse is best?', '[{"id": "a", "text": "Morphine now will help you rest so you can push more effectively."}, {"id": "b", "text": "Morphine this close to birth could slow the baby''s breathing."}, {"id": "c", "text": "Morphine is safe now, but an epidural would work even faster."}, {"id": "d", "text": "Morphine must wait until your cervix is fully dilated at 10 cm."}]'::jsonb, '["b"]', 'IV opioids are given early in labor, not close to delivery, because they can cause neonatal respiratory depression. With birth expected within the hour, morphine is not appropriate.'),
  ('intrapartum', 20, 'Four laboring clients ask for IV fentanyl for pain relief. Based on labor progress, which client is the most appropriate candidate?', '[{"id": "a", "text": "A client at 10 cm who has been pushing for 30 minutes"}, {"id": "b", "text": "A client at 9 cm whose birth is expected within an hour"}, {"id": "c", "text": "A client at 8 cm who is shaking and feels an urge to push"}, {"id": "d", "text": "A client at 4 cm with contractions every 6 to 8 minutes"}]'::jsonb, '["d"]', 'IV opioids such as fentanyl are given early in labor, not close to delivery, to avoid neonatal respiratory depression. The clients at 8–10 cm are in transition or pushing, close to birth.'),
  ('intrapartum', 21, 'A client received IV morphine 45 minutes before an unexpectedly rapid birth. At 1 minute of life, the newborn has slow, shallow respirations. Which medication should the nurse have ready?', '[{"id": "a", "text": "Naloxone"}, {"id": "b", "text": "Magnesium sulfate"}, {"id": "c", "text": "Oxytocin"}, {"id": "d", "text": "Terbutaline"}]'::jsonb, '["a"]', 'Opioids given close to delivery can cause neonatal respiratory depression, and naloxone (Narcan) is the reversal agent. Oxytocin acts on the uterus and does not reverse opioid effects.'),
  ('intrapartum', 22, 'A client at 3 cm with mild contractions every 15 minutes wants to avoid medication for as long as possible but is becoming uncomfortable. Which plan by the nurse is most appropriate?', '[{"id": "a", "text": "Arrange an epidural now so she stays ahead of the pain"}, {"id": "b", "text": "Plan IV morphine for when she is closer to delivery"}, {"id": "c", "text": "Offer breathing techniques, massage, and a birthing ball"}, {"id": "d", "text": "Keep her lying flat on her back in bed to conserve energy"}]'::jsonb, '["c"]', 'Breathing techniques, positioning, massage, hydrotherapy, and a birthing ball are non-pharmacologic options that fit her wishes. Epidurals are given in active labor (6–7 cm), and IV opioids should not be given close to delivery.'),
  ('intrapartum', 23, 'A client is positioned supine on the operating table for an emergency cesarean birth under general anesthesia, and her blood pressure begins to fall. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Place a wedge under her left hip"}, {"id": "b", "text": "Place a wedge under her right hip"}, {"id": "c", "text": "Lower the head of the table flat"}, {"id": "d", "text": "Assist her into knee-chest position"}]'::jsonb, '["b"]', 'A wedge under the right hip tilts the uterus to the left, relieving aortocaval compression and preventing supine hypotension. A left-hip wedge tilts the uterus the wrong way, and knee-chest positioning is for cord prolapse.'),
  ('intrapartum', 24, 'A client at 7 cm develops a complication requiring emergency cesarean birth under general anesthesia. While preparing her, which information is MOST important for the nurse to communicate to the anesthesia team?', '[{"id": "a", "text": "She would like her partner present for the birth"}, {"id": "b", "text": "She has had contractions every 3 minutes"}, {"id": "c", "text": "She requested an epidural earlier in labor"}, {"id": "d", "text": "She ate a full meal 90 minutes ago"}]'::jsonb, '["d"]', 'General anesthesia carries a risk of aspiration, which is why clients are NPO beforehand, so recent food intake is critical to report. The other details do not change the anesthesia risk.'),
  ('intrapartum', 25, 'The nurse is reviewing the plans of care for four laboring clients. For which client is general anesthesia most likely to be used?', '[{"id": "a", "text": "A client needing an emergency cesarean for cord prolapse"}, {"id": "b", "text": "A client at 6 cm requesting relief from strong contractions"}, {"id": "c", "text": "A client at 3 cm who wants medication early in labor"}, {"id": "d", "text": "A client in the second stage who is pushing effectively"}]'::jsonb, '["a"]', 'General anesthesia is used for emergency cesarean birth only, and cord prolapse requires an emergency C-section. A client at 6 cm is a candidate for an epidural, and early labor suits IV opioids or non-pharmacologic measures.'),
  ('intrapartum', 26, 'On vaginal examination, the nurse finds that a client''s cervix is 5 cm dilated and 70% effaced, with the fetal head at −2 station. The client asks where her baby is now. Which response by the nurse is most accurate?', '[{"id": "a", "text": "The baby''s head is crowning and birth is close."}, {"id": "b", "text": "The baby''s head is engaged at the ischial spines."}, {"id": "c", "text": "The baby''s head is still above the ischial spines."}, {"id": "d", "text": "The baby''s head is in the pelvis ready for pushing."}]'::jsonb, '["c"]', 'Station runs from −3 (floating) through 0 (engaged at the ischial spines) to +3 (crowning), so −2 means the head has not yet reached the spines. Engagement is station 0, and crowning is +3.'),
  ('intrapartum', 27, 'The nurse reviews the vaginal examination findings of four laboring clients. Which client''s fetus is engaged in the pelvis but not yet crowning?', '[{"id": "a", "text": "Dilation 4 cm, station −3"}, {"id": "b", "text": "Dilation 6 cm, station 0"}, {"id": "c", "text": "Dilation 10 cm, station +3"}, {"id": "d", "text": "Dilation 5 cm, station −2"}]'::jsonb, '["b"]', 'Station 0 means the presenting part is engaged (head in the pelvis at the ischial spines), while +3 is crowning. Stations −3 and −2 are above the level of engagement.'),
  ('intrapartum', 28, 'After a vaginal exam, the nurse tells a client at 5 cm that her cervix is 80% effaced. The client asks, ''Does that mean I''m 80% of the way to pushing?'' Which response by the nurse is best?', '[{"id": "a", "text": "Yes, at 100% effaced you''ll be fully dilated and can push."}, {"id": "b", "text": "No, it means your cervix is open 8 of the 10 centimeters."}, {"id": "c", "text": "It means the baby has moved 80% of the way into the pelvis."}, {"id": "d", "text": "It means your cervix has thinned; pushing begins at 10 cm."}]'::jsonb, '["d"]', 'Effacement (0–100%) measures how thin the cervix is, while dilation (0–10 cm) measures opening, and 10 cm is fully dilated and ready to push. Descent into the pelvis is described by station.'),
  ('intrapartum', 29, 'A client has been fully dilated for 40 minutes and is pushing with each contraction; the fetal head is at +1 station. Which nursing action is the priority during this stage of labor?', '[{"id": "a", "text": "Guide her pushing and monitor the FHR for fetal distress"}, {"id": "b", "text": "Massage the fundus and monitor her for heavy bleeding"}, {"id": "c", "text": "Encourage bonding and check vital signs every 15 minutes"}, {"id": "d", "text": "Prepare for epidural placement to control her pain"}]'::jsonb, '["a"]', 'From full dilation to birth is stage 2, when the nurse guides pushing, monitors for fetal distress, and assists delivery. Fundal massage belongs to stage 3, and 15-minute vital signs with bonding belong to stage 4.'),
  ('intrapartum', 30, 'A newborn was born 8 minutes ago and is skin-to-skin with the mother. The umbilical cord has been clamped, and the placenta has not yet delivered. Which nursing action is the priority during this stage?', '[{"id": "a", "text": "Coach the client to push hard with each contraction"}, {"id": "b", "text": "Check vital signs hourly and encourage family bonding"}, {"id": "c", "text": "Monitor bleeding and watch for placental separation"}, {"id": "d", "text": "Assess cervical dilation and fetal station"}]'::jsonb, '["c"]', 'The period between the baby''s birth and delivery of the placenta is stage 3, when the nurse monitors for bleeding and signs of separation, with fundal massage as needed. Guided pushing belongs to stage 2.'),
  ('intrapartum', 31, 'A client at 5 cm with contractions every 4 minutes is resting in bed with her partner at the bedside. Which nursing action is the priority at this point in her labor?', '[{"id": "a", "text": "Coach her to push with each contraction"}, {"id": "b", "text": "Monitor the FHR, contractions, and pain"}, {"id": "c", "text": "Perform fundal massage every 15 minutes"}, {"id": "d", "text": "Assess lochia and fundal firmness"}]'::jsonb, '["b"]', 'At 5 cm the client is in stage 1 (0–10 cm), when nursing care focuses on monitoring the FHR, contractions, and pain relief. Pushing is guided in stage 2, and fundal and lochia checks belong after birth.'),
  ('intrapartum', 32, 'A primigravida is admitted in labor with a cervix dilated to 4 cm. Which contraction pattern should the nurse expect to find at this point in her labor?', '[{"id": "a", "text": "Very strong contractions every 2–3 minutes lasting 45–90 seconds"}, {"id": "b", "text": "Contractions more than 5 times in 10 minutes lasting 90 seconds"}, {"id": "c", "text": "Strong contractions every 2 minutes with an urge to push"}, {"id": "d", "text": "Mild contractions every 5–30 minutes lasting 30–45 seconds"}]'::jsonb, '["d"]', 'At 4 cm the client is in the latent phase (0–5 cm), which has mild contractions 5–30 minutes apart lasting 30–45 seconds. Very strong contractions every 2–3 minutes with an urge to push describe transition.'),
  ('intrapartum', 33, 'A multipara who was admitted at 4 cm is now 9 cm dilated after several hours of labor. Which contraction pattern should the nurse expect to observe at this point?', '[{"id": "a", "text": "Very strong contractions every 2–3 minutes lasting 45–90 seconds"}, {"id": "b", "text": "Mild contractions every 5–30 minutes lasting 30–45 seconds"}, {"id": "c", "text": "Moderate contractions every 10 minutes lasting 20 seconds"}, {"id": "d", "text": "Contractions that have stopped while the placenta separates"}]'::jsonb, '["a"]', 'At 9 cm the client is in transition (8–10 cm), with very strong contractions 2–3 minutes apart lasting 45–90 seconds. Mild contractions 5–30 minutes apart describe the latent phase.'),
  ('intrapartum', 34, 'A client at 7 cm receiving oxytocin has recurrent FHR decelerations that occur after her contractions. Her contractions are every 3 minutes. Which set of nursing actions is most appropriate?', '[{"id": "a", "text": "Knee-chest position and push the fetal head upward"}, {"id": "b", "text": "McRoberts maneuver and suprapubic pressure"}, {"id": "c", "text": "Left side, O₂, stop oxytocin, IV fluids"}, {"id": "d", "text": "Wedge under the right hip and maintain NPO status"}]'::jsonb, '["c"]', 'FHR drops after contractions signal fetal distress (late decels), managed with left lateral position, O₂, stopping oxytocin, IV fluids, and preparing for delivery. Knee-chest is for cord prolapse and McRoberts for shoulder dystocia.'),
  ('intrapartum', 35, 'The nurse reviews the fetal heart rate baselines of four laboring clients. Which FHR finding requires immediate follow-up?', '[{"id": "a", "text": "Baseline of 152 bpm with accelerations present"}, {"id": "b", "text": "Baseline of 104 bpm between contractions"}, {"id": "c", "text": "Baseline of 118 bpm with moderate variability"}, {"id": "d", "text": "Baseline of 160 bpm with moderate variability"}]'::jsonb, '["b"]', 'Normal FHR during labor is 110–160 bpm; below 110 is bradycardia, which is non-reassuring. A baseline of 160 bpm is at the upper limit of normal, not tachycardia.'),
  ('intrapartum', 36, 'The charge nurse receives updates on four laboring and postpartum clients at the same time. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A client at 3 cm who is excited and talking with visitors"}, {"id": "b", "text": "A client at 7 cm whose epidural is working and BP is stable"}, {"id": "c", "text": "A client 1 hour postpartum with a firm fundus and stable vital signs"}, {"id": "d", "text": "A client on oxytocin with 6 contractions in the last 10 minutes"}]'::jsonb, '["d"]', 'More than 5 contractions in 10 minutes is uterine hyperstimulation, which requires stopping oxytocin, repositioning, O₂, and notifying the provider. The other clients show expected, stable findings.'),
  ('intrapartum', 37, 'A client at 6 cm received an epidural 15 minutes ago. She asks why the nurse keeps taking her blood pressure so often. Which response by the nurse is best?', '[{"id": "a", "text": "The epidural can widen blood vessels and lower your blood pressure."}, {"id": "b", "text": "The epidural often raises your blood pressure, which can harm the baby."}, {"id": "c", "text": "Frequent checks show whether you need more fluid to make urine."}, {"id": "d", "text": "We check it often to see when you will be ready to start pushing."}]'::jsonb, '["a"]', 'Hypotension is the most common epidural complication, caused by sympathetic blockade and vasodilation, so blood pressure is monitored frequently after placement. The epidural lowers rather than raises blood pressure.'),
  ('intrapartum', 38, 'The nurse teaches a client in early labor about the use of IV opioids for pain relief. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "If I want IV pain medicine, it is better to get it earlier."}, {"id": "b", "text": "The medicine can affect the baby''s breathing after birth."}, {"id": "c", "text": "I''ll save the IV pain medicine for when I''m ready to push."}, {"id": "d", "text": "I can also use breathing and position changes for comfort."}]'::jsonb, '["c"]', 'IV opioids should be given early in labor and not close to delivery, because they can cause neonatal respiratory depression. Saving them for pushing places the dose right before birth.'),
  ('intrapartum', 39, 'After a vaginal exam, a client is told her cervix is 100% effaced and 4 cm dilated. She says, ''Since I''m at 100%, I can start pushing now, right?'' Which response by the nurse is best?', '[{"id": "a", "text": "Yes, 100% effacement means you are ready to push."}, {"id": "b", "text": "Not yet; pushing starts when you are 10 cm dilated."}, {"id": "c", "text": "Yes, as long as the baby''s head is at station 0."}, {"id": "d", "text": "Not yet; the baby''s head must first be at −3 station."}]'::jsonb, '["b"]', 'Effacement measures cervical thinning; readiness to push depends on full dilation at 10 cm. Station 0 means engaged and −3 means floating, and neither signals readiness to push.'),
  ('intrapartum', 40, 'A client who is fully dilated has been pushing for an hour. On examination, the fetal station is now +3. Which interpretation should the nurse communicate to the birth team?', '[{"id": "a", "text": "The head is floating above the pelvic inlet"}, {"id": "b", "text": "The head has just reached the ischial spines"}, {"id": "c", "text": "The head is engaged but still well above crowning"}, {"id": "d", "text": "The head is crowning, and birth is approaching"}]'::jsonb, '["d"]', 'Station +3 is crowning, at the far end of the −3 (floating) to +3 scale. Reaching the ischial spines is station 0 (engaged).'),
  ('intrapartum', 41, 'A client is in the second stage of labor and pushing with each contraction. Which finding requires the nurse''s immediate follow-up?', '[{"id": "a", "text": "FHR baseline has dropped to 100 bpm"}, {"id": "b", "text": "Client reports a strong urge to push"}, {"id": "c", "text": "Contractions are every 2–3 minutes"}, {"id": "d", "text": "Fetal station has progressed to +2"}]'::jsonb, '["a"]', 'During stage 2 the nurse monitors for fetal distress, and an FHR below 110 bpm is bradycardia. An urge to push, frequent strong contractions, and descent are expected while pushing.'),
  ('intrapartum', 42, 'A client at 6 cm with strong, regular contractions asks for an epidural but worries, ''Isn''t it too late for that now?'' Which response by the nurse is best?', '[{"id": "a", "text": "Yes, epidurals must be given before 4 cm of dilation."}, {"id": "b", "text": "Yes, at this point only IV morphine can be given safely."}, {"id": "c", "text": "No, this active phase is the usual time to place one."}, {"id": "d", "text": "No, but we must wait until you are fully dilated first."}]'::jsonb, '["c"]', 'Epidurals are typically placed during active labor (around 6–7 cm), so 6 cm is an appropriate time. IV opioids, by contrast, should not be given close to delivery.'),
  ('intrapartum', 43, 'Over the past 3 hours, a client''s cervix has changed from 5 cm to 7 cm. Her contractions have become stronger and more regular, and her cervical progress is speeding up. Which phase of labor is she now in?', '[{"id": "a", "text": "Latent phase of the first stage"}, {"id": "b", "text": "Active phase of the first stage"}, {"id": "c", "text": "Transition phase of the first stage"}, {"id": "d", "text": "Second stage of labor"}]'::jsonb, '["b"]', 'The active phase spans about 6–7 cm, with stronger, more regular contractions and accelerating cervical progress. Latent is 0–5 cm and transition is 8–10 cm.'),
  ('intrapartum', 44, 'A client gave birth 1 hour ago. Her fundus is firm, her bleeding is within expected limits, and her vital signs have been stable on every 15-minute check. Which nursing action best supports the remaining priorities of this stage?', '[{"id": "a", "text": "Stop vital sign checks now that she has been stable"}, {"id": "b", "text": "Move the newborn to the nursery so the client can sleep"}, {"id": "c", "text": "Perform vigorous fundal massage every 5 minutes"}, {"id": "d", "text": "Encourage the parents to hold and bond with the baby"}]'::jsonb, '["d"]', 'Stage 4 (first 1–2 hours after birth) priorities are watching for hemorrhage, vital signs, and bonding, so with stable findings the nurse supports bonding while continuing checks. Stopping assessments during the highest-risk period for hemorrhage is unsafe.'),
  ('intrapartum', 45, 'A client at 8 cm develops an emergency requiring cesarean birth under general anesthesia. Which action by a nursing student requires correction?', '[{"id": "a", "text": "Offering the client sips of juice to keep her energy up"}, {"id": "b", "text": "Placing a wedge under the client''s right hip on the table"}, {"id": "c", "text": "Telling anesthesia the time the client last ate or drank"}, {"id": "d", "text": "Helping the team prepare the client quickly for surgery"}]'::jsonb, '["a"]', 'General anesthesia carries a risk of aspiration, so the client must be NPO before surgery. A wedge under the right hip and reporting last oral intake are correct actions.'),
  ('intrapartum', 46, 'A client in latent labor who wishes to avoid medication is taught about nonpharmacologic comfort measures. Which statement by the client indicates understanding?', '[{"id": "a", "text": "I should stay lying still on my back to save my strength."}, {"id": "b", "text": "I''ll ask for IV pain medicine right before I start to push."}, {"id": "c", "text": "A warm shower or sitting on a birthing ball may help me relax."}, {"id": "d", "text": "I''ll need an epidural first before I can use breathing techniques."}]'::jsonb, '["c"]', 'Hydrotherapy and a birthing ball are non-pharmacologic options, along with breathing, positioning, and massage. IV opioids should not be given close to delivery, and breathing techniques do not require an epidural.'),
  ('intrapartum', 47, 'A client gave birth at 02:10. At 02:32 the placenta delivers spontaneously, and her uterus is firm. Which interpretation of this timing is correct?', '[{"id": "a", "text": "Prolonged third stage that must be reported"}, {"id": "b", "text": "Normal third stage completed within 30 minutes"}, {"id": "c", "text": "Early placental delivery that signals hemorrhage"}, {"id": "d", "text": "Prolonged second stage requiring documentation"}]'::jsonb, '["b"]', 'Stage 3 runs from the baby''s birth to delivery of the placenta, normally within 30 minutes; 22 minutes is within that limit. The second stage ended at the baby''s birth.'),
  ('intrapartum', 48, 'During a birth in which the baby''s shoulder became stuck after the head delivered, a nursing student describes the interventions used. Which student statement requires correction?', '[{"id": "a", "text": "McRoberts means sharply flexing the mother''s thighs toward her abdomen."}, {"id": "b", "text": "Suprapubic pressure is applied just above the mother''s pubic bone."}, {"id": "c", "text": "The anterior shoulder is caught behind the mother''s pubic symphysis."}, {"id": "d", "text": "The first step is the knee-chest position with the head pushed up."}]'::jsonb, '["d"]', 'Shoulder dystocia is managed first with McRoberts maneuver (hyperflexing the thighs against the abdomen) and suprapubic pressure. Knee-chest position with pushing the head up is the response to cord prolapse.'),
  ('intrapartum', 49, 'A nursing student is asked why a wedge is placed under the client''s right hip during a cesarean birth under general anesthesia. Which explanation by the student is correct?', '[{"id": "a", "text": "It tilts the uterus left, off the vena cava and aorta."}, {"id": "b", "text": "It raises the pelvis to lower the risk of aspirating stomach contents."}, {"id": "c", "text": "It lifts the presenting part off the cord to restore fetal blood flow."}, {"id": "d", "text": "It flexes the hips to free the baby''s shoulder from the pubic bone."}]'::jsonb, '["a"]', 'A wedge under the right hip tilts the uterus to the left, relieving compression of the inferior vena cava and aorta and preventing supine hypotensive syndrome. Aspiration risk is managed by keeping the client NPO.'),
  ('intrapartum', 50, 'The nurse is caring for four clients in the first stage of labor. Based on cervical findings, which client is in the most intense phase of labor?', '[{"id": "a", "text": "Cervix 4 cm, 50% effaced"}, {"id": "b", "text": "Cervix 6 cm, 80% effaced"}, {"id": "c", "text": "Cervix 9 cm, 100% effaced"}, {"id": "d", "text": "Cervix 2 cm, 30% effaced"}]'::jsonb, '["c"]', 'Transition (8–10 cm) is the most intense phase of stage 1. A client at 6 cm is in the active phase, and clients at 2 and 4 cm are in the latent phase.'),
  ('previa', 1, 'A G3P2 client at 32 weeks reports waking in a pool of bright red blood. She denies cramping, her uterus is soft and non-tender, and no prenatal records are available. A new graduate nurse prepares to check cervical dilation. What is the charge nurse''s BEST instruction?', '[{"id": "a", "text": "Perform the exam gently using sterile gloves and lubricant"}, {"id": "b", "text": "Place an internal scalp electrode before checking the cervix"}, {"id": "c", "text": "Check dilation once IV access and crossmatch are complete"}, {"id": "d", "text": "Hold internal exams until ultrasound locates the placenta"}]'::jsonb, '["d"]', 'Painless bright red bleeding with a soft, non-tender uterus suggests placenta previa, and a vaginal exam can rupture the placenta and cause massive hemorrhage. Having IV access in place does not make the exam safe; ultrasound confirmation must come first.'),
  ('previa', 2, 'A client at 30 weeks calls the obstetric unit to report vaginal bleeding that began an hour ago. Which statement by the client MOST strongly suggests placenta previa rather than placental abruption?', '[{"id": "a", "text": "\"My belly feels hard like a board, and it hurts constantly.\""}, {"id": "b", "text": "\"The pain came on suddenly, though I see just a little blood.\""}, {"id": "c", "text": "\"It really hurts, and the bleeding seems to come and go.\""}, {"id": "d", "text": "\"The blood is bright red, and I have no pain or tightening.\""}]'::jsonb, '["d"]', 'Bleeding without pain points to previa, whereas bleeding with pain points to abruption. A hard, board-like, painful uterus describes abruption even when little blood is seen.'),
  ('previa', 3, 'The nurse reviews the histories of four clients at 24 weeks of gestation. Which client has the GREATEST number of risk factors for placenta previa?', '[{"id": "a", "text": "A 38-year-old G5P4 whose last two births were by cesarean"}, {"id": "b", "text": "A 33-year-old G2P1 who smokes half a pack of cigarettes daily"}, {"id": "c", "text": "A 36-year-old G1P0 who is pregnant with a single fetus"}, {"id": "d", "text": "A 27-year-old G2P1 pregnant with twins after a vaginal birth"}]'::jsonb, '["a"]', 'The 38-year-old has advanced maternal age (>35), multiparity, and prior cesarean scarring, which are three risk factors. Each other client has one (smoking, age over 35, or a multiple pregnancy).'),
  ('previa', 4, 'A client at 26 weeks had one episode of painless bright red bleeding that has now stopped. Her vital signs are stable, fetal heart tones are normal, and the monitor shows no contractions. Which diagnostic step should the nurse anticipate FIRST?', '[{"id": "a", "text": "Ultrasound to identify where the placenta is located"}, {"id": "b", "text": "Speculum and digital exam to inspect the cervix"}, {"id": "c", "text": "Internal fetal monitoring to clarify fetal status"}, {"id": "d", "text": "Serial cervical checks to rule out the onset of preterm labor"}]'::jsonb, '["a"]', 'Painless bright red bleeding after 20 weeks suggests previa, and a non-invasive ultrasound to confirm placental location is the first step. Digital or speculum exams and internal monitoring are avoided while previa is suspected.'),
  ('previa', 5, 'A client at 29 weeks with confirmed placenta previa had bright red bleeding six hours ago that has now stopped. She says, ''The bleeding is over, so I should be able to go home today, right?'' Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Once bleeding stops, the placenta has usually moved off the cervix.\""}, {"id": "b", "text": "\"Bleeding can stop and then recur, and each episode may be worse.\""}, {"id": "c", "text": "\"Bleeding that has stopped means your baby is no longer at risk.\""}, {"id": "d", "text": "\"Stopped bleeding shows the previa is marginal and will resolve.\""}]'::jsonb, '["b"]', 'Previa bleeding may stop and then recur, and each episode can worsen, so close monitoring continues. A pause in bleeding does not mean the placenta has moved or that the risk is gone.'),
  ('previa', 6, 'A client at 33 weeks with known placenta previa is on bed rest. Over 30 minutes the nurse notes a saturated perineal pad, BP falling from 118/72 to 92/58, pulse rising from 84 to 118/min, and new pallor. Which interpretation is MOST accurate?', '[{"id": "a", "text": "She is showing expected effects of prolonged bed rest"}, {"id": "b", "text": "She is having an anxiety response that needs reassurance"}, {"id": "c", "text": "She is showing signs of shock from ongoing blood loss"}, {"id": "d", "text": "She is reacting to the betamethasone given this morning"}]'::jsonb, '["c"]', 'Falling BP, rising heart rate, and pallor are the signs of shock the nurse monitors for in previa, here with a saturated pad. Anxiety may raise the pulse but does not explain hypotension and pallor with heavy bleeding.'),
  ('previa', 7, 'A client at 31 weeks with a known complete placenta previa reports a sudden gush of bright red blood. Her BP is 112/70, pulse 96/min, and fetal heart tones are normal. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Weigh pads over the next hour to quantify the loss"}, {"id": "b", "text": "Establish IV access and notify the provider at once"}, {"id": "c", "text": "Give betamethasone because she is under 34 weeks"}, {"id": "d", "text": "Offer emotional support and explain what is happening"}]'::jsonb, '["b"]', 'When a client with previa bleeds, the priority is to prepare IV access, monitor the FHR, and notify the provider immediately. Betamethasone and emotional support are appropriate but are not the first action during active bleeding.'),
  ('previa', 8, 'A client at 28 weeks is being discharged after a bleeding episode; ultrasound showed a partial placenta previa and the bleeding has stopped. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"My partner and I will avoid intercourse until my provider says otherwise.\""}, {"id": "b", "text": "\"I can use tampons if the spotting returns, as long as I change them.\""}, {"id": "c", "text": "\"If I start bleeding again, I will come to the hospital right away.\""}, {"id": "d", "text": "\"I will remind any new provider not to do an internal exam on me.\""}]'::jsonb, '["b"]', 'Pelvic rest means no vaginal penetration of any kind, including tampons, intercourse, and exams. The other statements reflect correct pelvic rest and awareness that bleeding may recur.'),
  ('previa', 9, 'At 36 weeks, ultrasound shows the placental edge lies 1.5 cm from the internal cervical os without covering it. The client asks whether she must have a cesarean birth. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"A cesarean is required because the placenta is within 2 cm.\""}, {"id": "b", "text": "\"A cesarean is usually needed because the os is partly covered.\""}, {"id": "c", "text": "\"A vaginal birth may be possible with close monitoring.\""}, {"id": "d", "text": "\"A vaginal birth is planned, and no extra monitoring is needed.\""}]'::jsonb, '["c"]', 'A placenta within 2 cm of the os but not covering it is low-lying, which may deliver vaginally with monitoring. Usually needing a cesarean describes a partial previa, which partly covers the os.'),
  ('previa', 10, 'At 34 weeks, a client with painless bleeding has an ultrasound showing the placenta completely covers the internal cervical os. Bleeding has slowed and fetal heart tones are normal. Which birth plan should the nurse anticipate?', '[{"id": "a", "text": "Cesarean birth"}, {"id": "b", "text": "Vaginal birth with close monitoring"}, {"id": "c", "text": "Oxytocin induction once at term"}, {"id": "d", "text": "Trial of labor with internal monitoring"}]'::jsonb, '["a"]', 'A placenta that completely covers the os is a total previa, for which cesarean birth is almost always required. Vaginal birth with close monitoring may be considered for marginal or low-lying placentas instead.'),
  ('previa', 11, 'A client at 35 weeks with placenta previa asks why she suddenly started bleeding now, when she has had no pain and no contractions. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"The placenta is separating early from the uterine wall.\""}, {"id": "b", "text": "\"Blood trapped behind the placenta is now leaking out.\""}, {"id": "c", "text": "\"Tightening of your uterus is squeezing the placental bed.\""}, {"id": "d", "text": "\"As your cervix thins and opens, vessels over it tear.\""}]'::jsonb, '["d"]', 'In previa the placenta covers the os, so as the cervix dilates or effaces, placental vessels tear and cause painless bright red bleeding. Premature separation of the placenta describes abruption.'),
  ('previa', 12, 'The nurse is caring for four clients with bleeding from placenta previa for whom early delivery is being considered. For which client should the nurse anticipate an order for betamethasone?', '[{"id": "a", "text": "A client at 33 weeks 5 days"}, {"id": "b", "text": "A client at 34 weeks 2 days"}, {"id": "c", "text": "A client at 36 weeks 1 day"}, {"id": "d", "text": "A client at 38 weeks 0 days"}]'::jsonb, '["a"]', 'Corticosteroids such as betamethasone are given if the client is under 34 weeks, to mature fetal lungs. A client at 34 weeks 2 days has already passed that cut-off.'),
  ('previa', 13, 'A client at 31 weeks with bleeding from placenta previa is receiving betamethasone. She asks, ''Is this shot going to stop my bleeding?'' Which reply by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, it tightens the torn vessels over the edge of the placenta.\""}, {"id": "b", "text": "\"No, it stops contractions so that labor will not start early.\""}, {"id": "c", "text": "\"Yes, it holds the placenta in place so it cannot separate.\""}, {"id": "d", "text": "\"No, it helps your baby''s lungs mature in case of early birth.\""}]'::jsonb, '["d"]', 'Betamethasone is a corticosteroid given to mature fetal lungs if early delivery is needed. It does not stop bleeding or hold the placenta in place.'),
  ('previa', 14, 'A client at 30 weeks has a moderate amount of painless bright red bleeding, and fetal heart tones are currently normal. Her partner says, ''The baby''s heartbeat is fine, so this can''t be serious.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"You''re right; a normal heartbeat means the bleeding is minor.\""}, {"id": "b", "text": "\"A normal rate means we can safely place an internal monitor now.\""}, {"id": "c", "text": "\"Fetal problems may not show early, so we keep monitoring.\""}, {"id": "d", "text": "\"A normal rate confirms the bleeding is not from the placenta.\""}]'::jsonb, '["c"]', 'In previa, fetal heart tones are often normal initially because fetal distress may not be present early on, so close monitoring continues. A normal heartbeat does not show the bleeding is minor.'),
  ('previa', 15, 'A nurse is supervising an unlicensed assistive personnel (UAP) caring for a client at 32 weeks admitted with placenta previa and light spotting. Which action by the UAP requires the nurse to intervene?', '[{"id": "a", "text": "Saves each used perineal pad for the nurse to check"}, {"id": "b", "text": "Reports a pulse of 112/min to the nurse right away"}, {"id": "c", "text": "Gives the client a tampon when she asks for one"}, {"id": "d", "text": "Keeps the external fetal monitor belt in position"}]'::jsonb, '["c"]', 'Clients with previa are on pelvic rest, so tampons are not used. Saving pads for counts, reporting tachycardia, and keeping external FHR monitoring in place are all appropriate.'),
  ('previa', 16, 'A client at 30 weeks is admitted for observation after a bleeding episode from a partial placenta previa. Her uterus is soft and she has no contractions. Which nursing assessment BEST tracks ongoing blood loss?', '[{"id": "a", "text": "Serial digital cervical examinations"}, {"id": "b", "text": "Palpating for a board-like uterus"}, {"id": "c", "text": "Watching the monitor for contractions"}, {"id": "d", "text": "Counting and checking perineal pads"}]'::jsonb, '["d"]', 'Bleeding in previa is monitored with pad counts. Digital cervical exams are contraindicated, and a board-like uterus is a sign of abruption rather than a measure of previa blood loss.'),
  ('previa', 17, 'A client at 37 weeks with a partial placenta previa has light bleeding. The provider gives a phone order to ''start oxytocin,'' but no delivery plan has been documented. What should the nurse do FIRST?', '[{"id": "a", "text": "Begin the infusion at a low rate and titrate it up slowly"}, {"id": "b", "text": "Check the cervix to confirm readiness for induction"}, {"id": "c", "text": "Place an internal monitor before starting the drip"}, {"id": "d", "text": "Clarify the order and delivery plan with the provider"}]'::jsonb, '["d"]', 'Oxytocin is not given to a client with previa without a delivery plan, so the order must be clarified first. Checking the cervix or placing an internal monitor is contraindicated in previa.'),
  ('previa', 18, 'A client at 34 weeks was admitted with painless bright red bleeding and a soft uterus. During reassessment, which new finding should the nurse report immediately because it suggests a different complication?', '[{"id": "a", "text": "Bright red spotting on the newest perineal pad"}, {"id": "b", "text": "A soft uterus that is non-tender on palpation"}, {"id": "c", "text": "Constant abdominal pain with a rigid uterus"}, {"id": "d", "text": "Normal fetal heart tones with no decelerations"}]'::jsonb, '["c"]', 'Bleeding with pain and a rigid, board-like uterus points to abruption, a different complication that needs immediate reporting. Painless bright red spotting and a soft, non-tender uterus are consistent with the known previa.'),
  ('previa', 19, 'A client at 37 weeks with a marginal placenta previa is laboring with close monitoring. A nursing student says, ''The external tracing is choppy, so let''s ask about a fetal scalp electrode.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"That is reasonable because her previa is just a marginal one.\""}, {"id": "b", "text": "\"Good idea, as long as a cervical check is done beforehand.\""}, {"id": "c", "text": "\"Internal fetal monitoring is avoided with a placenta previa.\""}, {"id": "d", "text": "\"We can place it once the bleeding has completely stopped.\""}]'::jsonb, '["c"]', 'Internal fetal monitoring is on the list of things not done in placenta previa, even when a marginal previa is allowed to labor with close monitoring. Doing a cervical check first would add a second contraindicated internal exam.'),
  ('previa', 20, 'A client at 33 weeks has an ultrasound showing that the placenta covers part, but not all, of the internal cervical os. She asks how her baby will most likely be born. Which response is MOST accurate?', '[{"id": "a", "text": "\"A vaginal birth with close monitoring is expected.\""}, {"id": "b", "text": "\"A vaginal birth may proceed once bleeding stops.\""}, {"id": "c", "text": "\"An induction with oxytocin is usually planned.\""}, {"id": "d", "text": "\"A cesarean birth is usually planned.\""}]'::jsonb, '["d"]', 'A placenta that partially covers the os is a partial previa, which is usually delivered by C-section. Vaginal birth with monitoring may be possible for marginal or low-lying placentas instead.'),
  ('previa', 21, 'At 37 weeks, ultrasound shows the edge of the placenta reaches the margin of the internal os but does not cover it. Bleeding stopped two days ago. The client asks about her birth options. Which statement by the nurse is accurate?', '[{"id": "a", "text": "\"A cesarean is always required with this placement.\""}, {"id": "b", "text": "\"A vaginal birth may be allowed with close monitoring.\""}, {"id": "c", "text": "\"A cesarean is usually planned since the os is covered.\""}, {"id": "d", "text": "\"Labor can be induced without any added monitoring.\""}]'::jsonb, '["b"]', 'A placental edge at the os is a marginal previa, which may allow vaginal birth with close monitoring. Cesarean is required for total previa and usually for partial previa.'),
  ('previa', 22, 'A 37-year-old G4P3 at 12 weeks had placenta previa in her last pregnancy and smokes one pack of cigarettes daily. Which of her placenta previa risk factors is the BEST focus for teaching because she can change it?', '[{"id": "a", "text": "Her cigarette smoking"}, {"id": "b", "text": "Her age over 35 years"}, {"id": "c", "text": "Her prior placenta previa"}, {"id": "d", "text": "Her three previous births"}]'::jsonb, '["a"]', 'Smoking is a previa risk factor the client can change. Advanced maternal age, previous previa, and multiparity are also risk factors but cannot be modified.'),
  ('previa', 23, 'The nurse receives morning report on four antepartum clients, each with an ultrasound-confirmed placenta previa. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "29 weeks; two pads soaked in 30 minutes, pulse 116/min, BP 94/60"}, {"id": "b", "text": "32 weeks; spotting stopped 4 hours ago, normal fetal heart tones"}, {"id": "c", "text": "34 weeks; stable and asking when her next steroid dose is due"}, {"id": "d", "text": "30 weeks; tearful about a long stay, vital signs at her own baseline"}]'::jsonb, '["a"]', 'Heavy bleeding with rising pulse and falling BP signals worsening bleeding and possible shock, and emergency care must not be delayed. The other clients are stable and can be seen afterward.'),
  ('previa', 24, 'A client at 33 weeks with complete placenta previa has recurring bright red bleeding. BP is 108/68 and pulse 98/min. The provider documents a plan for possible cesarean birth. Which nursing action is the PRIORITY now?', '[{"id": "a", "text": "Complete discharge teaching about strict pelvic rest"}, {"id": "b", "text": "Ensure IV access and type and crossmatch for blood"}, {"id": "c", "text": "Arrange a referral to a smoking cessation program"}, {"id": "d", "text": "Obtain consent for internal fetal heart monitoring"}]'::jsonb, '["b"]', 'Establishing IV access and a type and crossmatch prepares for hemorrhage and possible cesarean birth. Internal fetal monitoring is contraindicated, and teaching or referrals are not the priority during recurrent bleeding.'),
  ('previa', 25, 'A client at 27 weeks is going home after an episode of painless bleeding from placenta previa. She has no contractions and fetal heart tones were normal at discharge. Which statement by the client indicates the teaching was effective?', '[{"id": "a", "text": "\"Even without pain, any new bleeding means I come in right away.\""}, {"id": "b", "text": "\"No pain means nothing is separating, so spotting can wait at home.\""}, {"id": "c", "text": "\"Since the bleeding stopped, we can resume intercourse next week.\""}, {"id": "d", "text": "\"Using a tampon will help me measure how much I am bleeding.\""}]'::jsonb, '["a"]', 'Previa bleeding may stop and then recur, and it is characteristically painless, so any new bleeding needs prompt evaluation. Intercourse and tampons are prohibited under pelvic rest.'),
  ('previa', 26, 'A client at 36 weeks presents with bright red vaginal bleeding. Her uterus is soft and relaxed, she denies pain, and the monitor shows no contractions. Which underlying problem should the nurse suspect?', '[{"id": "a", "text": "Placental tissue lying over the cervical os"}, {"id": "b", "text": "Premature separation of the placenta"}, {"id": "c", "text": "Bleeding concealed behind the placenta"}, {"id": "d", "text": "Contractions tearing the placental edge"}]'::jsonb, '["a"]', 'Painless bright red bleeding with a soft, non-tender uterus and no contractions fits previa, in which the placenta covers the cervical os. Premature separation with painful, possibly concealed bleeding describes abruption.'),
  ('previa', 27, 'A client at 35 weeks arrives by ambulance with vaginal bleeding of unknown cause. She has had no prenatal care, no ultrasound is on record, and the provider is 20 minutes away. Which nursing action is MOST appropriate?', '[{"id": "a", "text": "Do a vaginal exam to rule out labor as the cause"}, {"id": "b", "text": "Defer vaginal exams; monitor bleeding and the FHR"}, {"id": "c", "text": "Apply a scalp electrode for more accurate FHR data"}, {"id": "d", "text": "Wait to begin pad counts until the provider arrives"}]'::jsonb, '["b"]', 'No vaginal exam is done when the cause of bleeding is unknown, because previa has not been ruled out; bleeding and FHR are monitored meanwhile. Delaying pad counts would leave blood loss unmonitored.'),
  ('previa', 28, 'A client at 31 weeks with placenta previa had bleeding that stopped 12 hours ago. BP is 116/74, pulse 82/min, fetal heart tones are normal, and her pad is dry. She is crying and says she must have caused this. Which nursing action is MOST appropriate now?', '[{"id": "a", "text": "Prepare her for an emergency cesarean birth now"}, {"id": "b", "text": "Provide emotional support and explore her concerns"}, {"id": "c", "text": "Report signs of shock to the provider immediately"}, {"id": "d", "text": "Begin an oxytocin infusion to shorten her stay"}]'::jsonb, '["b"]', 'With bleeding stopped and stable findings, providing emotional support is the appropriate nursing action. There are no signs of shock (falling BP, rising HR, pallor), and oxytocin is not given without a delivery plan.'),
  ('previa', 29, 'A client at 20 weeks has had prior uterine surgery and one cesarean birth. She asks why her provider wants to check the placenta''s location on her next ultrasound. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Prior surgery causes the placenta to separate too early.\""}, {"id": "b", "text": "\"Scar tissue makes the cervix open well before term.\""}, {"id": "c", "text": "\"Prior surgery makes painful bleeding more likely later.\""}, {"id": "d", "text": "\"Scarring can change where the placenta implants.\""}]'::jsonb, '["d"]', 'Prior C-section or uterine surgery causes scarring that alters implantation, raising the risk of previa. Early placental separation with painful bleeding describes abruption.'),
  ('previa', 30, 'The nurse reviews four triage notes for pregnant clients reporting vaginal bleeding. Which presentation should the nurse recognize as the classic pattern of placenta previa?', '[{"id": "a", "text": "At 26 weeks: painless bright red bleeding and a soft uterus"}, {"id": "b", "text": "At 14 weeks: painless bright red bleeding and a soft uterus"}, {"id": "c", "text": "At 26 weeks: painful bleeding and a rigid, board-like uterus"}, {"id": "d", "text": "At 26 weeks: painful bleeding that may be partly concealed"}]'::jsonb, '["a"]', 'Painless bright red bleeding is the cardinal sign of previa and appears after 20 weeks, so the 14-week presentation does not fit. Painful or concealed bleeding with a rigid uterus describes abruption.'),
  ('previa', 31, 'A client at 37 weeks with complete placenta previa begins bleeding heavily. BP is 98/60 and pulse 110/min. IV access is in place and the provider has been notified. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Prepare the client for cesarean birth"}, {"id": "b", "text": "Prepare for a vaginal birth with monitoring"}, {"id": "c", "text": "Give betamethasone and reassess in 24 hours"}, {"id": "d", "text": "Maintain pelvic rest and observe for recurrence"}]'::jsonb, '["a"]', 'Heavy bleeding with a complete previa calls for preparing for C-section, the usual delivery method for complete previa. Betamethasone is indicated under 34 weeks, and she is 37 weeks.'),
  ('previa', 32, 'A client at 30 weeks with placenta previa had bleeding stop earlier. Two hours later the nurse finds heavier bright red bleeding than the first episode; BP fell from 118/76 to 100/64 and pulse rose to 108/min. The provider asks the nurse to recheck in an hour. What should the nurse do?', '[{"id": "a", "text": "Recheck the vital signs and pad count in one hour"}, {"id": "b", "text": "Perform a vaginal exam to find the bleeding source"}, {"id": "c", "text": "Reassure the client that the bleeding will stop again"}, {"id": "d", "text": "Seek emergency care now rather than waiting an hour"}]'::jsonb, '["d"]', 'Worsening bleeding with falling BP and rising HR must not be met with a delay in emergency care. Each previa episode can be worse than the last, so waiting an hour or assuming it will stop is unsafe.'),
  ('previa', 33, 'A client at 18 weeks learns she is carrying triplets. She asks why the provider plans to recheck where her placenta lies as the pregnancy progresses. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Multiples cause the placenta to separate before the birth.\""}, {"id": "b", "text": "\"Carrying multiples increases the risk of placenta previa.\""}, {"id": "c", "text": "\"Multiples make the uterus rigid and board-like later on.\""}, {"id": "d", "text": "\"Multiples mean internal monitoring is needed in labor.\""}]'::jsonb, '["b"]', 'Multiple pregnancies (twins, triplets) and the large placenta of multiple gestation are risk factors for placenta previa. Premature separation and a board-like uterus describe abruption.'),
  ('previa', 34, 'A client at 33 weeks with placenta previa has light spotting and stable vital signs. She asks why blood was drawn for a type and crossmatch when she feels fine. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Bleeding can return and worsen, so blood should be ready.\""}, {"id": "b", "text": "\"It checks whether the placenta has separated too early.\""}, {"id": "c", "text": "\"It must be done before betamethasone can be given.\""}, {"id": "d", "text": "\"It confirms that the bleeding is coming from the placenta.\""}]'::jsonb, '["a"]', 'Type and crossmatch is part of previa management because bleeding may stop, then recur, and each episode can worsen. It does not diagnose separation or confirm the bleeding source.'),
  ('previa', 35, 'Two clients at 36 weeks are on the unit. Client A has a total placenta previa with no active bleeding. Client B has painful bleeding, a board-like uterus, and signs of fetal distress. Which statement about their birth plans is accurate?', '[{"id": "a", "text": "Client A needs an emergency cesarean; Client B can labor."}, {"id": "b", "text": "Both clients may attempt a vaginal birth with close monitoring."}, {"id": "c", "text": "Client B needs an emergency cesarean; Client A, a cesarean."}, {"id": "d", "text": "Client B can await an ultrasound; Client A needs birth now."}]'::jsonb, '["c"]', 'Painful bleeding with a board-like uterus is abruption, which requires emergency C-section, while total previa requires C-section. Neither client is a candidate for vaginal birth.'),
  ('previa', 36, 'A client at 28 weeks presents with painless bright red bleeding and a soft, non-tender uterus. Which item in her history is a recognized risk factor for the condition the nurse suspects?', '[{"id": "a", "text": "First pregnancy at age 22 years"}, {"id": "b", "text": "Cocaine use during this pregnancy"}, {"id": "c", "text": "Age 34 with one previous birth"}, {"id": "d", "text": "A single fetus and one placenta"}]'::jsonb, '["b"]', 'The findings suggest previa, and smoking or cocaine use is a listed risk factor. Advanced maternal age means over 35, so age 34 does not qualify, and a singleton pregnancy is not a risk factor.'),
  ('previa', 37, 'A client at 30 weeks with placenta previa calls the nurse: ''I''m bleeding again.'' Her pad shows fresh bright red blood, and no vaginal exam will be done. Which nursing assessment is the PRIORITY?', '[{"id": "a", "text": "Review her history for smoking"}, {"id": "b", "text": "Reinforce teaching on pelvic rest"}, {"id": "c", "text": "Check her betamethasone schedule"}, {"id": "d", "text": "Assess the FHR and maternal vital signs"}]'::jsonb, '["d"]', 'During new bleeding the nurse assesses the FHR and watches for signs of shock such as falling BP and rising HR. Risk-factor review, teaching, and medication timing can wait.'),
  ('previa', 38, 'A client at 32 weeks admitted with ultrasound-confirmed placenta previa is on bed rest with external fetal monitoring. Which assessment finding requires the nurse''s immediate follow-up?', '[{"id": "a", "text": "Normal fetal heart tones with no decelerations"}, {"id": "b", "text": "A soft uterus that is non-tender to the touch"}, {"id": "c", "text": "A fully saturated pad 20 minutes after a change"}, {"id": "d", "text": "No contractions seen on the monitor tracing"}]'::jsonb, '["c"]', 'Pad counts track previa bleeding, and rapid saturation signals active hemorrhage. A soft, non-tender uterus, absence of contractions, and normal heart tones are expected in previa.'),
  ('previa', 39, 'At a first prenatal visit at 8 weeks, a 33-year-old G2P1 reviews her history with the nurse. Which history item should the nurse flag as a risk factor for placenta previa later in this pregnancy?', '[{"id": "a", "text": "Being 33 years old at conception"}, {"id": "b", "text": "Placenta previa in her last pregnancy"}, {"id": "c", "text": "Her single fetus on early ultrasound"}, {"id": "d", "text": "Spotting earlier in this first trimester"}]'::jsonb, '["b"]', 'Previous placenta previa is a listed risk factor. Advanced maternal age applies over 35, and a singleton pregnancy is not a risk factor.'),
  ('previa', 40, 'An ultrasound report at 35 weeks states the placenta lies 1 cm from the internal os and does not cover it. How should the nurse classify this placental position when updating the care plan?', '[{"id": "a", "text": "Marginal placenta previa"}, {"id": "b", "text": "Low-lying placenta"}, {"id": "c", "text": "Partial placenta previa"}, {"id": "d", "text": "Total placenta previa"}]'::jsonb, '["b"]', 'A placenta within 2 cm of the os but not covering it is low-lying. A marginal previa has its edge at the os, and partial or total previa covers the os.'),
  ('previa', 41, 'A client at 38 weeks with an ultrasound-confirmed complete placenta previa has had no bleeding. She says, ''My last baby was born vaginally, so I want to try labor first.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"A trial of labor is reasonable as long as we monitor closely.\""}, {"id": "b", "text": "\"Labor can be induced with oxytocin to keep it short.\""}, {"id": "c", "text": "\"Vaginal birth is safe because you have not bled yet.\""}, {"id": "d", "text": "\"The placenta covers your cervix, so a cesarean is planned.\""}]'::jsonb, '["d"]', 'A total previa completely covers the cervical os and requires C-section. Trial of labor with close monitoring applies to marginal or low-lying placentas, not complete previa.'),
  ('previa', 42, 'A client at 24 weeks has painless spotting, and the provider orders a test to locate the placenta. She is anxious and asks, ''Will they need to put something inside me to find out?'' Which reply by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, a cervical exam is done first to find the source.\""}, {"id": "b", "text": "\"No, an ultrasound over your abdomen will show the placenta.\""}, {"id": "c", "text": "\"Yes, a small monitor is placed on the baby''s scalp.\""}, {"id": "d", "text": "\"No, a blood test by itself will show where the placenta is.\""}]'::jsonb, '["b"]', 'Placental location is confirmed with a transabdominal ultrasound, a non-invasive test. Cervical exams and internal monitoring are avoided when previa is suspected.'),
  ('previa', 43, 'A client at 36 weeks with a partial placenta previa is in early labor and has light bright red spotting while awaiting cesarean birth. Which provider order should the nurse question before implementing?', '[{"id": "a", "text": "Send a type and crossmatch for two units of blood"}, {"id": "b", "text": "Count and assess perineal pads every hour"}, {"id": "c", "text": "Apply a fetal scalp electrode for continuous FHR"}, {"id": "d", "text": "Maintain IV access and report any new bleeding"}]'::jsonb, '["c"]', 'Internal fetal monitoring is not done in placenta previa, so the scalp electrode order must be questioned. Crossmatch, pad counts, and IV access are standard previa care.'),
  ('previa', 44, 'At 0300, a client at 34 weeks with placenta previa reports new bright red bleeding. BP is 112/70, pulse 90/min, and fetal heart tones are normal. The nurse has started IV access and applied the fetal monitor. What should the nurse do NEXT?', '[{"id": "a", "text": "Document and recheck the pad count in two hours"}, {"id": "b", "text": "Give betamethasone per the standing protocol now"}, {"id": "c", "text": "Provide emotional support before calling anyone"}, {"id": "d", "text": "Notify the provider of the bleeding immediately"}]'::jsonb, '["d"]', 'With IV access and FHR monitoring in place, the provider must be notified immediately of any bleeding in previa. Betamethasone is indicated under 34 weeks, and delaying notification is unsafe.'),
  ('previa', 45, 'A client at 32 weeks has bright red bleeding without pain, and ultrasound confirms placental tissue over the os. When palpating the abdomen, which uterine finding should the nurse expect?', '[{"id": "a", "text": "Soft and non-tender"}, {"id": "b", "text": "Rigid and board-like"}, {"id": "c", "text": "Tender with contractions"}, {"id": "d", "text": "Tense and painful"}]'::jsonb, '["a"]', 'Previa presents with a soft, non-tender uterus and bleeding without contractions. A rigid, board-like, painful uterus is the abruption pattern.'),
  ('previa', 46, 'A client at 32 weeks with bleeding from placenta previa received her first dose of betamethasone. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"This medicine helps my baby breathe if born early.\""}, {"id": "b", "text": "\"I am getting it because I may deliver before 34 weeks.\""}, {"id": "c", "text": "\"This shot will stop the bleeding from my placenta.\""}, {"id": "d", "text": "\"My bleeding and the baby still need close watching.\""}]'::jsonb, '["c"]', 'Betamethasone matures fetal lungs if early delivery is needed and is given before 34 weeks; it does not stop bleeding. Monitoring bleeding and FHR continues regardless.'),
  ('previa', 47, 'A client at 29 weeks with painless bright red bleeding has normal fetal heart tones on admission. Which interpretation should the nurse document and communicate to the team?', '[{"id": "a", "text": "No fetal distress shows the bleeding is not placental"}, {"id": "b", "text": "Fetal status is reassuring now but may change with bleeding"}, {"id": "c", "text": "Normal tones mean continuous monitoring is unnecessary"}, {"id": "d", "text": "Normal tones show the placenta has separated only partially"}]'::jsonb, '["b"]', 'In previa, fetal heart tones are often normal initially, but each bleeding episode can worsen, so FHR monitoring continues. Normal tones do not exclude placental bleeding.'),
  ('previa', 48, 'The nurse is caring for four clients with ultrasound-confirmed placenta previa. Which client should the nurse see FIRST?', '[{"id": "a", "text": "33 weeks; light spotting, a soft uterus, and normal heart tones"}, {"id": "b", "text": "35 weeks; partial previa, awaiting a scheduled cesarean"}, {"id": "c", "text": "30 weeks; new bleeding with severe pain and a hard uterus"}, {"id": "d", "text": "28 weeks; second betamethasone dose due in two hours"}]'::jsonb, '["c"]', 'Bleeding plus pain with a rigid uterus suggests abruption, which requires emergency C-section, so this client is seen first. Painless spotting with a soft uterus is the expected previa picture.'),
  ('previa', 49, 'A client at 30 weeks is hospitalized with a confirmed partial placenta previa and is not currently bleeding. Which plan of care BEST reflects the nursing priorities for this client?', '[{"id": "a", "text": "Pad counts, FHR monitoring, and readiness for delivery"}, {"id": "b", "text": "Daily cervical checks and internal FHR monitoring"}, {"id": "c", "text": "Oxytocin on standby and pelvic exams each shift"}, {"id": "d", "text": "Weekly betamethasone until 38 weeks and routine care"}]'::jsonb, '["a"]', 'Previa care centers on monitoring bleeding, assessing FHR, and preparing for delivery. Cervical checks, internal monitoring, and pelvic exams are contraindicated, and betamethasone is used under 34 weeks.'),
  ('previa', 50, 'A client at 35 weeks with a known partial placenta previa begins having regular contractions every 5 minutes; her bleeding had been minimal. Which explanation BEST accounts for the nurse''s concern about increased bleeding?', '[{"id": "a", "text": "Contractions are causing the placenta to separate prematurely"}, {"id": "b", "text": "Contractions make the uterus rigid and board-like"}, {"id": "c", "text": "Cervical dilation can tear placental vessels over the os"}, {"id": "d", "text": "Contractions trap the bleeding behind the placenta"}]'::jsonb, '["c"]', 'In previa, as the cervix dilates or effaces, the placental vessels over the os tear and bleed. Premature separation, a board-like uterus, and concealed bleeding describe abruption.'),
  ('vealchop', 1, 'A client at 39 weeks is 6 cm dilated and laboring without oxytocin. The FHR baseline is 140 bpm with moderate variability. With each contraction the FHR slowly drops to 128 bpm, reaching its lowest point at the contraction peak and returning to 140 bpm as the contraction ends. What is the nurse''s best action?', '[{"id": "a", "text": "Continue routine monitoring, as this pattern needs no intervention"}, {"id": "b", "text": "Turn the client to her left side and apply oxygen by face mask"}, {"id": "c", "text": "Reposition the client and anticipate an order for amnioinfusion"}, {"id": "d", "text": "Increase the IV fluid rate and notify the provider of the pattern"}]'::jsonb, '["a"]', 'A gradual dip that mirrors the contraction (lowest at the peak, recovering as it ends) is an early deceleration from head compression, a benign vagal response that needs no action. Left lateral positioning and O₂ are for late decelerations, which begin after the contraction peak.'),
  ('vealchop', 2, 'A client in spontaneous labor (no oxytocin infusing) has an FHR baseline of 135 bpm. With each of the last four contractions, the FHR gradually slows starting after the contraction peak and does not return to baseline until after the contraction is over. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Apply oxygen at 8–10 L/min via face mask"}, {"id": "b", "text": "Increase the rate of the maintenance IV fluids"}, {"id": "c", "text": "Turn the client onto her left side"}, {"id": "d", "text": "Notify the provider about the recurrent pattern"}]'::jsonb, '["c"]', 'A gradual drop beginning after the contraction peak is a late deceleration (placental insufficiency); the first step is left lateral positioning, followed by O₂, increased IV fluids, and provider notification. Oxygen and fluids are correct but come after repositioning.'),
  ('vealchop', 3, 'During a 30-minute strip, a laboring client''s FHR baseline is 145 bpm. The nurse notes several abrupt, V-shaped drops to about 100 bpm; some occur during contractions and others occur between them. Which underlying cause should the nurse suspect?', '[{"id": "a", "text": "Head compression against the cervix triggering a vagal response"}, {"id": "b", "text": "Uteroplacental insufficiency reducing fetal oxygen delivery"}, {"id": "c", "text": "A normal fetal sleep cycle reducing CNS responsiveness"}, {"id": "d", "text": "Compression of the umbilical cord interrupting blood flow"}]'::jsonb, '["d"]', 'Abrupt V/U/W-shaped drops whose timing is not tied to contractions are variable decelerations caused by umbilical cord compression. Head compression produces gradual dips that mirror the contraction exactly.'),
  ('vealchop', 4, 'A laboring client''s FHR abruptly falls from 140 to 85 bpm for about 40 seconds and then quickly recovers. These drops occur unpredictably, both with and between contractions, and she is lying on her back. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Prepare the client for an amnioinfusion through an IUPC"}, {"id": "b", "text": "Change the client''s position, such as side to side"}, {"id": "c", "text": "Notify the provider and prepare for immediate delivery"}, {"id": "d", "text": "Increase the IV fluid rate and notify the provider"}]'::jsonb, '["b"]', 'Abrupt drops unrelated to contraction timing are variable decelerations from cord compression, and the first action is repositioning the mother to relieve compression. Amnioinfusion is considered only if variable decels persist despite repositioning.'),
  ('vealchop', 5, 'A client at 40 weeks has recurrent gradual FHR decelerations that begin after each contraction peak and recover after the contraction ends. The nurse has repositioned her and applied oxygen. Which provider prescription should the nurse question?', '[{"id": "a", "text": "Begin an amnioinfusion via an IUPC"}, {"id": "b", "text": "Increase the IV infusion rate"}, {"id": "c", "text": "Discontinue the oxytocin infusion"}, {"id": "d", "text": "Prepare the client for possible delivery"}]'::jsonb, '["a"]', 'Gradual decels beginning after the peak are late decelerations from placental insufficiency; amnioinfusion is used for variable decelerations (cord compression), not late decels. Stopping oxytocin, increasing IV fluids, and preparing for delivery are all part of late-decel management.'),
  ('vealchop', 6, 'During a nonstress test at 38 weeks, the FHR baseline is 145 bpm with 10-bpm variability. Twice in 20 minutes, with fetal movement, the FHR rises to 162 bpm for about 20 seconds before returning to 145 bpm. How should the nurse interpret these rises?', '[{"id": "a", "text": "Fetal tachycardia that should be reported to the provider"}, {"id": "b", "text": "Periods of minimal variability suggesting fetal sleep cycles"}, {"id": "c", "text": "Accelerations reflecting an intact CNS and good oxygenation"}, {"id": "d", "text": "Abrupt changes suggesting intermittent umbilical cord compression"}]'::jsonb, '["c"]', 'A rise of 17 bpm above the 145 baseline lasting about 20 seconds meets the ≥15 bpm × ≥15 sec acceleration criteria, a sign of intact fetal CNS and good oxygenation. Tachycardia refers to a baseline above 160 bpm, and the baseline here stays at 145.'),
  ('vealchop', 7, 'A client at 36 weeks is having a nonstress test with an FHR baseline of 130 bpm. Which brief FHR change noted by the nurse meets the criteria to be counted as an acceleration?', '[{"id": "a", "text": "A rise to 142 bpm lasting 30 seconds"}, {"id": "b", "text": "A rise to 150 bpm lasting 10 seconds"}, {"id": "c", "text": "A rise to 144 bpm lasting 14 seconds"}, {"id": "d", "text": "A rise to 146 bpm lasting 16 seconds"}]'::jsonb, '["d"]', 'An acceleration requires a rise of at least 15 bpm above baseline lasting at least 15 seconds; 146 bpm is 16 bpm above the 130 baseline for 16 seconds. The other rises fall short on height (12 or 14 bpm) or duration (10 or 14 seconds).'),
  ('vealchop', 8, 'The nurse is reviewing the fetal monitor strips of four clients in active labor, none of whom is receiving oxytocin. Which fetal finding requires the nurse''s immediate follow-up?', '[{"id": "a", "text": "Baseline 158 bpm with 12-bpm variability"}, {"id": "b", "text": "Baseline 106 bpm with 8-bpm variability"}, {"id": "c", "text": "Baseline 112 bpm with an acceleration"}, {"id": "d", "text": "Baseline 150 bpm with early decelerations"}]'::jsonb, '["b"]', 'Normal baseline FHR is 110–160 bpm, so a baseline of 106 bpm is bradycardia, a non-reassuring finding. Baselines of 112 and 158 bpm are within range, and early decelerations are benign.'),
  ('vealchop', 9, 'A client whose membranes ruptured 20 hours ago has developed a fever. Over the past hour the FHR baseline has risen from 145 to 170 bpm, with no decelerations. Which interpretation by the nurse is most accurate?', '[{"id": "a", "text": "Fetal tachycardia that may be related to maternal infection"}, {"id": "b", "text": "A normal baseline because it is still under 180 bpm"}, {"id": "c", "text": "A prolonged acceleration reflecting good fetal oxygenation"}, {"id": "d", "text": "Fetal bradycardia from cord compression after membrane rupture"}]'::jsonb, '["a"]', 'A baseline above 160 bpm is fetal tachycardia, and maternal fever/infection (including chorioamnionitis) is a listed cause; it is non-reassuring. A sustained change in baseline is not an acceleration, which is a brief rise above baseline.'),
  ('vealchop', 10, 'Thirty minutes after a laboring client receives an IV narcotic, the nurse notes the FHR baseline is 135 bpm but fluctuates only about 3 bpm. There are no decelerations. Which interpretation is most accurate?', '[{"id": "a", "text": "Moderate variability indicating a normal, well-oxygenated fetus"}, {"id": "b", "text": "Accelerations indicating a reactive and healthy fetus"}, {"id": "c", "text": "Minimal variability that may reflect fetal CNS depression"}, {"id": "d", "text": "Early decelerations indicating fetal head compression"}]'::jsonb, '["c"]', 'Fluctuation below 5 bpm is minimal variability, a non-reassuring sign of possible fetal CNS depression that can result from medications such as narcotics. Moderate (normal) variability is 6–25 bpm.'),
  ('vealchop', 11, 'The nurse is caring for four clients in active labor. Based on the following fetal monitor data, which fetus shows the strongest evidence of adequate oxygenation?', '[{"id": "a", "text": "Baseline 150 bpm, 4-bpm variability, no decelerations"}, {"id": "b", "text": "Baseline 140 bpm, 12-bpm variability, accelerations present"}, {"id": "c", "text": "Baseline 130 bpm, 10-bpm variability, recurrent late decelerations"}, {"id": "d", "text": "Baseline 165 bpm, 8-bpm variability, no decelerations"}]'::jsonb, '["b"]', 'Accelerations with moderate (6–25 bpm) variability and a normal baseline is the most reassuring combination, indicating intact CNS and adequate oxygenation. A 4-bpm variability is minimal, and 165 bpm is tachycardia.'),
  ('vealchop', 12, 'A laboring client''s FHR baseline has been 140 bpm. The FHR suddenly falls to 115 bpm and stays there for 4 minutes before returning to 140 bpm. How should the nurse classify this event?', '[{"id": "a", "text": "A new baseline bradycardia"}, {"id": "b", "text": "A mild variable deceleration"}, {"id": "c", "text": "An early deceleration"}, {"id": "d", "text": "A prolonged deceleration"}]'::jsonb, '["d"]', 'A drop of ≥15 bpm lasting 2–10 minutes is a prolonged deceleration; this 25-bpm drop lasted 4 minutes. It is not bradycardia, because the FHR never fell below 110 bpm and returned to baseline.'),
  ('vealchop', 13, 'A client receiving oxytocin has a 5-minute FHR drop from 150 to 100 bpm. Which additional assessment finding should the nurse recognize as the most likely cause of this deceleration?', '[{"id": "a", "text": "Seven contractions counted in the last 10 minutes"}, {"id": "b", "text": "Client report of fetal movement just before the drop"}, {"id": "c", "text": "FHR variability of 12 bpm before the drop began"}, {"id": "d", "text": "Contractions occurring about every 4 minutes"}]'::jsonb, '["a"]', 'Uterine hyperstimulation (more than 5 contractions in 10 minutes) is a listed cause of prolonged deceleration, along with cord prolapse, maternal hypotension, and abruptio placenta. Contractions every 4 minutes do not reach the hyperstimulation threshold.'),
  ('vealchop', 14, 'Immediately after the membranes rupture, a laboring client''s FHR drops from 140 to 70 bpm and stays down. On inspection the nurse sees a loop of umbilical cord at the vaginal opening. What is the nurse''s FIRST action?', '[{"id": "a", "text": "Turn the client to her left side and give oxygen at 10 L/min"}, {"id": "b", "text": "Place the client knee-chest and elevate the presenting part"}, {"id": "c", "text": "Prepare the client for an amnioinfusion to cushion the cord"}, {"id": "d", "text": "Notify the provider and prepare for emergency cesarean birth"}]'::jsonb, '["b"]', 'Cord prolapse causes sudden, severe, prolonged bradycardia; the nurse places the client in knee-chest position and manually elevates the presenting part to relieve compression, then applies O₂ and prepares for emergency C-section. Left lateral positioning is the first action for late decelerations, not cord prolapse.'),
  ('vealchop', 15, 'A client at 8 cm has just had spontaneous rupture of membranes. Within a minute, the FHR, which had a baseline of 145 bpm, shows a sudden, sustained drop to 80 bpm. Which complication should the nurse assess for immediately?', '[{"id": "a", "text": "Head compression against the cervix"}, {"id": "b", "text": "Placental insufficiency from contractions"}, {"id": "c", "text": "Prolapse of the umbilical cord"}, {"id": "d", "text": "Fetal CNS depression from medications"}]'::jsonb, '["c"]', 'Cord prolapse causes sudden, severe, prolonged bradycardia or severe variable decelerations from compression between the presenting part and the bony pelvis. Head compression produces benign, gradual early decelerations rather than a sustained drop.'),
  ('vealchop', 16, 'A client receiving an oxytocin infusion has contractions every 90 seconds. With each contraction the FHR gradually slows beginning after the contraction peak, and it recovers only after the contraction ends. Which action is the nurse''s priority?', '[{"id": "a", "text": "Decrease the oxytocin rate by half and recheck in 15 minutes"}, {"id": "b", "text": "Prepare to assist with an amnioinfusion through an IUPC"}, {"id": "c", "text": "Continue the oxytocin and apply oxygen at 8–10 L/min"}, {"id": "d", "text": "Stop the oxytocin infusion and reposition the client"}]'::jsonb, '["d"]', 'Contractions every 90 seconds exceed 5 in 10 minutes (hyperstimulation), and gradual decels after the peak are late decelerations; the priority is to stop the oxytocin and reposition to left lateral. Reducing or continuing the infusion leaves the cause in place, and amnioinfusion is for variable decels.'),
  ('vealchop', 17, 'A client on an oxytocin infusion is 6 cm dilated and has 5 contractions in 10 minutes. The FHR baseline is 140 bpm with 10-bpm variability and occasional accelerations. Which action by the nurse is best?', '[{"id": "a", "text": "Stop the oxytocin because hyperstimulation is present"}, {"id": "b", "text": "Continue the infusion and ongoing fetal monitoring"}, {"id": "c", "text": "Turn the client to her left side and apply oxygen"}, {"id": "d", "text": "Notify the provider of a non-reassuring tracing"}]'::jsonb, '["b"]', 'Hyperstimulation is more than 5 contractions in 10 minutes, so 5 does not meet it, and a normal baseline with moderate variability and accelerations is reassuring. Left lateral positioning and O₂ are for late decelerations, which are absent.'),
  ('vealchop', 18, 'After turning a client onto her left side for recurrent decelerations that begin after each contraction peak, the nurse prepares to give oxygen. Which oxygen delivery is correct for this situation?', '[{"id": "a", "text": "8–10 L/min by face mask"}, {"id": "b", "text": "2–4 L/min by nasal cannula"}, {"id": "c", "text": "6 L/min by nasal cannula"}, {"id": "d", "text": "1–2 L/min by face mask"}]'::jsonb, '["a"]', 'Decels beginning after the contraction peak are late decelerations, for which oxygen is given at 8–10 L/min via face mask. The low-flow settings listed do not match the recommended delivery.'),
  ('vealchop', 19, 'A client in spontaneous labor has recurrent FHR decelerations that start after each contraction peak and resolve after the contraction ends. No oxytocin is infusing. Which sequence of nursing actions is correct?', '[{"id": "a", "text": "Oxygen by mask, left lateral position, IV fluid increase, notify provider"}, {"id": "b", "text": "Notify provider, left lateral position, oxygen by mask, IV fluid increase"}, {"id": "c", "text": "Left lateral position, oxygen by mask, IV fluid increase, notify provider"}, {"id": "d", "text": "Left lateral position, notify provider, IV fluid increase, oxygen by mask"}]'::jsonb, '["c"]', 'For late decelerations the order is left lateral position, stop oxytocin (not running here), O₂ by face mask, increase IV fluids, then notify the provider. Starting with oxygen or notification delays the first-line positioning step.'),
  ('vealchop', 20, 'A nursing student observed a client with abrupt, irregularly timed FHR drops receive an amnioinfusion and is now explaining the procedure. Which student statement indicates a need for further teaching?', '[{"id": "a", "text": "The saline cushions the cord so it is not compressed."}, {"id": "b", "text": "This same procedure is first-line for late decelerations."}, {"id": "c", "text": "The fluid is infused through an intrauterine pressure catheter."}, {"id": "d", "text": "It can also be used when there is too little amniotic fluid."}]'::jsonb, '["b"]', 'Amnioinfusion is used for variable decelerations from cord compression, not late decelerations, which are treated with left lateral positioning, stopping oxytocin, O₂, and IV fluids. Cushioning the cord, IUPC delivery, and use for oligohydramnios are correct.'),
  ('vealchop', 21, 'The partner of a client at 7 cm asks why the baby''s heart rate dips each time a contraction starts. The nurse sees gradual, uniform dips that start and end with each contraction and a baseline of 135 bpm. Which response by the nurse is best?', '[{"id": "a", "text": "The baby''s cord is being squeezed, so I will help her change position."}, {"id": "b", "text": "The baby is not getting enough oxygen, so I will start oxygen now."}, {"id": "c", "text": "The baby''s head is pressed during contractions, which is expected now."}, {"id": "d", "text": "The placenta is not working well, so I will call the provider right away."}]'::jsonb, '["c"]', 'Uniform dips that mirror the contraction are early decelerations caused by head compression, a benign vagal response that is normal in active labor. Cord compression causes abrupt, irregularly timed drops instead.'),
  ('vealchop', 22, 'The labor and delivery nurse receives a change-of-shift report on four clients, none receiving oxytocin. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "Client at 5 cm with FHR dips that mirror each contraction"}, {"id": "b", "text": "Client at 39 weeks with FHR rises of 20 bpm lasting 20 seconds"}, {"id": "c", "text": "Client at 6 cm with an FHR baseline of 150 and 10-bpm variability"}, {"id": "d", "text": "Client at 4 cm with FHR dips starting after contraction peaks"}]'::jsonb, '["d"]', 'Dips beginning after the contraction peak are late decelerations from placental insufficiency, a non-reassuring pattern requiring immediate action. Mirroring dips (early decels), accelerations, and a normal baseline with moderate variability are benign or reassuring.'),
  ('vealchop', 23, 'A client at 7 cm has recurrent abrupt FHR drops to 80 bpm that are not related to contraction timing. The nurse has repositioned her side to side and applied oxygen, but the drops continue. What should the nurse do NEXT?', '[{"id": "a", "text": "Notify the provider and anticipate amnioinfusion"}, {"id": "b", "text": "Reposition her supine and recheck in 30 minutes"}, {"id": "c", "text": "Document the pattern as benign and continue care"}, {"id": "d", "text": "Prepare IV fluids to treat placental insufficiency"}]'::jsonb, '["a"]', 'When variable decelerations persist despite repositioning, the nurse notifies the provider and amnioinfusion is considered to cushion the cord. Severe variable decels are urgent, not benign, and placental insufficiency causes late decels.'),
  ('vealchop', 24, 'After membrane rupture, a laboring client''s amniotic fluid is noted to be thick and meconium-stained, and the provider orders an amnioinfusion. The client asks why it is needed. Which explanation by the nurse is best?', '[{"id": "a", "text": "It will correct the placental problem that causes late decelerations."}, {"id": "b", "text": "It will dilute the meconium to lower the baby''s aspiration risk."}, {"id": "c", "text": "It will slow your contractions to improve placental blood flow."}, {"id": "d", "text": "It will raise your blood pressure so the baby''s heart rate rises."}]'::jsonb, '["b"]', 'For thick meconium-stained fluid, the goal of amnioinfusion is to dilute the meconium and reduce aspiration risk. Amnioinfusion is not a treatment for late decelerations (placental insufficiency).'),
  ('vealchop', 25, 'The nurse is caring for four laboring clients. Based on the data, for which client should the nurse anticipate a prescription for amnioinfusion?', '[{"id": "a", "text": "Client on oxytocin with gradual decels after each contraction peak"}, {"id": "b", "text": "Client at 6 cm with uniform dips that mirror each contraction"}, {"id": "c", "text": "Client with low amniotic fluid and abrupt, irregularly timed drops"}, {"id": "d", "text": "Client with an FHR baseline of 150 bpm and 15-bpm accelerations"}]'::jsonb, '["c"]', 'Amnioinfusion is indicated for severe variable decelerations (cord compression) and oligohydramnios, restoring fluid to protect the cord. It is not used for late decels, and early decels and accelerations need no action.'),
  ('vealchop', 26, 'A student nurse turns a client with recurrent decelerations that begin after each contraction peak onto her left side. The preceptor asks the student to explain the purpose. Which explanation indicates correct understanding?', '[{"id": "a", "text": "It moves the uterus off the vena cava and aorta to improve flow."}, {"id": "b", "text": "It moves the fetal head off the cervix to stop the vagal response."}, {"id": "c", "text": "It lifts the presenting part off the umbilical cord to free it."}, {"id": "d", "text": "It slows the contractions so that the fetus can rest between them."}]'::jsonb, '["a"]', 'Left lateral positioning moves the gravid uterus off the inferior vena cava and aorta, improving venous return, cardiac output, and uteroplacental blood flow for late decelerations. Head compression causes benign early decels, and elevating the presenting part is the cord-prolapse intervention.'),
  ('vealchop', 27, 'A client''s FHR tracing shows smooth, gradual decelerations that begin after each contraction peak and return to baseline after the contraction is over. Her partner asks what this means. Which response by the nurse best explains the pattern?', '[{"id": "a", "text": "The baby''s head is being squeezed as it moves down."}, {"id": "b", "text": "The baby''s cord is being pinched between body parts."}, {"id": "c", "text": "The baby is in a sleep cycle and is less responsive now."}, {"id": "d", "text": "The baby isn''t getting enough oxygen from the placenta."}]'::jsonb, '["d"]', 'Decelerations beginning after the contraction peak are late decelerations, meaning the fetus is not getting adequate oxygen through the placenta. Head compression causes early decels, and cord compression causes variable decels.'),
  ('vealchop', 28, 'During a busy shift, the nurse reviews the FHR tracings of four laboring clients. Which fetal finding requires the most urgent follow-up?', '[{"id": "a", "text": "Baseline 120 bpm with uniform dips mirroring contractions"}, {"id": "b", "text": "Variability of 3 bpm with recurrent decels after peaks"}, {"id": "c", "text": "Baseline 155 bpm with accelerations of 15 bpm for 15 sec"}, {"id": "d", "text": "Single abrupt drop of 20 bpm that recovers in 20 seconds"}]'::jsonb, '["b"]', 'Minimal variability (<5 bpm) suggests possible fetal CNS depression, and with recurrent late decelerations it requires urgent evaluation. Early decels and accelerations are benign or reassuring, and a single mild variable decel is usually benign.'),
  ('vealchop', 29, 'A client at 34 weeks has a 40-minute fetal monitoring session. The baseline is 140 bpm with 8-bpm variability, but the FHR never rises 15 bpm or more above baseline. How should the nurse interpret this tracing?', '[{"id": "a", "text": "Reassuring, because the baseline and variability are normal"}, {"id": "b", "text": "Expected, because accelerations are not seen before 36 weeks"}, {"id": "c", "text": "Non-reassuring, because accelerations are absent at this age"}, {"id": "d", "text": "Reactive, because there are no decelerations on the tracing"}]'::jsonb, '["c"]', 'Absence of accelerations at ≥32 weeks is non-reassuring even with a normal baseline. A reactive NST uses the acceleration criterion (≥15 bpm × ≥15 sec), so the absence of decelerations alone does not make a tracing reactive.'),
  ('vealchop', 30, 'A laboring client has abrupt FHR drops whose timing is unrelated to her contractions. Which description of these drops should the nurse treat as the most urgent?', '[{"id": "a", "text": "Severe drops to 70 bpm that are prolonged before recovering"}, {"id": "b", "text": "Mild drops of 15–20 bpm that recover within seconds"}, {"id": "c", "text": "Occasional brief drops that resolve after the client turns over"}, {"id": "d", "text": "Drops that occur mainly during position changes in bed"}]'::jsonb, '["a"]', 'Abrupt drops unrelated to contraction timing are variable decelerations; mild ones are usually benign, but severe or prolonged ones are urgent. Drops that resolve with repositioning reflect relieved cord compression.'),
  ('vealchop', 31, 'A client in preterm labor received terbutaline 30 minutes ago. Her temperature is normal, and the FHR baseline has risen from 145 to 168 bpm with moderate variability. Which interpretation is most likely?', '[{"id": "a", "text": "Accelerations due to fetal movement after the medication"}, {"id": "b", "text": "Fetal tachycardia related to the medication effect"}, {"id": "c", "text": "Fetal tachycardia caused by maternal fever and infection"}, {"id": "d", "text": "A normal baseline that remains in the expected range"}]'::jsonb, '["b"]', 'A baseline above 160 bpm is fetal tachycardia, and medications such as terbutaline are a listed cause; the normal temperature makes maternal fever unlikely. A sustained baseline rise is not an acceleration.'),
  ('vealchop', 32, 'A laboring client is receiving magnesium. The FHR baseline is 130 bpm with only about 4 bpm of fluctuation and no decelerations or accelerations. Which statement best describes this finding?', '[{"id": "a", "text": "Moderate variability indicating an intact fetal CNS"}, {"id": "b", "text": "Fetal bradycardia that is related to the magnesium"}, {"id": "c", "text": "Blunted accelerations that are still reassuring"}, {"id": "d", "text": "Minimal variability that may be a medication effect"}]'::jsonb, '["d"]', 'Fluctuation below 5 bpm is minimal variability, which can result from medications such as magnesium and is non-reassuring. The 130-bpm baseline is within 110–160, so it is not bradycardia.'),
  ('vealchop', 33, 'A client receiving oxytocin has recurrent FHR decelerations that start after each contraction peak. Which action by a newly hired nurse requires the charge nurse to intervene?', '[{"id": "a", "text": "Discontinues the oxytocin infusion"}, {"id": "b", "text": "Applies oxygen at 10 L/min by face mask"}, {"id": "c", "text": "Positions the client flat on her back"}, {"id": "d", "text": "Increases the rate of the primary IV fluid"}]'::jsonb, '["c"]', 'Late-decel management includes left lateral positioning, stopping oxytocin, O₂, IV fluids, and provider notification; lying flat on the back does not move the uterus off the vena cava and aorta. The other actions are correct steps.'),
  ('vealchop', 34, 'Fifteen minutes after a laboring client becomes hypotensive, the nurse notes the FHR baseline has fallen from 140 to 100 bpm and remains there. Which interpretation is most accurate?', '[{"id": "a", "text": "Fetal bradycardia that may be linked to maternal hypotension"}, {"id": "b", "text": "Early decelerations from head compression during contractions"}, {"id": "c", "text": "Normal baseline variation that requires no nursing response"}, {"id": "d", "text": "Fetal tachycardia reflecting a compensatory fetal response"}]'::jsonb, '["a"]', 'A baseline below 110 bpm is fetal bradycardia, a non-reassuring pattern that may indicate maternal hypotension, cord compression, fetal hypoxia, or medication effects. Early decelerations are transient dips that mirror contractions, not a sustained low baseline.'),
  ('vealchop', 35, 'A client''s FHR continues to show recurrent decelerations beginning after each contraction peak despite left lateral positioning, stopping the oxytocin, oxygen by mask, an IV fluid increase, and provider notification. What should the nurse anticipate NEXT?', '[{"id": "a", "text": "Amnioinfusion to cushion the umbilical cord"}, {"id": "b", "text": "Restarting oxytocin at a lower infusion rate"}, {"id": "c", "text": "Preparing the client for delivery of the fetus"}, {"id": "d", "text": "Continued observation, as the pattern is benign"}]'::jsonb, '["c"]', 'The late-decel sequence ends with preparing for delivery after the provider is notified. Amnioinfusion is for variable decels, and late decels are an emergency, not a benign pattern.'),
  ('vealchop', 36, 'Four clients in early labor have the following FHR baselines, each with 8 to 12 bpm of variability and no decelerations. Which fetal heart rate requires the nurse''s immediate follow-up?', '[{"id": "a", "text": "112 bpm"}, {"id": "b", "text": "164 bpm"}, {"id": "c", "text": "158 bpm"}, {"id": "d", "text": "118 bpm"}]'::jsonb, '["b"]', 'Normal FHR is 110–160 bpm, so 164 bpm is tachycardia and should be reported. Baselines of 112, 118, and 158 bpm all fall within the normal range.'),
  ('vealchop', 37, 'A client at 6 cm watches the monitor and notices that the FHR line constantly wiggles between about 132 and 148 bpm around a baseline of 140 bpm. She asks if something is wrong. Which response by the nurse is best?', '[{"id": "a", "text": "The rapid changes suggest the baby''s cord is being squeezed."}, {"id": "b", "text": "The baby may be sleeping deeply, so the line keeps changing."}, {"id": "c", "text": "The baby''s heart rate is too fast, so I''ll call the provider."}, {"id": "d", "text": "This normal bouncing pattern is a reassuring, healthy sign."}]'::jsonb, '["d"]', 'A fluctuation of about 16 bpm falls within the normal 6–25 bpm variability range, which is reassuring. A baseline of 140 bpm is within 110–160, so it is not tachycardia.'),
  ('vealchop', 38, 'The labor nurse is notified about four clients at the same time. Which client should the nurse go to FIRST?', '[{"id": "a", "text": "FHR fell from 150 to 100 bpm three minutes ago and has not recovered"}, {"id": "b", "text": "FHR had one brief, abrupt drop of 15 bpm that recovered within seconds"}, {"id": "c", "text": "FHR dips gradually with each contraction and recovers as it ends"}, {"id": "d", "text": "FHR rises 20 bpm for 20 seconds each time the fetus moves"}]'::jsonb, '["a"]', 'A drop of ≥15 bpm lasting 2–10 minutes is a prolonged deceleration, whose causes (cord prolapse, maternal hypotension, hyperstimulation, abruption) must be treated urgently. A brief mild variable decel is usually benign, mirroring dips are early decels, and accelerations are reassuring.'),
  ('vealchop', 39, 'A client at 5 cm has FHR drops that are abrupt, U-shaped, and occur at unpredictable times relative to her contractions. When the nurse helps her turn from one side to the other, she asks why. Which explanation by the nurse is best?', '[{"id": "a", "text": "Turning moves the baby''s head off your cervix to stop the dips."}, {"id": "b", "text": "Turning slows your contractions so the placenta can recover."}, {"id": "c", "text": "Turning takes the uterus off your major vessels to raise your blood pressure."}, {"id": "d", "text": "Turning may relieve pressure on the umbilical cord to restore flow."}]'::jsonb, '["d"]', 'Abrupt U-shaped drops with variable timing are variable decelerations from cord compression; repositioning side to side relieves the compression. Moving the uterus off the major vessels is the rationale for left lateral positioning in late decelerations.'),
  ('vealchop', 40, 'A client at 41 weeks is laboring without oxytocin, with contractions every 3 minutes. The FHR (baseline 150 bpm) shows a smooth, gradual decline that begins after each contraction peak and recovers after the contraction ends. Which underlying problem does this pattern indicate?', '[{"id": "a", "text": "Fetal head compression as it descends into the pelvis"}, {"id": "b", "text": "Umbilical cord compression caused by low amniotic fluid"}, {"id": "c", "text": "Normal vagal response to contractions in active labor"}, {"id": "d", "text": "Uteroplacental insufficiency limiting fetal oxygenation"}]'::jsonb, '["d"]', 'A gradual drop beginning after the contraction peak is a late deceleration caused by placental insufficiency/uteroplacental compromise. A vagal response from head compression produces early decels that mirror the contraction.'),
  ('vealchop', 41, 'A preceptor asks a nursing student to describe a client''s FHR pattern of abrupt, W-shaped drops that occur at irregular times. Which statement by the student requires correction?', '[{"id": "a", "text": "These drops are most likely caused by umbilical cord compression."}, {"id": "b", "text": "Changing the client''s position is the first nursing action."}, {"id": "c", "text": "These drops begin after the peak of each uterine contraction."}, {"id": "d", "text": "Severe or prolonged drops of this type are treated as urgent."}]'::jsonb, '["c"]', 'Abrupt V/U/W-shaped dips that vary in timing are variable decelerations, which are not tied to contractions; beginning after the contraction peak describes late decelerations. The other statements about cord compression, repositioning, and severity are correct.'),
  ('vealchop', 42, 'The nurse has placed a client with a visible prolapsed cord in knee-chest position and is manually elevating the presenting part with a gloved hand. The FHR remains 80 bpm. Which action should occur NEXT?', '[{"id": "a", "text": "Remove the hand to perform an amnioinfusion"}, {"id": "b", "text": "Apply oxygen and prepare for an emergency C-section"}, {"id": "c", "text": "Turn the client to her left side and recheck the FHR"}, {"id": "d", "text": "Document the FHR and reassess it in 15 minutes"}]'::jsonb, '["b"]', 'After knee-chest positioning and manual elevation of the presenting part, the nurse applies O₂ and prepares for emergency C-section. Amnioinfusion is for persistent variable decelerations, and left lateral positioning is the late-decel intervention.'),
  ('vealchop', 43, 'The nurse is documenting a deceleration seen during a client''s last contraction: the FHR began a gradual fall only after the contraction had peaked and returned to baseline after the contraction ended. Which documentation entry is accurate?', '[{"id": "a", "text": "Late deceleration; nurse initiated left lateral positioning"}, {"id": "b", "text": "Early deceleration; no intervention required at this time"}, {"id": "c", "text": "Variable deceleration; amnioinfusion requested from provider"}, {"id": "d", "text": "Prolonged deceleration; fetal baseline reassessed in 2 hours"}]'::jsonb, '["a"]', 'A gradual drop beginning after the contraction peak is a late deceleration, and left lateral positioning is the first intervention. Early decels mirror the contraction, and variable decels are abrupt with variable timing.'),
  ('vealchop', 44, 'During a nonstress test at 33 weeks, the FHR baseline is 135 bpm. Twice in 20 minutes the FHR rises to exactly 150 bpm and stays there for exactly 15 seconds before returning to baseline. How should the nurse interpret these findings?', '[{"id": "a", "text": "Not accelerations, because the rise must exceed 15 bpm"}, {"id": "b", "text": "Not accelerations, because they must last over 15 seconds"}, {"id": "c", "text": "Accelerations, but they are not meaningful before 36 weeks"}, {"id": "d", "text": "Accelerations that meet the criteria for a reactive test"}]'::jsonb, '["d"]', 'Accelerations require a rise of at least 15 bpm lasting at least 15 seconds, so a 15-bpm rise for 15 seconds qualifies; this is the same criterion as a reactive NST. Accelerations are expected at 33 weeks because their absence at ≥32 weeks is non-reassuring.'),
  ('vealchop', 45, 'The nurse reviews 40-minute fetal monitoring strips for four clients who are not in labor. Which finding requires the nurse''s immediate follow-up with the provider?', '[{"id": "a", "text": "At 30 weeks: baseline 150 bpm, 10-bpm variability, no decelerations"}, {"id": "b", "text": "At 38 weeks: baseline 130 bpm with two 18-bpm, 20-second rises"}, {"id": "c", "text": "At 35 weeks: baseline 140 bpm, 8-bpm variability, no rises of 15 bpm"}, {"id": "d", "text": "At 37 weeks: baseline 125 bpm with moderate variability and rises"}]'::jsonb, '["c"]', 'Absence of accelerations at ≥32 weeks is non-reassuring, so the 35-week fetus with no rises of 15 bpm should be reported. The 38-week fetus has accelerations meeting the ≥15 bpm × ≥15 sec criteria.'),
  ('vealchop', 46, 'A client with low amniotic fluid has severe, abrupt FHR drops that persist after repositioning, and the provider prescribes an amnioinfusion. Which items should the nurse anticipate needing?', '[{"id": "a", "text": "IUPC and sterile saline solution"}, {"id": "b", "text": "Nasal cannula to deliver oxygen at 2 L/min"}, {"id": "c", "text": "Wedge to place under the client''s right hip"}, {"id": "d", "text": "IV dextrose bolus to improve placental blood flow"}]'::jsonb, '["a"]', 'Amnioinfusion is an infusion of sterile saline into the amniotic cavity via an intrauterine pressure catheter (IUPC). It cushions the cord in severe variable decelerations and restores volume in oligohydramnios.'),
  ('vealchop', 47, 'A client at 39 weeks in early labor notices that the FHR jumps from 140 to about 160 bpm for 20 to 30 seconds whenever the baby kicks, then returns to 140. She asks if this is a problem. Which response by the nurse is best?', '[{"id": "a", "text": "This means the baby is too fast, so I will notify the provider."}, {"id": "b", "text": "This shows the baby''s nervous system and oxygen levels are good."}, {"id": "c", "text": "This means the cord gets squeezed whenever the baby moves around."}, {"id": "d", "text": "This is a warning sign, so I will turn you onto your left side."}]'::jsonb, '["b"]', 'A rise of about 20 bpm for 20–30 seconds is an acceleration, indicating intact fetal CNS and adequate oxygenation, and needs no action. The baseline stays at 140 bpm, so this is not tachycardia.'),
  ('vealchop', 48, 'A client with recurrent decelerations beginning after each contraction peak has been turned to her left side, given oxygen by face mask, and had her IV rate increased. Which finding 30 minutes later BEST indicates these interventions have been effective?', '[{"id": "a", "text": "Baseline 135 bpm, 3-bpm variability, no further decelerations"}, {"id": "b", "text": "Baseline 170 bpm, 10-bpm variability, no further decelerations"}, {"id": "c", "text": "Baseline 140 bpm with gradual decels still starting after peaks"}, {"id": "d", "text": "Baseline 140 bpm, 12-bpm variability, accelerations present"}]'::jsonb, '["d"]', 'Accelerations with moderate (6–25 bpm) variability and a normal baseline is the most reassuring pattern, showing adequate oxygenation. A 3-bpm variability is minimal and 170 bpm is tachycardia, both non-reassuring.'),
  ('vealchop', 49, 'The nurse reviews the tracings of four laboring clients. Which FHR pattern requires only continued routine monitoring, with no nursing intervention?', '[{"id": "a", "text": "Abrupt V-shaped drops to 90 bpm at irregular times"}, {"id": "b", "text": "Gradual dips that begin after each contraction peak"}, {"id": "c", "text": "Rises of 20 bpm above baseline lasting 20 seconds"}, {"id": "d", "text": "A baseline of 104 bpm with 8-bpm variability"}]'::jsonb, '["c"]', 'Rises of ≥15 bpm for ≥15 seconds are accelerations, a reassuring sign that needs no action. Variable decels need repositioning, late decels need immediate action, and a baseline under 110 bpm is bradycardia.'),
  ('vealchop', 50, 'A client at 39 weeks with oligohydramnios has recurrent abrupt FHR drops. The provider plans an amnioinfusion, and the client asks what it will do for her baby. Which explanation by the nurse is best?', '[{"id": "a", "text": "It replaces fluid around the baby to help protect the cord."}, {"id": "b", "text": "It dilutes meconium so the baby is less likely to inhale it."}, {"id": "c", "text": "It improves the oxygen the baby receives from the placenta."}, {"id": "d", "text": "It slows your contractions so that the baby can recover."}]'::jsonb, '["a"]', 'In oligohydramnios, the goal of amnioinfusion is to restore fluid volume to protect the cord. Diluting meconium is the goal only when thick meconium-stained fluid is present.'),
  ('abruption', 1, 'A G2P1 client at 34 weeks is brought in after a car crash. She reports sudden, severe abdominal pain, her uterus is rigid and board-like, and there is a small amount of vaginal bleeding. Which condition should the nurse suspect?', '[{"id": "a", "text": "Premature separation of the placenta"}, {"id": "b", "text": "Placenta covering the cervical os"}, {"id": "c", "text": "Premature rupture of the membranes"}, {"id": "d", "text": "Disseminated intravascular coagulation"}]'::jsonb, '["a"]', 'Sudden severe abdominal pain with a rigid, board-like uterus and some bleeding after trauma indicates premature separation of a normally implanted placenta. A placenta covering the os causes painless bleeding with a soft uterus.'),
  ('abruption', 2, 'A client at 36 weeks with preeclampsia reports constant abdominal pain. Her pad is dry, but the uterus is tense and looks larger than on admission 3 hours ago. Pulse rose from 88 to 116/min and BP fell from 150/98 to 98/62. What should the nurse suspect?', '[{"id": "a", "text": "Concealed bleeding trapped behind the placenta"}, {"id": "b", "text": "Placenta previa with painless, bright red bleeding"}, {"id": "c", "text": "Partial separation with only visible bleeding"}, {"id": "d", "text": "Rapid uterine decompression from fluid loss"}]'::jsonb, '["a"]', 'A concealed abruption traps blood behind the placenta, so no vaginal blood is seen while the uterus becomes tense and may enlarge; the pulse and BP changes reflect shock. Previa bleeding is painless and visible.'),
  ('abruption', 3, 'A client at 32 weeks has sudden severe abdominal pain and a rigid uterus after a fall. BP is 88/50, pulse 128/min, and she is pale and diaphoretic. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Establish two large-bore IV lines"}, {"id": "b", "text": "Screen for domestic violence as the cause"}, {"id": "c", "text": "Inspect the skin for petechiae and oozing"}, {"id": "d", "text": "Review her history for a prior abruption"}]'::jsonb, '["a"]', 'Hypotension, tachycardia, and pale, diaphoretic skin indicate shock, so large-bore IV access ×2 comes first. Identifying the cause and watching for DIC are important but follow circulatory support.'),
  ('abruption', 4, 'A client at 35 weeks has a rigid, painful uterus, a pulse of 118/min, and signs of fetal distress on continuous monitoring. Two IV lines are infusing. Which oxygen order should the nurse expect to implement?', '[{"id": "a", "text": "2–4 L/min by nasal cannula"}, {"id": "b", "text": "8–10 L/min by face mask"}, {"id": "c", "text": "8–10 L/min by nasal cannula"}, {"id": "d", "text": "4–6 L/min by simple face mask"}]'::jsonb, '["b"]', 'With suspected abruption and fetal distress, oxygen is given at 8–10 L/min via face mask. The same flow by nasal cannula or a lower flow by mask does not match this priority.'),
  ('abruption', 5, 'After an emergency cesarean for a severe placental abruption, a client has blood oozing around her IV site and new petechiae on her chest. Which laboratory tests should the nurse anticipate monitoring closely?', '[{"id": "a", "text": "Liver enzymes and serum bilirubin"}, {"id": "b", "text": "24-hour urine protein and creatinine"}, {"id": "c", "text": "PT/PTT, fibrinogen, and platelets"}, {"id": "d", "text": "Blood glucose and serum electrolytes"}]'::jsonb, '["c"]', 'Oozing at IV sites and petechiae after severe abruption suggest DIC, a coagulation emergency monitored with PT/PTT, fibrinogen, and platelets. The other panels do not track clotting.'),
  ('abruption', 6, 'Two hours after an emergency cesarean for complete placental separation, the nurse finds oozing gums, blood-tinged urine in the catheter bag, and bleeding from an old IV site. What do these findings MOST likely indicate?', '[{"id": "a", "text": "Disseminated intravascular coagulation"}, {"id": "b", "text": "A concealed abruption that is recurring"}, {"id": "c", "text": "Expected bleeding after cesarean surgery"}, {"id": "d", "text": "Hypovolemic shock from the separation"}]'::jsonb, '["a"]', 'Uncontrolled bleeding from IV sites, oozing gums, and hematuria after severe abruption are signs of DIC. The placenta has been delivered, so recurrent concealed abruption does not explain bleeding at several sites.'),
  ('abruption', 7, 'A triage nurse receives four calls from clients past 20 weeks of gestation who report vaginal bleeding. Which caller''s description is MOST consistent with placental abruption?', '[{"id": "a", "text": "\"The blood is bright red, but I have no pain at all.\""}, {"id": "b", "text": "\"My belly is soft and doesn''t hurt when I press on it.\""}, {"id": "c", "text": "\"I have bright red spotting without any cramping now.\""}, {"id": "d", "text": "\"It hurts badly, and my belly feels hard as a board.\""}]'::jsonb, '["d"]', 'Bleeding with pain and a rigid, board-like uterus points to abruption. Painless bright red bleeding with a soft, non-tender uterus describes previa.'),
  ('abruption', 8, 'The nurse is setting monitoring priorities on an antepartum unit. Based on the leading cause of placental abruption, which client should the nurse monitor MOST closely for signs of separation?', '[{"id": "a", "text": "A client at 33 weeks with one prior vaginal birth"}, {"id": "b", "text": "A client at 33 weeks with a soft, non-tender uterus"}, {"id": "c", "text": "A client at 33 weeks who is 30 years of age"}, {"id": "d", "text": "A client at 33 weeks with preeclampsia"}]'::jsonb, '["d"]', 'Hypertension, including preeclampsia, is the number one cause of placental abruption. A prior uncomplicated birth or maternal age of 30 is not a listed abruption risk factor.'),
  ('abruption', 9, 'A client at 30 weeks has abdominal pain, a rigid uterus, and bruises in various stages on her arms. She says she ''fell down the stairs'' and avoids eye contact. Once stabilization is under way, which action is MOST important to identify the cause?', '[{"id": "a", "text": "Ask about a family history of bleeding"}, {"id": "b", "text": "Check whether her placenta covers the os"}, {"id": "c", "text": "Assess privately for domestic violence"}, {"id": "d", "text": "Ask about her number of prior pregnancies"}]'::jsonb, '["c"]', 'Trauma, including domestic violence and falls, is a cause of abruption, and the nurse must identify and treat the cause. Bruises in various stages with an inconsistent story point to possible abuse.'),
  ('abruption', 10, 'A client at 29 weeks has a positive urine screen for cocaine and arrives with sudden, severe abdominal pain and a rigid uterus. She asks how cocaine could cause this. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"It causes the placenta to implant over the cervical opening.\""}, {"id": "b", "text": "\"It makes the membranes rupture before labor has started.\""}, {"id": "c", "text": "\"It narrows blood vessels, which can make the placenta separate.\""}, {"id": "d", "text": "\"It lowers blood pressure and slows the flow to the placenta.\""}]'::jsonb, '["c"]', 'Cocaine and tobacco cause vasoconstriction, a risk factor for placental abruption. A placenta implanted over the os describes previa, which presents with painless bleeding.'),
  ('abruption', 11, 'A client at 37 weeks with twins and polyhydramnios has an amniotomy that releases a large volume of fluid at once. Within minutes she reports severe, constant abdominal pain and her uterus becomes rigid. Which factor MOST likely contributed?', '[{"id": "a", "text": "Rapid uterine decompression"}, {"id": "b", "text": "Hypertensive vasoconstriction"}, {"id": "c", "text": "Placenta covering the os"}, {"id": "d", "text": "Recurrence of prior abruption"}]'::jsonb, '["a"]', 'Sudden loss of a large fluid volume with polyhydramnios and a multiple gestation causes rapid uterine decompression, a risk factor for abruption. Nothing in the history suggests hypertension or a prior abruption.'),
  ('abruption', 12, 'A client at 34 weeks has painful vaginal bleeding and a firm, tender uterus after a minor car accident. The resident asks the nurse to set up for a vaginal exam to check dilation. What is the nurse''s BEST response?', '[{"id": "a", "text": "Set up for a sterile exam using extra lubricant"}, {"id": "b", "text": "Set up for the exam as soon as IV access has been established"}, {"id": "c", "text": "Set up for the exam because no blood is pooling"}, {"id": "d", "text": "Advise the resident that vaginal exams are avoided here"}]'::jsonb, '["d"]', 'Painful bleeding with a tender, firm uterus after trauma suggests abruption, and a vaginal exam is never done. IV access or the amount of visible blood does not make the exam safe.'),
  ('abruption', 13, 'A client at 33 weeks with suspected placental abruption has a pulse of 108/min and BP of 100/60. The nurse realizes the oxygen face mask is in the supply room down the hall. What is the BEST action?', '[{"id": "a", "text": "Leave briefly, since her vital signs are acceptable"}, {"id": "b", "text": "Stay with the client and call for someone to bring it"}, {"id": "c", "text": "Ask the client''s partner to watch her for a minute"}, {"id": "d", "text": "Finish charting first, then retrieve the mask quickly"}]'::jsonb, '["b"]', 'A client with suspected abruption must not be left unattended because her condition is time-critical and can deteriorate quickly. A family member cannot replace nursing surveillance.'),
  ('abruption', 14, 'A client at 34 weeks is being observed after a fall at home and has had no vaginal bleeding since arriving 2 hours ago. Which assessment finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "A soft uterus with mild bruising on one knee"}, {"id": "b", "text": "A tense, enlarging uterus with a rising pulse"}, {"id": "c", "text": "A dry pad and no reports of abdominal pain"}, {"id": "d", "text": "Normal fetal heart tones on continuous monitoring"}]'::jsonb, '["b"]', 'Trauma is an abruption risk, and concealed bleeding causes no visible blood while the uterus becomes tense and may enlarge; a rising pulse suggests shock. These concealed hemorrhage signs must not be missed.'),
  ('abruption', 15, 'A client at 31 weeks is admitted with abdominal pain, a rigid uterus, and light vaginal bleeding. Her vital signs are stable for the moment. Which fetal monitoring approach is MOST appropriate?', '[{"id": "a", "text": "Doppler checks of the FHR every hour"}, {"id": "b", "text": "An FHR assessment once every shift"}, {"id": "c", "text": "Fetal kick counts reported by the client"}, {"id": "d", "text": "Continuous electronic FHR monitoring"}]'::jsonb, '["d"]', 'Pain with a rigid uterus suggests abruption, which requires continuous FHR monitoring to detect fetal distress. Intermittent checks could miss sudden deterioration.'),
  ('abruption', 16, 'A client at 35 weeks has sudden severe abdominal pain, a board-like uterus, and continuous monitoring now shows signs of fetal distress. Two IV lines are running and blood is crossmatched. Which plan should the nurse anticipate?', '[{"id": "a", "text": "Oxytocin induction of labor"}, {"id": "b", "text": "Observation until bleeding stops"}, {"id": "c", "text": "Vaginal birth with monitoring"}, {"id": "d", "text": "Emergency cesarean birth"}]'::jsonb, '["d"]', 'Pain with a board-like uterus and fetal distress indicates abruption, which is delivered by emergency C-section. Waiting for bleeding to stop ignores how time-critical abruption is.'),
  ('abruption', 17, 'A client at 32 weeks arrives with painful vaginal bleeding and a rigid uterus; her pulse is 112/min. The nurse has placed two large-bore IVs. Which laboratory action is MOST urgent?', '[{"id": "a", "text": "Collect a 24-hour urine sample"}, {"id": "b", "text": "Draw liver enzymes in the morning"}, {"id": "c", "text": "Obtain a urine drug screen first"}, {"id": "d", "text": "Send a type and crossmatch now"}]'::jsonb, '["d"]', 'With suspected abruption and tachycardia, blood must be typed and crossmatched immediately in case of hemorrhage. Screening for causes such as drug use is less urgent.'),
  ('abruption', 18, 'A client at 33 weeks with painful vaginal bleeding becomes pale and diaphoretic. Her pulse is 124/min and BP 86/50. She says, ''I''m just nervous.'' Which interpretation should guide the nurse''s next action?', '[{"id": "a", "text": "She is showing signs of shock"}, {"id": "b", "text": "She is having an anxiety reaction"}, {"id": "c", "text": "She is showing early signs of DIC"}, {"id": "d", "text": "She is reacting to the oxygen mask"}]'::jsonb, '["a"]', 'Tachycardia, hypotension, and pale, diaphoretic skin are signs of shock in abruption. Anxiety does not explain hypotension, and DIC presents with bleeding from IV sites, petechiae, or oozing gums.'),
  ('abruption', 19, 'A client at 34 weeks has severe abdominal pain, a rigid uterus, a pulse of 120/min, and a small spot of blood on her pad. Her partner asks, ''How can she be so sick if she''s barely bleeding?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Blood can collect behind the placenta where we can''t see it.\""}, {"id": "b", "text": "\"Most of the bleeding is coming from vessels over the cervix.\""}, {"id": "c", "text": "\"Pain this severe means the bleeding has already stopped.\""}, {"id": "d", "text": "\"A small spot shows the separation is minor and stable.\""}]'::jsonb, '["a"]', 'In abruption, blood collects between the placenta and uterine wall and may be concealed, so visible blood can underestimate the loss. Bleeding from vessels over the cervix describes previa.'),
  ('abruption', 20, 'A client recovering from a severe placental abruption develops petechiae, oozing gums, and bleeding from IV sites. Her PT and PTT are prolonged and her platelet count is low. Which intervention should the nurse anticipate as the PRIORITY?', '[{"id": "a", "text": "Insert a new IV line in the other arm"}, {"id": "b", "text": "Administer blood products as ordered"}, {"id": "c", "text": "Teach about recurrence in a future pregnancy"}, {"id": "d", "text": "Apply cool compresses to the oozing sites"}]'::jsonb, '["b"]', 'These findings indicate DIC, a coagulation emergency treated by administering blood products as ordered. A new IV site would likely ooze as well, and teaching can wait.'),
  ('abruption', 21, 'A client at 36 weeks has sudden severe pain, a rigid uterus, BP 80/46, pulse 136/min, and continuous monitoring shows fetal distress. Which type of placental separation do these findings MOST suggest?', '[{"id": "a", "text": "Complete separation of the entire placenta"}, {"id": "b", "text": "Partial separation with mild, visible bleeding"}, {"id": "c", "text": "A placenta covering the internal cervical os"}, {"id": "d", "text": "A placental edge that lies close to the os"}]'::jsonb, '["a"]', 'When the entire placenta separates, maternal and fetal hemorrhage and shock result, matching these findings. Partial separation is mild to moderate, and placentas at or over the os cause painless bleeding.'),
  ('abruption', 22, 'A client at 33 weeks has mild abdominal pain, slight uterine tenderness, a small amount of visible bleeding, stable vital signs, and reassuring fetal monitoring. Which type of placental separation do these findings MOST suggest?', '[{"id": "a", "text": "Complete separation"}, {"id": "b", "text": "Partial separation"}, {"id": "c", "text": "Concealed separation"}, {"id": "d", "text": "Total placenta previa"}]'::jsonb, '["b"]', 'Partial abruption is mild to moderate, with part of the placenta separating and some bleeding. Complete separation causes hemorrhage and shock, and concealed abruption shows no visible blood.'),
  ('abruption', 23, 'A nurse is comparing two clients at 36 weeks. Client 1 has a total placenta previa with bleeding. Client 2 has painful bleeding with a rigid, board-like uterus. Which delivery method should the nurse anticipate for Client 2?', '[{"id": "a", "text": "Vaginal birth with monitoring"}, {"id": "b", "text": "Emergency cesarean birth"}, {"id": "c", "text": "Oxytocin induction at term"}, {"id": "d", "text": "Scheduled cesarean at 39 weeks"}]'::jsonb, '["b"]', 'Painful bleeding with a board-like uterus is abruption, which requires emergency C-section. A scheduled cesarean would delay a time-critical delivery.'),
  ('abruption', 24, 'A nursing student is helping set up for a client at 32 weeks admitted with sudden abdominal pain, a rigid uterus, and visible bleeding. Which action by the student requires the nurse to intervene?', '[{"id": "a", "text": "Placing the fetal monitor for continuous use"}, {"id": "b", "text": "Preparing a speculum tray for a pelvic exam"}, {"id": "c", "text": "Gathering two large-bore IV catheters"}, {"id": "d", "text": "Bringing an oxygen face mask to the room"}]'::jsonb, '["b"]', 'Pain with a rigid uterus and bleeding suggests abruption, so vaginal and pelvic exams are not done. Continuous FHR monitoring, large-bore IVs, and face-mask oxygen are all priorities.'),
  ('abruption', 25, 'A client at 34 weeks develops severe abdominal pain and a board-like uterus; her pulse is 110/min. The nurse plans to wait for lab results before calling the provider so the report will be complete. Which evaluation of this plan is accurate?', '[{"id": "a", "text": "It is safe as long as her vital signs stay stable"}, {"id": "b", "text": "It is unsafe; the provider should be called now"}, {"id": "c", "text": "It is acceptable if there is no visible bleeding"}, {"id": "d", "text": "It is safe if the fetal monitor remains in place"}]'::jsonb, '["b"]', 'Suspected abruption is time-critical, and notification of the provider must not be delayed. Absent visible bleeding does not mean safety, because hemorrhage may be concealed.'),
  ('abruption', 26, 'The nurse is caring for four clients who experienced placental abruption. Which client should the nurse monitor MOST closely for disseminated intravascular coagulation (DIC)?', '[{"id": "a", "text": "Partial separation with minimal bleeding"}, {"id": "b", "text": "Severe separation with hemorrhage and shock"}, {"id": "c", "text": "Mild pain with stable vital signs"}, {"id": "d", "text": "Light bleeding with a reassuring fetal status"}]'::jsonb, '["b"]', 'Severe abruption can lead to DIC, so the client with hemorrhage and shock is at greatest risk. The other clients have mild separations.'),
  ('abruption', 27, 'A client at 32 weeks is admitted after her membranes ruptured before the onset of labor. Twelve hours later she reports sudden, constant abdominal pain, and her uterus is firm and tender between palpations. Which complication should the nurse suspect?', '[{"id": "a", "text": "Placental abruption"}, {"id": "b", "text": "Placenta previa"}, {"id": "c", "text": "Disseminated intravascular coagulation"}, {"id": "d", "text": "Rapid uterine decompression"}]'::jsonb, '["a"]', 'PROM is a risk factor for abruption, and sudden pain with a firm, tender uterus fits separation. Previa bleeding is painless with a soft uterus, and there are no bleeding signs suggesting DIC.'),
  ('abruption', 28, 'At a first prenatal visit, a 30-year-old G3P2 reports that her placenta ''came loose'' during her last pregnancy and she needed an emergency birth. She does not smoke and has no hypertension. Which nursing action is MOST appropriate?', '[{"id": "a", "text": "Reassure her it is unlikely to happen again"}, {"id": "b", "text": "Plan pelvic rest, since the placenta may cover the os"}, {"id": "c", "text": "Flag the prior abruption as a risk factor"}, {"id": "d", "text": "Teach that only trauma can make a placenta separate"}]'::jsonb, '["c"]', 'Prior abruption is a risk factor for abruption in a later pregnancy, so it should be flagged. Pelvic rest for a placenta over the os relates to previa, and trauma is one of several causes.'),
  ('abruption', 29, 'Two clients at 34 weeks report vaginal bleeding. On palpation, one has a soft uterus and the other a rigid uterus. Which additional finding in the client with the rigid uterus would MOST support the nurse''s suspicion?', '[{"id": "a", "text": "Sudden onset of severe abdominal pain"}, {"id": "b", "text": "Painless bleeding that is bright red"}, {"id": "c", "text": "Bleeding that began without contractions"}, {"id": "d", "text": "Placental tissue over the cervical os"}]'::jsonb, '["a"]', 'Abruption presents with sudden severe abdominal pain plus a rigid, board-like uterus, with or without bleeding. Painless bright red bleeding and a placenta over the os describe previa.'),
  ('abruption', 30, 'At the start of a shift, the nurse receives report on four antepartum clients between 32 and 36 weeks of gestation. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "Painless spotting that stopped, soft uterus"}, {"id": "b", "text": "Preeclampsia, BP controlled, no complaints"}, {"id": "c", "text": "Sudden severe pain, rigid uterus, pulse 118/min"}, {"id": "d", "text": "Prior abruption, no symptoms today, monitor applied"}]'::jsonb, '["c"]', 'Sudden severe pain with a rigid uterus and tachycardia suggests an active abruption, which is time-critical. The other clients are currently stable.'),
  ('abruption', 31, 'A client at 26 weeks with chronic hypertension smokes a pack of cigarettes daily. After teaching about placental abruption, which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Smoking narrows my blood vessels and can harm my placenta.\""}, {"id": "b", "text": "\"Keeping my blood pressure controlled lowers my risk.\""}, {"id": "c", "text": "\"Sudden belly pain with a hard uterus needs care right away.\""}, {"id": "d", "text": "\"Smoking affects my lungs, but not my placenta.\""}]'::jsonb, '["d"]', 'Tobacco causes vasoconstriction and is a risk factor for abruption, so the client misunderstands. Hypertension is the number one cause, so BP control is appropriate.'),
  ('abruption', 32, 'A client at 32 weeks was in a low-speed car accident and reports no pain or bleeding. Her uterus is soft and her vital signs are at baseline. Which nursing action is MOST appropriate?', '[{"id": "a", "text": "Discharge her home now because no bleeding is visible"}, {"id": "b", "text": "Perform a vaginal exam to check for any hidden bleeding"}, {"id": "c", "text": "Monitor the FHR continuously and watch for hidden bleeding"}, {"id": "d", "text": "Check the FHR once and recheck it at her next prenatal visit"}]'::jsonb, '["c"]', 'A car accident is a trauma risk factor for abruption, and concealed hemorrhage may show no visible blood, so continuous FHR monitoring and vigilance are needed. Vaginal exams are never done.'),
  ('abruption', 33, 'A client at 35 weeks with signs of placental abruption has two large-bore IVs infusing and blood crossmatched. She is restless, and continuous monitoring shows signs of fetal distress. Which intervention should the nurse implement NEXT?', '[{"id": "a", "text": "Perform a pelvic exam to assess dilation"}, {"id": "b", "text": "Collect a urine sample for a drug screen"}, {"id": "c", "text": "Apply oxygen at 8–10 L/min by face mask"}, {"id": "d", "text": "Teach about risk in a future pregnancy"}]'::jsonb, '["c"]', 'Oxygen at 8–10 L/min via face mask is a nursing priority in abruption, especially with fetal distress. Pelvic exams are contraindicated, and cause screening and teaching are not urgent.'),
  ('abruption', 34, 'A UAP reports that a client who had an emergency cesarean for a severe abruption 3 hours ago has ''pink urine in the catheter bag and bleeding gums after brushing her teeth.'' What is the nurse''s PRIORITY action?', '[{"id": "a", "text": "Reassure the UAP that this is expected"}, {"id": "b", "text": "Assess for DIC and notify the provider"}, {"id": "c", "text": "Have the UAP get a softer toothbrush"}, {"id": "d", "text": "Recheck the urine at the next shift"}]'::jsonb, '["b"]', 'Hematuria and oozing gums after severe abruption are signs of DIC, a coagulation emergency. Treating them as expected or delaying assessment could miss life-threatening bleeding.'),
  ('abruption', 35, 'A client at 36 weeks has sudden, severe abdominal pain, no visible vaginal bleeding, and a pulse of 128/min. Her family asks why staff are preparing a blood transfusion when ''there is no blood.'' Which reply by the nurse is BEST?', '[{"id": "a", "text": "\"A transfusion is routine before every cesarean birth.\""}, {"id": "b", "text": "\"Blood is collecting near the cervix and will appear soon.\""}, {"id": "c", "text": "\"Her fast pulse is from pain, so blood is just a precaution.\""}, {"id": "d", "text": "\"Bleeding can be hidden behind the placenta inside the uterus.\""}]'::jsonb, '["d"]', 'A concealed abruption traps blood behind the placenta with no visible vaginal bleeding, while tachycardia signals shock. Attributing the pulse to pain misses concealed hemorrhage.'),
  ('abruption', 36, 'A client at 37 weeks has bright red, painless bleeding and a soft, non-tender uterus. Ultrasound shows the placenta totally covers the cervical os. Which birth plan should the nurse anticipate?', '[{"id": "a", "text": "Emergency cesarean for separation"}, {"id": "b", "text": "Cesarean birth for total previa"}, {"id": "c", "text": "Vaginal birth with close monitoring"}, {"id": "d", "text": "Induction for premature separation"}]'::jsonb, '["b"]', 'Painless bright red bleeding, a soft uterus, and a placenta covering the os indicate previa, delivered by C-section when total. Emergency C-section for premature separation applies to abruption.'),
  ('abruption', 37, 'A client is being discharged after an emergency birth for placental abruption. She has chronic hypertension and smokes. Which statement indicates she understands how to lower her risk in a future pregnancy?', '[{"id": "a", "text": "\"Since it happened once, it cannot happen to me again.\""}, {"id": "b", "text": "\"Car accidents are the one cause, so a seatbelt is enough.\""}, {"id": "c", "text": "\"I will stop smoking and keep my blood pressure controlled.\""}, {"id": "d", "text": "\"Painless bright red bleeding is the sign I watch for.\""}]'::jsonb, '["c"]', 'Hypertension is the number one cause of abruption and tobacco causes vasoconstriction, so both are risks she can reduce. Prior abruption increases, not removes, the risk.'),
  ('abruption', 38, 'A client at 34 weeks with a rigid, painful uterus and signs of fetal distress is receiving oxygen. The nurse finds that the UAP replaced the face mask with a nasal cannula at 2 L/min ''because she said the mask was uncomfortable.'' What should the nurse do FIRST?', '[{"id": "a", "text": "Reapply the face mask at 8–10 L/min"}, {"id": "b", "text": "Leave the cannula and raise it to 4 L/min"}, {"id": "c", "text": "Document her comfort preference and continue"}, {"id": "d", "text": "Leave the cannula and recheck the FHR in an hour"}]'::jsonb, '["a"]', 'Oxygen in abruption is given at 8–10 L/min via face mask, so the original order must be restored. Raising the cannula flow still does not meet the required delivery.'),
  ('abruption', 39, 'At 0200, a client at 33 weeks with preeclampsia reports new, constant abdominal pain. Her uterus is firm and tender, and her pulse has risen from 84 to 110/min. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Recheck her in 30 minutes"}, {"id": "b", "text": "Wait for the morning lab draw"}, {"id": "c", "text": "Document and reassess at 0600"}, {"id": "d", "text": "Notify the provider immediately"}]'::jsonb, '["d"]', 'Sudden pain with a tender, firm uterus and rising pulse in a client with preeclampsia suggests abruption, and notifying the provider must not be delayed. Waiting wastes time in a time-critical emergency.'),
  ('abruption', 40, 'After a severe placental abruption, a client''s family asks why the nurse keeps drawing blood for platelet and fibrinogen levels even though the baby has been delivered. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"These levels show whether her blood pressure is safe.\""}, {"id": "b", "text": "\"These tests check for infection after the cesarean.\""}, {"id": "c", "text": "\"Severe separation can trigger a clotting emergency.\""}, {"id": "d", "text": "\"These levels show whether she can breastfeed safely.\""}]'::jsonb, '["c"]', 'Severe abruption can lead to DIC, a coagulation emergency monitored with PT/PTT, fibrinogen, and platelets. These tests do not assess blood pressure or infection.'),
  ('abruption', 41, 'A client at 34 weeks with sudden severe abdominal pain and a rigid uterus has one small IV running maintenance fluids. Her pulse is 120/min and BP 94/58. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Slow the maintenance fluid rate"}, {"id": "b", "text": "Collect a sample for a drug screen"}, {"id": "c", "text": "Insert a second, large-bore IV line"}, {"id": "d", "text": "Ask about recent trauma or falls"}]'::jsonb, '["c"]', 'Abruption with tachycardia and low BP requires large-bore IV access ×2 for fluid and blood replacement. Identifying the cause matters but comes after circulatory access.'),
  ('abruption', 42, 'Over 20 minutes, a client at 35 weeks with a known partial abruption has a pulse change from 84 to 126/min, BP change from 120/78 to 86/52, and new pallor and sweating. Which conclusion is MOST accurate?', '[{"id": "a", "text": "She is going into shock"}, {"id": "b", "text": "She is anxious about birth"}, {"id": "c", "text": "She has a stable separation"}, {"id": "d", "text": "She is developing DIC signs"}]'::jsonb, '["a"]', 'Tachycardia, hypotension, and pale, diaphoretic skin are the shock findings in abruption. DIC presents with bleeding from IV sites, petechiae, oozing gums, and hematuria.'),
  ('abruption', 43, 'A client at 33 weeks with suspected placental abruption has a dry perineal pad, but the nurse is concerned that blood loss is being underestimated. Which assessment BEST reveals ongoing hidden bleeding?', '[{"id": "a", "text": "Hourly counts of perineal pads"}, {"id": "b", "text": "Serial vital signs and uterine size and tone"}, {"id": "c", "text": "A vaginal exam to check for clots"}, {"id": "d", "text": "Asking her to rate her pain level"}]'::jsonb, '["b"]', 'In concealed abruption, blood stays behind the placenta, so the uterus becomes tense and may enlarge while vital signs show shock. Pad counts miss hidden bleeding, and vaginal exams are never done.'),
  ('abruption', 44, 'A client at 35 weeks has polyhydramnios. She asks why the nurse wants to be called right away if her water breaks with a big gush. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"A big gush means the placenta is lying over the cervix.\""}, {"id": "b", "text": "\"A big gush causes high blood pressure that needs treatment.\""}, {"id": "c", "text": "\"A sudden loss of fluid means the baby must be born vaginally.\""}, {"id": "d", "text": "\"A sudden loss of fluid can make the placenta separate early.\""}]'::jsonb, '["d"]', 'Rapid uterine decompression, as with polyhydramnios, is a risk factor for abruption. A placenta lying over the cervix describes previa, not the effect of fluid loss.'),
  ('abruption', 45, 'A client at 34 weeks with preeclampsia developed a placental abruption. Two large-bore IVs are running, blood is crossmatched, and she is being prepared for surgery. Which additional action addresses the underlying cause?', '[{"id": "a", "text": "Treat her hypertension as ordered"}, {"id": "b", "text": "Screen her for recent cocaine use"}, {"id": "c", "text": "Ask about a prior abruption history"}, {"id": "d", "text": "Check for a history of PROM"}]'::jsonb, '["a"]', 'Trauma or hypertension should be identified and treated as the cause, and this client''s preeclampsia is the number one cause of abruption. The other histories are risk factors not suggested here.'),
  ('abruption', 46, 'A client at 32 weeks with a suspected abruption needs blood from the blood bank. The nurse is alone in the room, and the client''s pulse is rising. Which action is BEST?', '[{"id": "a", "text": "Go to the blood bank quickly herself"}, {"id": "b", "text": "Ask the client''s mother to stay with her"}, {"id": "c", "text": "Send another staff member for the blood"}, {"id": "d", "text": "Wait until the pulse is lower, then go"}]'::jsonb, '["c"]', 'The client must not be left unattended, so another staff member should retrieve the blood while the nurse stays. A family member cannot assess for deterioration.'),
  ('abruption', 47, 'The charge nurse observes care for a client at 31 weeks admitted with painful bleeding and a rigid uterus. Which action by the assigned nurse requires correction?', '[{"id": "a", "text": "Keeping two large-bore IV lines patent"}, {"id": "b", "text": "Giving oxygen at 8–10 L/min by face mask"}, {"id": "c", "text": "Checking the FHR by Doppler every 30 minutes"}, {"id": "d", "text": "Staying with the client between assessments"}]'::jsonb, '["c"]', 'Suspected abruption requires continuous FHR monitoring to detect fetal distress; intermittent Doppler checks are insufficient. The other actions are listed nursing priorities.'),
  ('abruption', 48, 'A client at 35 weeks arrives after being assaulted. She has severe abdominal pain, a rigid uterus, and light vaginal bleeding. Which provider order should the nurse question?', '[{"id": "a", "text": "Type and crossmatch blood now"}, {"id": "b", "text": "Start oxygen by face mask"}, {"id": "c", "text": "Begin continuous FHR monitoring"}, {"id": "d", "text": "Perform a sterile vaginal exam"}]'::jsonb, '["d"]', 'Trauma with severe pain and a rigid uterus suggests abruption, so a vaginal exam must never be done. The other orders are nursing priorities in abruption.'),
  ('abruption', 49, 'A client at 34 weeks was admitted with a mild partial abruption and stable findings. Which change MOST strongly suggests the separation has progressed to a complete abruption?', '[{"id": "a", "text": "Mild tenderness with stable vital signs"}, {"id": "b", "text": "Hypotension, tachycardia, and fetal distress"}, {"id": "c", "text": "A small amount of visible vaginal blood"}, {"id": "d", "text": "Reassuring fetal status on the monitor"}]'::jsonb, '["b"]', 'Complete separation causes maternal and fetal hemorrhage and shock, shown by hypotension, tachycardia, and fetal distress. Mild tenderness and small bleeding fit partial separation.'),
  ('abruption', 50, 'Four hours after an emergency cesarean for a severe abruption, the nurse reviews the client''s status. Which finding requires immediate follow-up?', '[{"id": "a", "text": "Tearfulness about the emergency birth"}, {"id": "b", "text": "A request to hold her newborn soon"}, {"id": "c", "text": "Thirst after being kept NPO all day"}, {"id": "d", "text": "New petechiae on the chest and arms"}]'::jsonb, '["d"]', 'Petechiae after severe abruption are a sign of DIC, a coagulation emergency. Emotional reactions and requests to see the newborn are not urgent physiologic problems.'),
  ('postpartum', 1, 'On postpartum day 5 after a vaginal birth, a client''s fundus is firm, midline, and 5 fingerbreadths below the umbilicus, and her lochia is pink-brown and watery without odor. Which interpretation by the nurse is correct?', '[{"id": "a", "text": "Involution and lochia are both progressing as expected"}, {"id": "b", "text": "The fundus should still be at the level of the umbilicus"}, {"id": "c", "text": "The pink-brown lochia suggests an infection of the uterus"}, {"id": "d", "text": "The watery lochia suggests a slow postpartum hemorrhage"}]'::jsonb, '["a"]', 'The fundus descends about 1 cm (one fingerbreadth) per day from the umbilicus, so 5 cm below on day 5 is expected, and pink/brown watery lochia on days 4–10 reflects normal healing. Infection is signaled by a foul smell, not by pink-brown color.'),
  ('postpartum', 2, 'On postpartum day 1, a client''s fundus is firm, 1 cm below the umbilicus, and deviated to the right of midline. She reports she has not voided since the catheter was removed several hours ago. What is the nurse''s first action?', '[{"id": "a", "text": "Massage the fundus until it returns to the midline"}, {"id": "b", "text": "Assist the client to empty her bladder, then reassess"}, {"id": "c", "text": "Administer oxytocin as prescribed for uterine atony"}, {"id": "d", "text": "Notify the provider of a postpartum hemorrhage"}]'::jsonb, '["b"]', 'A firm fundus pushed to one side points to a full bladder, which must be emptied first before the fundus is reassessed. Massage and oxytocin treat a boggy (atonic) uterus, which is not present here.'),
  ('postpartum', 3, 'One hour after a vaginal birth, a client has heavy bright red bleeding. The nurse palpates a soft, boggy fundus at the level of the umbilicus. Which action should the nurse take first?', '[{"id": "a", "text": "Administer oxytocin (Pitocin) as prescribed"}, {"id": "b", "text": "Increase the rate of the IV fluid infusion"}, {"id": "c", "text": "Perform fundal massage"}, {"id": "d", "text": "Prepare for a blood transfusion"}]'::jsonb, '["c"]', 'A boggy uterus signals uterine atony, and fundal massage is the first action for PPH. Oxytocin is added only if massage is ineffective, followed by IV fluids and transfusion.'),
  ('postpartum', 4, 'A client who gave birth vaginally 40 minutes ago continues to bleed heavily. After fundal massage, her fundus remains soft and boggy. Which intervention should the nurse implement next?', '[{"id": "a", "text": "Administer methylergonovine (Methergine) as prescribed"}, {"id": "b", "text": "Administer oxytocin (Pitocin) as prescribed"}, {"id": "c", "text": "Prepare the client for a blood transfusion"}, {"id": "d", "text": "Prepare the client for manual placental removal"}]'::jsonb, '["b"]', 'If fundal massage is ineffective, oxytocin is the next step for an atonic uterus. Methylergonovine is reserved for persistent PPH, and manual removal treats retained placenta rather than poor tone.'),
  ('postpartum', 5, 'A client whose pregnancy was complicated by preeclampsia continues to bleed from a boggy uterus despite fundal massage and oxytocin. The provider prescribes methylergonovine (Methergine). What is the nurse''s best action?', '[{"id": "a", "text": "Give the medication now, since the bleeding is persistent"}, {"id": "b", "text": "Hold the oxytocin infusion while giving the new medication"}, {"id": "c", "text": "Give the medication and recheck the fundus in one hour"}, {"id": "d", "text": "Question the prescription because of the preeclampsia history"}]'::jsonb, '["d"]', 'Methylergonovine is used for persistent PPH but should be avoided in preeclampsia because it causes hypertension, so the nurse clarifies the prescription. Persistent bleeding alone does not make it safe for this client.'),
  ('postpartum', 6, 'The nurse reviews estimated blood loss for four clients who gave birth today. Which client''s blood loss meets the definition of postpartum hemorrhage?', '[{"id": "a", "text": "A client after a vaginal birth with 450 mL of blood loss"}, {"id": "b", "text": "A client after a cesarean birth with 850 mL of blood loss"}, {"id": "c", "text": "A client after a vaginal birth with 600 mL of blood loss"}, {"id": "d", "text": "A client after a cesarean birth with 950 mL of blood loss"}]'::jsonb, '["c"]', 'PPH is blood loss over 500 mL after a vaginal birth or over 1000 mL after a cesarean, so only 600 mL after a vaginal birth qualifies. Losses of 850 and 950 mL after cesarean are below the 1000 mL cesarean threshold.'),
  ('postpartum', 7, 'After a rapid vaginal birth, a client has a steady trickle of bright red bleeding. Her fundus is firm and midline, the placenta was delivered intact, and her clotting studies are normal. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "Fundal massage followed by oxytocin"}, {"id": "b", "text": "Surgical repair of a laceration"}, {"id": "c", "text": "Manual removal of placental tissue"}, {"id": "d", "text": "Blood transfusion and treating the cause"}]'::jsonb, '["b"]', 'With a firm fundus (not tone), an intact placenta (not tissue), and normal clotting (not thrombin), the remaining T is trauma, such as a laceration, which needs surgical repair. Massage and oxytocin treat a boggy uterus.'),
  ('postpartum', 8, 'A client is bleeding heavily 30 minutes after a vaginal birth even though her fundus firms with massage. An ultrasound shows that part of the placenta remains in the uterus. Which intervention should the nurse prepare for?', '[{"id": "a", "text": "Manual removal or D&C"}, {"id": "b", "text": "Surgical repair of lacerations"}, {"id": "c", "text": "Blood transfusion and treating the cause"}, {"id": "d", "text": "Repeated fundal massage and IV fluids"}]'::jsonb, '["a"]', 'Retained placenta is the tissue cause of PPH and is treated with manual removal or D&C. Surgical repair addresses trauma, and massage with fluids addresses poor tone.'),
  ('postpartum', 9, 'A client continues to bleed after birth. Her fundus is firm and midline, the placenta was delivered intact, no lacerations are found, and laboratory results confirm a clotting disorder. Which treatment should the nurse anticipate?', '[{"id": "a", "text": "Fundal massage, then oxytocin, then IV fluids"}, {"id": "b", "text": "Manual removal of the placenta or a D&C"}, {"id": "c", "text": "Surgical repair of the birth canal"}, {"id": "d", "text": "Blood transfusion and treatment of the cause"}]'::jsonb, '["d"]', 'A clotting disorder such as DIC is the thrombin cause of PPH, treated with blood transfusion and treatment of the underlying cause. The firm fundus, intact placenta, and absent lacerations rule out tone, tissue, and trauma.'),
  ('postpartum', 10, 'A client calls on postpartum day 12 after a vaginal birth. She reports a small amount of yellowish-white discharge with no odor and asks whether she should come in. Which response by the nurse is best?', '[{"id": "a", "text": "This discharge is expected at this point in your recovery"}, {"id": "b", "text": "Come in today, because this color suggests a uterine infection"}, {"id": "c", "text": "Come in today, because the discharge should be pink by now"}, {"id": "d", "text": "This discharge means bleeding has restarted, so come in today"}]'::jsonb, '["a"]', 'From day 10 to 6 weeks, lochia alba is yellowish-white with no odor, so this is expected. A foul smell, not a yellowish-white color, signals endometritis.'),
  ('postpartum', 11, 'On postpartum day 7, a client''s lochia had become pink-brown and watery. She now calls to report a sudden return of bright red bleeding. Which response by the nurse is the priority?', '[{"id": "a", "text": "Reassure her that bleeding often varies during this phase"}, {"id": "b", "text": "Advise sitz baths to improve circulation and promote healing"}, {"id": "c", "text": "Tell her to report it only if the discharge develops an odor"}, {"id": "d", "text": "Treat it as a possible hemorrhage and have her seen promptly"}]'::jsonb, '["d"]', 'A sudden return to bright red bleeding after lochia has lightened is a possible hemorrhage and requires prompt evaluation. A foul odor signals infection, but waiting for odor would miss bleeding.'),
  ('postpartum', 12, 'On postpartum day 4, a client has a fever, reports tenderness when her uterus is palpated, and has foul-smelling lochia. Which treatment should the nurse anticipate first?', '[{"id": "a", "text": "Fundal massage followed by oxytocin"}, {"id": "b", "text": "IV antibiotics with monitoring for sepsis"}, {"id": "c", "text": "Oral antibiotics and warm compresses"}, {"id": "d", "text": "Sitz baths and witch hazel pads"}]'::jsonb, '["b"]', 'Fever, uterine tenderness, and foul-smelling lochia indicate endometritis, which is treated with IV antibiotics and monitoring for sepsis. Antibiotics with warm compresses are the regimen for mastitis.'),
  ('postpartum', 13, 'The nurse reviews home-visit notes for four postpartum clients who gave birth vaginally. Which finding requires follow-up?', '[{"id": "a", "text": "Day 5: pink-brown, watery lochia with no odor"}, {"id": "b", "text": "Day 12: yellowish-white lochia with no odor"}, {"id": "c", "text": "Day 8: pink-brown lochia with a foul smell"}, {"id": "d", "text": "Day 15: scant yellowish-white lochia, no odor"}]'::jsonb, '["c"]', 'A foul smell signals infection (endometritis) regardless of the lochia stage. Pink-brown watery lochia on days 4–10 and odorless yellowish-white lochia after day 10 are expected.'),
  ('postpartum', 14, 'A breastfeeding client on postpartum day 10 has a painful, hard, red area on her left breast and a fever. After teaching, which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I''ll take all of the antibiotics that were prescribed"}, {"id": "b", "text": "I''ll put a warm compress on the sore area of my breast"}, {"id": "c", "text": "I''ll keep feeding my baby on both sides as usual"}, {"id": "d", "text": "I''ll stop nursing on the left side until it heals"}]'::jsonb, '["d"]', 'A painful, hard, red breast with fever is mastitis, treated with antibiotics and warm compresses while breastfeeding continues. Stopping feeding on the affected side contradicts that teaching.'),
  ('postpartum', 15, 'On postpartum day 4, a breastfeeding client reports that both breasts feel full, firm, and uncomfortable. She has no fever and no reddened areas. Which instruction by the nurse is best?', '[{"id": "a", "text": "Feed frequently and use cold compresses between feeds"}, {"id": "b", "text": "Begin antibiotics and apply warm compresses to the breasts"}, {"id": "c", "text": "Wear a tight bra and avoid all nipple stimulation for now"}, {"id": "d", "text": "Stop breastfeeding and place cabbage leaves in the bra"}]'::jsonb, '["a"]', 'Bilateral fullness without fever is engorgement, which peaks at 3–5 days and is managed with frequent feeding and cold compresses between feeds. Antibiotics with warm compresses treat mastitis, and a tight bra with no nipple stimulation is for formula-feeding mothers.'),
  ('postpartum', 16, 'A formula-feeding client on postpartum day 4 reports painful, engorged breasts. After teaching, which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I''ll wear a snug, supportive bra day and night"}, {"id": "b", "text": "I''ll put cold compresses on my breasts for the pain"}, {"id": "c", "text": "I''ll pump a little milk to relieve the fullness"}, {"id": "d", "text": "I''ll place cabbage leaves inside my bra for relief"}]'::jsonb, '["c"]', 'Formula-feeding mothers should avoid nipple stimulation, so pumping is incorrect. A tight/supportive bra, cold compresses, and cabbage leaves are all recommended for their engorgement.'),
  ('postpartum', 17, 'On day 2 after a cesarean birth, a client reports pain in her left calf, which the nurse finds red, swollen, and warm. Which action by the assistive personnel requires the nurse to intervene?', '[{"id": "a", "text": "Reporting the client''s leg findings to the nurse"}, {"id": "b", "text": "Massaging the calf to relieve the client''s pain"}, {"id": "c", "text": "Helping the client back into bed for assessment"}, {"id": "d", "text": "Measuring and recording the client''s vital signs"}]'::jsonb, '["b"]', 'A red, swollen, painful, warm leg suggests DVT, which is treated with anticoagulants and must not be massaged. Reporting findings and obtaining vital signs are appropriate.'),
  ('postpartum', 18, 'The nurse receives report on four postpartum clients. Which client should the nurse assess first?', '[{"id": "a", "text": "Day 1: sudden chest pain, shortness of breath, and a rapid pulse"}, {"id": "b", "text": "Day 3: tearful with mood swings and mild sadness, caring for her baby"}, {"id": "c", "text": "Day 4: firm, full breasts on both sides with no fever or redness"}, {"id": "d", "text": "Day 6: small amount of pink-brown, watery lochia with no odor"}]'::jsonb, '["a"]', 'Sudden chest pain, shortness of breath, and tachycardia suggest pulmonary embolism, an emergency priority. The other clients show baby blues, engorgement, and normal lochia serosa.'),
  ('postpartum', 19, 'A postpartum client being treated with heparin for a red, swollen, painful leg suddenly becomes short of breath, reports chest pain, and has a rapid heart rate. What is the nurse''s priority action?', '[{"id": "a", "text": "Elevate the affected leg and reassess it in 15 minutes"}, {"id": "b", "text": "Gently massage the calf to improve the leg circulation"}, {"id": "c", "text": "Apply oxygen and initiate emergency care"}, {"id": "d", "text": "Reassure the client that anxiety is common postpartum"}]'::jsonb, '["c"]', 'Sudden chest pain, shortness of breath, and tachycardia in a client with DVT point to pulmonary embolism, which requires oxygen and emergency care as the priority. Massaging a leg with a clot is contraindicated.'),
  ('postpartum', 20, 'On postpartum day 3, a client cries easily, has mood swings, and says she feels a little sad, but she is feeding and caring for her newborn. Which nursing action is most appropriate?', '[{"id": "a", "text": "Arrange an urgent referral for antidepressant therapy"}, {"id": "b", "text": "Arrange emergency admission to a psychiatric unit"}, {"id": "c", "text": "Report the findings to the provider as depression"}, {"id": "d", "text": "Offer support and reassurance that this is expected"}]'::jsonb, '["d"]', 'Mood swings, crying, and mild sadness starting on day 2–3 in a client who is still caring for her baby are baby blues, which call for support and reassurance. Referral and antidepressants are for postpartum depression.'),
  ('postpartum', 21, 'At a 3-week postpartum visit, a client says she has felt intensely sad and worthless for over a week and cannot bring herself to care for her baby. She denies hearing voices. Which action is most appropriate?', '[{"id": "a", "text": "Refer her to a mental health provider for treatment"}, {"id": "b", "text": "Reassure her that these feelings resolve within 2 weeks"}, {"id": "c", "text": "Arrange emergency hospital admission right away"}, {"id": "d", "text": "Encourage more rest and recheck at the 6-week visit"}]'::jsonb, '["a"]', 'Intense sadness, worthlessness, and inability to care for the baby indicate postpartum depression, which requires referral to a mental health provider. Reassurance fits baby blues, and emergency admission is for psychosis with hallucinations or delusions.'),
  ('postpartum', 22, 'On postpartum day 5, a client tells the nurse she hears voices and believes her baby is not really hers. She appears confused and has not slept. Which action is the nurse''s priority?', '[{"id": "a", "text": "Refer her to an outpatient mental health provider"}, {"id": "b", "text": "Arrange emergency hospital admission"}, {"id": "c", "text": "Reassure her that mood changes are common this week"}, {"id": "d", "text": "Begin teaching about antidepressant medications"}]'::jsonb, '["b"]', 'Hallucinations, delusions, and confusion indicate postpartum psychosis, an emergency that may involve harm to the baby and requires hospital admission. Outpatient referral and antidepressants are the response to postpartum depression.'),
  ('postpartum', 23, 'The nurse is reviewing messages from four postpartum clients. Which client requires the most immediate intervention?', '[{"id": "a", "text": "Day 2: crying spells and mood swings, still caring for her baby"}, {"id": "b", "text": "Week 3: intense sadness and feeling worthless most of the day"}, {"id": "c", "text": "Day 4: hearing voices and confused beliefs about her baby"}, {"id": "d", "text": "Day 10: mild sadness that she says is improving each day"}]'::jsonb, '["c"]', 'Hallucinations and confusion signal postpartum psychosis, an emergency because the mother may harm the baby. Intense sadness and worthlessness need referral for depression but are not an emergency, and the other clients describe baby blues.'),
  ('postpartum', 24, 'Twelve hours after a vaginal birth with an episiotomy, a client''s perineum is swollen and sore. Which intervention is most appropriate at this time?', '[{"id": "a", "text": "Start sitz baths to increase perineal circulation"}, {"id": "b", "text": "Apply lanolin cream to the swollen perineal area"}, {"id": "c", "text": "Use the peri-bottle once daily during her shower"}, {"id": "d", "text": "Apply ice packs to the perineum"}]'::jsonb, '["d"]', 'Ice packs are used in the first 24 hours to reduce swelling and inflammation. Sitz baths begin after 24 hours, and the peri-bottle is used after each void or bowel movement.'),
  ('postpartum', 25, 'A client who gave birth vaginally 36 hours ago has been using perineal ice packs. Which statement by the client indicates correct understanding of her perineal care?', '[{"id": "a", "text": "Now that a day has passed, I can switch to sitz baths"}, {"id": "b", "text": "I should keep using the ice packs for the whole first week"}, {"id": "c", "text": "I''ll use the peri-bottle only in the morning and at night"}, {"id": "d", "text": "I can use tampons once the bleeding becomes much lighter"}]'::jsonb, '["a"]', 'Ice is used for the first 24 hours, then sitz baths are started to increase circulation and promote healing. The peri-bottle is used after each void or bowel movement, and tampons are avoided for 6 weeks.'),
  ('postpartum', 26, 'Eight hours after a vaginal birth, assistive personnel give a client instructions about perineal care. Which instruction requires the nurse to intervene?', '[{"id": "a", "text": "Spray warm water over your perineum after you urinate"}, {"id": "b", "text": "Use the peri-bottle once a day when you shower"}, {"id": "c", "text": "Use the peri-bottle again after each bowel movement"}, {"id": "d", "text": "Keep an ice pack on today to help reduce the swelling"}]'::jsonb, '["b"]', 'The peri-bottle is used after each void or bowel movement to cleanse the perineum and prevent infection, so once daily is inadequate. Ice packs are correct within the first 24 hours.'),
  ('postpartum', 27, 'On postpartum day 2, a client who had a vaginal birth reports painful, swollen hemorrhoids. Which intervention is most appropriate?', '[{"id": "a", "text": "Apply lanolin cream to the hemorrhoids after each void"}, {"id": "b", "text": "Place cabbage leaves against the perineum for swelling"}, {"id": "c", "text": "Apply witch hazel pads as needed"}, {"id": "d", "text": "Avoid the peri-bottle until the hemorrhoids have resolved"}]'::jsonb, '["c"]', 'Witch hazel pads are used as needed to relieve hemorrhoids and swelling. Lanolin is for sore nipples and cabbage leaves are for engorgement, and the peri-bottle should still be used after each void or bowel movement.'),
  ('postpartum', 28, 'At discharge 2 days after a vaginal birth, a client reviews her self-care plan with the nurse. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I''ll avoid intercourse for 6 weeks to reduce infection risk"}, {"id": "b", "text": "I''ll call if my discharge starts to have a foul smell"}, {"id": "c", "text": "I''ll report it if bright red bleeding suddenly comes back"}, {"id": "d", "text": "I can use tampons once my discharge turns yellowish-white"}]'::jsonb, '["d"]', 'Tampons are avoided for 6 weeks because of infection risk, and yellowish-white lochia appears from about day 10, well before 6 weeks. Reporting foul-smelling lochia or a sudden return of bright red bleeding is correct.'),
  ('postpartum', 29, 'A home-visit nurse assesses a breastfeeding mother and her newborn on postpartum day 5. Which finding requires follow-up?', '[{"id": "a", "text": "The baby nurses every 2 to 3 hours around the clock"}, {"id": "b", "text": "The baby has had 4 wet diapers in the past 24 hours"}, {"id": "c", "text": "The baby''s mouth opens wide and covers the areola"}, {"id": "d", "text": "The mother reports no nipple pain during the feedings"}]'::jsonb, '["b"]', 'By day 5, a breastfed newborn should have at least 6 wet diapers per day, so 4 is below the expected output. Feeding every 2–3 hours, a wide mouth over the areola, and painless feeding are all expected.'),
  ('postpartum', 30, 'While observing a breastfeeding session on postpartum day 2, the nurse notes that the newborn''s lips are closed around the nipple only and the mother winces with pain. Which action by the nurse is best?', '[{"id": "a", "text": "Help the baby re-latch with a wide mouth taking in the areola"}, {"id": "b", "text": "Apply lanolin cream and let the feeding continue in this position"}, {"id": "c", "text": "Apply a cold compress before feeding to help with milk let-down"}, {"id": "d", "text": "Stretch the feedings to every 4 hours so the nipples can rest"}]'::jsonb, '["a"]', 'A good latch shows a wide mouth, nipple plus areola in the mouth, and no pain, so this latch needs correction. Lanolin soothes sore nipples but does not fix the latch, and warm (not cold) compresses help let-down.'),
  ('postpartum', 31, 'On postpartum day 3, a breastfeeding client whose latch is correct reports sore nipples between feedings. She has no fever and no breast redness. Which recommendation by the nurse is best?', '[{"id": "a", "text": "Place cabbage leaves in the bra between feedings"}, {"id": "b", "text": "Wear a tight bra and avoid any nipple stimulation"}, {"id": "c", "text": "Apply lanolin cream to the nipples"}, {"id": "d", "text": "Take antibiotics and apply warm compresses"}]'::jsonb, '["c"]', 'Lanolin cream is recommended for sore nipples in breastfeeding mothers. Cabbage leaves and avoiding nipple stimulation are for formula-feeding engorgement, and antibiotics with warm compresses are for mastitis with fever.'),
  ('postpartum', 32, 'A breastfeeding client on postpartum day 3 says her milk seems slow to let down at the start of each feeding. Her breasts are not reddened and she has no fever. Which instruction is best?', '[{"id": "a", "text": "Apply a cold compress just before each feeding"}, {"id": "b", "text": "Wear a tight bra between feedings to stimulate flow"}, {"id": "c", "text": "Place cabbage leaves in the bra before each feeding"}, {"id": "d", "text": "Apply a warm compress just before each feeding"}]'::jsonb, '["d"]', 'A warm compress before feeding helps let-down. Cold compresses are used between feeds for engorgement, and a tight bra and cabbage leaves are measures for formula-feeding mothers.'),
  ('postpartum', 33, 'Thirty minutes after an uncomplicated vaginal birth, a client who plans to breastfeed says she would like to rest and start breastfeeding tomorrow. Which response by the nurse is best?', '[{"id": "a", "text": "Encourage breastfeeding now, within the first hour of life"}, {"id": "b", "text": "Agree, since breastfeeding should start after the first day"}, {"id": "c", "text": "Suggest waiting until engorgement begins on day 3 to 5"}, {"id": "d", "text": "Offer formula every 2 to 3 hours until she has rested"}]'::jsonb, '["a"]', 'Breastfed newborns should feed within the first hour of life. The 3–5 day window is when engorgement peaks, not when feeding should begin.'),
  ('postpartum', 34, 'The nurse reviews fundal assessments for four clients after vaginal births. Which finding is a deviation from expected uterine involution?', '[{"id": "a", "text": "Day 1: firm, midline, 1 cm below the umbilicus"}, {"id": "b", "text": "Day 8: firm, midline, 2 cm below the umbilicus"}, {"id": "c", "text": "Day 4: firm, midline, 4 cm below the umbilicus"}, {"id": "d", "text": "Day 11: fundus no longer palpable abdominally"}]'::jsonb, '["b"]', 'The fundus descends about 1 cm per day, so on day 8 it should be about 8 cm below the umbilicus; 2 cm below means it is not decreasing as expected. The day 1, day 4, and day 11 findings match the expected pattern.'),
  ('postpartum', 35, 'Forty-five minutes after a vaginal birth, a client asks to be left alone to sleep. Which nursing plan is the priority during this period?', '[{"id": "a", "text": "Teach about the expected return of menstruation"}, {"id": "b", "text": "Begin sitz baths to promote perineal healing"}, {"id": "c", "text": "Check vital signs and the fundus for hemorrhage"}, {"id": "d", "text": "Discuss emotional adjustment and support systems"}]'::jsonb, '["c"]', 'In the first 1–2 hours after birth, the focus is monitoring for hemorrhage with vital signs and fundal checks. Return of menstruation and emotional adjustment belong to late postpartum, and sitz baths start after 24 hours.'),
  ('postpartum', 36, 'The nurse receives report on four stable postpartum clients who gave birth vaginally. Based on timing alone, which client is at the highest risk for complications?', '[{"id": "a", "text": "A client on postpartum day 3"}, {"id": "b", "text": "A client on postpartum day 9"}, {"id": "c", "text": "A client 3 weeks after birth"}, {"id": "d", "text": "A client 6 hours after birth"}]'::jsonb, '["d"]', 'The highest risk for postpartum complications is during the first 24 hours, so the client 6 hours after birth is at greatest risk. The others are in the late postpartum period.'),
  ('postpartum', 37, 'The nurse is about to assess the fundus of a client on postpartum day 1 who last voided 5 hours ago. Which action should the nurse take first?', '[{"id": "a", "text": "Ask the client to empty her bladder"}, {"id": "b", "text": "Massage the fundus to make sure it is firm"}, {"id": "c", "text": "Check the lochia for its color and odor"}, {"id": "d", "text": "Assess her calves for redness and warmth"}]'::jsonb, '["a"]', 'The bladder should be emptied before assessment because a full bladder can displace the fundus and distort findings. Massage is for a boggy fundus, not a routine first step.'),
  ('postpartum', 38, 'While assessing a client''s episiotomy on postpartum day 1, the nurse documents redness, edema, ecchymosis, and discharge. Which component of the perineal assessment must still be evaluated?', '[{"id": "a", "text": "Elimination pattern"}, {"id": "b", "text": "Approximation of the wound edges"}, {"id": "c", "text": "Engorgement of the breasts"}, {"id": "d", "text": "Extremity warmth and swelling"}]'::jsonb, '["b"]', 'REEDA stands for redness, edema, ecchymosis, discharge, and approximation, so approximation remains. Breasts, bladder/bowels, and extremities are separate BUBBLE-EE components.'),
  ('postpartum', 39, 'A client on postpartum day 2 says she hopes to become pregnant again within the next year. Which supplement teaching by the nurse is most appropriate?', '[{"id": "a", "text": "Folic acid 400 mcg daily to prevent mastitis while nursing"}, {"id": "b", "text": "Folic acid 400 mcg daily to prevent another hemorrhage"}, {"id": "c", "text": "Folic acid 400 mcg daily to prevent neural tube defects"}, {"id": "d", "text": "Folic acid 40 mcg daily to prevent neural tube defects"}]'::jsonb, '["c"]', 'Folic acid 400 mcg/day prevents neural tube defects in the next pregnancy. The 40 mcg dose is incorrect, and folic acid is not taught for mastitis or hemorrhage prevention.'),
  ('postpartum', 40, 'During a home visit 3 weeks after birth, a client''s fundus is no longer palpable and her lochia is yellowish-white without odor. Which focus is most appropriate for this visit?', '[{"id": "a", "text": "Frequent fundal checks for hemorrhage"}, {"id": "b", "text": "Ice packs to reduce perineal swelling"}, {"id": "c", "text": "Fundal massage after each feeding"}, {"id": "d", "text": "Emotional adjustment and breastfeeding"}]'::jsonb, '["d"]', 'From 2 days to 6 weeks (late postpartum), the focus is emotional adjustment, breastfeeding, and return of menstruation, and her involution and lochia are normal. Frequent fundal checks belong to the first 1–2 hours, and ice packs to the first 24 hours.'),
  ('postpartum', 41, 'At an 8-week postpartum visit, a client whose bleeding has stopped says she still does not feel fully like herself physically or emotionally. She is caring for her baby and denies sadness. Which response by the nurse is most accurate?', '[{"id": "a", "text": "Recovery should be complete by 6 weeks, so you need a referral"}, {"id": "b", "text": "Full physical and emotional recovery can take up to 6 months"}, {"id": "c", "text": "This means your uterus has not yet returned to its normal size"}, {"id": "d", "text": "This is the baby blues, which usually starts around this time"}]'::jsonb, '["b"]', 'The extended postpartum period, 6 weeks to 6 months, is when full physical and emotional recovery occurs. Baby blues begin on day 2–3, and the fundus is no longer felt by day 10.'),
  ('postpartum', 42, 'A client has heavy bleeding and a soft, boggy uterus after a vaginal birth. If each step fails to control the bleeding, which sequence of interventions should the nurse anticipate?', '[{"id": "a", "text": "Oxytocin → fundal massage → blood transfusion → IV fluids"}, {"id": "b", "text": "IV fluids → fundal massage → oxytocin → blood transfusion"}, {"id": "c", "text": "Fundal massage → oxytocin → IV fluids → blood transfusion"}, {"id": "d", "text": "Fundal massage → blood transfusion → oxytocin → IV fluids"}]'::jsonb, '["c"]', 'For PPH from a boggy uterus, the order is fundal massage, then oxytocin, then IV fluids, then blood transfusion. Starting with oxytocin or fluids skips the first action of massage.'),
  ('postpartum', 43, 'The nurse performs fundal massage for a client with heavy bleeding and a boggy uterus 1 hour after birth. Which finding best indicates that the intervention was effective?', '[{"id": "a", "text": "The fundus is soft and 2 cm above the umbilicus"}, {"id": "b", "text": "The fundus is firm but displaced to the right side"}, {"id": "c", "text": "The lochia suddenly changes back to bright red"}, {"id": "d", "text": "The fundus is firm and midline with less bleeding"}]'::jsonb, '["d"]', 'A firm, midline fundus with decreased bleeding shows the atony has resolved. A firm but displaced fundus suggests a full bladder that still needs emptying, and a soft fundus means atony persists.'),
  ('postpartum', 44, 'The nurse is returning phone calls from four postpartum clients who gave birth vaginally. Which client should the nurse call back first?', '[{"id": "a", "text": "Day 6: lochia had lightened but is now bright red again"}, {"id": "b", "text": "Day 12: yellowish-white lochia without any odor"}, {"id": "c", "text": "Day 4: both breasts full and firm with no fever"}, {"id": "d", "text": "Day 3: crying and moody but caring for the baby"}]'::jsonb, '["a"]', 'A sudden return to bright red bleeding after lochia has lightened is a possible hemorrhage and takes priority. The other calls describe normal lochia alba, engorgement, and baby blues.'),
  ('postpartum', 45, 'A normotensive client has heavy bleeding from a boggy uterus, and fundal massage has not firmed it. The provider has prescribed both oxytocin and methylergonovine (Methergine) as needed. Which plan should the nurse expect?', '[{"id": "a", "text": "Methylergonovine first, then oxytocin if bleeding persists"}, {"id": "b", "text": "Oxytocin first, then methylergonovine if bleeding persists"}, {"id": "c", "text": "Both medications given together as the first medication step"}, {"id": "d", "text": "Neither medication until a blood transfusion is completed"}]'::jsonb, '["b"]', 'If massage is ineffective, oxytocin is given next, and methylergonovine is used for persistent PPH. Transfusion comes later in the PPH sequence, not before uterotonic medication.'),
  ('postpartum', 46, 'Two hours after a cesarean birth, a client''s total blood loss is calculated as 1,050 mL. Another client who had a vaginal birth has lost 480 mL. Which conclusion by the nurse is correct?', '[{"id": "a", "text": "Both clients meet the definition of postpartum hemorrhage"}, {"id": "b", "text": "Only the client with the vaginal birth meets the definition"}, {"id": "c", "text": "Only the client with the cesarean birth meets the definition"}, {"id": "d", "text": "Neither client meets the definition of postpartum hemorrhage"}]'::jsonb, '["c"]', 'PPH is more than 1000 mL after a cesarean, so 1,050 mL qualifies, but a vaginal loss must exceed 500 mL, so 480 mL does not. Applying the vaginal cut-off to the cesarean client would be wrong.'),
  ('postpartum', 47, 'On postpartum day 9, a breastfeeding client has a fever and a painful, hard, red area on one breast. Her lochia is pink-brown and watery without odor, and her uterus is not tender. Which treatment should the nurse anticipate?', '[{"id": "a", "text": "IV antibiotics and monitoring for sepsis"}, {"id": "b", "text": "Frequent feeding and cold compresses between feeds"}, {"id": "c", "text": "A tight bra, cabbage leaves, and no nipple stimulation"}, {"id": "d", "text": "Antibiotics, warm compresses, and continued breastfeeding"}]'::jsonb, '["d"]', 'A painful, hard, red breast with fever is mastitis, treated with antibiotics, warm compresses, and continued breastfeeding. Odorless lochia and a nontender uterus argue against endometritis, and cold compresses with frequent feeding treat engorgement without fever.'),
  ('postpartum', 48, 'During a postpartum head-to-toe assessment of four clients, which finding should the nurse report promptly?', '[{"id": "a", "text": "Day 2: one calf is warm, red, swollen, and painful"}, {"id": "b", "text": "Day 3: firm, midline fundus 3 cm below the umbilicus"}, {"id": "c", "text": "Day 14: yellowish-white lochia with no odor"}, {"id": "d", "text": "Day 4: both breasts full without fever or redness"}]'::jsonb, '["a"]', 'Pain, swelling, redness, and warmth in a leg are DVT signs, which require anticoagulant treatment and no massage. The fundus, lochia, and bilateral breast fullness described are expected for their days.'),
  ('postpartum', 49, 'A client on postpartum day 3 with crying spells and mood swings is still caring for her newborn. After teaching about this condition, which statement by the client indicates correct understanding?', '[{"id": "a", "text": "If this lasts past 2 months, it is still the baby blues"}, {"id": "b", "text": "If this lasts beyond 2 weeks, I should let my provider know"}, {"id": "c", "text": "I will need antidepressants to get through these feelings"}, {"id": "d", "text": "Hearing voices can be a normal part of the baby blues"}]'::jsonb, '["b"]', 'Baby blues begin on day 2–3 and resolve within 2 weeks, so symptoms lasting longer should be reported. Antidepressants are for postpartum depression, and hearing voices indicates psychosis.'),
  ('postpartum', 50, 'A new nurse is teaching a formula-feeding client on postpartum day 3 whose breasts are becoming engorged. Which instruction by the new nurse requires correction?', '[{"id": "a", "text": "Wear a tight, supportive bra"}, {"id": "b", "text": "Use cold compresses to relieve the engorgement"}, {"id": "c", "text": "Place cabbage leaves in your bra for relief"}, {"id": "d", "text": "Apply warm compresses to help your milk let down"}]'::jsonb, '["d"]', 'Warm compresses before feeding to help let-down are a breastfeeding measure; formula-feeding mothers use cold compresses for engorgement and avoid nipple stimulation. A tight bra and cabbage leaves are correct for formula-feeding engorgement.')
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale)
  JOIN _mat_seed_map m USING (source_key)
 CROSS JOIN _mat_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _mat_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Maternal seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
